P.entries["subzone:loading-room"] = {n="Loading Room",s="Loading Room是诺莫瑞根庞大机械综合设施内的一间工业装载室。在当今时代，这个地下的中转区位于受损的废弃首都深处，极其靠近像尖端机器人这样的失控构造体。",h="Loading Room是诺莫瑞根庞大机械综合设施内的一间工业装载室。在当今时代，这个地下的中转区位于受损的废弃首都深处，极其靠近像尖端机器人这样的失控构造体。",kw={"丹莫罗","诺莫瑞根","装载室","尖端机器人","工匠镇","地铁站"},ang={["profession:Engineering"]="失控的构造体尖端机器人以及留在Loading Room里的机械组件，为工程师们提供了一个严酷的教训：当自动化防御系统在缺乏维护的情况下发生故障时，会造成什么样的后果。",["race:Gnome"]="对于诺莫瑞根的收复者来说，Loading Room痛苦地提醒着人们，在石腭怪入侵和有毒灾难期间，日常城市基础设施是如何被暴力遗弃的。"},sec={{t="围城中的工业仓库",b="在诺莫瑞根陷落之前，Loading Room曾是连接这座工匠首都地下交通网络的繁忙中转点和货物装卸区。如今，和这座废墟城市的其他部分一样，这里已经陷入了混乱。放射性尘埃、入侵的石腭怪以及故障的机械使得该区域变得极度危险。失控的机械构造体尖端机器人守卫着附近区域，对任何试图稳固防线的诺莫瑞根幸存者或大胆的联盟收复者构成了严重的威胁。"}},faq={{q="装载间有什么用途？",a="历史上，它是连接诺莫瑞根内部交通和列车设施的工业装载区和货物中转点。自城市陷落以来，它已沦为另一个被各种危险所占据的失落区域。",al={"装载室用途","什么是装载室","装载室过去是什么"}},{q="在装载间里会遇到什么威胁？",a="装载间是失控机械防御构造体尖端机器人的所在地，此外还有城市深处残留的放射性污染和不稳定的机械。",al={"谁在装载室里","装载室首领","尖端机器人位置"}},{q="装载间可以安全探索吗？",a="不可以。整个区域都是诺莫瑞根废墟内的争夺地。任何冒险进入这部分设施的联盟突击小队都必须面对敌对的构造体和有毒的环境。",al={"这里安全吗","联盟可以去这里吗"}}},fx={["3f72b894"]={q="装载室是什么地方？",a="装载室是诺莫瑞根这座已然陷落的科技奇城内的一间工业舱室。它位于城市复杂基础设施的深处，在城市被穴居人攻占并遭到辐射污染之前，曾承担机械运输与货物装卸的职能。如今，穿行于这座遍布辐射的地下都市、应对重重险境的人，途中便会经过这里。",al={"装载室是什么","诺莫瑞根装载室","关于装载室"}},a3501e82={q="装载室发生了什么？",a="与诺莫瑞根的其他区域一样，装载室在穴居人入侵及随后灾难性的放射性尘埃释放中陷落。大工匠格尔宾·梅卡托克和他的顾问们释放放射性气体，试图阻止这些地下野兽，然而有毒的辐射却失控蔓延，使守军发生变异，也让这间舱室等曾经繁忙的工业区域遭到遗弃，或被尖端机器人之类失控的构造体占据。",al={"装载室历史","装载室发生了什么","装载室为何陷落"}},["6c9ce16b"]={q="装卸室为何沦为废墟？",a="灾难性的放射性气体释放未能消灭入侵的穴居人，这间舱室便与下层城区的其他区域一同遭到遗弃。辐射未能拯救城市，反而毒害了居民，将幸存的侏儒变成麻风侏儒，还让自动防御系统和机械维护装置在无人监管的情况下陷入疯狂。",al={"装载室为何沦为废墟","装载室遭到遗弃","为何被毁"}}},fp="12,180,28.465.0,34.152.0,46.161.0,36.160.0"}
P.entries["subzone:long-wash"] = {n="长桥码头",s="长桥码头是黑海岸一片凄凉且风大的海滩，从奥伯丁南侧一直延伸至亚米萨兰废墟。这片海岸阴郁沉闷，遍布海洋生物的残骸和漂浮物，最近由于敌对鱼人的势力增长，此处变得愈发危险。",h="长桥码头是黑海岸一片凄凉且风大的海滩，从奥伯丁南侧一直延伸至亚米萨兰废墟。这片海岸阴郁沉闷，遍布海洋生物的残骸和漂浮物，最近由于敌对鱼人的势力增长，此处变得愈发危险。",kw={"亚米萨兰","奥伯丁","黑海岸","长桥码头","鱼人","潮汐爬行者","迷雾之海"},ang={["race:NightElf"]="对于奥伯丁的卡多雷来说，长桥码头附近不断逼近的鱼人是另一种令人不安的不平衡迹象，它们正蔓延到这个主要港口的家门口。"},sec={{t="阴郁的海岸线",b="尽管名字里带有“长”字，长桥码头其实是黑海岸最短的一段独立海岸线。它终年笼罩在黑海岸阴沉的天空下，潮湿的沙滩上散落着漂浮物、搁浅的浮木，以及被迷雾之海冲上岸的海洋生物残骸。虽然当地的螃蟹在浪花中觅食，但从奥伯丁南下的旅者必须小心谨慎：鱼人部落已经在水边建立了营地，会猛烈攻击任何侵入它们领地的人。"}},faq={{q="长桥码头位于哪里？",a="长桥码头沿着黑海岸的海岸线延伸，位于奥伯丁的正南方，一直延伸到古老的亚米萨兰废墟西侧附近。",al={"长桥码头位置","长桥码头在哪里","如何找到长桥码头"}},{q="为什么叫长桥码头？",a="“冲刷区”（冲刷区）是一个古老的词汇，指的是海岸边被海浪冲刷和覆盖的部分。讽刺的是，尽管它被命名为长桥码头，它实际上是黑海岸最短的一段独立海滩。",al={"为什么叫长桥码头","长桥码头含义","冲刷区是什么意思"}},{q="在长桥码头能遇到什么威胁？",a="长桥码头的主要威胁来自于聚集在海岸线上的大量好战鱼人部族，此外还有极具领地意识的潮汐爬行者和其他沿海野生动物。",al={"长桥码头的危险","长桥码头的怪物","长桥码头有什么生物"}},{q="为什么沙滩上有这么多死去的生物？",a="迷雾之海汹涌的浪涛，加上正在侵蚀黑海岸沿海水域的腐蚀力量，经常将碎片、船骸和垂死的海洋生物冲刷到潮湿的沙滩上。",al={"长桥码头的死动物","黑海岸沙滩搁浅生物","海岸漂浮物"}}},fp="9,115,18.409.0,31.110.0,31.121.0,46.109.0,50.172.0"}
P.entries["subzone:longshore"] = {n="长滩",s="长滩是绵延整个西部荒野西侧边缘的广阔沙滩海岸线。尽管它辽阔而风景优美，但由于聚集了大量好斗的鱼人，且海岸外散布着大量沉船残骸，这里向来以危险著称。",h="长滩是绵延整个西部荒野西侧边缘的广阔沙滩海岸线。尽管它辽阔而风景优美，但由于聚集了大量好斗的鱼人，且海岸外散布着大量沉船残骸，这里向来以危险著称。",kw={"水栖形态","达芙妮·斯迪威尔","长滩","鱼人","老瞎眼","沉船","西部荒野","西部荒野灯塔"},ang={["class:Druid"]="联盟德鲁伊必须勇闯长滩西北部的深水区，找到隐藏在沉船附近的保险箱，以拼凑出他们获取水栖形态所需的坠饰。",["class:Paladin"]="追随暴风城达索瑞恩·拉尔指引的圣骑士会被派往南部的长滩，前往达芙妮·斯迪威尔的宅地，通过保护这位无辜的农夫免受迪菲亚强盗的侵害来证明他们的英勇。"},sec={{t="危险的海岸线",b="长滩贯穿了西部荒野的整个西海岸，是东部王国最宽阔、连续的沙滩之一。然而，它却很难让旅行者感到安宁。海岸鱼人在浪潮中横行霸道，其中以老瞎眼这样的恶名昭彰的恐怖生物为首，而沉船的残骸——包括被毁的精灵驱逐舰——则散落在浅滩上。在南部区域附近，像达芙妮·斯迪威尔这样孤立的定居者在迪菲亚强盗的劫掠下苦苦挣扎，而在水域对岸，西部荒野灯塔清晰可见。"}},faq={{q="为什么长滩如此危险？",a="海岸线上到处都是好斗的鱼人部落，它们在沙滩上横行无忌，伏击任何靠近浪潮的人。除了鱼人之外，沙滩南端还深受劫掠沿海宅地的迪菲亚强盗的困扰。",al={"为什么有这么多鱼人","长滩的危险","长滩安全吗"}},{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔是一位独自一人在长滩西南部经营着孤立农场的定居者。她脆弱的处境使她成为了迪菲亚潜行者频繁劫掠的目标，这也促使白银之手骑士团派遣圣骑士新兵去保护她。",al={"达芙妮·斯迪威尔","斯迪威尔农场","海滩上的女人"}},{q="海岸外的那些沉船是什么？",a="长滩外水域沉没着许多船只残骸，从商船到过去海战中遗失的精灵驱逐舰应有尽有。这些水下遗迹吸引了拾荒者、鱼人和寻求海浪之下失落遗物的冒险者。",al={"西部荒野的精灵驱逐舰","长滩沉船","沉船"}},{q="为什么德鲁伊会来到长滩？",a="联盟的德鲁伊会进行一项被称为海狮试炼的仪式，以掌握他们的水栖形态。这项试炼的一部分要求前往长滩西北部的一处近海沉船附近，寻找一个沉没的箱子，以取回水兽耐力坠饰的另一半。",al={"长滩德鲁伊任务","西部荒野的奇怪保险箱","水兽耐力坠饰"}}},fx={f7eb1386={q="长滩是什么地方？",a="长滩是一片绵延广阔的海岸，构成了西部荒野的西部与南部边缘。连片的沙地与岩石浅滩，使它成为艾泽拉斯最长的连续海滩之一。尽管自然风光优美，这里大部分地方仍然荒僻而危险，一侧是无尽之海，另一侧则是西部荒野未经开垦的平原。",al={"长滩是什么","西部荒野长滩","长滩海滩"}},ae612e51={q="长滩为何得名？",a="长滩的名字正是源于它惊人的长度。海滩沿着西部荒野整个西部与西南部边缘连绵延伸，形成了一条庞大的海岸线，堪称艾泽拉斯最长的连续海岸之一。",al={"为何叫长滩","长滩名称由来","长滩含义"}}},fp="9,80,23.381.0,34.148.0,23.175.0,44.188.0,34.206.0"}
P.entries["subzone:lordamere-internment-camp"] = {n="洛丹米尔收容所",s="洛丹米尔收容所是第二次战争时期的一处拘留设施，坐落在俯瞰达拉然的高地上。该营地最初用于关押昏睡的兽人，现在则被达拉然的幸存法师和卫兵，以及一群背叛的被遗忘者所占据。",h="洛丹米尔收容所是第二次战争时期的一处拘留设施，坐落在俯瞰达拉然的高地上。该营地最初用于关押昏睡的兽人，现在则被达拉然的幸存法师和卫兵，以及一群背叛的被遗忘者所占据。",kw={"奥特兰克","贝拉莫尔","血石","达拉然","收容","基根·达克玛","洛丹米尔","兽人"},ang={["race:Orc"]="对于兽人来说，造访这座营地会让他们痛苦地想起第二次战争后的那段岁月，那时数以千计的族人在囚禁中日渐衰弱，直到萨尔集结了他们的人民。",["race:Undead"]="躲藏在洛丹米尔的叛逃者是对黑暗女王的直接背叛。追捕基根·达克玛并收回血石，对于防止被遗忘者的秘密落入人类之手至关重要。"},sec={{t="从监狱到研究前哨",b="第二次战争结束后，联盟在北方王国各地建立了收容所，以关押战败的兽人部落。洛丹米尔是一个独特的收容所，它是唯一设在奥特兰克山脉内的营地，归达拉然管辖。随着兽人早已被解放或逃离，如今该营地在典狱官贝拉莫尔的领导下，作为达拉然残部研究危险魔法遗物的前哨站运作。"},{t="被遗忘者叛逃者",b="该营地已卷入了洛丹伦亡灵的政治漩涡之中。四名被遗忘者变节者——基根·达克玛和他的同伙——从幽暗城窃取了强大的血石神器并逃到这里，将其交给典狱官贝拉莫尔，以换取在达拉然防线后的庇护。法师们欣然接受了这些用于奥术研究的神器，而塔伦米尔的执行官们则派遣忠诚的部落特工去追捕这些叛逃者，并在达拉然解锁其力量之前收回被窃的血石。"}},faq={{q="这个营地最初是用来做什么的？",a="它由联盟在第二次战争后建立，旨在关押那些因失去恶魔之血的嗜血欲望而陷入昏睡的被俘兽人。由于该营地靠近法师之城，达拉然负责驻守瞭望塔并对营地实施监管。",al={"收容所历史","这里为什么会有营地","这里是什么地方"}},{q="现在是谁在控制这个营地？",a="典狱官贝拉莫尔以及一支达拉然卫兵和法师小队控制着该营地。尽管达拉然本身已遭受重创，但这些幸存者仍在设防的山顶上继续他们的研究。",al={"谁住在这里","谁在管理营地","典狱官贝拉莫尔是谁"}},{q="为什么营地里会有被遗忘者亡灵？",a="他们是由基根·达克玛领导的幽暗城逃兵。在背叛了希尔瓦娜斯女王并窃取了神圣的血石神器后，他们将这些遗物交给典狱官贝拉莫尔，以换取达拉然的保护，从而躲避被遗忘者的报复。",al={"这里的亡灵","基根·达克玛","被遗忘者叛逃者"}}},fp="25,128,31.407.0,18.391.1,40.222.0,32.179.0,46.206.0"}
P.entries["subzone:lordamere-lake"] = {n="洛丹米尔湖",s="洛丹米尔湖是东部王国最大的淡水水域之一，其边缘由提瑞斯法林地、银松森林和奥特兰克山脉环绕。这里曾是北部人类文明繁华的水上中心，如今，其冰冷的水域和岛屿上却盘踞着天灾军团的死灵法师、野蛮的鱼人，以及蔓延的亡灵阴影。",h="洛丹米尔湖是东部王国最大的淡水水域之一，其边缘由提瑞斯法林地、银松森林和奥特兰克山脉环绕。这里曾是北部人类文明繁华的水上中心，如今，其冰冷的水域和岛屿上却盘踞着天灾军团的死灵法师、野蛮的鱼人，以及蔓延的亡灵阴影。",kw={"奥特兰克山脉","黎明岛","芬里斯岛","洛丹米尔湖","银松森林","图勒·鸦爪","提瑞斯法林地","邪鳍鱼人"},ang={["race:Human"]="洛丹米尔那宁静而多雾的水域，让人沉重地回想起北方人类王国曾经辉煌的往事，那时，人们曾自由地在湖岸间进行贸易。",["race:Undead"]="对于被遗忘者而言，洛丹米尔湖既是保护提瑞斯法的防御护城河，也是一处活跃的前线，必须清除芬里斯岛上残留的天灾军团。"},sec={{t="陨落王国的中心",b="在洛丹伦联盟的黄金时代，洛丹米尔湖处于人类权力的交汇处。洛丹伦王城守卫着它的北岸，魔法城邦达拉然在它的南端升起，而奥特兰克王国则坐落在它东部崎岖的山脊旁。商船和渔船曾毫无畏惧地穿梭于其广阔且雾气缭绕的水面上。第三次战争的浩劫过后，这座湖泊从商业枢纽变成了一道天然屏障，将由被遗忘者控制的提瑞斯法和银松森林地区与奥特兰克险峻的高地分离开来。"},{t="争夺之地",b="如今，航行在洛丹米尔的漆黑水域上危机四伏。湖中心坐落着芬里斯岛，天灾军团的死灵法师图勒·鸦爪和他的腐皮豺狼人在此负隅顽抗，抵御被遗忘者的进攻。再往东是黎明岛，那里已被好战的邪鳍鱼人完全占据。从达拉然周围的废墟到幽暗城的岸边，这座湖泊不再是一条平静的航道，而是一片被残余怪物和亡灵大军争夺的没顶前线。"}},faq={{q="历史上哪些王国曾与洛丹米尔湖接壤？",a="在洛丹伦联盟鼎盛时期，洛丹米尔湖与三个主要的人类王国接壤：北面和西面的洛丹伦王国、南面的达拉然，以及东面山脊旁的奥特兰克。",al={"洛丹米尔湖的居民","洛丹米尔湖历史","洛丹米尔周边的王国"}},{q="谁控制着湖中心的芬里斯岛？",a="芬里斯岛目前由天灾军团死灵法师图勒·鸦爪指挥的腐皮豺狼人控制，但他们正面临着来自被遗忘者的持续猛攻。",al={"芬里斯岛上的势力","洛丹米尔湖芬里斯岛","芬里斯岛统治者"}},{q="黎明岛是什么？",a="黎明岛是位于洛丹米尔湖东部、芬里斯岛以东的一群小岛。它们已被充满敌意的邪鳍鱼人占领并占据。",al={"黎明岛位置","洛丹米尔湖中的岛屿","黎明岛的怪物"}},{q="这座湖泊是如何得名的？",a="这座湖泊的名字呼应了周围的洛丹伦王国，因为其王城就在附近；关于它命名的详情，记录中并没有提及更多信息。",al={"洛丹米尔命名由来","为什么叫洛丹米尔"}}},fp="14,248,28.450.0,19.400.1,51.186.0,51.135.1,27.164.0,30.160.0"}
P.entries["subzone:lost-fleet"] = {n="失落的舰队",s="失落的舰队由库尔提拉斯第三舰队的残骸组成，它们沉没在湿地北部海岸的巴拉丁海湾旁。在第二次战争期间，被龙喉氏族奴役的红龙摧毁了这支舰队，现在这些沉船残骸受到了不安的、被诅咒的不死水手的骚扰，他们被一种神秘的诅咒束缚在残骸上。",h="失落的舰队由库尔提拉斯第三舰队的残骸组成，它们沉没在湿地北部海岸的巴拉丁海湾旁。在第二次战争期间，被龙喉氏族奴役的红龙摧毁了这支舰队，现在这些沉船残骸受到了不安的、被诅咒的不死水手的骚扰，他们被一种神秘的诅咒束缚在残骸上...",kw={"巴拉丁海湾","蓝腮沼泽","被诅咒的舰队","帕雷斯之眼","菲兹莫斯","哈林多尔","无畏号","失落的舰队","斯涅利格","第三舰队","浪花女神号","湿地"},ang={["faction:Alliance"]="这些残骸沉重地提醒着人们，库尔提拉斯和联盟在第二次战争中付出了惨痛的代价，我们应当尊重阵亡者，并终结他们被诅咒的折磨。",["profession:Blacksmithing"]="联盟的铁匠经常听说关于沉没舰队的传说，因为同一分队的另一艘船只飞翔鱼鹰号在沉没时携带着稀有的Lightforge iron。"},sec={{t="第二次战争中的悲惨结局",b="在第二次战争期间的最后一次航行中，库尔提拉斯第三舰队遭到了被龙喉氏族部族奴役的红龙从空中的伏击。龙焰瞬间吞没了整个舰队，像浪花女神号和Intrepid这样引以为傲的船只撞向了蓝腮沼泽北部的浅滩和礁石。几乎所有船员都淹死或烧死，只有大副菲兹莫斯成为了这场灾难中唯一的幸存者。"},{t="帕雷斯之咒",b="水葬并不是第三舰队水手们的终点。在Intrepid沉没的货舱深处，藏着一件被称为被诅咒的帕雷斯之眼的禁忌神器，它是该船贪婪的指挥官哈林多尔船长私藏的。这件黑暗圣物腐蚀了溺亡的船员，将他们的灵魂束缚在破碎的木材上，使他们变成了狂乱、被诅咒的不死生物。只有大副斯涅利格的鬼魂还保留着一丝理智，在沼泽海岸徘徊，而他曾经的船员们则会猛烈攻击任何靠近残骸的入侵者。"}},faq={{q="什么是失落的舰队？",a="失落的舰队是来自第三舰队的几艘库尔提拉斯战舰的残骸，它们静静地躺在巴拉丁海湾湿地的北部海岸外。它们在第二次战争中被摧毁，现在被它们的不死船员所缠绕。",al={"失落的舰队","这里是什么地方","湿地沉船","第三舰队"}},{q="这些船只是如何被摧毁的？",a="在第二次战争期间，这支舰队遭到了兽人龙喉氏族部族所控制的被奴役的红龙的伏击和焚烧。猛烈的龙焰将这些船只化为燃烧的残骸，沉没在海岸边。",al={"谁击沉了这些船","它们是如何沉没的","是什么摧毁了舰队"}},{q="为什么这里的水手是不死生物？",a="他们的灵魂因为一种诅咒而被束缚在残骸上。大副菲兹莫斯正在寻求帮助，调查他们为何无法安息。",al={"为什么它们是幽灵","不死水手","帕雷斯之咒"}},{q="有人在舰队的毁灭中幸存下来吗？",a="来自浪花女神号的大副菲兹莫斯是这场灾难中唯一已知的幸存者。他设法到达了安全地带，目前居住在米奈希尔港。",al={"有幸存者吗","有人活下来吗","菲兹莫斯"}}},fp="10,220,30.344.0,19.495.1,23.207.0,31.182.0,32.116.0,48.146.0"}
P.entries["subzone:lost-point"] = {n="废弃哨塔",s="废弃哨塔是一座位于尘泥沼泽西部的破旧木制瞭望塔，最初由塞拉摩的部队建造，作为前哨侦察站。此后它因年久失修而脱离了吉安娜·普罗德摩尔的守卫控制，现在成了流氓逃兵的藏身处。",h="废弃哨塔是一座位于尘泥沼泽西部的破旧木制瞭望塔，最初由塞拉摩的部队建造，作为前哨侦察站。此后它因年久失修而脱离了吉安娜·普罗德摩尔的守卫控制，现在成了流氓逃兵的藏身处。",kw={"巴鲁斯·加科因","尘泥沼泽","废弃哨塔","侦察塔","塞拉摩逃兵"},ang={["faction:Alliance"]="对于联盟忠诚者来说，废弃哨塔是塞拉摩队伍中纪律涣散的苦涩象征，也是隐藏着军事叛国阴暗秘密的叛徒窝点。"},sec={{t="一个被遗弃的哨所",b="废弃哨塔由塞拉摩的远征军建立，旨在监视从贫瘠之地出现的交通和威胁，但它早已失去了最初的军事作用。在沼泽无情的潮湿环境下，哨所已经腐朽，木材开始腐烂，防御设施也被正规军遗弃。现在的塔楼及其周边地区没有驻守哨兵，而是被一群脱离了塞拉摩服役的人类逃兵所占据，他们在远离城市指挥官纪律的偏远荒野中寻求庇护。"},{t="逃兵巢穴",b="盘踞在废弃哨塔的逃兵听命于巴鲁斯·加科因，这是一名心怀不满的前士兵，他将这些流氓聚集在一起。他们的存在不仅仅是军事违抗命令那么简单。加科因和他的同伙掌握着有关塞拉摩队伍中叛徒的重要证词，包括列兵亨德尔参与了一场波及联盟高层的重大阴谋。"}},faq={{q="什么是废弃哨塔？",a="废弃哨塔是塞拉摩的人类在尘泥沼泽西部建造的一座破旧瞭望塔。虽然它最初旨在作为前哨侦察塔，但已被军队遗弃，并被逃兵接管。",al={"废弃哨塔概览","这座塔是什么","关于废弃哨塔"}},{q="现在谁住在废弃哨塔？",a="塔楼和周围的营地目前由塞拉摩的逃兵居住。这些叛变的人类士兵放弃了对塞拉摩的誓言，并在巴鲁斯·加科因的领导下行动。",al={"废弃哨塔里有什么人","废弃哨塔的敌人","废弃哨塔的怪物"}},{q="巴鲁斯·加科因是谁？",a="巴鲁斯·加科因是躲藏在废弃哨塔的塞拉摩逃兵的首领。尽管他有犯罪前科，但他掌握着有关塞拉摩内部令人不安的问题的关键情报。",al={"巴鲁斯·加科因","逃兵领袖","谁领导废弃哨塔"}},{q="塞拉摩为什么要废弃这座塔？",a="尘泥沼泽环境恶劣，补给困难。随着驻军士气低落，纪律松懈，这个孤立的哨所陷入了破败，成为了士兵们想要逃避职责又不想逃入部落领地的理想避难所。",al={"为什么被废弃","为什么废弃哨塔破败不堪","为什么荒废"}}},fp="10,179,18.355.0,16.284.1,19.167.0,34.129.0,20.140.1,36.220.0"}
P.entries["subzone:lost-rigger-cove"] = {n="落帆海湾",s="落帆海湾坐落在塔纳利斯东部的悬崖边，是南海海盗在该地区的主要行动基地。这个隐蔽的港口三面环绕着高耸的沙漠山脉，拥有码头、防御营地，还有一个正在建造新海盗船只的活跃造船厂。",h="落帆海湾坐落在塔纳利斯东部的悬崖边，是南海海盗在该地区的主要行动基地。这个隐蔽的港口三面环绕着高耸的沙漠山脉，拥有码头、防御营地，还有一个正在建造新海盗船只的活跃造船厂。",kw={"自由之刃","加基森","落帆海湾","造船厂","南海海盗","塔纳利斯"},ang={["class:Rogue"]="这个庞大的海盗营地里挤满了可以偷窃的口袋、私人的保险箱，以及精通各种海上打斗下作手段的恶棍。",["race:Gnome"]="对于侏儒技师来说，海盗的干船坞是拼凑机械和赃物零件的粗糙但却明显的展示，也是对南部海域每一艘商船的持续威胁。"},sec={{t="海盗与高山壁垒",b="由于几乎四面都被陡峭的岩壁所环绕，天然的防御优势使落帆海湾成为了南海自由之刃在卡利姆多东南边缘的理想海上据点。在这里，海盗恶棍、码头工人和强盗们在加基森当局的眼皮底下打捞物资并组装新的船体。海湾使南海海盗能够向无尽之海投射力量，同时劫掠棘齿城、藏宝海湾和沿海定居点之间的贸易航线。"},{t="近在咫尺的竞争对手",b="海盗们并不是毫无阻碍地占据着这片海湾。加基森和附近热砂港的地精们对家门口的这些劫掠者感到愤恨，并雇佣佣兵来屠杀南海海盗，削弱他们的兵力，破坏他们的行动。"}},faq={{q="谁控制着落帆海湾？",a="该海湾由南海海盗控制，这是一个在卡利姆多和南海各处活动的臭名昭著的海上集团。他们利用这个天然良港来修理舰队并建造新的战舰。",al={"谁拥有落帆海湾","谁住在落帆海湾","落帆海湾阵营"}},{q="谁在这里与海盗作战？",a="加基森和热砂港的地精们对家门口的劫掠者深恶痛绝，他们雇佣过往的冒险者突袭海盗据点，并削弱南海海盗的实力。",al={"塔纳利斯的侏儒地精营地","为什么侏儒会在这里","为什么要与海盗作战"}},{q="落帆海湾位于哪里？",a="它位于塔纳利斯东海岸，加基森东南方。可以通过穿过沿海山脉屏障的一条蜿蜒峡谷小径进入。",al={"落帆海湾在哪里","如何前往落帆海湾","落帆海湾地图"}},{q="海盗们在海湾里建造什么？",a="南海海盗在海湾中心运营着一个活跃的干船坞和造船厂，木匠和强盗们正在那里忙于组装一艘大型远洋战舰的船体。",al={"落帆海湾造船厂","海盗船建造"}}},fp="16,213,26.385.0,22.208.0,30.190.0,33.189.0,34.152.0,42.163.0"}
P.entries["subzone:lower-wilds"] = {n="低地荒野",s="低地荒野构成了菲拉斯的东部门户，潮湿的森林在此与千针石林的干旱峡谷交汇。穿过这片树林的主干道将边界处的萨兰纳尔与更西边的定居点连接起来，沿途布满了古老的绿植和难以预料的林地生物。",h="低地荒野构成了菲拉斯的东部门户，潮湿的森林在此与千针石林的干旱峡谷交汇。穿过这片树林的主干道将边界处的萨兰纳尔与更西边的定居点连接起来，沿途布满了古老的绿植和难以预料的林地生物。",kw={"莫沙彻营地","菲拉斯东部","菲拉斯","低地荒野","萨兰纳尔","千针石林","树人"},ang={["faction:Alliance"]="对于离开千针石林的联盟旅行者来说，低地荒野是他们看到的第一个菲拉斯景观，并以萨兰纳尔的暗夜精灵边境前哨站作为锚点。",["faction:Horde"]="部落信使和前往莫沙彻营地的补给线在从边界峡谷下来后，必须穿过整个低地荒野。"},sec={{t="东部边境",b="低地荒野横跨菲拉斯的东部区域，是千针石林被阳光灼烤的峡谷与西部深邃原始丛林之间的自然过渡地带。进入该区域的旅行者必须沿着主干道穿过这段森林，经过守卫着山口的精灵前哨站萨兰纳尔。这里茂密的树冠栖息着古老的树人，还有那些使偏离道路变得十分危险的本土野生动物。"},{t="一条充满纷争的公路",b="由于它连接了南部荒野和东部领土，低地荒野上经常有旅行者、侦察兵和信使往来。虽然暗夜精灵把守着萨兰纳尔的关口，但部落在更内陆的地方设有莫沙彻营地。因此，穿过低地荒野的道路是任何在卡利姆多南部运送物资的人的关键生命线，不仅充满了自然的危险，也伴随着阵营间的紧张局势。"}},faq={{q="低地荒野位于何处？",a="低地荒野构成了菲拉斯最东部的广阔地带。它们直接与千针石林接壤，从萨兰纳尔的山区门户向西延伸至丛林内部。",al={"低地荒野位置","低地荒野在哪里","如何前往低地荒野"}},{q="低地荒野里生活着哪些生物？",a="这片林地栖息着古老的森林守护者，包括树人，以及游荡在野性森林地面上的本土掠食野兽。",al={"低地荒野怪物","低地荒野有什么","低地荒野敌人"}},{q="有哪些定居点靠近低地荒野？",a="在最东边的边界坐落着暗夜精灵前哨站萨兰纳尔，它是联盟进入菲拉斯的主要入口。沿路向西则是部落的定居点莫沙彻营地。",al={"低地荒野城镇","低地荒野附近的营地","低地荒野的部落与联盟城镇"}},{q="穿过低地荒野的道路安全吗？",a="这条路本身是穿过该区域最安全的路线，但旅行者仍需保持警惕。偏离道路会引来具有攻击性的森林动物和领地守护者的袭击，敌对阵营间的冲突偶尔也会波及到公路上。",al={"低地荒野安全吗","低地荒野道路安全"}}},fp="11,147,20.255.0,19.326.0,34.144.0,39.112.0,47.92.0,41.150.0"}
P.entries["subzone:lushwater-oasis"] = {n="甜水绿洲",s="甜水绿洲是贫瘠之地中三处维持着生命的水源之一，坐落在十字路口南侧。尽管这里看起来生机盎然，但绿洲内充满了危险，这里不仅盘踞着极具攻击性的考尔克半人马，还是哀嚎洞穴的入口所在地。这里的池水受到污染，对于那些寻找奇特变异鱼的钓鱼者来说可谓尽人皆知。",h="甜水绿洲是贫瘠之地中三处维持着生命的水源之一，坐落在十字路口南侧。尽管这里看起来生机盎然，但绿洲内充满了危险，这里不仅盘踞着极具攻击性的考尔克半人马，还是哀嚎洞穴的入口所在地。这里的池水受到污染，对于那些寻找奇特变异鱼的...",kw={"十字路口","变异鱼","考尔克","甜水绿洲","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="甜水绿洲呈现出一种令人不安的、非自然的过度生长，这是受附近哀嚎洞穴中散发出的扭曲能量所驱动。",["profession:Cooking"]="这里的池塘是少数几个钓鱼者能够钓到变异鱼的水域之一，这是一种在卡利姆多各地都备受推崇的重要食材，用于烹制美味风蛇。"},sec={{t="一处不稳定的避难所",b="甜水绿洲坐落于十字路口以南一段路程处，为这片被烈日炙烤的贫瘠之地提供了一处看似安宁的休憩之所。虽然棕榈树冠和清澈的泉水吸引了来自大草原各处的口渴野兽，但考尔克半人马占据了湖岸，潜伏在那里，伺机屠杀猎物和毫无防备的旅人。这座绿洲也是哀嚎洞穴的门户，那庞大的地下网络将腐化能量渗入上方的水潭，滋生出非自然的野生生物和怪异的变异体。"}},faq={{q="哀嚎洞穴的入口在哪里？",a="哀嚎洞穴洞穴系统的入口开凿在俯瞰甜水绿洲东侧的天然岩壁上。",al={"哀嚎洞穴在哪里","哀嚎洞穴入口"}},{q="谁控制着甜水绿洲？",a="考尔克半人马在整个绿洲内保持着绝对的统治地位，他们利用茂密的植被伏击路过的野生动物，并袭击从十字路口出发的旅人。",al={"谁住在甜水绿洲","甜水绿洲敌人","绿洲半人马"}},{q="为什么这里的鱼很奇怪？",a="从哀嚎洞穴泄漏出的深层能量腐蚀了绿洲内的水道，导致当地的鱼类变异成了不寻常的变异鱼。",al={"变异鱼地点","为什么有变异鱼","绿洲变异鱼"}},{q="萨尔的部落曾经过这里吗？",a="在兽人与牛头人穿越贫瘠之地的“长途跋涉”期间，萨尔带领他的军队穿过了该地区的各个绿洲，以获取维持生命的水源，同时还要抵御半人马无休止的伏击。",al={"萨尔长途跋涉绿洲","贫瘠之地绿洲兽人"}}},fp="15,213,22.371.0,53.111.0,29.125.0,30.104.0,39.182.0"}
P.entries["subzone:maclure-vineyards"] = {n="马科伦农场",s="马科伦农场是一处位于艾尔文森林南部，由马科伦家族拥有的广阔农业庄园。虽然这里以向暴风城提供葡萄和葡萄酒而闻名，但该农场也因其与邻近的斯通菲尔德家族之间持续不断的激烈仇怨而臭名昭著。",h="马科伦农场是一处位于艾尔文森林南部，由马科伦家族拥有的广阔农业庄园。虽然这里以向暴风城提供葡萄和葡萄酒而闻名，但该农场也因其与邻近的斯通菲尔德家族之间持续不断的激烈仇怨而臭名昭著。",kw={"野猪","艾尔文","杰拉德","马科伦","梅贝尔","斯通菲尔德","葡萄园","葡萄酒"},ang={["faction:Alliance"]="该庄园是重要的粮仓和葡萄园，为附近的闪金镇和暴风城提供食物和烈酒。",["race:Human"]="对于暴风城的人类来说，农场之间的争斗是乡村顽固观念的典型案例，提醒着旅人们，即便是在核心领土，邻居们也常因围栏问题争吵不休，而更大的威胁却在暗处伺机而动。"},sec={{t="苦涩的收成",b="马科伦农场坐落在艾尔文森林南部郁郁葱葱的山丘中，本应是一个酿酒和耕作的宁静天堂。然而，日常的劳作却被与马路对面斯通菲尔德家族之间长期存在的恶劣竞争所笼罩。两个家庭之间关于偷窃和血海深仇的指控根深蒂固，即便在饥饿的野猪和入侵的狗头人等共同威胁着双方家园时，双方的怒火依然难以平息。"},{t="禁忌之恋",b="尽管两个族长之间有着激烈的敌意，年轻的爱情却跨越了界限。梅贝尔·马科伦和托米·乔·斯通菲尔德坠入了爱河，他们在避开父母猜忌目光的隐秘树林中秘密幽会。经过农场的旅人常常发现自己卷入其中，帮他们传递秘密信息、解决琐碎争端，并试图帮助这对年轻情侣逃离家族怨恨的阴影。"}},faq={{q="马科伦家族和斯通菲尔德家族为什么在争斗？",a="这场竞争是一场长期存在的乡村争端，建立在多年的猜忌、琐碎的指责和固执的自尊之上。两家人互不信任，互相指责对方导致了货物和牲畜的损失，尽管双方都没有对方犯下恶行的确凿证据。",al={"马科伦 斯通菲尔德 仇怨","他们为什么互相憎恨","家族争斗"}},{q="谁是梅贝尔·马科伦？",a="梅贝尔是马科伦家的女儿。她秘密地爱上了托米·乔·斯通菲尔德，不顾家人对邻居的深仇大恨，希望能找到一种让他们在一起的方法。",al={"梅贝尔","马科伦的女儿"}},{q="农场面临着什么威胁？",a="除了家庭纠纷外，农场还深受糟蹋庄稼和葡萄藤的饥饿野猪的困扰，以及从附近金矿出没并洗劫周边田地的狗头人的威胁。",al={"葡萄园的危险","马科伦的野猪"}},{q="马科伦家族在这里生产什么？",a="马科伦家族种植葡萄藤，为整个艾尔文森林和暴风城的酒馆老板及商人们供应葡萄酒和新鲜水果。",al={"这里种植什么","马科伦的庄稼"}}},fx={["7abbd722"]={q="马科伦农场是什么地方？",a="马科伦农场是一处位于艾尔文森林南部的农庄。这片土地由马科伦家族耕作经营，为暴风城王国出产葡萄与佳酿。葡萄架之外，农场还有家族住宅与开阔的田地，不过眼下正受到肆虐的野猪侵扰，与邻居的关系也十分紧张。",al={"马科伦农场是什么","艾尔文森林马科伦农场","马科伦农场"}},d4181dc3={q="谁住在马科伦农场？",a="这座葡萄园由马科伦家族拥有并耕作。农庄中住着马科伦家族的几代人，其中包括杰拉德·马科伦和年轻的梅贝尔·马科伦。他们共同照料葡萄藤，保护作物免遭野生动物侵扰，并在与附近斯通菲尔德家族持续的摩擦中经营这片庄园。",al={"谁住在这里","马科伦家族成员","谁经营马科伦农场"}},["6b11f938"]={q="马科伦农场危险吗？",a="农场本身是一处宁静的联盟农庄，但葡萄藤间仍潜伏着危险。凶猛的野猪不断在田里拱掘，破坏作物，并攻击任何靠得太近的人。此外，附近矿洞中的狗头人偶尔也会游荡到农场边缘，因此农工与旅人都必须保持警惕。",al={"马科伦农场安全吗","马科伦农场的危险","马科伦农场的威胁"}},["5a643901"]={q="马科伦农场为何得名？",a="庄园直接以马科伦家族命名，正是他们开垦了这片土地，种下成片的葡萄藤。几代以来，他们的姓氏始终与当地的收成，以及艾尔文森林此地产出的甜葡萄酒紧密相连。",al={"为何叫马科伦农场","马科伦农场名称由来","马科伦农场名称"}}},fp="17,173,16.309.0,19.338.1,46.201.0,23.202.0,35.151.0,34.153.0"}
P.entries["subzone:maestra-s-post"] = {n="迈斯特拉岗哨",s="迈斯特拉岗哨是位于灰谷西部的一个小型联盟定居点，坐落在阿斯特兰纳西北方向和奥迪拉兰废墟以南的道路沿线。这里由暗夜精灵哨兵守卫，同时也接纳了在卡利姆多这片古老森林中罕见的人类，作为防范入侵威胁的前哨站。",h="迈斯特拉岗哨是位于灰谷西部的一个小型联盟定居点，坐落在阿斯特兰纳西北方向和奥迪拉兰废墟以南的道路沿线。这里由暗夜精灵哨兵守卫，同时也接纳了在卡利姆多这片古老森林中罕见的人类，作为防范入侵威胁的前哨站。",kw={"灰谷","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","奥迪拉兰","哨兵"},ang={["faction:Alliance"]="对于离开黑海岸安全区域的联盟旅行者来说，这座岗哨代表着你在灰谷这片争夺激烈的森林中遇到的第一个友好的欢迎点和堡垒。",["race:NightElf"]="这座岗哨展示了新联盟日益发展的伙伴关系，哨兵们与东部王国的年轻种族共享炉火和守卫职责。"},sec={{t="前哨站",b="迈斯特拉岗哨坐落在灰谷西部的树冠之下，由一座细长的暗夜精灵哨塔和一间开放式小屋组成。它是往来于黑海岸海岸线和阿斯特兰纳大型枢纽之间的旅行者的重要中转站。尽管建筑风格宁静，但这座岗哨始终处于警戒状态。当地的哨兵密切注视着周围的荒野，那里的腐化熊怪蠢蠢欲动，附近部落的行动也时刻威胁着联盟的补给线。"},{t="联盟的聚集地",b="与森林深处许多封闭的暗夜精灵聚居地不同，迈斯特拉岗哨因容纳了少量人类盟友而引人注目。费罗·艾隆汉和净化者德尔格伦等人物与哨兵们住在一起，他们贡献自己的武力，并侍奉圣光，为更广阔的联盟效力。他们的存在使这个偏远的营地成为了东部王国与卡利姆多古老守护者之间最早的交汇点之一。"}},faq={{q="迈斯特拉岗哨在哪里？",a="它位于灰谷西部，坐落在阿斯特兰纳西北方向的道路沿线，就在奥迪拉兰废墟的南边。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪里","寻找迈斯特拉岗哨"}},{q="迈斯特拉是谁？",a="岗哨里没有任何记录说明迈斯特拉是谁。这座岗哨以此命名，但驻扎在这里的哨兵中并没有这位同名者。",al={"迈斯特拉是谁","月之女祭司迈斯特拉"}},{q="为什么精灵岗哨里会有人类？",a="在第三次战争之后，随着暗夜精灵加入联盟，像费罗·艾隆汉和净化者德尔格伦这样的旅行者和战士冒险来到卡利姆多，提供援助并加强与暗夜精灵盟友的关系。",al={"为什么人类会出现在灰谷","费罗·艾隆汉为什么在这里","净化者德尔格伦为什么在这里"}},{q="迈斯特拉岗哨面临哪些威胁？",a="岗哨必须应对潜伏在周围林地中的腐化熊怪部族，以及从附近进入灰谷的部落侦察队和入侵部队。",al={"谁在攻击迈斯特拉岗哨","迈斯特拉岗哨的危险"}}},fp="14,190,15.302.0,21.314.0,32.117.0,16.116.0,41.213.0,33.123.0"}
P.entries["subzone:mage-quarter"] = {n="Mage Quarter",s="法师区是暴风城的奥术核心，坐落于首都西南角，横跨运河。在鹅卵石街道和各种奥术专卖店上方，耸立着巫师圣殿，王国的施法者们在此磨练技艺。在这个充满学术气息的街区表面之下，还隐藏着幽暗的角落，包庇着那些钻研更黑暗魔法的施法者。",h="法师区是暴风城的奥术核心，坐落于首都西南角，横跨运河。在鹅卵石街道和各种奥术专卖店上方，耸立着巫师圣殿，王国的施法者们在此磨练技艺。在这个充满学术气息的街区表面之下，还隐藏着幽暗的角落，包庇着那些钻研更黑暗魔法的施法者。",kw={"奥术","蓝隐士","运河","法师区","已宰的羔羊","暴风城","巫师圣殿"},ang={["class:Mage"]="该街区是你在暴风城的核心家园，在巫师圣殿内提供高级训练师和法术材料。",["class:Warlock"]="在屠宰羔羊旅店的公众伪装下，隐藏着一个隐秘的集会，黑暗艺术的修行者们在此秘密聚会，训练并召唤爪牙。"},sec={{t="奥术圣殿",b="你可以从大教堂广场或贸易区跨越运河上的桥梁抵达法师区，这里完全满足联盟对于神秘学的所有需求。以巫师圣殿的高塔为中心，人类和盟友种族的施法者们聚集在这里，研究奥术编织，并训练学徒。周边的街道挤满了出售布匹、材料、炼金用品和附魔长袍的商人，构成了一个专门用于研究和王国防御的封闭街区。"},{t="表面之下的秘密",b="并非该区所施展的所有法术都得到了王国高等施法者的批准。虽然像蓝隐士旅店这样的场所为学者们提供了安静的避难所，但臭名昭著的屠宰羔羊旅店却在其地下墓穴中隐藏着一个隐秘的术士集会。在那里，远离城市卫兵的视线和圣光大教堂广场的注视，恶魔学者们钻研被禁止的邪能仪式并束缚异界生物，以此伪装在街区对神秘异常现象的普遍容忍之中。"}},faq={{q="什么是巫师圣殿？",a="巫师圣殿是法师区内最为显眼的塔楼。它是暴风城法师的主要学院、图书馆和训练场，也是学者、神秘学训练师和负责保卫首都的防御性施法者的驻地。",al={"法师塔","巫师圣殿","暴风城法师圣殿"}},{q="在法师区哪里可以训练术士？",a="术士们秘密地聚集在屠宰羔羊旅店下方，那是一家位于该区不引人注目的旅店。在其地穴和隐藏的地窖里，邪能魔法的修行者们可以研究黑暗仪式，召唤恶魔，并在不受城市卫兵监视的情况下进行训练。",al={"术士训练师位置","屠宰羔羊地下室","暴风城术士训练师"}},{q="法师区里有什么样的商店？",a="该区遍布着满足施法者和工匠需求的专卖店。游客们可以找到像邓肯的纺织品店和拉尔森服装店这样的裁缝店，以及炼金与草药商人、附魔供应商、烟火供应处和长袍商人。",al={"法师区商人","这里有什么商店","法师区店铺"}},{q="如何前往法师区？",a="法师区位于暴风城的西南角。你可以直接从贸易区或大教堂广场穿过横跨运河的桥梁进入。",al={"法师区在哪里","如何前往法师区","去往法师区的路线"}}},fx={cffe9f84={q="什么是法师区？",a="法师区是暴风城西南角的奥术中心，隔着运河与教堂广场和贸易区相望。这里以巍峨的巫师圣所尖塔为标志，是王国各地的学者、炼金师、裁缝和神秘技艺从业者的主要聚集地。",al={"什么是法师区","暴风城法师区","法师区"}},["4d297df6"]={q="谁住在法师区，或由谁管理？",a="这里主要居住着王国的法师、奥术研究者、学者，以及炼金师和制衣匠等相关行业的从业者。巫师圣所中的法师团体负责处理魔法事务，并致力于保障首都及周边土地的安全；不过，当地酒馆下方也有黑暗的施法者暗中聚集。",al={"谁住在法师区","谁管理法师区","法师区的居民"}},["1c00796e"]={q="法师区危险吗？",a="表面上，法师区是宁静的学术与商业中心，并由城卫严密看守。然而，在已宰的羔羊酒馆欢快的表象之下，藏着一个秘密的术士集会。他们在阴影中施展黑暗的恶魔召唤术，却不受上方城中当局的干涉。",al={"法师区安全吗","法师区的危险","法师区有哪些危险"}},ddf0f180={q="为什么叫法师区？",a="这里被定为暴风城施法者的聚集地，因此得名。城区围绕巫师圣所建立，城中的法师在此居住、学习并精进奥术技艺。",al={"为什么叫法师区","法师区名称由来"}}},fp="12,237,21.385.0,27.417.1,29.226.0,45.197.0,43.232.0,34.138.0"}
P.entries["subzone:magic-quarter"] = {n="Magic Quarter",s="魔法区是幽暗城的东北城区，是遗忘者进行奥术研究和钻研黑暗法术的中心。该区域由一座阴森恐怖的诅咒神庙所主宰，汇集了各种奥术和邪能的修行者。",h="魔法区是幽暗城的东北城区，是遗忘者进行奥术研究和钻研黑暗法术的中心。该区域由一座阴森恐怖的诅咒神庙所主宰，汇集了各种奥术和邪能的修行者。",kw={"遗忘者","法师","魔法区","传送门训练师","裁缝","诅咒神庙","幽暗城","术士"},ang={["class:Mage"]="魔法区是遗忘者法术研究的核心，提供奥术艺术的训练，以及将幽暗城与更广阔的部落连接起来的传送网络。",["class:Warlock"]="在诅咒神庙黑暗的壁龛中，术士们召唤恶魔仆从并磨练暗影魔法，远离联盟评判的目光。"},sec={{t="黑暗艺术的汇聚地",b="魔法区位于这座地下城市的东北象限，是遗忘者们保存奥术遗产并深入研究黑暗法术的地方。该区的核心是一座高耸的诅咒神庙，这是一种天灾军团风格的建筑遗迹，现已被获得自由意志的亡灵重新利用。在它穹顶之下阴影笼罩的大厅里，法师们在这里操纵微妙的魔法能量，术士们则在此与恶魔实体沟通，使这里成为了洛丹伦知识力量和神秘研究的枢纽。"},{t="学者、织法者与召唤师",b="除了对原始塑能和召唤的研究外，魔法区还是施法者们不可或缺的民用中心。传送门训练师在这里维护着连接部落领地的运输网络，而裁缝大师则利用附魔织物制作长袍和寿衣。与达拉然对学院派法术和禁忌魔法的严格隔离不同，遗忘者在这里公开地融合了奥术的好奇心与邪能的力量，以巩固他们对抗众多敌人的地位。"}},faq={{q="魔法区的目的是什么？",a="魔法区是遗忘者进行奥术和恶魔研究的中心。这里有法师和术士的职业训练师、连接其他城市的传送门大师，以及编织附魔布料的裁缝专业人士。",al={"什么是魔法区","魔法区的目的","幽暗城魔法区"}},{q="为什么幽暗城里会有诅咒神庙？",a="当幽暗城在洛丹伦王城废墟下被天灾军团挖掘出来时，他们建造了诅咒神庙这样的建筑。当希尔瓦娜斯和她拥有自由意志的遗忘者夺取了这座地下建筑群后，他们接管了这些现有的设施，并将其重新用于他们自己的施法者。",al={"幽暗城诅咒神庙","为什么有诅咒神庙","幽暗城的天灾建筑"}},{q="谁可以在魔法区接受训练？",a="法师、术士和恶魔训练师负责指导该区的修行者，而传送门专家和裁缝技师则提供运输和制作方面的训练。",al={"魔法区的训练师","谁在这里训练","魔法区的职业"}},{q="魔法区位于哪里？",a="它位于幽暗城的东北象限，穿过中心环形区域与炼金区相对。",al={"魔法区在哪里","魔法区位置","寻找魔法区"}}},fp="13,123,23.355.0,32.367.0,41.182.0,53.241.0,40.143.0,35.111.0"}
P.entries["subzone:magram-village"] = {n="玛格拉姆村",s="玛格拉姆村是玛格拉姆半人马氏族的定居点，坐落在凄凉之地东南部污浊的黄色池塘之间。这是玛格拉姆氏族对他们痛恨的宿敌吉尔吉斯氏族发动无休止战争的主要基地。",h="玛格拉姆村是玛格拉姆半人马氏族的定居点，坐落在凄凉之地东南部污浊的黄色池塘之间。这是玛格拉姆氏族对他们痛恨的宿敌吉尔吉斯氏族发动无休止战争的主要基地。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","玛格拉姆村","池塘"},ang={["race:Tauren"]="半人马的野蛮行径几代以来一直困扰着卡利姆多的部落，使得这些游牧掠夺者的任何定居点都令人不安地提醒着人们过去的流血冲突。"},sec={{t="泥潭中的据点",b="玛格拉姆村绵延分布在凄凉之地东南部的停滞硫磺池塘周边的岛屿和岸边，是一个由粗糙木桥和兽皮帐篷拼凑而成的简陋定居点。玛格拉姆半人马在这里时刻保持警惕，防备邻近的氏族。玛格拉姆人以残暴和对南部的吉尔吉斯氏族根深蒂固的敌意而闻名，他们愿意容忍外来者，前提是这些旅行者能通过屠杀吉尔吉斯敌人来证明自己的价值。"}},faq={{q="谁住在玛格拉姆村？",a="该村庄是玛格拉姆氏族的家园，这是凄凉之地土生土长的多个交战半人马部落之一。他们住在由简陋的人行桥连接的岛屿上的粗糙兽皮天棚下。",al={"谁在这里","玛格拉姆居民","半人马村庄"}},{q="我能在不被攻击的情况下进入玛格拉姆村吗？",a="起初，玛格拉姆半人马对所有外来者都怀有敌意。然而，旅行者可以通过追杀他们的誓敌——吉尔吉斯半人马——来赢得他们的信任，从而提升在该氏族的声望。",al={"玛格拉姆友好吗","玛格拉姆敌对","如何访问玛格拉姆村"}},{q="为什么村庄周围的池塘是黄色的？",a="村庄内外及周边的池塘被凄凉之地荒芜土地典型的硫磺和矿物径流所污染，导致它们停滞、变色且遭受污染。",al={"黄色的水","受污染的池塘","玛格拉姆的水"}},{q="为什么玛格拉姆要与吉尔吉斯开战？",a="凄凉之地的半人马氏族之间有着传说中的血腥宿怨。特别是玛格拉姆氏族和吉尔吉斯氏族，为了争夺荒原南部的统治权，已经进行了几代人的苦战。",al={"玛格拉姆对阵吉尔吉斯","半人马血仇","半人马战争"}}},fp="14,154,24.369.0,28.168.0,50.174.0,44.136.0,39.175.0"}
P.entries["subzone:main-hall-northshire"] = {n="Main Hall (Northshire)",s="主厅是艾尔文森林中北郡修道院的中央入口大厅。它是连接修道院庭院与上方塔楼、武器大厅以及图书馆侧翼的主要枢纽。在这里，新招募的人类冒险者们会进行报到，并领取他们效忠暴风城王国的首个任务。",h="主厅是艾尔文森林中北郡修道院的中央入口大厅。它是连接修道院庭院与上方塔楼、武器大厅以及图书馆侧翼的主要枢纽。在这里，新招募的人类冒险者们会进行报到，并领取他们效忠暴风城王国的首个任务。",kw={"修道院","艾尔文","武器大厅","图书馆侧翼","主厅","北郡","暴风城"},ang={["race:Human"]="对于王国的人类而言，北郡修道院的主厅标志着他们开始踏上效忠暴风城和圣光的旅程。"},sec={{t="修道院之心",b="穿过北郡修道院宏伟的拱门，访客便直接进入了主厅。作为这座建筑的中心枢纽，它将抵达的受训者和牧师人员引导至修道院的各个区域：一侧是用于军事训练的武器大厅，另一侧是充满学术气息的图书馆侧翼，还有通往修道院塔楼的阶梯。大厅原本宁静的庇护所氛围，因山谷中持续不断的冲突而显得有些紧迫，军官们在此召集身强力壮的新手，以保卫王国的边境。"}},faq={{q="主厅的用途是什么？",a="主厅是北郡修道院的中央接待大厅和交通枢纽。它将新兵、牧师和访客引导至武器大厅、图书馆侧翼以及修道院的上方塔楼。",al={"什么是主厅","北郡主厅的作用"}},{q="谁在这里引导新兵？",a="驻守在主厅的暴风城防卫军官和牧师会对到来的冒险者进行评估，并为他们提供清除威胁修道院领地之敌的最初指令。",al={"谁在这里发放任务","修道院指挥官"}}},fx={["23c998e2"]={q="北郡修道院的主厅是什么地方？",a="主厅是北郡修道院入口处的中央大厅，坐落于艾尔文森林中幽静的北郡山谷。它是连接修道院高塔、图书馆侧翼和武器大厅的主要通道，因此也成为初来乍到的王国守卫们的活动中心。",al={"主厅是什么地方","北郡的主厅","这座大厅是什么地方"}},c47795b4={q="主厅危险吗？",a="大厅有守卫驻守，能让人避开山谷中的危险。修道院外，凶猛的野生动物和迪菲亚匪徒威胁着周围一带。",al={"主厅安全吗","主厅危险","主厅里有敌人吗"}}},fp="22,213,18.329.0,37.166.0,30.161.0"}
P.entries["subzone:maker-s-terrace"] = {n="造物者遗迹",s="造物者遗迹是一处绵延的户外挖掘场，位于荒芜之地北部，正对着古老的泰坦金库——奥达曼的入口。从洛克莫丹向南探险的旅行者必须穿越其崎岖的外围，这里目前被黑铁矮人强硬地占据着。这个挖掘场是地表荒原与埋藏在下方的泰坦秘密之间的一道充满纷争的门槛。",h="造物者遗迹是一处绵延的户外挖掘场，位于荒芜之地北部，正对着古老的泰坦金库——奥达曼的入口。从洛克莫丹向南探险的旅行者必须穿越其崎岖的外围，这里目前被黑铁矮人强硬地占据着。这个挖掘场是地表荒原与埋藏在下方的泰坦秘密之间的一...",kw={"荒芜之地","黑铁矮人","挖掘","造物者遗迹","泰坦","奥达曼"},ang={["profession:Mining"]="凿刻在砂岩悬崖上的广阔采石场和土方工程显示出矮人挖掘者进行大规模矿石开采的明显迹象。",["race:Dwarf"]="对于铁炉堡的矮人来说，看到造物者遗迹掌握在阴险的黑铁氏族手中是一件令人痛苦的事，因为奥达曼深藏着矮人起源的终极秘密。"},sec={{t="金库的门槛",b="造物者遗迹横跨了荒芜之地的北部断崖，作为奥达曼地底大厅的外部集结地。在旅行者深入地下遗迹之前，必须先面对这处宏大挖掘场中焦灼的土方、脚手架和石沟。它正位于通往洛克莫丹的山口下方，是任何敢于进入这片干旱荒原的旅行者遇到的第一个地标。随着敌对势力争相探寻埋藏在岩石下的远古秘密，这片遗迹正充斥着暴力的工业活动。"},{t="黑铁矮人的占领",b="该遗址牢牢地处于黑铁氏族的掌控之下，他们带着充满敌意的警惕巡视着遗迹的沟渠和外围。被泰坦遗物和地下统治权的诱惑所吸引，这些穴居矮人不断向山坡深处挖掘，搜寻远古造物者留下的任何武器、记录或大地遗物。任何试图在不清理这些防御哨兵的情况下进入奥达曼深处大厅的人，很快就会发现自己难以应对。"}},faq={{q="造物者遗迹在哪里？",a="造物者遗迹位于荒芜之地的极北端，就在连接该区域与洛克莫丹的峡谷山口附近。它环绕着通往奥达曼远古建筑群的外部入口。",al={"造物者遗迹位置","造物者遗迹在哪里","如何找到造物者遗迹"}},{q="谁控制着造物者遗迹？",a="该遗址被怀有敌意的黑铁矮人占领并巡逻，他们在此进行积极的挖掘作业，并严密防守奥达曼的外部入口，抵御外来者。",al={"谁在造物者遗迹","造物者遗迹的敌人","谁控制了造物者遗迹"}},{q="挖掘的目的是什么？",a="黑铁矮人正在挖掘古老的泰坦建筑群奥达曼。他们试图在敌对势力抢先夺取之前，找出埋藏在地底金库中的遗物、强大的机械和古老的泰坦秘密。",al={"为什么他们在这里挖掘","造物者遗迹挖掘场","黑铁矮人在寻找什么"}},{q="造物者遗迹是奥达曼的一部分吗？",a="是的，造物者遗迹是通往奥达曼地下城和洞穴的外部露天挖掘坑。",al={"这是奥达曼吗","造物者遗迹与奥达曼的区别","遗迹与地下城的连接"}}},fp="15,155,22.315.0,20.361.0,37.141.0,33.126.0,38.194.0,35.100.0"}
P.entries["subzone:malaka-jin"] = {n="玛拉卡金",s="玛拉卡金是一个坐落在石爪山脉低矮丘陵地带的小型部落营地，位于恐怖图腾岗哨的正南方。这里主要居住着暗矛巨魔猎人，作为从贫瘠之地进入崎岖山峰的旅人们的一处乡村驿站和狩猎前哨。",h="玛拉卡金是一个坐落在石爪山脉低矮丘陵地带的小型部落营地，位于恐怖图腾岗哨的正南方。这里主要居住着暗矛巨魔猎人，作为从贫瘠之地进入崎岖山峰的旅人们的一处乡村驿站和狩猎前哨。",kw={"暗矛","恐怖图腾","部落","猎人","玛拉卡金","前哨站","石爪山脉","巨魔"},ang={["faction:Horde"]="玛拉卡金是部落在石爪山脉的最南端门户，是在贫瘠之地和北部山地要塞之间的道路上的一处重要驿站。",["race:Troll"]="对于暗矛巨魔来说，玛拉卡金是巨魔自力更生和追踪技巧的骄傲证明，他们在远离卡利姆多热带海岸的崎岖高地上开辟了一个家园。"},sec={{t="猎人的避难所",b="玛拉卡金隐藏在通往石爪山脉的主路附近，为冒险进入这一争夺中高地的部落漫游者提供了一个受欢迎的避难所。这个村庄是一群粗犷的巨魔猎人的家园，他们依靠岩脊和灌木丛艰难度日。虽然生活简朴，但这些猎人提供补给，与疲惫的冒险者交换新鲜猎物，并时刻警惕着敌对的山地野生动物，以及潜伏在更远山路上的好战的恐怖图腾牛头人。"},{t="高地上的立足点",b="玛拉卡金险要地坐落在贫瘠之地的边界附近，标志着部落在石爪山脉建立的最早的据点之一。虽然与北面更大的要塞烈日石居相比，这里既小又安静，但它起到了至关重要的后勤枢纽作用，使部落追踪者能够监控部落动乱，并保护蜿蜒的道路免受迫近威胁的侵扰。"}},faq={{q="什么是玛拉卡金？",a="玛拉卡金是位于石爪山脉南部的一个小型部落村庄和前哨站。这里住着一群暗矛巨魔猎人，他们为从贫瘠之地爬上来的旅行者提供庇护、贸易和补给。",al={"玛拉卡金在哪里","这是什么地方","玛拉卡金 石爪山脉"}},{q="谁住在玛拉卡金？",a="这个定居点几乎完全由巨魔猎人居住。他们靠狩猎山里的野味，并与过往的冒险者交易肉类和皮革来维持生计。",al={"玛拉卡金的非玩家角色","这里有什么人","石爪山脉的巨魔"}},{q="营地面临什么威胁？",a="除了凶猛的山地掠食者外，村庄直接位于敌对的恐怖图腾岗哨南面，这使得这个小型巨魔营地必须时刻警惕来自那个怀有敌意的牛头人部族的侵犯。",al={"玛拉卡金的敌人","谁在攻击玛拉卡金"}},{q="这里有飞行管理员吗？",a="没有。在这个时代，玛拉卡金没有飞行管理员。穿越石爪山脉的冒险者必须依靠西北方向更远处的烈日石居的飞行管理员，或者步行穿过道路。",al={"玛拉卡金的飞行点","飞往玛拉卡金"}}},fp="10,140,17.266.0,25.236.0,19.190.0,24.131.0,27.150.0,30.141.0"}
P.entries["subzone:malden-s-orchard"] = {n="玛尔丁果园",s="玛尔丁果园是银松森林北部的一处废弃农场，以在洛丹伦天灾军团入侵期间逃离的人类主人命名。这里早已荒废，黑暗的常青树在杂草丛生中矗立，凶残的黑狼在场地上徘徊。果园里摇摇欲坠的小屋曾作为一个与部队失散的被遗忘者斥候的临时避难所。",h="玛尔丁果园是银松森林北部的一处废弃农场，以在洛丹伦天灾军团入侵期间逃离的人类主人命名。这里早已荒废，黑暗的常青树在杂草丛生中矗立，凶残的黑狼在场地上徘徊。果园里摇摇欲坠的小屋曾作为一个与部队失散的被遗忘者斥候的临时避难所...",kw={"小屋","埃兰德·麦克里","伊瓦农场","玛尔丁","玛尔丁果园","银松森林","狼"},ang={["faction:Horde"]="从瑟伯切尔或提瑞斯法林地边界向南移动的旅行者在经过果园时必须小心，因为农场里栖息着极具攻击性的狼群。",["race:Undead"]="对于被遗忘者来说，这座果园是人类毁灭的遗迹，也是银松森林北部的一块争议之地，亡灵哨兵必须从野兽手中将其夺回。"},sec={{t="枯萎的收获",b="在第三次战争之前，这个农场由一位名叫玛尔丁的农夫照料，曾为洛丹伦的城镇供应新鲜水果。当天灾军团席卷王国时，玛尔丁为了逃避瘟疫抛弃了自己的土地。在此后的岁月里，果园在银松森林黑暗弥漫的雾气下窒息。常青树无人修剪，果实在枯萎的枝头腐烂，这片土地已完全被野生掠食者所占据。"},{t="困于小屋",b="杂草丛生的果园已成为领地性黑狼的猎场，使其成为穿过银松森林北部的一条危险路线。在为亡灵哨兵执行侦察任务期间，斥候埃兰德·麦克里被派往该地区进行调查，却发现自己被这些野兽包围。埃兰德在玛尔丁破旧的小屋中被困了数天，直到被遗忘者的增援部队冲破狼群并将他护送回伊瓦农场的斥候同伴身边，他才得以生还。"}},faq={{q="玛尔丁是谁？",a="玛尔丁是一位人类农夫，在洛丹伦陷落前住在这里。在第三次战争期间天灾军团入侵王国时，他抛弃了果园并为逃命而逃离。",al={"玛尔丁背景故事","谁拥有这个果园","玛尔丁是谁"}},{q="为什么果园里满是狼？",a="由于没有活人来保卫农场，在银松森林徘徊的野生黑狼将茂密的树林和废弃的庭院据为它们的狼群领地。",al={"为什么这里有狼","玛尔丁果园的狗","狼群出没"}},{q="谁被困在小屋里？",a="亡灵哨兵埃兰德·麦克里被困在小屋里。他受被遗忘者派遣执行侦察任务，却遭到了果园里狼群的伏击，只能躲在屋内直到救援到来。",al={"被困小屋的斥候","谁在屋子里","小屋里的亡灵哨兵"}},{q="现在还有人从这个果园采摘水果吗？",a="没有。这些黑暗的树木多年来无人照料，它们的果实在银松森林蔓延的腐朽中在枝头烂掉。",al={"水果能吃吗","玛尔丁果园的收获","能采摘水果吗"}}},fp="16,268,18.382.0,22.385.1,15.158.0,33.158.0,34.176.0,48.117.0"}
P.entries["subzone:mannoroc-coven"] = {n="玛诺洛克集会所",s="玛诺洛克集会所是位于凄凉之地南部的一处被恶魔占据的废墟，以深渊领主玛诺洛斯命名。它坐落在古老的暗夜精灵建筑群中，是燃烧军团在卡利姆多中部最大的据点。火刃氏族的邪教徒在这里维持着活跃的召唤传送门，用邪犬、魅魔和地狱火充斥着这片布满灰烬的土地。",h="玛诺洛克集会所是位于凄凉之地南部的一处被恶魔占据的废墟，以深渊领主玛诺洛斯命名。它坐落在古老的暗夜精灵建筑群中，是燃烧军团在卡利姆多中部最大的据点。火刃氏族的邪教徒在这里维持着活跃的召唤传送门，用邪犬、魅魔和地狱火充斥着...",kw={"阿兹雷索克","火刃氏族","集会所","凄凉之地","邪犬","地狱火","朱格卡尔·格里姆罗德","玛诺洛克"},ang={["class:Warlock"]="浓缩的邪能和活跃的军团召唤裂隙使该集会所成为了重要的战术目标，提供了对原始恶魔显现的第一手观察机会。",["race:NightElf"]="看着你远古先祖的石砌建筑被恶魔入侵者亵渎和践踏，玛诺洛克集会所成为了对上古之战令人痛苦的回忆。"},sec={{t="魔火堡垒",b="玛诺洛克集会所坐落于幽灵岗哨以南、葬影村以东，笼罩在压抑、受邪能污染的阴霾之中，覆盖了古老的暗夜精灵废墟。该集会所由领主阿兹雷索克与火刃氏族术士朱格卡尔·格里姆罗德在地面指挥。他们共同利用活跃的召唤传送门将恶魔增援部队直接拉入卡利姆多，其中包括末日守卫、地狱火和邪犬。尽管部落阵营的旅者试图利用伊鲁索斯之手这样的圣物切断这些连接，但新的裂隙仍在伤痕累累的大地上不断撕裂开来。"}},faq={{q="为什么这个地方被称为玛诺洛克集会所？",a="这座营地的命名是为了向毁灭者玛诺洛斯致敬，这位臭名昭著的深渊领主曾通过血之诅咒奴役了兽人，并最终死于灰谷。",al={"谁是玛诺洛斯","玛诺洛克名称起源","为什么叫玛诺洛克"}},{q="谁在统治这座集会所？",a="这里的恶魔军队由恶魔领主阿兹雷索克率领。凡人的事务则由火刃氏族邪教的代表，术士朱格卡尔·格里姆罗德负责。",al={"谁领导玛诺洛克集会所","玛诺洛克集会所首领","阿兹雷索克"}},{q="这座集会所建立在什么废墟之上？",a="这座恶魔营地占据了一个古老暗夜精灵定居点的破碎石基，早在恶魔用邪能魔法淹没该地区之前，这里就已经荒废很久了。",al={"这里有什么废墟","玛诺洛克古代废墟","凄凉之地的精灵废墟"}},{q="恶魔是如何抵达凄凉之地的？",a="火刃氏族的邪教徒在废墟各处维持着魔法召唤传送门。这些传送门不断地从扭曲虚空直接吸入增援部队，使得外界试图彻底净化该地点的努力受挫。",al={"恶魔从哪里来","凄凉之地的火刃氏族传送门"}}},fp="14,219,21.428.1,40.141.0,25.116.1,36.162.0,40.199.0"}
P.entries["subzone:manor-mistmantle"] = {n="密斯特曼托庄园",s="密斯特曼托庄园是一处腐朽的庄园，坐落在暮色森林东北部的阴影丘陵中，位于夜色镇以北。这里曾经是一个体面的家庭宅邸，如今已沦为废墟和恐怖之地，爬满了受其臭名昭著的主人驱使的亡灵食尸鬼。",h="密斯特曼托庄园是一处腐朽的庄园，坐落在暮色森林东北部的阴影丘陵中，位于夜色镇以北。这里曾经是一个体面的家庭宅邸，如今已沦为废墟和恐怖之地，爬满了受其臭名昭著的主人驱使的亡灵食尸鬼。",kw={"乞丐鬼屋","夜色镇","暮色森林","食尸鬼","密斯特曼托庄园","斯塔文","斯塔文·密斯特曼托","蒂罗亚之泪"},ang={["faction:Alliance"]="对于追踪斯塔文受害者悲惨命运的联盟调查者来说，密斯特曼托庄园是斯塔文传说悲剧性的终点。"},sec={{t="一处荒废的宅邸",b="密斯特曼托庄园位于乞丐鬼屋以西，是凶杀与疯狂的阴森纪念碑。庄园内充斥着腐烂的气息，凶残的食尸鬼徘徊其中，守护着这座破败的建筑。在腐烂和枯萎的植被中，这片土地上唯一的生命美景是那朵生长在无人照料的花园里、孤独而忧伤的花朵：名为蒂罗亚之泪的花。"},{t="庄园的主人",b="这座庄园属于斯塔文·密斯特曼托，他曾是一名教师和私人导师。他对自己的学生蒂罗亚一家犯下的骇人罪行，已成为王国里广为流传的黑暗传说。如今，身为亡灵代理人的斯塔文潜伏在自家宅邸的二楼，周围环绕着他所屠杀的受害者的残骸，并有蹒跚的恐怖生物守卫。来自夜色镇的旅人和调查者常常发现，这位暮色森林中最臭名昭著的幽灵的踪迹，最终都指向了这座血迹斑斑的庄园。"}},faq={{q="密斯特曼托庄园在哪里？",a="密斯特曼托庄园位于暮色森林的东北部，坐落在夜色镇的正北方，乞丐鬼屋的西侧。",al={"密斯特曼托庄园位置","密斯特曼托庄园在哪里","如何找到密斯特曼托庄园"}},{q="谁住在密斯特曼托庄园？",a="该庄园属于斯塔文·密斯特曼托，他曾是一名导师，如今已变成一个被食尸鬼环绕的亡灵生物。",al={"密斯特曼托庄园里的人","密斯特曼托庄园首领","斯塔文之屋"}},{q="什么是蒂罗亚之泪？",a="蒂罗亚之泪是盛开在密斯特曼托庄园花园中的一朵孤独而娇嫩的花，是腐朽的庄园中唯一的自然生命迹象。",al={"蒂罗亚之泪花朵","密斯特曼托花园花朵","蒂罗亚之花"}},{q="为什么这里有亡灵守卫？",a="在庄园里游荡的食尸鬼是受斯塔文·密斯特曼托驱使的爪牙，它们负责保护主人，并屠杀任何胆敢闯入这片荒芜庄园的人。",al={"为什么密斯特曼托有食尸鬼","密斯特曼托亡灵","密斯特曼托庄园敌人"}}},fp="16,142,20.218.0,24.462.1,34.99.0,30.108.1,27.146.0,42.143.1"}
P.entries["subzone:mardenholde-keep"] = {n="玛登霍尔德城堡",s="玛登霍尔德城堡是西瘟疫之地北端俯瞰壁炉谷的雄伟石制堡垒。它曾是提里奥·弗丁领主的祖传宅邸，如今在提里奥之子——泰兰·弗丁大领主的统治下，成为了狂热的血色十字军在该地区的Command Center。",h="玛登霍尔德城堡是西瘟疫之地北端俯瞰壁炉谷的雄伟石制堡垒。它曾是提里奥·弗丁领主的祖传宅邸，如今在提里奥之子——泰兰·弗丁大领主的统治下，成为了狂热的血色十字军在该地区的Command Center。",kw={"达索汉","壁炉谷","玛登霍尔德","血色十字军","白银之手","泰兰·弗丁","提里奥·弗丁"},ang={["class:Paladin"]="玛登霍尔德代表了圣骑士历史上悲剧性的一章：这里曾是白银之手高尚的圣所，而其大厅正是该组织在狂热的血色十字军与警惕的银色黎明之间分崩离析的地方。",["race:Human"]="对于洛丹伦的人类来说，玛登霍尔德是一个苦涩的提醒：他们家园中最引以为傲的堡垒在挺过了兽人战争后，却在天灾军团入侵期间沦为了疯狂与狂热的牺牲品。"},sec={{t="弗丁家族的领地",b="玛登霍尔德城堡最初是作为壁炉谷公国的行政中心而建，长期以来一直被洛丹伦的人民所称颂，因为在第二次战争期间它从未被攻破。提里奥·弗丁领主曾在议事大厅与其信任的顾问一同治理周边山谷，维持着和平，直到他因为捍卫兽人伊崔格而遭到了充满争议的审判与流放。在提里奥失势后，治理权先是落入了他那充满野心的学徒巴瑟拉斯手中，最终传给了提里奥之子泰兰，他在洛丹伦毁灭前夕继承了父亲的领地。"},{t="十字军的摇篮",b="当天灾军团横扫洛丹伦时，这座城堡归入了血色十字军的旗帜之下。然而，内部的偏执与黑暗的颠覆很快在其队伍中扎根，而达索汉和最狂热的信徒则将壁炉谷作为了十字军的坚固堡垒。"}},faq={{q="现在是谁在控制玛登霍尔德城堡？",a="这座城堡由血色十字军控制，是他们在西瘟疫之地的主要军事指挥中心。它直接由泰兰·弗丁大领主治理，他居住在主大厅中，周围环绕着精锐的血色十字军卫士。",al={"玛登霍尔德的领导者是谁","谁负责壁炉谷","玛登霍尔德的首领"}},{q="为什么这座要塞对提里奥·弗丁如此重要？",a="玛登霍尔德是提里奥·弗丁的祖居，也是他作为联盟圣骑士统治该地区的权力中心。他在这座城墙内抚养家人，直到他为了捍卫一位可敬的敌人而被剥夺头衔并遭到流放。",al={"提里奥与玛登霍尔德的联系","提里奥住在这里吗"}},{q="血色十字军是如何接管玛登霍尔德的？",a="在提里奥被流放以及第三次战争期间洛丹伦陷落后，提里奥之子泰兰放弃了白银之手，加入了血色十字军，从此城堡及其驻军开始为十字军效力。",al={"血色十字军如何占领壁炉谷","为什么血色十字军在这里"}},{q="玩家可以安全进入玛登霍尔德城堡吗？",a="不能。血色十字军认为所有外来者都是潜在的瘟疫携带者或他们事业的敌人。任何靠近城堡的冒险者都会被立即攻击，除非通过强大的幻象魔法进行伪装。",al={"玛登霍尔德是友好的吗","联盟可以进入玛登霍尔德吗","部落可以进入玛登霍尔德吗"}}},fp="16,163,21.520.0,21.269.1,40.191.0,53.219.0,50.185.0,42.184.0"}
P.entries["subzone:marris-stead"] = {n="玛瑞斯农场",s="玛瑞斯农场坐落在东瘟疫之地西南部的一座山脊上，曾是洛丹伦一处宁静的宅邸。在第三次战争的浩劫过后，它现在成了被遗忘者勇士纳萨诺斯·凋零者那座孤寂且防守严密的堡垒。",h="玛瑞斯农场坐落在东瘟疫之地西南部的一座山脊上，曾是洛丹伦一处宁静的宅邸。在第三次战争的浩劫过后，它现在成了被遗忘者勇士纳萨诺斯·凋零者那座孤寂且防守严密的堡垒。",kw={"凋零犬","东瘟疫之地","玛瑞斯农场","纳萨诺斯","纳萨诺斯·凋零者","纳萨诺斯·玛瑞斯","拉姆斯登","军情七处"},ang={["faction:Alliance"]="由于军情七处的特工失踪，这个由被遗忘者把持的农场成了联盟调查员在瘟疫之地的一个令人不安的焦点。",["faction:Horde"]="对于被遗忘者及其部落盟友来说，这个农场是他们与天灾军团和血色十字军作战时不可或缺的、防守严密的作战基地。"},sec={{t="游侠破碎的家园",b="在第三次战争之前，这座农场属于纳萨诺斯·玛瑞斯，他是一位著名的人类神射手，也是唯一被远行者接纳的人类游侠领主。当斯坦索姆陷落，天灾军团横扫洛丹伦时，恐怖的憎恶拉姆斯登在纳萨诺斯的家中将其逼入绝境并残忍杀害。他被复活成为效忠于巫妖王的无脑傀儡，但后来被希尔瓦娜斯·风行者亲手解放，摆脱了天灾军团的控制，并在被遗忘者中占据了一席之地。"},{t="勇士的堡垒",b="如今，这位勇士自称为纳萨诺斯·凋零者，带着一群凶猛的凋零犬回到了他祖辈的农场。在女妖之王的命令下，他协调着瘟疫之地各处的打击行动，矛头直指天灾军团和血色十字军。这座农场也引起了暴风城情报部门阴森的注视：被派往此处调查被遗忘者活动的军情七处特工遭到了屠杀，这促使联盟发现了纳萨诺斯那可怕的转变，并对他发出了高额悬赏。"}},faq={{q="谁住在玛瑞斯农场？",a="这座农场目前被纳萨诺斯·凋零者所占据。他与他的凋零犬群居住于此，作为前线指挥官和女妖之王的勇士在此驻守。",al={"谁在玛瑞斯农场","谁住在这里","农场的非玩家角色","纳萨诺斯的位置"}},{q="纳萨诺斯是如何成为亡灵的？",a="第三次战争期间，天灾军团蹂躏了洛丹伦，将许多受害者复活为亡灵。纳萨诺斯的个人经历以及他如何摆脱天灾军团的控制，在相关部分有详细介绍。",al={"纳萨诺斯是怎么死的","纳萨诺斯之死","谁杀了纳萨诺斯"}},{q="联盟为何对这个农场感兴趣？",a="军情七处军情大师马迪亚斯·肖尔收到了关于被遗忘者异常活动的干扰报告，并派遣特工前去调查。当只有一名特工返回后，联盟又派遣了更多的调查员去探明其他人的下落。",al={"联盟与玛瑞斯农场","军情七处瘟疫之地","为什么要杀纳萨诺斯"}}},fp="12,180,22.403.1,22.458.1,26.140.0,31.180.0,44.209.1"}
P.entries["subzone:marshal-s-refuge"] = {n="马绍尔营地",s="马绍尔营地是安戈洛环形山北侧悬崖上一个摇摇欲坠的中立避难所。它由威利德·马绍尔及其探险队建立，在盆地中的原始野兽摧毁了他们低处的营地后，这里成为了应急的堡垒。",h="马绍尔营地是安戈洛环形山北侧悬崖上一个摇摇欲坠的中立避难所。它由威利德·马绍尔及其探险队建立，在盆地中的原始野兽摧毁了他们低处的营地后，这里成为了应急的堡垒。",kw={"洞穴","探险队","霍兰妮","马绍尔营地","安戈洛环形山","威利德·马绍尔"},ang={["class:Hunter"]="营地高悬在火山口地面之上，为猎人们提供了一个有利位置，使他们能在进入追踪区域前，深入研究安戈洛最稀有、最致命的野兽。",["race:Gnome"]="侏儒学者和现场工程师们发现，营地是一个理想的前哨站，可以用来测试在环形山奇异的能量水晶和不稳定的喷泉上使用的各种仪器。"},sec={{t="险峻的栖身之所",b="当威利德·马绍尔和霍兰妮·马绍尔带领探险队进入安戈洛环形山时，他们严重低估了这里史前生物的凶猛程度。在最初的基地营地屡次被横冲直撞的野兽摧毁后，伤痕累累的幸存者爬上了北部洞穴密布的悬崖，才得以逃脱屠戮。重整旗鼓后，这里被称为马绍尔营地，高悬在丛林地面之上，为安戈洛环形山北部的疲惫探险者提供了唯一稳定的休息点、基础补给和飞行管理员。"},{t="好奇心的交汇点",b="由于安戈洛环形山拥有古老的生物奇观和神秘的水晶构造，马绍尔营地吸引了一群形形色色的研究者、寻宝者和古怪的流浪者。来自各地的博物学家，包括矮人学者和侏儒技师，与幸存的马绍尔探险队员们共享着这片拥挤的崖架。以此为据点，侦察兵们向火羽山这样的火山峰顶，或葛拉卡温泉那样的沸腾地标进发，希望能在被这片原始荒野吞噬前将其记录在册。"}},faq={{q="为什么马绍尔营地要建在悬崖那么高的地方？",a="马绍尔探险队最初在盆地低处建立了营地，但安戈洛凶猛的恐龙和极具攻击性的生物不断践踏并摧毁了这些营地。幸存者们撤退到了北部的岩壁上，以此获得了一个安全且易守难攻的制高点，避开了大型野兽的威胁。",al={"为什么它在洞穴里","马绍尔营地位置","为什么建在悬崖边"}},{q="马绍尔营地对部落和联盟都友好吗？",a="是的。它作为一个中立前哨站运作。安戈洛环形山的原始危机使得阵营对抗成为一种无法承担的奢侈，因此双方阵营的成员在此和平共处，进行补给和学术交流。",al={"马绍尔营地是中立的吗","部落可以去这里吗","联盟可以去这里吗"}},{q="谁在领导这个营地？",a="这个前哨站由威利德·马绍尔和霍兰妮·马绍尔领导，他们正是组织了那次命运多舛的安戈洛环形山马绍尔探险队的领头人。",al={"谁在负责","谁经营马绍尔营地","营地领袖"}},{q="营地提供哪些服务？",a="该营地在偏远的盆地中提供基本的生存必需品，包括为两个阵营提供服务的飞行管理员、基础贸易商人、修理服务，以及供研究者交流情报、悬赏任务和环形山调查工作的聚集点。",al={"飞行路线","修理","商人"}}},fp="16,181,18.389.0,25.391.0,52.207.0,56.115.0,25.119.0,42.161.0"}
P.entries["subzone:marshlands"] = {n="沼泽地",s="沼泽地是一片广阔且潮湿的湿地，占据了安戈洛环形山东南部的区域。它位于从塔纳利斯蜿蜒而下的斜坡尽头，往往是新来者进入这片原始盆地时见到的第一处荒野。",h="沼泽地是一片广阔且潮湿的湿地，占据了安戈洛环形山东南部的区域。它位于从塔纳利斯蜿蜒而下的斜坡尽头，往往是新来者进入这片原始盆地时见到的第一处荒野。",kw={"蓝色能量水晶","沼泽地","莫维克","迅猛龙","拉瓦萨龙","塔纳利斯","托尔瓦·寻路者","安戈洛"},ang={["class:Hunter"]="沼泽地是检验荒野生存能力的试金石，这里遍布着敏捷的迅猛龙、剧毒的掠食者，还有像托尔瓦·寻路者这样经验丰富的追踪者所指引的罕见野兽。",["profession:Herbalism"]="沼泽的北缘被具有攻击性的血瓣花幼苗和潮湿的植被所覆盖，是观察敌对、可移动植物生命的绝佳地点。"},sec={{t="通往环形山的大门",b="从塔纳利斯的干旱地带沿着陡峭的小径向下，旅行者会直接进入沼泽地潮湿的泥沼中。安戈洛环形山的其他区域边缘都是绝壁，攀爬极易坠亡，这使得这片险恶的湿地成为了进入安戈洛的主要通道。茂密的植被、积水和泥地里潜伏着大量凶猛的迅猛龙，其中还包括在芦苇丛中潜行的剧毒品种。在潮湿的空地上，探险者可以发现散落在地面的蓝色能量水晶，这是该区域特有的资源。"},{t="沼泽中的营地",b="尽管时刻面临掠食者的威胁，几位孤独的荒野专家仍在这里维持着据点。牛头人猎人托尔瓦·寻路者驻扎在一处显眼的土丘上，观察着此地的原始生物。在湿地的另一端，巨魔莫维克正在研究和训练当地的拉瓦萨龙。"}},faq={{q="为什么沼泽地通常是人们进入安戈洛后看到的第一片区域？",a="安戈洛环形山四周环绕着陡峭的悬崖，除了塔纳利斯的东南通道外，从其他任何地点进入几乎都会导致死亡。这条坡道直通沼泽地，迫使所有陆路旅行者必须穿过这片潮湿的区域。",al={"如何进入安戈洛","进入安戈洛环形山","沼泽地入口"}},{q="这里最常见的生物是什么？",a="这片沼泽以拥有大量迅猛龙而闻名。其中包括普通的狩猎型迅猛龙和致命的剧毒品种，它们能够在茂密的灌木丛中对粗心的探险者发起围攻。",al={"沼泽地野兽","沼泽地迅猛龙","这里有什么生物"}},{q="沼泽地里能找到什么独特的资源？",a="沼泽地是安戈洛环形山中唯一自然形成蓝色能量水晶的地方。这些发光的矿石碎片受到那些研究散布在盆地各处的神秘水晶塔的学者们的珍视。",al={"蓝色能量水晶","沼泽地水晶","安戈洛蓝色水晶"}},{q="托尔瓦·寻路者是谁？",a="托尔瓦·寻路者是一位经验丰富的牛头人猎人，驻扎在沼泽地内的一座高土丘上。他观察着环形山的生态系统，并指引有能力的冒险者对抗安戈洛最凶猛的野兽。",al={"托尔瓦","托尔瓦·寻路者营地"}},{q="这里的拉瓦萨龙可以被驯服或训练吗？",a="可以。住在沼泽地的巨魔莫维克专门负责处理和饲养当地的拉瓦萨龙，他能提供关于这些生物攻击性本能和习性的深刻见解。",al={"拉瓦萨龙训练师","莫维克","训练拉瓦萨龙"}}},fp="10,183,21.310.0,22.253.0,67.208.0,36.96.0,50.157.0,24.105.0,43.90.0"}
P.entries["subzone:mast-room"] = {n="Mast Room",s="Mast Room是一处巨大的地下伐木场，深藏于死亡矿井之中。这里由地精工头斯尼德及其木匠负责监管，专门加工从西部荒野掠夺来的木材。",h="Mast Room是一处巨大的地下伐木场，深藏于死亡矿井之中。这里由地精工头斯尼德及其木匠负责监管，专门加工从西部荒野掠夺来的木材。",kw={"死亡矿井","地精木匠","伐木场","桅杆室","收割机","斯尼德"},ang={["faction:Alliance"]="在这个洞穴中加工的木材表明，迪菲亚在西部荒野的劫掠并非简单的土匪行径，而是一场协调一致的工业生产行动。",["profession:Engineering"]="斯尼德在洞穴中操作的地精收割机是原始蒸汽与齿轮技术的奇迹，它原本用于森林伐木，如今被改装用来碾碎入侵者。"},sec={{t="地下锯木厂",b="穿过死亡矿井深处的矿道，便可抵达Mast Room。这是一个巨大的洞穴，已被改建成了一座功能齐全的伐木场。堆积如山的木材、锯末以及巨大的切割设备充斥着整个空间。地精木匠们正是在这里加工制造巨大的桅杆、龙骨和木板，以组装隐藏在铁甲湾深处的巨型战舰。在斯尼德的严密监视下，迪菲亚潜行者将西部荒野砍伐的木材转化为战争机器的零件。"},{t="工业劳作",b="这个洞穴展示了地精工业最冷酷的一面。斯尼德坐在一台机械收割机上监督生产，确保木匠们完成繁重的配额。巨大的圆木被源源不断地吊起并刨平，将曾经死寂的金矿变成了一个轰鸣作响、烟尘弥漫的造船厂。"}},faq={{q="为什么地下矿井里会有伐木场？",a="迪菲亚潜行者正在秘密建造一艘巨大的战舰，位置就在矿井下方的海湾里。桅杆室作为该船只的桅杆、骨架和船壳板的组装与塑形场所，所用的木材均是从西部荒野地表走私而来的。",al={"为什么这里有木材","为什么死亡矿井里有木头","桅杆室的用途"}},{q="谁负责管理桅杆室？",a="这个洞穴由斯尼德负责监管，他是一位地精工艺大师，在驾驶致命的机械伐木机指挥地精木匠们工作。",al={"桅杆室的首领","谁领导桅杆室","斯尼德是谁"}},{q="为什么地精会为迪菲亚效力？",a="艾德温·范克里夫雇佣了地精工程师和工匠，以提供人类石匠所缺乏的技术专长。地精们用重型机械、爆炸物和造船技术来换取金钱和利润。",al={"为什么地精在死亡矿井","迪菲亚地精"}}},fp="9,111,23.340.1,16.271.1,54.183.1,23.102.0,44.182.1"}
P.entries["subzone:master-s-cellar"] = {n="主宰的庇护所",s="主宰的庇护所是一处庞大的地下建筑群，位于逆风小径中卡拉赞南部的废弃定居点下方。这里曾是麦迪文庄园的酒窖和储藏室，如今已沦为一座闹鬼的废墟，到处都是昔日仆人和看守者那不安的幽灵。",h="主宰的庇护所是一处庞大的地下建筑群，位于逆风小径中卡拉赞南部的废弃定居点下方。这里曾是麦迪文庄园的酒窖和储藏室，如今已沦为一座闹鬼的废墟，到处都是昔日仆人和看守者那不安的幽灵。",kw={"逆风小径","卡拉赞","下层地窖","主宰的庇护所","麦迪文","不死的看守者"},ang={["class:Mage"]="守护者庄园下方徘徊的幽灵遗迹证明了麦迪文倒下时所引发的严重奥术反噬，将普通的家政储藏室变成了一处挥之不去的幽灵能量枢纽。",["class:Priest"]="被困在潮湿地窖中的受折磨的幽灵，是那些普通的看守者和仆人的悲惨灵魂，他们因逆风小径上挥之不去的诅咒而无法获得安宁。"},sec={{t="卡拉赞闹鬼的腹地",b="在宏伟的卡拉赞高塔以南，坐落着一片废弃村落的遗迹，这里曾住着维护麦迪文庄园的仆人、园丁和侍从。主宰的庇护所就位于这些坍塌房屋的下方。该建筑群可以通过地表废墟中的两个独立入口进入，并在地下向远处延伸。一个入口通向宽敞的拱顶酒窖，另一个则穿过坍塌的石块，通往深邃的天然洞穴。无论卡拉赞及其主人遭遇了怎样的黑暗结局，这片地下室也未能幸免，昔日的看守者化作了不死生物，哀嚎的幽灵和受诅咒的灵魂被困在这里，永世不得解脱。"},{t="下层洞穴",b="该建筑群的最深处被称为下层地窖，这里展示了地窖地板如何塌陷进逆风小径的天然岩层中。地窖的地基坍塌进了这些洞穴系统，形成了一座回荡着鬼哭狼嚎的崎岖迷宫。虽然探索小径的冒险者在这里几乎找不到活人，但从附近高塔渗出的弥漫性魔法腐蚀已将这些幽灵牢牢地束缚在岩石上，使得这些洞穴与上方的废墟一样危险。"}},faq={{q="主宰的庇护所最初的用途是什么？",a="它曾是卡拉赞高塔的主要储藏室和酒窖。上方的村庄安置着负责维护守护者麦迪文庞大家产的家政人员和园丁，他们利用这些地下金库来存放物资和陈年酒桶。",al={"主宰的庇护所的用途","这是什么地窖","为什么这里有酒窖"}},{q="为什么地窖里到处都是幽灵？",a="没有人确切知道他们遭遇了什么。无论卡拉赞及其主人遭遇了怎样的黑暗命运，这片村落也未能幸免，曾经居住在那里的仆人和村民如今化作了不安的暗影、哀嚎的幽灵和不死的看守者，在废墟中徘徊。",al={"为什么有幽灵","地窖里的不死生物是谁","为什么主宰的庇护所会闹鬼"}},{q="如何进入地窖下方的洞穴系统？",a="在卡拉赞南部的废墟建筑中，有两个不同的地窖入口。东侧的入口通向结构完整的酒窖，而西侧的入口则通向一段坍塌的石工结构，由此可以进入下层地窖的天然地下洞穴。",al={"如何进入下层地窖","主宰的庇护所入口","洞穴入口在哪里"}},{q="主宰的庇护所与卡拉赞内部直接相连吗？",a="不。尽管它靠近高塔底部，并且在历史上承担着为守护者庄园提供物资的任务，但这些地下房间并没有通往卡拉赞内部的通道。地窖依然是独立存在于村庄废墟之下的。",al={"主宰的庇护所通向卡拉赞吗","从地窖进入卡拉赞的入口"}}},fp="15,188,30.452.0,17.387.0,49.203.0,33.229.0,52.213.0,70.178.0"}
P.entries["subzone:master-s-glaive"] = {n="主宰之剑",s="主宰之剑是一处古老且令人不安的地标，位于黑海岸西南部，一把巨大的精金武器深深地插在一个巨大的石化头骨中。长期以来，当地的暗夜精灵一直将其视为神圣的谜团，而现在，受某种古老实体残留的邪恶力量吸引，暮光之锤的邪教徒们蜂拥至此。",h="主宰之剑是一处古老且令人不安的地标，位于黑海岸西南部，一把巨大的精金武器深深地插在一个巨大的石化头骨中。长期以来，当地的暗夜精灵一直将其视为神圣的谜团，而现在，受某种古老实体残留的邪恶力量吸引，暮光之锤的邪教徒们蜂拥至此...",kw={"黑海岸","主宰之剑","上古之神","暮光之锤"},ang={["race:NightElf"]="几代以来，暗夜精灵一直将这座奇怪的石化纪念碑视为神圣的场所，因此暮光之锤邪教最近的入侵是对黑海岸这片神圣土地令人无法容忍的亵渎。"},sec={{t="古代冲突的纪念碑",b="主宰之剑从黑海岸的土地上拔地而起，那是一把巨大的精金之刃，深深地埋在一个巨大的石化头骨中。没有任何记录记载死在这里的生物，也没有记录记载是谁将这把利刃插入其中。知识古树欧努只说，一位古老得可怕的大地之主倒在了这里，而暗夜精灵们长期以来一直认为，只有泰坦才能挥舞如此巨大的武器。今天，这块被贯穿的巨石作为那场被遗忘的斗争的见证，矗立在那里，成为一座石化的纪念碑。"},{t="黑暗发掘",b="虽然这个地点几代以来一直受到暗夜精灵的肃穆崇敬，但最近邪恶势力占领了这里。暮光之锤邪教的狂热分子在沉没的尸骸周围建立了营地，开凿出战壕，并挖掘出石化的肋骨。受到石头下方低语的吸引，邪教徒们痴迷地研究着这些遗骸，并与仍然依附在这些古老残骸上的邪恶力量进行沟通，试图复活或利用沉睡在大地之中的某种邪恶本质。"}},faq={{q="插在头骨上的巨型武器是什么？",a="没人能确定。那把巨大的精金之刃正是主宰之剑本身，它是在某个被遗忘的时代被插入头骨之中的。暗夜精灵们相信，只有泰坦才能挥舞如此巨大尺寸的武器。",al={"主宰之剑是什么","主宰之剑","谁把剑插在那里的"}},{q="这里埋着什么生物的头骨？",a="它的名字已经失传了。知识古树欧努只说，一位古老得可怕的大地之主倒在了这里，而暮光之锤相信这些石化的遗骸属于上古之神的仆从。",al={"什么生物死在这里","主宰之剑下埋葬的是谁"}},{q="暮光之锤邪教为什么聚集在这里？",a="暮光之锤邪教崇拜上古之神。他们占领了主宰之剑并开始挖掘那些石化的遗骸，因为受到了残留的黑暗力量的吸引，并希望让那个倒下的生物复活。",al={"邪教徒为什么在这里","黑海岸的暮光之锤","邪教徒在挖掘什么"}},{q="谁了解这个地点的历史？",a="居住在黑海岸的知识古树欧努认出这里是一位古老的大地之主的安息之地，并指示调查者们去一探究竟。",al={"谁在研究主宰之剑"}}},fp="15,207,30.379.0,16.380.0,46.196.0,37.196.0,48.216.0,41.148.0"}
P.entries["subzone:maul-subzone"] = {n="Maul (subzone)",s="巨槌竞技场是一座位于菲拉斯的厄运之槌遗迹外破碎平原中的下沉式角斗场。这里曾是古老的暗夜精灵城市埃雷萨拉斯的宏伟场地，如今却变成了一个无法无天的血腥运动场，流浪者们在此为了荣耀或生存，与凶猛的野兽和敌对的勇士厮杀。",h="巨槌竞技场是一座位于菲拉斯的厄运之槌遗迹外破碎平原中的下沉式角斗场。这里曾是古老的暗夜精灵城市埃雷萨拉斯的宏伟场地，如今却变成了一个无法无天的血腥运动场，流浪者们在此为了荣耀或生存，与凶猛的野兽和敌对的勇士厮杀。",kw={"破碎平原","厄运之槌竞技场","埃雷萨拉斯","菲拉斯","自由混战玩家对战","穆什戈格","不可撼动者斯卡尔","巨槌竞技场","拉扎"},ang={["class:Warrior"]="对于那些在有组织的战场之外寻求纯粹战斗的战士来说，巨槌竞技场提供了原始、未经修饰的血腥运动，只有个人的实力和坚硬的护甲才能决定生死。",["race:NightElf"]="看着古老埃雷萨拉斯骄傲的建筑被贬为食人魔出没的处决坑，这令人痛苦地回想起上层精灵文明已经没落到了何种地步。"},sec={{t="沉没的深坑",b="巨槌竞技场深凿于破碎平原的岩石之中，曾作为埃雷萨拉斯的上层精灵的剧院或仪式竞技场。在大分裂之后，随着戈多克食人魔的入侵，这里沦为了一个野蛮的角斗场。就像远在荆棘谷臭名昭著的古拉巴什竞技场一样，一旦踏入巨槌竞技场的沙地，所有的效忠关系都会被暂停，战斗者被卷入一场无法无天的混战，派系界限荡然无存，生存完全取决于个人的武力。"},{t="野兽与杀戮",b="进入竞技场的挑战者必须谨慎行事。虽然勇敢的斗士经常从平原的高处直接跳下，但坠落会造成巨大的伤害。从西侧的拱门穿过隧道是更安全的选择，那里有沉睡的戈多克鬣狗，这也是离开竞技场地面唯一的步行出口。危险的野兽和臭名昭著的角斗士会不定期地出现在坑中，使每一次进入都成为对钢铁意志和本能的不可预测的考验。"}},faq={{q="为什么我可以在这里攻击我同阵营的成员？",a="巨槌竞技场是一个无法无天的战斗坑，就像荆棘谷的古拉巴什竞技场一样。当你踏入它的沙地时，标准的阵营条约和停火协议将不再适用，这会将战斗者标记为可以与非队友的任何人进行混战。",al={"自由混战玩家对战 厄运之槌","自由混战竞技场","为什么我可以攻击部落"}},{q="我该如何安全地进出巨槌竞技场？",a="虽然你可以直接从破碎平原跳下去，但这样会造成严重的坠落伤害。最安全的路径是穿过平原西侧的一道拱门，沿着隧道绕过沉睡的戈多克鬣狗。这条隧道也是步行攀爬出来的唯一途径。",al={"如何进入巨槌竞技场","巨槌竞技场入口","离开巨槌竞技场"}},{q="竞技场里会出现什么样的敌人？",a="除了敌对的冒险者之外，据闻还有异域且凶残的威胁会潜入竞技场坑中，包括巨大的真菌巨人穆什戈格、被称为“拉扎”的奇美拉，以及凶猛的角斗士“不可撼动者”斯卡尔。",al={"竞技场稀有精英","巨槌竞技场刷新怪物","巨槌竞技场首领"}},{q="这个竞技场最初是做什么用的？",a="在大分裂破碎古老的卡利姆多之前，这座石制角斗场属于伟大的上层精灵城市埃雷萨拉斯。入侵的戈多克食人魔将这座古老的精灵建筑改造成了适合他们野蛮口味的血腥竞技场。",al={"巨槌竞技场背景","谁建造了巨槌竞技场","埃雷萨拉斯竞技场"}}},fp="14,176,14.364.0,20.348.0,48.191.0,41.188.0,42.157.0,40.167.0"}
P.entries["subzone:mazthoril"] = {n="麦索瑞尔",s="麦索瑞尔是一座位于冬泉谷中心地带的巨大冰封洞穴，它是蓝龙军团在卡利姆多北部的核心据点。洞穴由龙人、施法巨龙和奥术哨兵重重把守，蜿蜒的冰冻隧道中隐藏着强大的魔法，并通往隐居的蓝龙族母海蕾的巢穴。",h="麦索瑞尔是一座位于冬泉谷中心地带的巨大冰封洞穴，它是蓝龙军团在卡利姆多北部的核心据点。洞穴由龙人、施法巨龙和奥术哨兵重重把守，蜿蜒的冰冻隧道中隐藏着强大的魔法，并通往隐居的蓝龙族母海蕾的巢穴。",kw={"蓝龙军团","科尔巴坦","海蕾","玛里苟斯","麦索瑞尔","奥妮克希亚钥匙","斯佩尔莫","冬泉谷"},ang={["class:Mage"]="作为玛里苟斯仆从的领域，麦索瑞尔充满了浸润在纯粹奥术能量中的生物，这使它成为了奥术学者们极为关注的地点。",["faction:Alliance"]="调查黑龙军团的联盟英雄会前往麦索瑞尔寻找族母海蕾。"},sec={{t="蓝龙的堡垒",b="麦索瑞尔开凿在永望镇南部的冰冻山脉中，栖息着一大群效忠于织法者玛里苟斯的蓝龙。洞穴及其周围的峭壁由警觉的龙人把守，包括斯佩尔莫、阿祖罗斯和科尔巴坦将军，而精锐的守卫则监视着内部洞穴。任何闯入麦索瑞尔的人都将面对完全受奥术能量浸润的龙兽，若无充分准备，深入其中将极为危险。"},{t="传送符文与族母",b="在冰封迷宫的深处，有一枚由幼龙法力之爪和斯克里尔严密看守的神奇地面符文。踏上这枚符文会将旅行者传送到洞穴上方一个孤立的山顶巢穴。蓝龙军团的族母海蕾居住于此，并维持着高等精灵的伪装。尽管海蕾对凡人天生保持警惕，但她拥有关于龙族血统的深厚知识，并在破解保护奥妮克希亚的巢穴的隐藏结界中扮演着关键角色。"}},faq={{q="谁统治着麦索瑞尔？",a="麦索瑞尔由强大的蓝龙族母海蕾管辖。她居住在洞穴建筑群上方高处的孤立巢穴中，只能通过位于隧道深处的魔法传送符文进入。当她接待凡人访客时，会幻化成一位高等精灵女性的形象。",al={"谁领导麦索瑞尔","麦索瑞尔的首领是谁","麦索瑞尔族母"}},{q="为什么蓝龙会居住在冬泉谷？",a="蓝龙军团受泰坦委派守护艾泽拉斯的奥术魔法，他们密切监视着世界各地残留的古老能量之源。冬泉谷拥有凯斯利尔湖周围上层精灵古老文明的遗迹，这使得麦索瑞尔成为他们哨兵在卡利姆多的天然据点。",al={"为什么冬泉谷有龙","为什么蓝龙军团在这里","冬泉谷的玛里苟斯龙群"}},{q="如何到达海蕾那里？",a="要到达海蕾那里，你必须在麦索瑞尔内部洞穴中杀出一条血路，穿过重重龙人。在那里，在幼龙法力之爪和斯克里尔的侧翼护卫下，地面上有一枚发光的奥术符文。踏入符文中心即可将你传送到她位于山顶的高处栖息地。",al={"到达海蕾","找到海蕾","传送到海蕾处","海蕾在哪里"}},{q="麦索瑞尔在进入奥妮克希亚的巢穴中扮演什么角色？",a="正在调查奥妮克希亚保护结界的联盟英雄会被派去咨询海蕾。她在这一旅程中的作用将在受保护的部分进行探讨。",al={"奥妮克希亚钥匙麦索瑞尔","奥妮克希亚开门任务海蕾","龙火护符海蕾"}}},fp="9,230,25.404.0,40.419.1,20.232.0,44.319.0,23.215.0,56.151.2"}
P.entries["subzone:menethil-bay"] = {n="米奈希尔海湾",s="米奈希尔海湾是湿地西海岸一片受庇护的水域，坐落在米奈希尔港和丹莫罗北部的陡峭悬崖之间。这片水域向外通往更广阔的巴拉丁海湾，栖息着凶猛的鳄鱼，还有沉船的残骸。这里是联盟往返于东部王国和卡利姆多之间的主要海上航道。",h="米奈希尔海湾是湿地西海岸一片受庇护的水域，坐落在米奈希尔港和丹莫罗北部的陡峭悬崖之间。这片水域向外通往更广阔的巴拉丁海湾，栖息着凶猛的鳄鱼，还有沉船的残骸。这里是联盟往返于东部王国和卡利姆多之间的主要海上航道。",kw={"巴拉丁海湾","鳄鱼","丹莫罗","飞鹰号","米奈希尔海湾","米奈希尔港","湿地"},ang={["faction:Alliance"]="米奈希尔海湾是通往米奈希尔港的重要海上通道，保障了连接铁炉堡、暴风城与卡利姆多之间脆弱的海上航线。"},sec={{t="湿地的庇护水域",b="作为无尽之海沿岸更广阔的巴拉丁海湾的一部分，米奈希尔海湾形成了一个天然的入口，北接米奈希尔港，东临黑水沼泽，南靠丹莫罗高耸的海岸断崖。其浅滩边缘和沼泽海岸爬满了各种年龄和体型的鳄鱼，使得这些浅水区对于没有向导的旅行者来说危机四伏，尽管该海湾是联盟海上交通的命脉。在海湾入口附近躺着飞鹰号的残骸，无声地提醒着人们水面下潜藏的危险。"}},faq={{q="米奈希尔海湾具体在哪里？",a="米奈希尔海湾位于湿地的西海岸。它坐落在巴拉丁海湾更广阔的区域内，北侧是米奈希尔港，东侧是黑水沼泽，南侧是丹莫罗北部的山崖。",al={"米奈希尔海湾在哪里","米奈希尔海湾位置","湿地海湾"}},{q="米奈希尔海湾里生活着什么生物？",a="海湾的沼泽海岸和浅水入口栖息着大量各种体型的鳄鱼。它们以伏击毫无防备的游泳者而闻名，经常被寻找珍贵毛皮的制皮师猎杀。",al={"米奈希尔海湾怪物","海湾里有什么","米奈希尔海湾的鳄鱼"}},{q="海湾里的沉船是什么？",a="位于米奈希尔海湾入口附近的残骸属于飞鹰号，这是一艘沉没在港口航道附近沿海水域的船只。",al={"米奈希尔海湾沉船","飞鹰号","湿地沉船"}},{q="为什么这个海湾对联盟很重要？",a="该海湾庇护着米奈希尔港，这是连接铁炉堡和卡兹莫丹北部土地与卡利姆多及南方的主要海军门户。往返于塞拉摩和黑海岸的运输船必须经过这片水域。",al={"米奈希尔海湾的重要性","湿地的联盟港口","米奈希尔港水域"}}},fp="12,254,32.406.0,38.187.0,36.168.0,35.123.0,41.215.0"}
P.entries["subzone:menethil-harbor"] = {n="米奈希尔港",s="米奈希尔港是一座戒备森严的矮人港口城镇，坐落在湿地西海岸外的一座岛屿上。它以泰瑞纳斯·米奈希尔二世国王的名字命名，是连接东部王国与遥远的卡利姆多大陆的主要海上生命线。在巨大的石质城墙和米奈希尔城堡坚固塔楼的庇护下，这里成为了商人们、休假的士兵们以及粗犷冒险者们熙熙攘攘的中心。",h="米奈希尔港是一座戒备森严的矮人港口城镇，坐落在湿地西海岸外的一座岛屿上。它以泰瑞纳斯·米奈希尔二世国王的名字命名，是连接东部王国与遥远的卡利姆多大陆的主要海上生命线。在巨大的石质城墙和米奈希尔城堡坚固塔楼的庇护下，这里成...",kw={"奥伯丁","船","深水","码头","渡轮","港口","米奈希尔","斯托菲","塞拉摩","湿地"},ang={["faction:Alliance"]="对于任何向西旅行的联盟旅者来说，米奈希尔港是至关重要的中转站，也是连接东部王国与塞拉摩的唯一海上桥梁。",["race:Dwarf"]="虽然冠以人类国王的名字，但这处港口主要由矮人的石艺建筑维护，并由把守着卡兹莫丹外部防线的铁炉堡卫兵驻守。"},sec={{t="一座堡垒避风港",b="为了向洛丹伦的泰瑞纳斯·米奈希尔二世国王致敬，米奈希尔港成为了联盟在湿地海岸的一座重要避风港。尽管地处偏远的沼泽地带，它依然是一座防守严密的堡垒，有着巨大的城墙、一条连通的栈桥，以及米奈希尔城堡的四座石质瞭望塔的加固。"},{t="横跨无尽之海的门户",b="如今，这座港口是联盟的交通大枢纽。船只不断地横跨大洋，驶向尘泥沼泽的塞拉摩岛，或是经由南海镇前往黑海岸的奥伯丁，运载着贸易物资、外交官，以及在深水旅店挥霍薪水的休假库尔提拉斯海军陆战队士兵。然而，这里的和平十分脆弱：通往丹奥加兹的内陆补给线经常受到龙喉氏族的袭扰，而北面沼泽地带潜伏的黑铁矮人突袭者也给港口带来了巨大压力，这使得斯托菲队长和港口守卫队必须时刻保持警惕。"}},faq={{q="米奈希尔港的船只驶向哪里？",a="从米奈希尔港码头出发的船只将横跨无尽之海前往卡利姆多大陆。定期的客轮不仅有前往尘泥沼泽塞拉摩岛的航线，还会向北前往希尔斯布莱德丘陵的南海镇，并从那里继续航行至暗夜精灵的避风港奥伯丁。",al={"米奈希尔港船只","船去哪里","米奈希尔渡轮","卡利姆多船只"}},{q="谁在统治米奈希尔港？",a="米奈希尔港是以铁炉堡为权威的联盟定居点。斯托菲队长指挥着城镇守卫队，并负责米奈希尔城堡的港口防务工作，保护码头免受沼泽野兽、叛逃兽人以及内陆突袭者的侵扰。",al={"谁负责米奈希尔","米奈希尔港领导者","谁领导米奈希尔"}},{q="为什么这座城镇被命名为米奈希尔？",a="这座港口是以洛丹伦的泰瑞纳斯·米奈希尔二世国王的名字命名的，他的领导力将人类、矮人和精灵王国联合成了最初的洛丹伦联盟。",al={"为什么叫米奈希尔港","米奈希尔名字由来","谁是米奈希尔"}},{q="这座港口目前面临着哪些威胁？",a="港口面临着潜伏在湿地丘陵中的龙喉氏族持续不断的威胁，他们经常试图切断通往丹奥加兹的通道，以切断港口的增援。北面靠近丹莫德的黑铁矮人入侵以及四处游荡的迅猛龙也让守卫们倍感头疼。",al={"米奈希尔港有危险吗","米奈希尔威胁","湿地兽人米奈希尔"}}},fp="15,231,17.271.0,28.461.0,46.233.0,26.238.0,31.168.0,44.244.0"}
P.entries["subzone:menethil-keep"] = {n="米奈希尔城堡",s="米奈希尔城堡是矗立在湿地米奈希尔港天际线上的石质要塞。它以四座坚固的瞭望塔为标志，是这座联盟港口的行政中心和防御堡垒，当地民兵指挥官斯托菲队长就在此坐镇。",h="米奈希尔城堡是矗立在湿地米奈希尔港天际线上的石质要塞。它以四座坚固的瞭望塔为标志，是这座联盟港口的行政中心和防御堡垒，当地民兵指挥官斯托菲队长就在此坐镇。",kw={"斯托菲队长","米奈希尔港","米奈希尔城堡","民兵","塔楼","湿地"},ang={["faction:Alliance"]="对于乘坐船只从卡利姆多抵达，或向北前往铁炉堡和阿拉希的联盟旅行者来说，米奈希尔城堡是确保这一重要交通枢纽安全的主要军事要塞。"},sec={{t="港口堡垒",b="米奈希尔城堡高耸于湿地的木制码头和泥泞沼泽之上，是米奈希尔港的核心军事据点。凭借四座俯瞰全镇与海湾的石质瞭望塔，这座要塞拥有绝佳的视野，可以抵御海上的掠夺者、叛军以及不断侵蚀周边的沼泽野兽。在城堡内部，斯托菲队长负责监管港口的防御工作，指挥城镇民兵并组织巡逻队，以保卫联盟在该地区的利益。"}},faq={{q="米奈希尔城堡有什么用？",a="米奈希尔城堡是米奈希尔港城镇民兵的总部，也是联盟在湿地的主要指挥哨所。斯托菲队长在这座石墙内指挥当地驻军，负责调度防御工作并组织冒险者解决遍布沼泽的威胁。",al={"米奈希尔城堡的用途","米奈希尔城堡的作用","这座城堡是什么"}},{q="谁负责管理米奈希尔城堡？",a="斯托菲队长指挥着这座城堡和米奈希尔民兵。他负责协调港口防御，以应对黑铁矮人掠夺者、沼泽野兽和海盗等当地威胁。",al={"谁领导米奈希尔城堡","城堡指挥官","斯托菲队长"}},{q="城堡位于哪里？",a="这座城堡坐落在湿地西海岸的米奈希尔港内，地理位置十分显眼，四座高耸的石塔直接俯瞰着整个定居点。",al={"米奈希尔城堡在哪里","米奈希尔城堡的位置","如何找到米奈希尔城堡"}}},fp="13,142,21.359.0,31.255.0,34.164.0,26.131.0"}
P.entries["subzone:merchant-coast"] = {n="商旅海岸",s="商旅海岸是贫瘠之地东部海岸线的一段，毗邻无尽之海。这里由繁忙的地精港口棘齿城占据，海岸因其繁荣的海洋贸易而得名，尽管它一直受到海盗的骚扰。",h="商旅海岸是贫瘠之地东部海岸线的一段，毗邻无尽之海。这里由繁忙的地精港口棘齿城占据，海岸因其繁荣的海洋贸易而得名，尽管它一直受到海盗的骚扰。",kw={"贫瘠之地","无尽之海","商旅海岸","棘齿城","南海海盗","热砂港"},ang={["faction:Alliance"]="联盟在附近的北方城堡保持着海军存在，密切监视着通过棘齿城的地精贸易以及沿岸横行霸道的南海海盗。",["faction:Horde"]="商旅海岸是部落在贫瘠之地通往海洋的主要商业生命线，因此保障棘齿城的安全和压制当地海盗对于地区补给线至关重要。"},sec={{t="商业与冲突的门户",b="商旅海岸沿贫瘠之地的东部边缘延伸，是连接卡利姆多中部与东部王国及塞拉摩的重要海上动脉。其名称是为了纪念热砂港勤劳的地精商人，他们建立的中立港口棘齿城为所有付得起金币的人提供货运服务。然而，广阔的海路吸引的不只是商船：南海海盗在沙滩和附近水域徘徊，掠夺商船并在沿岸建立非法营地。"}},faq={{q="为什么这里被称为商旅海岸？",a="这条海岸线因通过地精港口棘齿城进行的利润丰厚的贸易而得名。热砂港的商人将货物从这片海岸通过无尽之海运往艾泽拉斯各地的港口。",al={"商旅海岸名称由来","为什么叫商旅海岸"}},{q="商旅海岸有哪些主要定居点？",a="最显著的定居点是棘齿城，这是一座由加兹鲁维管理的中立地精港口城市。在海岸线更南端坐落着联盟的要塞北方城堡，而勇士岛则位于离岸不远处。",al={"商旅海岸上的城镇","商旅海岸有什么"}},{q="是谁在控制这一带的沙滩？",a="虽然棘齿城控制着港口本身，但南海海盗在周围的沙滩上建立了营地。这些海盗积极干扰贸易、抢劫地精车队，并挑战棘齿城的权威。",al={"商旅海岸的海盗","谁在攻击商旅海岸"}}},fp="14,136,35.310.0,36.160.0,49.176.0,37.163.0"}
P.entries["subzone:military-ward"] = {n="Military Ward",s="军事区是铁炉堡的军事核心，驻扎着城市的指挥机构、武器大师和兵营。这里悬挂着醒目的红色旗帜，矮人战士、猎人和攻城工程师与机械攻城车和飞行器一同在此进行训练。",h="军事区是铁炉堡的军事核心，驻扎着城市的指挥机构、武器大师和兵营。这里悬挂着醒目的红色旗帜，矮人战士、猎人和攻城工程师与机械攻城车和飞行器一同在此进行训练。",kw={"布里维夫·石拳","飞行机器","武器大厅","铁炉堡","军事区","蒸汽坦克","密林武器店"},ang={["class:Hunter"]="游侠和山地卫兵可以在武器大厅找到兽王和补给品，旁边还有供应弹药和装备的Goldfury's Hunting Supplies。",["class:Warrior"]="军事区是铁炉堡主要的军事枢纽，提供战士训练师、用于实战练习的训练假人以及武器大师，以扩充你的战场武器库。"},sec={{t="矮人力量之砧",b="军事区坐落在山中要塞的北侧，将铁炉堡的防御力量集中在一个繁忙的集结地。中央建筑武器大厅容纳了战士和猎人训练师、战场军官，以及存放矮人飞行器和蒸汽坦克的机库。在演武场和训练假人周围，分布着如Craghelm's Plate and Chain、Goldfury's Hunting Supplies和密林武器店等补给商店，使这里成为了山地卫兵和城市守卫的主要集结点。"},{t="战旗之下的驻地",b="与公共区的淡蓝色和Great Forge的炽热橙色不同，军事区装饰着象征军事的红色旗帜。在操练和武器检查的间隙，士兵和下班的卫兵会聚集在Bruuk's Corner喝上一杯麦芽酒，而武器大师布里维夫·石拳则在向新兵传授古老的矮人武技。"}},faq={{q="军事区是什么地方？",a="它是铁炉堡的军事区，作为矮人军队、战士和猎人训练师、武器商人和攻城器械的中央基地。",al={"军事区 铁炉堡","铁炉堡兵营","铁炉堡战士区"}},{q="我在铁炉堡哪里可以进行武器训练？",a="武器大师布里维夫·石拳驻扎在军事区的密林武器店，为联盟战士提供各种武器的训练。",al={"铁炉堡武器大师","布里维夫·石拳在哪里","学习武器铁炉堡"}},{q="武器大厅里存放着什么？",a="武器大厅作为军事指挥部，驻有战斗导师、战场军官，并设有存放蒸汽坦克和矮人飞行机的大型机库。",al={"武器大厅 铁炉堡","武器大厅里有什么","铁炉堡攻城坦克"}},{q="为什么这个区的旗帜是红色的？",a="铁炉堡的各个区域使用特定的纹章颜色以用于导航和传统；军事区悬挂着醒目的红色旗帜，代表了这座山中之城的军事力量。",al={"军事区颜色","红色旗帜铁炉堡"}}},fx={f3d6c901={q="军事区危险吗？",a="对你或任何联盟的盟友来说都不危险。军事区是整个山中城邦里防御最严密、最安全的区域之一。这里是铁炉堡军队的主要驻地和集结地，到处都是身经百战的战士、战场军官和运转中的蒸汽坦克。除非敌军攻破山门，否则这里始终处于矮人军队的完全掌控之下。",al={"军事区安全吗","军事区的危险","军事区里的危险"}},ba2db6a3={q="为什么叫军事区？",a="这个城区因其作为铁炉堡常备军指挥中心和总部的职能而得名。这里的一切都服务于战争，从武器大厅和武器店，到补给哨站，以及停放攻城器械和旋翼机的载具库，无不如此。",al={"为什么叫军事区","军事区如何得名","军事区名称由来"}}},fp="13,184,26.498.0,31.301.0,26.133.0,42.143.0,37.124.0,41.147.0"}
P.entries["subzone:mirage-flats"] = {n="雾气平原",s="雾气平原是位于荒芜之地中部荒原的一片贫瘠、被烈日灼烧的广阔地带。这片干燥的高原位于火山洞穴以东，因其闪烁的热浪和饥饿的捕食者而臭名昭著。",h="雾气平原是位于荒芜之地中部荒原的一片贫瘠、被烈日灼烧的广阔地带。这片干燥的高原位于火山洞穴以东，因其闪烁的热浪和饥饿的捕食者而臭名昭著。",kw={"荒芜之地","岩石郊狼","龙喉","火山洞穴","巨型秃鹫","雾气平原","山脊潜伏者"},ang={["class:Hunter"]="雾气平原开阔的平原提供了大量可供追踪、研究或驯服的攻击性野兽，特别是那些凶猛的山脊潜伏者和久经沙漠生存考验的强韧郊狼。"},sec={{t="焦灼的荒原",b="雾气平原位于火山洞穴以东，这片土地向旅人们展现着一片无情的、布满裂纹的红土地，以及使其得名的闪烁热浪。很少有文明种族在此驻足；相反，这片开阔的平原被伺机而动的食腐动物和致命的野兽所占据。成群的巨型秃鹫在热气流中懒散地盘旋，俯视着下方。它们在等待着凶猛的山脊潜伏者和成群结队的岩石郊狼留下的残羹剩饭，这些野兽在灌木丛中搜寻着易得的猎物。"}},faq={{q="雾气平原位于哪里？",a="平原位于荒芜之地中部，在火山洞穴以东。往返于西部悬崖和东部峡谷之间的旅行者经常会穿过这片被太阳炙烤的土地。",al={"雾气平原位置","雾气平原在哪里","雾气平原地图"}},{q="为什么这个地区叫雾气平原？",a="这个名字来源于刺眼的沙漠烈日和从平坦的岩石地面辐射出的压抑热浪，这些热浪制造了持久的视觉错觉和热晕，常常使口渴的旅行者在荒原中迷失方向。",al={"为什么叫雾气平原","雾气平原名字含义","荒芜之地热浪"}},{q="什么生物在平原上出没？",a="该地区居住着适应了严酷荒地的强韧捕食者和食腐动物。成群结队的狂犬岩石郊狼和游荡的山脊潜伏者首领在灌木丛中捕猎，而巨型秃鹫则在头顶盘旋，等待着享用任何倒在尘土中的猎物。",al={"雾气平原怪物","雾气平原有什么生物","雾气平原野兽"}}},fp="12,136,20.254.0,35.166.0,36.146.0,31.160.0"}
P.entries["subzone:mirage-raceway"] = {n="沙漠赛道",s="沙漠赛道是一处位于千针石林闪光平原上的临时工程试验场。它的诞生源于地精技师普兹克和侏儒工程师菲兹尔·铜栓之间激烈的竞争，两人的高速火箭车在干涸的土地上进行着较量。这条赛道是一个中立的聚集地，联盟和部落的成员都可以在此下注、修理机械并为他们支持的赛车加油助威。",h="沙漠赛道是一处位于千针石林闪光平原上的临时工程试验场。它的诞生源于地精技师普兹克和侏儒工程师菲兹尔·铜栓之间激烈的竞争，两人的高速火箭车在干涸的土地上进行着较量。这条赛道是一个中立的聚集地，联盟和部落的成员都可以在此下注...",kw={"菲兹尔·铜栓","沙漠赛道","普兹克","火箭车","闪光平原","千针石林"},ang={["profession:Engineering"]="对于任何阵营的技师来说，沙漠赛道代表了地精冒险精神与侏儒严谨设计之间的终极碰撞，为测试纯粹的速度、不稳定的燃料和实验性车辆部件提供了实地演练的机会。",["race:Gnome"]="菲兹尔·铜栓在此高举诺莫瑞根的旗帜，依靠同族侏儒和盟友来证明，严谨的创新可以轻松胜过鲁莽的地精燃烧技术。"},sec={{t="速度、盐地与较量",b="沙漠赛道横跨闪光平原广袤的白色荒漠，它源于两位工程大师之间旷日持久的怨恨：地精普兹克和侏儒菲兹尔·铜栓。为了彻底分出到底哪个种族拥有更卓越的工程天赋，两人制造了定制的火箭动力加速车，并招募了各自的车队，每天进行高速对决。无休止的竞争将这片荒芜的平原变成了一个充满了发明、破坏与测试的热闹中心，每一个车队都在拼命寻找任何机械上的优势。"},{t="中立的十字路口",b="这条赛道吸引了来自部落和联盟的支持者。来自卡利姆多的观众聚集在此，要么为侏儒的精密机械喝彩，要么为地精的强大火力欢呼，而赌徒和投机分子则在各种下注中获利。在火箭引擎的轰鸣声之外，这些营地也是往来于千针石林和塔纳利斯炽热沙地之间的旅行者们进行贸易的繁忙中转站。"}},faq={{q="什么是沙漠赛道？",a="沙漠赛道是一条横跨千针石林盐碱地的露天火箭车赛道。它由相互竞争的工程师建造，旨在证明地精机械和侏儒机械究竟孰优孰劣。",al={"什么是沙漠赛道","赛道目的","闪光平原赛道"}},{q="这里是谁在组织比赛？",a="这条赛道由侏儒工程师菲兹尔·铜栓和地精技师普兹克共同维护。双方都在赛道旁经营着各自的专属车队和车间，以派遣参赛的火箭车。",al={"谁领导赛道","菲兹尔与普兹克","谁建造了这条赛道"}},{q="部落和联盟都能使用这个区域吗？",a="是的。来自两个阵营的支持者都会聚集在赛道旁为他们喜爱的赛车加油、投注，并协助竞争对手的工程团队。",al={"沙漠赛道是中立的吗","联盟可以访问吗","部落可以访问吗"}},{q="为什么要在盐碱地上赛车？",a="闪光平原平坦宽阔，为需要数英里距离来达到最高时速并安全减速的火箭动力车辆提供了理想的平滑、无障碍的场地。",al={"为什么在千针石林","为什么在盐地上赛车","为什么在闪光平原"}}},fx={df07332a={q="沙漠赛道的历史是什么？",a="赛道源于地精普兹克与侏儒菲兹尔·铜栓之间激烈的技术竞争。两人决心证明各自种族的工程技术更胜一筹，于是建造了高速火箭赛车，并组建了专属车队。随着时间推移，这场私人较量演变成有组织的赛事，吸引了联盟和部落各地的观众与地下赌徒，每天前来观看两方赛车在盐地上激烈角逐。",al={"沙漠赛道的历史","沙漠赛道如何建立","沙漠赛道的起源"}},["2d853a10"]={q="沙漠赛道危险吗？",a="沙漠赛道吸引着联盟和部落的支持者前来下注和观看比赛。不过，赛车本身是性能不稳定的实验性机械，容易发生灾难性的故障。此外，越过赛营外围，你就会进入蛮荒的闪光平原，那里到处都是具有攻击性的石化蜥蜴、蝎子和敌对的拾荒者。",al={"沙漠赛道安全吗","沙漠赛道的危险","沙漠赛道的威胁"}}},fp="14,197,24.327.0,20.312.0,27.167.0,24.176.0,42.142.0,31.127.0"}
P.entries["subzone:mirkfallon-lake"] = {n="暗色湖",s="暗色湖位于石爪山脉中央的一处高地盆地中，坐落在狂风峭壁的险峻悬崖之下。湖水及其周边岸边充斥着各种原生生物，包括极具攻击性的软泥怪、游荡的雷霆蜥蜴以及盘旋的翼龙。",h="暗色湖位于石爪山脉中央的一处高地盆地中，坐落在狂风峭壁的险峻悬崖之下。湖水及其周边岸边充斥着各种原生生物，包括极具攻击性的软泥怪、游荡的雷霆蜥蜴以及盘旋的翼龙。",kw={"暗色湖","石爪山脉湖泊","石爪山脉雷霆蜥蜴","狂风峭壁湖泊"},ang={["class:Druid"]="暗色湖周围的野生兽群代表了石爪山脉荒野中脆弱的平衡，而上方峭壁中不断侵入的机械伐木机正让这一切变得岌岌可危。"},sec={{t="高地盆地",b="暗色湖位于石爪山脉的地理中心，坐落在通往南边蛛网小径和北边石爪峰的山路之间。得益于高地的径流补给，这座湖泊成为了群山峻岭中一片肥沃的绿洲，吸引着雷霆蜥蜴前来饮水，也将翼龙从高处的巢穴引向此处。湖中还栖息着奇特的、不断冒泡的软泥怪，使得这片宁静的高山湖泊成为了独行旅客眼中的危险之地。"},{t="峭壁十字路口",b="湖泊盆地四通八达。向东，岩石小径蜿蜒而上，直通狂风峭壁以及深入森林峡谷的伐木作业区。向北经过湖泊的旅行者会攀向暗夜精灵的圣所和牛头人的高地，而向南绕行的旅行者则必须应对毒蛛遍布的洞穴。因此，暗色湖的湖岸往往成为探险家和斥候穿越这片纷争山脉时一个充满变数的交汇点。"}},faq={{q="暗色湖周围生活着哪些生物？",a="湖泊及其岸边栖息着游荡的雷霆蜥蜴、浅水区有害的软泥怪，以及在周围盆地狩猎并在上方高处筑巢的山地翼龙。",al={"暗色湖野兽","暗色湖野生动物","暗色湖有什么"}},{q="湖泊通向哪里？",a="向北攀爬可通往石爪峰。向南下行会穿过蛛网小径，而向东的岩石坡路则蜿蜒通向狂风峭壁。",al={"暗色湖路径","暗色湖通向哪里","暗色湖方向"}},{q="在暗色湖钓鱼安全吗？",a="湖中盛产鼠尾鱼和漂浮的残骸，这让垂钓者十分心动。然而，软泥怪和翼龙等具有攻击性的野兽经常出没于湖岸，这使得在此安静垂钓变得十分困难。",al={"暗色湖钓鱼","能在暗色湖钓鱼吗"}}},fp="15,180,16.323.0,22.374.0,43.147.0,25.152.0,35.136.0"}
P.entries["subzone:mirror-lake"] = {n="明镜湖",s="明镜湖是位于艾尔文森林西北部果园旁的一处风景如画的水域。它由暴风城悬崖下的一道柔和瀑布汇聚而成，其平静的水面之下却潜藏着岸边的危险，从四处游荡的迪菲亚潜行者到当地魔网线中奇怪的干扰，无所不包。",h="明镜湖是位于艾尔文森林西北部果园旁的一处风景如画的水域。它由暴风城悬崖下的一道柔和瀑布汇聚而成，其平静的水面之下却潜藏着岸边的危险，从四处游荡的迪菲亚潜行者到当地魔网线中奇怪的干扰，无所不包。",kw={"迪菲亚","艾尔文森林","明镜湖","暴风城","瀑布","法师区"},ang={["class:Mage"]="在暴风城法师区学习的初学者们被派往此处收集水样，亲身学习动荡的奥术通道是如何渗入自然生态系统的。",["faction:Alliance"]="尽管离首都高耸的城墙很近，但这片湖泊却提醒着人们，王国守卫在面对迪菲亚不法之徒时显得多么捉襟见肘。"},sec={{t="不安的田园",b="明镜湖坐落在暴风城高耸的城墙之下，本应是渔夫和疲惫旅人的宁静休憩之所。然而，迪菲亚潜行者的强盗们却在周围的果园中潜行，使得任何在此停留过久的当地人都面临危险。更糟糕的是，艾泽拉斯各地发生的神秘干扰已经开始扭曲整个森林中奥术能量的自然流向。法师区的法师们正密切注视着这片湖泊，派遣修行者取样其水流，以确保下游社区不会受到混乱奥术外溢的毒害。"}},faq={{q="明镜湖为什么危险？",a="尽管风景优美，但湖泊周边区域有大量迪菲亚强盗出没，他们以路人和农夫为目标。此外，近期区域魔法的波动也引发了人们对湖水安全性的担忧。",al={"明镜湖安全吗","明镜湖的敌人","明镜湖的迪菲亚"}},{q="为什么法师要研究明镜湖？",a="艾泽拉斯各地的大规模魔法冲突破坏了整个艾尔文森林和暴风城的魔网流向。法师区派遣初学者对湖水进行采样，检测是否存在不稳定的奥术残余，以免其影响饮用湖水的人们。",al={"法师区与明镜湖","明镜湖任务","明镜湖的魔法"}},{q="明镜湖的瀑布从哪里来？",a="瀑布从环绕暴风城外围的高耸悬崖和水道倾泻而下，汇入湖泊，随后水流蜿蜒流经艾尔文森林的河流系统。",al={"明镜湖瀑布","明镜湖水源"}}},fx={["80ec8f44"]={q="明镜湖是什么地方？",a="明镜湖是艾尔文森林西部果园附近的一片小湖，景色秀丽。一道湍急的瀑布从暴风城下方的山间倾泻而下，汇入湖中，若非如今有歹徒控制着湖岸，这里本该是一处垂钓和游泳的清静去处。",al={"明镜湖艾尔文","明镜湖是什么地方","关于明镜湖"}},e8bd98e7={q="谁控制着明镜湖？",a="如今，明镜湖已被迪菲亚潜行者占据。这些不法之徒在湖岸和周围的果园游荡，赶走当地渔夫和旅人，将暴风城城墙外这片偏僻隐蔽的水域当作行动基地。",al={"谁住在明镜湖","明镜湖的匪徒","谁控制着明镜湖"}}},fp="11,189,15.494.0,29.155.0,35.243.0,50.150.0"}
P.entries["subzone:mirror-lake-orchard"] = {n="明镜湖果园",s="明镜湖果园是位于艾尔文森林西部、明镜湖南岸的一处安静的树林和农舍。这里曾是雷霆瀑布附近的一处宁静家园，如今却落入了迪菲亚潜行者的手中。在暴风城的卫兵无暇顾及之时，他们正在此处肆意劫掠乡间。",h="明镜湖果园是位于艾尔文森林西部、明镜湖南岸的一处安静的树林和农舍。这里曾是雷霆瀑布附近的一处宁静家园，如今却落入了迪菲亚潜行者的手中。在暴风城的卫兵无暇顾及之时，他们正在此处肆意劫掠乡间。",kw={"迪菲亚潜行者","艾尔文森林","明镜湖","明镜湖果园","暴风城强盗","雷霆瀑布"},ang={["class:Rogue"]="这座果园展示了典型的迪菲亚战略：夺取水边和悬崖旁易守难攻且被忽视的房产，以便在监视道路的同时躲避城市巡逻队的搜查。",["faction:Alliance"]="对于联盟的旅行者来说，这座被占领的果园是迪菲亚潜行者在王国腹地大胆扩张的又一个苦涩证明。"},sec={{t="被占据的果园",b="明镜湖果园隐匿于雷霆瀑布的奔流附近，曾是一处得益于明镜湖清澈水源的富饶农庄。如今，这座宁静的农舍已被那些打着迪菲亚潜行者旗号的投机窃贼和强盗所侵占。随着王国的军队兵力吃紧，且瓦里安·乌瑞恩国王失踪，像这样的乡村产业已成为那些试图在艾尔文森林乡间寻找藏身处的歹徒眼中的软柿子。"}},faq={{q="现在是谁控制着明镜湖果园？",a="目前迪菲亚潜行者占据了明镜湖果园及其附属的农舍。他们赶走了曾经照料果树的诚实平民，现在将这片隐蔽的场地当作他们在艾尔文森林西部的据点。",al={"谁在明镜湖果园","谁住在这里","果园敌人"}},{q="明镜湖果园在哪里？",a="果园坐落在艾尔文森林西部的明镜湖南岸，位于雷霆瀑布正东方，通往西部荒野的主路以北。",al={"明镜湖果园位置","果园在哪里","查找艾尔文森林果园"}},{q="为什么暴风城没有收复果园？",a="由于政治僵局和瓦里安·乌瑞恩国王的神秘失踪，暴风城的正规军大多不在艾尔文森林的乡村地区驻扎。由于当地驻军人手不足，偏远的农庄和果园常常不得不独自面对迪菲亚潜行者的侵扰。",al={"为什么迪菲亚在这里","卫兵在哪里"}},{q="果园和雷霆瀑布有什么联系？",a="明镜湖的水流直接注入雷霆瀑布，这使得果园刚好位于咆哮的瀑布之上。它靠近悬崖的隐蔽位置使其成为强盗们理想且易于防守的据点。",al={"雷霆瀑布的联系","果园和瀑布"}}},fx={["9fb3552d"]={q="明镜湖果园是什么地方？",a="明镜湖果园是一处宁静的小农庄，坐落在艾尔文森林西部的明镜湖南岸。这里曾是一片安宁的果园，旁边还有一间小屋，如今却和周围大部分乡野一样，陷入了无法无天的境地。",al={"这里是什么地方","明镜湖果园的故事","关于明镜湖果园"}},fc4dc36b={q="明镜湖果园发生过什么？",a="随着动乱蔓延到艾尔文森林各地，曾经照料这些果树的安分农民被赶走，或自行离开了家园。迪菲亚潜行者的不法之徒趁机进驻，将荒废的小屋和果园变成了另一处隐蔽的行动集结地。",al={"明镜湖果园的历史","这里发生过什么","果园的背景"}},d58df7ba={q="明镜湖果园为什么被遗弃了？",a="暴风城无暇兼顾各处，当地守卫又人手不足，艾尔文各地的乡间农庄便成了匪徒的主要目标。随着迪菲亚匪徒步步逼近，果园被遗弃，他们随即将小屋和土地据为己有。",al={"果园为什么被遗弃","农民为什么离开","谁遗弃了果园"}},["90c4a3ea"]={q="明镜湖果园危险吗？",a="是的。如今，这片区域已被充满敌意的迪菲亚匪徒占据，他们在果树林间巡逻，并盘踞在附近的房屋里。任何疏于戒备、贸然穿过树林的人，都可能一被发现就遭到伏击。",al={"这里安全吗","明镜湖果园的危险","明镜湖果园的敌人"}},["626e53a6"]={q="为什么叫明镜湖果园？",a="果园的名字直接取自它在明镜湖南岸的位置，那里的果树就栽种在平静如镜的湖水旁。",al={"为什么叫明镜湖果园","明镜湖果园名字含义","果园名字由来"}}},fp="19,188,21.213.0,43.174.0,37.155.0,43.259.0,61.155.0"}
P.entries["subzone:mist-s-edge"] = {n="薄雾海",s="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一条漫长而多风的海岸线。在这片被潮湿的海雾笼罩的灰色沙滩上，散落着沉船残骸、巨大的海洋生物遗骸，以及成群游荡的螃蟹和鱼人。",h="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一条漫长而多风的海岸线。在这片被潮湿的海雾笼罩的灰色沙滩上，散落着沉船残骸、巨大的海洋生物遗骸，以及成群游荡的螃蟹和鱼人。",kw={"奥伯丁","沙滩","海岸","螃蟹","黑海岸","薄雾海","鱼人","沉船"},ang={["race:NightElf"]="对于奥伯丁的暗夜精灵来说，薄雾海既是一个重要的海上边界，也是一个遭受鱼人入侵和卑劣食腐者困扰的未驯化边境。"},sec={{t="迷雾笼罩的海岸",b="薄雾海位于黑海岸的西缘，以潮湿的沙滩、岩石潮池和终年不断的沿海迷雾为特征。这片海滩是一座海洋坟场，布满了腐烂的海洋巨兽残骸、漂流木以及破碎的船只龙骨。虽然看起来荒凉，但海岸线上遍布着岸边食腐生物，尤其是极具攻击性的螃蟹和在浪花中筑巢的领地意识极强的鱼人部落。"},{t="沉船与食腐者",b="黑海岸附近危险的水域吞噬了无数船只，将破碎的船体和丢弃的货物堆满了沙滩。暗夜精灵哨兵和当地的食腐者对这条海岸线保持着警惕，投机取巧的鱼人营地经常威胁着那些沿着海岸往返于奥伯丁的旅人。"}},faq={{q="什么是薄雾海？",a="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一片广阔海岸线，以寒冷的海雾、沉船残骸和搁浅的海洋生物而闻名。",al={"薄雾海","黑海岸沙滩","什么是薄雾海"}},{q="什么威胁在这片海岸徘徊？",a="海岸线上居住着大量的敌对沿海螃蟹和好战的鱼人族群，它们在水边建立原始的营地。",al={"薄雾海怪物","沙滩上的袭击者","黑海岸沿岸危险"}},{q="为什么这里有这么多沉船和骨骸？",a="黑海岸附近险恶的洋流、暗礁和浓雾使得航行充满危险，导致船只触礁。同样，洋流也经常将巨大的利维坦和海洋生物的残骸冲上岸。",al={"黑海岸搁浅鲸鱼","薄雾海沉船","黑海岸巨型骨骸"}}},fp="11,164,20.268.0,21.207.0,20.129.0,31.111.0,52.219.0"}
P.entries["subzone:misty-pine-refuge"] = {n="雾松避难所",s="雾松避难所是银色黎明在丹莫罗中部冰天雪地中建立的一处小型哨所。",h="雾松避难所是银色黎明在丹莫罗中部冰天雪地中建立的一处小型哨所。",kw={"银色黎明","丹莫罗","加文神父","雾松避难所"},ang={["class:Priest"]="加文神父那简朴的哨所证明了圣光的侍奉往往在于远离战场、默默的警惕之中。"},sec={{t="雪中庇护所",b="雾松避难所坐落在丹莫罗风雪肆虐的山丘之间，是银色黎明在矮人领地内一处毫不起眼的哨所。尽管周遭的岩壁有铁炉堡的登山者巡逻，但这座避难所仍是加文神父（银色黎明在此地的唯一特工）的驻地，在严酷的天气和威胁着山路的危险面前，他为路人提供了一处宁静的炉火。"}},faq={{q="雾松避难所是什么地方？",a="它是银色黎明在丹莫罗中部的一处哨所，由该组织的一名特工，加文神父负责看守。",al={"这是什么地方","雾松","雾松避难所概览"}},{q="银色黎明为什么会出现在丹莫罗？",a="虽然银色黎明的重点主要在于北方的不死族威胁，但像加文神父这样的特工也在联盟领地的僻静角落进行着监视。",al={"为什么银色黎明在这里","加文神父银色黎明","银色黎明矮人领地"}},{q="谁待在避难所里？",a="银色黎明特工加文神父是该组织驻扎在避难所的唯一成员。",al={"雾松避难所里有什么人","雾松避难所非玩家角色"}}},fx={f4fbb46a={q="雾松避难所危险吗？",a="不危险，避难所本身是丹莫罗寒冷荒野中的一处安全港湾。这里是银色黎明的前哨，由伽文神父悉心照看，不过周围的雪原上仍有游荡的野兽和穴居人，带来荒野中常见的危险。",al={"雾松避难所安全吗","雾松避难所危险","雾松避难所的威胁"}}},fp="17,82,19.253.0,26.127.0,42.145.0,24.94.0"}
P.entries["subzone:misty-reed-post"] = {n="芦苇哨岗",s="芦苇哨岗是一个粗犷的部落营地，位于悲伤沼泽东部的雄鹿沼泽和芦苇海滩之间。它作为斯通纳德管辖下的前哨阵地而建立，旨在监视这片危险的湿地和凶险的海岸线。",h="芦苇哨岗是一个粗犷的部落营地，位于悲伤沼泽东部的雄鹿沼泽和芦苇海滩之间。它作为斯通纳德管辖下的前哨阵地而建立，旨在监视这片危险的湿地和凶险的海岸线。",kw={"卡塔尔","芦苇哨岗","芦苇海滩","雄鹿沼泽","斯通纳德","悲伤沼泽","托克卡尔"},ang={["class:Hunter"]="这里主要由熟悉周边沼泽生态的斯通纳德猎人驻守，代表了在充满敌意的湿地掠食者中追踪与生存所需的坚韧。",["faction:Horde"]="对于在沼泽危险的东部边缘航行的部落斥候来说，该营地提供了一个受欢迎的安全避风港和当地向导。"},sec={{t="孤寂的前哨",b="芦苇哨岗掩映在雄鹿沼泽与东海岸之间潮湿阴郁的环境中，不过是一个斯通纳德旗下的简陋营地。驻守在此的有几名斯通纳德猎人、一名萨满祭司卡塔尔，以及负责监管该哨岗的托克卡尔。这里的环境十分恶劣，没有坚固的掩体来抵御沼泽中充满敌意的野生生物和长久不散的潮气。托克卡尔怀揣着一个安静的愿望，希望斯通纳德的部落指挥部终有一天能用坚固的兽人地洞或瞭望塔来加强这一阵地，但就目前而言，斥候们必须依靠帐篷、篝火烟雾和锋利的钢铁来守住这片沼泽。"}},faq={{q="芦苇哨岗的目的是什么？",a="它作为斯通纳德部落驻军的次要前哨营地。它位于雄鹿沼泽的湿地和芦苇海滩的海岸之间，哨兵们负责监视海岸威胁和沼泽原生野兽。",al={"为什么芦苇哨岗在这里","芦苇哨岗的目的","这个营地是什么"}},{q="这里由谁负责？",a="该哨岗由托克卡尔领导，这是一名兽人，他的任务是与斯通纳德萨满祭司卡塔尔以及几名斯通纳德猎人一起守住这个脆弱的营地。托克卡尔希望该定居点最终能获得建造永久防御工事的资源。",al={"谁领导芦苇哨岗","托克卡尔"}},{q="芦苇哨岗有飞行管理员吗？",a="没有。芦苇哨岗是一个简朴的野战营地，没有双足飞龙设施。需要飞行航线的旅行者必须沿着道路向西前往斯通纳德。",al={"芦苇哨岗飞行航线","这里有飞行航线吗","芦苇哨岗飞行管理员"}}},fp="15,168,16.362.0,39.163.0,22.159.0,44.99.0"}
P.entries["subzone:misty-reed-strand"] = {n="芦苇海滩",s="芦苇海滩是悲伤沼泽东部一片雾气笼罩、荒凉的海岸线。这里布满了参差不齐的礁石、冲上岸的残骸和蔓延的沼泽迷雾，是凶猛的螃蟹、鳄鱼人和沿海鱼人部落的家园。前往岸边的旅者常常发现自己必须与当地的野生生物争夺冲上岸的资源。",h="芦苇海滩是悲伤沼泽东部一片雾气笼罩、荒凉的海岸线。这里布满了参差不齐的礁石、冲上岸的残骸和蔓延的沼泽迷雾，是凶猛的螃蟹、鳄鱼人和沿海鱼人部落的家园。前往岸边的旅者常常发现自己必须与当地的野生生物争夺冲上岸的资源。",kw={"海滩","海岸","鳄鱼人","浮木","无尽之海","芦苇海滩","鱼人","悲伤沼泽"},ang={["faction:Alliance"]="从守望堡向南行进或穿越沼泽地的联盟侦察兵经常在海滩上搜集丰富的浮木和资源，同时还要抵御那里凶猛的野生生物。",["faction:Horde"]="斯通纳德的守卫者将海滩上的鱼人部落视为一种失控的威胁，经常命令作战巡逻队去清除它们在岸边的营地。"},sec={{t="雾气弥漫的海岸线",b="芦苇海滩沿着悲伤沼泽的整个东部边界延伸，构成了深层泥沼和无尽之海之间的一道潮湿屏障。浓雾不断从水面上涌来，模糊了视线，也掩盖了当地野生生物的叫声。海滩上散落着海洋碎片、浮木和从内陆沼泽冲出来的腐烂植被。由于其地理位置偏远且气候恶劣，海岸线上没有任何正式的永久定居点，沙滩上尽是好斗的甲壳类生物、潜行的鳄鱼人和暴力捍卫其觅食领地的领土鱼人。"},{t="纷争水域",b="联盟和部落的侦察兵都会定期指引冒险者前往芦苇海滩，尽管没有任何一方宣称这片海滩是其主权领土。联盟经常在这里收集浮木和海滩残骸，同时试图削减横行的蟹群数量。与此同时，内陆的部落哨所时刻警惕着海岸线上的鱼人营地，派遣经验丰富的战士去减少它们的数量，以免这些两栖掠夺者向斯通纳德方向深入或威胁到沼泽地的通行。"}},faq={{q="芦苇海滩位于哪里？",a="芦苇海滩沿着悲伤沼泽的最东端延伸，与无尽之海接壤。从斯通纳德或周围的沼泽小径向东穿过湿地，即可到达这里。",al={"芦苇海滩在哪里","芦苇海滩位置","如何前往芦苇海滩"}},{q="海滩上栖息着哪些生物？",a="海岸线上居住着大量的巨型沿海螃蟹、沼泽鳄鱼人和各种在潮汐线附近搜寻食物的敌对鱼人部落。",al={"芦苇海滩的怪物","芦苇海滩有什么生物","芦苇海滩的敌人"}},{q="海滩上有定居点吗？",a="海滩上没有永久的友好城镇或现成的军事哨所。最近的定居点位于悲伤沼泽的更内陆地区。",al={"芦苇海滩附近的城镇","芦苇海滩基地","芦苇海滩的友好营地"}},{q="为什么双方阵营会派遣冒险者前往芦苇海滩？",a="联盟和部落偶尔都会派遣雇佣兵前往海岸。联盟使者通常会寻找可回收的浮木和沿海材料，而部落军队则会派遣战士去清理生活在岸边的凶猛鱼人部落。",al={"为什么要前往芦苇海滩","芦苇海滩任务"}}},fp="17,181,17.404.0,16.348.0,39.206.0,34.120.0,39.147.0,62.144.0"}
P.entries["subzone:misty-shore"] = {n="雾气湖岸",s="雾气湖岸是奥特兰克山脉的一处静谧湖岸，沿着洛丹米尔湖的东岸延伸。它位于达伦德农场与达拉然周边区域之间，由此处可以开阔地眺望雾气蒙蒙的黎明岛，以及芬里斯城堡那阴森的剪影。",h="雾气湖岸是奥特兰克山脉的一处静谧湖岸，沿着洛丹米尔湖的东岸延伸。它位于达伦德农场与达拉然周边区域之间，由此处可以开阔地眺望雾气蒙蒙的黎明岛，以及芬里斯城堡那阴森的剪影。",kw={"奥特兰克山脉","达伦德农场","黎明岛","芬里斯城堡","洛丹米尔湖","雾气湖岸","乌龟"},ang={["faction:Horde"]="这片雾气蒙蒙的河岸提供了一条自然通道，连接着塔伦米尔附近的被遗忘者控制区和北部的湖岸，使旅客能够避开巡逻队的视线。",["profession:Cooking"]="洛丹米尔湖岸是鳄龟丰富的狩猎场，能为穿行于奥特兰克的厨师提供鲜嫩的肉食。"},sec={{t="雾气笼罩的水岸",b="雾气湖岸沿着洛丹米尔湖延伸，横跨达伦德农场与达拉然之间。湖面上经常漂浮着又厚又湿的雾气，遮蔽了鳄龟和偶尔从附近据点溜达下来的狂热信徒。"},{t="注视湖面",b="从雾气湖岸的岸边，旅客们可以眺望水域对面的黎明岛，以及芬里斯城堡那令人望而生畏的阴影。由于此处横跨洛丹米尔湖，且邻近达拉然和血色十字军控制的区域，沿岸的旅客往往会保持低调，以避免引起不必要的注意。"}},faq={{q="雾气湖岸位于哪里？",a="雾气湖岸位于奥特兰克山脉，沿着洛丹米尔湖的东岸，介于达伦德农场和达拉然外围之间。",al={"雾气湖岸位置","雾气湖岸在哪里","雾气湖岸地图"}},{q="从这里隔水可以看见什么？",a="隔着洛丹米尔湖的水域望去，你可以看到雾气中的黎明岛以及芬里斯城堡那巍峨的轮廓。",al={"水对面有什么","雾气湖岸景观","湖景"}},{q="岸边通常会有什么威胁？",a="湖岸边栖息着鳄龟之类的湖中野兽，但旅客也有可能遭遇血色十字军的狂热信徒，或者从邻近农场和废墟中游荡出来的斥候。",al={"雾气湖岸的危险","雾气湖岸的敌人","雾气湖岸的生物"}}},fx={["140433c1"]={q="雾气湖岸是什么地方？",a="雾气湖岸是奥特兰克山脉中沿洛丹米尔湖东岸延伸的一片静谧海岸，常年笼罩在雾气之中。它大致位于达伦德农场与达拉然外围之间，从这里可以清楚地眺望湖对岸的黎明岛，以及远处的芬里斯城堡塔楼。",al={"雾气湖岸是什么","雾气湖岸介绍","雾气湖岸概况"}},fbe1f33b={q="雾气湖岸危险吗？",a="乍看之下，这里平静安宁，实则绝不安全。水中和岸边满是凶猛的钳嘴龟，旅人还得提防附近巡逻的血色十字军敌对人类。他们会攻击任何被视为受到污染或擅闯领地的人。",al={"雾气湖岸有多危险","雾气湖岸的危险","雾气湖岸安全吗"}}},fp="11,190,24.236.0,17.219.0,33.129.0,44.108.0,49.136.0"}
P.entries["subzone:misty-valley"] = {n="迷雾谷",s="迷雾谷隐藏在悲伤沼泽的西北边缘，是一处被阴影笼罩、终年浓雾弥漫的山谷，位于通往逆风小径的隘口以北。这片幽静的盆地中挤满了原始的沼泽野兽、游荡的沼泽漫步者和纠缠的恐怖怪。在山谷最深处的洞穴中，居住着巨大而恐怖的泥沼之王。",h="迷雾谷隐藏在悲伤沼泽的西北边缘，是一处被阴影笼罩、终年浓雾弥漫的山谷，位于通往逆风小径的隘口以北。这片幽静的盆地中挤满了原始的沼泽野兽、游荡的沼泽漫步者和纠缠的恐怖怪。在山谷最深处的洞穴中，居住着巨大而恐怖的泥沼之王。",kw={"逆风小径","泥沼之王","迷雾谷","悲伤沼泽","沼泽漫步者","纠缠恐怖怪"},ang={["class:Druid"]="栖息在这个幽静山谷中的笨重沼泽漫步者和纠缠恐怖怪，代表了与沼泽原始本性深度交织的沼泽元素的狂野与未驯化的愤怒。"},sec={{t="雾气笼罩的峡谷",b="迷雾谷坐落在将悲伤沼泽与逆风小径隔开的高耸悬崖之下，终年被浓厚的沼泽水汽所笼罩。与东部开阔的湿地不同，这个与世隔绝的小区域内密布着巨大的沼泽元素，包括高耸的沼泽漫步者、古老的沼泽漫步者长者以及蔓延的纠缠恐怖怪。在迷雾峡谷的最深处有一个洞穴，那是泥沼之王的巢穴，它是困扰这片沼泽的最强大的自然威胁之一。"}},faq={{q="迷雾谷位于哪里？",a="迷雾谷位于悲伤沼泽的最西北角，紧邻通往逆风小径的道路以北。",al={"迷雾谷位置","迷雾谷在哪里","悲伤沼泽迷雾谷"}},{q="这里栖息着什么生物？",a="山谷中到处都是巨大的植物元素和沼泽恐怖怪，特别是沼泽漫步者、沼泽漫步者长者以及在浓雾中游荡的纠缠恐怖怪。",al={"迷雾谷怪物","迷雾谷里的生物","迷雾谷的敌人"}},{q="山谷后面的洞穴里有什么？",a="在迷雾谷后方的洞穴深处居住着泥沼之王，这是一个巨大而强大的沼泽元素，统治着这片幽静的山谷。",al={"迷雾谷洞穴","泥沼之王洞穴","谁在迷雾谷洞穴里"}},{q="迷雾谷适合穿行吗？",a="一点也不。游荡在浓雾中的高大沼泽漫步者和纠缠恐怖怪充满敌意且极具侵略性，对于偏离主路不慎闯入的旅行者来说，这里非常危险。",al={"迷雾谷危险吗","迷雾谷等级"}}},fp="12,154,19.333.0,34.106.0,35.67.0,50.139.0,37.143.0"}
P.entries["subzone:mizjah-ruins"] = {n="米扎废墟",s="米扎废墟是坐落在荆棘谷北部的一处古老石制遗迹，位于格罗姆高营地东南方。这些破败的建筑早已被其最初的巨魔建造者所遗弃，现在已被蛮力惊人的莫什奥格食人魔所占据。食人魔以此为据点，对往来于悲伤沼泽的补给车队发动破坏性的伏击。",h="米扎废墟是坐落在荆棘谷北部的一处古老石制遗迹，位于格罗姆高营地东南方。这些破败的建筑早已被其最初的巨魔建造者所遗弃，现在已被蛮力惊人的莫什奥格食人魔所占据。食人魔以此为据点，对往来于悲伤沼泽的补给车队发动破坏性的伏击。",kw={"蛮兵","格罗姆高","米扎","米扎废墟","莫什奥格","斯通纳德","荆棘谷","巫医"},ang={["faction:Horde"]="莫什奥格在米扎的存在直接威胁到了部落的关键后勤，迫使格罗姆高营地派遣战士去保护通往斯通纳德的补给路线。"},sec={{t="食人魔的巢穴",b="和散布在荆棘谷各处的许多古老石制废墟一样，米扎废墟由古拉巴什帝国在现代文明崛起很久之前所建。如今，长满苔藓的拱门和开裂的石板被莫什奥格氏族所占据，其中主要是粗野的蛮兵和粗鄙的巫医。这些食人魔并没有安分守己地待在他们窃取的领地里，而是经常袭击前往斯通纳德部落定居点的补给车队，让这些古老的遗迹成为了格罗姆高指挥官们眼中一根持续作痛、血迹斑斑的肉中刺。"}},faq={{q="谁建造了米扎废墟？",a="和散布在荆棘谷北部的大多数石制建筑一样，米扎废墟最初是由古拉巴什帝国的丛林巨魔所建造的，在经历数世纪的战争与衰败后才被废弃。",al={"谁建造了米扎","米扎起源","米扎巨魔遗迹"}},{q="现在是谁住在米扎废墟？",a="这些废墟目前被莫什奥格食人魔占据，主要是莫什奥格蛮兵和莫什奥格巫医，他们已将这些石制建筑加固，作为当地的营地。",al={"谁住在这里","米扎怪物","莫什奥格营地"}},{q="为什么部落有兴趣清理这些废墟？",a="居住在米扎的莫什奥格食人魔积极猎食部落的补给线，伏击往返于格罗姆高营地和位于悲伤沼泽的斯通纳德前哨站之间的车队。",al={"为什么要杀莫什奥格","格罗姆高防御","斯通纳德补给任务"}}},fp="12,179,14.291.0,27.140.0,34.154.0,50.109.0"}
P.entries["subzone:mo-grosh-stronghold"] = {n="莫格罗什要塞",s="莫格罗什要塞是位于洛克莫丹东北部山丘中一处被食人魔占据的堡垒。这些野蛮的巨人栖息在古老而风化的遗迹之中，对山下的矮人定居点构成了持续不断的威胁。",h="莫格罗什要塞是位于洛克莫丹东北部山丘中一处被食人魔占据的堡垒。这些野蛮的巨人栖息在古老而风化的遗迹之中，对山下的矮人定居点构成了持续不断的威胁。",kw={"洛克莫丹","莫格罗什","山地巡逻队","食人魔","遗迹","要塞"},ang={["faction:Alliance"]="保卫洛克莫丹需要压制莫格罗什食人魔，以确保铁炉堡与北部山路之间的通行安全。",["race:Dwarf"]="莫格罗什食人魔不断威胁着矮人的巡逻队和旅行者，因此铲除它们的要塞成为了洛克莫丹山地巡逻队的一项公民防卫任务。"},sec={{t="迫在眉睫的威胁",b="莫格罗什要塞隐匿在洛克莫丹东北部的岩脊之中，是莫格罗什食人魔氏族在该地区的主要据点。潜伏在洞穴和外围营地中的蛮力部队经常劫掠往来的矮人补给车队，并对塞尔萨玛的和平造成了长久的威胁。营地周围散落的粗糙石制品暗示着这里在笨重的食人魔占据领地并建立他们独特的土丘之前，曾属于一个更古老的定居点。"}},faq={{q="莫格罗什要塞是什么？",a="它是一处建在洛克莫丹东北部山丘里的食人魔据点。莫格罗什食人魔居住在洞穴和周边地区，组成了该领地上最大的敌对食人魔飞地。",al={"莫格罗什要塞","洛克莫丹食人魔营地","莫格罗什洞穴"}},{q="在食人魔占据这里之前，谁曾居住在此？",a="古老的石制品表明在食人魔到来之前这里曾有过一个定居点，但其最初的居民是谁尚不得而知。",al={"洛克莫丹古代遗迹","谁建造了莫格罗什","洛克莫丹的巨魔"}},{q="为什么这些食人魔对矮人来说是个问题？",a="它们靠近关键的交通路线，对当地交通和在洛克莫丹穿行的贸易商队构成了严重的危险。矮人当局经常呼吁冒险者削减它们的数量，以保障山路的通行安全。",al={"为什么要击杀莫格罗什食人魔","铁炉堡面临的莫格罗什威胁"}}},fx={c213ae8d={q="谁住在莫格罗什要塞？",a="要塞被莫格罗什食人魔占据，这个野蛮的氏族盘踞在洛克莫丹东北部的丘陵与土丘间。他们之中有蛮兵、萨满祭司，以及其他强壮的打手。他们住在简陋的土丘和宽阔的地穴中，凶狠地抵御任何靠近营地的外来者或矮人巡逻队。",al={"谁住在莫格罗什要塞","莫格罗什要塞食人魔","谁领导莫格罗什要塞"}},c4467cb6={q="莫格罗什要塞危险吗？",a="极其危险。莫格罗什食人魔是整个洛克莫丹最危险的威胁之一。与附近零散的穴居人和野兽不同，这些食人魔体型庞大、组织严密，既有凶悍的蛮力，也会施展萨满法术。疏于戒备的探险者独自闯入他们的营地，往往会丧命，塞尔萨玛的巡山人也告诫人们，没有强援就不要进入。",al={"莫格罗什要塞危险吗","莫格罗什要塞有多危险","莫格罗什要塞危险"}}},fp="19,163,16.277.0,28.182.0,39.120.0,44.230.0"}
P.entries["subzone:molsen-farm"] = {n="摩尔森农场",s="摩尔森农场是位于西部荒野粮仓地区的一处废弃宅地。这里曾是一片肥沃的农田，为暴风城提供粮食，但在迪菲亚潜行者崛起，以及随之而来的机械收割傀儡肆虐之后，这里已是一片荒凉。",h="摩尔森农场是位于西部荒野粮仓地区的一处废弃宅地。这里曾是一片肥沃的农田，为暴风城提供粮食，但在迪菲亚潜行者崛起，以及随之而来的机械收割傀儡肆虐之后，这里已是一片荒凉。",kw={"废弃农场","迪菲亚","收割傀儡","宅地","摩尔森农场","西部荒野"},ang={["faction:Alliance"]="摩尔森农场杂草丛生的田野，严酷地提醒着人们暴风城对其农村领地日益衰弱的控制力，以及迪菲亚潜行者带来的紧迫威胁。"},sec={{t="一处废弃的宅地",b="和西部荒野各地许多宅地一样，摩尔森农场也成为了王国忽视和犯罪起义的牺牲品。当迪菲亚潜行者控制了乡村地区时，当地的农夫们被赶走，甚至遭遇了更糟的命运，不得不放弃了他们的作物和建筑。如今，这里不再有辛勤劳作的农夫，取而代之的是充满敌意的机械收割傀儡和游荡的暴徒，他们在那片荒芜的田野中横行，使得这座农场对于途径该地区的任何人来说都充满了危险。"}},faq={{q="摩尔森农场为何会被废弃？",a="当迪菲亚潜行者横扫西部荒野时，这座农场被废弃了。由于得不到来自暴风城的军事保护，农场主们无法抵御强盗和失控的收割傀儡，被迫逃离了自己的家园。",al={"为什么它是空的","谁住在这里","摩尔森农场发生了什么"}},{q="现在是谁控制着农场？",a="田野里到处都是发生故障的收割傀儡和与迪菲亚潜行者结盟的暴徒。目前没有合法的公民居住或耕作于此。",al={"摩尔森农场的敌人","谁在摩尔森农场"}},{q="摩尔森是谁？",a="在最近的动乱导致西部荒野的农业人口流离失所或陷入贫困之前，该农场因最初在此定居并耕种土地的当地家族而得名。",al={"谁是摩尔森","摩尔森家族"}}},fx={b4e71629={q="摩尔森农场是什么地方？",a="摩尔森农场是散布在西部荒野平原上的众多农庄之一。它曾是一座运作中的农庄，为王国提供谷物和农产品；后来，随着动荡与困苦席卷这片地区，它也和周边乡村一同衰败。",al={"摩尔森农场是什么","西部荒野的摩尔森农场","摩尔森农场介绍"}},f96eccd7={q="摩尔森农场发生了什么？",a="与西部荒野的许多地方一样，第二次战争后的动乱令摩尔森农场沦为废墟。农场主被迫离开土地，迪菲亚潜行者夺取了这片领地，机械收割机也在此横行。",al={"摩尔森农场发生了什么","摩尔森农场历史","摩尔森农场故事"}},["977abee8"]={q="摩尔森农场危险吗？",a="是的，普通旅人身处此地极其危险。田地里有失控的机械收割机巡逻，还有隶属迪菲亚潜行者的亡命之徒四处游荡。他们会凶狠地攻击任何擅闯其领地的人。",al={"摩尔森农场危险吗","摩尔森农场的威胁","摩尔森农场的危险"}}},fp="11,208,18.436.0,29.210.0,26.148.0,15.157.0"}
P.entries["subzone:moon-horror-den"] = {n="惨月洞穴",s="惨月洞穴是一处偏僻且布满冰霜的洞穴，位于冬泉谷中永望镇这座地精贸易站的东北方。洞穴坐落在参差不齐的山腰上，是狂暴枭兽的筑巢地。旅行者在靠近其冰冷的洞口时必须小心，因为这些领地意识极强的枭兽会激烈地保卫它们的庇护所。",h="惨月洞穴是一处偏僻且布满冰霜的洞穴，位于冬泉谷中永望镇这座地精贸易站的东北方。洞穴坐落在参差不齐的山腰上，是狂暴枭兽的筑巢地。旅行者在靠近其冰冷的洞口时必须小心，因为这些领地意识极强的枭兽会激烈地保卫它们的庇护所。",kw={"洞穴","永望镇","惨月洞穴","枭兽","狂暴枭兽","冬泉谷"},ang={["class:Druid"]="作为艾露恩神圣生物的守护者，德鲁伊们发现洞穴中栖息的枭兽处于暴力狂乱状态，这令人感到警醒，反映出冬泉谷正受到狂暴力量的侵袭。",["class:Hunter"]="该洞穴为追踪凶猛的枭兽提供了一个狭窄而危险的场地，在这里，与皮糙肉厚的枭兽进行近距离战斗将考验任何追踪者的胆量。"},sec={{t="羽毛与冰霜之穴",b="惨月洞穴位于距离永望镇守卫森严的大门东北方向不远处，深入山岩之中。这座洞穴是强大的狂暴枭兽的家园——这种凶猛的枭兽以其蛮力和在冬泉谷严寒雪地中的野性天性而闻名。尽管它在地理位置上靠近南面的寒水村熊怪定居点，但陡峭的山壁形成了一道不可逾越的天然屏障，确保了该洞穴依然是枭兽与世隔绝的避难所，而非交通要道。"}},faq={{q="惨月洞穴里住着什么生物？",a="这座洞穴栖息着狂暴枭兽，这是一种适应了冬泉谷严寒气候的大型且具有攻击性的枭兽。这些领地意识极强的野兽会猛烈攻击任何误入其地下巢穴的人。",al={"惨月洞穴里有什么","惨月洞穴怪物","洞穴里的枭兽"}},{q="惨月洞穴位于哪里？",a="它位于冬泉谷东部，就在地精城镇永望镇东北方不远处。洞口坐落在北面的岩壁中。",al={"惨月洞穴位置","如何找到惨月洞穴","惨月洞穴在哪里"}},{q="你能从洞穴到达寒水村吗？",a="不能。尽管在地图上寒水村就在正南方，但高耸的山脊在洞穴后方形成了一道不可逾越的天然墙壁。前往该村庄需要绕过山坡，穿过开阔的山谷。",al={"去寒水村的路径","去寒水村的捷径","从洞穴到寒水村"}},{q="为什么旅行者要冒险进入这个洞穴？",a="冒险者通常进入该洞穴狩猎狂暴枭兽，以协助那些研究冬泉谷中受到腐蚀或具有攻击性的枭兽种群的自然学家和研究人员。",al={"为什么要去惨月洞穴","惨月洞穴任务"}}},fp="15,164,27.284.0,43.168.0,37.143.0,46.155.0,40.149.0"}
P.entries["subzone:moonbrook"] = {n="月溪镇",s="月溪镇位于西部荒野西南部，如今被迪菲亚控制，镇上安居度日的居民早已逃离。兄弟会守卫着这座城镇，他们隐藏在死亡矿井中的总部就在镇子下方。",h="月溪镇位于西部荒野西南部，如今被迪菲亚控制，镇上安居度日的居民早已逃离。兄弟会守卫着这座城镇，他们隐藏在死亡矿井中的总部就在镇子下方。",kw={"死亡矿井","迪菲亚","月溪镇","学校","哨兵岭","范克里夫","西部荒野"},ang={["class:Rogue"]="身为潜行者，你能看到一个不法团伙在月溪镇的小巷与遭到洗劫的民宅间公然活动。",["faction:Alliance"]="对联盟而言，月溪镇是王国疏于照管治下领土的痛苦见证。这里奉公守法的臣民遭到遗弃，只能独自面对迪菲亚潜行者。"},sec={{t="沦陷的城镇",b="第一次兽人战争之前，月溪镇坐落在西部荒野粮食产区的腹地。农户和死亡矿井的金矿井都依赖这座城镇。Old Horde将它夷为平地，但月溪镇在Second War之后重建了起来。\n\n和平并未持续多久。暴风城的贵族对这处聚落置之不理，还撤走了保护这里的军队。居民无力抵抗戴着红色面罩的匪徒，只得逃离家园，前往哨兵岭和艾尔文森林。镇民和教师都离开了。"},{t="迪菲亚要塞",b="戴着红色面罩的暴徒和为非作歹的巫师在月溪镇的街道与遭到洗劫的民宅间巡逻。收割傀儡在周围的田野中游荡。镇子边缘一座不起眼的谷仓下方，藏着一处入口。兄弟会守卫着死亡矿井隧道上方的月溪镇，而隧道中正酝酿着反抗暴风城的叛乱。"}},faq={{q="为什么月溪镇被废弃了？",a="迪菲亚潜行者夺取西部荒野的控制权后，月溪镇安居度日的居民纷纷逃离。由于当地没有暴风城军队驻军，镇民被迫离开，匪徒占据了这里。",al={"月溪镇发生了什么","为什么月溪镇有强盗","谁占领了月溪镇"}},{q="月溪镇里面的矿洞通向哪里？",a="月溪镇边缘谷仓下方的入口通往死亡矿井。这里曾为暴风城供应大量黄金，如今矿井隧道成了迪菲亚潜行者的藏身之所，也是他们集结行动的据点。",al={"死亡矿井在哪里","月溪镇下面有什么","月溪镇矿洞入口"}},{q="在强盗占领之前，这里住着什么人？",a="矿工、农民和手艺人曾在月溪镇生活，支撑着西部荒野的农业。在匪徒占领城镇之前，斯塔文·密斯特曼托曾短暂掌管当地的月溪镇学校。",al={"月溪镇居民","谁住在月溪镇","斯塔文·密斯特曼托学校"}},{q="暴风城有计划收复这座小镇吗？",a="暴风城宫廷屡次拒绝派遣王国军队，解放月溪镇和周边农场。宫廷声称兵力捉襟见肘，只留下哨兵岭由志愿者组成的人民军保卫这一带。",al={"暴风城会拯救月溪镇吗","为什么军队不帮助月溪镇"}}},fx={["2fd23d69"]={q="月溪镇是什么地方？",a="月溪镇是西部荒野西南部一座荒废的聚落，就坐落在死亡矿井所在的山丘下方。这里曾是繁荣的采矿和农业社区，为暴风城供应粮食，如今却已沦为废墟，被迪菲亚潜行者彻底占据。",al={"这是什么城镇","月溪镇资料","关于月溪镇"}},ef8d3ecf={q="月溪镇发生过什么？",a="月溪镇在第一次兽人战争期间被兽人部落攻陷，又在第二次兽人战争之后重建。当遭到剥夺的石匠兄弟会组建迪菲亚潜行者并夺取西部荒野时，他们赶走了居民，占领月溪镇，将镇下废弃的金矿控制在手中，作为自己的总部。",al={"月溪镇历史","月溪镇的历史","这里发生过什么"}},["4b3385a0"]={q="谁住在月溪镇，又是谁掌管这里？",a="迪菲亚潜行者完全控制着月溪镇。艾德温·范克里夫麾下的匪徒、拦路强盗和盗贼扒手占据着破败的房屋，在周围街道上游荡，借这座城镇守卫通往死亡矿井地下据点的秘密入口。",al={"谁控制月溪镇","谁住在月溪镇","月溪镇居民"}},["00d0c34b"]={q="月溪镇危险吗？",a="是的。月溪镇到处都是全副武装的迪菲亚匪徒和失控的收割傀儡，任何旅人一进入视野就会遭到攻击。由于暴风城没有在镇中驻军，毫无准备地进入月溪镇，很快就会引起多名相互配合、埋伏在暗处的盗贼的注意。",al={"月溪镇安全吗","月溪镇危险","月溪镇的威胁"}}},fp="9,180,13.481.0,17.317.1,27.189.0,42.201.1,41.193.0,40.228.0"}
P.entries["subzone:moonbrook-schoolhouse"] = {n="Moonbrook Schoolhouse",s="月溪镇校舍坐落在月溪镇的西北角，是一座显眼的建筑，外观酷似市政厅，后面还有一个小小的墓地。它最初是由校长斯塔文·密斯莱特建立的，旨在教导当地的孩子们。如今，随着迪菲亚潜行者占领了西部荒野，这里已然荒废。",h="月溪镇校舍坐落在月溪镇的西北角，是一座显眼的建筑，外观酷似市政厅，后面还有一个小小的墓地。它最初是由校长斯塔文·密斯莱特建立的，旨在教导当地的孩子们。如今，随着迪菲亚潜行者占领了西部荒野，这里已然荒废。",kw={"迪菲亚潜行者","足箱","校长","密斯莱特","月溪镇","校舍","斯塔文","西部荒野"},ang={["faction:Alliance"]="这座破败的校舍严酷地提醒着人们，西部荒野距离王国的庇护已有多远，曾经的学习中心如今沦为了法外之徒的藏身之所。"},sec={{t="坠入阴影的灯塔",b="在月溪镇陷入荒废与强盗的侵扰之前，社区曾集资兴建了这座宏伟的校舍，用于培养青少年。在斯塔文·密斯莱特开始辅导当地孩子后，镇长便委任他来经营这所学校。在那些美好的日子里，这里挤满了学生，而非窃贼，它是月溪镇曾经繁荣的证明。现在，这座校舍任由风雨侵蚀，还充斥着不法之徒，而后方墓地饱经风霜的墓碑则静静地注视着西部荒野的不断衰败。"},{t="地板下的秘密",b="虽然早已不再有学者在此，但校舍中却隐藏着一个残酷谜团的开端。在大厅遗留的一个旧足箱里，放着一封未寄出的信，讲述了斯塔文来到月溪镇的过程、他对当地孩子的辅导，以及镇长委任他建立新校舍的事宜。后来在闪金镇发现的另一封信则解释了区域动荡迫使他离开职位，转而寻求私人家庭教师的工作。"}},faq={{q="这座建筑最初是做什么用的？",a="它曾是月溪镇的校舍，专门为当地儿童提供正规教育而建造。其宽敞的设计（类似于市政厅）反映了该镇在衰落前所怀抱的抱负与自豪。",al={"建造原因","月溪镇学校用途","这是什么地方"}},{q="斯塔文·密斯莱特是谁？",a="斯塔文·密斯莱特是一位博学的学者，后来成为了这所校舍的校长。调查者可以顺着他留下的书信来进一步了解他的生平。",al={"斯塔文是谁","斯塔文·密斯莱特背景故事","学校校长"}},{q="为什么现在校舍被废弃了？",a="当月溪镇在经济困境下分崩离析，而迪菲亚潜行者占领了西部荒野南部时，镇上的公共机构便随之瓦解。校舍与镇上的其他地方一起被遗弃，现在已被强盗占领。",al={"为何荒废","月溪镇学校发生了什么","现在谁住在这里"}},{q="今天在校舍里能找到什么？",a="追踪斯塔文·密斯莱特的联盟调查员可以在一楼找到一个布满灰尘的旧足箱，里面装着一封未寄出的信。",al={"足箱位置","校舍里的战利品","内部的任务物品"}}},fx={["8f4dfb64"]={q="月溪镇学校是什么地方？",a="月溪镇学校位于西部荒野南部的月溪镇西北角，是一座外形类似镇政厅的显眼建筑。它专为学者斯塔文·密斯特曼托而建，在月溪镇衰败之前，曾是当地孩子就读的学校。建筑后方静静地坐落着一片小墓地。",al={"月溪镇学校是什么","月溪镇学校","西部荒野学校"}},["5cab6b72"]={q="月溪镇学校发生过什么？",a="这所学校是为了给社区提供教育而建，斯塔文·密斯特曼托被任命为校长。任职期间，斯塔文教导当地学生，也与朋友和官员通信。西部荒野陷入动荡、月溪镇被迪菲亚潜行者占领后，学校便被废弃，只留下旧物和被遗忘的信件，躺在布满灰尘的储物箱里。",al={"学校历史","月溪镇学校发生过什么","斯塔文学校往事"}},eb59fad3={q="月溪镇学校危险吗？",a="是的。学校本身虽只是一座破败的厅堂，却位于迪菲亚潜行者重兵盘踞的月溪镇内。盗匪、强盗和亡命之徒在周围街道巡逻，也时常在建筑入口附近徘徊，没有防护的旅人每次到访都要冒险。",al={"月溪镇学校危险吗","学校的威胁","月溪镇学校的危险"}}},fp="21,161,27.291.0,26.355.1,43.163.0,27.129.0,37.182.0,47.139.0"}
P.entries["subzone:moonshrine-ruins"] = {n="Moonshrine Ruins",s="月光神殿废墟是位于黑暗深渊深处的一片被淹没的古老暗夜精灵建筑遗迹。这些正在崩塌的大厅曾用于供奉艾露恩，如今却遭到了暮光之锤教派的亵渎和占领。",h="月光神殿废墟是位于黑暗深渊深处的一片被淹没的古老暗夜精灵建筑遗迹。这些正在崩塌的大厅曾用于供奉艾露恩，如今却遭到了暮光之锤教派的亵渎和占领。",kw={"阿奎尼斯","黑暗深渊","月神殿","遗迹","圣所","瑟拉顿","暮光之锤"},ang={["class:Shaman"]="通过黑暗符文石束缚阿奎尼斯男爵这类水之精魂的行为，揭示了暮光之锤扭曲和奴役元素力量的程度有多深。",["race:NightElf"]="看到这些献给艾露恩的神圣大厅沦为被淹没、被教派蹂躏的废墟，对于任何踏入深渊的暗夜精灵来说，都是一种苦涩的悲哀。"},sec={{t="艾露恩的浸没大厅",b="穿过洞穴状的Pool of Ask'ar，便到了月光神殿废墟。这里是暗夜精灵在灰谷海岸悠久过去的凄凉见证。这些部分淹没在大厅里曾经回荡着赞美月亮女神艾露恩的圣歌，但大分裂摧毁了这座神殿，将其下层淹没在海水中。如今，浑浊的水域中翻涌着凶猛的水生野兽，从极具攻击性的螃蟹到蛇形的瑟拉顿，而暮光之锤教派则在这些石块间保持着活跃，沉迷于亵渎神殿神圣起源的黑暗仪式。"},{t="元素深处",b="这些遗迹连接着Forgotten Pool和Moonshrine Sanctum，是该教派进行召唤仪式的基地。在淹没的密室水面之下，坐落着一块与元素相连的古老符文石。通过这个水下聚焦点，暮光之锤操纵着深渊的水流，召唤出了阿奎尼斯男爵——一个受他们邪恶阴谋束缚的巨大水元素。"}},faq={{q="月光神殿废墟最初是用来做什么的？",a="这些遗迹最初是一个献给暗夜精灵女神艾露恩的宏伟地下神殿建筑群的一部分，在大分裂将古老大陆撕裂之前就已建成。",al={"月光神殿起源","谁建造了月光神殿废墟","这是什么地方"}},{q="现在是谁在控制月光神殿废墟？",a="遗迹中不仅出没着瑟拉顿和尖壳蟹等充满敌意的水生野兽，还有属于暮光之锤的邪教徒，他们已经彻底占领了整个沉没的建筑群。",al={"这里有什么人","月光神殿的怪物","黑暗深渊中的暮光之锤"}},{q="月光神殿废墟通向哪里？",a="遗迹位于阿斯卡之池之外的隧道深处。从月光神殿废墟出发，路径可以直接通向更深处的月光圣地，并提供前往遗忘之池的通道。",al={"月光神殿的出口","这里通向哪里","穿过遗迹的路径"}},{q="阿奎尼斯男爵是谁？",a="阿奎尼斯男爵是一个强大的水元素，可以通过触摸遗迹下方浑浊水域中隐藏的淹没符文石来召唤，他服务于暮光之锤的邪恶目的。",al={"阿奎尼斯男爵背景故事","月光神殿的水下首领","水中的元素"}}},fp="16,191,22.410.0,20.287.1,52.194.0,38.137.0,35.160.0,21.163.0"}
P.entries["subzone:moonshrine-sanctum"] = {n="Moonshrine Sanctum",s="Moonshrine Sanctum是深藏在黑暗深渊中的一座古老精灵神殿，现在是暮光之锤教派的内层堡垒。在梦游者克尔里斯的统治下，这座密室供奉着一座艾萨拉女王的原始雕像，并直接守卫着通往Aku'mai's Lair的封印入口。",h="Moonshrine Sanctum是深藏在黑暗深渊中的一座古老精灵神殿，现在是暮光之锤教派的内层堡垒。在梦游者克尔里斯的统治下，这座密室供奉着一座艾萨拉女王的原始雕像，并直接守卫着通往Aku'mai's...",kw={"阿库麦尔","艾萨拉","黑暗深渊","蜡烛","克尔里斯","月神殿","密室","暮光之锤"},ang={["class:Priest"]="梦游者克尔里斯在这个密室中进行的扭曲仪式颠倒了神圣的崇拜，引导的是虚空的疯狂低语，而非恢复性的神圣祈祷。",["race:NightElf"]="看到一座由你的祖先在天崩地裂前开凿的古老神殿，沦为暮光之锤和纳迦的祭祀巢穴，这是灰谷阴影不断侵蚀的令人作呕的证明。"},sec={{t="一座被亵渎的神殿",b="Moonshrine Sanctum位于被淹没的月光神殿废墟之外，是黑暗深渊内邪教活动的核心枢纽。虽然这座大厅最初是暗夜精灵在数千年前为纪念月亮和他们的统治者而建的，但现在它已被暮光之锤玷污。有趣的是，邪教徒们小心翼翼地维护着艾萨拉女王的高大雕像，似乎对雕像所描绘的对象并不在意。在梦游者克尔里斯的注视下，幽暗的仪式在如洞穴般的石顶下日夜吟唱。"},{t="通往阿库麦尔的门槛",b="这座密室是Aku'mai's Lair前的最后一道防线。沉重的双扇石门封印着那头巨大的多头蛇，并由古老的结界咒语牢牢锁住。艾萨拉的中央雕像周围有四个仪式火盆，必须点燃它们才能解开封印。这样做会惊动神殿里沉睡的守护者——成群的巨型螃蟹、断颚海龟、披甲马库拉和被召唤来防御密室不受冒失闯入者侵扰的水元素。"}},faq={{q="月光圣地在哪里？",a="月光圣地位于灰谷佐拉姆海岸的黑暗深渊地下城深处。它就在被淹没的月光神殿废墟之后，紧邻多头蛇阿库麦尔的巢穴。",al={"月光神殿圣所位置","月光神殿圣所在哪里","黑暗深渊密室"}},{q="谁统治着月光圣地？",a="梦游者克尔里斯掌管着这座密室。他是暮光之锤教派中一位强大的织梦法师，负责主持仪式以向他们古老的虚空眷顾者致敬。",al={"谁是这里的首领","月光神殿圣所的首领","谁管理密室"}},{q="为什么这里有一座完好无损的艾萨拉雕像？",a="该密室最初是一座古老的精灵神殿，在天崩地裂前供奉着艾萨拉女王。暮光之锤一直很好地维护着这座雕像，似乎对它所尊崇的女王毫无异议。",al={"艾萨拉雕像","为什么有艾萨拉雕像","黑暗深渊纳迦雕像"}},{q="如何打开密室后方的大门？",a="要解锁通往阿库麦尔的巢穴的大门，冒险者必须点燃艾萨拉雕像脚下的四支仪式蜡烛。点燃每一支蜡烛都会唤醒一波必须被击败的守护水生野兽和水元素。",al={"如何打开黑暗深渊大门","阿库麦尔大门开启","点燃黑暗深渊蜡烛"}}},fp="18,170,19.410.0,24.331.1,32.181.0,38.162.0,46.213.0,59.197.0"}
P.entries["subzone:moonspray"] = {n="Moonspray",s="Moonspray是一艘隶属于卡多雷舰队的联盟运输船。它在将卡利姆多大陆与宏伟的世界之树泰达希尔隔开的水域上，提供了至关重要的海上通行服务。",h="Moonspray是一艘隶属于卡多雷舰队的联盟运输船。它在将卡利姆多大陆与宏伟的世界之树泰达希尔隔开的水域上，提供了至关重要的海上通行服务。",kw={"奥伯丁","船","黑海岸","渡轮","卡多雷舰队","月浪号","鲁瑟兰村","泰达希尔","运输"},ang={["faction:Alliance"]="Moonspray形成了连接联盟在卡利姆多北部的主要沿海枢纽与孤立的达纳苏斯首都之间的重要交通纽带。",["race:NightElf"]="对于离开泰达希尔去探索广阔世界的年轻暗夜精灵来说，Moonspray往往是载着他们第一次离开与世隔绝的家园前往大陆的那艘船。"},sec={{t="重要的岛屿渡轮",b="Moonspray是黑海岸奥伯丁码头与泰达希尔根部的鲁瑟兰村之间不可或缺的生命线。这艘运输船穿越薄雾之海，运送冒险者、信使和重要补给品，连接着世界之树树冠上与世隔绝的暗夜精灵庇护所与古老的卡利姆多大陆。"}},faq={{q="月浪号往返于何处？",a="月浪号往返于黑海岸的港口城镇奥伯丁与位于泰达希尔海上基地的鲁瑟兰村之间。",al={"月浪号航线","月浪号去哪里","月浪号目的地"}},{q="谁拥有并运营这艘船？",a="月浪号是一艘暗夜精灵船只，隶属于卡多雷舰队，悬挂联盟旗帜航行。",al={"谁在驾驶月浪号","卡多雷舰队 月浪号","月浪号属于联盟吗"}},{q="为什么这条渡轮航线如此重要？",a="泰达希尔是一座坐落在卡利姆多西北海岸外海域高处的岛屿。像月浪号这样的船只是将部队、补给和旅行者从海上运往大陆的主要交通工具。",al={"为什么要乘坐月浪号","泰达希尔船只"}}},fp="9,152,20.212.0,32.104.0,32.93.0,34.161.0"}
P.entries["subzone:moonwell-ashenvale"] = {n="月亮井 (灰谷)",s="这座隐蔽的神龛，在暗夜精灵中被称为“纯净月井”，坐落在灰谷中部，伊瑞斯湖以东，林中树居以西。它那受祝福的井水汇聚了艾露恩的恩典，滋养着这片古老的森林，并净化着大地上蔓延的邪恶。追随莱恩·狼行者的研究的联盟旅人，常常会寻找在那宁静的池畔守望的莎尔蒂恩。",h="这座隐蔽的神龛，在暗夜精灵中被称为“纯净月井”，坐落在灰谷中部，伊瑞斯湖以东，林中树居以西。它那受祝福的井水汇聚了艾露恩的恩典，滋养着这片古老的森林，并净化着大地上蔓延的邪恶。追随莱恩·狼行者的研究的联盟旅人，常常会寻找...",kw={"灰谷","净化","艾露恩","伊瑞斯湖","月井","纯净月井","林中树居"},ang={["profession:Tailoring"]="裁缝可以利用聚集在水中的浓郁月亮能量，将恶魔布编织成纯净的月布。",["race:NightElf"]="对于卡多雷来说，每一口月井都是远在他乡的神圣家园，既是艾露恩恩典的精神源泉，也是抵御威胁着灰谷的恶魔腐蚀的前线堡垒。"},sec={{t="纯净圣所",b="这口月井藏在灰谷中部的树冠之下，是卡多雷的精神锚点。它那发光的井水汲取着自然的潜能与月之女神的光辉。随着周围的森林饱受萨特腐化、邪能污染以及伐木入侵的折磨，像这样的纯净神龛便成了那些试图治愈森林之人的重要生命线。"},{t="治愈森林",b="协助莱恩·狼行者的冒险者们来到这里寻找莎尔蒂恩，她知晓达图尔曾经制造的那根权杖。她会指引他们前往寻找散落的碎片，待碎片找齐后，她便会在月井旁重铸权杖。"}},faq={{q="这口特定的月井叫什么名字？",a="这个地点被称为纯净月井。它是灰谷各处的月井之一，位于伊瑞斯湖以东、林中树居以西。",al={"这是哪座月井","月井名称","纯净月井"}},{q="月井有什么用？",a="月井是供奉给艾露恩的神圣水池，融合了月亮力量与自然魔法。暗夜精灵利用它们来维持大地的生机、恢复精神力量，并净化被黑暗或恶魔力量污染的物品。",al={"月井的作用","月井用途","月井存在的意义"}},{q="为什么联盟冒险者会造访这座月井？",a="从阿斯特兰纳出发，追随莱恩·狼行者研究的联盟英雄们会来到这里寻找莎尔蒂恩，她会帮助他们找回达图尔权杖的碎片。",al={"莱恩的净化月井","为什么要来这里","在此净化权杖"}}},fp="20,279,19.289.0,16.242.1,38.143.0,28.225.0,48.162.0"}
P.entries["subzone:mor-shan-rampart"] = {n="莫尔杉壁垒",s="莫尔杉壁垒是部落位于贫瘠之地北界的一处重兵把守的防御工事，守卫着通往灰谷的入口。它主要由战歌氏族建造，既可以抵御暗夜精灵的反击，保护部落领土，也作为向森林深处进军的集结地。",h="莫尔杉壁垒是部落位于贫瘠之地北界的一处重兵把守的防御工事，守卫着通往灰谷的入口。它主要由战歌氏族建造，既可以抵御暗夜精灵的反击，保护部落领土，也作为向森林深处进军的集结地。",kw={"灰谷","贫瘠之地","黄金之路","莫尔杉壁垒","莫尔杉","战歌氏族"},ang={["faction:Alliance"]="联盟战士将莫尔杉壁垒视为一种侵略性的路障，认为它是部落为了保护掠夺的领土并向灰谷发起突袭而建立的。",["faction:Horde"]="对于部落而言，该壁垒是保护贫瘠之地心脏地带免受暗夜精灵入侵的主要陆路大门，同时也保证了通往灰谷伐木作业点的补给线畅通无阻。"},sec={{t="北门",b="莫尔杉壁垒矗立在黄金之路的北端，标志着从贫瘠之地的干旱平原到灰谷古老林冠之间的过渡。这座堡垒由厚重的木材、防御栅栏和坚固的瞭望塔建成，旨在遏制暗夜精灵因部落伐木行动而产生的报复性打击。它既是保卫卡利姆多内陆北门的盾牌，也是向北挺进阿斯特兰纳的突袭部队的前哨站。"},{t="战歌前哨站",b="这里主要由隶属于战歌氏族的久经沙场的战士驻守，壁垒始终保持着高度的军事戒备。岗哨从城垛上监视着林线，寻找暗夜精灵斥候和弓箭手的踪迹，确保灰谷前线哨所与南部更广阔的部落定居点之间的补给线畅通。"}},faq={{q="莫尔杉壁垒是什么？",a="它是一个位于贫瘠之地与灰谷交界处的部落防御要塞。它的建造旨在阻止联盟的反击进入贫瘠之地，并守卫黄金之路的北端。",al={"莫尔杉壁垒","这是什么路障","贫瘠之地北门"}},{q="谁控制着这座防御工事？",a="该防御工事由部落驻守，具体来说是隶属于战歌氏族的战士和哨兵。他们在森林边界沿线维护着瞭望塔和栅栏。",al={"谁控制了莫尔杉","谁在守卫壁垒","莫尔杉守军"}},{q="为什么壁垒建在这里，而不是灰谷更深处？",a="它是黄金之路北端的支点，是连接贫瘠之地中部与灰谷的主要陆路通道。控制这个咽喉要道可以确保暗夜精灵的袭击无法轻易南下直抵部落控制领土的核心地带。",al={"为什么在这里建造壁垒","莫尔杉战略重要性"}},{q="联盟旅行者能安全通过壁垒吗？",a="不能。壁垒是部落的现役军事阵地。从灰谷或贫瘠之地接近的联盟旅行者会被驻守的卫兵发现并立即攻击。",al={"联盟可以通行吗","联盟通过莫尔杉"}}},fp="16,230,17.256.0,15.241.0,29.151.0,32.145.0,55.220.0,55.134.0"}
P.entries["subzone:morgan-s-plot"] = {n="摩根墓场",s="摩根墓场是一片荒凉的墓地，坐落于逆风小径卡拉赞高塔后方，包含一座摇摇欲坠的礼拜堂。这里充斥着躁动不安的亡灵和令人窒息的死寂，埋藏着被遗忘的墓穴，以及那些曾经与麦迪文的领地有着千丝万缕联系的人们的长眠之地。",h="摩根墓场是一片荒凉的墓地，坐落于逆风小径卡拉赞高塔后方，包含一座摇摇欲坠的礼拜堂。这里充斥着躁动不安的亡灵和令人窒息的死寂，埋藏着被遗忘的墓穴，以及那些曾经与麦迪文的领地有着千丝万缕联系的人们的长眠之地。",kw={"墓穴","逆风小径","卡拉赞","麦迪文","摩根墓场"},ang={["class:Mage"]="达拉然的法师们对这个地方心存敬畏，因为他们知道这里埋葬着在麦迪文悲剧终局中丧生的人们。",["class:Priest"]="被亵渎的坟墓和游荡的不死居民，使摩根墓场成为了一种鲜明的警示，提醒人们守护者的黑暗命运所带来的腐蚀性污秽至今仍挥之不去。"},sec={{t="高塔阴影下的坟冢",b="摩根墓场紧靠卡拉赞后方陡峭的岩坡，是一片悲凉而杂草丛生的墓地，中心是一座破败的礼拜堂和地下墓穴。在这一带沦为逆风小径之前，这片庄园曾是高塔住户和附近区域的墓葬地。在最后的守护者麦迪文陨落后，黑暗能量渗入大地，将一切正常的秩序驱散。如今，躁动的不死生物在礼拜堂的地面上游荡，徘徊在仆从和历史人物的墓碑之间。"},{t="守护者与仆从的安息之所",b="这片墓地埋葬着与卡拉赞历史紧密相关的人物。麦迪文在摧毁高塔的悲剧发生后，曾被安葬于此。麦迪文后来复活，并于第三次战争期间回归。虽然地底墓穴中究竟还有什么依然是个谜，但这片土地本身就沉重地压抑着古老、久久未散的奥术气息和不安的灵魂。"}},faq={{q="摩根墓场位于何处？",a="摩根墓场位于逆风小径南部，坐落在卡拉赞高塔后方一个阴暗的低谷中。",al={"摩根墓场在哪里","摩根墓场位置","如何前往摩根墓场"}},{q="谁被安葬于此？",a="从历史上看，这片墓地和墓穴曾是卡拉赞的家族墓地。在麦迪文陨落后，这位守护者本人也被安葬在这里。",al={"谁埋在摩根墓场","麦迪文之墓","莫罗斯之墓","艾格文埋葬地"}},{q="摩根墓场有什么威胁？",a="礼拜堂及其周围区域徘徊着不死生物和躁动不安的灵魂，它们在墓碑和墓穴入口附近流连。",al={"摩根墓场的怪物","这里有什么敌人","礼拜堂怪物"}}},fp="13,147,34.452.0,39.254.1,31.103.0,19.117.0,43.120.0"}
P.entries["subzone:morgan-s-vigil"] = {n="摩根的岗哨",s="摩根的岗哨是坐落在燃烧平原东南部高地上的一处联盟废弃要塞。这里曾经是一个小村庄，如今其烧焦的房屋和崩塌的法师塔已成为监视黑石山山口的侦察兵们的简陋前哨站。它是联盟在这片由黑铁矮人和黑石兽人主宰、尘埃弥漫的土地上唯一的据点。",h="摩根的岗哨是坐落在燃烧平原东南部高地上的一处联盟废弃要塞。这里曾经是一个小村庄，如今其烧焦的房屋和崩塌的法师塔已成为监视黑石山山口的侦察兵们的简陋前哨站。它是联盟在这片由黑铁矮人和黑石兽人主宰、尘埃弥漫的土地上唯一的据点...",kw={"联盟哨所","黑石山","燃烧平原","狮鹫管理员","法师塔","摩根的岗哨","废墟"},ang={["faction:Alliance"]="这座饱经风霜的峭壁是你在这片燃烧平原上唯一的安全避难所，它不仅与暴风城有直接的飞行航线，还是组织对抗黑铁矮人和黑石兽人威胁的指挥中心。",["race:Human"]="守住这道山脊，就能防止黑石山下诞生的恐怖怪物肆无忌惮地涌入山口，危及脆弱的赤脊山山谷乃至暴风城的核心。"},sec={{t="平原上的最后一处炉火",b="摩根的岗哨坐落在俯瞰烈焰荒原的高耸岩石之上。在燃烧平原的恐怖灾难将其吞噬之前，这里曾是一个朴素的定居点。如今，烧焦的梁柱和破裂的法师塔遗迹成为了那场大劫难阴森的见证。幸存的守卫者们在满是煤灰的废墟中搭建起简陋的帆布帐篷，以此安身。尽管已成废墟，营地仍保留着一个狮鹫管理员，提供了一条跨越山脉直达暴风城的空中通道。对于在此奔波的侦察兵、指挥官和过往的冒险者们来说，这里是一处急需的避风港，让他们能在饱受下方掠夺成性的战帮骚扰之余，获得片刻的喘息。"},{t="漫长的守望",b="这个哨所的名字和存在目的源于对黑石山潜在威胁的警惕。随着黑铁部族深入钻研黑暗魔法，黑石兽人占据了周边的荒野，该营地便成为了前线集结地。守卫者们负责维持营地的防御，协调横跨灰烬的侦察行动，并确保通往南方赤脊山这一重要通道的安全。"}},faq={{q="这里的建筑发生了什么？",a="村里的房屋和其他结构都被烧成了平地，法师塔也残破不堪。幸存的居民在废墟中的帐篷里生活。造成破坏的元凶尚不明确。",al={"为什么摩根的岗哨被烧毁","摩根的岗哨遗迹","谁摧毁了摩根的岗哨"}},{q="摩根是谁？",a="摩根是这座岗哨以其命名的女性。她目前并不在驻守该营地的守卫者之列。",al={"摩根是谁","摩根的岗哨命名缘由","摩根在哪里"}},{q="联盟为什么要维持这个营地？",a="它是联盟在燃烧平原上唯一的防御性制高点，负责守卫通往赤脊山的北部山口，监视黑石山周边的部队动向，并直接从暴风城接收及时的补给和增援。",al={"联盟为何在此","摩根的岗哨的用途","为何要保留摩根的岗哨"}},{q="我该如何往返摩根的岗哨？",a="该哨所设有联盟狮鹫管理员，可直接飞往暴风城、湖畔镇、守望堡、跨过灼热峡谷的瑟银哨塔，以及河林的法霍德要塞。",al={"摩根的岗哨狮鹫管理员","如何前往摩根的岗哨","摩根的岗哨飞行路线"}},{q="摩根的岗哨免受攻击吗？",a="它有联盟岗哨严密防守，但营地外围始终暴露在游荡的野兽、烈焰元素和潜伏在山脊之外的袭击兽人面前。",al={"摩根的岗哨是否处于争夺中","部落能进入摩根的岗哨吗","安全区"}}},fp="14,269,30.435.0,14.314.0,36.195.0,14.106.0,41.247.0,44.185.0,35.152.0"}
P.entries["subzone:morlos-aran"] = {n="摩罗萨兰",s="摩罗萨兰是一处古老的暗夜精灵遗迹，坐落在费伍德森林的南部。在天崩地裂之前，它曾是一个繁荣而自豪的定居点，而今它已成为那个失落黄金时代的阴郁纪念碑，淹没在肆虐周边森林的恶魔枯萎病中。",h="摩罗萨兰是一处古老的暗夜精灵遗迹，坐落在费伍德森林的南部。在天崩地裂之前，它曾是一个繁荣而自豪的定居点，而今它已成为那个失落黄金时代的阴郁纪念碑，淹没在肆虐周边森林的恶魔枯萎病中。",kw={"亚米萨兰","巴莎兰","费伍德森林","卡多雷","摩罗萨兰","遗迹","天崩地裂"},ang={["class:Druid"]="废墟地基周围扭曲的土地展示了费伍德森林所遭受的严重破坏，这促使塞纳里奥议会致力于净化这片土地。",["race:NightElf"]="穿过摩罗萨兰是一个悲剧性的提醒，让人看到帝国曾经多么辉煌又如何陨落，神圣的祖传石雕如今已被军团邪恶的恶魔腐化所吞噬。"},sec={{t="黄金时代的余响",b="一万年前，天崩地裂之前，摩罗萨兰是古代卡多雷文明的一座宏伟城市中心。就像散布在北卡利姆多的姊妹定居点（如亚米萨兰、巴莎兰和奥迪拉兰）一样，它的大理石拱门和月光广场曾充满了精灵的生机与奥术。当永恒之井崩塌时，这座城市随之破碎，只留下残破的柱廊作为他们文明巅峰的纪念。"},{t="一处枯萎的遗迹",b="虽然黑海岸和灰谷的邻近遗迹陷入了衰败和荒野，但摩罗萨兰在第三次战争中遭遇了更为惨烈的命运。由于直接处于燃烧军团践踏的通道上，它仅存的地基被恶魔的腐化和有毒的泥沼所窒息。如今，遗迹中徘徊着野兽、堕落的元素以及滞留在费伍德森林的暗影势力残余。"}},faq={{q="摩罗萨兰最初是什么？",a="它是一座在天崩地裂之前繁荣昌盛的主要暗夜精灵定居点。它与古代卡利姆多各地的姊妹城市一起，构成了卡多雷黄金时代文明的核心部分，并在万年前沦为废墟。",al={"摩罗萨兰是什么","摩罗萨兰的历史","谁建造了摩罗萨兰"}},{q="为什么名字以“'埃兰”结尾？",a="这个后缀的含义并无记载，但它出现在几座天崩地裂前的暗夜精灵城市中，包括黑海岸的亚米萨兰和巴莎兰、灰谷的奥迪拉兰，以及凄凉之地的特瑟兰。",al={"埃兰的含义","埃兰后缀","与亚米萨兰的联系"}},{q="摩罗萨兰具体位于何处？",a="它位于费伍德森林南部，靠近灰谷的边界入口。其坍塌的大理石建筑在主路旁那些腐化、枯萎的树木间清晰可见。",al={"摩罗萨兰的位置","摩罗萨兰在哪里","寻找摩罗萨兰"}},{q="如今有什么威胁徘徊在这些遗迹中？",a="堕落的野生动物、被污染的树人以及滞留的恶魔滋生在周边森林，使摩罗萨兰对于向北前往费伍德森林的过往旅人来说极其危险。",al={"摩罗萨兰里有什么","摩罗萨兰的怪物","摩罗萨兰的危险"}}},fp="11,142,24.346.0,16.382.0,32.234.0,33.201.0,37.184.0,38.184.0"}
P.entries["subzone:mortwake-s-tower"] = {n="Klaven's Tower",s="克拉文之塔，也被称为迪菲亚之塔，是一座矗立在西部荒野东南部河岸边的加固瞭望塔。它由潜行者克拉文·摩特维克指挥，是走私赃物跨越王国边界的关键中转站。",h="克拉文之塔，也被称为迪菲亚之塔，是一座矗立在西部荒野东南部河岸边的加固瞭望塔。它由潜行者克拉文·摩特维克指挥，是走私赃物跨越王国边界的关键中转站。",kw={"安玻·吉尔妮","匕首岭","迪菲亚之塔","克拉文·摩特维克","克拉文之塔","军情七处","巨魔毒药","西部荒野"},ang={["class:Rogue"]="对于在暴风城受训的潜行者新秀来说，克拉文之塔是一个试炼之地：军情七处会指派特工潜入摩特维克的据点，测试他们的开锁和潜行技能，并掌握致命毒药的制作工艺。",["faction:Alliance"]="这座迪菲亚据点坐落在艾尔文、西部荒野和赤脊山的交界处，展示了迪菲亚潜行者对王国境内河道和贸易路线的渗透程度之深。"},sec={{t="走私者的据点",b="克拉文之塔坐落在匕首岭北部的边界地带，是迪菲亚潜行者在西部荒野南部行动的重要枢纽。它与河对岸艾尔文森林的杰罗德码头遥相呼应，作为从赤脊山掠夺来的违禁品的接收点和集结地。凭借对水道的有利控制，迪菲亚潜行者可以避开王国的巡逻队，将物资运送过去，从而保护他们的后勤网络不被王室察觉。"},{t="毒雾与阴影",b="这座塔由克拉文·摩特维克控制，他是一位沉迷于致命药剂的炼金术士兼潜行者。摩特维克在塔内花费大量时间酿造奇特的巨魔毒药，产生的浓厚毒烟充斥着塔楼上层。这些毒气虽然对入侵者来说是致命的，但也会削弱摩特维克手下卫兵的感官，从而为暴风城情报机构军情七处（SI:7）派出的潜行特工提供了可乘之机，他们在附近的丘陵上监视着这座建筑。"}},faq={{q="谁控制着这座塔？",a="这座塔由迪菲亚潜行者克拉文·摩特维克把守，他负责监管走私行动并进行易挥发毒药的实验。在他指挥下，一支迪菲亚哨兵和巡逻队负责守卫这里。",al={"摩特维克是谁","克拉文是谁","谁住在塔里"}},{q="为什么这座塔对迪菲亚潜行者很重要？",a="它是运往西部荒野的赃物的主要后勤中转站。从赤脊山走私的货物穿过艾尔文森林，经由杰罗德码头，通过这座塔汇集，以支持迪菲亚潜行者更大规模的叛乱。",al={"迪菲亚之塔的目的","这座塔有什么用","为什么塔在这里"}},{q="为什么军情七处（SI:7）要监视这个地方？",a="在马迪亚斯·肖尔大师的领导下，暴风城情报部门一直对该地点保持严密监视，因为摩特维克制造的致命毒药以及该塔在迪菲亚潜行者补给线中的核心地位。像安玻·吉尔妮这样的特工在周边进行侦察，以评估迪菲亚潜行者的动向并获取有价值的情报。",al={"军情七处 摩特维克 之塔","安玻·吉尔妮 之塔","为什么暴风城在监视"}},{q="塔内弥漫的烟雾是什么？",a="这些烟雾来自克拉文·摩特维克进行的巨魔毒药实验。关于它们对塔内卫兵的影响，请参考受保护的章节。",al={"西部荒野 毒药之塔","塔内烟雾","克拉文 毒药"}}},fx={["2b1660bb"]={q="克拉文之塔是什么？",a="这座石制瞭望塔坐落在西部荒野东南边缘，靠近河流，位于匕首岭以北。迪菲亚潜行者早已夺取此地，并将其用作坚固据点和走私窝点，连接他们在西部荒野、艾尔文森林和赤脊山的行动。",al={"克拉文之塔是什么","摩特维克西部荒野之塔","西部荒野的迪菲亚之塔"}},d8588bd0={q="克拉文之塔发生过什么事？",a="这座塔由叛逃的迪菲亚成员克拉文·摩特维克及其追随者控制。迪菲亚潜行者将其改造成坚固的走私仓库，通过杰罗德码头转运违禁品。这引起了军情七处的密切关注，他们派出安玻·吉尔妮等间谍监视塔院，并设法应对克拉文的致命药剂。",al={"摩特维克之塔的历史","克拉文之塔的历史","塔里发生了什么"}},["6fe20dc9"]={q="克拉文之塔危险吗？",a="这里极其危险。全副武装的迪菲亚哨兵和巡逻兵守卫着每个入口，改造过的无人机也潜伏在塔内。比起那些挥舞利刃的强盗，更阴险的是克拉文·摩特维克炼金药剂留下的有毒烟雾；它们弥漫在空气中，威胁着毫无防备的闯入者。",al={"克拉文之塔安全吗","摩特维克之塔的威胁","摩特维克之塔有多危险"}},["61b98615"]={q="为什么叫克拉文之塔？",a="这座据点直接以克拉文·摩特维克命名。他是迪菲亚的盗贼指挥官和毒药师，控制了这座建筑，并将其变成迪菲亚潜行者活动的中心。",al={"为什么叫摩特维克之塔","摩特维克是谁","为何叫克拉文之塔"}}},fp="14,173,23.429.0,17.400.1,24.181.0,53.200.0,32.281.0,46.138.0"}
P.entries["subzone:mosh-ogg-ogre-mound"] = {n="莫什奥格食人魔山",s="莫什奥格食人魔山是一处位于荆棘谷北部的防御性洞穴建筑群，坐落在祖尔格拉布遗迹的正南方。这里是莫什奥格食人魔部落在丛林中的主要据点，由他们冷酷的食人魔巫师酋长玛兹索斯统治。",h="莫什奥格食人魔山是一处位于荆棘谷北部的防御性洞穴建筑群，坐落在祖尔格拉布遗迹的正南方。这里是莫什奥格食人魔部落在丛林中的主要据点，由他们冷酷的食人魔巫师酋长玛兹索斯统治。",kw={"玛兹索斯","心灵之眼","莫什奥格","山洞","食人魔","荆棘谷","祖尔格拉布"},ang={["class:Mage"]="食人魔巫师玛兹索斯在山洞深处挥舞着心灵之眼，拥有着对于粗野的食人魔来说非同寻常的原始奥术能量。"},sec={{t="食人魔的巢穴",b="莫什奥格食人魔山开凿在祖尔格拉布南部的崎岖丛林山脊中，到处是野蛮的莫什奥格殴打者、萨满祭司和战争使者。食人魔占据了这个洞穴网络，将其作为抵御敌对丛林巨魔和潜行野兽的理想堡垒。"},{t="玛兹索斯与心灵之眼",b="在山洞蜿蜒深处坐镇的是玛兹索斯，这位强大的双头食人魔巫师统领着莫什奥格氏族。他拥有心灵之眼，这是一件强大而危险的奥术圣物，增强了他对追随者的精神与法术控制力。玛兹索斯对魔法的掌控和纯粹的蛮力使得进入山洞深处对任何在荆棘谷北部探险的旅行者来说都是一场危机。"}},faq={{q="谁住在莫什奥格食人魔山？",a="这座山洞由莫什奥格食人魔部落居住，包括他们的战士、殴打者、萨满祭司和战争使者。他们受到藏在洞穴深处的双头食人魔巫师酋长玛兹索斯的统治。",al={"山洞里有什么人","莫什奥格居民","食人魔山怪物"}},{q="心灵之眼是什么？",a="心灵之眼是一件强大的魔法神器，由山洞内的食人魔巫师玛兹索斯持有。它奇异的奥术力量助长了他的巫术，并巩固了他对当地食人魔的领导地位。",al={"玛兹索斯拥有什么","心灵之眼圣物","心灵之眼"}},{q="山洞位于何处？",a="这座山洞位于荆棘谷北部，坐落在祖尔格拉布巨魔城市入口以南的山丘中。",al={"莫什奥格食人魔山在哪里","食人魔山位置","如何找到食人魔山"}}},fp="19,183,14.208.0,27.375.0,37.180.0,23.151.0,27.95.0"}
P.entries["subzone:mosshide-fen"] = {n="藓皮沼泽",s="藓皮沼泽是湿地东部一片沼泽遍布、充满危险的区域，被藓皮豺狼人部落所占据。这里遍布着原始的营地，对于那些偏离主要贸易道路的旅人来说，它是最危险的地区之一。",h="藓皮沼泽是湿地东部一片沼泽遍布、充满危险的区域，被藓皮豺狼人部落所占据。这里遍布着原始的营地，对于那些偏离主要贸易道路的旅人来说，它是最危险的地区之一。",kw={"格纳尔骨头","豺狼人","沼泽地","藓皮","藓皮沼泽","湿地"},ang={["race:Dwarf"]="铁炉堡的登山者必须时刻关注藓皮沼泽，因为这些充满侵略性的豺狼人狼群会威胁到在沼泽中搜寻物资的勘探者和守卫东部小径的侦察兵。"},sec={{t="狼群领地",b="藓皮沼泽横跨湿地东部昏暗的区域，是充满侵略性的藓皮豺狼人的主要领地。这里的沼泽稠密且杂乱，散布着简陋的棚屋和堆满骨头的营地。在像格纳尔骨头（纳博恩）这样残暴的狼群首领的指挥下，豺狼人们极力守护着他们泥泞的领地，随时准备伏击并吞噬任何愚蠢到闯入他们猎场的旅人、侦察兵或勘探者。"}},faq={{q="什么是藓皮沼泽？",a="藓皮沼泽是位于湿地东部的一个子区域。它由完全被藓皮豺狼人占据和定居的湿透沼泽地组成。",al={"藓皮沼泽背景故事","这是什么地方","藓皮沼泽"}},{q="谁统治着藓皮沼泽？",a="藓皮豺狼人部落占据着这片沼泽，听命于像格纳尔骨头（纳博恩）这样残暴的首领，他指挥着自己的狼群去捕获并吞噬任何闯入他们领地的外来者。",al={"谁在这里领导豺狼人","格纳尔骨头","藓皮首领"}},{q="为什么这个区域对旅人来说很危险？",a="藓皮沼泽的豺狼人以其侵略性和贪婪的食欲而臭名昭著。旅人如果偏离既定道路，或者在湿透的灌木丛中搜寻补给，就会面临游荡狩猎群的突袭。",al={"为什么它很危险","沼泽危险"}}},fp="12,163,21.253.0,21.74.0,23.154.0,40.156.0"}
P.entries["subzone:mystic-ward"] = {n="Mystic Ward",s="秘法区是铁炉堡的西北区，是这座矮人主城用于精神信仰和奥术研究的宁静圣所。该区域以其凉爽、淡蓝色的旗帜和安静的大厅而闻名，与附近Great Forge那叮当作响的铁砧形成了鲜明对比。区内最宏伟的建筑Hall of Mysteries在巨大的石拱门下汇集了牧师、圣骑士和法师。",h="秘法区是铁炉堡的西北区，是这座矮人主城用于精神信仰和奥术研究的宁静圣所。该区域以其凉爽、淡蓝色的旗帜和安静的大厅而闻名，与附近Great Forge那叮当作响的铁砧形成了鲜明对比。区内最宏伟的建筑Hall of...",kw={"秘法大厅","铁炉堡","长莓的材料店","麦瓦的魔法服装店","法师训练师","秘法区","牧师训练师","战斗法师"},ang={["class:Mage"]="对于联盟的施法者来说，秘法区是卡兹莫丹除暴风城学院之外，获取奥术补给、法术书籍和进行进阶研究的首要中心。",["class:Priest"]="该区及其宏伟的Hall of Mysteries提供了一个宁静的避风港，矮人和到访的圣光修行者们在此聚集，进行祈祷、指导和交流。"},sec={{t="信仰与法术的圣所",b="虽然矮人以其在锻造和战场上的英勇而闻名于艾泽拉斯，但秘法区却代表了该王国更安静的知识和精神追求。这个巨大的区域以淡蓝色纹章为标志，连接着熙熙攘攘的平民区以及荒弃的洞穴和Great Forge。在这一区域内，商人们为学者和施法者提供各式法袍、卷轴和炼金试剂，商店包括The Fighting Wizard和Maeva's Mystical Apparel。该区的主体是雄伟的Hall of Mysteries，圣光的修习与奥术魔法的实践在此交汇，为那些在联盟防御战中运用神秘力量的人们提供指导。"}},faq={{q="秘法区的用途是什么？",a="秘法区是铁炉堡专门用于奥术魔法、学术研究和精神崇拜的区域。它为圣骑士、牧师和法师提供施法者补给、试剂商店和训练场地。",al={"秘法区的用途","这里发生了什么","秘法区的作用"}},{q="秘法区的主要建筑是什么？",a="该区域以神秘大厅为中心，这是一个巨大的拱形大厅，容纳了主城的神圣和奥术施法者训练师，此外还有一个显眼的装饰性水池。",al={"秘法大厅","大圣殿","秘法区的建筑"}},{q="为什么这个区的旗帜是淡蓝色的？",a="铁炉堡使用独特的纹章来划分其城市区域。军事区飘扬着尚武的红色旗帜，大锻炉以火红色为特色，而秘法区则展示淡蓝色旗帜，以象征沉思、智慧和魔法研究。",al={"铁炉堡的蓝色旗帜","为什么有蓝色旗帜"}},{q="秘法区通向哪里？",a="该区位于城市的西北象限。通道向南连接平民区，向东南连接大锻炉，向东直接通往荒弃的洞穴。",al={"秘法区的连接路径","如何前往秘法区"}}},fx={["943c276c"]={q="秘法区是什么地方？",a="秘法区是铁炉堡西北部的城区，专供奥术与神圣法术的研习和施展。这里远比喧闹的大锻炉安静，设有魔法商铺、施法材料商店，以及宏伟的秘法大厅，施法者聚集在淡蓝色旗帜下学习和训练。",al={"铁炉堡秘法区","秘法区是什么"}},fa80dc8d={q="谁住在秘法区，或管理着这里？",a="这片城区是矮人都城中学者、法师、圣骑士和牧师的安身之所。这里没有单一的总督，而是聚居着以秘法大厅为据点的知名魔法导师和精神领袖，以及当地的奥术用品商和施法材料店主。",al={"谁管理秘法区","秘法区的领袖","谁在秘法区"}},["95712a2a"]={q="秘法区危险吗？",a="对铁炉堡的访客和盟友来说并不危险。秘法区是这座联盟都城中一片和平、安全的城区。尽管厅堂内涌动着强大的魔法与神圣力量，但纪律严明的导师和学者始终对其保持着严密的控制。",al={"秘法区安全吗","秘法区有敌意吗"}},["5e418007"]={q="为什么叫秘法区？",a="这片城区因专注于神秘法术而得名。与从事工业生产的大锻炉和崇尚武备的军事区不同，这片区域完全致力于王国的奥术与神圣法术研究、施法材料贸易和魔法教学。",al={"秘法区名字由来","为何叫秘法区"}}},fp="11,205,32.447.0,33.176.0,45.160.0,43.217.0,32.146.0"}
P.entries["subzone:mystral-lake"] = {n="密斯特拉湖",s="密斯特拉湖是灰谷最大的水域，位于中南部森林，就在银风避难所下方。它深邃的水域吸引着来自联盟和部落的旅行者。",h="密斯特拉湖是灰谷最大的水域，位于中南部森林，就在银风避难所下方。它深邃的水域吸引着来自联盟和部落的旅行者。",kw={"灰谷","水之召唤","密斯特拉湖","银风避难所","水元素"},ang={["class:Shaman"]="密斯特拉湖湍急的深处是水之召唤任务中至关重要的一站，有志向的萨满必须在那里面对当地的灵魂，以掌握他们的元素技艺。",["race:NightElf"]="在银风避难所的注视下，这片灰谷最大的湖泊位于你们种族所保卫的森林中心。"},sec={{t="森林大湖",b="密斯特拉湖横跨银风避难所以南和Talondeep Vale以东的广阔区域，是灰谷最大的湖泊。暗夜精灵在北岸的银风避难所前哨站监视着这里，而来自部落和联盟的旅行者也经常会被吸引到湖畔。"},{t="精神的十字路口",b="密斯特拉湖吸引了各个阵营的关注。寻求元素沟通之道的部落萨满在试炼期间会前往其深邃的水域，以理解水的元素。湖泊中原始的共鸣使其成为那些学习束缚和敬畏潮汐之灵的人们必去的一处朝圣之地。"}},faq={{q="密斯特拉湖位于何处？",a="密斯特拉湖位于灰谷中南部。它直接坐落于银风避难所以南，石爪谷以东，是森林中最大的开放水域。",al={"密斯特拉湖在哪里","密斯特拉湖位置","密斯特拉湖地图"}},{q="萨满为何要造访密斯特拉湖？",a="部落萨满在进行水之召唤的精神试炼时会被指引前往密斯特拉湖。该湖泊拥有深厚的元素共鸣，是理解并调和水之灵的重要地点。",al={"水之召唤 密斯特拉湖","萨满任务 密斯特拉湖"}},{q="谁控制着密斯特拉湖？",a="没有任何阵营对湖泊本身拥有直接的军事控制权。暗夜精灵在北岸的银风避难所前哨站对其进行监视。",al={"密斯特拉湖是部落还是联盟的","谁拥有密斯特拉湖"}}},fp="12,146,23.321.0,20.258.0,30.149.0,33.158.0,26.152.0"}
P.entries["subzone:nat-s-landing"] = {n="Nat's Landing",s="Nat's Landing是坐落在尘泥沼泽中尘泥海湾岸边的一处简朴钓鱼营地。它是纳特·帕格的私人营地和隐居之所，他被公认为艾泽拉斯最著名的钓鱼大师。来自世界各地的冒险者们都会寻访这个不起眼的码头，以磨练他们的钓鱼技艺。",h="Nat's Landing是坐落在尘泥沼泽中尘泥海湾岸边的一处简朴钓鱼营地。它是纳特·帕格的私人营地和隐居之所，他被公认为艾泽拉斯最著名的钓鱼大师。来自世界各地的冒险者们都会寻访这个不起眼的码头，以磨练他们的钓鱼技艺。",kw={"垂钓者","码头","尘泥海湾","尘泥沼泽","钓鱼","纳特·帕格","纳特的码头","塞拉摩"},ang={["faction:Alliance"]="对于驻扎在塞拉摩的联盟公民来说，Nat's Landing只是沿海岸线走一小段宁静的路程，可以轻松拜访这位世界顶级的钓鱼大师。",["faction:Horde"]="从贫瘠之地穿越危险沼泽跋涉而来的部落垂钓者会发现，纳特对战争毫不关心，他只会根据垂钓者的抛竿技术来评判来访者。"},sec={{t="大师的避风港",b="Nat's Landing位于塞拉摩岛西南方，掩映在尘泥海湾浑浊的水域边，不过是一个饱经风霜的营地而已。这里只有一顶简单的帆布帐篷，挂满当天渔获的晾晒架，挂在树上的额外渔具，以及一座伸入海湾的摇摇欲坠的木质码头。尽管沼泽中迷雾缭绕、险象环生，但这段宁静的海岸线为传奇钓鱼大师纳特·帕格提供了一个可以远离尘世喧嚣、独自垂钓并享受宁静时光的地方。"},{t="钓鱼者的朝圣之旅",b="尽管乍看之下不起眼，但这个码头却是渴望进阶的钓鱼者必经的一站。那些已经学完了铁炉堡、奥格瑞玛或其他地方标准训练师所教知识的垂钓者，会被指引到这里向纳特证明自己的价值。帕格从不关心政治或阵营纷争；任何敢于冒着沼泽猛兽的危险来到他码头的垂钓者，都必须在世界上最危险的水域中展现出耐心和技巧，才能获得他最顶级的指导。"}},faq={{q="纳特的码头在哪里？",a="纳特的码头坐落在尘泥海湾沿岸的一处小型海岸岩礁上，位于尘泥沼泽东部，就在塞拉摩岛西南方。",al={"纳特的钓鱼点在哪里","纳特的钓鱼点位置","如何前往纳特的钓鱼点"}},{q="谁住在纳特的码头？",a="这个码头是著名人类钓鱼大师纳特·帕格的私人营地，他整天都在码头上拿着酒杯垂钓。",al={"纳特的钓鱼点有什么人","纳特的钓鱼点非玩家角色","谁住在这里"}},{q="为什么垂钓者要来这里？",a="当垂钓者掌握了主城中所有当地训练师能教给他们的知识后，他们就会被派往纳特·帕格那里。在向他们传授工匠级的指导之前，他会用世界各地极具挑战性的渔获来考验他们的专注力。",al={"为什么要来纳特的钓鱼点","工匠级钓鱼训练师","纳特·帕格训练"}},{q="纳特·帕格欢迎联盟和部落吗？",a="是的。对于专注的垂钓者，纳特·帕格持中立态度，无论是来自塞拉摩的联盟旅行者，还是从贫瘠之地冒险而来的部落旅行者，他都表示欢迎，而不论其阵营效忠。",al={"纳特的钓鱼点有敌意吗","部落可以和纳特交谈吗","纳特·帕格中立吗"}}},fp="13,135,16.350.0,26.303.0,31.97.0,27.83.0,27.191.0,47.93.0"}
P.entries["subzone:nek-mani-wellspring"] = {n="纳克迈尼圣泉",s="纳克迈尼圣泉高踞于南野人海岸上方的峭壁之上，泉中流淌着极其纯净的圣水。它是暮色森林以南唯一为人所知的未受污染的淡水源。然而，这个神圣的地点最近被充满敌意的娜迦探险者占领，它们严加防守着泉水。",h="纳克迈尼圣泉高踞于南野人海岸上方的峭壁之上，泉中流淌着极其纯净的圣水。它是暮色森林以南唯一为人所知的未受污染的淡水源。然而，这个神圣的地点最近被充满敌意的娜迦探险者占领，它们严加防守着泉水。",kw={"圣泉","圣水","娜迦","纳克迈尼","野人海岸","荆棘谷"},ang={["class:Priest"]="围绕纳克迈尼泉水神圣起源的各种说法使其成为牧师们好奇的对象，尽管关于它属于哪种信仰的争执仍是一场持久的学术纠纷。"},sec={{t="神圣之盆",b="纳克迈尼圣泉坐落在荆棘谷西部的崎岖海岸高地上。作为暮色森林以南唯一未受污染的淡水源，这处泉水被各方学者和朝圣者誉为圣水。由于不同文化和传统都声称这神圣的泉水是专为他们自己的族群所祝福，它依然是激烈神学争论的主题。尽管它享有属灵盛名，但在此进行宁静的沉思已不可能：一群凶残的娜迦最近占领了水盆，并防备着所有靠近泉水的人。"}},faq={{q="纳克迈尼圣泉有什么特别之处？",a="这处圣泉产出极其纯净的圣水，被公认为暮色森林以南荒野中唯一未受污染、完全新鲜的淡水源。许多宗教学者认为其泉水神圣，尽管不同信仰对于这泉水最初是为谁而造仍争论不休。",al={"纳克迈尼为何重要","什么是清澈圣水","荆棘谷圣泉"}},{q="圣泉具体位于何处？",a="它位于荆棘谷西岸，高踞在俯瞰南野人海岸的悬崖边上。",al={"纳克迈尼圣泉在哪里","如何找到纳克迈尼","纳克迈尼位置"}},{q="目前是谁控制着纳克迈尼圣泉？",a="一支充满敌意的娜迦探险队最近从海洋深入内陆，占领了这处神圣的水盆，并凶残地攻击任何靠近泉水的人。",al={"谁在纳克迈尼","纳克迈尼的怪物","纳克迈尼的娜迦"}},{q="为什么冒险者会被派往这处泉水？",a="旅行者和研究人员寻求圣泉的泉水用于强大的附魔、净化仪式和需要绝对纯净水的炼金配方。",al={"纳克迈尼任务","荆棘谷圣水任务","荆棘谷净水"}}},fp="19,164,14.332.0,43.195.0,40.124.0,47.139.0,40.140.0"}
P.entries["subzone:nesingwary-s-expedition"] = {n="奈辛瓦里远征队营地",s="奈辛瓦里远征队营地是一个质朴的狩猎营地，位于北荆棘谷，纳菲瑞提湖的正北面。该哨站由著名的矮人神射手赫米特·奈辛瓦里建立，旨在为那些想要在丛林中最凶猛的掠食者面前一试身手的猎人们提供一处集结地。",h="奈辛瓦里远征队营地是一个质朴的狩猎营地，位于北荆棘谷，纳菲瑞提湖的正北面。该哨站由著名的矮人神射手赫米特·奈辛瓦里建立，旨在为那些想要在丛林中最凶猛的掠食者面前一试身手的猎人们提供一处集结地。",kw={"营地","远征队","青山","赫米特","猎人","纳菲瑞提","奈辛瓦里","荆棘谷"},ang={["class:Hunter"]="对于神射手和兽王猎人来说，这个营地是一块试金石，你可以在这里磨练你的追踪技巧，挑战荆棘谷最致命的掠食者。",["race:Dwarf"]="看到赫米特·奈辛瓦里和卡兹莫丹的同僚登山者们在潮湿的热带荒野中开辟出一处繁荣的营地，这是矮人坚韧精神和狩猎热情的典型写照。"},sec={{t="丛林中的猎人哨站",b="这个偏远的营地坐落在纳菲瑞提湖北侧的河边，是大型狩猎者、追踪者和神射手们熙熙攘攘的避风港。赫米特·奈辛瓦里建立此营地是为了追踪荆棘谷的传奇野兽，他的周围聚集着诸如埃尔加丁爵士、艾耶克·罗欧克和巴尼尔·石罐等经验丰富的同僚。营地由雇佣神射手守卫，并由中立商人提供补给，无论阵营如何，这里欢迎任何懂得使用步枪或弓箭的人，将他们团结在追踪丛林中最致命掠食者的共同目标之下。"},{t="书页与掠食者",b="远征队营地的生活围绕着激烈的竞争和宏大的传奇故事展开。猎人们不断受到挑战，去精通追踪和猎杀丛林中原生的猎豹、迅猛龙和虎类，并最终挑战顶级猛兽。除了狩猎的快感外，营地还要应对其自身的一些小后勤灾难，最著名的是奈辛瓦里那份长篇手稿散落在荒野中，让营地的学者们急于找回每一章遗失的内容。"}},faq={{q="谁在管理奈辛瓦里远征队营地？",a="该营地由传奇的矮人大型野兽猎人赫米特·奈辛瓦里，协同几位资深神射手共同创立并领导。",al={"谁领导这个营地","奈辛瓦里营地领导者","谁负责这里"}},{q="为什么远征队会来到荆棘谷？",a="远征队前往荆棘谷是为了猎杀这片茂密丛林中最危险的野生动物，包括潜行的猎豹、极具攻击性的迅猛龙、凶猛的虎类，以及传奇的战利品野兽。",al={"他们在这里做什么","为什么奈辛瓦里在荆棘谷","营地目的"}},{q="奈辛瓦里远征队营地对联盟和部落都友好吗？",a="是的。该营地作为一个中立的狩猎组织运作。只要访客尊重营地，奈辛瓦里的雇佣枪手就会维持秩序，欢迎任何希望证明自己追踪技巧的联盟和部落猎人。",al={"奈辛瓦里是中立的吗","部落可以访问奈辛瓦里吗","联盟可以访问奈辛瓦里吗"}},{q="丢失的手稿书页背后的故事是什么？",a="赫米特·奈辛瓦里撰写了一部名为《荆棘谷的青山》的长篇狩猎回忆录。不幸的是，手稿的散页在荒野中遗失了，促使营地档案管理员巴尼尔·石罐招募旅人去寻回它们。",al={"荆棘谷的青山的故事","为什么书页会散落","巴尼尔·石罐的书"}}},fp="23,214,32.363.0,19.326.0,33.117.0,49.163.0,63.175.0,54.209.0"}
P.entries["subzone:nethander-stead"] = {n="奈杉德哨岗",s="奈杉德哨岗是一处位于希尔斯布莱德丘陵南海镇以东道路旁的废弃农场。这里曾是一座正常运作的人类农场，如今已沦为废墟，被泥头豺狼人部族完全占领。田野中长满了被称为“泥头花”的巨大白色蘑菇，这引起了被遗忘者炼金师的兴趣。",h="奈杉德哨岗是一处位于希尔斯布莱德丘陵南海镇以东道路旁的废弃农场。这里曾是一座正常运作的人类农场，如今已沦为废墟，被泥头豺狼人部族完全占领。田野中长满了被称为“泥头花”的巨大白色蘑菇，这引起了被遗忘者炼金师的兴趣。",kw={"泥头花","豺狼人","希尔斯布莱德","泥头","蘑菇","奈杉德","南海镇","哨岗"},ang={["faction:Alliance"]="这座被占领的农场令人不安地提醒着人们，南海镇的防线依然脆弱，野蛮的豺狼人就盘踞在东面的道路尽头。",["faction:Horde"]="需要潜入南海镇附近的这座农场，以收集皇家药剂师学会进行致命研究所需的泥头花。"},sec={{t="一处荒废的家园",b="奈杉德哨岗坐落在南海镇东部边界的视野之内，曾经是该地区农业带的重要组成部分。和东部丘陵的大部分地区一样，随着地区安全局势的恶化和野外部族的侵入，这座农场被废弃了。如今，这里是泥头豺狼人在丘陵地带唯一的栖息地。这些野兽居住在残破的篱笆和附属建筑之间，极其凶暴地驱赶着任何误入它们领地的旅行者。"},{t="泥头花",b="哨岗内无人打理的土壤为奇异真菌的生长提供了肥沃的温床。被称为“泥头花”的巨大苍白蘑菇覆盖了荒废的农田。这些真菌蕴含着强效的天然毒素，引起了塔伦米尔皇家药剂师学会的注意。药剂师们寻求直接从豺狼人领地采集的样本，用以蒸馏腐蚀性的药剂，这使得这个原本微不足道的农场成为了部落深入联盟领地进行秘密行动的目标。"}},faq={{q="奈杉德哨岗是什么？",a="奈杉德哨岗是位于希尔斯布莱德丘陵南海镇以东的一座废弃人类农场。它已经被一群充满敌意的泥头豺狼人完全占领。",al={"这个农场是什么","奈杉德哨岗信息","奈杉德哨岗在哪里"}},{q="现在是谁控制着奈杉德哨岗？",a="这座农场被泥头豺狼人部族所占据。这是希尔斯布莱德丘陵中该部族唯一的营地。",al={"谁住在这里","谁在奈杉德哨岗","这里有什么怪物"}},{q="田野里生长的巨大白色蘑菇是什么？",a="它们是泥头花，一种在哨岗荒废的土壤中茁壮成长的大型白色真菌。它们含有毒性成分，对于研究毒药的被遗忘者炼金师来说非常有价值。",al={"白色蘑菇","泥头蘑菇","泥头花"}},{q="为什么部落会关注这个荒废的农场？",a="塔伦米尔的药剂师林度恩需要生长在哨岗田野里的泥头花。它们强效的汁液是酿造痛苦药剂的重要试剂。",al={"部落为什么要来这里","被遗忘者的兴趣","部落奈杉德任务"}}},fp="15,175,18.340.0,21.330.1,24.143.0,39.117.0,57.170.0,47.146.0"}
P.entries["subzone:nethergarde-keep"] = {n="守望堡",s="守望堡是一座防御森严的联盟据点，坐落于通往诅咒之地的道路高处的悬崖之上。它由联盟在第二次战争后建立，作为一名警惕的哨兵，守望着沉寂的黑暗之门以及弥漫在红色荒原上的混乱能量。如今，在暴风城的支持下，法师和驻军仍在此进行着孤独的守望，抵御着恶魔和挥之不去的腐蚀。",h="守望堡是一座防御森严的联盟据点，坐落于通往诅咒之地的道路高处的悬崖之上。它由联盟在第二次战争后建立，作为一名警惕的哨兵，守望着沉寂的黑暗之门以及弥漫在红色荒原上的混乱能量。如今，在暴风城的支持下，法师和驻军仍在此进行着孤...",kw={"诅咒之地","黑暗之门","堡垒","卡德加","肯瑞托","守望堡","暴风城"},ang={["class:Mage"]="对于奥术修行者来说，守望堡代表了肯瑞托数十年来对维度裂隙、裂隙封印以及阻挡邪能腐蚀熵增的研究成果。",["faction:Alliance"]="这座要塞是联盟最重要的前沿堡垒之一，它以鲜血和黄金为代价建立，以确保第一次和第二次战争的恐怖永远不会再次从传送门中倾泻而出。"},sec={{t="红色世界前的哨兵",b="第二次战争末期黑暗之门被毁后，大法师卡德加和洛丹伦联盟的领袖们意识到，艾泽拉斯绝不能再让这道裂隙处于无人看守的状态。建造者们辛勤劳作，在通往诅咒之地的峡谷通道沿线竖起了高耸的壁垒、营房和法师塔。这里由肯瑞托的法师驻守，其双重使命是持续监视这道破碎的传送门，并编织结界，防止焦土上的恶魔枯萎病向北蔓延进人类王国。"},{t="孤独的守望",b="当黑暗之门重新开启，联盟远征军冒险进入德拉诺时，卡德加和他的同伴们从背后封印了传送门，将守望堡留下来看守这片死寂的遗迹。二十年来，来自达拉然和法师区的学者们一直在分析传送门残留的能量、变异的当地动物以及恶魔入侵。随着达拉然在第三次战争中被毁，守望堡完全依赖来自暴风城的关键补给车队来供养其士兵和法师，让他们能够独自对抗萦绕在这片荒原上的恐怖。"}},faq={{q="守望堡为何而建？",a="它是在第二次战争后由大法师卡德加和洛丹伦联盟下令建造的，旨在防范来自德拉诺的另一次兽人入侵，并遏制诅咒之地不断蔓延的恶魔腐蚀。",al={"守望堡的目的","守望堡为何存在","守望堡历史"}},{q="谁建造了这座堡垒？",a="守望堡是在第二次战争后，在大法师卡德加的敦促下由洛丹伦联盟建立的，并主要由达拉然肯瑞托的巫师们驻守。",al={"谁建造了守望堡","守望堡建造者"}},{q="谁现在指挥和补给这座要塞？",a="该要塞最初由达拉然的肯瑞托负责维护，但在达拉然沦陷于天灾军团和燃烧军团之后，现在主要依靠暴风城王国提供军队、定期补给车队和后勤支持。",al={"谁在管理守望堡","守望堡补给","暴风城与守望堡"}},{q="要塞内的法师在研究什么？",a="来自法师区的研究人员正在研究黑暗之门的沉寂能量、困扰当地野生生物的奇怪突变，以及防御这片红色土地上挥之不去的邪能污染的方法。",al={"守望堡法师","法师区守望堡","他们在研究什么"}}},fp="16,290,32.414.0,16.542.0,31.220.0,25.151.0,43.195.0,44.190.0"}
P.entries["subzone:night-run"] = {n="夜道谷",s="夜道谷是灰谷中东部悬崖环绕的高地上的一处偏僻的小型萨特前哨站。这里栖息着恶魔化的邪鬃萨特，是一处在古老的精灵废墟中暗藏邪恶灵魂魔法的腐化营地。",h="夜道谷是灰谷中东部悬崖环绕的高地上的一处偏僻的小型萨特前哨站。这里栖息着恶魔化的邪鬃萨特，是一处在古老的精灵废墟中暗藏邪恶灵魂魔法的腐化营地。",kw={"灰谷","黑滩教派","弗伦河","邪鬃","夜道谷","萨特","灵魂宝石"},ang={["faction:Alliance"]="夜道谷坐落在林中树居的正北面，是一个时刻威胁着重要哨兵补给线的恶魔祸患。",["race:NightElf"]="夜道谷的沦陷是一道挥之不去的伤疤：这些古老的精灵遗迹如今成为了扭曲的邪鬃萨特的避难所。"},sec={{t="一处易守难攻的悬崖高地",b="夜道谷是灰谷三大萨特据点（另外两个是萨维亚和萨提纳尔）中规模最小、位置最偏远的一处。该定居点坐落在由陡峭且无法翻越的悬崖包围的高脊之上，掩映在崩塌的精灵石雕和断裂的柱子之间。前往此处需要沿着弗伦河绕行，经过萨维亚附近的水域，或者从林中树居上方的北侧险峻岩架穿行。尽管规模不大，但这一据点威胁巨大：居住于此的邪鬃萨特与阴影之中的黑滩教派勾结，通过将扭曲的灵魂宝石固定在这里，汇聚森林中的恶魔精华。"}},faq={{q="谁控制着夜道谷？",a="夜道谷由邪鬃萨特占领，这是一个隶属于黑滩教派、由腐化的暗夜精灵恶魔组成的阵营。",al={"居住在夜道谷的生物","夜道谷怪物","夜道谷有什么"}},{q="如何前往夜道谷？",a="因为它坐落在一处四周环绕着陡峭悬崖的高耸高地上，旅行者必须通过林中树居北侧的一条狭窄岩架，或者沿着弗伦河向萨维亚方向行进，然后向西攀上山脊。",al={"如何到达夜道谷","夜道谷路径","夜道谷入口"}},{q="黑滩教派在这里做什么？",a="该教派与萨特合作，在夜道谷内维护着一颗黑暗灵魂宝石，用于收割并引导恶魔能量在灰谷各地流转。",al={"黑滩教派夜道谷","灵魂宝石夜道谷"}}},fp="9,132,26.552.0,23.119.0,27.200.0,47.161.0"}
P.entries["subzone:night-web-s-hollow"] = {n="夜行蜘蛛洞穴",s="夜行蜘蛛洞穴是一处位于提瑞斯法林地，丧钟镇西北方向的低洼地带和废弃金矿。这里充斥着蛛形纲生物，是新苏醒的被遗忘者进行试炼的场所，他们被派往此处清除害虫，以证明自己的战斗能力。",h="夜行蜘蛛洞穴是一处位于提瑞斯法林地，丧钟镇西北方向的低洼地带和废弃金矿。这里充斥着蛛形纲生物，是新苏醒的被遗忘者进行试炼的场所，他们被派往此处清除害虫，以证明自己的战斗能力。",kw={"丧钟镇","矿井","夜行蛛后","夜行蜘蛛洞穴","蜘蛛","提瑞斯法林地"},ang={["profession:Mining"]="虽然这些矿井最初是为了开采黄金而挖掘的，但由于致命的蛛形生物泛滥，这里的采矿作业早已停止。",["race:Undead"]="对于刚复活的被遗忘者来说，这处洞穴是你的首批试炼之一。猎杀这些蛛形生物可以证明你拥有效忠黑暗女王所需的专注与意志。"},sec={{t="被侵扰的矿坑",b="夜行蜘蛛洞穴坐落于丧钟镇北部的群山之中，在瘟疫席卷洛丹伦之前，曾是一座普通的人类金矿。王国陷落后，矿井彻底废弃。如今，厚厚的蛛网笼罩着岩壁，令人窒息的阴影中隐藏着一个庞大的夜行蜘蛛群落。新苏醒的被遗忘者经常被派往洞穴及其地下的隧道中，猎杀幼年和成年蜘蛛，以便被遗忘者能够重新开采矿井中的黄金。"}},faq={{q="夜行蜘蛛洞穴是什么地方？",a="这是一座废弃的金矿，位于丧钟镇西北方的一处小型峡谷。这里蛛网丛生，游荡着大量具有攻击性的蜘蛛，是新兵被遗忘者最早的试炼场之一。",al={"夜行蜘蛛洞穴","丧钟镇蜘蛛矿洞","提瑞斯法蜘蛛洞"}},{q="为什么被遗忘者要清理这些蜘蛛？",a="被遗忘者需要矿井里的黄金，但只要蜘蛛占据着隧道，他们就无法进入。执行官阿伦人手不足，因此他要求新兵协助逐步清除这些虫害。",al={"为什么要杀蜘蛛","丧钟镇蜘蛛任务"}},{q="矿井深处有什么？",a="当幼年蜘蛛在洞穴外乱爬时，成年的夜行蜘蛛会在矿井隧道中潜行。在最深、最黑暗的洞室里，盘踞着整个虫群的母体——夜行蛛后。",al={"矿洞蜘蛛首领","夜行蛛后位置"}},{q="这里一直都是蜘蛛窝吗？",a="并不是。在洛丹伦陷落之前，这里是当地人类民众开采黄金的矿场。天灾军团摧毁了该地区后，矿井年久失修，蜘蛛便搬进了阴暗、隐蔽的隧道中。",al={"谁挖掘了矿井","丧钟镇矿井历史"}}},fp="18,198,17.394.0,27.208.0,46.158.0,39.184.0,29.183.0"}
P.entries["subzone:nighthaven"] = {n="永夜港",s="永夜港是坐落在月光林地月神湖北岸的一处隐秘定居点。作为塞纳里奥议会的心脏，这里是一处避风港，暗夜精灵和牛头人德鲁伊可以在此和平共处，潜心研习，远离艾泽拉斯的阵营战争。",h="永夜港是坐落在月光林地月神湖北岸的一处隐秘定居点。作为塞纳里奥议会的心脏，这里是一处避风港，暗夜精灵和牛头人德鲁伊可以在此和平共处，潜心研习，远离艾泽拉斯的阵营战争。",kw={"塞纳里奥议会","德鲁伊","月神湖","洛甘纳尔","春节","月光林地","永夜港","雷姆洛斯"},ang={["class:Druid"]="永夜港是你远离家乡后的精神家园。通过“传送：月光林地”技能，你可以立即前往会见职业导师、进行动物形态试炼，并获得前往鲁瑟兰村或雷霆崖的独特飞行连接。",["profession:Herbalism"]="永夜港是一处宁静之地，你可以在月光林地静谧的树林间咨询草药学训练师。"},sec={{t="塞纳里奥议会的避难所",b="永夜港依傍着月神湖宁静的湖岸而建，采用了传统的暗夜精灵建筑风格，是一处远离尘世喧嚣的静谧休憩之所。在这里，月亮井为致力于维护自然平衡的林地和大厅洒下柔和的光辉。作为塞纳里奥议会的主要驻地，这里为德鲁伊学徒提供了导师、草药学训练师以及专业的供应商。该定居点保持着严格的中立，无论修行者效忠于联盟还是部落，这里都欢迎他们。"},{t="远古历史与神圣集会",b="永夜港的安宁在历史上曾多次受到考验。在上古之战结束后的几个世纪里，勇士们曾聚集于此对抗暴怒的半神欧门，将其驱逐至月神湖底。在春节期间，这座村庄也会敞开其隐秘的边界，欢迎来自艾泽拉斯各地的朝圣者，以缅怀先祖，并在艾露恩的注视下欢庆节日。"}},faq={{q="谁在统治或管理永夜港？",a="永夜港由塞纳里奥议会管理，在守护者雷姆洛斯和像洛甘纳尔这样的资深德鲁伊的指导下运作。它是一个独立、中立的避难所，而非暗夜精灵政府的领土。",al={"永夜港的管理者","永夜港的领袖","此处的负责人"}},{q="非德鲁伊可以访问永夜港吗？",a="可以。非德鲁伊可以通过木喉要塞的隧道到达月光林地，或者使用山谷中其他地方的公共飞行管理员，然后前往永夜港。村庄内的专属飞行管理员仅为德鲁伊提供服务。",al={"非德鲁伊能否进入永夜港","非德鲁伊如何到达这里"}},{q="为什么暗夜精灵和牛头人能在这里和平共处？",a="塞纳里奥议会致力于治愈自然和翡翠梦境，其重要性高于一切阵营政治。成员在月光林地内会宣誓保持中立，搁置联盟与部落的纷争，以平等的身份研习德鲁伊之道。",al={"为何此处禁止战斗","为什么允许牛头人在此","部落与联盟的和平"}},{q="从永夜港出发有哪些飞行路线？",a="塞纳里奥专属飞行管理员为德鲁伊提供直达旅程：角鹰兽为联盟提供返回鲁瑟兰村的交通，而双足飞龙则载着部落德鲁伊返回雷霆崖。",al={"永夜港的飞行管理员","此处可前往何处"}}},fp="10,157,34.361.0,37.322.0,33.196.0,32.203.0,63.269.0,49.193.0"}
P.entries["subzone:nightmare-vale"] = {n="噩梦谷",s="噩梦谷是位于提瑞斯法林地西南部的一处阴暗洼地，就在Crusader's Outpost的西面。这里曾经是一片郁郁葱葱的森林避风港，但如今树木已在枯萎的凋零之火下枯萎，凶猛的掠食者在扭曲的树干间游荡。",h="噩梦谷是位于提瑞斯法林地西南部的一处阴暗洼地，就在Crusader's Outpost的西面。这里曾经是一片郁郁葱葱的森林避风港，但如今树木已在枯萎的凋零之火下枯萎，凶猛的掠食者在扭曲的树干间游荡。",kw={"暗色猎犬","噩梦谷","缝补者雷桑","提瑞斯法林地","吸血蝙蝠"},ang={["class:Hunter"]="山谷中栖息着凶猛的暗色猎犬和吸血蝙蝠，其中包括稀有的白蝙蝠“缝补者”雷桑，这使其成为寻求可怕野兽的猎人们值得一去的试炼场。",["race:Undead"]="噩梦谷扭曲的野生动物提醒着人们瘟疫在提瑞斯法留下的持久印记，对离开布瑞尔冒险的被遗忘者旅行者构成了直接威胁。"},sec={{t="一片腐朽的荒野",b="在第三次战争之前，这片山谷是提瑞斯法乡村中一片青翠的地带，到处是鸣禽和常见的林地野味。在天灾军团的瘟疫之后，植被已经发黑腐烂。贪婪的暗色猎犬和巨大的吸血蝙蝠吞噬了当地的野生动物，将这片洼地变成了食腐动物和猛兽的阴森巢穴。"},{t="洼地的潜行者",b="在噩梦谷的阴影中潜伏着“缝补者”雷桑，这是一只体型异常巨大、通体苍白的吸血蝙蝠，在当地旅行者中臭名昭著。这片山谷夹在闹鬼的荒野和附近Crusader's Outpost狂热的哨兵之间，是一片冷酷无情的区域，粗心的冒险者很快就会成为猎物。"}},faq={{q="噩梦谷在哪里？",a="噩梦谷位于提瑞斯法林地的西南部边缘，藏在十字军前哨的西面。",al={"噩梦谷位置","噩梦谷在哪里","寻找噩梦谷"}},{q="为什么这片山谷被称为噩梦谷？",a="这片山谷曾经是一片宁静、充满生机的森林，但在摧毁洛丹伦的瘟疫中彻底沦陷。它枯萎的树木和具有攻击性的掠食者——饥饿的暗色猎犬和嗜血的蝙蝠——使得经过这里的每一个人都仿佛置身于清醒的噩梦之中。",al={"为什么叫噩梦谷","噩梦谷背景故事"}},{q="什么生物在噩梦谷出没？",a="这片山谷里到处都是凶猛的暗色猎犬和巨大的吸血蝙蝠，它们已经驱逐或吞噬了当地的森林动物。罕见的白色吸血蝙蝠，“缝补者”雷桑，也在这个洼地中徘徊。",al={"噩梦谷怪物","噩梦谷里的怪物","这里的野兽"}},{q="“缝补者”雷桑是谁？",a="“缝补者”雷桑是一只稀有的、通体雪白的吸血蝙蝠，以在噩梦谷阴暗的天空和枯萎的树冠下潜行而闻名。",al={"雷桑","缝补者雷桑","提瑞斯法稀有蝙蝠"}}},fp="14,186,20.284.0,22.290.0,32.89.0,40.231.0,35.168.0,26.114.0"}
P.entries["subzone:nightsong-woods"] = {n="夜歌森林",s="夜歌森林构成了灰谷饱受战火蹂躏的东部广袤地带，从林中树居一直延伸至艾萨拉的边界。这里是守卫神圣森林的暗夜精灵与为部落采伐木材的战歌氏族之间的主要战场。在森林阴影笼罩的林间空地上，古老的丛林与设防的营地在挥之不去的恶魔腐蚀中激烈交锋。",h="夜歌森林构成了灰谷饱受战火蹂躏的东部广袤地带，从林中树居一直延伸至艾萨拉的边界。这里是守卫神圣森林的暗夜精灵与为部落采伐木材的战歌氏族之间的主要战场。在森林阴影笼罩的林间空地上，古老的丛林与设防的营地在挥之不去的恶魔腐蚀...",kw={"灰谷","弗伦河","夜歌森林","萨提纳尔","银翼要塞","碎木岗哨","战歌伐木营地"},ang={["faction:Horde"]="这条东部战线通过碎木岗哨获取至关重要的建筑木材和战略补给路线，因此必须时刻警惕哨兵的伏击和恶魔野兽。",["race:NightElf"]="夜歌森林是一片处于围困之中的神圣边境；保护其古老的丛林免受战歌氏族斧头的砍伐，并清除残存的萨特腐化，是卡多雷义不容辞的基本职责。"},sec={{t="饱经战火的森林",b="夜歌森林横跨灰谷向东延伸至艾萨拉，其特征是不断升级的暴力冲突。弗伦河横贯西部地区，在联盟定居点和部落的蚕食之间划出了一条动荡的边界。向东深入，森林在激烈的争夺中支离破碎，碎木岗哨在这里协调着部落针对银翼要塞的军事行动。兽人的斧头不断伐倒南部的丛林，以支持部落的扩张，留下的开垦痕迹让卡多雷愤怒不已。更糟糕的是，诸如萨提纳尔和萨维亚的萨特据点，以及屠魔峡谷和冥火岭中残存的恶魔势力，正在侵蚀着这片东部的林冠。"}},faq={{q="夜歌森林位于何处？",a="夜歌森林涵盖了灰谷的东半部。其边界从林中树居和通往费伍德森林的北路一直延伸到东侧未开发的艾萨拉边界。",al={"夜歌森林位置","夜歌森林在哪里","灰谷东部森林"}},{q="为什么灰谷的这一区域战斗如此频繁？",a="该地区处于银翼要塞与战歌氏族冲突的前线。部落严重依赖从南部树木中采伐的茂密木材来建造和维持他们的定居点，而暗夜精灵则奋力抵抗这种乱砍滥伐，并试图夺回他们祖先的土地。",al={"为什么夜歌森林有战斗","灰谷部落与联盟冲突","战歌氏族冲突"}},{q="谁控制着夜歌森林？",a="没有单一派系能统治这片森林。弗伦河大致将西部的联盟领土与东部以碎木岗哨和战歌伐木营地为核心的部落阵地分隔开来。森林中还有部分地区被萨提纳尔和萨维亚的堕落萨特，以及屠魔峡谷附近的军团势力所占据。",al={"谁拥有夜歌森林","夜歌森林派系控制权"}},{q="这里存在哪些恶魔威胁？",a="东部的荒野深受恶魔和腐化力量的影响。萨特居住在诸如萨提纳尔和萨维亚这样设防的古老遗迹中，而残留的燃烧军团爪牙则盘踞在冥火岭和屠魔峡谷深处。",al={"夜歌森林的恶魔","灰谷东部的萨特","冥火岭恶魔"}}},fp="15,134,22.497.0,38.132.0,56.234.0,29.299.0,32.222.0"}
P.entries["subzone:nijel-s-point"] = {n="尼耶尔前哨站",s="尼耶尔前哨站是坐落在凄凉之地北部峭壁高处的一处联盟与塞纳里奥议会的防御据点。它远离下方被枯萎侵蚀的山谷，成为了联盟旅行者、研究人员和士兵在荒原中穿行时唯一的安全港湾。",h="尼耶尔前哨站是坐落在凄凉之地北部峭壁高处的一处联盟与塞纳里奥议会的防御据点。它远离下方被枯萎侵蚀的山谷，成为了联盟旅行者、研究人员和士兵在荒原中穿行时唯一的安全港湾。",kw={"安东修士","半人马","凄凉之地","玛兰蒂斯","玛拉顿","尼耶尔前哨站","前哨站","本迪加斯"},ang={["class:Druid"]="玛兰蒂斯守望者利用这处高山避难所，组织力量去回收玛拉顿内部腐化中滋生的扎尔塔遗骸。",["faction:Alliance"]="尼耶尔前哨站是你在凄凉之地唯一的防御避难所和飞行中转站，连接着石爪山脉、塞拉摩和菲拉斯之间的补给线。"},sec={{t="荒原之上的堡垒",b="尼耶尔前哨站开凿于毗邻石爪山脉的陡峭悬崖之中，高居于凄凉之地的灰色尘埃和四处劫掠的半人马部族之上。这处定居点由本迪加斯上尉率领的暴风城军队分遣队驻守，负责监视那些威胁到联盟在卡利姆多南部利益的激烈部族战争。其高海拔和狭窄的通路使其易守难攻，为往返于石爪峰、塞拉摩和羽月要塞之间的信使、斥候和狮鹫骑士提供了安全的补给中转站。"},{t="塞纳里奥与十字军的远征",b="除了暴风城的驻军外，这个前哨站还庇护着一些怀揣不同且危险目的的使者。玛兰蒂斯守望者和他的树妖们以此营地作为行动基地，深入玛拉顿对抗瑟莱德丝公主，试图寻回陨落的半神扎尔塔。就连血色十字军也在此地派驻了一名使者——安东修士，他致力于清除肆虐在谷底的亡灵。尽管士兵和德鲁伊们在这里往来穿梭，但“尼耶尔”究竟是谁，对于那些驻守在山脊上的人们来说，仍是一个被岁月遗忘的古老谜团。"}},faq={{q="为什么联盟会驻扎在凄凉之地？",a="本迪加斯上尉率领一支暴风城军队分遣队在此监视交战的半人马氏族。联盟担心，一旦某个氏族消灭了其他氏族，胜利的部落大军就会将其侵略目标转向邻近的领土和定居点，例如石爪山脉和菲拉斯。",al={"为什么联盟在这里","凄凉之地的暴风城军队","尼耶尔前哨站存在的原因"}},{q="尼耶尔是谁？",a="前哨站里似乎没人知道。他真实的过往早已湮没在历史长河中。",al={"谁是尼耶尔","尼耶尔背景故事","尼耶尔前哨站是以谁命名的"}},{q="塞纳里奥议会在尼耶尔前哨站做什么？",a="玛兰蒂斯守望者和他的树妖姐妹来到凄凉之地，目的是肃清玛拉顿，击杀瑟莱德丝公主，并寻回扎尔塔的遗骸，将其送回石爪山脉的神圣林地。",al={"尼耶尔前哨站的德鲁伊","玛兰蒂斯守望者的任务","为什么树妖在这里"}},{q="为什么血色十字军会在尼耶尔前哨站？",a="安东修士担任血色十字军的一名外派使者。暴风城的克罗雷修士会派遣联盟冒险者去见他，而他则会考验这些冒险者在对抗白骨之谷中肆虐的亡灵时的决心。",al={"安东修士与血色十字军","凄凉之地的血色十字军"}}},fp="13,182,26.490.0,32.432.0,42.242.0,14.85.0,51.178.0,44.211.0"}
P.entries["subzone:north-coast"] = {n="北部海岸",s="北部海岸是一片阴暗、雾气缭绕的海岸线，标志着提瑞斯法林地沿着无尽之海的北缘。在洛丹伦沦陷后，这里受到腐蚀，寒冷的沙滩上布满了腐烂的海洋生物，并由敌对的鱼人部落强力守卫。",h="北部海岸是一片阴暗、雾气缭绕的海岸线，标志着提瑞斯法林地沿着无尽之海的北缘。在洛丹伦沦陷后，这里受到腐蚀，寒冷的沙滩上布满了腐烂的海洋生物，并由敌对的鱼人部落强力守卫。",kw={"海滩","迪布","无尽之海","鱼人","北部海岸","提瑞斯法林地","邪鳍"},ang={["race:Undead"]="虽然被遗忘者的巡逻路线紧贴着穿过布瑞尔的道路，但清除北部海岸入侵的鱼人可以确保提瑞斯法林地的北侧保持相对安全。"},sec={{t="凋零的海岸线",b="在第三次战争之前，这些北方的水域和多石的沙滩曾是洛丹伦宁静的北边界。当亡灵天灾横扫整个大陆时，其腐蚀性的瘟疫渗下了悬崖，毒害了海岸。水域变得冰冷浑浊，冲刷着巨型海洋生物的尸体，如今这些尸体在终年不散的海岸迷雾中，在沙滩上腐烂。"},{t="邪鳍之岸",b="随着人类王国破碎，被遗忘者将注意力集中在布瑞尔和洛丹伦王城周围，海岸鱼人便占据了这片荒凉的沙滩。当地的邪鳍鱼人部落在浪花边搭建了小屋，并将附近的浅滩用作产卵地。成群结队的贪婪鱼人，包括像迪布这样的知名人物以及无数正在成长的幼体，暴力地守护着潮汐线，抵御任何地表生物。"}},faq={{q="北部海岸栖息着什么生物？",a="海滩主要被好斗的邪鳍鱼人、它们的幼体以及在从无尽之海冲刷上岸的腐烂海洋生物中觅食的食腐动物所占据。",al={"北部海岸怪物","北部海岸有什么生物"}},{q="迪布是谁？",a="迪布是一名鱼人个体，可以在北部海岸的海岸小屋和浅滩附近徘徊时找到他。",al={"迪布","鱼人迪布","迪布是谁"}},{q="为什么海岸上到处都是腐烂的尸体？",a="摧毁了洛丹伦的亡灵瘟疫渗入了沿海生态系统，毒害了周围的浅滩，导致死去的海洋巨兽被冲上岸，在被腐蚀的沙滩上腐烂。",al={"死去的海洋巨兽","提瑞斯法搁浅的鲸鱼","为什么有死去的生物"}},{q="北部海岸有任何主要派系争夺吗？",a="无论是被遗忘者还是联盟的残余势力，都没有在北部海岸驻军。它仍然是一片狂野、未被驯服的边缘地带，主要留给了鱼人和海洋害虫。",al={"谁拥有北部海岸","被遗忘者在北部海岸的驻扎情况"}}},fp="11,146,20.328.0,18.295.0,39.147.0,12.78.0,46.160.0,51.147.0"}
P.entries["subzone:north-gate-outpost"] = {n="北门哨岗",s="北门哨岗是一座坚固的矮人营地，坐落在丹莫罗的北门小径高处。它扼守着铁炉堡冰雪覆盖的心脏地带与洛克莫丹之间崎岖的通道，驻扎在此的山地探险队员保护着过往的旅人，免受遍布于岩壁间的敌对野兽侵扰。",h="北门哨岗是一座坚固的矮人营地，坐落在丹莫罗的北门小径高处。它扼守着铁炉堡冰雪覆盖的心脏地带与洛克莫丹之间崎岖的通道，驻扎在此的山地探险队员保护着过往的旅人，免受遍布于岩壁间的敌对野兽侵扰。",kw={"丹莫罗","铁炉堡","洛克莫丹","山地探险队员","北门哨岗","北门小径"},ang={["race:Dwarf"]="这座哨岗展现了铁炉堡山地探险队员坚毅的职责，无论气候多么寒冷，亦或掠食者如何出没，他们始终坚守着这些严苛的高地隘口。",["race:Gnome"]="随着侏儒重新在丹莫罗各地定居，他们经常利用自己的智慧和枪法协助矮人驻军搜寻失踪的巡逻队。"},sec={{t="小径守卫",b="这个小型定居点位于北门小径中部，是丹莫罗的东北门户。驻扎在此的矮人山地探险队员负责清理通往洛克莫丹的山间隧道主干道上的野兽，并监视往来交通。恶劣的气候和陡峭的沟壑使巡逻任务变得十分危险，驻军经常请求过往旅人协助侦察周边山脊，寻找失踪的巡逻队和危险的掠食者。"}},faq={{q="北门哨岗的用途是什么？",a="它是一座山区军事检查站，负责保障北门小径的安全。北门小径是连接丹莫罗与洛克莫丹的北部通道。驻扎在这里的山地探险队员通过控制野兽数量，确保这条通道的贸易与通行顺畅。",al={"北门哨岗用途","北门哨岗的存在意义"}},{q="穿过小径的道路通往哪里？",a="向东穿过哨岗后的山间隧道可抵达气候温和的洛克莫丹山谷，向西则可通往卡拉诺斯和铁炉堡。",al={"北门小径通向哪里","穿过北门哨岗的道路"}},{q="为什么山地探险队员需要旅人的帮助？",a="积雪崖壁间的当地野生动物领地意识极强。几名山地探险队员在猎杀危险野兽时失踪于岩壁之中，迫使驻军不得不征召有能力的侦察者来查明他们的下落。",al={"北门哨岗任务","失踪的山地探险队员"}}},fx={c46f381d={q="北门哨岗是什么地方？",a="北门哨岗是丹莫罗最东北端的矮人聚居点。它坐落在北门小径的高处，扼守着连接西侧丹莫罗与东侧洛克莫丹谷地的重要山路，是供旅人和补给商队通行的设防关卡。",al={"北门哨岗是什么","北门哨岗背景故事","北门哨岗介绍"}},["650c30dc"]={q="谁住在北门哨岗，或负责管理那里？",a="哨岗由矮人巡山人驻守，他们负责巡逻高山隘口，保障丹莫罗与洛克莫丹之间的通行安全。他们时刻警戒着冰封的道路，但恶劣的天气与凶猛的野兽让这支小规模守军疲于应付。",al={"北门哨岗有谁","谁管理北门哨岗","北门哨岗居民"}},["5e6548b7"]={q="北门哨岗危险吗？",a="哨岗本身可以提供庇护，但周围的山道危机四伏。不断逼近的山地掠食者时常威胁哨岗外围，最近已有几名巡山人在雪地中失踪，当时他们正在追踪盘踞于峭壁间、格外凶猛的野兽。",al={"北门小径危险吗","北门哨岗附近的危险","北门哨岗的威胁"}},aaf153dc={q="为什么叫北门哨岗？",a="哨岗得名于它所守卫的北门小径，也就是北面的山间通道。它正好位于这条交通路线的中段，是连接丹莫罗与洛克莫丹的北方门户。",al={"为什么叫北门哨岗","北门哨岗名称","北门哨岗如何得名"}}},fp="18,142,18.354.0,36.210.0,42.99.0,49.198.0"}
P.entries["subzone:north-gate-pass"] = {n="北门小径",s="北门小径是连接丹莫罗的雪山峻岭与洛克莫丹的起伏盆地的一条重要山间通道。它是卡兹莫丹群峰间的一条北部走廊，有一座坚固的矮人哨岗驻守于此。前往湿地北部低地的旅客经常会穿过这条高路。",h="北门小径是连接丹莫罗的雪山峻岭与洛克莫丹的起伏盆地的一条重要山间通道。它是卡兹莫丹群峰间的一条北部走廊，有一座坚固的矮人哨岗驻守于此。前往湿地北部低地的旅客经常会穿过这条高路。",kw={"丹莫罗","铁炉堡","洛克莫丹","山地探险队员","北门哨岗","北门小径","湿地"},ang={["faction:Alliance"]="这条隘口是连接矮人首都与前往湿地的北方联盟远征军的一条关键军事和补给走廊。",["race:Dwarf"]="对于往返于铁炉堡高大城门与洛克湖周边边境定居点之间的矮人来说，这条隘口是一个熟悉的、由岩石开凿而成的门槛，且有同僚山地探险队员在此驻守。"},sec={{t="群峰间的隘口",b="北门小径开凿在卡兹莫丹的陡峭岩壁之中，是连接丹莫罗高处冰封的山谷与洛克莫丹温带水域的北部动脉通道。旅客穿过陡峭的山间隧道，从西面走出，映入眼帘的便是洛克湖谷那广阔的景象。由于它位于通往湿地道路的必经之路上，这条隘口承担着大量矮人信使、商人和漫游冒险者的通行往来。它的战略价值由北门哨岗所保障，山地探险队员们在此保持警惕，防御穴居人和山地掠食者。"}},faq={{q="北门小径通向哪里？",a="这条隘口连接着丹莫罗东部和洛克莫丹西北部。沿着这条路继续向北绕过洛克湖，便可抵达通往湿地的山间隧道，这使得它成为了北方旅客的一个关键枢纽。",al={"北门小径通向哪里","北门小径目的地","穿越北门小径的路线"}},{q="什么在守卫这处隘口？",a="铁炉堡山地探险队直接在道路旁驻守着北门哨岗，监控过往旅客，并确保这条山路免受游荡的野兽和穴居人的骚扰。",al={"谁在守卫北门小径","北门小径守卫","北门矮人哨岗"}},{q="它与南门小径有何不同？",a="这两条隘口都通过开凿的隧道将丹莫罗与洛克莫丹连接起来，但北门小径位于北部，为前往湿地和北方领地的旅客提供了最直接的陆路通道。",al={"北门小径与南门小径的区别","北门与南门对比"}}},fx={c14f680d={q="北门小径是什么地方？",a="北门小径是开凿于卡兹莫丹群峰间的一条重要山间通道，连接着西侧丹莫罗的积雪高地和东侧地势较低的洛克莫丹盆地。前往通向湿地下坡路的旅人和冒险者常从这里经过。",al={"北门小径是什么","北门小径介绍","北门小径资料"}},["8f6c351e"]={q="谁住在北门小径，或负责管理那里？",a="这条山道由驻扎在北门哨岗的铁炉堡巡山人维护并守卫。山道内没有常住的平民，矮人卫兵在此巡逻，保护往来丹莫罗与洛克莫丹的友方旅人。",al={"谁控制北门小径","谁守卫北门小径","北门小径居民"}},a4ac9bea={q="为什么叫北门小径？",a="这条通道得名于北门哨岗及其地理位置：贯穿丹莫罗与洛克莫丹之间山脊的两条主要隧道中，它位于北侧，与南面的南门小径相对应。",al={"为什么叫北门小径","北门小径名称含义","北门名称由来"}}},fp="15,199,25.369.0,32.224.0,21.156.0,42.173.0"}
P.entries["subzone:north-tide-s-hollow"] = {n="北流谷",s="北流谷是银松森林中一处崎岖的荒野凹地，位于瑟伯切尔正北面。这里被效忠于背叛者大法师阿鲁高的野性月怒狼人所盘踞，这片林间空地是这些潜伏在海岸丛林中的野兽的行动基地。",h="北流谷是银松森林中一处崎岖的荒野凹地，位于瑟伯切尔正北面。这里被效忠于背叛者大法师阿鲁高的野性月怒狼人所盘踞，这片林间空地是这些潜伏在海岸丛林中的野兽的行动基地。",kw={"阿鲁高","月怒","北流谷","瑟伯切尔","银松森林","狼人"},ang={["race:Undead"]="月怒狼人盘踞在北流谷，距离瑟伯切尔的位置近得令人不安，这对被遗忘者在银松森林的统治地位和后勤补给线构成了直接威胁。"},sec={{t="野性的立足点",b="北流谷隐藏在被遗忘者定居点瑟伯切尔以北的茂密树林中，被野蛮的月怒狼人所占据。这些通过大法师阿鲁高鲁莽的魔法被带入洛丹伦的野性狼人，在峡谷各处建立了简陋的营地。这些粗糙的庇护所仅由这些强悍野兽所需的最基本必需品构成，为它们提供了距离被遗忘者交通要道极近的前沿阵地。"},{t="影牙的阴影之下",b="与普通的丛林掠食者不同，北流谷的狼人听命于从影牙城堡散发出的邪恶意志。它们靠近西海岸线和穿过银松森林的主干道，对试图稳固该地区的被遗忘者信使和巡逻队构成了持续的威胁。"}},faq={{q="北流谷在哪里？",a="北流谷位于银松森林西部，就在被称为瑟伯切尔的被遗忘者前哨站北面，靠近海岸悬崖。",al={"北流谷位置","北流谷在哪里","峡谷位置"}},{q="北流谷里住着什么生物？",a="这片峡谷中到处都是月怒狼人，这些超自然的狼形野兽被束缚在大法师阿鲁高的疯狂意志之下。",al={"谁住在这里","北流谷的敌人","北流谷的怪物"}},{q="为什么狼人住在这里的简陋营地里？",a="尽管狼人凶残狂野，但月怒狼人仍保留了足够的狡诈来组织基础的营地。由于天生坚韧强悍，它们只需要最原始的避难所和生存必需品就能在洛丹伦的荒野中生存。",al={"狼人营地","为什么狼人有帐篷"}},{q="谁控制着该地区的狼人？",a="北流谷的月怒狼人效忠于大法师阿鲁高，是他将狼人召唤到了洛丹伦，并从影牙城堡指挥着它们。",al={"谁领导着狼人","狼人主人"}}},fp="19,158,16.277.0,25.217.0,29.111.0,43.105.0,43.187.0,37.99.0"}
P.entries["subzone:north-tide-s-run"] = {n="北流海岸",s="北流海岸是银松森林西北部风起云涌的海岸线，紧邻无尽之海。这片沙滩上有一艘半沉的失事船只，是一处鲜为人知的隐秘试炼场，供寻求与水域和谐共处的旅行德鲁伊使用。",h="北流海岸是银松森林西北部风起云涌的海岸线，紧邻无尽之海。这片沙滩上有一艘半沉的失事船只，是一处鲜为人知的隐秘试炼场，供寻求与水域和谐共处的旅行德鲁伊使用。",kw={"水栖形态","德鲁伊试炼","无尽之海","北流海岸","沉船","银松森林"},ang={["class:Druid"]="对于牛头人德鲁伊来说，这片寒冷的海岸代表着一个至关重要的成人礼，这里存放着掌握海狮形态所必需的沉没试炼组件。",["race:Tauren"]="北流海岸远离莫高雷温暖的平原，是洛丹伦为数不多能让年轻牛头人在精神旅程早期前往的地方之一。"},sec={{t="孤寂之岸",b="北流海岸沿着银松森林的西北边缘延伸，由冰冷的沙滩、汹涌的浪潮和无尽之海的一角组成。这里最显眼的标志是浅滩上那艘半沉的失事船只，正摇摇欲坠地倾斜在水中。"},{t="海狮之水",b="尽管环境荒凉，但对于行走在塞纳留斯之道的部落新兵来说，北流海岸具有神圣的重要性。年轻的牛头人德鲁伊会被指引至此进行朝圣，找回被海浪卷走的沉没圣物，以此考验他们的肺活量和耐力，从而获得水栖形态的祝福。"}},faq={{q="什么是北流海岸？",a="它是银松森林的西北岸线和大陆架，毗邻无尽之海。其特征是沉船、潮汐水域以及荒凉、宁静的沙滩。",al={"北流海岸","北流海岸在哪里","这片海滩是什么"}},{q="为什么德鲁伊会来到北流海岸？",a="牛头人德鲁伊会在试炼期间前往此处朝圣，与海洋之灵交流。通过勇敢地潜入海岸附近的深处寻找遗失的坠饰碎片，他们可以获得变形为水栖形态的力量。",al={"银松森林海滩德鲁伊任务","银松森林水栖形态","为什么牛头人在这里"}},{q="水里的沉船是什么？",a="那艘失事船只是一艘半沉在沙滩外浅滩里的船骸。它的存在是为搜寻海岸的旅行者提供了一个导航标志。",al={"北流海岸沉船","银松森林海滩沉船","失事船只"}}},fp="16,160,14.189.0,22.196.0,25.167.0,39.158.0,37.115.0"}
P.entries["subzone:northdale"] = {n="北谷",s="北谷是位于东瘟疫之地圣光之愿礼拜堂以北，靠近奎尔萨拉斯边界的一处废墟定居点。这里曾经是一个繁荣的北方小镇，如今却已支离破碎，被女妖、暗影守望者和堕落的元素生物所占据。北谷最为人所知的身份，是泰兰·弗丁在此放弃白银之手骑士团，转而投向血色十字军狂热信仰的痛苦转折点。",h="北谷是位于东瘟疫之地圣光之愿礼拜堂以北，靠近奎尔萨拉斯边界的一处废墟定居点。这里曾经是一个繁荣的北方小镇，如今却已支离破碎，被女妖、暗影守望者和堕落的元素生物所占据。北谷最为人所知的身份，是泰兰·弗丁在此放弃白银之手骑士...",kw={"女妖","无眼守望者","弗丁","北谷","瘟疫之地","血色十字军","白银之手","泰兰"},ang={["class:Paladin"]="对于圣光的骑士来说，北谷是一座令人清醒的纪念碑，记录着信仰的丧失——这片土地，正是泰兰·弗丁为了追求复仇而抛弃白银之手的地方。",["race:Human"]="北谷烧焦的地基和游荡的女妖，代表了又一个被天灾军团屠戮并占领的洛丹伦社区。"},sec={{t="悲伤之镇",b="北谷坐落在圣光之愿礼拜堂以北的山丘之上，曾经是通往奎尔萨拉斯的北侧大道上一个宁静的社区。第三次战争使其化为残垣断壁，家园不再温存，居民也惨遭屠戮或流离失所。如今，哀嚎的女妖在破败的墙垣间游荡，隐形的无眼守望者潜伏在黑暗中，窥视着受诅咒的道路。就连附近的湖泊也未能幸免于瘟疫的侵蚀，水面上翻涌着扭曲且堕落的水元素。"},{t="被遗弃的誓言",b="在弗丁家族的悲剧史中，北谷有着黑暗的意义。洛丹伦陷落，白银之手骑士团解散后，年轻的泰兰·弗丁站在这些破碎的街道上，正式抛弃了他父亲的教诲。他认为白银之手的残部过于软弱，无法铲除亡灵天灾，于是放弃了自己的神圣职责，加入了激进的血色十字军——这一决定成为了血色十字军掌控壁炉谷的关键节点。"}},faq={{q="北谷发生了什么？",a="北谷在第三次战争中，当亡灵天灾横扫洛丹伦时被摧毁。这里的建筑被夷为平地，居民倒在了瘟疫之下，只留下一片石块堆砌的躯壳，如今被复仇的怨灵和堕落的元素所占据。",al={"北谷为什么会成为废墟","北谷历史","什么是北谷"}},{q="这里发生了什么重大事件？",a="泰兰·弗丁正是在这里宣布脱离白银之手骑士团。由于对洛丹伦的陷落感到绝望，他在此抛弃了圣骑士的誓言，并向新生的血色十字军宣誓效忠。",al={"泰兰·弗丁北谷","泰兰发生了什么","白银之手骑士团北谷"}},{q="如今有哪些生物在废墟中游荡？",a="城镇废墟中到处都是效忠于天灾军团的哀嚎女妖和肉眼不可见的无眼守望者。邻近的水域也遭到污染，充斥着堕落的水元素。",al={"北谷怪物","北谷敌人","北谷有什么"}},{q="北谷位于何处？",a="北谷位于东瘟疫之地的东北部，就在圣光之愿礼拜堂的北面，通往奎尔萨拉斯的萨拉斯小径东南方。",al={"北谷位置","北谷在哪里","寻找北谷"}}},fp="9,237,16.430.0,17.375.1,27.219.0,39.187.0,37.142.0,27.139.0"}
P.entries["subzone:northfold-manor"] = {n="诺斯弗德农场",s="诺斯弗德农场是一座破败的农业庄园，位于阿拉希高地的西北边缘。这里曾是激流堡陷落前一处繁荣的人类家园，而如今，辛迪加的犯罪分子占据了这片土地，并在进行着令人不安的黑暗勾当。",h="诺斯弗德农场是一座破败的农业庄园，位于阿拉希高地的西北边缘。这里曾是激流堡陷落前一处繁荣的人类家园，而如今，辛迪加的犯罪分子占据了这片土地，并在进行着令人不安的黑暗勾当。",kw={"阿拉希高地","血石","诺斯弗德农场","辛格","激流堡","辛迪加","托尔甘"},ang={["class:Shaman"]="笼罩在诺斯弗德农场上空的恶魔残余力量扰乱了自然元素，使靠近这里的萨满祭司感到精神不安并引发炽烈的怒火。",["faction:Horde"]="落锤镇的萨满祭司们密切注视着诺斯弗德农场，并派遣勇士去夺取辛迪加用来涉足恶魔召唤的血石护身符。"},sec={{t="强盗巢穴",b="诺斯弗德农场坐落在索拉丁之墙隘口附近起伏的高地上，曾经支撑着激流堡王国。在该王国分崩离析后的混乱时期，流离失所的奥特兰克贵族和辛迪加的歹徒们占据了这里的庄园主屋、谷仓和农田，将其作为行动基地。辛迪加的雇佣兵、拦路强盗和寻路者们不再耕种作物，而是利用这个农场在道路上伏击过往行人，并协调他们在阿拉希各地的势力。"},{t="恶魔的阴影",b="在日常的盗窃和武装对抗背后，诺斯弗德农场还隐藏着更险恶的企图。恶魔召唤的残留气息笼罩着整个农场，该地区的敏感施法者和萨满祭司对此有着强烈的感知。地面上散落着被丢弃的血石护身符——这是一种用于驱动黑暗咒语的强大护身符——这表明这里的辛迪加盗贼正纠缠于超越普通强盗勾当的恶魔魔法之中。"}},faq={{q="是谁控制了诺斯弗德农场？",a="这座庄园已落入辛迪加之手。辛迪加是一个由失势的奥特兰克贵族、强盗和流氓雇佣兵组成的组织，他们现在将此地作为武装营地。",al={"谁住在这里","谁拥有诺斯弗德","辛迪加农场"}},{q="这里在进行什么黑暗魔法仪式？",a="对魔法能量敏感的访客可以探测到恶魔召唤的残留痕迹。驻扎在庄园里的辛迪加部队持有血石护身符，这些护身符被用来引导和辅助危险的恶魔仪式。",al={"诺斯弗德的恶魔","血石","他们正在召唤什么"}},{q="部落为什么关心这个农场？",a="落锤镇的巨魔萨满祭司托尔甘察觉到高地上正在酝酿一种反常的干扰。对源头的调查直接将他引向了诺斯弗德农场，这促使部落开始调查辛迪加的邪教活动。",al={"部落对诺斯弗德的兴趣","托尔甘为什么关心"}},{q="辛格是谁？",a="辛格是一个难以捉摸的辛迪加人物，偶尔能看到他潜伏在诺斯弗德农场的主屋内，混迹在其他强盗之中。",al={"辛格","辛格稀有","辛格是谁"}}},fp="15,194,17.478.0,18.336.1,29.162.0,40.186.0,40.223.0,14.108.0"}
P.entries["subzone:northpass-tower"] = {n="北地哨塔",s="北地哨塔是一座位于东瘟疫之地北部，通往奎尔萨拉斯道路上的洛丹伦废弃侦查哨塔。它在第三次战争中被摧毁，但至今仍俯瞰着通往精灵领地的北方大道。",h="北地哨塔是一座位于东瘟疫之地北部，通往奎尔萨拉斯道路上的洛丹伦废弃侦查哨塔。它在第三次战争中被摧毁，但至今仍俯瞰着通往精灵领地的北方大道。",kw={"东瘟疫之地","洛丹伦","北地哨塔","奎尔萨拉斯","天灾军团","侦查哨塔"},ang={["faction:Alliance"]="北地哨塔是洛丹伦陷落的堡垒之一，也是通往精灵领地的道路上一座破碎的哨兵。",["faction:Horde"]="对于部落而言，像北地哨塔这样的废墟展现了天灾军团是如何彻底摧毁北方王国的防御体系的。"},sec={{t="北方哨兵",b="北地哨塔由洛丹伦王国建造，旨在守卫通往奎尔萨拉斯的重要通道。在天灾军团入侵期间，这座哨塔沦为残垣断壁。尽管石墙已然破碎，但其高处的地势依然具有巨大的战略价值，俯瞰着斯坦索姆受诅咒的郊区与遥远的精灵领地之间那条被瘟疫笼罩的边境。"},{t="无声的守望",b="如今哨塔内已无驻军。它破碎的墙体伫立在一条如今受天灾军团盘踞的道路旁，提醒着人们洛丹伦曾经对通往奎尔萨拉斯的道路所进行的守望。"}},faq={{q="北地哨塔最初是为何而建的？",a="它最初由洛丹伦王国建造，作为观察哨所，用于监视通往奎尔萨拉斯精灵王国的北方道路。",al={"什么是北地哨塔","北地哨塔历史","北地哨塔为何而建"}},{q="为什么北地哨塔会成为废墟？",a="它在第三次战争的天灾军团入侵中，连同洛丹伦北部其他的防御设施一起被摧毁，只留下了残破的砖石和脚手架。",al={"谁摧毁了北地哨塔","北地哨塔为何破碎"}},{q="现在有人占据北地哨塔吗？",a="没有。这座哨塔在天灾军团入侵时与洛丹伦的北部防御体系一同被毁，如今作为一座空旷的废墟伫立在通往北方的道路旁。",al={"为何争夺北地哨塔","谁控制着北地哨塔"}},{q="经过北地哨塔的道路通向哪里？",a="这条路向北直通萨拉斯边境和奎尔萨拉斯的南部领土。",al={"经过北地哨塔的道路","北方道路通向哪里"}}},fp="15,170,17.262.0,14.183.0,46.116.0,32.134.0,37.138.0,46.113.0"}
P.entries["subzone:northridge-lumber-camp"] = {n="北山伐木场",s="北山伐木场是一座活跃的锯木厂，坐落在西瘟疫之地北部靠近壁炉谷的山丘之中。目前由血色十字军占领并加固，它为维持周边据点提供了至关重要的木材。联盟和部落都将此设施视为削弱这些狂热者地区基础设施的首要目标。",h="北山伐木场是一座活跃的锯木厂，坐落在西瘟疫之地北部靠近壁炉谷的山丘之中。目前由血色十字军占领并加固，它为维持周边据点提供了至关重要的木材。联盟和部落都将此设施视为削弱这些狂热者地区基础设施的首要目标。",kw={"壁炉谷","莱文","木材","锯木厂","北山","瘟疫之地","血色十字军","白蚁"},ang={["faction:Alliance"]="虽然血色十字军声称要对抗亡灵，但他们极端的排外主义使他们成为联盟在洛丹伦北部进行侦察和地区行动的一大威胁。",["faction:Horde"]="对于被遗忘者及其部落盟友来说，扰乱十字军的伐木行动可以削弱壁炉谷，并将这些狂热者逼回他们的据点。"},sec={{t="为十字军供能",b="北山伐木场位于壁炉谷下方的道路旁，是血色十字军至关重要的后勤枢纽。尽管挥之不去的瘟疫正在扼杀周边的森林，伐木场仍在砍伐和加工当地的木材，以建造防御工事、维修瞭望塔，并为十字军在洛丹伦的战争行动提供物资。该锯木厂由狂热的劳工和卫兵重兵把守，严密防范天灾军团和外来入侵者。"},{t="破坏目标",b="由于壁炉谷极度依赖这些木材来维持其防御，外部势力正积极密谋对其进行破坏。联盟指挥官和部落侦察兵都意识到，对加固的十字军阵地进行公开突袭代价高昂。相反，特工们倾向于采取非常规的破坏手段——例如将贪婪的蛀木白蚁释放到锯木厂的木材储备中——从内部悄然腐蚀十字军的补给。"}},faq={{q="谁控制着北山伐木场？",a="血色十字军目前控制并运营着该伐木场，利用其卫兵和劳工为附近的壁炉谷采伐木材。",al={"谁在运营北山","谁控制着锯木厂","北山派系"}},{q="为什么这座锯木厂很重要？",a="它为维持血色十字军在西瘟疫之地北部的防御工事和哨所提供了必要的木材和建筑材料。",al={"为什么北山很重要","北山的意义","这个营地是做什么的"}},{q="为什么联盟和部落想要破坏它？",a="双方阵营都认为激进且狂热的血色十字军是瘟疫之地中一个危险的威胁。剥夺他们的木材供应可以在无需付出高昂代价进行直接入侵的情况下，削弱他们加固壁炉谷的能力。",al={"为什么袭击北山","白蚁任务","为什么要毁掉木材"}},{q="第三次战争前是谁在经营这家锯木厂？",a="在洛丹伦王国陷落于天灾军团之前，当地的平民家庭居住在这里，并以这家锯木厂为业，过着宁静的地区生活。",al={"谁拥有北山伐木场","北山锯木厂的历史"}}},fp="22,216,19.418.0,19.418.0,36.128.0,34.155.0,50.191.0,38.142.0"}
P.entries["subzone:northshire-abbey"] = {n="北郡修道院",s="北郡修道院是一座历史悠久的修道院，坐落在艾尔文森林北部的山脚下，掩映在北郡山谷之中。在第一次战争中被毁后，它经过重建，如今已成为北郡兄弟会的精神核心，也是响应暴风城王国号召的新兵们的首要训练中心。",h="北郡修道院是一座历史悠久的修道院，坐落在艾尔文森林北部的山脚下，掩映在北郡山谷之中。在第一次战争中被毁后，它经过重建，如今已成为北郡兄弟会的精神核心，也是响应暴风城王国号召的新兵们的首要训练中心。",kw={"修道院","兄弟会","教士","迪菲亚","艾尔文","法奥","北郡","山谷"},ang={["class:Paladin"]="北郡代表了大主教阿隆苏斯·法奥和早期教士们的遗产，正是他们的牺牲为白银之手骑士团奠定了基础。",["race:Human"]="对于暴风城的人类来说，北郡修道院是你旅程的起点，在这里，王国韧性与奉献的历史欢迎每一位拿起武器的新兵。"},sec={{t="信仰与废墟的传承",b="几个世纪前，来自洛丹伦的牧师们向南跋涉，进入暴风城王国传播圣光的信仰，并建立了北郡教士圣职会及其修道院。这座修道院很快成为王国生活的重要支柱，这里的人们不仅照料病患，甚至在守护者麦迪文陷入昏迷的那些年里，也由他们负责照顾。在第一次战争中，修道院屡遭强盗和兽人部落的袭击，最终被彻底夷为平地。第二次战争中，洛丹伦联盟收复了该地区，大主教阿隆苏斯·法奥帮助重建了这座圣所，并将这里的守卫者重新组建为北郡兄弟会。"},{t="训练场",b="如今，北郡修道院已成为志愿者、民兵新兵和希望保卫饱受战火蹂躏的暴风城的初学者的基地。修道院分为大厅、Hall of Arms和图书馆侧翼，这里驻扎着教导武艺、奥术和神圣艺术的导师，而侦察兵和潜行者则在外面的院子里进行训练。尽管有白银之手骑士团的警惕守护，此地的和平依然脆弱。狗头人在附近的矿井肆虐，凶猛的狼群在果园游荡，迪菲亚潜行者的特工们则在山谷的道路上潜伏，掠夺着修道院珍藏的古老卷轴和神圣典籍。"}},faq={{q="什么是北郡兄弟会？",a="北郡兄弟会是一个宗教组织，由以北郡修道院为基地的教士、牧师和圣骑士组成。它最初由几个世纪前来自洛丹伦的传教士创立，在第一次战争后由大主教阿隆苏斯·法奥重建，旨在训练忠诚的保卫者并保存神圣的经文。",al={"谁管理北郡修道院","北郡教士","北郡兄弟会背景故事"}},{q="为什么北郡修道院在第一次战争中被摧毁？",a="在第一次战争中，这座修道院对暴风城具有战略和精神上的双重重要性。兽人军队煽动人类强盗对其发动攻击，在半兽人迦罗娜被短暂囚禁于此后，兽人部落发起了一场大规模的猛攻，将这片圣地夷为平地。在整个战争期间，它一直处于废墟状态，直到联盟驱逐了兽人氏族并对其进行了重建。",al={"谁摧毁了北郡修道院","第一次战争与北郡","北郡发生了什么"}},{q="为什么修道院外会有迪菲亚强盗和狗头人？",a="暴风城的军队忙于保卫遥远的边境，导致周边地区防守薄弱。投机的狗头人侵占了当地的金矿，而迪菲亚潜行者则利用防守空虚的机会抢劫过往行人，骚扰当地葡萄园，并洗劫修道院的图书馆以窃取奥术典籍和圣物。",al={"为什么北郡遭到攻击","北郡的狗头人","北郡外的迪菲亚"}},{q="北郡修道院和死亡矿井之间有什么联系？",a="在第一次战争期间，一位名叫图洛克的食人魔酋长从北郡修道院偷走了神圣的《神圣之书》，并退守到了死亡矿井中。安度因·洛萨爵士率领一支远征队深入矿井夺回这本神圣经文，结果被困其中，直到一支皇家救援队将他救出，并把经文归还给了修道院妥善保管。",al={"北郡的神圣之书","北郡与死亡矿井背景","安度因·洛萨与死亡矿井"}}},fp="16,248,26.564.0,20.509.0,38.285.0,52.323.0,59.313.0,66.289.0"}
P.entries["subzone:northshire-valley"] = {n="北郡山谷",s="北郡山谷坐落在艾尔文森林的北部群山之中，是暴风城王国新兵的摇篮与训练场，环境静谧安宁。山谷四周被天然屏障环绕，这里坐落着历史悠久的北郡修道院、肥沃的农场以及资源丰富的回音山矿洞。尽管表面上一派祥和，但山谷正面临着越来越大的不安，到处游荡的劫匪、横行的狗头人以及流离失所的掠食者都威胁着这里的安全。",h="北郡山谷坐落在艾尔文森林的北部群山之中，是暴风城王国新兵的摇篮与训练场，环境静谧安宁。山谷四周被天然屏障环绕，这里坐落着历史悠久的北郡修道院、肥沃的农场以及资源丰富的回音山矿洞。尽管表面上一派祥和，但山谷正面临着越来越大...",kw={"修道院","迪菲亚潜行者","回音山矿洞","艾尔文森林","狗头人","玛克布莱德","北郡山谷","北郡农场","维里"},ang={["faction:Alliance"]="北郡是大联盟关键的新兵征召与恢复基地，训练着下一代保卫者，以稳定王国的核心区域。",["race:Human"]="对于暴风城的人类来说，北郡山谷是他们踏上旅程的起点，来到修道院的庭院中，响应王国的召唤。"},sec={{t="一处避世的圣所",b="北郡山谷四周被几乎无法逾越的山脊所包围，唯一的出路是一条向南通往闪金镇和艾尔文森林其他地区的公路，那里设有一座戒备森严的门楼。一条清澈的小河蜿蜒穿过牧场，最后汇入南边的水晶湖。在山谷中心矗立着北郡修道院，这是一座古老的圣所，人们在此传授圣光之道，新兵们则由白银之手骑士团和经验丰富的老兵进行训练。在修道院围墙之外，坐落着物产丰饶的北郡农场和回音山矿洞，它们构成了一个自给自足的暴风城领地，仿佛远离了外界战火的纷扰。"},{t="潜伏的威胁",b="即使是这处避风港，也感受到了暴风城兵力吃紧带来的压力。治安官玛克布莱德和他的暴风城卫兵分遣队竭尽全力试图维持山谷的秩序。成群的狼从受到污染的暮色森林北上，在周边的树林里徘徊；而如害虫般的狗头人则占领了回音山矿洞的隧道。更糟糕的是，效忠于迪菲亚潜行者的蒙面暴徒们公开骚扰农场，并威胁到修道院的地界，迫使当地指挥官不得不征召每一位抵达大门且身体健康的平民。"}},faq={{q="为什么北郡山谷有重兵把守？",a="山谷内拥有北郡修道院，它是暴风城军队关键的信仰中心和训练场，此外还有回音山矿洞和农场等重要的本地资源。由于暴风城的军事力量捉襟见肘，治安官玛克布莱德在南侧隘口维持着一座戒备森严的门楼，以防威胁在山谷与艾尔文森林大部之间蔓延。",al={"为什么要守卫北郡","北郡的门楼","谁在保卫北郡"}},{q="山谷里的狼是从哪儿来的？",a="维里副队长指出，最近成群的狼越过了河流，从南边阴暗的暮色森林逃入了山谷。暮色森林中蔓延的黑暗迫使野兽逃离了栖息地，闯入了原本宁静的牧场。",al={"为什么有这么多狼","狼群出没","来自暮色森林的狼"}},{q="为什么狗头人要攻击回音山矿洞？",a="狗头人是机会主义的掘洞生物，被地下的矿脉所吸引。随着王国巡逻队的兵力减少，一群狗头人趁机占领了回音山矿洞，觊觎那里的黄金和蜡烛，并强行将人类矿工驱逐出了隧道。",al={"回音山矿洞的狗头人","为什么北郡有狗头人","狗头人问题"}},{q="那些骚扰农场的强盗是谁？",a="在米莉·奥斯沃斯农场附近活动的盗贼是迪菲亚潜行者的走狗。他们潜伏在山谷边缘地带，旨在破坏物资供应、骚扰当地农民，并试探修道院的防御。",al={"农场的强盗","北郡的迪菲亚","红面罩暴徒"}},{q="第二次战争期间北郡发生了什么？",a="在第二次战争期间，北郡修道院曾落入敌手，并一度被古尔丹的暮光之锤氏族用作指挥部，直到后来联盟收复并修复了山谷。",al={"北郡与第二次战争","北郡的暮光之锤","北郡的古尔丹"}},{q="如何离开北郡山谷？",a="徒步离开的唯一通路是向南穿过设有门楼的公路。通过这道大门，旅行者将直接进入艾尔文森林中部，沿着主路前往闪金镇。",al={"离开北郡","前往闪金镇的道路","如何离开"}}},fx={["9b50c77b"]={q="北郡山谷是什么地方？",a="北郡山谷是一处隐蔽的山间谷地，坐落在艾尔文森林北部。这里最为人熟知的便是北郡修道院及其周围的葡萄园。山谷四周峭壁环立，唯一的入口是南面设有防御工事的关口，是暴风城王国训练和招募新晋守卫者的主要场所。",al={"北郡山谷在哪里","北郡山谷介绍","我在北郡哪里"}},["3a470446"]={q="北郡山谷属于暴风城吗？",a="是的。北郡山谷位于艾尔文森林腹地，而这片森林正是暴风城王国的核心领土。这里的驻军高悬暴风城的旗帜，执行王国的法律，并直接向王国的上级军事指挥机构汇报。",al={"北郡属于暴风城吗","暴风城拥有北郡吗"}},["52057ec0"]={q="为什么所有新兵都在北郡山谷受训？",a="山谷四周高崖环绕，是一处有屏障守护、自成一体的避风港，非常适合用作集结地。经验丰富的治安官、职业导师，以及提供精神指引的北郡兄弟会都汇聚在修道院，为新兵提供走向更广阔森林之前所需的一切训练。",al={"为什么在这里训练","新兵为什么来北郡"}},["0f9fef82"]={q="我作为新兵，为什么会来到北郡山谷？",a="你来到这里，是为了响应王国对守卫者的迫切需求。暴风城的正规军分散在战事不断的边境，兵力捉襟见肘，当局因此开放北郡修道院，训练所有愿意宣誓效力、保卫王国的勇士。",al={"我为什么在这里","新兵为什么在这里","我为何来到这里"}},["0fbb181a"]={q="北郡修道院是什么地方？",a="北郡修道院是一处历史悠久的圣地，也是北郡兄弟会的传统驻地，这个教士修会由圣光教会的传教士在数百年前创立。除了履行宗教职责，修道院还设有图书馆、武器大厅，以及训练刚刚宣誓效忠联盟的勇士的营舍。",al={"北郡修道院介绍","修道院是什么"}},["385ef21f"]={q="谁掌管北郡修道院？",a="教士负责修道院的宗教事务，而治安官杜格拉斯·玛克布莱德则代表暴风城军队，指挥此地的驻军，统管整个山谷的防务。",al={"谁领导修道院","修道院的领袖"}},ac0d723b={q="为什么教堂外面驻扎着军队？",a="近来的动乱迫使军队直接进驻修道院。强盗占据了毗邻的葡萄园，狗头人也钻进了附近的矿洞，没有军队直接介入，教士们已无力守护这片圣地。",al={"修道院为什么有士兵","教堂为什么有驻军"}},["2babcb98"]={q="北郡山谷这一带由谁负责？",a="治安官杜格拉斯·玛克布莱德统管北郡山谷的防务。他驻守在修道院内，指挥驻军，招募前来报到的新兵，并协调各方行动，抵御不断侵入山谷的威胁。",al={"这里由谁负责","北郡的指挥官","谁掌管北郡"}},["5231335a"]={q="治安官玛克布莱德向谁负责？",a="治安官玛克布莱德是暴风城军队的一名军官，为王室效力。他麾下的北郡驻军与驻扎在闪金镇的部队一道，承担着艾尔文森林的防务。",al={"玛克布莱德的上级","谁是玛克布莱德的上司"}},["0040026b"]={q="“身边的危机”讲的是什么？",a="这个说法指的是王国境内令人担忧的治安崩溃。暴风城面对的并非来自境外的大军，而是就在这片神圣腹地滋生的颠覆势力、为非作歹的盗贼和有害生物。",al={"身边的危机的含义","身边的危机是什么任务","内部有什么威胁"}},["3e58992c"]={q="狗头人是什么？",a="狗头人是生活在地下、外形似鼠的人形生物，以痴迷挖掘坑道，以及势单力薄时的胆怯而闻名。它们在王国的阴暗角落搜寻矿物和可用之物，并凶狠地抵御任何闯入地下巢穴的外来者。",al={"狗头人的背景","狗头人是什么","狗头人是谁"}},["1071f0ff"]={q="回音山矿洞是什么地方，以前属于我们吗？",a="直到不久前，回音山矿洞还是一座由王国开采、产量丰厚的矿场。狗头人从周围的山丘涌入坑道，赶走了人类矿工，将这里变成了有武装守卫的聚居地。",al={"回音山矿洞原来属于谁","回音山属于我们吗","回音山是什么"}},ffddbb43={q="为什么要我杀这么多狗头人，它们到底做了什么？",a="狗头人占据回音山矿洞，切断了宝贵资源的供应，还在修道院旁建立了一处危险的巢穴。如果放任不管，它们的挖掘活动可能破坏山谷的地基稳定，它们也会大量涌上附近的道路。",al={"为什么杀狗头人","为什么消灭狗头人"}},c35515fc={q="那些戴红色面巾的家伙是谁？",a="他们是迪菲亚潜行者的成员，在当地由加瑞克·帕德弗特率领。他们曾是石匠行会中技艺精湛的工匠和劳工，参与了暴风城的重建，却在一场激烈的报酬纠纷后落草为寇，起兵反抗王室。",al={"红色面巾强盗","谁戴红色面巾","北郡的红色面罩"}},c05e8af1={q="为什么迪菲亚强盗敢在离暴风城这么近的地方袭击？",a="王国军队远征在外，境内驻军又物资匮乏，迪菲亚因此愈发肆无忌惮，在艾尔文各地强占农场和果园。北郡的葡萄园为他们提供了食物、美酒，以及一处就在王室眼皮底下的集结地。",al={"暴风城附近为什么有强盗","迪菲亚为什么在北郡"}},["660e62c8"]={q="修道院为什么会有术士训练师？",a="杜希拉·拉萨雷在北郡的墓地训练术士，远离修道院的教士和圣骑士。她身处偏僻之地，也反映出那些献身于圣光的人对邪能魔法的疑虑。",al={"修道院为什么有术士","这里为什么有术士训练师"}},["808e49f9"]={q="为什么大家都让我这个新手去做这些事？",a="暴风城卫队的兵力早已不堪重负。士兵们守卫着重要边境，王国军队又远在他乡，当地驻军根本没有足够的人手清理每一座矿洞、守护每一片葡萄园，只能让你这样的新兵成为他们目前最可靠的防线。",al={"为什么选我这个新手","为什么所有活都由我来干","为什么找新兵"}},["99bf7d8e"]={q="我是怎么来到北郡山谷的？",a="你是为寻找北郡修道院而来，这里是为愿意拿起武器、保卫暴风城王国的人设立的主要招募和训练场所。这片宁静的山谷四周高山环绕，入口有设防的关隘守卫，是新晋守卫者最初的集结地。无论你是徒步穿过艾尔文森林而来，还是响应王室的征兵号召，治安官玛克布莱德和修道院的导师们都在等着你这样满怀热忱的人前来报到。",al={"我是怎么来到这里的","我怎么会到了这里","我为什么来到北郡"}},bb6d78ec={q="我在北郡山谷应该做些什么？",a="你来到这里，是要在修道院训练师的指导下磨炼武艺或魔法，同时协助当地驻军。治安官杜格拉斯·玛克布莱德和暴风城卫队人手不足，急需新兵处理附近的威胁。在向南进入艾尔文森林之前，你需要清剿从林缘逼近的凶猛野狼，从入侵的狗头人手中夺回回音山矿洞，并保护米莉·奥斯沃斯的葡萄园，抵御潜伏在附近的迪菲亚潜行者匪徒。",al={"我在这里该做什么","我在这里的目标是什么","我在北郡该做什么"}},["11801d7a"]={q="为什么新的人类角色会从北郡山谷开始冒险？",a="几个世纪以来，北郡修道院始终是王国内人类坚韧精神的重要支柱，既是北郡兄弟会的家园，也是白银之手骑士团的集会之所。如今，暴风城的正规军兵力捉襟见肘，国王瓦里安·乌瑞恩又神秘失踪，渴望保卫家园的年轻人类便被指引至这处僻静的庇护所，开始接受正式训练，领取介绍信，并证明自己对王室的忠诚。",al={"人类为什么从这里开始","人类角色为什么从北郡开始","北郡为什么是人类起始地"}}},fp="17,317,20.374.0,20.454.0,44.365.0,49.202.0,42.243.0,44.189.0,50.191.0,35.157.0"}
P.entries["subzone:northshire-vineyards"] = {n="北郡农场",s="北郡农场是位于北郡修道院以东的谷地避风盆地中的葡萄种植园。尽管这里曾经是牧师们安宁的葡萄酒产地，但现在这些农田已经落入迪菲亚潜行者及其当地匪徒的控制之中。",h="北郡农场是位于北郡修道院以东的谷地避风盆地中的葡萄种植园。尽管这里曾经是牧师们安宁的葡萄酒产地，但现在这些农田已经落入迪菲亚潜行者及其当地匪徒的控制之中。",kw={"迪菲亚","艾尔文","加瑞克·帕德弗特","葡萄","米莉·奥斯沃斯","北郡山谷","北郡农场"},ang={["faction:Alliance"]="这些宁静的葡萄园中的动荡表明，混乱已经深入到即使是暴风城王国受保护最严密的角落。",["race:Human"]="对于许多第一次闯荡世界的年轻人类来说，被占领的葡萄园是他们第一次直接接触到迪菲亚潜行者的险恶与势力。"},sec={{t="被掠夺的收成",b="北郡农场位于北郡修道院以东，隔溪相望，代表着山谷中宁静的农业生活。农田原本由像米莉·奥斯沃斯这样的当地工人照料，但日益加剧的动乱使他们失去了保护。隶属于迪菲亚潜行者的强盗在名为加瑞克·帕德弗特的亡命之徒的指挥下，占领了这些土地。这些窃贼不仅仅是进行破坏，他们占据农田是为了掠夺收成，剥夺当地农民的生计，并为迪菲亚潜行者的新招募人员提供了一个就在修道院眼皮底下的立足点。"}},faq={{q="现在是谁控制着北郡农场？",a="属于迪菲亚潜行者的窃贼和暴徒占领了农田。他们的当地首领是加瑞克·帕德弗特，一个被通缉的潜行者，他指挥着对庄稼的掠夺，并恐吓着当地的工人。",al={"谁在葡萄园","谁占领了北郡农场","谁是加瑞克·帕德弗特"}},{q="为什么修道院任由强盗在农田里横行霸道？",a="随着国王瓦里安·乌瑞恩的失踪，暴风城的军事资源已经极度匮乏。修道院守卫撤回以保卫修道院本身并监视山谷道路，迫使当地农民不得不依靠新到的冒险者来找回被盗的物资。",al={"为什么没有暴风城守卫","为什么修道院不保卫葡萄园"}},{q="米莉·奥斯沃斯是谁？",a="米莉·奥斯沃斯是一位在葡萄园工作的当地农民。当迪菲亚强盗闯入并夺走葡萄收成时，她被赶走了，现在她正在寻找勇敢的旅行者进入田野，找回她被掠夺的板条箱。",al={"米莉·奥斯沃斯","米莉是谁"}}},fx={d5ec287a={q="北郡农场是什么地方？",a="北郡农场是位于北郡山谷内、北郡修道院正东面的农田。平日里，这些田地为当地居民提供葡萄和农产品，但近来因犯罪活动而陷入混乱。",al={"北郡农场是什么","北郡农场概况","关于北郡农场"}},["1ba8e301"]={q="北郡农场发生了什么？",a="迪菲亚潜行者的成员突然袭来，夺取了农场的控制权。在匪徒加瑞克·帕德弗特的带领下，他们赶走当地工人，抢走米莉·奥斯沃斯等居民的收成，并在修道院门前驻扎了武装人员。",al={"北郡农场历史","这里发生了什么","葡萄园的故事"}},af15433a={q="北郡农场危险吗？",a="是的。葡萄田里到处都是加瑞克·帕德弗特麾下充满敌意的迪菲亚匪徒和暴徒。任何不带武器便在葡萄藤间游荡的人，都可能遭到那些霸占这片土地的扒手和强盗的当面袭击。",al={"这里安全吗","北郡农场的危险","葡萄园安全吗"}}},fp="20,179,19.330.0,48.152.0,59.216.0,21.181.0"}
P.entries["subzone:noxious-glade"] = {n="剧毒林地",s="剧毒林地位于圣光之愿礼拜堂以北的山丘中，是一处深藏于盆地中、弥漫着浓缩瘟疫的隐秘之地。这里充斥着有毒的绿色空气和变黑的土壤，是天灾军团在银色黎明眼皮底下建立的一处近距离堡垒。",h="剧毒林地位于圣光之愿礼拜堂以北的山丘中，是一处深藏于盆地中、弥漫着浓缩瘟疫的隐秘之地。这里充斥着有毒的绿色空气和变黑的土壤，是天灾军团在银色黎明眼皮底下建立的一处近距离堡垒。",kw={"枯萎病","东瘟疫之地","圣光之愿礼拜堂","剧毒林地","瘟疫锅","天灾军团","屠宰场","通灵塔"},ang={["class:Paladin"]="这片林地令人警惕地提醒着人们，天灾瘟疫正在以多近的距离蚕食着圣光之愿礼拜堂这片神圣的庇护所，并提供了大量亡灵缝合怪和通灵师供人净化。",["race:Undead"]="被遗忘者勇士会认出这里的屠宰场和瘟疫锅，它们是巫妖王控制下的典型工具，赤裸裸地展示了那些无法挣脱束缚者的下场。"},sec={{t="邪恶的立足点",b="当银色黎明在圣光之愿礼拜堂保持警戒时，一支天灾军团的营地正潜伏在礼拜堂北方的山丘之上。剧毒林地遭受的感染比周围大部分地区都要严重得多：空气中弥漫着浓厚的病态绿雾，土壤也已腐烂成深紫色。在这处凹地内，亡灵建造了通灵塔、一座用来拼凑缝合怪的屠宰场，以及一座不断向大气中喷吐瘟疫的瘟疫锅。"},{t="在黎明的注视下",b="由于其紧邻礼拜堂，这片林地对往来的旅客、信使以及在圣光之愿活动的圣职战士构成了持续的威胁。驻扎在此的天灾军队建造了邪恶的怪兽并酿造毒药，它们不惧阳光，借由周围天然山脊的掩护保持隐蔽，直到粗心的旅行者沿着小路直接闯入它们的核心地带。"}},faq={{q="剧毒林地位于何处？",a="剧毒林地坐落在圣光之愿礼拜堂正北方的山丘中，位于东瘟疫之地的东部地区。",al={"剧毒林地在哪里","剧毒林地位置","如何前往剧毒林地"}},{q="为什么这里的空气和地面颜色不同？",a="与瘟疫之地的其他区域相比，这片林地受到的枯萎病侵蚀极其严重。一个运作中的瘟疫锅和附近的天灾建筑不断向凹地中排放毒素，将大地染成了深紫色，并让这片林地笼罩在有毒的绿色烟雾中。",al={"为什么这里是绿色的","为什么地面是紫色的","剧毒林地枯萎病"}},{q="林地里有什么天灾建筑？",a="这片空地具有典型的天灾建筑风格，包括一座高耸的瘟疫锅、几座通灵塔，以及一座用于组装缝合怪等恐怖构造体的屠宰场。",al={"剧毒林地里有什么","剧毒林地建筑"}},{q="银色黎明知道这个地方吗？",a="知道，但由于他们不仅要防御瘟疫之地各处天灾军团的大规模猛攻，资源还被不断消耗，像剧毒林地这样的哨站仍然是礼拜堂周边地带危险的腐烂口袋。",al={"圣光之愿礼拜堂是否知晓","银色黎明 剧毒林地"}}},fp="13,144,15.414.0,21.294.0,35.128.0,49.232.0,41.144.0,43.171.0"}
P.entries["subzone:noxious-lair"] = {n="腐化之巢",s="腐化之巢是一处位于塔纳利斯西南部沙漠、毗邻安戈洛环形山的下沉式异种虫巢穴。这片区域曾经是一片水源充沛的青翠盆地，但现在已被穴居的森提帕尔虫群所侵扰，其重要资源被掠夺殆尽。如今，这里已成为一座充满酸液的繁殖地，到处都是成群的虫族和丰富的矿脉。",h="腐化之巢是一处位于塔纳利斯西南部沙漠、毗邻安戈洛环形山的下沉式异种虫巢穴。这片区域曾经是一片水源充沛的青翠盆地，但现在已被穴居的森提帕尔虫群所侵扰，其重要资源被掠夺殆尽。如今，这里已成为一座充满酸液的繁殖地，到处都是成群...",kw={"森提帕尔","巢穴","腐化之巢","沙掠者","异种虫","索里德","塔纳利斯"},ang={["class:Druid"]="该巢穴是大自然令人不安的扭曲产物，展示了入侵的异种虫如何能迅速将一片曾经有水的盆地抽干，变成荒芜的酸性荒原。",["profession:Mining"]="异种虫在盆地中的挖掘活动暴露了异常多样的矿石，让矿工们能在同一片区域采集铁矿、秘银、真银和瑟银矿脉。"},sec={{t="干涸的盆地",b="腐化之巢坐落在俯瞰安戈洛环形山的西侧山脊旁，占据着沙地中曾经是一处湖泊或浅河的低洼地带。当森提帕尔异种虫入侵时，它们消耗了沙漠中残留的地下水分，将这片盆地变成了一处不断扩张的殖民地。巨大的螯钳和抽动的肢体直接从沙丘中伸出，围绕着布满腐蚀性昆虫分泌物和成簇孵化卵的地下隧道。"},{t="森提帕尔虫群",b="地下隧道连接着地表的入口和沙层下潮湿、覆盖着酸液的繁殖室。森提帕尔工虫、掘地虫、黄蜂和巨大的沙掠者在周边巡逻，保护它们的巢穴免受外界威胁。除了生物危险外，异种虫挖掘所引起的剧变还挖掘出了深层的矿藏，创造了一片异常多样的狩猎和勘探地，地下矿石暴露在虫群出没的巢穴之中。"}},faq={{q="腐化之巢里居住着什么样的生物？",a="巢穴中居住着森提帕尔，这是一个异种虫聚居地。巢穴由工虫、掘地虫、飞行黄蜂和掠食性的沙掠者守卫，它们都在像吞噬者索里德这样的稀有巢穴恐兽的统治下受到保护。",al={"腐化之巢的怪物","腐化之巢的昆虫","森提帕尔异种虫"}},{q="在异种虫占据这里之前，这里有什么？",a="下沉的地形表明该地区曾经是一条河床或浅沙漠湖。抵达此地的异种虫在地底挖掘，耗尽了塔纳利斯西部的宝贵水源和自然资源，留下了一片荒凉、被酸液浸透的盆地。",al={"腐化之巢的历史","腐化之巢曾是湖泊吗","腐化之巢的水源"}},{q="为什么地精对这个巢穴感兴趣？",a="加基森的地精将这个巢穴视为沙漠贸易的危害，并派遣冒险者去调查这个巢穴以及异种虫的扩张。",al={"腐化之巢的地精任务","蒸汽浮空城与腐化之巢","雷霆竞技场的异种虫"}},{q="腐化之巢与沙漠中的其他虫巢有联系吗？",a="腐化之巢代表了森提帕尔巢穴，它是从南部荒原蔓延开来的数个虫族殖民地之一。虽然它在物理上与更南方的巢穴不同，但其隧道共享着同样的诡异地下建筑，并威胁着要扼杀整个塔纳利斯的生命。",al={"塔纳利斯的其它巢穴","森提帕尔巢穴的联系","异种虫扩张"}}},fp="12,184,15.378.0,19.320.0,48.173.0,44.194.0,40.141.0,66.232.0"}
P.entries["subzone:old-ironforge"] = {n="Old Ironforge",s="Old Ironforge，也被称为“领主大厅”，是一座古老的地下密室，位于铁炉堡王座厅的正下方。它深深地开凿在山脉根部、炽热的岩浆脉之上，是这座矮人首都的祖源中心。如今，位于皇家王座大厅的厚重入口大门依然紧闭，并有严密的守卫看守。",h="Old...",kw={"艾格瑞姆的研究室","领主大厅","王座厅","铁炉堡","麦格尼·铜须","旧铁炉堡"},ang={["class:Rogue"]="王座厅的封闭大门受到国王麦格尼的卫兵严密监视，任何试图擅自闯入下方古老密室的人都将面临严厉的矮人正义制裁。",["race:Dwarf"]="对于矮人而言，Old Ironforge和领主大厅是与他们祖源的圣神纽带，保留了他们在山中王国黎明时期开凿出的最深处基石。"},sec={{t="领主大厅",b="在王座厅中国王麦格尼·铜须的王座之下，坐落着被称为Old Ironforge或领主大厅的巨大洞穴。在这些灼热的地下基石深处，蜿蜒的石桥横跨过地底熔岩池。早在Great Forge和公共区回荡着现代矮人商业繁荣的声音之前，早期的领主们就已聚集在这些深邃的洞穴中，商讨并治理着这座山中王国。"},{t="封闭的密室",b="目前，从王座大厅进入Old Ironforge的入口已被牢牢封锁。铁炉堡皇家卫队严密监视着通往旧地库的入口。"}},faq={{q="什么是旧铁炉堡？",a="旧铁炉堡，历史上被称为领主大厅，是直接开凿在现代城市铁炉堡下方的古老下层区域。它由巨大的大厅和熔岩管道组成。",al={"领主大厅","什么是旧铁炉堡","地下铁炉堡"}},{q="玩家可以进入旧铁炉堡吗？",a="无法通过王座大厅进入。王座厅的大门紧闭，由矮人皇家卫队看守，下方的密室对普通市民关闭。不过，这些深处并非完全寂静：黑铁矮人的地图显示，有隧道汇聚在铁炉堡正下方的某个点。",al={"如何进入旧铁炉堡","旧铁炉堡是否开放","旧铁炉堡大门锁定"}},{q="入口在哪里？",a="入口直接位于王座厅内部，即国王麦格尼·铜须在铁炉堡城内接见臣民的皇家谒见厅。",al={"旧铁炉堡入口在哪里","旧铁炉堡位置"}},{q="为什么旧铁炉堡对矮人历史如此重要？",a="它被称为领主大厅，在现代山中首都的上层环廊完全建成之前的早期时代，曾是矮人领袖和山丘之王们举行会议的古老场所。",al={"旧铁炉堡历史","为什么被称为领主大厅"}}},fp="13,166,22.304.0,16.130.0,22.157.0,32.212.0,30.114.0,52.170.0"}
P.entries["subzone:old-port-authority"] = {n="Old Port Authority",s="Old Port Authority是位于藏宝海湾木栈道旁的一个熙熙攘攘、汇集了众多商贩的仓库。在它的屋檐下，旅客们可以浏览从异国宠物和火枪到丰盛口粮和精制武器等各种商品。",h="Old Port Authority是位于藏宝海湾木栈道旁的一个熙熙攘攘、汇集了众多商贩的仓库。在它的屋檐下，旅客们可以浏览从异国宠物和火枪到丰盛口粮和精制武器等各种商品。",kw={"黑水海盗","火枪进口","藏宝海湾","切伤-淤青","航海需求","旧港务局","荆棘谷"},ang={["class:Hunter"]="东部火枪进口的商人们让这座建筑成为了一个可靠的补给站，在深入荆棘谷的丛林之前，可以在这里补充弹药和火药。",["profession:Cooking"]="烹饪旅行者可以顺便去美味佳肴摊位，购买过往商船带来的地区性烹饪原料和补给品。"},sec={{t="木栈道上的商业活动",b="Old Port Authority坐落在海盗避风港藏宝海湾内，是一个划分为不同摊位的室内市场，其内部繁忙的商业活动十分活跃。商人们向无赖和私掠船员兜售冒险补给品、火枪、弓箭、食物和武器。这里还拥有外来进口商品，向任何有钱的人提供从码头直接运来的色彩斑斓的鸟类和航海奇珍。"}},faq={{q="什么是旧港务局？",a="它是藏宝海湾内一个显眼的商业仓库，被隔断成几个市场摊位。冒险者和海盗们会来这里购买食物、弹药、武器和贸易杂货。",al={"这座建筑是什么","藏宝海湾仓库","藏宝海湾港务局"}},{q="里面有什么商店？",a="该仓库包含五个不同的商人摊位：航海需求、美味佳肴、迅捷飞行、东部火枪进口和切伤-淤青有限公司，涵盖了口粮、武器、宠物鸟和基本补给品。",al={"内部商贩","港务局内的商店","我可以在这里买什么"}},{q="这里可以买到宠物吗？",a="可以。在航海需求摊位，旅客可以获得异国情调的鸟类伙伴，如玄凤鹦鹉和塞内加尔鹦鹉，它们是当地水手和私掠船员中受欢迎的伙伴。",al={"藏宝海湾宠物商人","藏宝海湾鹦鹉","航海需求商人"}}},fp="18,169,25.288.0,31.177.0,28.191.0,22.147.0"}
P.entries["subzone:old-town"] = {n="Old Town",s="旧城区是暴风城最古老且最为粗犷的区域，在第一次战争的破坏中基本保持完整。这里没有闪闪发光的石砌广场，取而代之的是狭窄的巷道、风化的砖墙、工薪阶层的公寓以及熙熙攘攘的军事设施。它是王国军事Command Center以及SI:7秘密总部的所在地。",h="旧城区是暴风城最古老且最为粗犷的区域，在第一次战争的破坏中基本保持完整。这里没有闪闪发光的石砌广场，取而代之的是狭窄的巷道、风化的砖墙、工薪阶层的公寓以及熙熙攘攘的军事设施。它是王国军事Command...",kw={"勇士大厅","指挥中心","第一次战争","马迪亚斯·肖尔","旧城区","猪和哨声旅店","si:7","暴风城"},ang={["class:Rogue"]="旧城区是你在这座首都中的天然避难所；在普通的巷道背后隐藏着SI:7的总部，情报大师和秘密联络员们会在此提供指引。",["class:Warrior"]="Command Center和勇士大厅使旧城区成为暴风城中久经沙场的老兵们寻求装备和战斗训练的首选聚集地。"},sec={{t="旧王国的遗迹",b="虽然第一次战争后暴风城的其余部分由石匠工会从零开始精心重建，但旧城区逃过了彻底的毁灭。由于它不需要大规模重建，这里从未像贸易区或教堂广场那样获得崭新的大理石外墙和宏伟的运河。相反，它依然保留着古朴、拥挤的样貌，是打工者、劳工和城中最贫困居民的居所。这里的鹅卵石街道比首都的其他地方更狭窄、更脏乱，但也更加混乱，然而它们保留了战前暴风城最真实的氛围。"},{t="士兵、间谍与酒馆",b="在风化的公寓背后，旧城区充当着联盟首都的军事支柱。Command Center设有暴风城的军事官员、营房和战斗训练师，旁边则是勇士大厅，联盟最精锐的战士们都聚集于此。在区域边缘隐藏着SI:7的秘密基地，这是由马迪亚斯·肖尔领导的王国秘密情报机构。下班的步兵和暗影特工们都会聚集在猪和哨声旅店，在这个城市最热闹的酒馆之一把酒言欢。"}},faq={{q="为什么旧城区看起来比暴风城的其他地方脏得多？",a="旧城区在第一次战争期间在很大程度上躲过了部落对暴风城的摧毁。由于它没有被夷为平地，石匠工会没有对其进行重建，这意味着它错过了赋予城市其他区域的崭新石砌建筑和宏伟的建筑风格。",al={"为什么旧城区破旧","旧城区的贫困","为什么旧城区很脏"}},{q="SI:7是什么，它位于哪里？",a="SI:7是暴风城和联盟的秘密情报机构，由马迪亚斯·肖尔负责监管。他们的秘密总部隐藏在旧城区的深处，穿过训练场和军用马厩就能找到。",al={"si:7位置","什么是si:7","暴风城间谍"}},{q="旧城区的指挥中心有什么用？",a="指挥中心是暴风城军队的主要驻地和总部。在它的院子内及周边，军官们负责协调城市防御，战士和猎人则在马厩管理员和骑术训练师的指导下进行训练。",al={"指挥中心的用途","旧城区兵营","暴风城军事总部"}},{q="旧城区的酒馆在哪里？",a="当地的酒馆是猪和哨声旅店，位于该区域的中心附近。它以接待饥肠辘辘的士兵、冒险者和寻找丰盛烹饪食谱的旅行者而闻名。",al={"旧城区旅店","猪和哨声旅店位置","猪和哨声旅店在哪里"}}},fx={ddeb3ebc={q="旧城区是什么地方？",a="旧城区是暴风城现存最古老的城区。第一次大战中，兽人部落洗劫了这座城市，但与首都的其他地方不同，旧城区的大部分地区幸存了下来。如今，这里是一片简朴贫困的街区，住着暴风城的底层民众、普通劳工和不法之徒，同时也设有指挥中心和军情七处总部等重要军事设施。",al={"旧城区是什么","暴风城旧城区","关于旧城区"}},["70a73a68"]={q="第一次大战期间，旧城区发生了什么？",a="第一次大战结束时，兽人部落将暴风城夷为平地，首都的大部分地区都遭到了毁灭性的破坏。然而，旧城区没有被彻底摧毁，也躲过了最猛烈的火势。由于这里的建筑大多完好，战后大规模重建时基本保留了原貌，而城中其他地方则重建成了你如今看到的那些光鲜的石砌城区。",al={"旧城区历史","旧城区发生了什么","旧城区如何幸存"}},["73f1f985"]={q="谁住在旧城区？",a="旧城区住着暴风城较为贫困的民众，包括劳工、乞丐、扒手和盗贼。不过，这里也是城中军队与治安部队的重要基地。暴风城的军队以位于街区中央的指挥中心为指挥中心，而马迪亚斯·肖尔则在隐于街区之中的军情七处总部，指挥着这个组织的秘密特工。",al={"谁住在旧城区","旧城区居民","谁控制着旧城区"}},["3b861739"]={q="旧城区危险吗？",a="虽然有城市卫兵巡逻，王国的军事指挥中心也坐落于此，旧城区仍暗藏着险恶的一面。扒手、盗贼和刺客潜伏在狭窄的巷道与阴暗角落中，来路不明的店铺则贩卖毒药和暗藏的利刃。正直的旅人在拥挤的街道上穿行时，最好攥紧自己的钱袋。",al={"旧城区危险吗","旧城区的危险","旧城区安全吗"}},["840898dc"]={q="为什么这里叫旧城区？",a="这个名字的含义很直白：这里是暴风城最初的历史街区。由于第一次大战未将这里彻底夷平，这些建筑早在石匠兄弟会主持的近代重建之前便已存在，因此这里是整座城市现存最古老的区域。",al={"为什么叫旧城区","旧城区如何得名","旧城区的名字"}}},fp="8,201,26.520.0,28.393.0,66.229.0,37.202.0,48.210.0,32.170.0"}
P.entries["subzone:olsen-s-farthing"] = {n="奥森农场",s="奥森农场曾是一处繁荣的农庄，坐落于银松森林的主干道旁。第三次战争后，农田荒废，被效忠于亡灵巫师图勒·鸦爪的复生奴仆所占据。",h="奥森农场曾是一处繁荣的农庄，坐落于银松森林的主干道旁。第三次战争后，农田荒废，被效忠于亡灵巫师图勒·鸦爪的复生奴仆所占据。",kw={"芬里斯岛","洛丹伦农场","奥森农场","鸦爪劫掠者","鸦爪奴仆","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="清理奥森农场的劫掠者对于确保连接北部的瑟伯切尔和通往提瑞斯法林地的道路畅通至关重要。",["race:Undead"]="对于被遗忘者来说，像奥森农场这样的地方提醒着他们：天灾军团的威胁依然存在，他们试图奴役死者，而不是解放他们。"},sec={{t="被枯萎的农庄",b="在瘟疫吞噬洛丹伦之前，奥森农场是一处繁忙的农业据点，可以直通银松森林的主要贸易道路。如今，它的耕地已被杂草淹没，建筑破败不堪，曾经的农耕记忆早已被天灾军团的死灵法术抹去。在图勒·鸦爪指挥下被奴役为苦力和劫掠者的亡灵徘徊在这片荒凉的土地上，屠杀任何靠近的旅行者。"},{t="鸦爪的掌控",b="徘徊在奥森农场的蹒跚恐怖之物并非漫无目的的游荡者，而是听命于图勒·鸦爪的仆从。图勒·鸦爪是一位强大的亡灵巫师，盘踞在洛丹米尔湖中心的芬里斯岛上。他利用黑暗魔法唤醒并奴役了周围乡村的死者，他的魔爪延伸至奥森农场，对试图确保银松森林北部区域安全的被遗忘者构成了直接威胁。"}},faq={{q="第三次战争前，奥森农场是什么地方？",a="它曾是一处繁忙的路边农庄，支撑着银松森林主要贸易路线上的当地商业活动，在洛丹伦王国陷落于天灾军团之前，它曾为各定居点提供粮食。",al={"奥森农场历史","这个地方曾经是什么","谁曾住在奥森农场"}},{q="为什么这个农场会被亡灵侵扰？",a="该农场在第三次战争中被摧毁，其残骸被亡灵巫师图勒·鸦爪所占据，他将死者复活为奴仆和劫掠者，以此恐吓路上的旅行者。",al={"为什么这里有亡灵","谁控制了奥森农场的亡灵","鸦爪的奴仆 银松森林"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一位危险的亡灵巫师，他效忠于天灾军团，并从他在芬里斯岛的据点指挥着遍布银松森林的亡灵入侵。",al={"图勒·鸦爪是谁","图勒·鸦爪传说","谁指挥鸦爪劫掠者"}},{q="部落或被遗忘者在这里有驻军吗？",a="没有。农场已被忠于图勒·鸦爪的敌对亡灵完全占领，对于被遗忘者的侦察兵和部落旅行者来说，这里是一片充满敌意的土地。",al={"奥森农场属于部落吗","被遗忘者住在奥森农场吗","这里有任务中心吗"}}},fp="16,138,20.303.0,22.341.1,47.209.0,37.165.0,23.159.1,50.134.0"}
P.entries["subzone:oneiros"] = {n="奥奈罗斯",s="奥奈罗斯是一片广袤的古老暗夜精灵遗迹，位于菲拉斯北部，加德米尔湖的南面。这片遗迹与附近通往伊瑟拉国度的传送门紧密相连，其布满苔藓的石碑由精英绿龙人把守。",h="奥奈罗斯是一片广袤的古老暗夜精灵遗迹，位于菲拉斯北部，加德米尔湖的南面。这片遗迹与附近通往伊瑟拉国度的传送门紧密相连，其布满苔藓的石碑由精英绿龙人把守。",kw={"龙裔","菲拉斯","绿龙军团","加德米尔湖","奥奈罗斯"},ang={["class:Druid"]="德鲁伊对奥奈罗斯怀有深深的敬畏与关切，因为他们认识到这里与伊瑟拉领域之间存在着空灵的联系，以及梦魇腐蚀带来的挥之不去的危险。",["race:NightElf"]="对于暗夜精灵来说，漫步在奥奈罗斯是提醒他们古老帝国版图以及绿龙军团警惕守护的一种庄严方式。"},sec={{t="梦境之下的遗迹",b="奥奈罗斯的残垣断壁和断柱碎片散布在菲拉斯北部的茂密森林地面上，暗示着这里曾是一处数千年前被废弃的卡多雷定居点。如今，大自然已经重新收复了这些建筑，巨大的树根和青翠的植被将其缠绕覆盖。绿龙军团的精英卫士无情地巡逻着阴凉的小径和破败的广场，阻止凡人接近这些古老的秘密。"},{t="回响与腐蚀",b="奥奈罗斯与翡翠梦境之间的精神纽带使该地区变得极不稳定。效忠于织梦者的龙人在此边界周围保持着警惕的守望，但面纱之外仍有黑暗在涌动。误入奥奈罗斯的凡人必须面对强大的龙裔，他们将任何闯入者视为对抑制腐蚀的脆弱结界的潜在威胁。"}},faq={{q="奥奈罗斯在哪里？",a="奥奈罗斯位于菲拉斯北部，直接位于加德米尔湖南面，森林主干道的北侧。它坐落在翡翠梦境传送门边缘的巨树附近。",al={"奥奈罗斯位置","奥奈罗斯在哪里","寻找奥奈罗斯"}},{q="奥奈罗斯有什么生物？",a="这片遗迹中有大量强大的绿龙裔和效忠于绿龙军团的龙人在巡逻。旅行者在靠近时应保持谨慎，因为这些哨兵是可怕的精英守卫。",al={"奥奈罗斯怪物","奥奈罗斯的敌人","谁住在奥奈罗斯"}},{q="为什么这里会有暗夜精灵遗迹？",a="奥奈罗斯是一处古老的暗夜精灵定居点，其历史可以追溯到大分裂之前。和大部分菲拉斯地区一样，这里的文明在万年前就已崩溃，留下的石柱廊和庭院如今已被大自然重新占据。",al={"为什么会有遗迹","菲拉斯的卡多雷遗迹","奥奈罗斯历史"}},{q="奥奈罗斯和翡翠梦境有什么联系？",a="它靠近连接卡利姆多与梦境国度的巨大枝干，导致物质世界与精神世界之间的界限变得模糊。",al={"奥奈罗斯翡翠梦境","菲拉斯梦境连接"}},{q="附近有安全的地方休息吗？",a="遗迹本身并不安全，因为这里属于绿龙人。联盟旅行者可以撤退到西海岸外的羽月要塞，而部落成员则可以在菲拉斯东部的莫沙彻营地寻求庇护。",al={"奥奈罗斯附近的营地","菲拉斯织梦者休憩处","奥奈罗斯友方枢纽"}}},fp="7,168,23.273.0,21.266.1,25.177.0,31.169.0,35.196.0,61.136.0,37.225.0"}
P.entries["subzone:onyxia-s-lair"] = {n="奥妮克希亚的巢穴",s="奥妮克希亚的巢穴是一处位于尘泥沼泽巨龙沼泽深处的地下洞穴。它不仅是黑龙军团的龙后奥妮克希亚的筑巢圣地，也是她的据点。在这闷热且布满岩浆的巢穴深处，这位伟大的巨龙守护着一窝又一窝的黑龙卵。",h="奥妮克希亚的巢穴是一处位于尘泥沼泽巨龙沼泽深处的地下洞穴。它不仅是黑龙军团的龙后奥妮克希亚的筑巢圣地，也是她的据点。在这闷热且布满岩浆的巢穴深处，这位伟大的巨龙守护着一窝又一窝的黑龙卵。",kw={"黑龙军团","龙后","黑龙谷","尘泥沼泽","巢穴","奥妮克希亚","雏龙","巨龙沼泽"},ang={["faction:Alliance"]="对于联盟的勇士来说，这个洞穴是一位黑龙龙后的巢穴，她不断壮大的后裔威胁着塞拉摩及沼泽周围的每一个定居点。",["faction:Horde"]="尘泥沼泽与贫瘠之地和莫高雷的部落领地接壤；让一位黑龙龙后在卡利姆多孵化出一支巨龙军队，对整个新部落构成了生存威胁。"},sec={{t="岩浆与废墟之穴",b="这处洞穴开凿在巨龙沼泽凶险的泥沼和石化木林之中，入口酷似一条巨龙张开的大嘴。走进洞内，沼泽的阴冷瞬间被炽热的火山热浪所取代。岩浆从黑曜石的裂缝中渗出，地下的震颤不时撼动着洞穴顶部。中央大厅是一个巨大的孵化场，数以百计的黑龙卵在灰烬和余火中被孵育，并由龙族近亲、龙人守卫以及奥妮克希亚亲自看管。"},{t="龙后的隐居之所",b="当奥妮克希亚的兄弟奈法利安在海对岸的黑石塔中密谋时，奥妮克希亚长期以来一直保持着这处位于卡利姆多的隐秘栖息地，以繁衍黑龙军团的下一代。当她错综复杂的政治阴谋败露时，这里便是她的堡垒。在这里，远离人类王国的宫廷，她可以褪去伪装，显露作为死亡之翼之女的真正可怕形态。"}},faq={{q="奥妮克希亚的巢穴究竟在哪里？",a="该巢穴位于尘泥沼泽南部的巨龙沼泽内，黑龙谷以南。入口处有巨大的龙骨、冒烟的地形，以及把守着如同张开巨口的石缝的黑龙族守卫。",al={"奥妮克希亚在哪里","奥妮克希亚位置","如何找到奥妮克希亚的巢穴","黑龙谷洞穴"}},{q="巢穴里居住着哪些生物？",a="洞穴内几乎全部是黑龙军团的成员。龙后奥妮克希亚统领着深处的大厅，周围簇拥着成群刚孵化的雏龙、守护龙人和成年的黑龙。",al={"奥妮克希亚的巢穴怪物","谁住在奥妮克希亚的巢穴","里面有什么"}},{q="既然位于沼泽之中，为什么洞穴会如此炎热？",a="奥妮克希亚将她的巢穴深挖进卡利姆多的地壳，触及了地下的岩浆脉络。极端的火山热量提供了孵化黑龙卵所需的灼热环境，与上方尘泥沼泽冰冷的泥沼形成了鲜明对比。",al={"为什么尘泥沼泽里有熔岩","奥妮克希亚的巢穴火山"}},{q="奥妮克希亚为什么要躲在卡利姆多？",a="尘泥沼泽提供了隔绝与隐蔽。其浓重的雾气、阴郁的泥潭和危险的野生动物令凡人军队望而却步，使龙后能在不被打扰的情况下补充她军团的数量，同时在海外协调她的暗中干涉。",al={"为什么奥妮克希亚在这里","为什么是尘泥沼泽","奥妮克希亚卡利姆多"}}},fp="13,165,23.368.0,25.331.1,31.228.0,37.176.0,45.164.0,37.202.0"}
P.entries["subzone:oracle-glade"] = {n="神谕林地",s="神谕林地坐落在泰达希尔的西北部，是一片神圣的林地庇护所，也是奇妙的神谕之树和世界之树首要月亮井的所在地。尽管这里作为交流和警觉的中心，环境宁静祥和，但这片林地却面临着血羽鹰身人不断侵扰的威胁。",h="神谕林地坐落在泰达希尔的西北部，是一片神圣的林地庇护所，也是奇妙的神谕之树和世界之树首要月亮井的所在地。尽管这里作为交流和警觉的中心，环境宁静祥和，但这片林地却面临着血羽鹰身人不断侵扰的威胁。",kw={"血羽","范达尔·鹿盔","鹰身人","月亮井","神谕林地","神谕之树","泰达希尔","涌泉湖"},ang={["class:Druid"]="对于荒野的德鲁伊来说，神谕之树是护林工作中的活生生的伙伴，它直接从树皮上脱落书面记录，提供关于这片土地健康状况的信息。",["race:NightElf"]="神谕林地代表了培育泰达希尔使其繁茂所需的悉心照料，这里安置着王冠上最强大的月亮井，以及一位直接与塞纳里奥领导层对话的无声守望者。"},sec={{t="林地之心",b="神谕林地安静地栖身于达纳苏斯和涌泉湖之间，是暗夜精灵与自然沟通的重要枢纽。在它的中心矗立着神谕之树，这是一株古老的树木，其巨大的枝桠勾勒出了一只雄鹰栖息在巨熊之上的轮廓。附近闪烁着泰达希尔第一口、也是最强的一口神圣月亮井，这是沐浴在艾露恩恩泽下的月亮魔法绿洲。与古树之环一起，神谕之树守望着岛上的枝叶，并脱落刻字的树皮，这些树皮是向范达尔·鹿盔大德鲁伊传达关于世界之树健康状况的重要讯息。"},{t="受困的枝桠",b="林地的宁静十分脆弱。咄咄逼人的血羽鹰身人降临到了这片林地，在高高的树枝间筑巢，威胁着这棵圣树。从达纳苏斯派遣来的哨兵们努力想要根除这些禽类拾荒者，而这些鹰身人积极骚扰过往的德鲁伊，并玷污了月亮井的自然宁静。穿行于北部枝桠的旅者必须小心谨慎，因为鹰身人会迅速攻击任何靠近它们巢穴的人。"}},faq={{q="什么是神谕之树？",a="神谕之树是一棵古老且受到魔法滋养的树，外形如同一只雄鹰栖息在一头巨熊身上。它监测着泰达希尔的生长与健康，并脱落刻字的树皮，其中包含的详细报告由德鲁伊直接送交到达纳苏斯的范达尔·鹿盔大德鲁伊手中。",al={"神谕之树是谁","神谕之树背景故事","泰达希尔会说话的树"}},{q="为什么鹰身人要攻击神谕林地？",a="血羽氏族的鹰身人在林地的高处树冠筑巢，被这里原始的荒野和魔法活力所吸引。它们暴力地捍卫自己的巢穴并骚扰神谕之树，迫使当地的哨兵必须将它们控制住。",al={"血羽鹰身人","为什么这里有鹰身人","神谕林地的敌人"}},{q="这片林地里的月亮井有什么重要性？",a="神谕林地中的水池是泰达希尔建立的第一口、也是最强大的一口月亮井。它引导着艾露恩的神圣能量，滋养着周围的森林，并供养着前来汲取井水的卡多雷德鲁伊和女祭司。",al={"神谕林地月亮井","第一口月亮井","泰达希尔第一口月亮井"}},{q="神谕林地在哪里？",a="它位于泰达希尔西北部，涌泉湖以西。一条南向的道路将林地与达纳苏斯城门外环绕的主路直接连接起来。",al={"神谕林地位置","神谕林地在哪里","如何前往神谕林地"}}},fp="12,206,21.504.0,16.357.0,24.239.0,43.161.0,53.219.0,34.155.0"}
P.entries["subzone:orgrimmar"] = {n="奥格瑞玛",s="奥格瑞玛是新部落强大的战士之都，坐落于杜隆塔尔北部蜿蜒的红色峡谷之中。它由大酋长萨尔所建，得名于纪念奥格瑞姆·毁灭之锤，是兽人复兴和卡利姆多各部落生存的中心。",h="奥格瑞玛是新部落强大的战士之都，坐落于杜隆塔尔北部蜿蜒的红色峡谷之中。它由大酋长萨尔所建，得名于纪念奥格瑞姆·毁灭之锤，是兽人复兴和卡利姆多各部落生存的中心。",kw={"暗矛巨魔","毁灭之锤","杜隆塔尔","索尔的堡垒","新部落","奥格瑞玛","牛头人","萨尔"},ang={["faction:Horde"]="作为部落领导权的最高所在地，奥格瑞玛是整个卡利姆多及更远地区军事行动、部落联盟和外交关系的中心集结地。",["race:Orc"]="对于兽人而言，奥格瑞玛是他们救赎的实现，在这里，他们抛弃了恶魔诅咒的遗产，建立起一个光荣、独立的未来。"},sec={{t="岩石中的堡垒",b="第三次战争结束后，在海加尔山取得胜利，大酋长萨尔带领幸存的族人向南迁徙，在杜隆塔尔建立了永久的家园。奥格瑞玛坐落于天然的崎岖山崖屏障之中，工程设计旨在抵御围攻，拥有带尖刺的木制栅栏、石砌瞭望塔和深凿入山的洞穴。这座堡垒由暗矛巨魔、牛头人石匠和地精工程师共同建造，将一片荒芜的荒野变成了坚不可摧的力量堡垒。"},{t="新部落之心",b="摆脱了曾经束缚他们的恶魔嗜血诅咒，兽人将奥格瑞玛建造为荣誉、社区与生存的灯塔。如今在ADP 25年，这座城市不仅容纳了兽人和暗矛巨魔，还迎接了来自莫高雷的牛头人使节以及新结盟的被遗忘者。在防御森严的峡谷内，萨满教导下一代如何保持先祖的平衡，而老兵们在角斗场中通过战斗磨练军队，守护着卡利姆多脆弱的和平。"}},faq={{q="奥格瑞玛是以谁的名字命名的？",a="大酋长萨尔以他的导师和前任——传奇的兽人大酋长奥格瑞姆·毁灭之锤的名字命名了这座城市。毁灭之锤在东部王国解放兽人收容所的战斗中牺牲，临终前将他标志性的战甲和战锤传给了萨尔。",al={"奥格瑞玛名字起源","为什么叫奥格瑞玛","奥格瑞玛命名来源"}},{q="谁帮助建造了这座城市？",a="这座首都是在兽人、暗矛巨魔、牛头人、受雇的地精工兵和工程师以及游荡的勇士雷克萨的共同努力下迅速建成的。其天然的石墙经过挖掘和加固，在杜隆塔尔严酷的地形中提供了快速且易守难攻的庇护所。",al={"谁建造了奥格瑞玛","奥格瑞玛建造方式","奥格瑞玛建设者"}},{q="哪些种族以奥格瑞玛为家？",a="奥格瑞玛主要居住着兽人和森金的暗矛巨魔，他们共同居住在各区。牛头人旅行者作为坚定的盟友经常在此居住，新近接纳的被遗忘者的使节也已开始在他们身边建立起一席之地。",al={"谁住在奥格瑞玛","奥格瑞玛居民","奥格瑞玛种族"}},{q="大酋长萨尔居住在哪里？",a="萨尔在奥格瑞玛智慧谷内的中心要塞索尔的堡垒统领着新部落，该要塞以纪念他牺牲的朋友格罗姆·地狱咆哮而命名。",al={"萨尔在哪里","萨尔奥格瑞玛位置","大酋长驻地"}}},fp="9,229,25.414.0,22.407.0,29.243.0,26.244.0,32.206.0,34.140.0"}
P.entries["subzone:ortell-s-hideout"] = {n="奥泰尔藏身处",s="奥泰尔藏身处是坐落在希利苏斯东南部山脉中的一处简陋而隐秘的洞穴。这里是隐士奥泰尔的避难所，他是少数几个有足够勇气或愚勇，敢于独自在这片贫瘠荒原上生活的独行者之一。",h="奥泰尔藏身处是坐落在希利苏斯东南部山脉中的一处简陋而隐秘的洞穴。这里是隐士奥泰尔的避难所，他是少数几个有足够勇气或愚勇，敢于独自在这片贫瘠荒原上生活的独行者之一。",kw={"洞穴","隐士奥泰尔","奥泰尔藏身处","希利苏斯","希利苏斯东南部"},sec={{t="隐士的庇护所",b="奥泰尔藏身处隐蔽在希利苏斯东南部的崎岖峭壁之中，在肆虐的沙尘暴和充斥着这片荒原的异种虫群威胁下，它提供了一个极其简陋的避难所。这个洞穴仅由隐士奥泰尔一人居住，他是一个古怪的遁世者，远离文明世界和塞纳里奥要塞的坚固据点，在这里艰难地维持着生计。那些敢于冒险前往这个偏远角落的旅行者，通常是为了寻求他关于沙漠及其危险的独特见解。"}},faq={{q="奥泰尔藏身处在哪里？",a="这个藏身处是在希利苏斯东南边缘的山岩中开凿出来的，远离中央沙漠道路，深藏在边界的悬崖之下。",al={"奥泰尔在哪里","奥泰尔位置","如何找到奥泰尔洞穴"}},{q="隐士奥泰尔是谁？",a="隐士奥泰尔是一个独居者，生活在塞纳里奥议会的远征队和世界各方势力之外。他选择独自生活在希利苏斯的危险之中，只守着他那小小的洞穴。",al={"奥泰尔是谁","隐士奥泰尔背景故事"}},{q="奥泰尔藏身处没有异种虫吗？",a="虽然洞穴本身没有受到虫害，但它孤立地处在一个极度危险的区域，那里到处是虫群和暮光之锤的邪教徒。要到达这个藏身处，需要穿过险恶的地形。",al={"洞里有虫子吗","奥泰尔洞穴安全吗"}}},fp="16,128,18.353.0,26.150.0,21.160.0,43.173.0"}
P.entries["subzone:owl-wing-thicket"] = {n="枭翼树丛",s="枭翼树丛是冬泉谷南部一片由洞穴和岩石栖息地构成的崎岖区域。这里栖息着大量狂暴、受月光影响且疯狂的枭兽，它们在雪崖间四处徘徊。在深处，古老的暗夜精灵祭坛保存着关于这些生物起源，以及它们与月神艾露恩之间联系的神圣知识。",h="枭翼树丛是冬泉谷南部一片由洞穴和岩石栖息地构成的崎岖区域。这里栖息着大量狂暴、受月光影响且疯狂的枭兽，它们在雪崖间四处徘徊。在深处，古老的暗夜精灵祭坛保存着关于这些生物起源，以及它们与月神艾露恩之间联系的神圣知识。",kw={"艾露恩","艾露恩卫士","枭兽","受月光影响","枭翼树丛","兰莎尔拉","冬泉谷"},ang={["class:Druid"]="德鲁伊认为枭兽形态是神圣的，这使得这片树丛成了一个令人警醒的地方，这些被赋予了月光亲和力的生物已经陷入了无法自控的疯狂。",["race:NightElf"]="对于卡多雷来说，枭翼树丛是已荒废的圣地，它在保存艾露恩恩泽早期记录的同时，也存在着那些失去了古老平衡的野性枭兽。"},sec={{t="枭兽圣所",b="枭翼树丛开凿在永望镇南部的雪山高地中，是冬泉谷野生枭兽最稠密的巢穴之一。很久以前，暗夜精灵守护者曾将这些生物尊为受到艾露恩祝福的神圣卫士。古老的神龛和月石祭坛至今仍隐藏在洞穴悬壁中，由艾露恩卫士的徘徊之魂守望着。然而，今天许多野兽已经陷入疯狂，攻击任何闯入它们神圣洞穴的旅行者。"},{t="枭兽传说",b="暗夜精灵学者和祭司会前往枭翼树丛寻求与艾露恩卫士沟通。在祭司兰莎尔拉的指引下，联盟的探寻者们点燃洞穴建筑群中的圣火，以唤醒古老的灵魂。这些卫士讲述了野生枭兽最初是如何由艾露恩创造出来，以守护纯净的自然圣所的传说，尽管它们现在变得野蛮且充满敌意，但这提供了关于这些野兽神圣血统的真相。"}},faq={{q="什么是枭翼树丛？",a="枭翼树丛是位于冬泉谷南部的一片雪崖和洞穴网络。这里因其栖息着大量的野生枭兽以及数座供奉暗夜精灵月神艾露恩的古老神龛而闻名。",al={"枭翼树丛","枭翼树丛在哪里","枭翼树丛传说"}},{q="为什么这里的枭兽如此具有攻击性？",a="虽然最初是被艾露恩祝福的自然守护者，但冬泉谷中许多枭兽已经陷入了暴力狂乱之中。在枭翼树丛中，它们作为疯狂、狂暴且受月光影响的野兽徘徊，攻击任何接近其巢穴的人。",al={"为什么枭兽会发狂","冬泉谷的疯狂枭兽","狂暴的枭兽"}},{q="兰莎尔拉是谁？",a="兰莎尔拉是一位前往枭翼树丛的艾露恩暗夜精灵祭司。她寻求古老的艾露恩卫士的指引，以发掘枭兽一族神圣的起源与历史。",al={"兰莎尔拉","冬泉谷的兰莎尔拉是谁","祭司兰莎尔拉"}},{q="在树丛中发现的艾露恩卫士是什么？",a="艾露恩卫士是与洞穴内祭坛相连的古老暗夜精灵之魂。当通过重新点燃圣火将它们召唤出来时，它们会讲述枭兽是如何被创造出来以看守荒野和圣地的。",al={"艾露恩卫士","枭翼树丛中的灵魂","枭兽之魂"}}},fp="16,204,24.421.0,23.414.1,25.172.0,41.201.0,17.176.0,57.201.0"}
P.entries["subzone:palemane-rock"] = {n="白鬃石",s="白鬃石是坐落在莫高雷西部群山之中的一个洞穴和营地。它是具有侵略性的白鬃豺狼人部落的主要据点，对附近的血蹄村牛头人构成了持续的困扰和威胁。",h="白鬃石是坐落在莫高雷西部群山之中的一个洞穴和营地。它是具有侵略性的白鬃豺狼人部落的主要据点，对附近的血蹄村牛头人构成了持续的困扰和威胁。",kw={"血蹄","洞穴","豺狼人","莫高雷","白鬃","石头"},ang={["faction:Horde"]="确保莫高雷的边境免受像白鬃豺狼人这样的地方害虫骚扰，对于维持牛头人家园的安全与稳定至关重要。",["race:Tauren"]="占据这些西部洞穴的白鬃豺狼人是你们族人眼中挥之不去的顽疾，它们威胁着莫高雷草场上的猎物和粗心大意的旅人。"},sec={{t="豺狼人据点",b="白鬃石位于莫高雷大草原的西缘，由一个巨大的露天营地和一个深邃阴暗、开凿在山腰的洞穴组成。白鬃豺狼人占据了洞穴内部和外围的山麓，将其划为自己的领地。这些豺狼人充满敌意且领地意识极强，它们凶猛地保卫着自己的巢穴，攻击任何靠得太近的猎人、旅行者和斥候。"}},faq={{q="什么是白鬃石？",a="白鬃石是一个天然形成的洞穴，也是一个位于莫高雷西部悬崖处的豺狼人据点。",al={"白鬃石信息","白鬃洞穴","白鬃石在哪里"}},{q="谁住在白鬃石？",a="该洞穴及周边营地由白鬃氏族的豺狼人所占据。它们极具侵略性，防范着包括当地牛头人在内的外来者入侵其领地。",al={"这里住着谁","白鬃怪物","白鬃石的豺狼人"}},{q="为什么白鬃石对牛头人很重要？",a="白鬃石紧邻莫高雷中部和血蹄村，是一个充满敌意的掠夺者巢穴，牛头人猎人和勇士必须不断地对其进行压制。",al={"为什么牛头人很在意","血蹄村豺狼人","对莫高雷的威胁"}}},fp="13,100,18.279.0,22.73.0,27.116.0,44.146.0"}
P.entries["subzone:park"] = {n="Park",s="暴风城位于教堂广场和法师区之间，其西侧边缘有一处名为“公园”的郁郁葱葱的避难所，这里充满绿意，是个安静沉思的好去处。在这座喧嚣的石砌都城中，它致力于自然与休闲，是前来造访的暗夜精灵的主要避风港，也是东部王国唯一的德鲁伊训练师所在地。",h="暴风城位于教堂广场和法师区之间，其西侧边缘有一处名为“公园”的郁郁葱葱的避难所，这里充满绿意，是个安静沉思的好去处。在这座喧嚣的石砌都城中，它致力于自然与休闲，是前来造访的暗夜精灵的主要避风港，也是东部王国唯一的德鲁伊训...",kw={"德鲁伊","卡多雷","月亮井","娜拉·梅德隆","暗夜精灵","公园","暴风城"},ang={["class:Druid"]="这片宁静的飞地是你在整个东部王国进行训练和寻求建议的唯一避难所。",["race:NightElf"]="对于横跨大海旅行的暗夜精灵来说，公园提供了一种宾至如归的感觉，这里以发光的月亮井为中心，还有熟悉的艾露恩与荒野导师。"},sec={{t="石砌都城中的林地",b="暴风城的其他区域大多是鹅卵石铺就的人行道、高耸的石灰岩壁垒和拥挤的集市摊位，而公园则提供了一丝宁静的荒野气息。它最初是为市民建立的安静休闲场所，后来自然而然地转变成了暗夜精灵使者和从无尽之海远道而来的旅人的聚居地。在遮天蔽日的树冠下，围绕着中央的月亮井，该区域将卡利姆多神圣林地的一角带入了人类王国的心脏地带。"},{t="避难所与友谊",b="对于暗夜精灵来说，公园是他们在异国他乡的重要立足点。在这里，像娜拉·梅德隆这样的卡多雷牧师照料着前来朝圣的人们，德鲁伊导师也为那些献身荒野的人提供指导。该区域也是一处宁静的休憩之所，疲惫的冒险者可以在此从贸易区的喧嚣和大教堂的神圣职责中获得片刻休息。"}},faq={{q="公园位于暴风城的什么位置？",a="公园坐落在暴风城的极西边缘。你可以从教堂广场向西南方向走，或者从法师区向西北方向走，就能到达它那绿意盎然的小径。",al={"公园在哪里","如何前往公园","公园位置"}},{q="为什么公园里有这么多暗夜精灵？",a="公园被前来造访的暗夜精灵视为避难所，他们在此寻求从暴风城高耸的石街中解脱出来。这里郁郁葱葱的林地和宁静的氛围让他们想起了家乡的森林，于是他们选择在此定居，甚至在广场上建立了一座月亮井。",al={"为什么有暗夜精灵","暴风城暗夜精灵区","卡多雷区"}},{q="我可以在这里训练德鲁伊技能吗？",a="可以。公园目前是东部王国中唯一有联盟德鲁伊训练师驻扎的地方，他们为远离卡利姆多的卡多雷修行者提供指导和训练。",al={"暴风城德鲁伊训练师","东部王国德鲁伊训练地点","公园德鲁伊训练"}},{q="公园中心那座发光的池塘是什么？",a="公园中间的池塘是一座神圣的暗夜精灵月亮井，由卡多雷访客建造，旨在人类城市中作为精神安宁与月神之力的神圣源泉。",al={"公园月亮井","公园发光的喷泉","公园里的水池"}}},fx={a403a5e6={q="花园区是什么地方？",a="花园区坐落在暴风城西侧的一角，是一片草木葱茏的城区。这里最初主要供人休闲，如今则成为来访暗夜精灵的绿荫庇护所，让他们得以远离城中宽阔的石板大道，稍作休憩。宁静的林间有一座神圣的月亮井，东部王国唯一一处德鲁伊训练师聚集地也在这里。",al={"花园区是什么","暴风城花园区概况","花园区是什么城区"}},["7a811135"]={q="花园区发生过什么？",a="这片城区原本只是供暴风城居民休闲的地方，第三次战争后，暗夜精灵加入联盟并来到这座都城，这里也随之改变。暗夜精灵在远离石板街道的林木绿荫中找到了慰藉，于是在此建立了永久的聚居地，为一座泛着光芒的月亮井举行祝圣仪式，并将德鲁伊之道带到了人类的土地上。",al={"花园区历史","花园区的历史","花园区发生过什么"}},["83a38db8"]={q="花园区危险吗？",a="不，花园区是暴风城最安宁祥和的城区之一。城市卫兵保护着这里，来访的暗夜精灵哨兵和德鲁伊也在此守卫，让人们得以远离都城繁忙的贸易区和军事区，安静地休憩。",al={"花园区安全吗","花园区危险吗","花园区的威胁"}}},fp="4,225,28.365.0,24.290.0,39.128.0,46.177.0,33.144.0,51.173.0"}
P.entries["subzone:pestilent-scar"] = {n="瘟疫之痕",s="瘟疫之痕是一道深邃且受腐蚀的峡谷，切开了东瘟疫之地那片饱受蹂躏的大地。与天灾军团腐蚀造成的锯齿状裂痕不同，这道裂谷似乎是一处天然峡谷或干涸的湖床，后来遭到腐蚀并被贪婪的软泥怪所占据。",h="瘟疫之痕是一道深邃且受腐蚀的峡谷，切开了东瘟疫之地那片饱受蹂躏的大地。与天灾军团腐蚀造成的锯齿状裂痕不同，这道裂谷似乎是一处天然峡谷或干涸的湖床，后来遭到腐蚀并被贪婪的软泥怪所占据。",kw={"腐蚀","东瘟疫之地","峡谷","魔刃之痕","软泥怪","瘟疫之痕","软泥"},ang={["profession:Herbalism"]="峡谷边缘浸透了浓烈的腐败之物，有时会在悬崖边孕育出阿尔萨斯之泪和瘟疫花这类罕见的、适应了腐蚀的植物。",["race:Undead"]="被遗忘者的药剂师经常研究栖息在这些深邃裂缝中的软泥怪，以分离出天灾军团最恶毒毒素的不稳定变体。"},sec={{t="一道受腐蚀的裂谷",b="瘟疫之痕蜿蜒穿过东瘟疫之地的东部区域，在受腐蚀的地貌中形成了一道阴森的裂缝。虽然像魔刃之痕这样的附近裂缝是由亡灵瘟疫突然爆发所撕裂开的，但学者们指出，瘟疫之痕似乎起源于一种天然的地质构造。它很可能是一条深邃的河谷或天然湖泊，在天灾军团席卷洛丹伦时干涸，留下了一条荒芜的沟壑，并逐渐汇聚了有毒的径流和污秽的软泥。"},{t="软泥坑",b="这片洼地失去了纯净的水源，终日浸泡在持久的邪恶腐败之中，已成为变异酸性软泥怪和食腐害虫的滋生温床。在其摇摇欲坠的边缘附近行走十分危险；裂谷上方的空气中充斥着刺鼻的烟雾，且不稳定的土壤经常威胁着要将粗心大意的冒险者直接抛入下方翻滚的淤泥之中。"}},faq={{q="什么是瘟疫之痕？",a="瘟疫之痕是位于东瘟疫之地的一道下陷峡谷。在洛丹伦陷落期间受到腐蚀，峡谷中充满了污秽的径流、病变的土壤以及极具攻击性的软泥怪。",al={"瘟疫之痕背景故事","什么是瘟疫之痕","瘟疫之痕峡谷"}},{q="瘟疫之痕是如何形成的？",a="与天灾军团爆发所造成的非自然地表裂缝不同，瘟疫之痕似乎曾是一处天然山谷、湖泊或河谷，在亡灵瘟疫的腐蚀下干涸并枯萎了。",al={"瘟疫之痕是如何形成的","瘟疫之痕的起源","谁制造了瘟疫之痕"}},{q="它与魔刃之痕有何不同？",a="魔刃之痕是作为一种喷涌出纯粹魔法腐蚀物的非自然火山裂缝而被猛烈撕开的。瘟疫之痕则是一处更古老的天然地势洼地，在土地死后逐渐聚集了腐蚀物和径流。",al={"瘟疫之痕与魔刃之痕","魔刃之痕的区别"}},{q="瘟疫之痕里生活着什么生物？",a="裂谷底部主要是由瘟疫催生的酸性软泥怪和食腐害虫所占据，它们在底部聚集的有毒水潭和腐烂的有机物质中繁衍生息。",al={"瘟疫之痕的生物","瘟疫之痕中有什么生物"}}},fp="14,146,16.404.0,14.261.0,27.164.0,32.189.0,42.222.0,42.135.0"}
P.entries["subzone:petitioner-s-chamber"] = {n="Petitioner's Chamber",s="Petitioner's Chamber，也被称为请愿者大厅，是一个位于暴风要塞主入口坡道旁的前厅。它是贵族、教会要员以及寻求觐见国王的来访臣民的官方候见室。在此逗留的人们常常会在这里交谈、饮酒，或等待摄政王的召见。",h="Petitioner's Chamber，也被称为请愿者大厅，是一个位于暴风要塞主入口坡道旁的前厅。它是贵族、教会要员以及寻求觐见国王的来访臣民的官方候见室。在此逗留的人们常常会在这里交谈、饮酒，或等待摄政王的召见。",kw={"德拉维主教","卡雷德拉·晨风","雷明顿·瑞治维尔伯爵","请愿者大厅","祈求者之厅","暴风要塞"},ang={["class:Priest"]="由于德拉维主教经常驻扎在这个前厅，该房间成为了圣光教会行政层级与皇室宫廷之间的交汇点。",["faction:Alliance"]="对于联盟的忠诚者来说，这个房间代表了暴风城的行政瓶颈，国内的上诉、教会事务以及贵族的请求都在这里等待着皇家议会那少得可怜的关注。"},sec={{t="候见与权谋之室",b="Petitioner's Chamber位于登上暴风要塞后右侧。这里是国家大事与日常官僚事务交汇之处。雷明顿·瑞治维尔伯爵等贵族和德拉维主教等高级神职人员常常在此消磨时间，等待觐见安度因·乌瑞恩国王和伯瓦尔·弗塔根公爵。在宫廷礼仪那光鲜亮丽的表象之下，这里是城堡内进行闲谈、私下游说以及观察王国中谁才是真正掌权者的理想角落。"}},faq={{q="请愿者大厅在哪里？",a="该房间位于暴风要塞内。当你沿着主入口坡道登上要塞时，它就在你右手边的第一个房间。",al={"祈愿厅在哪里","如何找到祈愿厅","祈愿厅位置"}},{q="谁会聚集在这个房间里？",a="这里常有请愿者、宫廷随从和寻求觐见王室的贵族出没，其中包括雷明顿·瑞治维尔伯爵、卡雷德拉·晨风以及圣光教会的德拉维主教等人物。",al={"谁在祈愿厅","祈愿厅里的非玩家角色","谁在这里等待"}},{q="为什么它也被称为请愿者大厅？",a="它的正式功能是接待那些已向王室提交正式请愿书的臣民。访客必须在此等待，直到摄政王、伯瓦尔·弗塔根公爵或皇家议会批准他们进入王座大厅。",al={"请愿者大厅","为什么叫请愿者大厅"}},{q="城市任务期间这里会发生什么？",a="造访该房间的主要目的是交付货物，或是与驻扎在要塞内的贵族及神职人员交谈，例如为等待宫廷事务处理而口渴的贵族提供波特酒等饮品。",al={"祈愿厅任务","什么任务会指引到这里"}}},fx={["7fbb3fec"]={q="觐见室是什么地方？",a="觐见室是暴风要塞的公共接见厅，沿着通往王宫的宏伟坡道向上走，就在右手边。臣民、外国使节和来访贵族若想觐见君主或王廷，便会在这间正式的等候厅中等候。",al={"祈愿厅是什么","暴风城祈愿厅","这个房间是什么"}},["7106fd20"]={q="觐见室危险吗？",a="丝毫不危险。这间厅室位于暴风要塞戒备森严的殿堂之中，由皇家卫兵保护，十分安全。只要你不把麻烦直接带进王宫，这里就是王国中最安全、最安宁的前厅之一。",al={"祈愿厅安全吗","祈愿厅危险","祈愿厅的威胁"}}},fp="20,158,31.362.0,42.114.0,25.163.0,46.187.0,37.171.0"}
P.entries["subzone:pig-and-whistle-tavern"] = {n="Pig and Whistle Tavern",s="猪和哨声旅店是一家坐落在暴风城旧城区崎岖街区的热闹旅店。它是联盟旅客、当地工人和那些回忆着王国过往冲突的老兵们所钟爱的聚会场所。",h="猪和哨声旅店是一家坐落在暴风城旧城区崎岖街区的热闹旅店。它是联盟旅客、当地工人和那些回忆着王国过往冲突的老兵们所钟爱的聚会场所。",kw={"烹饪","肯多尔·卡邦卡","旧城区","猪和哨声旅店","暴风城","旅店"},ang={["faction:Alliance"]="对于路过首都的联盟士兵和旅客来说，这家旅店提供了一个温馨、质朴的炉火，以及与王国早期战争老兵共叙友谊的机会。",["profession:Cooking"]="烹饪技艺大师们经常会前往这家旅店寻找肯多尔·卡邦卡，他出售着来自艾泽拉斯各地的无与伦比的稀有烹饪食谱收藏。"},sec={{t="旧城区中的避风港",b="猪和哨声旅店坐落在旧城区布满砂砾、蜿蜒曲折的小巷中，为那些行走在首都较粗犷街区的人们提供温暖、麦芽酒和住宿。当城中的贵族聚集在大教堂广场和云石广场时，这家店则为普通市民、劳动人民和刚从路途归来的旅客提供服务。在旅店内，顾客可以找到像著名的食谱商人肯多尔·卡邦卡这样的商贩，还有那些一边啜饮着酒杯，一边交流着第一次和第二次战争回忆的饱经风霜的老兵。"}},faq={{q="猪和哨声旅店位于何处？",a="猪和哨声旅店坐落在暴风城的东部街区旧城区，那里以其军事营地、盗贼窝点和工人阶级居住区而闻名。",al={"猪和哨声旅店在哪里","猪和哨声旅店位置","旧城区旅店"}},{q="谁经常光顾这家旅店？",a="这家旅店在旅客、休班卫兵和交流第一次和第二次战争故事的老兵中很受欢迎，此外还有像烹饪食谱大师肯多尔·卡邦卡这样的著名商人。",al={"猪和哨声旅店里有什么人","猪和哨声旅店常客"}},{q="这家旅店提供什么服务？",a="猪和哨声旅店是一家旅店，疲惫的旅客可以在这里休息，购买食物、饮料和专业的烹饪食谱。",al={"猪和哨声旅店是旅店吗","猪和哨声旅店服务"}}},fx={["97956e92"]={q="猪和哨声旅店是什么地方？",a="猪和哨声旅店藏在暴风城的旧城区城区内，是一家热情好客的酒馆。它是疲惫的联盟旅人在外的家，提供温暖的炉火、烈酒和安全的栖身之所。老兵们常在馆内聚饮，追忆第一次战争和第二次战争，而旅人与当地居民则远离更为繁忙的贸易区，在此相聚交谈。",al={"猪和哨声旅店","猪和哨声旅店是什么"}},["7bd4ea21"]={q="猪和哨声旅店危险吗？",a="完全不危险。这家酒馆是一处宁静的避风港，始终受到暴风城卫兵的保护。虽然旧城区幽暗的小巷中可能藏着见不得光的交易，但酒馆里只有歇脚的旅人、互诉往昔征战故事的老兵，以及喝着麦酒放松身心的当地手艺人。",al={"猪和哨声旅店危险吗","猪和哨声旅店危险"}}},fp="22,154,20.279.0,44.146.0,25.183.0,38.108.0"}
P.entries["subzone:plaguemist-ravine"] = {n="毒雾峡谷",s="毒雾峡谷是一条狭窄的山间通道，连接着辛特兰苍翠的荒野与西瘟疫之地达隆米尔湖阴魂不散的湖岸。它因北方涌来的病态浓雾而得名，是一条穿越山脉的幽静荒凉之路。",h="毒雾峡谷是一条狭窄的山间通道，连接着辛特兰苍翠的荒野与西瘟疫之地达隆米尔湖阴魂不散的湖岸。它因北方涌来的病态浓雾而得名，是一条穿越山脉的幽静荒凉之路。",kw={"凯尔达隆","达隆米尔","辛特兰","山口","瘟疫之雾","毒雾峡谷","奎尔丹尼","西瘟疫之地"},ang={["class:Hunter"]="峡谷是一处平静的过渡地带，但这里既无猎物，也无林间野兽，因此对向北进入瘟疫之地的追踪者而言，这片边界显得格外诡异。",["faction:Alliance"]="这条通道为驻扎在奎尔丹尼小屋的联盟侦察兵提供了一条隐蔽的路线，使他们能够监视凯尔达隆周围受腐蚀的湖岸，而无需面对大路上的巡逻队。"},sec={{t="疫病之地的门户",b="毒雾峡谷隐于奎尔丹尼小屋西北方的群山之中，是两片截然不同地域之间的地理分界。南面是辛特兰繁茂而原始的高地森林，北面的山口则直通凯尔达隆与西瘟疫之地遭疫病侵蚀的广袤土地。峡谷因从瘟疫之地向南蔓延的污浊异雾而得名，这些雾气与邻近荒野清冽的山间空气形成了刺眼的反差。"},{t="寂静的通道",b="尽管峡谷直通遭天灾军团蹂躏的地域边缘，谷内却出奇地荒寂。旅人在峡谷中既见不到野兽，也见不到游荡的亡灵。正因这份诡异的寂静，这条蜿蜒的小径成了一条便利却又阴森的小路，供大胆的信使和冒险者绕过通往洛丹伦、戒备森严的大道与边境关卡。"}},faq={{q="毒雾峡谷通往哪里？",a="毒雾峡谷连接辛特兰与西瘟疫之地。向北走，便会来到凯尔达隆这座岛上要塞附近的达隆米尔湖岸；向南走，则会进入奎尔丹尼小屋西北方林木覆盖的丘陵。",al={"毒雾峡谷通往哪里","毒雾峡谷路线","毒雾峡谷连接区域"}},{q="为什么叫毒雾峡谷？",a="这处山口最近才得名，缘由是从西瘟疫之地向南飘散、无处不在的疫病浓雾。这里病态的空气与辛特兰一贯清新、未受污染的气息形成了鲜明对比。",al={"为何叫毒雾峡谷","毒雾峡谷名称由来"}},{q="峡谷里有敌人或非玩家角色吗？",a="没有。峡谷中完全没有敌对生物、野生动物或友善的非玩家角色，因此成了两个活跃区域之间一条格外寂静的通道。",al={"毒雾峡谷怪物","毒雾峡谷安全吗"}},{q="如何找到辛特兰一侧的入口？",a="在辛特兰，入口隐于北面的山壁中，位于奎尔丹尼小屋以西、拉普索迪·铁铲的营地以北。",al={"如何找到毒雾峡谷","毒雾峡谷入口"}}},fp="17,187,20.397.0,15.342.0,34.227.0,35.202.0,44.153.0,48.138.0"}
P.entries["subzone:plaguewood"] = {n="病木林",s="病木林曾经是一片名为“绿木林”的宁静林地，如今却成了一片位于斯坦索姆以南、充满了腐化与真菌的荒芜之地。这里爬满了天灾军团的建筑，还有四处巡逻的血色十字军，是东瘟疫之地最腐败的角落之一。",h="病木林曾经是一片名为“绿木林”的宁静林地，如今却成了一片位于斯坦索姆以南、充满了腐化与真菌的荒芜之地。这里爬满了天灾军团的建筑，还有四处巡逻的血色十字军，是东瘟疫之地最腐败的角落之一。",kw={"真菌","绿木林","病木林","天灾军团","屠宰场","斯坦索姆","恐惧谷","通灵塔"},ang={["class:Paladin"]="病木林中扭曲的树木和邪恶的大锅令人痛苦地回想起洛丹伦的陷落，任何圣光的勇士都必须在这里面对成群的憎恶和顽固的狂热分子。",["faction:Alliance"]="对于幸存的联盟成员来说，走在这些小径上意味着重走阿尔萨斯王子当年通往斯坦索姆的清洗之路，而如今这条路已经淹没在腐烂和疯狂的血色十字军教徒之中。"},sec={{t="从绿木林到腐朽",b="在第三次战争之前，这一地区被称为绿木林，是一片与葱郁的艾尔文森林不相上下的生机勃勃的林地。入口附近曾有一个简朴的村庄，农夫和士兵常来常往。但当从安多哈尔运来的被污染的粮食抵达后，这一切便化为乌有。如今，松软且腐烂的土壤取代了肥沃的土地，巨大的蘑菇遮蔽了枯死的树木，不断向林地表面喷吐着有害的褐色蒸汽。"},{t="死亡的堡垒",b="病木林现已完全被天灾军团占据，成为了环绕斯坦索姆的不死生物的阴森集结地。通灵塔和屠宰场星罗棋布地散落在腐朽的土地上，源源不断地制造出憎恶和邪教徒。更糟糕的是，狂热的血色十字军在通往斯坦索姆大门的道路上不分昼夜地巡逻，他们急于肃清天灾军团，并会残忍地屠杀遇到的任何活着的旅行者。"}},faq={{q="瘟疫发生前，这片森林叫什么名字？",a="在第三次战争之前，该地区被称为绿木林。它曾是一片繁茂的森林，入口处有一个小村庄，在美景和气候上与艾尔文森林非常相似。",al={"病木林旧称","绿木林背景知识","病木林是什么"}},{q="为什么这里到处长着巨大的蘑菇？",a="瘟疫从根本上扭曲了当地的生态系统。土壤变得松软，巨大的真菌在林地上疯狂生长，喷发出有害的褐色云雾，就像瘟疫大锅里冒出的蒸汽一样。",al={"病木林巨型蘑菇","病木林真菌","为什么有蘑菇"}},{q="如今谁控制着病木林？",a="这片森林几乎完全被天灾军团控制，其中包括亡灵法师、食尸鬼、通灵塔和屠宰场。此外，血色十字军的巡逻队经常在主干道上行进，攻击所见的不死生物和任何活着的旅行者。",al={"谁统治病木林","病木林敌人","谁住在病木林"}},{q="穿过森林的路通向哪里？",a="主路直接向北延伸，通往陷落的斯坦索姆城大门，而这片被瘟疫侵蚀的森林西部则向着废弃的恐惧谷延伸。",al={"病木林道路终点","小径通向何处","斯坦索姆之路"}}},fp="10,142,23.362.0,21.321.0,46.156.0,51.160.0,34.197.0,43.128.0"}
P.entries["subzone:plaguewood-tower"] = {n="Plaguewood Tower",s="病木林哨塔是一座洛丹伦的废弃哨塔，位于病木林北端，临近恐惧谷。在天灾军团入侵期间，它被摧毁殆尽，如今只剩下一片残垣断壁，矗立在这片被瘟疫侵蚀的森林中。",h="病木林哨塔是一座洛丹伦的废弃哨塔，位于病木林北端，临近恐惧谷。在天灾军团入侵期间，它被摧毁殆尽，如今只剩下一片残垣断壁，矗立在这片被瘟疫侵蚀的森林中。",kw={"东瘟疫之地","洛丹伦","哨站","病木林","病木林哨塔","天灾军团","恐惧谷","瞭望塔"},ang={["faction:Alliance"]="对于联盟军队来说，洛丹伦这些破碎的瞭望塔是一个痛苦的提醒，时刻警示着他们人类失守于天灾军团的领土。",["faction:Horde"]="对于部落来说，像病木林哨塔这样的废弃防御工事展示了天灾军团是如何彻底击垮北方王国的防御的。"},sec={{t="北方的废墟哨岗",b="病木林哨塔坐落在被瘟疫笼罩的病木林边缘，毗邻遭到腐蚀的城镇恐惧谷，曾经是洛丹伦王国重要的北方监视哨。当天灾军团席卷这片大地时，这座防御工事被夷为废墟，留下的残砖碎石被淹没在受腐蚀的真菌树冠之下。如今，这些破裂的石块依然俯瞰着北方的道路，无声地提醒着人们，洛丹伦曾经在这片土地上履行过守望的职责。"}},faq={{q="病木林哨塔最初的用途是什么？",a="病木林哨塔由洛丹伦王国建造，作为区域性的瞭望塔。在第三次战争之前，驻扎在此的卫兵负责守卫北方的森林、道路和像恐惧谷这样的定居点，直到天灾军团攻陷并摧毁了这处驻地。",al={"最初用途","谁建造了病木林哨塔","哨塔历史"}},{q="这座塔的具体位置在哪里？",a="它位于东瘟疫之地的北部区域，在病木林内，紧邻已成废墟的恐惧谷，位于斯坦索姆外围瘟疫区的南面。",al={"哨塔位置","病木林哨塔在哪里","地图位置"}}},fp="16,164,30.365.0,46.236.0,35.164.0"}
P.entries["subzone:pool-of-ask-ar"] = {n="Pool of Ask'ar",s="Pool of Ask'ar是一个广阔的淹没式洞穴湖泊，位于黑暗深渊的深处。这里挤满了水生野兽和邪恶的纳迦入侵者，其水下隐藏着古老的暗夜精灵建筑，以及蜿蜒深入这座堕落圣殿的隐秘通道。",h="Pool of Ask'ar是一个广阔的淹没式洞穴湖泊，位于黑暗深渊的深处。这里挤满了水生野兽和邪恶的纳迦入侵者，其水下隐藏着古老的暗夜精灵建筑，以及蜿蜒深入这座堕落圣殿的隐秘通道。",kw={"黑暗深渊","淹没的神殿","加摩拉","萨利维丝","洛迦里斯手稿","纳迦","阿斯卡之池"},ang={["faction:Alliance"]="必须穿过这些水路才能揭开银月守卫塞尔瑞德的命运，他为了执行对抗暮光之锤的神圣任务而冒险进入了这些洞穴深处。",["race:NightElf"]="水潭淹没了曾经神圣的艾露恩神殿区域，淹没了古老的建筑，并将洛迦里斯手稿等神圣遗物散落各处，任由纳迦搜刮。"},sec={{t="沉没洞穴的深处",b="Pool of Ask'ar位于Drowned Sacellum之外，填满了一个巨大的地下穹顶，水质浑浊而冰冷。天然洞穴和古老的石构建筑已成为大型鳄龟和深海蟹的筑巢地，由巨大的远古龟类加摩拉监视着。占据了神殿的纳迦将这个淹没的门槛用作防御集结地，守卫着通往建筑深处，前往萨利维丝和月光神殿废墟的积水通道。"},{t="水面之下的秘密",b="除了怪异的动物群和敌对巡逻队，水潭的水下还隐藏着神殿大分裂之前的珍贵遗物。沿着洞穴边缘的淹没岩架和隐蔽壁龛藏匿着失落的神器，包括铁炉堡的矮人学者葛利·硬骨所寻找的珍贵的洛迦里斯手稿。游过洪水泛滥的南部通道，旅行者将进入由邪恶鱼人和古神信徒守卫的干燥隧道，这使得水潭成为了黑暗深渊关键的水路十字路口。"}},faq={{q="阿斯卡之池是什么？",a="这是一个位于黑暗深渊内的巨大地下水潭，就在淹没的祭坛的后面。这里主要由鳄龟、螃蟹和纳迦守卫占据。",al={"阿斯卡之池","这是什么水潭","黑暗深渊水域"}},{q="谁居住在这个地下水潭里？",a="这个洞穴栖息着野生礁石生物，例如鳄龟和螃蟹，其中最引人注目的是巨大的龟类加摩拉。敌对的纳迦也巡逻着淹没的岸边和附近的房间。",al={"水潭怪物","阿斯卡之池首领","水潭里有什么"}},{q="水下隧道通向哪里？",a="穿过洪水泛滥的南部通道，可以通向由萨利维丝和银月守卫塞尔瑞德占据的房间，并通往绕过格里哈斯特前往月光神殿废墟的道路。",al={"水潭隧道","水路通向哪里","阿斯卡之池出口"}},{q="在这个水潭里可以找到什么值得注意的物品？",a="沿水潭边缘的淹没废墟中藏有洛迦里斯手稿，这是一份关于古神的古老文献，被铁炉堡的葛利·硬骨所垂涎。",al={"阿斯卡之池遗物","洛迦里斯手稿","水潭掉落"}}},fp="14,173,27.421.0,27.444.0,27.158.0,36.166.0,37.170.0,44.133.0"}
P.entries["subzone:pool-of-tears"] = {n="泪水之池",s="泪水之池是一片广阔而浑浊的湖泊，占据了悲伤沼泽的东部区域。在它深邃的湖面之下，坐落着沉没的神庙（阿塔哈卡神庙），它由绿龙军团摧毁并沉入湖底，以封印其中的恐怖。如今，凶猛的狂乱鱼群巡游在浑浊的水中，古老的巨魔遗迹散落在被淹没的岸边。",h="泪水之池是一片广阔而浑浊的湖泊，占据了悲伤沼泽的东部区域。在它深邃的湖面之下，坐落着沉没的神庙（阿塔哈卡神庙），它由绿龙军团摧毁并沉入湖底，以封印其中的恐怖。如今，凶猛的狂乱鱼群巡游在浑浊的水中，古老的巨魔遗迹散落在被淹...",kw={"阿塔莱","狂乱鱼群","泪水之池","沉没的神庙","悲伤沼泽","阿塔哈卡神庙","伊瑟拉"},ang={["class:Druid"]="德鲁伊对这座湖泊怀有敬意，他们认为这是伊瑟拉和绿龙军团介入并遏制血神腐化的地方。",["race:Troll"]="对于暗矛巨魔来说，这片水池是一个严峻的警示，提醒他们如果巨魔一族沉迷于阿塔莱那样被禁的血魔法，会发生什么。"},sec={{t="一座被淹没的圣所",b="很久以前，狂热的阿塔莱巨魔为他们嗜血的神灵——“噬魂者”哈卡，建立了一座宏伟的阶梯金字塔。龙王伊瑟拉对其中发生的亵渎行为感到震惊，她震碎了建筑物下方的地面，将这座庞大的神庙沉入沼泽深处。现有的湖水淹没了神庙的废墟。虽然巨龙试图永远埋葬这份邪恶，但这座金字塔依然矗立在淤泥和波涛之下，绿龙幼龙依然在这一地区保持警惕，以封印其中的腐化。"},{t="危险之水",b="对于任何前往沉没大厅的冒险者来说，航行在这片浑浊的湖面上都是危机四伏的。食肉的狂乱鱼群出没在水中，而阿塔莱的神器和被淹没的石制建筑依然散落在泥泞的湖底。旅行者必须勇敢地面对这些充满敌意的浅滩，才能进入沉没神庙的上层通道，那里的邪教徒和徘徊的龙族守卫正在争夺这座黑暗圣所的控制权。"}},faq={{q="为什么它被称为泪水之池？",a="这个名字的由来并无记载。这座湖泊以阿塔哈卡神庙而闻名，伊瑟拉将其沉入水底，以阻止哈卡的召唤。",al={"泪水之池名字由来","为什么叫泪水之池","泪水之池的含义"}},{q="湖中心那座巨大的建筑是什么？",a="那是阿塔哈卡神庙，通常被称为沉没的神庙。它曾是一座高耸的阿塔莱阶梯金字塔，被伊瑟拉沉入水底，如今仍然部分淹没在湖泊的中心。",al={"泪水之池里的建筑","悲伤沼泽湖泊中的遗迹","沉没的神庙位置"}},{q="为什么水边会有绿龙？",a="伊瑟拉的族群来到这里摧毁了神庙，并淹没了它那邪恶的仪式。绿龙幼龙和龙人依然守护着这片湖泊，以确保阿塔莱邪教徒无法完成他们对血神的召唤。",al={"悲伤沼泽的绿龙","为什么这里有龙","伊瑟拉 神庙 湖泊"}},{q="游过这个湖泊安全吗？",a="不安全。湖中到处都是极具攻击性的食肉狂乱鱼群，它们会攻击任何游向神庙入口的人。",al={"泪水之池游泳","泪水之池的狂乱鱼群","悲伤沼泽的狂乱鱼群"}}},fp="13,151,19.383.0,15.339.0,35.164.0,55.218.0,45.199.0,35.108.0"}
P.entries["subzone:pools-of-arlithrien"] = {n="阿里斯瑞恩之池",s="阿里斯瑞恩之池是位于泰达希尔西部的一片隐秘泉水，就在达纳苏斯大门以南。这里曾经是一处以神圣月亮井为中心的静谧休憩之所，但如今却因当地野生生物和附近怀恨在心的棘木熊怪的侵扰，变得荒废且危险。",h="阿里斯瑞恩之池是位于泰达希尔西部的一片隐秘泉水，就在达纳苏斯大门以南。这里曾经是一处以神圣月亮井为中心的静谧休憩之所，但如今却因当地野生生物和附近怀恨在心的棘木熊怪的侵扰，变得荒废且危险。",kw={"阿里斯瑞恩","达纳苏斯","熊怪","棘木","月亮井","阿里斯瑞恩之池","泰达希尔"},ang={["class:Druid"]="研究泰达希尔失衡现象的德鲁伊们认为，这里桀骜不驯的野生生物和荒废的月亮井，是这棵巨树缺乏自然真正祝福的又一征兆。",["race:NightElf"]="在达纳苏斯附近废弃一座神圣月亮井，这对于暗夜精灵来说是一个令人不安的提醒，意味着腐化和混乱正在泰达希尔蔓延。"},sec={{t="一处困顿的圣所",b="阿里斯瑞恩之池掩映在达纳苏斯南部的阴凉树荫之下，最初本是一处充满自然和谐的宁静之地。其核心是一口石质月亮井，其中盛满了被艾露恩恩泽所灌注的井水。然而，尽管此处离暗夜精灵首都近在咫尺，却已变得危机四伏。焦躁的野兽在浅滩徘徊，加上流离失所的棘木熊怪持续不断的敌意，迫使暗夜精灵放弃了对该遗址的日常维护，使得这处宁静的奇迹笼罩在岛屿日益增长的不安阴影之下。"}},faq={{q="阿里斯瑞恩之池位于何处？",a="这些水池坐落在泰达希尔的西部边缘，位于通往首都达纳苏斯的主桥和入口以南。",al={"阿里斯瑞恩之池位置","阿里斯瑞恩在哪里","阿里斯瑞恩地图"}},{q="为什么这里的月亮井会被废弃？",a="由于危险日益增加，暗夜精灵撤出了对月亮井的日常照料。充满敌意的棘木熊怪在附近建立了威胁性的据点，而富有攻击性的森林野生生物也占领了周围的水域。",al={"为何废弃","阿里斯瑞恩月亮井废弃","空置的月亮井"}},{q="旅行者在水池会遇到什么威胁？",a="在水池附近徘徊的旅行者不仅要面对占领了水域的攻击性林地生物，还要提防附近极具领地意识的棘木熊怪所带来的威胁。",al={"阿里斯瑞恩怪物","阿里斯瑞恩之池小怪","水池处的敌人"}},{q="玩家还能使用阿里斯瑞恩之池的月亮井吗？",a="可以。尽管由于当地的危险，祭司和德鲁伊已经不再照料并废弃了这里，但月亮井本身依然保存着神圣的井水，仍然是月亮精华的有效来源。",al={"使用阿里斯瑞恩月亮井","月亮井是否可用","水池的水"}}},fp="19,205,20.420.0,42.107.0,36.171.0,45.108.0,62.150.0"}
P.entries["subzone:pools-of-vision"] = {n="预见之池",s="预见之池是位于雷霆崖灵魂高地下方的一处地底洞穴。这里水面平静，光线昏暗，是一处隐蔽的地下空间，也是被遗忘者在牛头人主城内的主要聚集地。",h="预见之池是位于雷霆崖灵魂高地下方的一处地底洞穴。这里水面平静，光线昏暗，是一处隐蔽的地下空间，也是被遗忘者在牛头人主城内的主要聚集地。",kw={"污染者","被遗忘者","法师传送门","预见之池","灵魂高地","雷霆崖","亡灵聚集地"},ang={["class:Mage"]="该洞穴锚定了通往城市的奥术地脉连接；任何织入雷霆崖的传送法术都会将施法者直接传送到这些隐蔽的池水旁。",["race:Undead"]="对于穿越卡利姆多平原的被遗忘者来说，这处洞穴提供了一个熟悉且阴凉的避难所，配备了奥术资源、牧师指引和同伴情谊。"},sec={{t="台地之下的避难所",b="虽然雷霆崖阳光明媚的峰顶属于风、大地和天空，但预见之池却直通灵魂高地下方的幽暗深处。通过通往高地的桥梁旁一条不起眼的洞穴小径即可进入，这处地下石窟提供了一种与上方露天营地截然不同的幽静休憩之所。薄雾笼罩的池水在此汇聚，营造出一种隔绝的氛围，部落的施法者们聚集于此，远离了喧闹的中央台地。"},{t="亡灵前哨",b="在雷霆崖，预见之池实际上是被遗忘者的行动基地。来自东部王国的旅行者在这里能找到志同道合的同伴：练习暗影之道的亡灵牧师、施展奥术传送门的法师，以及为阿拉希高地的战事招募新兵的污染者特使。无论是出于牛头人的猜忌，还是被遗忘者自身对黑暗的偏好，这处安静的避难所连接起了洛丹伦的亡灵与他们在卡利姆多的盟友。"}},faq={{q="预见之池的入口在哪里？",a="入口位于灵魂高地上，就在穿过从下层台地通往高地的木制绳桥后，右侧即是。",al={"如何前往预见之池","预见之池入口","预见之池在哪里"}},{q="为什么被遗忘者住在这里？",a="这个洞穴是驻扎在雷霆崖的被遗忘者的中心枢纽。它提供了躲避卡利姆多强烈阳光的庇护所，并容纳了那些可能会让传统牛头人灵术士感到不安的修行活动。",al={"为什么亡灵在这里","为什么被遗忘者在洞穴里","雷霆崖亡灵"}},{q="在预见之池里可以找到哪些服务？",a="洞穴内有牧师和法师的训练师与修行者，还有为阿拉希高地战争招募士兵的污染者特使。",al={"预见之池训练师","预见之池有什么"}},{q="法师传送到雷霆崖时会到达哪里？",a="施放传送或开启通往雷霆崖的传送门的法师，会直接出现在灵魂高地下方预见之池那片隐蔽的水域中。",al={"法师传送雷霆崖位置","雷霆崖传送点"}}},fp="15,154,24.263.0,18.365.0,45.109.0,38.212.0,54.135.0,58.127.0"}
P.entries["subzone:purgation-isle"] = {n="赎罪岛",s="赎罪岛是一座蜿蜒崎岖的岩石岛屿，位于希尔斯布莱德丘陵南部的海岸外。这座荒凉的礁石岛上矗立着一座墓地和一座荒废的侦察塔，它被诅咒所笼罩，到处都是人类和矮人死后不安、受谴责的灵魂。",h="赎罪岛是一座蜿蜒崎岖的岩石岛屿，位于希尔斯布莱德丘陵南部的海岸外。这座荒凉的礁石岛上矗立着一座墓地和一座荒废的侦察塔，它被诅咒所笼罩，到处都是人类和矮人死后不安、受谴责的灵魂。",kw={"被诅咒的阿拉多斯","希尔斯布莱德","法官塞尔格拉姆","科尔莫克","赎罪岛","灵魂"},ang={["class:Paladin"]="被诅咒的圣骑士和审判官在赎罪岛上游荡的悲惨景象，令人沉重地意识到，当神圣的保卫者堕落于黑暗诅咒并被拒绝永恒安息时，会发生什么。",["race:Dwarf"]="在墓地中游荡的受诅咒幽灵中，还有矮人的灵魂，将你的族人束缚在这块远离卡兹莫丹群山的孤独而多风的岩石上。"},sec={{t="一个闹鬼的避难所",b="赎罪岛从希尔斯布莱德以南的海面上突兀地升起，是一处阴森的地方，蜿蜒的小径穿过墓碑，通向一座废弃的瞭望塔。如今没有任何活着的国家宣称拥有它。相反，这座岛屿饱受受谴责的灵魂折磨——曾经的圣骑士、牧师、法师和法官在坟墓间游荡，无法在死亡中获得安宁。"},{t="黑暗关联",b="困在岛上的游魂使其成为了一个充满邪恶意味的地方。据说食人魔死灵法师科尔莫克（库尔莫克）等黑暗施法者很乐于利用岛上痛苦的死者，召唤这些灵魂为他们效命。"}},faq={{q="赎罪岛位于哪里？",a="赎罪岛是一座与世隔绝的岛屿，位于希尔斯布莱德丘陵南海岸外，坐落在大陆以南的海湾中。",al={"赎罪岛位置","赎罪岛在哪里","如何找到赎罪岛"}},{q="什么在岛上游荡？",a="岛上到处都是强大的受谴责灵魂，包括被诅咒的圣骑士、审判官、牧师、侍僧，以及人类和矮人后裔的痛苦法师。",al={"赎罪岛上有什么人","赎罪岛怪物","赎罪岛鬼魂"}},{q="科尔莫克是谁，他为什么关心这座岛屿？",a="科尔莫克是一位臭名昭著的食人魔死灵法师，他掌握了利用特制的黑暗神器召唤赎罪岛上受谴责的灵魂为他效劳的技巧。",al={"科尔莫克关联","召唤火盆鬼魂"}}},fx={["17b72096"]={q="赎罪岛是什么地方？",a="赎罪岛从希尔斯布莱德丘陵以南的海面上拔地而起，是一座盘旋而险峻的岩石岛屿，顶端矗立着杂草丛生的墓园和一座已成残垣的旧瞭望塔。这里早已沦为废墟，荒无人烟，与大陆隔绝，活着的水手都避而远之。",al={"赎罪岛是什么地方","赎罪岛","介绍赎罪岛"}},["6d7a3de4"]={q="赎罪岛危险吗？",a="这里极其危险。岛上遍布不得安息、饱受折磨的幽灵，他们生前是被判罪的圣骑士、牧师、法师和法官，会猛烈攻击任何登岸的活物。更黑暗的势力也企图利用他们；食人魔通灵师库尔莫克因将这些受折磨的灵魂束缚于自己的黑暗意志而臭名昭著。",al={"赎罪岛有多危险","赎罪岛安全吗","赎罪岛的危险"}}},fp="14,186,19.277.0,17.222.0,32.96.0,23.158.0,53.149.0"}
P.entries["subzone:pyrewood-village"] = {n="焚木村",s="焚木村是一座位于银松森林南部、影牙城堡下方的人类定居点。它原本属于吉尔尼斯，但在格雷迈恩之墙建立后被遗弃在墙外。如今，居住在这里的居民正深受疯狂大法师阿鲁高所降下的恐怖诅咒折磨。",h="焚木村是一座位于银松森林南部、影牙城堡下方的人类定居点。它原本属于吉尔尼斯，但在格雷迈恩之墙建立后被遗弃在墙外。如今，居住在这里的居民正深受疯狂大法师阿鲁高所降下的恐怖诅咒折磨。",kw={"阿鲁高","格雷迈恩之墙","月怒","焚木村","影牙城堡","银松森林"},ang={["faction:Alliance"]="这座村庄是洛丹伦幸存人类的一个悲剧缩影，他们白天愿意与旅人进行贸易，而每当黑夜降临，便会屈服于那恐怖的诅咒。",["faction:Horde"]="对于被遗忘者来说，焚木村是一处就在他们边境线上、由敌对人类和侍奉大法师阿鲁高的恐怖狼人所盘踞的据点。"},sec={{t="被切断的城镇",b="焚木村曾是一个繁荣的吉尔尼斯定居点。第二次战争结束后，吉恩·格雷迈恩国王决定将王国封锁在巨大的格雷迈恩之墙后，而焚木村却被留在了城墙北侧。随着天灾军团横扫洛丹伦，被切断了与故国联系的镇民在第三次战争中完全失去了防卫力量。尽管他们侥幸躲过了亡灵大军的第一波进攻，但真正的噩梦却在大法师阿鲁高占据了上方要塞后开始了。"},{t="月怒诅咒",b="大法师阿鲁高从影牙城堡的塔楼中向周围的土地释放了来自异界的野兽，最终诅咒了焚木村的所有活人。白昼之时，镇民看起来与普通人类无异，他们安分地维护着市政厅、铁匠铺和教堂，甚至还会与到访的联盟旅人进行贸易。然而一旦太阳落入地平线，恐怖的变身便会发生：每一位镇民都会转变为残暴嗜血的月怒狼人，并攻击任何不幸滞留在城墙内的生灵。"}},faq={{q="为什么焚木村在晚上会攻击我？",a="镇民们受到了影牙城堡的大法师阿鲁高所施加的黑暗诅咒。在白天，他们保留着人类的形态和正常的思维，但每当夜幕降临，他们就会变身为贪婪的月怒狼人，攻击所有见到的外来者。",al={"焚木村夜间敌对","焚木村狼人变身","为什么他们是狼人"}},{q="为什么焚木村在格雷迈恩之墙外？",a="第二次战争后，吉恩·格雷迈恩国王下令建造格雷迈恩之墙，将吉尔尼斯与外部世界隔绝开来。焚木村恰好位于围墙的另一侧，导致其居民不得不自谋生路。",al={"为什么在墙外","焚木村是吉尔尼斯的吗"}},{q="联盟玩家可以安全地访问焚木村吗？",a="可以，但必须是在白天。当太阳升起时，联盟旅人可以在镇民中行走，并与村里的商人们进行交易。然而，一旦夜幕降临，无论你的阵营为何，整个村庄都会变身为敌对的狼人。",al={"联盟在焚木村是否友好","联盟可以去焚木村吗","焚木村商人"}},{q="部落如何看待焚木村？",a="被遗忘者认为该村庄是对其南部边境无法容忍的威胁。在亡灵哨兵费雷亚等特工的指挥下，部落试图刺杀该村的议会成员，并切断焚木村与阿鲁高的联系。",al={"被遗忘者与焚木村","部落与焚木村敌对","亡灵哨兵费雷亚与焚木村"}}},fp="16,197,14.394.0,18.434.1,45.200.1,42.198.0,43.168.1,33.210.0"}
P.entries["subzone:quagmire"] = {n="泥潭沼泽",s="泥潭沼泽位于尘泥沼泽中央，是一片广阔而险恶的区域。它北接蕨墙村，南临黑龙谷，其积水的低地以难以通行而臭名昭著。敌对的野兽和贪婪的软泥怪使穿越这片中央湿地的旅程危机四伏。",h="泥潭沼泽位于尘泥沼泽中央，是一片广阔而险恶的区域。它北接蕨墙村，南临黑龙谷，其积水的低地以难以通行而臭名昭著。敌对的野兽和贪婪的软泥怪使穿越这片中央湿地的旅程危机四伏。",kw={"比吉尔","鳄鱼","尘泥","泥潭沼泽","塔贝萨"},ang={["class:Mage"]="在沼泽深处坐落着Tabetha's Farm，对于那些渴望远离肯瑞托视线、寻求神秘训练的有志法师来说，这里是一个至关重要的目的地。"},sec={{t="沼泽之心",b="泥潭沼泽占据了西起废弃哨塔，东至尘泥海湾的广阔地带，是整个沼泽的荒野核心。这里的地势极不稳定，坚实的土地常常会变成浑浊的水洼和粘稠的泥沼。旅行者不仅要提防潜伏在浮渣下的掠食性鳄鱼、筑巢于枯木丛中的凶猛蜘蛛，还要应对在污泥中渗透的诡异软泥怪。"},{t="逼近的冲突",b="除了自然险阻外，泥潭沼泽还是沼泽内各方势力争夺的变幻莫测的十字路口。在这片泥沼深处坐落着Tabetha's Farm，这是寻求隐士智慧的修行者在沼泽险境中唯一的避难所。"}},faq={{q="泥潭沼泽位于何处？",a="泥潭沼泽覆盖了尘泥沼泽的中心区域。它向西延伸至废弃哨塔，向东延伸至尘泥海湾，北至蕨墙村边界，南抵土地下沉的黑龙谷。",al={"泥潭沼泽位置","泥潭沼泽在哪里","泥潭沼泽地图"}}},fp="8,210,16.299.0,19.232.0,30.194.0"}
P.entries["subzone:quel-lithien-lodge"] = {n="奎尔林斯小屋",s="奎尔林斯小屋是一座与世隔绝的高等精灵狩猎小屋，坐落在东瘟疫之地北部森林覆盖的丘陵地带，靠近通往奎尔萨拉斯的入口。这里的远行者游侠们在枯萎的森林中坚守阵地，他们不仅被天灾军团包围，还遭到被遗忘者特工的猎杀，同时他们还在守护着古老的精灵档案。",h="奎尔林斯小屋是一座与世隔绝的高等精灵狩猎小屋，坐落在东瘟疫之地北部森林覆盖的丘陵地带，靠近通往奎尔萨拉斯的入口。这里的远行者游侠们在枯萎的森林中坚守阵地，他们不仅被天灾军团包围，还遭到被遗忘者特工的猎杀，同时他们还在守护...",kw={"远行者","高等精灵","玛瑞斯农场","奎尔林斯","奎尔萨拉斯名册"},ang={["class:Hunter"]="驻扎在此的远行者代表了几个世纪以来经典的萨拉斯射术，他们在完全与文明社会隔绝的恶劣荒野中维持着生存技能。",["faction:Horde"]="在玛瑞斯农场的纳萨诺斯·凋零者的指挥下，部落勇士被派往此处执行一项致命的任务，旨在通过武力强行夺取高等精灵的记录。"},sec={{t="枯萎之地中的游侠营地",b="在第三次战争之前，奎尔林斯小屋曾是通往奎尔萨拉斯的道路上的一个远行者营地，里面存放着游侠部队的精灵记录。在天灾军团横扫洛丹伦并入侵精灵王国后，这座小屋陷入了困境。如今，这里的游侠们依然在被腐蚀的森林中保持警惕，这是洛丹伦仅存的两处高等精灵主要聚集地之一。"},{t="瘟疫之地的猎物",b="游侠们沉默的守望并非无人知晓。在被污染的森林深处，纳萨诺斯·凋零者——这位曾经与这些精灵们共同训练的孤独人类游侠领主——已经指挥部落勇士潜入奎尔林斯小屋。纳萨诺斯意图夺取“奎尔萨拉斯名册”，这份官方记录记载了游侠部队的详细信息和精灵血统，他下令屠杀小屋的守卫以获取它。奎尔林斯小屋的游侠们发现自己正同时受到昔日盟友和周边亡灵的围攻。"}},faq={{q="为什么东瘟疫之地会有活着的高等精灵？",a="这座小屋长期以来一直是一个远行者营地。即使在天灾军团将该地区夷为平地之后，这里的高等精灵游侠依然留守于此，在靠近通往奎尔萨拉斯的道路上守护着洛丹伦最后的一处精灵据点。",al={"为什么这里有高等精灵","奎尔林斯住着谁","奎尔林斯精灵"}},{q="奎尔林斯小屋的精灵属于联盟吗？",a="不属于。虽然他们对联盟旅行者表现友好，并对部落公开敌视，但该小屋作为一个完全自治的高等精灵定居点运作，没有接受来自暴风城或铁炉堡的任何正式支持或指令。",al={"奎尔林斯精灵属于联盟吗","奎尔林斯阵营"}},{q="为什么纳萨诺斯·凋零者要针对这个小屋？",a="纳萨诺斯·凋零者派遣部落特工攻击该小屋，主要是为了获取“奎尔萨拉斯名册”，这是一份记录了精灵游侠人员和档案的重要历史文件，目前仍存放在小屋的档案库中。",al={"纳萨诺斯为什么要攻击奎尔林斯","游侠领主的命令","奎尔萨拉斯名册"}},{q="奎尔林斯小屋与奎尔丹尼小屋有什么区别？",a="两者都是历史悠久的高等精灵狩猎小屋，但奎尔丹尼小屋坐落在辛特兰，处于友好的蛮锤矮人的保护之下。而奎尔林斯小屋则孤立地坐落在东瘟疫之地的最前线，被困在枯萎的废墟和封闭的奎尔萨拉斯大门之间。",al={"奎尔丹尼与奎尔林斯对比","辛特兰小屋对比"}}},fp="18,295,27.363.0,25.403.1,59.204.0,57.193.0,48.174.0,51.232.0"}
P.entries["subzone:rage-scar-hold"] = {n="怒痕堡",s="怒痕堡是开凿在菲拉斯荒野中的一个洞穴，坐落于大陆之上，距离羽月要塞不远。这里因栖息着该地区最凶残的雪人而臭名昭著。奇怪的是，洞穴深处散落的书籍、符号以及暗夜精灵建筑的痕迹表明，在这些野兽占据此地之前，这个大兽穴曾有着更文明的用途。",h="怒痕堡是开凿在菲拉斯荒野中的一个洞穴，坐落于大陆之上，距离羽月要塞不远。这里因栖息着该地区最凶残的雪人而臭名昭著。奇怪的是，洞穴深处散落的书籍、符号以及暗夜精灵建筑的痕迹表明，在这些野兽占据此地之前，这个大兽穴曾有着更文...",kw={"古墓穴","羽月","菲拉斯","魔法书籍","怒痕堡","雪人"},ang={["class:Mage"]="洞穴深处存在奥术符号和被遗弃的典籍，这引发了关于谁在洞穴深处丧命的令人不安的问题。",["race:NightElf"]="肮脏的雪人亵渎了看似古老的古墓穴或圣所，这无情地提醒着人们，荒野的危险正在重新夺回卡多雷的历史领地。"},sec={{t="野兽的领地",b="怒痕堡开凿在菲拉斯崎岖的荒野之中，被一群凶猛的雪人所占据，它们会袭击任何靠近巢穴的人。这些生物让周围的森林小径对联盟哨兵和过往旅人都变得危险重重。虽然雪人在卡利姆多的未开发地区很常见，但怒痕堡的居民却因其原始的侵略性和领地凶猛性而格外引人注目。"},{t="过去的痕迹",b="在洞穴深暗的走廊里，隐藏着古老居住者留下的微妙线索。雕刻的石制品和暗夜精灵风格的建筑暗示这里曾是一个古墓穴或奥术圣所。被遗忘的典籍和神秘的符号残留在泥土和骸骨之间，让旅人们不禁猜测，是不幸的学者遭到了野兽的屠杀，还是雪人受到了此地残留魔法的吸引。"}},faq={{q="怒痕堡是什么地方？",a="怒痕堡是菲拉斯的一个地下洞穴网络，位于大陆上，距离羽月要塞不远。它目前被一群极具攻击性的野性雪人所占据。",al={"怒痕堡","这个洞穴是什么","菲拉斯雪人洞穴"}},{q="为什么雪人巢穴里会有书籍和符号？",a="堡垒内部遗弃着典籍、卷轴和奥术符号。虽然这些野蛮的生物不可能识字或研究法术，但这些遗迹表明，这个洞穴曾是那些不幸的施法者或暗夜精灵学者的家园，他们最终成了雪人的受害者。",al={"为什么雪人洞穴里有书","雪人在研究魔法吗","怒痕堡书籍"}},{q="这个洞穴是暗夜精灵建造的吗？",a="洞穴内部有着暗夜精灵的石刻，以及令人想起古墓穴的洞穴结构。内部已没有活着的卡多雷，这意味着最初的居住者要么很久以前就废弃了此地，要么在雪人迁入时被消灭了。",al={"暗夜精灵建筑","怒痕堡曾是精灵古墓穴吗","菲拉斯古墓穴"}},{q="这里的雪人与其他卡利姆多的雪人有什么不同吗？",a="当地旅人指出，怒痕堡的雪人是菲拉斯同类中最凶猛、最具攻击性的，它们以野蛮的暴力守护着它们夺来的地下家园。",al={"菲拉斯雪人","这些雪人有多危险","怒痕堡野兽"}}},fp="14,183,16.255.0,18.224.0,23.132.0,50.163.0,37.191.0,53.142.0"}
P.entries["subzone:ragefire-chasm"] = {n="怒焰裂谷",s="怒焰裂谷是一片位于部落主城奥格瑞玛地下的火山洞穴网络。可以通过大断崖进入，其岩浆照亮的隧道中潜藏着野蛮的穴居人，还有一个妄图从内部瓦解年轻兽人国度的影子议会秘密教派。",h="怒焰裂谷是一片位于部落主城奥格瑞玛地下的火山洞穴网络。可以通过大断崖进入，其岩浆照亮的隧道中潜藏着野蛮的穴居人，还有一个妄图从内部瓦解年轻兽人国度的影子议会秘密教派。",kw={"巴扎兰","暗影裂口","祈求者耶戈什","奥格瑞玛","怒焰裂谷","灼热之刃","塔拉加曼","穴居人"},ang={["class:Warlock"]="灼热之刃及其恶魔主宰的存在，证明了萨尔的新部落正积极试图根除邪能魔法残留的腐蚀。",["faction:Horde"]="怒焰裂谷代表着主城心脏地带的一个严重安全危机，考验着年轻冒险者保护初生部落的决心。"},sec={{t="街道下的威胁",b="当萨尔在地面上努力巩固杜隆塔尔的同时，地下的危险正在奥格瑞玛的地基之下滋生。怒焰裂谷是一个由火山口和岩浆河组成的不稳定网络，如今已成了凶残的怒焰穴居人的巢穴。这些从隧道深处不明区域涌出的敌对生物，暴力地拒绝了玛加萨·野性图腾提出的外交提议。如果不加制止，它们庞大的数量将威胁到这座主城的根基并将其淹没。"},{t="灼热之刃",b="比穴居人更危险的是灼热之刃，这是一个在裂谷阴影中运作的恶魔影子议会的叛乱教派。在术士祈求者耶戈什、萨特巴扎兰，以及被称为饥饿者塔拉加曼的高大邪能卫士的指挥下，这些邪教徒密谋摧毁萨尔的部落。虽然尼鲁·火刃声称反对他们，但该教派正在积极地测试他们的力量，并试图从下方破坏兽人的新家园。"}},faq={{q="怒焰裂谷的入口在哪里？",a="入口位于奥格瑞玛深处的大断崖内，就在术士尼鲁·火刃的帐篷旁边。",al={"怒焰裂谷入口","如何前往怒焰裂谷","怒焰裂谷的位置"}},{q="谁住在怒焰裂谷里？",a="裂谷中充斥着极具攻击性的怒焰穴居人，并被灼热之刃占据，这是一个与影子议会有联系的邪教组织。他们的首领是术士祈求者耶戈什、萨特巴扎兰以及邪能卫士饥饿者塔拉加曼。",al={"怒焰怪物","怒焰裂谷里的敌人","谁控制了怒焰裂谷"}},{q="为什么萨尔没有清理这个裂谷？",a="部落在建立杜隆塔尔和防御外部威胁方面已捉襟见肘。大酋长萨尔依靠有能力的勇士深入洞穴，在穴居人突破城市街道之前消灭灼热之刃的领导层并控制穴居人的数量。",al={"为什么萨尔容忍怒焰裂谷存在","萨尔怒焰裂谷"}},{q="联盟玩家可以进入怒焰裂谷吗？",a="可以，但想要到达那里需要潜入奥格瑞玛的大门，并深入守卫森严的大断崖，这对联盟的冒险者来说是一项极其危险的任务。",al={"联盟可以打怒焰裂谷吗","联盟在怒焰裂谷"}}},fp="14,158,28.324.0,17.310.1,40.110.0,32.222.1,40.259.0,42.185.0"}
P.entries["subzone:ragefire-chasm-classic"] = {n="Ragefire Chasm (Classic)",s="怒焰裂谷是位于奥格瑞玛地下的一个广阔的火山隧道网，可以通过暗影裂口阴暗的深处进入。尽管位于部落主城的下方，这些灼热的洞穴中却爬满了敌对的穴居人，以及忠于暗影议会的阴谋邪教徒。",h="怒焰裂谷是位于奥格瑞玛地下的一个广阔的火山隧道网，可以通过暗影裂口阴暗的深处进入。尽管位于部落主城的下方，这些灼热的洞穴中却爬满了敌对的穴居人，以及忠于暗影议会的阴谋邪教徒。",kw={"巴扎兰","暗影裂口","祈求者耶戈什","怒焰裂谷","灼热之刃","饥饿者塔拉加曼","穴居人"},ang={["faction:Horde"]="清理怒焰裂谷是保卫家园的一环，旨在保护杜隆塔尔的基石免受内部破坏，并铲除恶魔同谋者。",["race:Tauren"]="长者玛加萨·野性图腾曾派遣使节与入侵的穴居人求和；他们血腥的拒绝证明了面对这些地底野兽，外交是不可能的。"},sec={{t="潜藏的危机",b="在奥格瑞玛坚硬的街道和高耸的塔楼之下，坐落着怒焰裂谷，这是一片充满岩浆的险恶地下洞穴。最近，这些隧道被从深层地壳裂隙中涌出的野蛮的怒焰穴居人所占据。来自牛头人的玛加萨·野性图腾曾试图与这些生物进行和平外交，但她的提议遭到了暴力的拒绝。如果不加以遏制，穴居人将威胁要进一步挖掘，直到危及城市本身的地基。"},{t="灼热之刃",b="比那些毫无理智的穴居人更危险的是“灼热之刃”的存在，这是一个隶属于恶魔暗影议会的叛乱邪教。在魁梧的邪能卫士饥饿者塔拉加曼、兽人术士祈求者耶戈什以及堕落萨特巴扎兰的领导下，这些阴谋家企图瓦解萨尔的部落在杜隆塔尔建立的一切。大酋长萨尔并没有立即清理这些洞穴，而是保持对他们活动的监视，希望他们愚蠢的过度自信能暴露暗影议会高层的行踪。"}},faq={{q="怒焰裂谷的入口在哪里？",a="入口传送门位于奥格瑞玛深处，具体是在被称为暗影裂口的地下峡谷中。它靠近兽人术士尼鲁·火刃的帐篷。",al={"怒焰裂谷在哪里","怒焰裂谷入口","如何前往怒焰裂谷","怒焰裂谷位于何处"}},{q="为什么奥格瑞玛下面会有穴居人？",a="穴居人从杜隆塔尔下方古老而深邃的洞穴系统中浮出，直接进入了城市的火山地底。他们突然的入侵对主城构成了结构和物理上的危害，而且他们拒绝任何和平遏制的尝试。",al={"为什么这里有穴居人","怒焰穴居人","奥格瑞玛穴居人"}},{q="为什么萨尔允许邪教徒生活在主城下面？",a="大酋长萨尔完全知晓邪教在城下的存在。他没有发动可能会导致更广泛的网络四散奔逃的粗暴突袭，而是让他们在严密监视下活动，希望他们能无意中揭露暗影议会真正领导者的身份和下落。",al={"为什么萨尔不清理怒焰裂谷","萨尔 暗影议会","为什么灼热之刃在奥格瑞玛地下"}},{q="谁领导着裂谷里的邪教徒？",a="怒焰裂谷里的灼热之刃由三个人物指挥：可怕的邪能卫士饥饿者塔拉加曼；兽人术士祈求者耶戈什；以及背叛的萨特巴扎兰。",al={"怒焰裂谷首领","谁领导灼热之刃","怒焰裂谷领袖"}}},fp="24,154,14.364.0,17.386.1,40.166.0,39.232.0,57.183.0,40.162.0"}
P.entries["subzone:raptor-grounds"] = {n="迅猛龙巢穴",s="迅猛龙巢穴位于南贫瘠之地尘土飞扬的丘陵深处，是一座被阳鳞迅猛龙占据的隐蔽山谷。与普通的野生野兽不同，这里的兽群展现出一种诡异、善于使用工具的狡黠，并且有一种强迫性地从附近定居点偷取闪亮饰品的冲动。",h="迅猛龙巢穴位于南贫瘠之地尘土飞扬的丘陵深处，是一座被阳鳞迅猛龙占据的隐蔽山谷。与普通的野生野兽不同，这里的兽群展现出一种诡异、善于使用工具的狡黠，并且有一种强迫性地从附近定居点偷取闪亮饰品的冲动。",kw={"北方城堡","迅猛龙巢穴","迅猛龙","被偷走的银币","阳鳞迅猛龙","贫瘠之地"},ang={["class:Hunter"]="阳鳞兽群不同寻常的狡黠、群体协调能力以及建造简易住所的能力，使其成为任何熟练追踪者眼中令人着迷的研究对象。",["faction:Horde"]="阳鳞迅猛龙对南贫瘠之地各处的部落车队和哨所构成了反复出现的威胁，促使人们针对被盗的财富发布悬赏并组织回收远征队。"},sec={{t="南部荒野的奇异野兽",b="迅猛龙巢穴位于北方城堡以西，是阳鳞迅猛龙的主要筑巢地。旅行者们很快就会发现，这些生物绝非毫无思想的掠食者：它们表现出非同寻常的智慧，会制造简陋的住所、组装原始工具，并协调进行狩猎。在对闪亮和奇异物品的执着驱使下，兽群经常袭击过往的车队和部落营地，将硬币、饰品和补给品拖回它们的峡谷巢穴中。"}},faq={{q="迅猛龙巢穴在哪里？",a="迅猛龙巢穴是南贫瘠之地南部的一座小型下沉式山谷，坐落在北方城堡以西的岩石丘陵中。",al={"迅猛龙巢穴位置","迅猛龙巢穴在哪里","迅猛龙巢穴地图"}},{q="为什么这里的迅猛龙与普通野兽不同？",a="阳鳞迅猛龙表现出非同寻常的智慧。它们不仅仅依赖野蛮的本能，还会组装原始工具并建造粗糙的小屋来庇护兽群并隐藏偷来的财物。",al={"阳鳞迅猛龙智慧","为什么迅猛龙会有小屋","贫瘠之地聪明的迅猛龙"}},{q="为什么迅猛龙会袭击车队并偷取物品？",a="兽群对闪闪发光或不同寻常的物体有着痴迷的吸引力。这种迷恋驱使它们伏击旅行者并洗劫部落定居点，将偷来的钱币和金属囤积在山谷深处。",al={"迅猛龙偷走的银币","为什么迅猛龙会偷东西","迅猛龙闪亮的东西"}},{q="谁控制着这个山谷？",a="没有任何阵营控制这个山谷。它依然是野生阳鳞迅猛龙未被驯服的狩猎和筑巢领地，它们会激烈地捍卫这里，抵御任何闯入者。",al={"谁拥有迅猛龙巢穴","迅猛龙巢穴属于部落吗"}}},fp="14,204,37.363.0,28.112.0,54.144.0,51.199.0,25.146.0"}
P.entries["subzone:raptor-ridge"] = {n="恐龙岭",s="恐龙岭是湿地东部一片高耸、崎岖的开阔地带，位于龙喉大门西北方。这里是成群凶猛的剃刀猛禽的主要狩猎和筑巢地，在洞穴深处由一只特别凶残的族群首领看守。",h="恐龙岭是湿地东部一片高耸、崎岖的开阔地带，位于龙喉大门西北方。这里是成群凶猛的剃刀猛禽的主要狩猎和筑巢地，在洞穴深处由一只特别凶残的族群首领看守。",kw={"龙喉大门","恐龙岭","剃刀猛禽","剃刀猛禽族母","湿地"},ang={["class:Hunter"]="山脊上凶猛的剃刀猛禽是任何猎人追求敏捷而顽强的沼泽伴侣时的强力选择。"},sec={{t="捕食者的巢穴",b="恐龙岭高耸于湿地东部的沼泽之上，是该地区最危险的荒野之一。凶猛的剃刀猛禽成群结队地徘徊在它的岩架和岩石小径上，使得卡兹莫丹山脚附近的旅行对漫游者来说危机四伏。山脊中心坐落着一个深邃的洞穴，由剃刀猛禽族母统治，其好斗的后代会猛烈地攻击任何入侵的掠食者，或是在龙喉大门附近徘徊的鲁莽旅人。"}},faq={{q="恐龙岭位于哪里？",a="恐龙岭位于湿地的最东端，正处于通往格瑞姆巴托的龙喉大门西北方。",al={"恐龙岭位置","恐龙岭在哪里","如何前往恐龙岭"}},{q="这里生活着哪些生物？",a="山脊上到处都是剃刀猛禽。在洞穴深处，旅行者还能发现正在看护巢穴和幼崽的剃刀猛禽族母。",al={"恐龙岭有哪些怪物","湿地的猛禽","恐龙岭野兽"}},{q="剃刀猛禽族母是谁？",a="剃刀猛禽族母是当地猛禽群中体型巨大且致命的领袖，它盘踞在山脊中央洞穴的巢穴中。",al={"剃刀猛禽族母","湿地猛禽族母","湿地猛禽首领"}},{q="为什么这个地区如此危险？",a="除了成群结队、速度极快且会围攻入侵者的猛禽外，山脊还处于山口附近敌对的龙喉兽人领地的阴影之下。",al={"恐龙岭是否危险","恐龙岭威胁"}}},fp="12,160,18.303.0,30.120.0,25.108.0,30.107.0,41.160.0"}
P.entries["subzone:ratchet"] = {n="棘齿城",s="棘齿城是贫瘠之地东海岸的一座繁华中立港口城镇，由热砂港管理。它由总工程师加兹鲁维在协助建造奥格瑞玛后建立，是连接卡利姆多中部与东部王国的海上贸易枢纽。",h="棘齿城是贫瘠之地东海岸的一座繁华中立港口城镇，由热砂港管理。它由总工程师加兹鲁维在协助建造奥格瑞玛后建立，是连接卡利姆多中部与东部王国的海上贸易枢纽。",kw={"贫瘠之地","藏宝海湾","加兹鲁维","少女之爱号","棘齿城","热砂港","斯坦哈德·法尔杉"},ang={["class:Warlock"]="坐落在棘齿城上方悬崖上的高塔，是一个主要的训练场，来自各地的术士们在斯坦哈德·法尔杉和梅纳拉·沃伦德的带领下聚集于此，钻研高等恶魔召唤术。",["faction:Alliance"]="对于联盟冒险者来说，棘齿城提供了一个难得的安全落脚点，使他们得以深入危机四伏的贫瘠之地中心，并可以使用船运和飞行航线。"},sec={{t="无尽之海的十字路口",b="棘齿城坐落在杜隆塔尔与尘泥沼泽之间的干旱海岸线上，为所有携带金币的人提供安全的避风港。这座港口由创业家工程师加兹鲁维在第三次大战争后建立，兴起于各路走私者、流亡者和想要发掘卡利姆多边境财富的大胆商贩之中。它在热砂港的旗帜下运作，在部落与联盟之间保持严格的中立。像“少女之爱”号这样的船只定期横跨无尽之海，航行至藏宝海湾，在各大陆之间运输货物、雇佣兵和原材料。当地的打手们紧盯着码头，严厉打击任何胆敢挑起事端并扰乱商业活动的人。"},{t="码头上的阴影",b="尽管棘齿城表面上是一座充斥着码头、酒馆和工坊的喧闹商贸城镇，但它背后也潜藏着更黑暗的交易。在俯瞰海港的山丘上，坐落着一座隐蔽的高塔，被一个公开的术士集会占据，其中包括斯坦哈德·法尔杉和梅纳拉·沃伦德等人物。当镇民和水手们忙于处理货物清单和地精工程时，这些黑魔法的修行者们在此自由地聚会，与恶魔力量进行沟通，不受传统阵营主城道德约束的困扰。"}},faq={{q="谁统治棘齿城？",a="棘齿城由总工程师加兹鲁维监管，他代表着中立的热砂港进行运作。在因为指导建设奥格瑞玛的基础设施而从大酋长萨尔那里获得了丰厚的报酬后，加兹鲁维建立了这座城镇。",al={"棘齿城领导者","谁负责棘齿城","加兹鲁维 棘齿城"}},{q="联盟玩家可以安全访问棘齿城吗？",a="可以。棘齿城是一座中立的地精港口。只要你与热砂港保持非敌对声望，且不攻击城内的任何人，无论是联盟还是部落的旅行者，都可以使用这里的旅店、银行、商贩、飞行点和渡轮。",al={"棘齿城对联盟安全吗","联盟在棘齿城","联盟能去棘齿城吗"}},{q="棘齿城的船去哪里？",a="停靠在南码头的船只“少女之爱”号，会横跨无尽之海航行至荆棘谷南端的藏宝海湾。它是连接卡利姆多与东部王国的主要海上航线之一。",al={"棘齿城船只目的地","棘齿城的船去哪里","前往东部王国的船"}},{q="为什么镇子上方山丘里有术士？",a="俯瞰棘齿城的高塔内住着一个由斯坦哈德·法尔杉和梅纳拉·沃伦德等人领导的术士集会。热砂港对黑魔法的漠不关心使得这些施法者能够在这里运作、教导学徒并召唤恶魔，而不会受到宗教或民事当局的干扰。",al={"棘齿城术士","斯坦哈德·法尔杉之塔","棘齿城术士塔"}},{q="如果我在棘齿城挑起争斗会怎样？",a="棘齿城打手会立即介入，用沉重的木棒和网兜攻击挑衅者。在地精定居点中，扰乱商业活动是严格禁止的，在这里战斗会迅速降低你与热砂港的声望。",al={"棘齿城守卫","在棘齿城攻击玩家","棘齿城打手"}}},fp="7,145,31.531.0,23.443.0,18.182.0,42.216.0,34.197.0,51.263.0,43.169.0"}
P.entries["subzone:ravaged-caravan"] = {n="被破坏的货车",s="“被破坏的货车”是一处位于莫高雷石牛湖北岸、仍在冒烟的残骸。这支运输队曾是运往主管菲兹斯普罗克特采矿作业点的补给车队，后遭到当地牛头人的伏击并被摧毁，牛头人此举意在阻止地精对其家园的掠夺。",h="“被破坏的货车”是一处位于莫高雷石牛湖北岸、仍在冒烟的残骸。这支运输队曾是运往主管菲兹斯普罗克特采矿作业点的补给车队，后遭到当地牛头人的伏击并被摧毁，牛头人此举意在阻止地精对其家园的掠夺。",kw={"莫高雷","被破坏的货车","石牛湖","主管菲兹斯普罗克特","牛头人","荆棘谷地精","货车"},ang={["class:Druid"]="笼罩在石牛湖岸边的黑烟，时刻提醒着人们地精机械对自然平衡所造成的鲁莽破坏。",["race:Tauren"]="这些烧焦的货车代表了你们的人民对于外国工业辛迪加企图玷污莫高雷神圣草场行为的直接而果断的拒绝。"},sec={{t="石牛湖上的浓烟",b="“被破坏的货车”坐落在石牛湖上方的高地上，标志着血蹄村的牛头人与不断侵蚀领土的荆棘谷地精之间爆发的早期冲突。这支车队原定将采矿补给品、蓝图和设备运往主管菲兹斯普罗克特的挖掘现场，但在抵达目的地前就被牛头人防守者拦截并摧毁。尽管遭受了如此惨重的破坏，顽固的荆棘谷地精幸存者仍死守着损毁的货车和冒烟的板条箱，极力守护着仅存的微薄物资。"}},faq={{q="这辆货车发生了什么事？",a="这辆货车被当地的牛头人拦截并摧毁，他们发现了荆棘谷地精深入莫高雷的企图。为了阻止地精掠夺这片土地，牛头人在补给物资运达附近矿洞前就摧毁了整个车队。",al={"为什么货车会被烧毁","这里发生了什么","被破坏的货车背景故事"}},{q="这些损毁的货车属于谁？",a="这辆货车属于荆棘谷地精，这是一个毫无底线的地精采矿财团，正试图在莫高雷的山丘上进行未经许可的非法开采活动。",al={"这是谁的货车","谁拥有这辆货车","荆棘谷地精货车"}},{q="这辆货车原本要前往哪里？",a="它当时正运载着工具、机械和补给品向北行进，目的地是主管菲兹斯普罗克特，他负责指挥荆棘谷地精在风险投资公司矿洞的露天采矿作业。",al={"货车目的地","它要去哪里","菲兹斯普罗克特的补给品"}},{q="为什么还有荆棘谷地精的工人在残骸处徘徊？",a="幸存的荆棘谷地精雇佣兵和工人们对公司的财产有着强烈的保护欲。他们不仅没有放弃这些损失，反而死守在烧焦的货车周围，试图抢救出哪怕是一点点残余的设备。",al={"为什么地精还在这里","荆棘谷地精幸存者","谁在守卫残骸"}}},fp="15,202,25.371.0,30.213.0,28.139.0,30.172.0,63.143.0"}
P.entries["subzone:ravaged-twilight-camp"] = {n="暮光营地废墟",s="暮光营地废墟隐匿在希利苏斯西北部偏远的水晶谷中，在耸立的矿石地层间残破不堪。这里是古怪的隐士德米提恩的孤立据点，他是一位逐风者的信徒。",h="暮光营地废墟隐匿在希利苏斯西北部偏远的水晶谷中，在耸立的矿石地层间残破不堪。这里是古怪的隐士德米提恩的孤立据点，他是一位逐风者的信徒。",kw={"水晶谷","德米提恩","暮光营地废墟","希利苏斯","桑德兰","雷霆之怒","暮光之锤"},ang={["class:Paladin"]="那些寻求古代传奇元素武器的人必须前往水晶谷寻找德米提恩，以解开桑德兰王子的容器。",["class:Warrior"]="任何追寻传奇武器“雷霆之怒，逐风者的祝福之剑”传闻的勇士，最终都会发现他们的道路直接指向这座被遗弃营地中的德米提恩。"},sec={{t="谷中的隐士废墟",b="虽然暮光之锤在希利苏斯的沙地各处拥有许多活跃的前哨站，但水晶谷中这座破败的营地却有着不同的故事。营地远离教派的主要堡垒，除德米提恩外，大部分已沦为废墟且无人居住。作为桑德兰的仆从，德米提恩徘徊在乱石之中，仿佛已被更广阔的暮光阶层所遗弃或脱离，独自沉思着元素束缚以及逐风者失落的力量。"}},faq={{q="暮光营地废墟是什么地方？",a="这是一座位于希利苏斯西北部水晶谷中残破的废墟前哨，因是德米提恩的私人居所而闻名。",al={"暮光营地废墟","希利苏斯暮光营地废墟","水晶谷营地"}},{q="谁住在这里？",a="这里唯一的著名居民是德米提恩，一个与元素传说及桑德兰王子的束缚紧密相连的孤独人物。",al={"暮光营地废墟里有谁","德米提恩位置","营地角色"}},{q="为什么营地会变成废墟？",a="教派记录提到了该地点的废墟状态，但德米提恩依然留在残骸之中，与在希利苏斯活动的其余暮光之锤成员隔绝。",al={"为什么它成了废墟","是什么摧毁了营地","谁袭击了营地"}},{q="这里的暮光之锤是敌对的吗？",a="与希利苏斯南部和中部的喧闹暮光营地不同，这里缺乏具有攻击性的教派巡逻队，让德米提恩得以在宁静中沉思。",al={"教徒会在这里发起攻击吗","德米提恩是敌对的吗"}}},fp="21,157,27.294.0,34.122.0,15.123.0,23.147.0,38.159.0"}
P.entries["subzone:raven-hill"] = {n="乌鸦岭",s="乌鸦岭是暮色森林西部一座荒凉废弃的村庄，坐落在广阔的乌鸦岭墓地的长影之中。这里曾经是一个热闹的人类定居点，如今却已被废弃，只剩下少数几个惊恐的非法定居者和看不见的幽灵。",h="乌鸦岭是暮色森林西部一座荒凉废弃的村庄，坐落在广阔的乌鸦岭墓地的长影之中。这里曾经是一个热闹的人类定居点，如今却已被废弃，只剩下少数几个惊恐的非法定居者和看不见的幽灵。",kw={"废弃的城镇","布里兹提克","墓地","暮色森林","基特斯","乌鸦岭","无影者"},ang={["faction:Alliance"]="对于从西部荒野过桥而来的联盟旅人来说，乌鸦岭是迎接他们进入吞噬暮色森林西部噩梦的阴森前奏。",["race:Human"]="这些腐朽的小屋提醒着人们，暴风城王国已经因为蔓延的黑暗和疏于管理而失去了多少领土。"},sec={{t="一座被黑暗吞噬的城镇",b="乌鸦岭位于暮色森林西部通道沿线，腐草农场正北，它已沦为昔日繁荣景象的悲惨空壳。当黑暗魔法和亡灵恐怖横扫大汉姆雷特地区时，生者们向东撤离至夜色镇，或是彻底逃离了这片领地。如今，破败的木屋在永恒的阴暗中腐烂，避开了旅人们的足迹，他们既惧怕从邻近墓地游荡而下的The Restless Dead，也恐惧潜伏在残垣断壁间的隐形者Unseen。"},{t="留下的少数人",b="尽管名声惨淡，乌鸦岭并非完全无人居住。一位名叫基特斯的冒险者精神崩溃，躲在废弃的建筑群中，对徘徊在树林里的恐怖生物感到恐惧。在其中一间破旧的阁楼高处，一个名叫布里兹提克的地精正通过向谨慎的过路人出售补给品，艰难地维持着独居生活。他们与被称为Unseen的隐形幽灵共享着这些废墟，在这片庞大墓地的边缘苟延残喘。"}},faq={{q="乌鸦岭为什么会被废弃？",a="当阴影笼罩暮色森林，带来亡灵恐怖、黑暗魔法和捕食野兽时，乌鸦岭被废弃了。由于该镇毗邻巨大的乌鸦岭墓地，使其极难防守，幸存的居民被迫向东逃往设防的定居点夜色镇。",al={"乌鸦岭发生了什么","为什么乌鸦岭变成了废墟","谁曾住在乌鸦岭"}},{q="现在还有谁住在村子里？",a="只有少数几个大胆或绝望的灵魂居住在这里。惊恐的人类基特斯躲在废墟地基中，饱受内疚和恐惧的折磨；而地精商人布里兹提克则在楼上经营生意，与任何有胆量搜寻这些废弃建筑的人进行交易。",al={"谁在乌鸦岭","乌鸦岭角色","乌鸦岭的活人"}},{q="在乌鸦岭出没的无形者是什么？",a="无形者是徘徊在乌鸦岭和附近墓地中的隐形敌对幽灵。虽然肉眼无法看见，但对于任何探索这片荒凉城镇的大意旅人来说，它们的存在构成了突如其来的致命威胁。",al={"乌鸦岭的无影者","乌鸦岭的隐形怪物","乌鸦岭的鬼魂"}},{q="通往乌鸦岭的道路通向哪里？",a="经过乌鸦岭的道路向西连接通往西部荒野的河桥，向南通往腐草农场和荆棘谷的边界，向东穿过暮色森林的中心地带直达夜色镇。",al={"乌鸦岭的道路","道路通向哪里","前往乌鸦岭"}}},fp="10,188,23.392.0,18.370.0,28.224.0,38.259.0,40.185.0,44.180.0"}
P.entries["subzone:raven-hill-cemetery"] = {n="乌鸦岭墓地",s="乌鸦岭墓地是一片广袤而受诅咒的墓园，横跨暮色森林的西部。这里曾是当地村落宁静的安息之地，如今却已被成群的行尸、食腐蜘蛛和冷酷的盗墓贼所占据。",h="乌鸦岭墓地是一片广袤而受诅咒的墓园，横跨暮色森林的西部。这里曾是当地村落宁静的安息之地，如今却已被成群的行尸、食腐蜘蛛和冷酷的盗墓贼所占据。",kw={"亚伯克隆比","暮色森林","荒弃鬼屋","盗墓贼","摩拉迪姆","摩本特·费尔","乌鸦岭墓地","骷髅"},ang={["class:Paladin"]="乌鸦岭墓地那无休止的腐化和被亵渎的坟墓，亟需圣光的净化。",["class:Priest"]="这座墓地隐藏着强大的暗影与残留悲伤的导管，作为一种凄凉的教训，警示着那些无法前往圣光的灵魂所遭受的悲剧。"},sec={{t="The Restless Dead之园",b="在黑暗吞噬黎明森林之前，乌鸦岭墓地是周边定居点主要的安息之所。随着黑暗魔法降临此地，死者无法继续安息于坟墓之中。骷髅、食尸鬼和蹒跚的恐怖生物从土壤中爬出，充斥着这座墓园阴森的边界。如今，它是暮色森林中最危险的灾祸之地之一。这里不仅有腐烂的憎恶和巨型蜘蛛徘徊，还有渴望洗劫祖先墓穴、且未受当地势力阻挠的绝望盗墓贼。"},{t="不安的灵魂与黑暗力量",b="乌鸦岭墓地的悲剧化身为摩拉迪姆，它是堕落骑士摩根·拉迪莫尔毫无理智的骷髅化身。他在疯狂与悲伤中结束了自己的生命，如今在墓碑间永无止境地徘徊。再往北，在荒弃鬼屋的高地上，黑暗通灵师摩本特·费尔利用坟墓中的邪恶能量来复活并奴役成群的亡灵。在更远处的东北边缘，坐落着隐士亚伯克隆比的偏僻小屋，他从迷雾边缘注视着这座墓园。"}},faq={{q="为什么乌鸦岭墓地里有这么多亡灵复生？",a="当暮色森林遭受凋零时，这座墓地陷入了黑暗的腐化，使得死灵法术的力量渗入了大地。潜伏在墓园边缘荒弃鬼屋的邪恶法师摩本特·费尔，正积极地扭曲这些能量，将尸体从坟墓中复活并加以控制。",al={"为什么这里有僵尸","为什么乌鸦岭闹鬼","是谁在乌鸦岭复活了死者"}},{q="摩拉迪姆是谁？",a="摩拉迪姆是一个致命的骷髅亡魂，他徘徊在墓园中并攻击旅人。他的身份和过去可以通过在夜色镇进行的调查得知。",al={"摩拉迪姆","在墓地徘徊的骷髅","摩根·拉迪莫尔"}},{q="摩本特·费尔在墓地里的什么位置？",a="摩本特·费尔居住在被称为荒弃鬼屋的小山上，位于乌鸦岭墓地的西北角。他住在一座俯瞰着墓碑的破旧房屋中，指挥着周围的亡灵。",al={"摩本特·费尔的位置","摩本特·费尔在哪里","荒弃鬼屋"}},{q="住在墓地边缘的隐士是谁？",a="这位隐士是亚伯克隆比，一个古怪而虚弱的老人，住在这座墓地东北边界附近的一间破烂小屋里。他经常请求路过的旅人为他收集奇怪的组件和材料，用于他那病态的个人研究。",al={"乌鸦岭的隐士","亚伯克隆比","乌鸦岭的小屋"}}},fp="19,187,29.453.0,32.420.1,53.196.0,17.142.1,45.172.0,53.220.0"}
P.entries["subzone:ravencrest-monument"] = {n="拉文凯斯雕像",s="拉文凯斯雕像耸立在艾萨拉南部的风蚀悬崖之上，是一座古老的暗夜精灵巨像破碎的残骸。这座雕像曾经是一座俯瞰无尽之海的高大纪念碑，如今早已破碎，只剩下高耸的双腿和散落的石块废墟，现在被敌对的毒皮纳迦所占据。",h="拉文凯斯雕像耸立在艾萨拉南部的风蚀悬崖之上，是一座古老的暗夜精灵巨像破碎的残骸。这座雕像曾经是一座俯瞰无尽之海的高大纪念碑，如今早已破碎，只剩下高耸的双腿和散落的石块废墟，现在被敌对的毒皮纳迦所占据。",kw={"艾萨拉","巨像","埃达拉斯","库塔洛斯·拉文凯斯","拉文凯斯","拉文凯斯雕像","毒皮","雕像"},ang={["class:Warrior"]="拉文凯斯这个名字在战斗指挥官中具有传奇般的份量，因为库塔洛斯·拉文凯斯是燃烧军团灾难性入侵期间凡人军队中最杰出的将军。",["race:NightElf"]="对于暗夜精灵来说，这座纪念碑是一个令人清醒的提醒，让人想起古老的卡多雷帝国和拉文凯斯的高贵血统，正是他们在上古之战中的英勇抵抗拯救了艾泽拉斯，使其免于被恶魔毁灭。"},sec={{t="巨像废墟",b="拉文凯斯雕像高耸于埃达拉斯废墟东南方的海洋之上，曾经是卡多雷石雕艺术的惊世杰作。今天，这座宏伟巨像剩下的只有那对深深扎根于石座之中的巨大断腿，而躯干和头部的残片则深埋在悬崖边的泥土中，或失落于下方的波涛之下。想要到达这处偏远的海岸岬角，需要穿过艾萨拉的陆地桥梁，因为陡峭的岩壁阻断了从海上接近的路线。"},{t="被遗忘的遗产",b="学者们常推测这座纪念碑是为了纪念库塔洛斯·拉文凯斯领主，这位著名的贵族在辛-艾萨里陷落后，于上古之战期间集结并领导了暗夜精灵军队。然而，由于它靠近大分裂之前的埃达拉斯城，且幸存的石雕风格暧昧不清，其真实的起源仍存在争议。如今，这里没有朝圣者或暗夜精灵看守，周边的悬崖已被蛇形的毒皮纳迦占据，它们以凶残的领地意识守护着这座倒塌的纪念碑。"}},faq={{q="拉文凯斯雕像是什么？",a="它是位于艾萨拉南部一处海岸岬角上的巨大暗夜精灵巨像的废墟基座。只有它巨大的石腿依然屹立不倒，而雕像的其他部分则破碎并散落在悬崖顶上。",al={"拉文凯斯雕像","这是什么雕像","艾萨拉的巨腿"}},{q="这座纪念碑是为了纪念谁而建的？",a="它带有拉文凯斯家族的名称，该家族因库塔洛斯·拉文凯斯领主而闻名，他是在上古之战期间领导凡人反抗燃烧军团的贵族指挥官。然而，由于它位于古老的埃达拉斯废墟附近，尚不清楚它是直接纪念库塔洛斯，还是纪念大分裂前的一位更早期的先祖。",al={"拉文凯斯是谁","这座雕像是谁的","库塔洛斯·拉文凯斯"}},{q="如何前往这座纪念碑？",a="由于悬崖峭壁林立，无法从海上攀爬或进入该纪念碑。旅行者必须通过陆路穿过艾萨拉南部，越过埃达拉斯废墟附近的石桥才能到达该岬角。",al={"如何前往拉文凯斯雕像","拉文凯斯路径","拉文凯斯入口"}},{q="如今有什么生物居住在纪念碑处？",a="悬崖顶部和周边的阶地被毒皮纳迦所占据，使得独行的旅行者探索这些古老废墟时险象环生。",al={"这里有什么生物","纪念碑的敌人","艾萨拉纳迦"}}},fp="19,172,19.420.0,18.431.0,32.187.0,36.296.0,30.158.0,42.113.0"}
P.entries["subzone:ravenholdt-manor"] = {n="拉文霍德庄园",s="拉文霍德庄园坐落在希尔斯布莱德丘陵上方的高山之中，是一座隐蔽的总部，也是被称为拉文霍德的盗贼与刺客公会的所在地。在乔拉齐·拉文霍德公爵的统领下，这处庄园为潜行大师们提供了一处远离世人与当局目光的隐秘避难所，让他们得以磨练自己的技艺。",h="拉文霍德庄园坐落在希尔斯布莱德丘陵上方的高山之中，是一座隐蔽的总部，也是被称为拉文霍德的盗贼与刺客公会的所在地。在乔拉齐·拉文霍德公爵的统领下，这处庄园为潜行大师们提供了一处远离世人与当局目光的隐秘避难所，让他们得以磨练...",kw={"奥特兰克","刺客","希尔斯布莱德","乔拉齐·拉文霍德","庄园","拉文霍德","潜行者公会","辛迪加","盗贼"},ang={["class:Rogue"]="拉文霍德庄园是贵职业的首选庇护所，提供严格的试炼、专业的训练以及深厚的地下联络网。",["profession:Engineering"]="眼光独到的工程师会特意穿过山口，从庄园的补给中获取稀有的侏儒隐形装置图纸。"},sec={{t="暗影中的庇护所",b="拉文霍德庄园隐藏在敦霍尔德城堡西北方的一条狭窄山口和蜿蜒洞穴之后，孤零零地矗立在奥特兰克山脉的边境地带。这处地产属于乔拉齐·拉文霍德公爵，他维持着一个纪律严明的盗贼、刺客和情报特工据点。庄园内设有一座宁静的花园和一处由像康恩大师这样的武术专家监督的露天训练场，为练习开锁、制作毒药和近身格斗提供了规范的场地。虽然庄园欢迎那些在诡计方面有天赋的人，但笨拙的外来者和不受欢迎的访客会受到庄园警卫冷漠的怀疑。"},{t="丘陵地带的苦涩恩怨",b="在第一次战争之前，庄园周围的土地曾是奥特兰克王国的一部分，庄园屋顶上风化的橙色瓦片便是明证。在奥特兰克沦陷后的动荡中，辛迪加的没落贵族试图控制该地区，这使他们与拉文霍德产生了直接冲突。对于乔拉齐的追随者来说，在希尔斯布莱德和奥特兰克发生的每一次冲突，都是为了维护他们这处主权避难所而进行的无声战争的一部分。"}},faq={{q="如何前往拉文霍德庄园？",a="若要前往庄园，请前往希尔斯布莱德丘陵中敦霍尔德城堡西北方的台地。在台地与北部山脉交界处附近，有一条不起眼的土路蜿蜒向上，穿过一个隐蔽的洞穴，最终直通庄园场地。",al={"拉文霍德庄园在哪里","如何去拉文霍德","拉文霍德路径"}},{q="谁拥有拉文霍德庄园？",a="这处庄园属于乔拉齐·拉文霍德公爵，他领导着一个被称为拉文霍德的精英盗贼与刺客兄弟会。他在艾泽拉斯的盗贼中享有崇高的威望。",al={"谁领导拉文霍德","拉文霍德公爵","庄园主"}},{q="拉文霍德为何憎恨辛迪加？",a="这两个派系都声称起源于支离破碎的奥特兰克。辛迪加的流亡贵族在丘陵各处诉诸强盗行径和无法无天之举，而拉文霍德则以严明的纪律运作，并积极致力于挫败辛迪加的野心。",al={"拉文霍德与辛迪加","辛迪加恩怨","为何对抗辛迪加"}},{q="任何人都可以参观庄园吗？",a="任何旅行者在物理上都可以走进庄园场地，但驻守在那里的警卫和刺客对局外人持有公开的敌意。潜行者和受信任的特工会受到热烈欢迎并获得深入的训练，而其他人则会收到令人不寒而栗的警告，要求他们离开。",al={"非潜行者在拉文霍德","局外人是否被允许进入拉文霍德"}}},fp="16,180,26.554.0,30.403.0,34.190.0,26.152.0,39.205.0,27.205.0"}
P.entries["subzone:raynewood-retreat"] = {n="林中树居",s="林中树居是一座古老的暗夜精灵哨站，坐落在灰谷中北部的一棵参天大树周围。它由树妖和塞纳里奥保护者守卫，作为一处警惕的圣所，监视着通往被腐蚀的费伍德森林的北部隘口。这里也是塞纳留斯之子、丛林守护者欧达努斯的避难所，他正受到邪恶外部势力的觊觎。",h="林中树居是一座古老的暗夜精灵哨站，坐落在灰谷中北部的一棵参天大树周围。它由树妖和塞纳里奥保护者守卫，作为一处警惕的圣所，监视着通往被腐蚀的费伍德森林的北部隘口。这里也是塞纳留斯之子、丛林守护者欧达努斯的避难所，他正受到邪...",kw={"灰谷","布莱林","塞纳留斯","费伍德森林","欢笑姐妹","欧达努斯","林中树居","避难所"},ang={["class:Druid"]="林中树居是塞纳留斯之子管辖下的神圣土地，是抵御恶魔和邪能腐蚀的堡垒。",["faction:Horde"]="对于部落来说，这个林中树居是一处亲近联盟的林地，其守护者丛林守护者欧达努斯是被秘密任务发布者列为清除目标的猎物。"},sec={{t="巨树堡垒",b="这座哨站坐落在莎尔蒂恩的月亮井和萨特出没的夜道谷废墟之间，由塞纳里奥保护者、精灵龙和欢笑姐妹严密守卫。她们共同保持着警惕，注视着从北面费伍德森林蔓延而来的腐蚀。"},{t="猎杀欧达努斯",b="在大树的枝头高处，居住着丛林守护者欧达努斯，他是塞纳留斯的长子之一。虽然树冠为他提供了庇护，但也成了黑暗阴谋的焦点。效忠于暗影议会残党的特工，特别是布莱林·火拳，企图谋害这位守护者。部落雇佣兵被派遣去强攻高处并取下他的首级，将这片本应宁静的林中圣所变成了战场。"}},faq={{q="林中树居是什么地方？",a="林中树居是一处位于灰谷中北部大树周围的暗夜精灵和塞纳里奥定居点。它作为一处支持联盟的圣所和瞭望哨，负责监控通往费伍德森林的入口。",al={"林中树居","这里是什么地方","林中树居大树"}},{q="谁居住在林中树居？",a="这座哨站由塞纳里奥保护者、被称为欢笑姐妹的树妖以及精灵龙防守。其最著名的居民是居住在大树高处的丛林守护者欧达努斯。",al={"这里有什么人","林中树居的怪物","谁在守卫林中树居"}},{q="丛林守护者欧达努斯是谁？",a="丛林守护者欧达努斯是一位强大的丛林守护者，也是半神塞纳留斯的长子之一。他负责管理这座圣所，但却发现自己正被敌对的渗透者猎杀。",al={"丛林守护者欧达努斯","欧达努斯是谁","欧达努斯背景故事"}},{q="为什么部落会攻击林中树居？",a="布莱林·火拳雇佣部落冒险者渗透进大树并寻找丛林守护者欧达努斯。她的动机和效忠对象会在任务中被揭露。",al={"部落的林中树居任务","为什么要杀欧达努斯","布莱林·火拳任务"}}},fp="17,166,25.240.0,20.341.1,26.199.0,31.128.0,22.101.0,44.151.0"}
P.entries["subzone:razor-hill"] = {n="剃刀岭",s="剃刀岭是杜隆塔尔中部主要的部落定居点，坐落于连接试炼谷、贫瘠之地和奥格瑞玛的战略十字路口。它以一座显眼的坚固兵营为中心，是年轻的兽人和巨魔战士在严酷荒野中磨练意志的集结地和训练中心。",h="剃刀岭是杜隆塔尔中部主要的部落定居点，坐落于连接试炼谷、贫瘠之地和奥格瑞玛的战略十字路口。它以一座显眼的坚固兵营为中心，是年轻的兽人和巨魔战士在严酷荒野中磨练意志的集结地和训练中心。",kw={"兵营","火刃氏族","杜隆塔尔","加索克","库尔提拉斯","奥戈尼尔·魂痕","剃刀岭"},ang={["faction:Horde"]="作为离开训练场后遇到的第一个真正的城镇，剃刀岭是年轻的部落士兵证明他们对萨尔新国度忠诚的出发点。",["race:Orc"]="剃刀岭见证了兽人在杜隆塔尔开创的新生活，他们用恶魔的奴役换取了坚固的地洞和来之不易的生存。"},sec={{t="杜隆塔尔之心",b="剃刀岭建于重要的地理交汇处，连接着杜隆塔尔北部、南部的沿海定居点，以及怒水河对岸广阔的贫瘠之地平原。这座定居点在杜隆塔尔建立之初便已设立，其标志是石木结构的兵营和经典的兽人地洞。第三次大战后不久，来自库尔提拉斯的人类军队曾假借外交峰会的名义，在此引诱部落进入伏击圈；雷克萨代替萨尔赴会，挫败了这次袭击。如今，这座前哨站已严加设防，以应对后续的沿海入侵。"},{t="边境哨所",b="在加索克等资深军官的指挥下，剃刀岭负责协调针对多重威胁的当地防御。人类海军残部依然盘踞在东海岸的提拉加德城堡，而好战的野猪人和鹰身人部落则不断骚扰当地的补给线。更为阴险的是火刃氏族邪教的存在，他们在附近的岩架上进行黑暗仪式，其腐化的代理人正受到奥戈尼尔·魂痕等调查员的严密追踪和清剿。"}},faq={{q="剃刀岭在杜隆塔尔有什么作用？",a="剃刀岭是杜隆塔尔中部主要的行政和防御前哨站。它连接着南部的海岸和试炼谷，通往北方的奥格瑞玛和西方的贫瘠之地，同时也为年轻的冒险者提供补给和训练。",al={"剃刀岭为何建于此","剃刀岭的作用","剃刀岭简介"}},{q="库尔提拉斯入侵期间这里发生了什么？",a="第三次大战后，效忠于库尔提拉斯的军队提议在剃刀岭与大酋长萨尔举行和平峰会。勇士雷克萨怀疑其中有诈，便代替萨尔前往，揭穿了伏击并击败了人类刺客。",al={"库尔提拉斯伏击","雷克萨剃刀岭","剃刀岭峰会发生了什么"}},{q="谁在指挥这个定居点？",a="该定居点的驻军由兽人老兵加索克在镇内的兵营中指挥，负责监督针对人类残部和当地野生猛兽的巡逻。",al={"剃刀岭指挥官","谁管理剃刀岭","加索克"}},{q="火刃氏族在剃刀岭附近做什么？",a="这个阴暗的恶魔邪教已经渗透到了杜隆塔尔中部周围隐藏的岩架和峡谷中。在奥戈尼尔·魂痕的指挥下，部落侦察兵以剃刀岭为据点，搜寻他们的集会点并消除其影响。",al={"火刃氏族杜隆塔尔","奥戈尼尔·魂痕","剃刀岭附近的邪教徒"}}},fp="10,185,16.440.0,21.370.0,40.220.0,49.207.0,28.145.0,48.212.0"}
P.entries["subzone:razor-hill-watchtower"] = {n="Razor Hill Watchtower",s="这座坚固的哨所矗立在俯瞰剃刀岭的红色石崖上，是杜隆塔尔中心地带的早期预警点。弗恩·凝眉时刻警惕地注视着尘土飞扬的平原和海岸线，保护着下方的定居点免受威胁的侵扰。",h="这座坚固的哨所矗立在俯瞰剃刀岭的红色石崖上，是杜隆塔尔中心地带的早期预警点。弗恩·凝眉时刻警惕地注视着尘土飞扬的平原和海岸线，保护着下方的定居点免受威胁的侵扰。",kw={"杜隆塔尔","瞭望","剃刀岭","剃刀岭哨塔","哨兵","哨塔"},ang={["class:Hunter"]="这个高处的制高点可以毫无阻挡地观察周围的岩壁，是观察员追踪猎物和监控杜隆塔尔各地野兽动向的理想位置。",["faction:Horde"]="对于从试炼谷走出的年轻战士和侦察兵来说，这座哨塔是一个令人安心的地标，象征着初生的部落的安全与力量。"},sec={{t="杜隆塔尔之眼",b="剃刀岭哨塔由厚实的木材和铁架建成，守卫着剃刀岭定居点及周边的峡谷。杜隆塔尔面临着来自东海岸库尔提拉斯海军陆战队、在灌木丛中潜行的野猪人袭击者，以及潜伏在附近岩壁中的火刃氏族邪教徒的无尽威胁。从山脊上这个高耸的制高点，哨兵可以在敌军到达定居点大门之前，很远就能发现逼近的战团、烟雾信号和入侵者。"}},faq={{q="剃刀岭哨塔的用途是什么？",a="这座哨塔是剃刀岭和杜隆塔尔中心地带的主要监视点。凭借其高海拔，侦察兵可以监控路径、观察野兽，并探测来自附近联盟营地或半人马袭击队的任何部队调动。",al={"为什么要有这个哨塔","哨塔用途","剃刀岭塔"}},{q="谁在守护这座哨塔？",a="上了年纪的兽人弗恩·凝眉在这里守望着入侵者，并在必要时吹响信号号角。随着杜隆塔尔逐渐安定下来，他开始为年轻的冒险者制作背包。",al={"谁在塔里","哨塔守卫"}},{q="在这里能看到什么威胁？",a="侦察兵主要留意来自剃刀鬃毛部族的暴躁野猪人、沿着东海岸从提拉加德城堡潜入的人类，以及在干旱峡谷中游荡的野兽。",al={"剃刀岭的威胁","他们在寻找什么"}}},fp="21,162,17.387.0,49.216.0,26.181.0,38.161.0"}
P.entries["subzone:razorfen-downs"] = {n="剃刀高地",s="剃刀高地是野猪人的祖先之都和神圣的埋骨迷宫，深深地嵌入在南贫瘠之地与千针石林交界处那巨大的荆棘丛中。这里曾是他们最神圣的避难所，如今却已落入亡灵天灾军团的魔掌，变成了一个散发着恶臭的死灵法术堡垒。",h="剃刀高地是野猪人的祖先之都和神圣的埋骨迷宫，深深地嵌入在南贫瘠之地与千针石林交界处那巨大的荆棘丛中。这里曾是他们最神圣的避难所，如今却已落入亡灵天灾军团的魔掌，变成了一个散发着恶臭的死灵法术堡垒。",kw={"阿迦玛甘","阿迦玛娜","寒冰之王","死灵法师黑棘","死亡之头","高地","野猪人","剃刀高地","天灾军团"},ang={["faction:Horde"]="野猪人一直是十字路口的心头大患，但一个盘踞在贫瘠之地边缘、直接效忠于巫妖王的据点，则是部落绝对无法忽视的生存威胁。",["race:Undead"]="对于被遗忘者来说，发现一个天灾军团的巫妖在卡利姆多秘密行动，这不禁让人回想起他们曾誓死反抗的那个主人，必须立即采取果断行动将其彻底铲除。"},sec={{t="一座被腐蚀的神圣城市",b="剃刀高地长期以来被视为野猪人种族的祖先之都和埋骨之地，坐落在从陨落的半神阿迦玛甘身上长出的巨大石化荆棘丛中。传说其拱形的入口正是直接从这位巨猪的嘴里开凿出来的。几个世纪以来，死亡之头氏族的高阶祭司们一直守护着这些深邃蜿蜒的洞穴，并祭奠他们受人敬仰的死者。然而，尽管这里在野猪人心中地位神圣，但这片骨头与荆棘组成的迷宫最近却遭遇了一场远比贫瘠之地的水源争夺更为黑暗的灾难。"},{t="天灾军团蔓延至卡利姆多",b="第三次战争的浩劫过后，亡灵天灾军团的触角悄然伸向了卡利姆多南部。在寒冰巫妖阿迦玛娜的率领下，死亡的爪牙渗透进这片荆棘迷宫，并策反了死亡之头氏族的祭司。野猪人们不再祭奠祖先，而是转而在他们神圣的栖息地中窝藏腐烂的食尸鬼、骷髅和死灵法师。此地的腐化正威胁着向外扩散至整个贫瘠之地，将野猪人最神圣的土地变成天灾军团在西方扩张野心的跳板。"}},faq={{q="什么是剃刀高地？",a="剃刀高地是野猪人种族的祖先之都和埋骨之地。它由陨落的远古之灵阿迦玛甘所形成的巨大荆棘丛生长而成，是野猪人文化的精神核心，也是他们的高阶祭司——死亡之头氏族的总部。",al={"什么是剃刀高地","剃刀高地背景故事","谁居住在剃刀高地"}},{q="为什么天灾军团会盘踞在剃刀高地？",a="巫妖阿迦玛娜在第三次战争后抵达此地，旨在为巫妖王建立一个卡利姆多的据点。通过腐化死亡之头氏族的祭司并复活野猪人的尸体，阿迦玛娜将这座迷宫般的荆棘之城变成了一个隐藏的死灵力量巢穴。",al={"为什么剃刀高地有亡灵","阿迦玛娜剃刀高地","剃刀高地的天灾军团"}},{q="剃刀高地与剃刀沼泽有何不同？",a="剃刀沼泽是野猪人的主要军事堡垒和聚居地，由妖婆卡尔加·刺肋直接统治。相比之下，剃刀高地则是他们传统的首都和神圣埋骨地，位于更南边，现已沦陷在死灵法术和天灾军团的控制之下。",al={"剃刀沼泽和剃刀高地的区别","剃刀高地与剃刀沼泽","剃刀沼泽还是剃刀高地"}},{q="入口在哪里？",a="剃刀高地坐落在贫瘠之地的最南端，俯瞰着通往千针石林的巨大断崖。其入口是一个嵌入高耸纠结荆棘丛中的天然拱形裂隙，神话传说称其是由阿迦玛甘张开的大嘴雕琢而成。",al={"剃刀高地入口","剃刀高地在哪里","如何进入剃刀高地"}}},fx={e1cd26cb={q="剃刀高地发生过什么？",a="剃刀高地曾是野猪人的骄傲都城和祖先墓地，由巨大的荆棘藤蔓构成。据说这些藤蔓是从半神阿迦玛甘的鲜血中生长出来的。然而，第三次战争后，城中降临了灾祸。天灾军团的爪牙潜入荆棘迷宫，散播致命瘟疫。在寒冰之王阿姆纳尔的带领下，亡灵奴役了许多亡首部族成员，将这片神圣故土变成了滋生亡灵的据点。",al={"剃刀高地历史","剃刀高地发生了什么","剃刀高地的历史传说"}},ac7f90f4={q="谁统治着剃刀高地？",a="这座要塞已落入阿姆纳尔·寒冰之王的铁腕统治之下。他是强大的天灾巫妖，被派往卡利姆多南部建立据点。在他麾下效力的是亡首部族的野猪人，他们腐化的高阶祭司已转而钻研通灵术；此外还有成群的无脑食尸鬼、骷髅和其他可怖亡灵。",al={"谁统治剃刀高地","谁领导剃刀高地","剃刀高地首领"}},["42eaec66"]={q="剃刀高地危险吗？",a="这里极其危险。与剃刀沼泽的野蛮部族不同，这里的守卫得到了天灾军团的冰冷魔法加持。染疫的野猪人、通灵师和成群复活的亡者在错综复杂的隧道中游荡。深处盘踞着阿姆纳尔·寒冰之王，他的存在威胁着要将亡灵瘟疫扩散至整个贫瘠之地和千针石林。",al={"剃刀高地有多危险","剃刀高地的威胁","剃刀高地安全吗"}}},fp="14,182,23.427.0,28.459.1,23.270.0,41.235.0,51.259.0,30.235.0"}
P.entries["subzone:razorfen-downs-classic"] = {n="Razorfen Downs (Classic)",s="剃刀高地是野猪人的祖先埋骨地和传统都城，坐落在南贫瘠之地巨大的荆棘丛深处。最近，由巫妖寒冰之王亚门纳尔领导的天灾军团特工夺取了这座迷宫的控制权，复活了死去的野猪人，并威胁要将其统治范围扩张到整个卡利姆多中部。",h="剃刀高地是野猪人的祖先埋骨地和传统都城，坐落在南贫瘠之地巨大的荆棘丛深处。最近，由巫妖寒冰之王亚门纳尔领导的天灾军团特工夺取了这座迷宫的控制权，复活了死去的野猪人，并威胁要将其统治范围扩张到整个卡利姆多中部。",kw={"阿迦玛甘","亚门纳尔","贫瘠之地","死亡之颅","野猪人","剃刀高地","天灾军团"},ang={["faction:Horde"]="在贫瘠之地南侧边境线上出现的这座天灾要塞，对部落的腹地和补给线构成了迫在眉睫的威胁。",["race:Undead"]="幽暗城的皇家药剂师学会和被遗忘者领导层非常渴望调查并清除这股在高地中滋生的敌对亡灵魔法。"},sec={{t="荆棘之都",b="剃刀高地和附近的剃刀沼泽一样，都是由高耸的石化藤蔓生长而成，这里是上古野猪半神阿迦玛甘在上古之战中倒下的地方。世世代代以来，这座荆棘迷宫一直是野猪人的神圣墓地和权力中心，由死亡之颅部族的秘法师严密守护。对野猪人而言，这些茂密的荆棘是神圣之地，浸透了他们神圣先祖的鲜血。"},{t="卡利姆多的天灾据点",b="随着天灾军团的特工渗入荆棘丛，高地的神圣性被打破了。寒冰之王亚门纳尔，一位侍奉巫妖王的强大巫妖，奴役了当地的死亡之颅部族野猪人，并将这座祖先的安息之地变成了天灾军团的要塞。复活的骷髅、蹒跚的尸体和尖叫的女妖现在徘徊在荆棘之环中。附近的贫瘠之地部落和暴风城光明大教堂的使者都认为，这个不断扩大的天灾势力据点对整个大陆构成了严重的威胁。"}},faq={{q="什么是剃刀高地？",a="剃刀高地是野猪人的祖先都城和墓地，开凿在南贫瘠之地的巨大荆棘丛中。它最近落入了天灾军团的控制之下。",al={"什么是剃刀高地","剃刀高地背景故事","高地背景"}},{q="为什么野猪人的城市里会有亡灵？",a="一位名为寒冰之王亚门纳尔的天灾巫妖入侵了高地，奴役了当地的死亡之颅部族，并复活了死去的野猪人，以此在卡利姆多建立了一个亡灵滩头阵地。",al={"为什么天灾军团会在高地","为什么贫瘠之地会有亡灵","谁把天灾军团带到了这里"}},{q="剃刀高地和剃刀沼泽有什么区别？",a="这两座地下城都是从阿迦玛甘的荆棘中开凿出来的，但剃刀沼泽是由卡尔加·刺肋领导的野猪人居住要塞。而剃刀高地是他们的祖先埋骨地，目前被天灾军团所占领。",al={"高地对比沼泽","剃刀沼泽对比剃刀高地","高地和沼泽的区别"}},{q="谁目前统治着剃刀高地？",a="天灾军团的巫妖，寒冰之王亚门纳尔，在荆棘之环深处指挥着这座要塞。",al={"剃刀高地最终首领","谁领导着剃刀高地","高地的首领"}}},fp="24,250,17.399.0,29.455.0,23.150.0,44.170.0,65.193.0,35.104.0"}
P.entries["subzone:razorfen-kraul-classic"] = {n="Razorfen Kraul (Classic)",s="剃刀沼泽是野猪人的祖居心脏地带，深入挖掘在野猪半神阿迦玛甘倒下后，其鲜血所化出的巨型荆棘丛中。这座防御森严的迷宫由冷酷的巫婆卡尔加·刺肋统治，是他们向南贫瘠之地发起血腥劫掠的集结地。",h="剃刀沼泽是野猪人的祖居心脏地带，深入挖掘在野猪半神阿迦玛甘倒下后，其鲜血所化出的巨型荆棘丛中。这座防御森严的迷宫由冷酷的巫婆卡尔加·刺肋统治，是他们向南贫瘠之地发起血腥劫掠的集结地。",kw={"阿迦玛甘","阿迦瑟洛斯","贫瘠之地","卡尔加·刺肋","野猪人","拉姆塔斯","剃刀沼泽","天灾军团"},ang={["faction:Horde"]="卡尔加·刺肋的侵略性劫掠直接威胁着南部的定居点和贸易路线，使得平定剃刀沼泽成为部落刻不容缓的安全要务。",["race:Tauren"]="牛头人猎人和萨满与野猪人有着深厚的历史宿怨，而有关邪恶的天灾腐蚀正在阿迦玛甘的神圣土地上扎根的传言，要求他们立即采取行动进行干预。"},sec={{t="野猪之神的鲜血",b="一万年前的上古之战期间，巨型野猪半神阿迦玛甘在对抗燃烧军团以拯救艾泽拉斯时不幸殒命。每当他那神圣的鲜血渗入卡利姆多南部的土地，巨大的、无法穿透的荆棘藤蔓就会从地底迸发而出。野猪人自认为是这位伟大的野猪之神的凡间后裔，他们聚集在这些茂密的荆棘丛中居住，并祭祀他的牺牲。被称为剃刀沼泽的这片密集丛林是他们最受尊崇的堡垒，里面布满了野猪人战士、野兽训练师和塑地萨满。"},{t="巫婆的野心",b="剃刀沼泽的控制权落在了年迈的地卜师卡尔加·刺肋手中。在她的铁腕统治下，剃刀野猪人部落对敌对的野猪人部族以及附近的部落营地发动了残酷的战争。然而，比单纯的领土劫掠更令人不寒而栗的是，警惕的斥候报告称，有人发现亡灵身影在荆棘丛周围徘徊。有传言称，卡尔加已经开始与天灾军团的代理人进行交易，这不仅危及了贫瘠之地，还可能为亡灵在卡利姆多打开一个险恶的立足点。"}},faq={{q="是什么造就了剃刀沼泽周围的巨型荆棘？",a="根据传说，一万年前的上古之战中，野猪半神阿迦玛甘的鲜血洒落在哪里，巨大的荆棘藤蔓就会在哪里萌发。",al={"这里为什么有荆棘","贫瘠之地巨型荆棘藤蔓","阿迦玛甘荆棘背景故事"}},{q="谁统治着剃刀沼泽？",a="剃刀沼泽由卡尔加·刺肋指挥，她是一位冷酷的野猪人巫婆兼地卜师，指挥着针对邻近部落和定居点的袭击。",al={"剃刀沼泽首领","谁领导剃刀沼泽","卡尔加·刺肋"}},{q="为什么沼泽附近有亡灵？",a="据报道，卡尔加·刺肋已经与天灾军团的代理人进行了秘密谈判，寻求结成邪恶的联盟，这可能会将亡灵的力量引入野猪人的部族中。",al={"剃刀沼泽的天灾军团","亡灵野猪人","为什么天灾军团在贫瘠之地"}},{q="剃刀沼泽位于哪里？",a="剃刀沼泽位于贫瘠之地的最南端，坐落在升降梯以北、巨型荆棘丛的西侧。",al={"剃刀沼泽在哪里","剃刀沼泽入口","剃刀沼泽位置"}}},fx={["6f44c4ee"]={q="什么是剃刀沼泽？",a="剃刀沼泽是野猪人的祖传家园和戒备森严的要塞，深藏在南贫瘠之地巨大的荆棘丛中。野猪人被认为是堕落的野猪半神阿迦玛甘在人世间的后裔，他们将茂密的荆棘视为圣地和理应属于自己的领地。",al={"什么是剃刀沼泽","剃刀沼泽传说","关于剃刀沼泽"}},["8546d87b"]={q="剃刀沼泽发生过什么？",a="一万年前的上古之战期间，野猪半神阿迦玛甘在与燃烧军团的战斗中陨落。他洒下的鲜血使大片遍布荆棘的灌木丛破土而出。野猪人将中央的荆棘丛据为祖传家园，但老巫婆卡尔加·刺肋最近夺取了剃刀沼泽的统治权，驱使守卫攻击敌对部族和附近的聚居地。",al={"剃刀沼泽的历史","剃刀沼泽历史","剃刀沼泽发生了什么"}},["2a3e9319"]={q="剃刀沼泽危险吗？",a="危险。除了凶悍的野猪人战士、驯服的野兽和地卜师会竭力守护他们的神圣荆棘丛外，在卡尔加·刺肋的命令下，剃刀沼泽也变得极具敌意。更令人担忧的是，有传闻称天灾军团的爪牙正在其中出没，这让人们担心邪恶势力正在卡利姆多扎根。",al={"剃刀沼泽安全吗","剃刀沼泽的危险","剃刀沼泽的威胁"}}},fp="24,186,21.493.0,20.407.1,52.145.0,25.144.0,36.142.1,32.125.0"}
P.entries["subzone:razormane-grounds"] = {n="钢鬃营地",s="钢鬃营地是钢鬃野猪人从贫瘠之地向东推进至杜隆塔尔中部的前进营地。这里长满了尖锐的荆棘，随处可见野生动物的骸骨，这座令人毛骨悚然的前哨站成为了野猪人与奥格瑞玛兽人之间无休止冲突的最前线。",h="钢鬃营地是钢鬃野猪人从贫瘠之地向东推进至杜隆塔尔中部的前进营地。这里长满了尖锐的荆棘，随处可见野生动物的骸骨，这座令人毛骨悚然的前哨站成为了野猪人与奥格瑞玛兽人之间无休止冲突的最前线。",kw={"平牙队长","杜隆塔尔","地卜师摩特尔","野猪人","拉格拉恩","钢鬃","钢鬃营地"},ang={["faction:Horde"]="压制钢鬃营地对于保障贫瘠之地与部落主城奥格瑞玛之间的交通和补给线至关重要。",["race:Orc"]="对于杜隆塔尔的兽人来说，钢鬃营地是威胁他们新家园心脏地带的顽疾，年轻的勇士们必须通过屠杀这些野猪人来证明自己的实力。"},sec={{t="杜隆塔尔的眼中钉",b="钢鬃营地坐落在杜隆塔尔中部的红岩悬崖之下，标志着野猪人从贫瘠之地向外扩张的最东端。这里荆棘丛生，到处散落着白骨，对往来怒水河的旅人构成了持续的威胁。营地由战斗卫士平牙队长和地卜师摩特尔等首领领导，他们策划对邻近的兽人定居点和过往的补给线发动袭击。尽管剃刀岭及附近的哨所经常派出巡逻队，但钢鬃部族补充兵力的速度极快，他们从荆棘丛中涌出的速度甚至超过了部落的清理速度。"}},faq={{q="钢鬃营地是什么？",a="它是位于杜隆塔尔中部的一个野猪人防御营地，是钢鬃部族从贫瘠之地向东扩张的前进基地。",al={"钢鬃营地","野猪人营地 杜隆塔尔","钢鬃在哪"}},{q="为什么野猪人要袭击杜隆塔尔？",a="钢鬃野猪人认为所有邻近的领土都理应属于他们，他们试图通过牺牲部落的新定居点来扩大自己的荆棘丛和狩猎场。",al={"野猪人为何攻击","钢鬃为何在此","野猪人入侵"}},{q="谁在领导钢鬃营地的野猪人？",a="营地由钢鬃战斗卫士的首领平牙队长，以及擅长塑地之术的地卜师摩特尔共同指挥。",al={"钢鬃首领","钢鬃营地指挥官","平牙队长"}},{q="为什么营地周围有这么多骨头？",a="钢鬃部族是极具攻击性的拾荒者和猎手，他们将当地野生动物的肉剔食殆尽来供养劫掠者，并将残骸留在原地以标记领地。",al={"营地白骨","钢鬃动物尸骸","死去的动物为何"}}},fp="17,150,25.438.0,30.115.0,39.145.0,48.103.0,44.177.0"}
P.entries["subzone:razorwind-canyon"] = {n="烈风峡谷",s="烈风峡谷是一条蜿蜒曲折的岩石深沟，横跨在剃刀岭与奥格瑞玛之间的主干道上。这里盘踞着极具攻击性的尘风鹰身人，对前往部落首府的旅人构成了持续的威胁。",h="烈风峡谷是一条蜿蜒曲折的岩石深沟，横跨在剃刀岭与奥格瑞玛之间的主干道上。这里盘踞着极具攻击性的尘风鹰身人，对前往部落首府的旅人构成了持续的威胁。",kw={"枯水谷","杜隆塔尔","尘风鹰身人","剃刀岭","烈风峡谷","托克雷农场"},ang={["faction:Horde"]="将尘风鹰身人从烈风峡谷中清理出去，对于确保剃刀岭与奥格瑞玛首府之间的主干道对信使和新兵的安全至关重要。",["race:Orc"]="盘踞在杜隆塔尔中央大道旁的鹰身人是对兽人家园安全的蔑视，必须派遣年轻的勇士去削减它们的数量。"},sec={{t="高路上的威胁",b="烈风峡谷毗邻连接剃刀岭与奥格瑞玛的交通大动脉，向东侧的峭壁和西侧通往托克雷农场的灌木丛延伸出数条路径。峡谷是尘风鹰身人的巢穴，这些领地意识极强的生物会毫不犹豫地袭击任何靠近其栖息地的旅人。由于它们盘踞在首府贸易路线附近，清理这些峡谷成为了杜隆塔尔守军的一项长期必要任务。"},{t="通道与沟壑",b="烈风峡谷不仅是鹰身人的巢穴，其错综复杂的路径也构成了穿过杜隆塔尔红岩丘陵的隐秘通道。东侧的分支深深地钻入岩壁，通过一个洞穴与枯水谷相连。由于鹰身人栖息在高处并成群俯冲攻击，大意的冒险者在穿越这些隘口时很容易陷入包围并遭到屠戮。"}},faq={{q="烈风峡谷位于何处？",a="烈风峡谷位于杜隆塔尔中部，横跨在剃刀岭与奥格瑞玛之间主干道的两侧。入口分布在剃刀岭北侧、托克雷农场附近，以及通过一个洞穴连接至枯水谷。",al={"烈风峡谷位置","烈风峡谷在哪里","如何找到烈风峡谷"}},{q="什么生物栖息在烈风峡谷？",a="峡谷中盘踞着大量的尘风鹰身人。这些极具攻击性的类鸟生物在峡谷和岩石突起处筑巢，并以毫无防备的旅人为食。",al={"烈风峡谷怪物","烈风峡谷生活着什么","杜隆塔尔鹰身人峡谷"}},{q="为什么部落对这条峡谷感到担忧？",a="烈风峡谷紧邻连接剃刀岭与奥格瑞玛的主要贸易和旅行路线。筑巢的鹰身人经常骚扰经过中央大道的信使、补给商队和旅人。",al={"为什么关注烈风峡谷","奥格瑞玛烈风峡谷威胁"}},{q="烈风峡谷是否与其他地区相连？",a="是的。除了通向主干道外，峡谷还提供向西前往托克雷农场的小径，以及一条通往枯水谷的东侧洞穴通道。",al={"峡谷连接处","烈风峡谷通向哪里"}}},fp="16,195,25.318.0,20.283.0,34.210.0,40.120.0,45.212.0,45.134.0"}
P.entries["subzone:rebel-camp"] = {n="反抗军营地",s="反抗军营地坐落在荆棘谷北部路边，是那些脱离库尔森上校指挥的联盟士兵的坚固避难所。在多伦上尉的领导下，这些士兵拒绝向控制其指挥官远征队的疯狂屈服，如今他们为生存而战，并致力于终结库尔森的暴政。",h="反抗军营地坐落在荆棘谷北部路边，是那些脱离库尔森上校指挥的联盟士兵的坚固避难所。在多伦上尉的领导下，这些士兵拒绝向控制其指挥官远征队的疯狂屈服，如今他们为生存而战，并致力于终结库尔森的暴政。",kw={"库尔森上校","多伦","库尔森","库尔森的营地","麦佐斯","反抗军营地","荆棘谷"},ang={["faction:Alliance"]="当你从暮色森林过桥向南进入荆棘谷时，反抗军营地是你主要的集结地和最安全的避风港。",["race:Human"]="眼看着昔日的暴风城正规军在丛林中分崩离析令人感到清醒，多伦上尉急需王国的同胞帮助，以终结库尔森这支蒙羞的部队。"},sec={{t="对抗疯狂",b="当库尔森上校代表暴风城深入荆棘谷丛林时，局势迅速恶化。受到黑暗丛林魔法和食人魔巫师麦佐斯诅咒的影响，上校及其核心亲信陷入疯狂，变得残暴并开始蹂躏这片荒野。在多伦上尉的带领下，一小群神志清醒的士兵拒绝参与暴行。他们脱离了库尔森的营地，在北部建立了这个隐秘营地，对昔日的战友展开了绝望的游击战。"},{t="坚守阵线",b="反抗军营地危险地坐落在暮色森林边界附近，时刻面临着威胁。由于切断了来自暴风城的常规补给，多伦依靠秘密补给和防御武器——包括通过藏宝海湾运作的地精爆炸物——来守住防线，抵御库尔森突袭小队的进攻。对于向南冒险进入这片蛮荒丛林的联盟旅行者来说，这座营地是他们维持理智的重要落脚点。"}},faq={{q="反抗军营地的反抗军是谁？",a="他们是前暴风城士兵，曾是库尔森上校深入荆棘谷远征队的一员。当库尔森及其核心圈子陷入疯狂和暴政时，多伦上尉率领这部分人发动兵变，逃离并开始对抗他们。",al={"反抗军营地的居住者","这些士兵是谁","反抗军营地与联盟"}},{q="如果他们忠于暴风城，为什么还要叫它“反抗军营地”？",a="他们只是库尔森上校指挥体系下的“反抗军”。库尔森曾是他们的指挥官，因此违抗他的命令从技术上讲属于兵变，尽管他们仍然忠于联盟和暴风城。",al={"为什么叫反抗军营地","他们是叛徒吗","他们反抗谁"}},{q="该营地如何在没有暴风城官方支持的情况下生存？",a="由于远离官方补给线，多伦上尉依靠机智的非官方渠道，包括与远在藏宝海湾的克拉兹克等人进行交易，由他提供地雷和重要装备来加强营地的防御。",al={"反抗军营地的补给","他们的食物来源","反抗军营地的后勤"}},{q="库尔森上校在哪里？",a="库尔森及其疯癫的追随者占据着库尔森的营地，这是一座位于反抗军营地东南方向的坚固基地。",al={"库尔森的位置","库尔森在哪里","库尔森的营地"}}},fp="10,193,23.510.0,16.405.0,37.252.0,63.185.0,61.180.0,32.114.0"}
P.entries["subzone:red-rocks"] = {n="赤色石",s="赤色石是位于莫高雷东北部的一座高耸砂岩峭壁，是牛头人神圣的祖先墓地。这里安葬着最英勇的逝去勇士，年轻的勇士们也会前往那宁静的高处，寻求先辈的智慧。",h="赤色石是位于莫高雷东北部的一座高耸砂岩峭壁，是牛头人神圣的祖先墓地。这里安葬着最英勇的逝去勇士，年轻的勇士们也会前往那宁静的高处，寻求先辈的智慧。",kw={"刺鬃","墓地","大地母亲","莫高雷","野猪人","赤色石","智慧试炼","雷霆崖"},ang={["class:Shaman"]="风中承载着因野猪人的亵渎而不得安宁的灵魂的悲伤，呼唤着萨满仪式来恢复元素平衡和祖先的安宁。",["race:Tauren"]="对于你们的人民来说，赤色石是神圣的土地。肮脏的野猪人在你们受人尊敬的祖先墓地上挖掘，这是必须予以净化的公开暴行。"},sec={{t="神圣之石与祖先之墓",b="赤色石深红色的岩层高高耸立在莫高雷东北部的平原之上，标志着生者世界与死后世界之间神圣的界限。牛头人的传统将这片庄严的土地保留给他们最英勇的英雄——那些在建立和保卫雷霆崖的过程中献出生命的酋长、守卫者和勇士。他们荣耀地安息于此，与先辈的坟墓为伴。这里同样也是精神启程之地，年轻的牛头人会通过祭拜祖先墓地和与风沟通来完成他们的成年礼。"},{t="野猪人的亵渎",b="赤色石持久的宁静已被刺鬃野猪人打破。这些极具侵略性的食腐动物从巢穴中爬出，侵占了砂岩峭壁，并用污秽亵渎了祖先的坟墓。这种暴行深深冒犯了雷霆崖的精神传统。萨满祭司和博学者们现在正号召各方援助以净化这些岩架，驱逐刺鬃野猪人，并收复他们先人安息之地的神圣性。"}},faq={{q="赤色石的用途是什么？",a="赤色石是莫高雷牛头人最重要的祖先墓地和仪式祭坛。只有最英勇的逝去英雄才能安葬于此，年轻的牛头人也会在成年礼期间造访其高处，以此向逝者致敬。",al={"为什么赤色石很重要","赤色石的目的","赤色石发生了什么"}},{q="为什么赤色石会有野猪人？",a="刺鬃野猪人从他们的荆棘巢穴中涌出， 占领 了高原，玷污了墓冢。牛头人认为他们的入侵是对祖先安息之灵的亵渎，是不可容忍的罪行。",al={"赤色石的野猪人","谁在入侵赤色石","为什么刺鬃野猪人在这里"}},{q="谁被安葬在赤色石？",a="安葬在赤色石是一种荣耀，仅保留给最英勇的牛头人，包括曾与凯恩·血蹄并肩作战以确保莫高雷安全并建立雷霆崖的伟大战士，以及在为部落服务时牺牲的英雄。",al={"谁被火化于此","赤色石的死者","这是谁的坟墓"}},{q="这里会举行什么仪式？",a="除了安葬受人尊敬的英雄，这座峭壁还是“智慧试炼”的核心场所。年轻的牛头人勇士会在这里留下祭品，聆听风中传来的祖先之灵的指引。",al={"赤色石的仪式","牛头人在赤色石的仪式"}}},fx={dabb6ac9={q="什么是赤色石？",a="赤色石是莫高雷东北部一处显眼的红色砂岩地貌。对牛头人而言，这里是受尊崇的圣地，位于尘世的雷霆崖与远方的祖灵领域之间。牛头人青年会在此完成成年仪式，各部族也会在这里纪念最伟大的阵亡勇士。",al={"什么是赤色石","关于赤色石","赤色石概况"}},["281a060c"]={q="赤色石危险吗？",a="这里原本一直是宁静庄严的圣地，但如今因野蛮的刺背野猪人入侵而危机四伏。这些入侵者亵渎了墓地，还会主动攻击任何接近圣地的人。",al={"赤色石危险吗","赤色石的危险","赤色石的敌人"}},["63db11a0"]={q="为什么叫赤色石？",a="这个地方因独特的天然峭壁和鲜红的砂岩地貌而得名，与周围山谷起伏的绿色草原形成鲜明区别。",al={"为什么叫赤色石","赤色石名称的含义","为什么是赤色石"}}},fp="9,133,36.383.0,24.374.0,33.141.0,36.195.0,27.185.0,35.168.0"}
P.entries["subzone:refuge-pointe"] = {n="避难谷地",s="避难谷地是联盟以及激流堡的幸存者在阿拉希高地内的主要堡垒。它位于高地贸易道路的中心，是收复残破的激流堡首都以及抵御该地区敌对势力的集结地。",h="避难谷地是联盟以及激流堡的幸存者在阿拉希高地内的主要堡垒。它位于高地贸易道路的中心，是收复残破的激流堡首都以及抵御该地区敌对势力的集结地。",kw={"阿拉希高地","阿拉索","尼艾丝队长","阿拉索联军","避难谷地","激流堡","萨多尔大桥"},ang={["faction:Alliance"]="避难谷地是你身处阿拉希高地时唯一的军事避难所和飞行点，在这片由食人魔、辛迪加和部落争夺的危险领土上提供着至关重要的补给。",["race:Human"]="对人类而言，避难谷地令人感慨地唤起了激流堡作为人类尚武之地的昔日荣光。这里的守军坚忍不拔，即使敌众我寡，也不肯放弃家园。"},sec={{t="激流堡残部的堡垒",b="第三次大战和激流堡的惨痛沦陷之后，激流堡的大部分幸存平民逃往了南方的安全地带。留下的人组成了一支坚定的先锋队，在尼艾丝队长的指挥下坚守在避难谷地。这个营地由久经沙场的激流堡士兵、阿拉索联军部队以及支援的联盟专家组成，代表着该王国在其故土上最后的有组织抵抗。"},{t="兵力捉襟见肘",b="避难谷地一直处于岌岌可危的边缘。由于被位于落锤镇的被遗忘者和部落、枯木巨魔、辛迪加盗贼以及巨石食人魔团团包围，驻军没有丝毫预备队可供调遣。当位于受损严重的萨多尔大桥的矮人指挥官急切请求增援以击退黑铁矮人时，尼艾丝队长不得不予以拒绝。避难谷地的每一把剑、每一面盾牌和每一份补给都必须用于保卫高地，并为夺回激流堡的反攻做准备。"}},faq={{q="为什么联盟在这里的兵力如此薄弱？",a="激流堡王国在第三次大战后沦为废墟，迫使大多数幸存的平民向南撤离。避难谷地的部队是激流堡军队的一支陷入苦战的残部，并得到了联盟远征军的加强。由于补给极度匮乏，且四面受敌，他们勉强只能守住自己的防御营地。",al={"避难谷地为何规模小","为何士兵这么少","阿拉希联盟兵力"}},{q="为什么避难谷地不派兵支援萨多尔大桥？",a="矮人信使前来请求派兵，协助保卫丹莫德和萨多尔大桥，抵御黑铁的进攻，尼艾丝队长却不得不拒绝。激流堡已经沦陷，敌对势力又将他们团团包围，无论为了职责还是生存，每一名士兵都必须留下，坚守高地，夺回沦陷的都城。",al={"为何不支援丹莫德","尼艾丝队长 萨多尔大桥","联盟的恳求任务"}},{q="谁指挥这座营地？",a="尼艾丝队长指挥着避难谷地的驻军。她负责指导激流堡在高地各处的军事行动，协调侦察工作、针对辛迪加和食人魔的小规模战斗，以及沿着主干道的防御巡逻。",al={"避难谷地指挥官","这里由谁负责","尼艾丝队长"}},{q="阿拉索联军是什么？",a="阿拉索联军是一个致力于收复阿拉希高地并保卫邻近阿拉希盆地重要资源的联盟组织。他们与避难谷地的激流堡残部并肩作战，抵御被遗忘者领导的污染者对这片肥沃山谷的控制。",al={"阿拉索联军","阿拉索联军是谁","阿拉希盆地联盟"}}},fp="13,223,35.397.0,22.410.0,43.276.0,66.270.0,22.196.0,30.269.0"}
P.entries["subzone:remtravel-s-excavation"] = {n="雷姆塔维尔挖掘场",s="雷姆塔维尔挖掘场是一处位于黑海岸南部的考古挖掘点。该探险队由矮人勘察员雷姆塔维尔建立，最近他们在挖掘古老的地下遗迹时，意外发掘出了充满敌意的石腭怪和石傀儡，这些生物很快就淹没了整个采石场。",h="雷姆塔维尔挖掘场是一处位于黑海岸南部的考古挖掘点。该探险队由矮人勘察员雷姆塔维尔建立，最近他们在挖掘古老的地下遗迹时，意外发掘出了充满敌意的石腭怪和石傀儡，这些生物很快就淹没了整个采石场。",kw={"黑海岸","挖掘","化石","傀儡","碎石","勘察员","雷姆塔维尔","石腭怪"},ang={["race:Dwarf"]="探险者协会的矮人探险家以寻求过去的秘密而闻名，尽管在异国土地上挖掘出危险的石腭怪往往会带来熟悉的麻烦。",["race:NightElf"]="卡多雷通常对联盟矮人这种深入的干预行为持怀疑态度，尤其是在这种粗心大意的挖掘惊动了黑海岸古老土地上的野生石腭怪时。"},sec={{t="被淹没的采石场",b="勘察员雷姆塔维尔来到黑海岸寻找遥远过去的遗物，他在远离奥伯丁安全区域的地方建立了一个雄心勃勃的挖掘点。当挖掘古老地层时，他的团队在地底之下发掘出了一群地下碎石石腭怪，以及笨重的石傀儡。该挖掘点瞬间从学术考古地变成了危险区，矿工们四散奔逃，雷姆塔维尔也只能匆忙撤离，试图抢回他最有价值的发现。"},{t="失踪的化石",b="在挖掘现场陷入混乱之前，雷姆塔维尔曾发现过一块散发着奇异神秘特性的稀有化石。在石腭怪突袭引发的恐慌中，再加上他那出了名的健忘，这位勘察员在混乱的土坑中弄丢了这件珍贵的遗物。深入挖掘点取回化石意味着必须同时面对凶恶的石腭怪和那些被镐头惊醒的古老自动机械。"}},faq={{q="雷姆塔维尔挖掘场是什么地方？",a="这是一处位于黑海岸南部的考古挖掘点，由勘察员雷姆塔维尔建立，他是一位寻找古老化石和地下遗物的探险家。",al={"这里是什么地方","黑海岸挖掘点","雷姆塔维尔挖掘场"}},{q="为什么这里会有石腭怪？",a="矮人矿工挖掘得太深，凿穿了地下洞穴，惊醒了当地的一个被称为碎石石腭怪的部落，同时也惊醒了沉睡的石傀儡。",al={"为什么黑海岸有石腭怪","碎石石腭怪","石腭怪来自哪里"}},{q="勘察员雷姆塔维尔是谁？",a="他是一位领导挖掘工作的矮人考古学家。他以对文物的敏锐眼光和健忘的性格而闻名，在挖掘场遭到袭击时，他弄丢了一块关键的化石。",al={"雷姆塔维尔是谁","勘察员雷姆塔维尔背景故事"}},{q="这里发现了什么样的遗物？",a="在石腭怪从深处涌出之前，雷姆塔维尔发现了一块蕴含着奇异、神秘特性的特殊化石。",al={"他们发现了什么","雷姆塔维尔的化石","神秘化石"}}},fp="22,79,16.367.0,18.341.1,31.139.0,26.134.0,28.167.0,39.114.0"}
P.entries["subzone:render-s-rock"] = {n="撕裂者之石",s="撕裂者之石是一座隐藏在赤脊山西北角悬崖中的洞穴要塞，坐落在通往燃烧平原的高处山口附近。它由凶猛的黑石兽人控制，作为前进堡垒，是他们对下方山谷进行突袭的活跃集结地。",h="撕裂者之石是一座隐藏在赤脊山西北角悬崖中的洞穴要塞，坐落在通往燃烧平原的高处山口附近。它由凶猛的黑石兽人控制，作为前进堡垒，是他们对下方山谷进行突袭的活跃集结地。",kw={"黑石兽人","燃烧平原","基沙恩下士","基沙恩","赤脊山","撕裂者之石"},ang={["faction:Alliance"]="对于联盟战士来说，撕裂者之石代表了黑石氏族在赤脊山最根深蒂固的据点之一，清除它是营救基沙恩下士和保护湖畔镇的关键。"},sec={{t="高地上的黑石堡垒",b="撕裂者之石开凿于湖畔镇北部的崎岖高地，是入侵的黑石氏族的防御性洞穴系统。从这个靠近通往燃烧平原山口的易守难攻的堡垒出发，经验丰富的黑石兽人策划着针对赤脊山当地守军的进攻。这里阴影重重的深处戒备森严，对于那些试图切断兽人补给线或营救冲突中失踪战俘的人来说，任何深入其中的尝试都是极其危险的行动。"},{t="阴影中的人质",b="除了对兽人的战略价值外，撕裂者之石对湖畔镇的守军也具有严峻的重要性。赤脊山的受伤士兵基沙恩下士被囚禁在其深处。基沙恩身陷敌后，与同伴失散，他的被俘既体现了黑石氏族入侵的猖獗，也凸显了当地驻军为保卫山路畅通所付出的沉重代价。"}},faq={{q="撕裂者之石在哪里？",a="撕裂者之石位于赤脊山西北部的极远处山峰中，坐落在通往北方燃烧平原的小路旁。",al={"撕裂者之石位置","撕裂者之石在哪里","寻找撕裂者之石"}},{q="谁控制着撕裂者之石？",a="这个洞穴被强大的黑石兽人占据，他们将此峭壁作为堡垒来协调进攻，并监控着与燃烧平原接壤的山路。",al={"谁住在撕裂者之石","撕裂者之石的敌人","谁控制了撕裂者之石"}},{q="谁被关押在洞穴里？",a="联盟驻军的一名受伤老兵基沙恩下士被关押在撕裂者之石内，需要援助才能安全逃回湖畔镇。",al={"基沙恩位置","撕裂者之石俘虏","谁被困在撕裂者之石"}},{q="为什么这个洞穴对湖畔镇的防御很重要？",a="因为撕裂者之石在赤脊山谷上方窝藏了经验丰富的黑石战士，对湖畔镇构成了直接威胁，并使兽人得以在燃烧平原以南维持一个立足点。",al={"为什么要进攻撕裂者之石","撕裂者之石威胁","撕裂者之石的重要性"}}},fp="13,148,34.333.0,24.279.1,31.117.0,27.138.0,34.136.0,50.159.0"}
P.entries["subzone:render-s-valley"] = {n="撕裂者山谷",s="撕裂者山谷是位于赤脊山东南部的一处偏僻营地，由黑石兽人占据。相比起规模宏大的石堡要塞，这里的防御工事要薄弱得多，但它依然对附近的旅人构成了持续的威胁，并关押着从周边地区掠夺来的俘虏。",h="撕裂者山谷是位于赤脊山东南部的一处偏僻营地，由黑石兽人占据。相比起规模宏大的石堡要塞，这里的防御工事要薄弱得多，但它依然对附近的旅人构成了持续的威胁，并关押着从周边地区掠夺来的俘虏。",kw={"黑石兽人","赤脊山","撕裂者山谷","阿祖拉之塔的仆从","悲伤沼泽通道"},ang={["faction:Alliance"]="该营地是黑石氏族的一个次要劫掠前哨，威胁着赤脊山南部，因此铲除它对于保障湖畔镇的贸易与交通至关重要。",["profession:Tailoring"]="被关押在兽人营地的阿祖拉之塔仆从会向那些愿意杀出重围接近他的工匠提供独特的裁缝图纸和材料。"},sec={{t="东南方的一处立足点",b="撕裂者山谷坐落在止水湖东南方向的崎岖山脊之间，是黑石兽人在赤脊山活动的辅助营地。与北部悬崖上那些防御森严的堡垒和石塔不同，这座山谷仅由几顶简陋的战帐、旗帜和哨岗组成。尽管这里的兵力规模和武装程度都不如黑石氏族的核心部队，但他们依然不断劫掠当地的道路，骚扰过往行人，并将被捕的俘虏关押在简陋的笼子里严加看守。"},{t="秘密路径与被俘者",b="除了在土路上巡逻的战队外，这座山谷对于勇敢的侦察兵来说还有意想不到的发现。营地内偶尔能见到人类俘虏的身影，其中包括一名与阿祖拉之塔有关联的被俘仆从，他竟然在看守者的眼皮底下成功地交易了特种商品。此外，山谷后方高耸的南部峭壁上还有一些崎岖且未标记的小径，敢于冒险的探路者可以通过这些路径翻越边境，进入昏暗的悲伤沼泽。"}},faq={{q="谁控制着撕裂者山谷？",a="该山谷由黑石氏族占据，这是一个极具侵略性的兽人派系，他们从燃烧平原向南推进至赤脊山，意图征服领土并骚扰人类定居点。",al={"谁在撕裂者山谷","撕裂者山谷兽人","撕裂者山谷是什么氏族"}},{q="这里的兽人和石堡的兽人一样危险吗？",a="不。驻扎在撕裂者山谷的黑石战士通常比驻守在北部石堡要塞的精锐部队更年轻，战斗力也相对较弱。",al={"撕裂者山谷难度","这里的兽人有多强"}},{q="营地里关押的俘虏是谁？",a="一名与艾尔文森林的阿祖拉之塔有关联的仆从被黑石氏族俘获并关押在这里。那些有胆量接近他的人可以获得专业的裁缝用品。",al={"撕裂者山谷俘虏","赤脊山的阿祖拉之塔仆从","撕裂者山谷裁缝"}},{q="能从这里前往悲伤沼泽吗？",a="可以。在撕裂者山谷后方，有一条陡峭的非官方山路蜿蜒穿过南部的峭壁，这是一条直接通往悲伤沼泽北部荒野的隐藏捷径。",al={"通往悲伤沼泽的道路","撕裂者山谷山路","赤脊山到悲伤沼泽的捷径"}}},fp="15,154,27.411.0,25.377.0,29.172.0,57.162.0,37.182.0,45.148.0"}
P.entries["subzone:rethban-caverns"] = {n="瑞斯班洞穴",s="瑞斯班洞穴是一套隐藏在赤脊山西北侧悬崖中的庞大洞穴系统。这里盘踞着好斗的赤脊山豺狼人，它是瑞斯班矿石这种稀有矿产的唯一来源，因此而闻名。",h="瑞斯班洞穴是一套隐藏在赤脊山西北侧悬崖中的庞大洞穴系统。这里盘踞着好斗的赤脊山豺狼人，它是瑞斯班矿石这种稀有矿产的唯一来源，因此而闻名。",kw={"多诺·烂爪","烂爪","豺狼人","湖畔镇","赤脊山","瑞斯班","瑞斯班洞穴","瑞斯班矿石"},ang={["faction:Alliance"]="盘踞在洞穴内那群好斗的豺狼人对赤脊山北部的旅行者构成了持续的威胁，需要湖畔镇的守卫来确保断崖的安全。",["profession:Mining"]="这些洞穴因盛产瑞斯班矿石而闻名，这是一种当地豺狼人部落激烈争夺的矿产资源。"},sec={{t="豺狼人巢穴",b="瑞斯班洞穴深深地开凿在俯瞰止水湖的西北侧山脉中，是当地豺狼人的防御要塞。在狡诈的领袖多诺·烂爪的统领下，这群豺狼人凶猛地守卫着弯曲的通道和地底洞室，攻击任何靠近其山坡入口的游荡者。"},{t="瑞斯班的矿脉",b="这些洞穴以瑞斯班矿石而闻名，这是一种在岩壁中发现并被烂爪氏族所持有的独特矿物。湖畔镇的铁匠和研究者经常派遣旅行者进入危险且蜿蜒的隧道，以收集这种稀有的山脉矿石样本。"}},faq={{q="瑞斯班洞穴位于何处？",a="洞穴位于赤脊山西北部地区的参差断崖沿线，在通往湖畔镇主路的北面。",al={"瑞斯班洞穴位置","瑞斯班在哪里","如何找到瑞斯班洞穴"}},{q="什么生物栖息在瑞斯班洞穴中？",a="隧道中挤满了烂爪氏族的赤脊山豺狼人，他们听命于狡诈的酋长多诺·烂爪。",al={"瑞斯班怪物","谁住在瑞斯班洞穴","瑞斯班敌人"}},{q="为什么冒险者要进入这些洞穴？",a="来自湖畔镇的旅行者和镇民们为了寻找瑞斯班矿石而来，这是一种在洞穴深处发现并被盘踞在此的豺狼人所持有的稀有矿脉。",al={"瑞斯班洞穴任务","为什么去瑞斯班洞穴","瑞斯班矿石任务"}}},fp="15,121,14.236.0,20.226.0,34.109.0,44.90.0,44.131.0"}
P.entries["subzone:ridgepoint-tower"] = {n="山巅之塔",s="山巅之塔是一座加固过的哨所，监视着艾尔文森林的东部边境。它由暴风城卫兵驻守，是防御王国中心地带免受敌对势力侵袭的一道预警屏障。哨所的卫兵们密切监视着通往邻近荒野的危险通道。",h="山巅之塔是一座加固过的哨所，监视着艾尔文森林的东部边境。它由暴风城卫兵驻守，是防御王国中心地带免受敌对势力侵袭的一道预警屏障。哨所的卫兵们密切监视着通往邻近荒野的危险通道。",kw={"迪菲亚","暮色森林","艾尔文森林","豺狼人","赤脊山","山巅之塔","暴风城卫兵","瞭望塔"},ang={["class:Warrior"]="无论是士兵还是雇佣兵，都会对这些在危机四伏的边境前哨坚守的卫兵们肃然起敬。",["faction:Alliance"]="对于联盟的旅行者来说，山巅之塔是一座令人心安的灯塔，代表着在穿越赤脊山危险山口或暮色森林闹鬼道路之前的安全与秩序。"},sec={{t="东部边境的哨兵",b="山巅之塔矗立在艾尔文森林东部的高地上，是暴风城势力在未开化荒野之外的最后堡垒。驻扎在此地的守军时刻监视着周围的山谷和道路。随着大陆各处的局势日益紧张，这座石制瞭望塔确保了任何威胁在危及北郡和闪金镇附近的农场与定居点之前，就能被及时发现并遏制。"},{t="地平线上的重重威胁",b="山巅之塔同时面临来自多个方向的压力。东面是赤脊山，那里有凶猛的豺狼人部族和黑石兽人袭击者不断试探人类的防御。穿过南方的河流，便是阴影笼罩的暮色森林，那里潜伏着亡灵恐怖。在更近的地方，迪菲亚潜行者的强盗们在荒野营地中四处游荡，急于利用守军防线上的任何空隙。"}},faq={{q="什么是山巅之塔？",a="山巅之塔是一座由暴风城卫兵在艾尔文森林东部运营的加固侦察塔。它作为前线哨所，负责警示并保护王国免受敌对入侵。",al={"山巅之塔 艾尔文","这座哨塔是什么","艾尔文东部塔楼"}},{q="谁控制并驻守这座塔？",a="这座塔由效忠于暴风城王国的卫兵和侦察兵把守并驻扎，并在暴风城卫队的指挥下运作。",al={"谁在山巅之塔","谁拥有山巅之塔"}},{q="驻军在防范哪些威胁？",a="卫兵们防范着从赤脊山涌出的豺狼人和入侵的兽人，从暮色森林被亵渎的树林中穿行而来的亡灵，以及在附近隐秘林地营地活动的迪菲亚强盗。",al={"山巅之塔附近的敌人","是什么在攻击山巅之塔","为什么这里会有塔"}},{q="山巅之塔位于何处？",a="它矗立在艾尔文森林最东端的高地上，靠近艾尔文森林与赤脊山以及暮色森林的交界处。",al={"山巅之塔位置","山巅之塔在哪里"}}},fx={eff326af={q="山巅之塔危险吗？",a="高塔本身很安全，由暴风城卫队牢牢掌控，但周围的土地危机四伏。这座哨塔坐落于边境要地，时刻受到各种威胁：从赤脊山下来的豺狼人和兽人、从暮色森林向北游荡的不死生物，以及潜伏在附近营地中的迪菲亚匪徒。",al={"山巅之塔危险吗","山巅之塔安全吗","山巅之塔的威胁"}}},fp="16,198,30.257.0,24.328.0,25.127.0,32.131.0,45.191.0,34.121.0"}
P.entries["subzone:rocktusk-farm"] = {n="石牙农场",s="石牙农场是位于杜隆塔尔北部的一个小型养猪场，坐落在奥格瑞玛大门外的道路旁。该农场紧邻首都的防御工事，为城中居民供应必要的肉类和物资。",h="石牙农场是位于杜隆塔尔北部的一个小型养猪场，坐落在奥格瑞玛大门外的道路旁。该农场紧邻首都的防御工事，为城中居民供应必要的肉类和物资。",kw={"杜隆塔尔","部落补给","奥格瑞玛","养猪场","石牙农场","猪"},ang={["faction:Horde"]="农场坐落在首都郊外，这里饲养的猪只对于驻扎在奥格瑞玛的战士和劳工来说是至关重要的食物来源。",["profession:Cooking"]="农场里饲养的猪深受部落厨师的青睐，他们一直在寻找新鲜的猪肉、肋排和美味的肉块进行烧烤。"},sec={{t="首都的补给",b="石牙农场在杜隆塔尔干旱的土地上开辟而成，专门饲养能够适应粗砺沙漠气候的耐寒猪。由于杜隆塔尔的土地极其干旱且多石，耕种非常困难，因此家猪养殖场成为了维持奥格瑞玛日益增长的人口所需的基本生命线。农场坐落在首都坚固的防御圈附近，享有着在红色峡谷荒野中难得的安全保障。"}},faq={{q="石牙农场的用途是什么？",a="石牙农场是一个家猪养殖场。它饲养猪只，为邻近的奥格瑞玛首都供应鲜肉和物资，因为那里缺乏耕地。",al={"这是什么地方","石牙农场的作用","为什么这里有猪"}},{q="石牙农场位于哪里？",a="农场位于杜隆塔尔北部，就在奥格瑞玛正门西南方向的道路旁，依傍着岩石峭壁。",al={"石牙农场在哪里","石牙农场位置"}},{q="农场能避开野兽的威胁吗？",a="由于它紧邻奥格瑞玛且有部落巡逻队驻扎，相比杜隆塔尔其他偏远的农场要安全得多，尽管仍有一些野兽和徘徊的害虫出没在边缘地带。",al={"石牙农场安全吗","石牙农场的危险"}}},fp="13,189,26.255.0,31.94.0,31.119.0,34.156.0"}
P.entries["subzone:roguefeather-den"] = {n="飞羽洞穴",s="飞羽洞穴是坐落在千针石林中南部的一处洞穴。这座洞穴里盘踞着凶猛尖叫的鹰身人，鹰身人将这里当作一处加固过的巢穴，并把搜刮来的补给藏在深处的阴暗角落里。",h="飞羽洞穴是坐落在千针石林中南部的一处洞穴。这座洞穴里盘踞着凶猛尖叫的鹰身人，鹰身人将这里当作一处加固过的巢穴，并把搜刮来的补给藏在深处的阴暗角落里。",kw={"洞穴","鹰身人","飞羽","飞羽洞穴","巢穴","千针石林"},ang={["faction:Horde"]="对于前往闪光平原的长途跋涉的部落旅行者来说，栖息在飞羽洞穴中的那群好斗的鹰身人构成了南部峡谷底部持续存在的空中威胁和伏击威胁。"},sec={{t="峡谷中的巢穴",b="飞羽洞穴开凿在千针石林南部的陡峭砂岩断崖上，是当地鹰身人那污秽的巢穴。鹰身人以其野蛮的尖叫和极强的领地意识而闻名，它们将这个洞穴既视为安全的避难所，也视为仓库，警惕地守卫着堆放在洞穴后方深处黑暗角落里的食物和Stolen Supplies。"}},faq={{q="飞羽洞穴是什么？",a="这是一处位于千针石林南侧峭壁上的小型洞穴，是具有领地意识的飞羽鹰身人的巢穴和补给仓库。",al={"这个洞穴是什么","飞羽洞穴信息","飞羽洞穴在哪里"}},{q="什么生物栖息在这个洞穴里？",a="洞穴里盘踞着充满敌意、不断尖叫的鹰身人，它们凶猛地保护着自己的巢穴和囤积的食物，抵御任何入侵者。",al={"谁住在飞羽洞穴里","飞羽洞穴里的怪物"}},{q="飞羽洞穴深处藏着什么？",a="在洞穴的最深处，鹰身人囤积着搜刮和窃取来的食物，并以无情的攻击性守护着它们。",al={"洞穴深处有什么","飞羽食物"}}},fx={["2910d8e2"]={q="飞羽洞穴危险吗？",a="是的，进入洞穴极其危险。洞内狭窄，盘踞着凶猛尖叫的 鹰身人，它们会拼命守护自己的领地。进入者可能在黑暗的隧道中遭到围攻，尤其是靠近洞穴深处时，那里的一群 鹰身人 会狂热地守护它们囤积的物资。",al={"飞羽洞穴危险吗","飞羽洞穴的危险","飞羽洞穴有多危险"}}},fp="16,155,22.215.0,25.140.0,32.109.0,42.87.0"}
P.entries["subzone:rogues-quarter"] = {n="Rogues' Quarter",s="潜行者区是幽暗城东南侧一个灯光昏暗的区域。这里是被遗忘者的斥候、刺客和地下活动人员的集结地，同时也聚集了支持他们的工匠。",h="潜行者区是幽暗城东南侧一个灯光昏暗的区域。这里是被遗忘者的斥候、刺客和地下活动人员的集结地，同时也聚集了支持他们的工匠。",kw={"工程学","被遗忘者","制皮","毒药商人","潜行者训练师","潜行者区","剥皮","幽暗城"},ang={["class:Rogue"]="对于被遗忘者和部落的刺客来说，这个区域是掌握潜行、学习战斗技巧和储备致命毒药试剂的首选中心。",["profession:Engineering"]="修补匠们来到潜行者区学习图纸，并制作隐秘特工所青睐的炸弹、小玩意和机械工具。"},sec={{t="幽暗城的阴影",b="潜行者区隐藏在地下都市的东南象限，聚集了被遗忘者中最狡诈、最致命的幸存者。生前，他们中的许多人曾是洛丹伦王国的盗贼、扒手或沉默的利刃；死后，他们在潜行、毒药和误导方面的专长被重新利用，用以保护这个新生的国家免受天灾军团和血色十字军的威胁。该区域充满了静谧的活动，提供了一个隐秘的避风港，特工们在这里磨砺匕首，酿造致命毒素，并磨练秘密技能。"},{t="生存工具",b="除了潜行和暗杀，潜行者区还是实现隐蔽生存的专业技能所在地。工匠们聚集在这里，教导旅行者学习制皮和剥皮，将生皮转化为轻便、静音的护甲。当工匠们组装小玩意时，工程学工作台的碰撞声在石厅中回荡，而战地医师和药剂师则提供急救指导，并出售隐秘行动所必需的致命毒药。"}},faq={{q="潜行者区位于哪里？",a="潜行者区位于幽暗城外环的东南部分，穿过贸易区即可到达。",al={"潜行者区位置","潜行者区在哪里","幽暗城潜行者区地图"}},{q="这里有哪些训练师？",a="该区域设有潜行者训练师，以及制皮、剥皮、工程学和急救的导师。附近还驻扎有毒药商人以供应试剂。",al={"潜行者区训练师","幽暗城潜行者训练师","谁在潜行者区训练"}},{q="为什么被遗忘者要专门为潜行者保留一个区域？",a="被遗忘者被天灾军团和血色十字军等敌对势力包围，他们严重依赖间谍活动、暗杀和打了就跑的战术来保卫领土，这使得隐秘特工对他们的生存至关重要。",al={"为什么被遗忘者需要潜行者","被遗忘者刺客","幽暗城潜行者背景故事"}}},fp="15,150,24.374.0,18.312.0,37.103.0,32.145.0,61.185.0"}
P.entries["subzone:roland-s-doom"] = {n="罗兰之墓",s="罗兰之墓是一座荒废、阴影笼罩的矿井，坐落于暮色森林的东南部山区，就在烂果园的东边。这里曾是一处普通的挖掘点，如今却因被野蛮的狼人占领而成为了臭名昭著的危险巢穴。",h="罗兰之墓是一座荒废、阴影笼罩的矿井，坐落于暮色森林的东南部山区，就在烂果园的东边。这里曾是一处普通的挖掘点，如今却因被野蛮的狼人占领而成为了臭名昭著的危险巢穴。",kw={"噬骨者","基特斯","内法鲁","夜祸","罗兰之墓","烂果园","艾露恩之镰","维琳德·星歌"},ang={["profession:Mining"]="虽然这里曾经是一座运作中的采石场，但任何愚蠢到在这里挥动十字镐的勘探者都会很快发现，罗兰之墓里唯一的矿脉就是嗜血的狼人。",["race:NightElf"]="对失踪的女祭司维琳德·星歌和难以捉摸的艾露恩之镰的搜寻，使得罗兰之墓成为了那些调查族人命运的暗夜精灵们进行沉思的场所。"},sec={{t="阴影与野蛮的巢穴",b="罗兰之墓开凿在烂果园以东的山脊中，早已不再是运作中的矿井。它现在是夜祸狼人氏族的暴力聚集地，由噬骨者和内法鲁等野兽领导。阴暗的隧道中回荡着低沉的咆哮，弥漫着潮湿的泥土和血腥味，这使得它成为暮色森林对粗心大意的旅人而言最危险的角落之一。"},{t="维琳德·星歌的陨落",b="罗兰之墓真正的悲剧深埋在它的隧道之中。正是此地，暗夜精灵女祭司维琳德·星歌在携带艾露恩之镰——一件拥有强大且不稳定力量的远古神器——时走到了生命的尽头。矿井中被惊动的尘土依然能唤起维琳德残留的灵魂，诉说着她最后的时刻。后来，受惊的流浪者基特斯在挖掘点内偶然发现了这把镰刀，意外地导致野蛮狼人的数量激增，并将致命的黑暗骑士引到了暮色森林。"}},faq={{q="什么是罗兰之墓？",a="罗兰之墓是一座位于暮色森林东南部，烂果园东侧的废弃矿井。目前已被凶残的夜祸狼人所占领。",al={"罗兰之墓在哪里","这个矿井是什么"}},{q="为什么矿井里会有狼人？",a="在艾露恩之镰遗失后，这座矿井就被狼人所侵占。目前，包括内法鲁和噬骨者在内的夜祸狼人氏族强悍野兽，都在其潮湿的矿道中筑巢。",al={"为什么这里有狼人","谁住在罗兰之墓"}},{q="维琳德·星歌是谁，她为什么与这个地方有关？",a="维琳德·星歌是一位艾露恩的暗夜精灵女祭司，她曾挥舞艾露恩之镰与费伍德森林的恶魔战斗。她的旅程跨越重洋来到暮色森林，并在就在这座矿井中遇害，留下了那把镰刀。",al={"维琳德·星歌与罗兰之墓","谁死在这里"}},{q="基特斯在罗兰之墓的故事中扮演了什么角色？",a="基特斯进入了罗兰之墓，发现了埋藏于此的艾露恩之镰。他的插手无意间将更多的狼人释放到暮色森林，并将邪恶的黑暗骑士引向该地区，使这片森林陷入了更大的危险之中。",al={"基特斯与矿井","基特斯与镰刀"}}},fp="13,113,29.375.0,28.414.1,22.122.0,37.153.1,64.228.1,53.206.1"}
P.entries["subzone:rolling-plains"] = {n="草海平原",s="草海平原横跨莫高雷的南部区域，在血蹄村和贫瘠之地的边界之间延伸。这些风吹草动的草原是野生动物繁衍生息的家园，但由于游荡的半人马掠夺者和好斗的鹰身人，这里也时刻保持着警惕。",h="草海平原横跨莫高雷的南部区域，在血蹄村和贫瘠之地的边界之间延伸。这些风吹草动的草原是野生动物繁衍生息的家园，但由于游荡的半人马掠夺者和好斗的鹰身人，这里也时刻保持着警惕。",kw={"血蹄村","半人马","鹰身人","科多兽","莫高雷","草海平原","陆行鸟","狂风"},ang={["class:Hunter"]="草海平原拥有充足的科多兽、陆行鸟、狼和美洲狮群，是磨练追踪技巧、收集补给和驯服第一只动物伙伴的理想荒野。",["race:Tauren"]="草海平原为新统一的部落提供了重要的狩猎场，但古老的半人马宿敌在血蹄村附近出没，使得保卫这条南部走廊成了关乎部落生存的大事。"},sec={{t="莫高雷南部之心",b="草海平原从血蹄村向南延伸，直抵通往贫瘠之地的天然土质大门，体现了牛头人家园广阔开敞的地理特征。该地区拥有部落生存所需的各种野生猎物，包括草原狼、科多兽群、平原美洲狮和敏捷的陆行鸟。对于向长者证明自己价值的年轻猎人来说，这些广袤的草原是不可或缺的试炼场，在此处，追踪术、耐心和对大自然的敬畏都将经受考验。"},{t="迫近的危险",b="尽管莫高雷拥有天然的环形峭壁堡垒，但草海平原依然极易受到外部威胁。这是唯一一个半人马哨兵突破防御外围并骚扰过往旅行者和狩猎小队的边境地区。更糟糕的是，一群捕食性的狂风鹰身人栖息在东部的悬崖上，俯冲扑向落单的猎物和脆弱的游牧营地。"}},faq={{q="在草海平原可以找到哪些动物？",a="这片草原养育了种类丰富的本地动物群，包括漫步的野生科多兽群、敏捷的陆行鸟、游荡的草原狼和潜行的平原美洲狮。这些野兽为血蹄村的部落提供了重要的肉食、毛皮和筋腱。",al={"草海平原野生动物","草海平原生物","莫高雷平原动物"}},{q="为什么半人马会出现在莫高雷的这一区域？",a="草海平原与通往贫瘠之地的东部通道接壤，使其成为莫高雷唯一一个半人马掠夺者能够突破防线的区域。侵扰的哨兵不断侦察平原，试探牛头人的防御并威胁着落单的猎人。",al={"莫高雷的半人马","为什么草海平原有半人马","半人马哨兵"}},{q="还有哪些敌对生物威胁着这片平原？",a="除了游荡的半人马侦察兵之外，一群危险的狂风鹰身人也在该地区的东部悬崖边筑巢，捕食粗心的旅行者并骚扰当地的野生动物。",al={"草海平原的鹰身人","草海平原的危险"}},{q="草海平原的起止范围在哪里？",a="平原覆盖了莫高雷的大部分南部地区，从血蹄村一直延伸到与贫瘠之地接壤的山区边界。",al={"草海平原位置","草海平原在哪里","草海平原边界"}}},fx={["711c701d"]={q="草海平原是什么地方？",a="草海平原是莫高雷南部广阔的开阔草原，从血蹄村一直延伸到贫瘠之地的边界。这里是富饶的狩猎场，栖息着科多兽、 陆行鸟、狼和美洲狮等野生动物，也是莫高雷南部牛头人领地的牧歌般腹地。",al={"草海平原是什么地方","草海平原的背景","草海平原简介"}},["8a6ccc31"]={q="草海平原危险吗？",a="草原虽是开阔的狩猎场，却并非毫无危险。除了四处游荡的美洲狮和狼，这里还是莫高雷唯一有半人马斥候侵入的区域，它们在开阔地带四处游荡。东部还有一处凶猛的风怒鹰身人巢穴，对旅行者和猎人构成额外威胁。",al={"草海平原有多危险","草海平原的危险","草海平原安全吗"}}},fp="14,105,25.324.0,19.356.0,48.161.0,53.238.0,49.143.0,42.117.0"}
P.entries["subzone:rotting-orchard"] = {n="烂果园",s="烂果园是一片位于暮色森林南部的荒废果林。它曾经是附近夜色镇居民的收成来源，如今已陷入一片颓败，并被一群被称为“夜行者”狼人的凶猛掠食者所占据。",h="烂果园是一片位于暮色森林南部的荒废果林。它曾经是附近夜色镇居民的收成来源，如今已陷入一片颓败，并被一群被称为“夜行者”狼人的凶猛掠食者所占据。",kw={"夜色镇","暮色森林","夜行者","烂果园","暗影编织者","狼人"},ang={["class:Hunter"]="扭曲的树木和损毁的外屋提供了绝佳的潜行场地，但夜行者狼人敏锐的掠食本能和法术，让这里随时都可能发生伏击。",["faction:Alliance"]="夜行者狼人对烂果园的侵占，对不远处的夜色镇本就脆弱的安全构成了直接的掠食威胁。"},sec={{t="夜行者巢穴",b="烂果园坐落在废弃的约根农场以东、静谧花园墓场以西，是暮色森林衰败的冷酷见证。果树上挂满了枯萎腐烂的果实，破败的谷仓和外屋则被夜行者狼人改造成了简陋的营地。夜行者潜行者在扭曲的灌木丛中徘徊，而被称为“暗影编织者”的黑暗施法者们则在腐朽的木材间编织着邪恶的魔法。这群狼人听命于凶猛的古斯皮尔和内法鲁，他们潜伏在附近的罗兰之墓矿井中。"}},faq={{q="烂果园里有哪些生物？",a="这片果园完全被夜行者狼人一族所盘踞。其中包括狡诈的潜行者——夜行者潜行者，以及被称为“夜行者暗影编织者”的黑暗施法者。",al={"烂果园怪物","谁住在烂果园","烂果园有什么"}},{q="烂果园在暮色森林的什么位置？",a="烂果园位于暮色森林南部，夜色镇西南方。它恰好坐落在西边的约根农场和东边的静谧花园墓场之间。",al={"烂果园位置","烂果园在哪里","如何找到烂果园"}},{q="谁在领导果园里的狼人？",a="这里的夜行者狼人由残暴的古斯皮尔和内法鲁领导，他们将巢穴设在果园东侧的罗兰之墓矿井中。",al={"烂果园首领","谁领导夜行者"}},{q="这个地方一直都被怪物占领吗？",a="并不是。像暮色森林周围的许多农舍一样，这里曾经是一个支持当地人类居民的丰饶农场和果林，直到黑暗诅咒和超自然恐怖笼罩了这片地区，迫使农民们背井离乡。",al={"果园历史","果园为何腐烂"}}},fp="15,159,20.443.0,42.172.0,49.169.0,37.117.0,42.179.0"}
P.entries["subzone:royal-gallery"] = {n="Royal Gallery",s="Royal Gallery隐藏在暴风要塞的庭院花园之后，是一座静谧的纪念厅。厅内陈列着宏伟的雕像和精美的艺术品，用以纪念王国历史和Grand Alliance中的杰出人物。",h="Royal Gallery隐藏在暴风要塞的庭院花园之后，是一座静谧的纪念厅。厅内陈列着宏伟的雕像和精美的艺术品，用以纪念王国历史和Grand Alliance中的杰出人物。",kw={"戴林·普罗德摩尔","迪娜·肯尼迪","莱恩·乌瑞恩","玛拉·弗塔根","皇家画廊","雕像","暴风要塞"},ang={["faction:Alliance"]="这座展廊是联盟牺牲精神的宁静丰碑，向Daelin Proudmoore和莱恩国王等传奇领袖致敬。",["race:Human"]="对于暴风城的人类来说，这座大厅纪念着乌瑞恩家族和弗塔根家族的遗产，将他们的皇家传承保留在要塞之中。"},sec={{t="英雄大厅",b="Royal Gallery毗邻皇家图书馆，就在暴风要塞郁郁葱葱的内花园之外。大厅内安放着塑造了这个王国的伟人雕像：暴风城陨落的统治者莱恩乌瑞恩国王；来自库尔提拉斯的Daelin Proudmoore海军上将；以及第一次战争后逃往洛丹伦的难民的守护者玛拉·弗塔根女士。它既是一座展示高贵传统的私人博物馆，也是德娜·肯尼迪这样的宫廷访客寻求宁静的休憩之所。"}},faq={{q="皇家画廊在哪里？",a="皇家画廊位于暴风要塞内。穿过要塞，经过内部的小型庭院公园，就在皇家图书馆的旁边。",al={"皇家画廊位置","如何前往皇家画廊","它在哪里"}},{q="这里纪念了哪些历史人物？",a="展廊内陈列着宏伟的雕像，纪念莱恩乌瑞恩国王、戴林·普罗德摩尔海军上将和玛拉·弗塔根，颂扬王国及其最亲密盟友的血统与英勇。",al={"皇家画廊的雕像","雕像是谁","这里纪念谁"}},{q="谁会来参观这个展廊？",a="经常可以看到德娜·肯尼迪在展廊内欣赏精美的艺术品，感受这里沉思般的氛围。",al={"谁在这里","皇家画廊的角色","德娜·肯尼迪"}},{q="皇家画廊和皇家图书馆有什么区别？",a="虽然它们在暴风要塞的皇家区紧挨着，但它们是不同的房间。图书馆收藏皇家档案并供学者使用，而展廊则专注于精美的艺术品和纪念雕塑。",al={"皇家画廊与图书馆的区别","它是图书馆的一部分吗"}}},fx={["57ab90b0"]={q="皇家画廊是什么地方？",a="皇家画廊 是一座小巧幽静的展厅，坐落在暴风要塞内，位于庭院小公园后方，毗邻皇家图书馆。这里是一处纪念展区，陈列着精美的艺术品和宏伟的大理石雕像，以纪念联盟与暴风城王国的杰出人物。",al={"皇家画廊是什么","暴风城皇家画廊","这里是什么地方"}},["0132543d"]={q="皇家画廊危险吗？",a="丝毫没有危险。展厅位于暴风要塞核心深处，由城中精锐的皇家卫兵严密守护。这里始终是一座宁静安全的纪念厅，贵族与朝臣可以安心缅怀王国最伟大的英雄，无须担忧受到伤害。",al={"皇家画廊危险吗","皇家画廊的威胁","皇家画廊安全"}}},fp="13,165,16.408.0,35.116.0,47.149.0,38.76.0,71.220.0"}
P.entries["subzone:royal-library"] = {n="Royal Library",s="皇家图书馆坐落在暴风要塞石翼深处，保存着王国的集体记忆、编年史卷轴和论述。在首席图书管理员米尔顿·西弗的注视下，书架上陈列着关于古代战争、失落传说以及海外疆域的关键记录。",h="皇家图书馆坐落在暴风要塞石翼深处，保存着王国的集体记忆、编年史卷轴和论述。在首席图书管理员米尔顿·西弗的注视下，书架上陈列着关于古代战争、失落传说以及海外疆域的关键记录。",kw={"马迪亚斯·肖尔","米尔顿·西弗","皇家图书馆","暴风要塞","暴风城图书馆"},ang={["class:Mage"]="对于奥术学者来说，图书馆提供了关于提瑞斯法的过去、远古屠龙记以及最后守护者遗产的稀有原始资料。",["faction:Alliance"]="书架上保存的基础条约和战争编年史，将人类、矮人和精灵种族在历代冲突中紧密联系在了一起。"},sec={{t="王国的宝库",b="虽然暴风要塞里充满了全副武装的卫兵和宫廷阴谋，但其皇家图书馆却是一片宁静的学术绿洲。该馆由米尔顿·西弗监管，是南方人类历史的首要档案馆，不仅保存着第一次战争前的幸存文献，还有近期的军事编年史和找回的古籍。联盟的学者、牧师和旅行者可以自由查阅馆藏的开放论述，内容涵盖从最初洛丹伦联盟的组建到近期萨尔的部落在卡利姆多崛起等各类信息。"}},faq={{q="皇家图书馆位于哪里？",a="它位于暴风城东区的皇家要塞暴风要塞内。穿过要塞的大门厅，沿着走廊即可到达学者和档案馆区域。",al={"图书馆在哪里","暴风城图书馆位置","如何找到图书馆"}},{q="谁负责管理图书馆？",a="米尔顿·西弗担任首席图书管理员。他负责管理档案记录，并协助学者和冒险者寻找遗失的卷轴或特定的王国文献。",al={"谁是图书管理员","首席图书管理员","米尔顿·西弗"}},{q="这里可以读到什么种类的书？",a="参观者可以阅读涵盖洛丹伦联盟、提瑞斯法守护者、第二次战争余波，以及有关新部落的报告的历史著作，此外还有关于暴风城和奥特兰克的区域历史。",al={"图书馆里的书","可阅读的背景书籍","读什么"}},{q="谁可以使用图书馆？",a="来自联盟所有种族的冒险者都可以来到皇家图书馆，翻阅其广泛收藏的卷轴、古籍和关于各种主题的文献。",al={"我可以使用图书馆吗","谁能在图书馆阅读"}}},fx={["0be1be66"]={q="皇家图书馆是什么地方？",a="皇家图书馆是设在暴风要塞城墙之内的宏伟藏书馆。这里保存着大量历史典籍、古老卷轴，以及探讨影响世界的各类学问的学术论著。联盟各地的学者和冒险者都可以前来翻阅藏书，探寻昔日诸国的历史、奥术知识，以及艾泽拉斯更广阔地域的见闻。",al={"皇家图书馆是什么","关于皇家图书馆","暴风城图书馆背景"}},c9a9445a={q="皇家图书馆危险吗？",a="丝毫没有危险。图书馆位于暴风要塞防御森严的核心深处，由王国的皇家卫兵守护。这里十分安宁，是学者、编年史家和四处游历的冒险者安心研读的清静居所。",al={"皇家图书馆安全吗","皇家图书馆的危险","皇家图书馆的敌人"}},["45bbfcdd"]={q="为什么叫皇家图书馆？",a="它之所以冠以皇家之名，是因为它是 乌瑞恩家族 与暴风城王国的官方宫廷图书馆。这座档案馆就设在暴风要塞的王宫内，由王室资助建立并维护，旨在保存王国的传承、法律与奥术知识。",al={"为什么叫皇家图书馆","皇家图书馆名称由来","皇家图书馆为何得名"}}},fp="13,224,25.436.0,35.158.0,21.156.0,37.217.0,24.125.0"}
P.entries["subzone:royal-quarter"] = {n="Royal Quarter",s="皇家区是幽暗城内隐秘的权力中心，也是希尔瓦娜斯·风行者女士的王座厅。在这里，女妖之王与她的恐惧魔王执行者瓦里玛萨斯共同指挥着被遗忘者，并由精锐的皇家恐惧卫士严密守卫。",h="皇家区是幽暗城内隐秘的权力中心，也是希尔瓦娜斯·风行者女士的王座厅。在这里，女妖之王与她的恐惧魔王执行者瓦里玛萨斯共同指挥着被遗忘者，并由精锐的皇家恐惧卫士严密守卫。",kw={"女妖之王","黑暗女王大厅","皇家恐惧卫士","皇家区","希尔瓦娜斯·风行者","王座厅","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="前往皇家区的部落使节通常以极度怀疑的眼光看待黑暗女王的那斯雷兹姆顾问，质疑在部落主城的核心地带信任一个恶魔是否明智。",["race:Undead"]="皇家区代表了被遗忘者独立的核心，希尔瓦娜斯·风行者和她的恐惧魔王副官在这里规划着他们解放后的人民的未来。"},sec={{t="黑暗女王的王座",b="皇家区隐藏在高耸的拱门和阴影笼罩的走廊之后，也被称为黑暗女王大厅，是被遗忘者的政治和军事中枢。希尔瓦娜斯·风行者在这间巨大的地下室中坐镇，筹划着她那拥有自由意志的亡灵的生存大计，以及摧毁天灾军团的方略。全副武装的皇家恐惧卫士在台座旁守卫，确保不速之客和刺客无法接近他们的女王。"},{t="危险的联盟",b="站在黑暗女王身边的是那斯雷兹姆瓦里玛萨斯，他是幽暗城中心一个出人意料且令人不安的存在。在洛丹伦废墟的内战期间，为了保命，他站在了Sylvanas一边，并向她的事业宣誓效忠。从皇家区开始，他指挥着死亡卫士并协调着整个王国的防御行动。虽然他的战术狡诈对被遗忘者大有裨益，但他那恶魔的本性令许多部落盟友对他真实的忠诚度心存疑虑。"}},faq={{q="谁在皇家区进行统治？",a="女妖之王希尔瓦娜斯·风行者女士在皇家区的王座上统治着被遗忘者。她的身边是那斯雷兹姆瓦里玛萨斯，他在收复洛丹伦期间向她宣誓效忠。",al={"皇家区里的人","幽暗城王座厅领袖","谁统治幽暗城"}},{q="为什么王座厅里会站着一个恐惧魔王？",a="瓦里玛萨斯在收复洛丹伦王都期间向希尔瓦娜斯·风行者投降，随后背叛了他的兄弟德瑟罗克和巴纳扎尔。他通过向希尔瓦娜斯宣誓效忠保住了性命，现在担任她的执行者和侦察兵大师。",al={"为什么瓦里玛萨斯在这里","幽暗城里的恐惧魔王","为什么恶魔在皇家区"}},{q="什么是皇家恐惧卫士？",a="皇家恐惧卫士是专门挑选出来保卫希尔瓦娜斯女士和皇家区的精锐被遗忘者护卫。他们是幽暗城中最训练有素且致命的防御者。",al={"恐惧卫士","幽暗城王座厅守卫","皇家区守卫"}},{q="这间大厅还有什么其他用途？",a="除了作为黑暗女王和瓦里玛萨斯的主要接见大厅外，皇家区还设有战场军官，负责协调部落战士参与艾泽拉斯各地的对外战役和战略冲突。",al={"皇家区里还有什么","皇家区用途","皇家区战场军官"}}},fp="13,180,25.392.0,20.406.0,33.191.0,53.237.0,31.165.0,44.195.0"}
P.entries["subzone:ruined-reaches"] = {n="废墟海岸",s="废墟海岸构成了艾萨拉南部险峻的海岸线，靠近杜隆塔尔的边界。这里遍布着崩塌的古代遗迹、破碎的船只残骸和锯齿状的浅滩，整个海滩被充满攻击性的沿海掠食者所占据。在这一片荒凉之中，一个小型侏儒前哨站高踞于海浪之上的悬崖边。",h="废墟海岸构成了艾萨拉南部险峻的海岸线，靠近杜隆塔尔的边界。这里遍布着崩塌的古代遗迹、破碎的船只残骸和锯齿状的浅滩，整个海滩被充满攻击性的沿海掠食者所占据。在这一片荒凉之中，一个小型侏儒前哨站高踞于海浪之上的悬崖边。",kw={"艾萨拉","布利莫·加基斯普林","杜隆塔尔","锯齿暗礁","朱比·加基斯普林","娜迦","鱼人","废墟海岸"},ang={["profession:Engineering"]="布利莫和朱比·加基斯普林经营的孤独工坊为探索艾萨拉荒野的工程师们提供了宝贵的零件和补给。",["race:Gnome"]="在艾萨拉充满敌意的悬崖上发现一个繁荣的高科技侏儒家园，这提醒着人们，即便远离铁炉堡，侏儒依然足智多谋。"},sec={{t="饱受摧残的海岸",b="废墟海岸沿着艾萨拉的南部边界延伸，位于杜隆塔尔以北，是一个由岩石入口、悬崖峭壁和布满碎片的沙滩组成的迷宫。如同北边的锯齿暗礁一样，隐蔽的浅滩使得海上航行极其危险，导致无数破损的船只残骸散落在岸边。这里的水域和海滩充满了充满敌意的野生生物，包括领地意识极强的鱼人、凶猛的多头蛇和披甲的娜迦，使得陆路交通与航行一样危险。"},{t="加基斯普林前哨站",b="坐落在俯瞰海滩的西侧悬崖上，是一处意想不到的工匠文明据点：一个可以通过艾萨拉大陆一条陡峭小径到达的侏儒工坊。该前哨站由布利莫和朱比·加基斯普林经营，为路过的冒险者提供工程学组件和一般贸易商品。内部设有一部通往私人宿舍的电梯，里面有三张床位，不过那第三张床究竟属于谁——如果确实有人住的话——仍然是一个安静的家庭谜团。"}},faq={{q="废墟海岸位于哪里？",a="它们构成了艾萨拉最南端的海岸带，与杜隆塔尔的北缘接壤。该地区由沙滩、海岸入口和大陆悬崖下的峭壁组成。",al={"废墟海岸位置","废墟海岸在哪里","如何到达废墟海岸"}},{q="这段海岸有什么威胁？",a="海滩和浅水区栖息着敌对的野生动物，主要是充满攻击性的鱼人部落、多头蛇，以及潜伏在潮滩上的娜迦。",al={"废墟海岸的怪物","这里有什么生物","废墟海岸的生物"}},{q="谁住在悬崖上的侏儒建筑里？",a="布利莫和朱比·加基斯普林在那里生活和工作。他们经营着一家小店，为在荒凉海岸航行的旅行者提供工程学零件和贸易补给。",al={"废墟海岸的侏儒","加基斯普林住宅","谁住在侏儒房子里"}},{q="为什么这里有这么多沉船？",a="和邻近的锯齿暗礁一样，这里的沿海水域布满了礁石和隐蔽的危险，经常让毫无防备的船只触礁，并将它们撞得粉碎。",al={"艾萨拉的沉船","为什么船只在这里失事","废墟海岸的残骸"}}},fp="14,219,16.434.0,24.318.0,37.158.0,43.137.0,49.155.0,38.138.0"}
P.entries["subzone:ruins-of-aboraz"] = {n="阿博拉兹废墟",s="阿博拉兹废墟是坐落在荆棘谷东南部悬崖上的古老古拉巴什石制遗迹。这片摇摇欲坠的台地曾经是庞大的丛林巨魔帝国的一部分，如今却成了被放逐的巫医赞吉尔和他那受其奴役、神志不清的仆从们的隐秘堡垒。",h="阿博拉兹废墟是坐落在荆棘谷东南部悬崖上的古老古拉巴什石制遗迹。这片摇摇欲坠的台地曾经是庞大的丛林巨魔帝国的一部分，如今却成了被放逐的巫医赞吉尔和他那受其奴役、神志不清的仆从们的隐秘堡垒。",kw={"阿博拉兹","查基","朱布瓦尔","荆棘谷","巫医","耶尼库","赞吉尔"},ang={["faction:Alliance"]="联盟的私掠者和雇佣兵在追捕与藏宝海湾的地精和海盗有关的债务或赏金时，经常会撞上赞吉尔的势力。",["race:Troll"]="对于暗矛部族来说，阿博拉兹是一种侮辱：一个利用扭曲的巫毒术奴役同胞巨魔，并将年轻的耶尼库扣押在古拉巴什祖先领地上的流亡者。"},sec={{t="巫医的领地",b="阿博拉兹风化的砖石建筑坐落在朱布瓦尔废墟的东南方，水晶矿洞的南面，已经被改造成了一个炼金术的试验场。被放逐的巫医赞吉尔因受到当地部落和大陆居民的共同排斥，退居于此，酿造威力强大的致幻药水和毒性药剂。在这些石砌的庭院里，赞吉尔完全控制着一支令人不安的仆从大军，其中包括蹒跚的亡灵食尸鬼、被腐蚀的巨魔奴隶，甚至还有被俘虏的沿海娜迦。"},{t="棋子与囚徒",b="赞吉尔那诡异的药水不仅能毒害身体，更能摧毁意志。在那些来回踱步的迷失灵魂中，就有被奴役的暗矛部族青年耶尼库，他的意志至今仍被禁锢在赞吉尔的巫术之中。和他一同盲目徘徊的还有查基·“十指”，一个因躲避藏宝海湾的“海狼”麦金利讨债而逃亡的落魄海盗，如今也沦为了赞吉尔药剂下的一具无知守卫。"}},faq={{q="谁统治着阿博拉兹废墟？",a="这片废墟由被放逐的巫医赞吉尔控制，他因其暗黑炼金术和强大的精神控制药剂在整个荆棘谷臭名昭著。",al={"阿博拉兹的首领","阿博拉兹首领","阿博拉兹废墟里的生物"}},{q="为什么这里会有娜迦和食尸鬼聚集在一起？",a="赞吉尔独特的药剂使他能够支配思想并复活尸体。他强迫巨魔流亡者、起尸的丛林食尸鬼以及被诱捕的沿海娜迦成为其台地的无条件守卫。",al={"为什么这里有娜迦","阿博拉兹食尸鬼","阿博拉兹怪物"}},{q="阿博拉兹废墟位于哪里？",a="它们坐落在荆棘谷东南部的高耸悬崖上，位于水晶矿洞以南，朱布瓦尔废墟东南方向，俯瞰着东面的大海。",al={"阿博拉兹位置","阿博拉兹在哪里","如何前往阿博拉兹废墟"}}},fp="15,127,23.428.0,18.280.1,35.150.0,44.160.0,38.181.0"}
P.entries["subzone:ruins-of-alterac"] = {n="奥特兰克废墟",s="白雪覆盖的奥特兰克废墟是奥特兰克王国的曾经那座引以为傲的山中都城——奥特兰克城的遗迹。在第二次战争期间，由于国王艾登·匹瑞诺德的背叛，这座城市被逐出了联盟并被实施了军事管制。如今，这片破败的堡垒已被粗野的碎颅食人魔所占据。",h="白雪覆盖的奥特兰克废墟是奥特兰克王国的曾经那座引以为傲的山中都城——奥特兰克城的遗迹。在第二次战争期间，由于国王艾登·匹瑞诺德的背叛，这座城市被逐出了联盟并被实施了军事管制。如今，这片破败的堡垒已被粗野的碎颅食人魔所占据...",kw={"奥特兰克城","布洛金","碎颅","穆戈尔","匹瑞诺德","奥特兰克废墟","斯坦恩布莱德","辛迪加"},ang={["faction:Horde"]="这座沦陷的城市是旧部落曾经结盟的遗响，但如今它也为被遗忘者提供了从分心的碎颅食人魔手中搜寻魔法圣物的机会。",["race:Human"]="对于联盟的人类来说，这些废墟是对第二次战争中人类软弱与叛国行为的沉重提醒，匹瑞诺德的懦弱曾摧毁了七大王国之间的手足情谊。"},sec={{t="王国的背叛",b="奥特兰克曾是一个从古老的阿拉索帝国中分裂出来的人类独立王国，坐落于穿越群山的贸易路线高处。在第二次战争期间，由于畏惧入侵的旧部落会带来毁灭，国王艾登·匹瑞诺德秘密与兽人达成了协议。当凯尔达隆的战斗结束后，他的背叛行径被揭露，洛丹伦联盟迅速展开了报复。泰瑞纳斯·米奈希尔二世国王对该城实施了军事管制，并废黜了匹瑞诺德。随着民众的逃离或沦为法外之徒，这座宏伟的防御工事、教堂和宫殿也逐渐荒废。"},{t="食人魔的占领",b="虽然幸存的奥特兰克贵族和流亡士兵组成了辛迪加，试图从斯坦恩布莱德等城镇发起游击战，但他们彻底失去了祖辈的都城。今天，穆戈尔率领的碎颅食人魔居住在破碎的城墙、宫殿大厅和残破的弩炮之间。无论是辛迪加还是南海镇的人类防御者，都没能收复这座沦陷的城市，这使得其坍塌的塔楼和废弃的拱顶成为了宝藏猎人和拾荒者眼中的险地。"}},faq={{q="奥特兰克为何会被摧毁？",a="在第二次战争期间，国王艾登·匹瑞诺德为了保全王国，与入侵的兽人部落结盟。洛丹伦联盟发现了这一叛国行为，攻占了奥特兰克城，拆除了其防御设施，并对该王国实施了军事管制。",al={"奥特兰克为什么成为废墟","奥特兰克城发生了什么","奥特兰克的陨落"}},{q="现在是谁住在废墟里？",a="由穆戈尔领导的碎颅食人魔已经接管了宫殿、城墙和积雪的庭院。此外，一名足智多谋的地精炼金商人布洛金正静静地坐在北面的城墙上。",al={"谁控制了奥特兰克废墟","奥特兰克食人魔","谁在奥特兰克"}},{q="辛迪加与这个地方有什么联系？",a="辛迪加主要由失去领土的前奥特兰克贵族和士兵组成，他们在王国解体后失去了家园。尽管他们痛心地渴望收复奥特兰克，但他们已被碎颅食人魔赶出了都城，目前在斯坦恩布莱德等前哨站活动。",al={"辛迪加住在这里吗","辛迪加与奥特兰克的联系"}},{q="联盟的冒险者为什么要来这里？",a="来自南海镇的联盟士兵会对袭击道路的敌对碎颅食人魔发布悬赏，而南方的贵族，例如雷明顿·瑞治维尔伯爵，也会派遣代理人进入废墟，寻找失落的家族传家宝，比如匹瑞诺德王冠。",al={"奥特兰克废墟的联盟任务","碎颅悬赏"}},{q="为什么部落对这些废墟感兴趣？",a="希尔瓦娜斯·风行者和被遗忘者对散落在沦陷人类王国各处的文物有着浓厚的兴趣，他们派遣勇士进入这个被食人魔占据的堡垒，以夺取诸如意志之冠之类的强大圣物。",al={"奥特兰克废墟的部落任务","希尔瓦娜斯奥特兰克"}}},fx={["46d22466"]={q="奥特兰克废墟是什么地方？",a="这些被冰雪覆盖的石墙和残破的雉堞，是奥特兰克城仅存的遗迹。它曾是人类王国奥特兰克引以为傲的山地都城。阿拉索扩张之后数千年，这座城市建立起来，守护着蜿蜒穿过群山的重要贸易路线；直到国王的背叛在第二次战争期间招致了它的覆灭。",al={"奥特兰克废墟是什么","奥特兰克废墟概况","奥特兰克城"}},["967fd086"]={q="第二次战争期间奥特兰克城发生了什么？",a="第二次战争期间，艾登·匹瑞诺德国王与入侵的兽人部落秘密结盟，以保全自己的领土。当洛丹伦联盟发现奥特兰克的叛变后，联盟军队进军这座山地王国，夷平了都城，并对残存地区实行戒严。匹瑞诺德被废黜并遭到唾弃，随后入狱，王国也因此支离破碎、沦为废墟。",al={"奥特兰克城历史","奥特兰克发生了什么","奥特兰克的覆灭"}},fd0078c8={q="奥特兰克废墟有多危险？",a="对毫无准备的人来说极其危险。碎脊食人魔占据了积雪覆盖的街道和破败的大厅，凶狠地抵御任何闯入其领地的人。雪上加霜的是，冷酷无情的辛迪加和游荡的亡灵有时也会出现在废墟中，使山间隘口危机四伏，随时可能遭到伏击。",al={"奥特兰克废墟危险吗","奥特兰克废墟的威胁","奥特兰克城的危险"}},fbcb07c6={q="这个地方为什么叫奥特兰克废墟？",a="此地因曾经矗立于此的人类古王国及城市奥特兰克而得名。王国解体、都城在第二次战争期间遭到严重摧毁后，宏伟的首都只剩下开裂的石墙、破碎的大门和坍塌的高塔，昔日强盛的权力中心就此沦为一片废墟。",al={"为何称为奥特兰克废墟","奥特兰克废墟名称由来"}}},fp="16,213,20.563.0,19.455.0,26.279.0,27.187.0,49.270.0,38.250.0,43.228.0"}
P.entries["subzone:ruins-of-andorhal"] = {n="安多哈尔废墟",s="安多哈尔废墟曾是洛丹伦北部的农业枢纽和粮食集散中心，如今却成了西瘟疫之地腹地一座满目疮痍的大墓地要塞。在巫妖召唤者阿拉基的统治下，这座残破的城镇遍布成群的亡灵憎恶、食尸鬼和怨灵。",h="安多哈尔废墟曾是洛丹伦北部的农业枢纽和粮食集散中心，如今却成了西瘟疫之地腹地一座满目疮痍的大墓地要塞。在巫妖召唤者阿拉基的统治下，这座残破的城镇遍布成群的亡灵憎恶、食尸鬼和怨灵。",kw={"安多哈尔","召唤者阿拉基","克罗米","谷仓","天灾军团","时间寄生虫","西瘟疫之地"},ang={["class:Paladin"]="对于白银之手骑士团和联盟各地的圣骑士来说，安多哈尔是一片沦为梦魇的圣地——正是这里，受污染的谷物毒害了洛丹伦的粮仓，注定了北方王国的覆灭。",["race:Undead"]="被遗忘者旅行者以沉痛的心情看待这座废墟城市：今天许多行走在幽暗城中的人，曾经都是洛丹伦的公民，他们当年都曾食用过从这些周边田地收割的受污染谷物。"},sec={{t="瘟疫之心",b="安多哈尔是亡灵瘟疫在洛丹伦最初的集结地，遭诅咒神教污染的谷物在这里装袋，运往人类王国各地。如今，这座废城已成为天灾军团在西瘟疫之地的一座庞大堡垒。召唤者阿拉基坐镇废墟中央，身旁簇拥着食尸鬼、骷髅恐魔和高大的血肉傀儡。血色十字军的侦察队不时试探城市外围，但天灾军团仍牢牢控制着残破的街道。"},{t="错乱的时间",b="除了亡灵盘踞，安多哈尔还饱受奇异的时间异常困扰。市政厅的大钟和散落街头的废弃怀表，全都永远停在了三点。青铜龙克罗米栖身于废墟边缘的旅店，调查在谷仓内筑巢的时间寄生虫。天灾军团部队似乎正在干扰时间本身的流动，试图改变这座城市悲惨覆灭的时间线。"}},faq={{q="谁统治着安多哈尔废墟？",a="废墟由召唤者阿拉基统治，这名强大的巫妖负责协调天灾军团在这一带的行动。他盘踞在城市中央，周围守卫着由骷髅卫兵和血肉构造体组成的精锐先锋。",al={"谁领导安多哈尔","安多哈尔首领","召唤者阿拉基"}},{q="克罗米为什么在废墟里？",a="克罗米化身为一名女性侏儒，调查时间线中不自然的扰动。她怀疑城市谷仓周围存在干扰，并请旅人协助调查。",al={"克罗米在安多哈尔做什么","克罗米为什么在这里","克罗米 安多哈尔"}},{q="为什么所有的钟表都停在三点？",a="市政厅的大钟和废墟中找到的私人怀表都停在了三点。这可能与安多哈尔的时间扰动有关，但确切原因尚未得到证实。",al={"三点的怀表","安多哈尔钟表停摆","为什么停在三点"}},{q="血色十字军为什么进攻安多哈尔？",a="由血色医护员、猎人和祈求者组成的小股突击队试图潜入城内。狂热的血色十字军力图收复洛丹伦，消灭天灾军团，但他们对防守严密的城市中心发起的突袭很少成功。",al={"安多哈尔的血色十字军","安多哈尔血色巡逻队"}}},fp="17,207,19.428.0,15.413.1,32.177.0,32.180.0,48.176.0,45.197.0"}
P.entries["subzone:ruins-of-constellas"] = {n="克斯特拉斯废墟",s="克斯特拉斯废墟是位于费伍德森林的一处古代暗夜精灵定居点的破碎残迹，坐落在海加尔山脚下。如今，这片曾经神圣的土地已被翡翠之火萨特占领，他们用邪恶的邪能魔法粗暴地亵渎了此地的月亮井。",h="克斯特拉斯废墟是位于费伍德森林的一处古代暗夜精灵定居点的破碎残迹，坐落在海加尔山脚下。如今，这片曾经神圣的土地已被翡翠之火萨特占领，他们用邪恶的邪能魔法粗暴地亵渎了此地的月亮井。",kw={"克斯特拉斯","费伍德森林","翡翠之火","月亮井","萨特","萨瓦里克","萨瓦瑟拉斯"},ang={["class:Druid"]="曾经神圣的月亮井如今却由恶魔照看，克斯特拉斯成为了德鲁伊誓言恢复费伍德森林平衡的一个鲜明提醒。",["race:NightElf"]="克斯特拉斯的亵渎及其受污染的月亮井是对艾露恩的极大冒犯，这要求暗夜精灵必须驱逐翡翠之火萨特。"},sec={{t="亵渎的圣所",b="克斯特拉斯那些古典的石拱门和崩塌的广场显示，这里曾经是一个田园诗般的暗夜精灵社区。第三次战争期间，燃烧军团进军费伍德森林，摧毁了这个避风港，使其暴露在挥之不去的恶魔腐蚀之下。现在，邪恶的翡翠之火萨特统治着这片废墟。在萨瓦瑟拉斯的领导下，他们积极照料着一口被亵渎的月亮井，为了他们的主人萨瓦里克领主，将纯净的井水转化成了散发着邪能之力的毒泉。"},{t="净化的抗争",b="克斯特拉斯的腐化让所有致力于治愈费伍德森林的人感到沉重。对于那些试图净化森林的人来说，萨瓦瑟拉斯和他的翡翠之火是最令人作呕的腐化者之一。萨特们在废墟的营帐中以及处于核心位置的被污染的月亮井旁严加防守，对抗任何试图终结他们恶行的人。"}},faq={{q="被腐化之前的克斯特拉斯是什么样的地方？",a="克斯特拉斯是海加尔山脚下的一处古代暗夜精灵定居点。其建筑风格和月亮井表明，在第三次战争期间燃烧军团入侵森林之前，这里曾是一个致力于供奉艾露恩与自然的宁静林地。",al={"克斯特拉斯历史","克斯特拉斯过去是什么","谁建造了克斯特拉斯"}},{q="现在谁控制着废墟？",a="废墟目前被翡翠之火萨特占据，由萨瓦瑟拉斯在当地负责指挥。在萨瓦里克领主的总体命令下，他们在这片区域培养着恶魔能量。",al={"谁居住在这里","谁统治克斯特拉斯","翡翠之火萨特克斯特拉斯"}},{q="克斯特拉斯的月亮井发生了什么？",a="月亮井被翡翠之火萨特夺取，并被邪能魔法腐蚀。它不再引导艾露恩的抚慰祝福，而是被扭曲成了一个由萨瓦瑟拉斯所培育的、充满邪能的毒源。",al={"费伍德森林受污染的月亮井","克斯特拉斯月亮井","为什么井是绿色的"}},{q="萨瓦里克是谁？",a="萨瓦里克是翡翠之火中另一名残暴的萨特，也是萨瓦瑟拉斯效忠的对象。克斯特拉斯被腐蚀的月亮井就是为了他而培育的。",al={"萨瓦里克","萨瓦瑟拉斯效忠于谁"}}},fp="19,141,19.385.0,26.269.0,42.218.0,27.135.0,44.176.0,15.127.0"}
P.entries["subzone:ruins-of-eldarath"] = {n="埃达拉斯废墟",s="埃达拉斯废墟是位于艾萨拉崎岖峭壁上的一座上古之战前的上层精灵城市，如今已是残垣断壁。它曾是卡多雷奥术研究的堡垒，而现在，它那坍塌的广场和破败的神殿已被充满敌意的纳迦所占据。学者和冒险者们勇敢地深入这片危险的海岸废墟，寻找着古代刻写的石板和遗失的远古圣物。",h="埃达拉斯废墟是位于艾萨拉崎岖峭壁上的一座上古之战前的上层精灵城市，如今已是残垣断壁。它曾是卡多雷奥术研究的堡垒，而现在，它那坍塌的广场和破败的神殿已被充满敌意的纳迦所占据。学者和冒险者们勇敢地深入这片危险的海岸废墟，寻找...",kw={"艾萨拉","艾索雷葛斯","埃达拉斯","探险者协会","上层精灵","卡多雷","纳迦","大分裂","石板"},ang={["class:Mage"]="埃达拉斯是一个神圣但又充满警示意义的研究场所：散布在广场上的石板记载了最有天赋的上层精灵法师在帝国覆灭前刻下的奥术基础理论。",["race:NightElf"]="这些被阳光晒白的废墟是对上层精灵傲慢和大分裂的痛苦提醒，它们长期被现代卡多雷所回避，如今又遭到了扭曲的纳迦的亵渎。"},sec={{t="破碎的上层精灵堡垒",b="在一万年前大分裂彻底摧毁古代卡利姆多之前，埃达拉斯曾是一座繁荣的暗夜精灵城市。著名的上层精灵法师们曾聚集于此，将他们最深奥的奥术见解和基础魔法准则刻在大型石板上，放置在公共广场供同僚们研习。大分裂使埃达拉斯的大部分沉入了风暴海湾。残留在东部悬崖上的部分在数千年来一直被现代暗夜精灵所摒弃，逐渐被蔓延的海盐喷雾和常春藤所侵蚀。"},{t="纳迦的统治与遗忘的圣物",b="近来，凶残的纳迦从海中涌出，夺取了埃达拉斯残破的街道，并在辛玛洛神殿等附近的圣所中由潜伏的军阀指挥。尽管蛇人构成了威胁，但废墟对外界来说仍然有着不可抗拒的吸引力。探险者协会已经派遣联盟冒险者进入断壁残垣的庭院，拓印埃达拉斯古老的奥术石板。关于失落宝藏和残留奥术能量的传言也吸引了蓝龙艾索雷葛斯来到周边的荒野，这进一步证实了巨大的力量之秘仍沉睡在废墟的碎石板之下。"}},faq={{q="埃达拉斯在化为废墟之前是什么样子？",a="在一万年前的大分裂之前，埃达拉斯是一座由上层精灵居住的宏伟暗夜精灵城市。在世界大分裂将其摧毁之前，它曾是奥术研究的中心和坚固的避风港。",al={"埃达拉斯是什么","埃达拉斯历史","埃达拉斯起源"}},{q="如今谁在控制埃达拉斯废墟？",a="充满敌意的纳迦已经彻底占领了这片废墟，利用坍塌的广场和附近的建筑（如辛玛洛神殿）作为海岸据点，并在像克雷利安军阀这样的头目指挥下进行活动。",al={"谁住在埃达拉斯","埃达拉斯里有什么","埃达拉斯怪物"}},{q="为什么学者和探险者要前往埃达拉斯？",a="学者们致力于寻找古代上层精灵法师留下的保存完好的石板。这些公共标记包含了奥术魔法的基础准则和失传已久的研究，其价值之高，使得矮人探险者协会等组织派遣侦察兵去获取这些文本的拓片。",al={"为什么要前往埃达拉斯","埃达拉斯任务","埃达拉斯有什么"}},{q="为什么蓝龙艾索雷葛斯会在废墟附近徘徊？",a="艾索雷葛斯被艾萨拉海岸边残留的极高浓度的远古奥术能量所吸引。有传言称，大分裂之前的强大圣物——甚至可能包括接触过远古永恒之井的瓶子——仍然隐藏在废墟之中或周围。",al={"为什么艾索雷葛斯在这里","艾索雷葛斯埃达拉斯","艾萨拉的蓝龙"}}},fp="17,210,29.503.0,30.517.0,44.209.0,41.191.0,49.225.0,55.235.0"}
P.entries["subzone:ruins-of-isildien"] = {n="伊斯迪尔废墟",s="伊斯迪尔废墟是菲拉斯西南部一座古老的暗夜精灵城市的庞大遗迹，在一万年前的大分裂期间被摧毁。如今，那些杂草丛生的石造建筑和开裂的神殿庭院已被残暴的戈杜尼食人魔所占据。",h="伊斯迪尔废墟是菲拉斯西南部一座古老的暗夜精灵城市的庞大遗迹，在一万年前的大分裂期间被摧毁。如今，那些杂草丛生的石造建筑和开裂的神殿庭院已被残暴的戈杜尼食人魔所占据。",kw={"艾露恩","菲拉斯","戈杜尼","伊斯迪尔","卡多雷","食人魔","大分裂","月神殿"},ang={["class:Priest"]="位于顶部的宏伟圆形大厅与艾露恩的高级圣所建筑布局相同，回荡着一万年前向白夫人献上的祈祷声。",["race:NightElf"]="走在伊斯迪尔，不仅能让人回想起分裂前帝国那令人痛苦的辉煌高度，如今它已沦为废墟，并被野蛮的戈杜尼食人魔所亵渎。"},sec={{t="一座陨落的卡多雷城市",b="一万年前，在世界破碎之前，伊斯迪尔是坐落在古代卡利姆多原始森林中的一座宏伟的暗夜精灵定居点。它优雅的大理石拱门和宏伟的露台曾是卡多雷文明和信仰的纪念碑。当永恒之井崩塌并将大陆撕裂时，伊斯迪尔陷入了荒废，被数千年来野蛮生长的丛林所覆盖。主宰着上层露台的是一座巨大的圆顶建筑，与达纳苏斯的月神殿惊人地相似，这表明这座城市曾经是一处供奉艾露恩的重要圣所。"},{t="戈杜尼要塞",b="在现代，伊斯迪尔优雅的石造建筑被用于远为粗鄙的用途。菲拉斯的戈杜尼食人魔已将这些庞大的露台和岩层据为己有，作为他们的主要定居点之一。食人魔加固了摇摇欲坠的走道，用粗糙的篝火、原始的障碍物和战旗亵渎了古老的广场，凶猛地保卫着他们窃取的家园，抵御任何胆敢靠近南部山丘的外来者。"}},faq={{q="伊斯迪尔最初是什么？",a="伊斯迪尔是一座重要的大型暗夜精灵城市，建于一万年前大分裂之前。在灾变使其成为废墟之前，它拥有宏大的石砌广场、多层露台和显赫的神殿。",al={"什么是伊斯迪尔","伊斯迪尔历史","谁建造了伊斯迪尔"}},{q="现在是谁控制着伊斯迪尔废墟？",a="这些废墟已被戈杜尼食人魔占领并加固，他们利用破败的大理石大厅和天然的地理优势，将其作为在菲拉斯南部的一处要塞。",al={"谁住在伊斯迪尔","伊斯迪尔的敌人","伊斯迪尔的食人魔"}},{q="楼梯顶部的大型圆形亭子是什么？",a="那座显眼的圆形亭子在建筑结构上与达纳苏斯的月神殿极为相似，这有力地表明上面的高台曾经是供奉艾露恩的圣洁殿堂。",al={"伊斯迪尔神殿","伊斯迪尔的圆形建筑","菲拉斯的艾露恩神殿"}},{q="废墟里有什么隐藏的东西吗？",a="在废墟东侧的悬崖上嵌有一个洞穴，当地的食人魔除了利用北部和南部的分散石质露台外，也会使用这个洞穴。",al={"伊斯迪尔洞穴","伊斯迪尔的秘密"}}},fp="17,162,29.471.0,23.315.0,29.164.0,39.152.0,61.135.0,42.148.0"}
P.entries["subzone:ruins-of-jubuwal"] = {n="朱布瓦尔废墟",s="朱布瓦尔废墟是古拉巴什帝国古老定居点的残垣断壁，位于荆棘谷的古拉巴什竞技场以东。这里曾是帝国和举行仪式的场所，如今却已被流亡巫医赞吉尔及其稀奇古怪的爪牙所控制。",h="朱布瓦尔废墟是古拉巴什帝国古老定居点的残垣断壁，位于荆棘谷的古拉巴什竞技场以东。这里曾是帝国和举行仪式的场所，如今却已被流亡巫医赞吉尔及其稀奇古怪的爪牙所控制。",kw={"古拉巴什","琼琼","朱布瓦尔","麦金利","瘸腿莫里","荆棘谷","赞吉尔"},ang={["class:Rogue"]="朱布瓦尔的阴影和破碎的砖石建筑为躲避来自藏宝海湾的赏金猎人的逃犯提供了绝佳的掩护。",["race:Troll"]="对于暗矛巨魔来说，朱布瓦尔既代表了古拉巴什文明悲剧性的崩溃，也代表了像赞吉尔这样的恶棍对祖传巫毒法术的扭曲和亵渎。"},sec={{t="流亡者的避难所",b="朱布瓦尔坐落在穿过荆棘谷的主干道旁，曾是宏伟的古拉巴什文明的一部分。如今，这里的石刻和藤蔓缠绕的砖石建筑已被赞吉尔占据。这位古怪的巫医以其强大的药剂和邪恶的巫毒法术而闻名。赞吉尔在废墟中聚集了一群非自然的追随者，包括被奴役的食尸鬼、被征服的纳迦以及背叛的巨魔。在石拱门之间还潜伏着绝望的逃亡者，例如“乌鸦”琼琼和“瘸腿”莫里，他们都是为了躲避藏宝海湾那位冷酷无情的债务催收人“海狼”麦金利而藏匿于此。"}},faq={{q="朱布瓦尔废墟在哪里？",a="这些废墟位于荆棘谷中部，古拉巴什竞技场以东，紧邻连接荆棘谷北部和南部的主要土路。",al={"朱布瓦尔废墟位置","朱布瓦尔在哪","朱布瓦尔地图"}},{q="谁控制着朱布瓦尔废墟？",a="废墟由流亡者赞吉尔及其爪牙把持。他那折中主义的追随者包括被洗脑的巨魔、复活的食尸鬼、结盟的纳迦以及各类寻求庇护以逃避外界法律制裁的恶棍。",al={"朱布瓦尔的居民","朱布瓦尔敌人","谁控制朱布瓦尔"}},{q="为什么食尸鬼和纳迦会在这里合作？",a="流亡者赞吉尔使用有毒的巫毒混合物和致幻药剂来征服并指挥周围的人。通过这些混合药剂，他将复活的亡灵、纳迦和巨魔束缚成一支听命于他的战斗力量。",al={"朱布瓦尔的食尸鬼","赞吉尔的爪牙"}},{q="为什么像琼琼和莫里这样的逃犯要躲在这里？",a="“乌鸦”琼琼和“瘸腿”莫里都逃到了朱布瓦尔，以躲避臭名昭著的债务催收人“海狼”麦金利的愤怒，麦金利就在藏宝海湾活动。",al={"乌鸦琼琼","瘸腿莫里","麦金利的债务人"}}},fp="16,136,23.522.0,39.166.0,34.161.0,46.183.0,51.150.0"}
P.entries["subzone:ruins-of-kel-theril"] = {n="凯斯利尔废墟",s="凯斯利尔废墟是古老暗夜精灵城市留下的破碎残骸，坐落于冬泉谷中心地带的凯斯利尔湖冰封湖畔。这座城市在万年前的大分裂中被摧毁，其冰冻的石柱和神庙至今仍被在大灾变中丧生的上层精灵那痛苦的灵魂所萦绕。",h="凯斯利尔废墟是古老暗夜精灵城市留下的破碎残骸，坐落于冬泉谷中心地带的凯斯利尔湖冰封湖畔。这座城市在万年前的大分裂中被摧毁，其冰冻的石柱和神庙至今仍被在大灾变中丧生的上层精灵那痛苦的灵魂所萦绕。",kw={"幽灵","上层精灵","凯斯利尔","凯斯利尔湖","废墟","大分裂","冬泉谷"},ang={["class:Mage"]="探索废墟的法师们会感受到那些古老而沉寂的奥术能量，这些能量曾经支撑着卡利姆多在大分裂前最引以为傲的魔法城市之一。",["race:NightElf"]="对于暗夜精灵来说，凯斯利尔是一个庄严的提醒，警示着古老上层精灵阶级的傲慢，以及他们因肆意使用奥术魔法所造成的可怕破坏。"},sec={{t="破碎的遗产",b="早在冬泉谷变成冰封高地之前，凯斯利尔曾是古老暗夜精灵帝国的一座宏伟定居点。当永恒之井在大分裂期间崩塌时，这座城市被炸成废墟，并埋葬在冰雪之下。这场灾难让当时居住于此的上层精灵猝不及防，将他们的灵魂束缚在冰冷的岩石上。如今，这些昔日施法者的灵魂徘徊在冰封的拱门之间，无休止地重温着他们生命中那灾难般的最后时刻。"},{t="雪中的回响",b="勇闯冬泉谷中心的旅行者经常会遇到在废墟湖畔游荡的、不安的幽灵上层精灵。这些幻影通常带有敌意，被数千年的孤独和撕裂了他们文明的狂暴魔法逼至疯狂。然而，少数悲伤的幽灵，例如悔恨的上层精灵，会寻找愿意倾听他们长久哀鸣并抚平他们被遗忘的往事的旅行者。"}},faq={{q="凯斯利尔城发生了什么事？",a="凯斯利尔在万年前的大分裂期间被摧毁。当永恒之井内爆并撕裂了古老的卡利姆多大陆时，这座城市坍塌成了瓦砾，并被随后笼罩冬泉谷的突如其来的严寒所吞没。",al={"凯斯利尔历史","凯斯利尔为何荒废","凯斯利尔如何陷落"}},{q="什么灵魂萦绕着这些废墟？",a="这些废墟被在大分裂中丧生的上层精灵暗夜精灵的幽灵所萦绕。他们的灵魂依然被束缚在倒塌的石头上，在痛苦中挣扎，徘徊在凯斯利尔湖的雪地边缘。",al={"凯斯利尔幽灵","谁在凯斯利尔游荡","凯斯利尔亡灵"}},{q="你能与这些幽灵交谈吗？",a="虽然大多数徘徊的灵魂都充满敌意且陷入疯狂，但在废墟中仍能找到一个孤独的悔恨的上层精灵，他愿意与那些试图了解这里悲惨往事的联盟旅行者交谈。",al={"友好的凯斯利尔幽灵","悔恨的上层精灵","凯斯利尔幽灵任务"}},{q="废墟位于何处？",a="凯斯利尔废墟位于凯斯利尔湖的岸边，这是一座坐落在冬泉谷中心地带的冰封湖泊。",al={"凯斯利尔位置","凯斯利尔在哪里","寻找凯斯利尔"}}},fp="19,225,18.372.0,18.331.0,40.206.0,31.208.0,37.207.0,28.74.0"}
P.entries["subzone:ruins-of-lordaeron"] = {n="洛丹伦废墟",s="洛丹伦废墟是王都地表上留下的残骸，这里曾是人类北方帝国光辉荣耀的核心。当阿尔萨斯王子弑父并释放天灾军团后，这里便遭到了毁灭，如今那被摧毁的庭院和大厅已成为下方幽暗城的防御门户。",h="洛丹伦废墟是王都地表上留下的残骸，这里曾是人类北方帝国光辉荣耀的核心。当阿尔萨斯王子弑父并释放天灾军团后，这里便遭到了毁灭，如今那被摧毁的庭院和大厅已成为下方幽暗城的防御门户。",kw={"阿尔萨斯","王都","闹鬼","洛丹伦","宫殿","天灾军团","希尔瓦娜斯","泰瑞纳斯","大厅","幽暗城"},ang={["race:Human"]="站在这座大厅里，是对人类历史上最大背叛的痛苦提醒，阿尔萨斯王子摧毁了洛丹伦联盟，并将人类的明珠交到了亡者手中。",["race:Undead"]="这些破败的城墙是你的祖居之地。曾经孕育你的生者王国如今已成为守护幽暗城和女妖之王的圣地门户。"},sec={{t="陨落帝国的门户",b="王都曾是人类文明璀璨的巅峰，在泰瑞纳斯·米奈希尔二世国王的统治下统一了北方诸国。当阿尔萨斯王子带着被诅咒的符文剑“霜之哀伤”从诺森德归来时，庆祝仪式变成了屠宰场。阿尔萨斯在王座上杀死了他的父亲，这座大都市随之在天灾军团的统治下腐朽。在分裂天灾军团的内战之后，希尔瓦娜斯·风行者占据了这座被摧毁的宫殿，在巩固地表防御的同时，将下方的地窖和地下城扩建为幽暗城。"},{t="背叛的回响",b="宫殿废墟因那场暴力的陷落而留下了心灵创伤。路过入口和庭院的旅行者常会听到庆祝钟声的幽灵回响、欢呼人群的低语，以及阿尔萨斯在弑父前与国王那令人毛骨悚然的对话。大厅的地面上仍留有血迹，而那些拥有魔法感知能力的人，可以看到幽灵般的市民在不断重现王子断送他们生命的那天下午。"}},faq={{q="为什么我在穿过入口时会听到钟声和低语？",a="泰瑞纳斯国王及其城市的突然屠杀在这些石头上留下了心灵印记。任何穿过外门和残破大厅的人都能听到跨越时空的幽灵钟声、虚幻的欢呼声，以及泰瑞纳斯与阿尔萨斯之间的最后对话。",al={"洛丹伦诡异声音","大厅低语","闹鬼城堡声音"}},{q="如今是谁统治着这些废墟？",a="地表废墟由希尔瓦娜斯·风行者麾下的被遗忘者所占据和巡逻。尽管希尔瓦娜斯和她的廷臣居住在下方的幽暗城中，但上方的废墟仍是通往她地下国度的宏伟要塞入口。",al={"谁拥有洛丹伦废墟","谁控制洛丹伦废墟"}},{q="曾经居住在这里的人们发生了什么？",a="大多数居民在阿尔萨斯向城市释放天灾军团时被屠杀。许多人被复活为无脑的亡灵，后来挣脱束缚加入了希尔瓦娜斯成为被遗忘者，而另一些人的无形之魂依然在宫殿庭院中游荡。",al={"洛丹伦人民去了哪里","王都人类发生了什么"}},{q="大厅里的黑色污渍是什么？",a="标记在王座台阶上的深色干燥残留物是泰瑞纳斯·米奈希尔二世国王的鲜血，当王子将霜之哀伤刺入他心口时，这些鲜血从他体内流出。",al={"大厅地板上的血迹","洛丹伦大厅的污渍"}}},fx={d8b1c653={q="洛丹伦废墟是什么地方？",a="这些破碎的城墙和宏伟大厅，是首都城仅存的遗迹。首都城曾是已覆灭的人类王国洛丹伦的壮丽中心，也是第二次战争期间联盟的核心。王子阿尔萨斯·米奈希尔背叛王国、释放天灾军团后，这座城市便陷入崩塌。如今，地表宫殿已破败不堪、阴魂不散，成为通往庞大的被遗忘者地下都市——幽暗城的入口。",al={"洛丹伦废墟是什么","洛丹伦废墟概况","首都城废墟传说"}},b22541a4={q="洛丹伦为何沦为废墟？",a="洛丹伦毁于内部的背叛。王储阿尔萨斯·米奈希尔被受诅咒的霜之哀伤腐化后，以巫妖王的旗号从诺森德归来。他杀死父亲泰瑞纳斯国王后，与他的亡灵天灾军团屠杀了城中居民，摧毁了城市的防御。此后，恐惧魔王、幸存的联盟抵抗军以及希尔瓦娜斯·风行者领导的被遗忘者之间的冲突，彻底毁掉了这座地表城市。",al={"洛丹伦为何被毁","洛丹伦是如何被毁的","洛丹伦为何沦为废墟"}},e6ebc4a5={q="洛丹伦废墟危险吗？",a="对部落勇士而言，地表废墟十分安全，被遗忘者卫兵会巡逻庭院以及通往幽暗城的通道。然而，联盟旅者会发现这里敌意十足，到处都是被遗忘者哨兵。此地也阴气沉沉，回荡着悲惨的幽灵低语和被屠杀居民的无形鬼魂；周围的提瑞斯法林地还有邪恶的天灾生物和野兽四处出没。",al={"洛丹伦废墟的危险","洛丹伦废墟安全吗","洛丹伦废墟是否敌对"}},["39a2d118"]={q="为什么称为洛丹伦废墟？",a="此地最初是首都城，是洛丹伦王国的宏伟中心。天灾军团彻底毁灭王国并屠杀其人民后，只剩下开裂的大理石墙、破碎的王座大厅和坍塌的庭院。这个名称旨在铭记人类北方最强大王国昔日的辉煌及其悲惨覆灭。",al={"洛丹伦废墟名称由来","为何称为洛丹伦废墟","洛丹伦废墟名称从何而来"}}},fp="18,226,25.480.0,18.396.0,67.234.0,26.191.0,50.241.0,42.153.0"}
P.entries["subzone:ruins-of-mathystra"] = {n="玛塞斯特拉废墟",s="玛塞斯特拉废墟是一座古老暗夜精灵城市的残垣断壁，坐落于黑海岸的北岸。这座沿海废墟在一万年前的大分裂中被摧毁，如今已被充满敌意的风鳞娜迦所占据，并有难以捉摸的幽灵豹在此潜行。",h="玛塞斯特拉废墟是一座古老暗夜精灵城市的残垣断壁，坐落于黑海岸的北岸。这座沿海废墟在一万年前的大分裂中被摧毁，如今已被充满敌意的风鳞娜迦所占据，并有难以捉摸的幽灵豹在此潜行。",kw={"黑海岸","幽灵豹","大分裂","上层精灵","玛塞斯特拉","娜迦","玛塞斯特拉废墟","风鳞"},ang={["class:Hunter"]="在玛塞斯特拉的瓦砾中潜行的半透明幽灵豹，对于追求与灵魂世界有联系且外形引人注目的伙伴的兽王猎人来说，是著名的野兽。",["race:NightElf"]="玛塞斯特拉是古老上层精灵傲慢的阴沉纪念碑，他们鲁莽的魔法为自己宏伟的沿海定居点带来了毁灭性的灾难。"},sec={{t="一座沉入海底的城市",b="一万年前，玛塞斯特拉曾是一处繁华的暗夜精灵定居点，也是高阶上层精灵贵族的家园。当永恒之井在大分裂期间崩塌时，灾难性的巨浪摧毁了这座沿海城市，推倒了宏伟的大理石拱门，并将大部分石建筑冲入了海中。幸存的暗夜精灵放弃了这座残破的城市，转而前往更南方的林地村庄居住，将玛塞斯特拉沉没的庭院和破裂的地基留给了无情的海岸风化。"},{t="风鳞毒蛇与幽灵豹",b="在现代，玛塞斯特拉已成为风鳞娜迦统治的危险领地。这些蛇形怪物从深暗的海底爬出，凶狠地守卫着破碎的厅堂，驱逐任何越过奥萨拉克斯之塔向北冒险的旅行者。在破碎的石板间，古老的上层精灵遗物依然半埋在沙砾与海沫中。大胆的年轻暗夜精灵有时会冒着生命危险闯入娜迦的地盘，希望能寻回他们失落的遗产。他们不仅要面对蛇人的利刃，还要应对潜伏在破败街道上的幽灵豹。"}},faq={{q="在废墟之前这里是什么？",a="玛塞斯特拉是一座繁荣的暗夜精灵城市，兴建于古老上层精灵帝国鼎盛时期。一万年前，当永恒之井爆炸并撕裂卡利姆多大陆的大分裂期间，这座城市被摧毁并大部沉入水中。",al={"玛塞斯特拉历史","谁建造了玛塞斯特拉","玛塞斯特拉是什么"}},{q="现在是谁控制着玛塞斯特拉废墟？",a="这片废墟目前被风鳞娜迦占据，它们从海中涌出，占据了沉没的亭台楼阁和海岸线。它们会猛烈攻击任何侵入其领地的陆地居民。",al={"谁住在玛塞斯特拉","玛塞斯特拉怪物","玛塞斯特拉有哪些人"}},{q="什么是幽灵豹？",a="幽灵豹是一种虚幻且半透明的猫科生物，徘徊在玛塞斯特拉的残垣断壁间。猎人们经常在海岸边寻找它们，不过据称干扰该地区的古代雕像会将这些灵魂从阴影中引出。",al={"玛塞斯特拉幽灵豹","黑海岸发光的猫","幽灵豹"}},{q="为什么暗夜精灵今天会造访这些废墟？",a="年轻的暗夜精灵和学者偶尔会冒险进入废墟，寻找大分裂后遗留下的古代上层精灵遗物。然而，凶猛的风鳞娜迦的存在使得找回这些历史珍宝变得异常危险。",al={"玛塞斯特拉遗物","为什么要前往玛塞斯特拉"}}},fp="18,196,24.386.0,38.337.0,38.240.0,46.152.0,22.198.0,43.159.0"}
P.entries["subzone:ruins-of-ordil-aran"] = {n="奥迪拉兰废墟",s="奥迪拉兰废墟是位于灰谷西北部的一处古老暗夜精灵定居点的残垣断壁，坐落在迈斯特拉岗哨和巴斯兰鬼屋之间。这里曾是暗影教徒的隐秘堡垒，但如今这些倾颓的石块已被腐化的蓟皮熊怪占据。",h="奥迪拉兰废墟是位于灰谷西北部的一处古老暗夜精灵定居点的残垣断壁，坐落在迈斯特拉岗哨和巴斯兰鬼屋之间。这里曾是暗影教徒的隐秘堡垒，但如今这些倾颓的石块已被腐化的蓟皮熊怪占据。",kw={"灰谷","暗滩教派","心木","迈斯特拉岗哨","奥迪拉兰","废墟","蓟皮熊怪"},ang={["faction:Alliance"]="奥迪拉兰的那些好战占据者位于迈斯特拉岗哨以北，威胁着前往黑海岸的联盟侦察兵和旅行者。",["race:NightElf"]="这些废墟是卡利姆多帝国崩溃的又一个痛苦缩影，如今又遭到了腐化的熊怪和黑暗教徒的玷污。"},sec={{t="一处争议废墟",b="奥迪拉兰只剩下少量最初的卡多雷建筑，仅存风化的石柱、开裂的拱门和布满青苔的石雕。这片孤立的废墟曾一度成为暗滩教派的巢穴，他们潜伏在瓦砾之中，伏击灰谷西北道路上的旅行者。然而最近，凶残的蓟皮熊怪部落通过一场血腥的夺取行动将教徒们赶了出去。暗滩教派成员的尸体横尸遍地，而好战的熊怪则在四周巡逻，严密守卫着这处遗迹和生长在其中的古老心木。"}},faq={{q="奥迪拉兰最初是什么地方？",a="奥迪拉兰是一处大分裂之前的古老暗夜精灵定居点。和灰谷中许多其他的卡多雷前哨站一样，它在漫长的岁月中逐渐荒废，只留下了杂草丛生的石拱门和摇摇欲坠的砖石。",al={"奥迪拉兰历史","奥迪拉兰是什么","谁建造了奥迪拉兰"}},{q="为什么废墟里有死去的教徒？",a="暗滩教派此前曾将这些废墟用作行动基地。蓟皮熊怪发动了猛烈攻击并驱逐了他们，占领了这片废墟，留下了横尸遍地的教徒。",al={"死去的教徒","暗滩教派尸体","为什么教徒死在这里"}},{q="什么是心木？",a="心木是一棵生长在奥迪拉兰废墟内独特的古树。它的枝干和木材因其强大的魔法和自然属性而备受追捧。",al={"心木","心木任务","奥迪拉兰心木"}},{q="谁目前控制着这些废墟？",a="好战的蓟皮熊怪目前占据着这些废墟，他们杀死了或驱逐了之前居住在此处的暗滩教派教徒。",al={"谁住在这里","奥迪拉兰有什么人","奥迪拉兰怪物"}}},fp="19,168,16.408.0,31.200.0,51.149.0,23.155.0,33.115.0"}
P.entries["subzone:ruins-of-ravenwind"] = {n="鸦风废墟",s="鸦风废墟是坐落在菲拉斯北部的一座古代上层精灵城市的破碎遗迹。如今，这些摇摇欲坠的大理石建筑被凶残的北泉鹰身人所占据，并由沉思的龙人所守卫。",h="鸦风废墟是坐落在菲拉斯北部的一座古代上层精灵城市的破碎遗迹。如今，这些摇摇欲坠的大理石建筑被凶残的北泉鹰身人所占据，并由沉思的龙人所守卫。",kw={"羽月","菲拉斯","鹰身人","上层精灵","加德米尔","北泉","鸦风"},ang={["faction:Alliance"]="像羽月要塞这样的前哨站密切关注着鸦风废墟，并派遣勇敢的侦察兵去回收强大的魔法遗物，以免它们被野兽或更黑暗的力量所吞噬。",["race:NightElf"]="对于卡多雷而言，这些遗迹痛苦地提醒着他们，那个鲁莽的奥术帝国曾将古老的卡利姆多撕裂，而如今这里又被鹰身人和野兽所亵渎。"},sec={{t="上层精灵的回响",b="就像东部的宏伟城市厄运之槌一样，鸦风废墟是古代上层精灵文明在天崩地裂前达到巅峰与傲慢的庄严纪念碑。这处遗址早已被其最初的卡多雷建造者所遗弃，如今已沦为蔓生的野生植被、被遗忘的奥术祭坛以及北泉鹰身人巢穴的栖息地，这些鹰身人捕食着任何在破碎拱门下徘徊的生物。"},{t="野生危险的汇聚点",b="除了尖啸的鹰身人之外，鸦风废墟周边还存在着各种各样的领地威胁。被称为“加德米尔”的凶猛绿龙人盘旋在中央树林和水道上空，守护着古老的树木遗迹。与此同时，流浪的过客——从心不在焉的暗夜精灵探险家到附近徘徊的奇怪而孤独的豺狼人——经常发现自己陷入了遗迹残留的魔法和野生掠食者的交火之中。"}},faq={{q="是谁建造了鸦风废墟？",a="该定居点由数千年前的卡多雷文明贵族阶层——上层精灵所建造。在天崩地裂之后，它和厄运之槌以及菲拉斯各地的其他精灵古迹一样，沦为了废墟。",al={"谁建造了鸦风","鸦风历史","鸦风废墟起源"}},{q="目前是什么生物盘踞在废墟中？",a="废墟被北泉鹰身人所充斥，这些野蛮的鸟形野兽在破碎的石料间筑巢。此外，加德米尔龙人潜伏在周围的水域和中央树林中，凶猛地守卫着当地的植被。",al={"鸦风怪物","鸦风住着什么","鸦风鹰身人"}},{q="联盟为何要前往该地区？",a="驻扎在羽月要塞的联盟学者和哨兵派遣冒险者前往此地，发掘失落的奥术遗物，并与古老的祭坛互动，从而为艾奎尼克斯法杖等强大的神器充能。",al={"联盟鸦风任务","羽月鸦风"}}},fp="18,154,23.317.0,28.308.0,33.196.0,33.176.0,38.192.0"}
P.entries["subzone:ruins-of-stardust"] = {n="星尘废墟",s="星尘废墟是一座古老而破败的暗夜精灵圣所，坐落在灰谷西南部的一座湖心岛上。这里曾经是一处宁静的礼拜场所，但岛上的湖水和原生的沼泽兽却受到了从费伍德森林冲刷而下的恶魔腐蚀。尽管这种破坏无处不在，但发光的星尘灌木依然在残垣断壁间茁壮成长，保留着强大的恢复力量。",h="星尘废墟是一座古老而破败的暗夜精灵圣所，坐落在灰谷西南部的一座湖心岛上。这里曾经是一处宁静的礼拜场所，但岛上的湖水和原生的沼泽兽却受到了从费伍德森林冲刷而下的恶魔腐蚀。尽管这种破坏无处不在，但发光的星尘灌木依然在残垣断壁...",kw={"灰谷","沼泽兽","费伍德腐蚀","暗夜精灵废墟","星尘废墟","星尘灌木","水体腐蚀"},ang={["class:Shaman"]="在这里发现的未受腐蚀的星尘是精神试炼中的重要净化试剂，包括掌握恢复元素的关键试炼“水之召唤”。",["race:NightElf"]="看着这座曾经的圣所屈服于费伍德森林缓慢而腐烂的径流，这令人痛苦地提醒着人们，保护灰谷免受持续恶魔腐蚀的斗争仍在继续。"},sec={{t="一处被荒废的圣所",b="星尘废墟位于阿斯特兰纳南部的孤岛上，曾经是受人尊敬的暗夜精灵圣地。如今，一种怪异、病态的黄绿色调笼罩在水面上——这是从费伍德森林向南流下的恶魔腐臭造成的后果，就像附近的伊瑞斯湖一样。当地的植物已经扭曲成了敌对的沼泽兽，在倒塌的石砌建筑间徘徊，它们的性情也因这片受污染的湖水而变得狂暴。"},{t="不朽的星尘",b="尽管土壤和海岸线充斥着腐蚀，但这座岛屿仍拥有一种不屈的韧性。星尘灌木散布在废墟之中，绽放着未被恶魔污染的花朵。它们的叶片和花朵具有非凡的净化和治疗功效，吸引了寻求对抗灰谷不断蔓延的腐朽之法的萨满、草药师和当地的暗夜精灵保卫者。"}},faq={{q="星尘废墟最初的用途是什么？",a="在古代，这个地方是暗夜精灵照料的神圣土地。早在恶魔腐蚀在这个森林中扎根之前，这里经典的在大理石柱和湖畔环境就是一处宁静的崇拜之地。",al={"什么是废墟","星尘背景故事","谁建造了星尘"}},{q="为什么岛屿周围的水变色了？",a="恶魔腐蚀从费伍德森林那受损的山峰渗透到灰谷的水道中，污染了湖水，使水体呈现出浑浊的黄绿色，并破坏了自然平衡。",al={"为什么水是绿色的","为什么湖泊被腐蚀了","星尘之水"}},{q="是什么让星尘灌木如此特别？",a="尽管生长在浸透了恶魔径流的土壤中，星尘灌木依然保持着完全的纯净。它们抵御了环境污染，并拥有非凡的恢复和治疗特性，使它们成为净化仪式中极具价值的试剂。",al={"什么是星尘灌木","星尘植物","星尘灌木丛"}},{q="有什么生物在废墟中游荡？",a="岛上到处都是大型、被腐蚀的沼泽兽。湖泊受污染的水将这些自然元素生物从宁静的森林守护者变成了对任何穿越浅滩的人具有攻击性的沉重威胁。",al={"星尘怪物","这里有什么怪物","沼泽兽"}}},fp="17,178,20.357.0,21.262.0,52.190.0,46.171.0,39.162.0,32.184.0"}
P.entries["subzone:ruins-of-thaurissan"] = {n="索瑞森废墟",s="索瑞森废墟是黑铁部族最初在燃烧平原上的地表首都留下的焦黑残骸。它曾是一座坐落在赤脊山北部郁郁葱葱的崇山峻岭中的辉煌城市，但在三锤之战中，当大巫师索瑞森无意间召唤出炎魔拉格纳罗斯时，这座城市化为了一片灰烬。",h="索瑞森废墟是黑铁部族最初在燃烧平原上的地表首都留下的焦黑残骸。它曾是一座坐落在赤脊山北部郁郁葱葱的崇山峻岭中的辉煌城市，但在三锤之战中，当大巫师索瑞森无意间召唤出炎魔拉格纳罗斯时，这座城市化为了一片灰烬。",kw={"阿克瑟努斯","燃烧平原","黑铁部族","拉格纳罗斯","索瑞森废墟","大巫师","索瑞森","三锤之战"},ang={["faction:Alliance"]="在铁炉堡皇家历史学家阿克瑟努斯的委托下，联盟的侦察兵和研究人员搜寻着这些仍在冒烟的地基，寻找揭示黑石山主人真相的遗物。",["race:Dwarf"]="对于铁炉堡的矮人来说，这些废墟是一座严酷的纪念碑，记录着黑铁部族在三锤之战中的傲慢，以及召唤元素力量所付出的惨痛代价。"},sec={{t="一个王国的覆灭",b="大约两个世纪前，在至高王莫迪姆斯·安威玛尔死后，黑铁部族被驱逐出铁炉堡，随后他们向南迁徙并建立了索瑞森城。在三锤之战的最紧要关头，面对铜须部族和蛮锤部族联军的全面围攻，大巫师索瑞森试图寻找一种终极武器来扭转局势。他与七名心腹法师深入地下，引导古老的魔法。他们的仪式并没有召唤出一个顺从的仆人，反而撕裂了一条通往元素位面的通道，并召唤出了炎魔拉格纳罗斯。这场灾难性的喷发震碎了周围的山脉，将翠绿的土地烧成了灰烬弥漫的燃烧平原，隆起了黑石山的火山，并将城市化为焦土。"},{t="灰烬中的回响",b="今天，破碎的砖石和倒塌的柱子散落在荒原上，这里盘踞着巡逻的黑铁部族残党和火元素。在铁炉堡皇家历史学家阿克瑟努斯的指引下，联盟派遣了探险队来发掘埋藏在灰烬下的古代遗物。触碰这些被附魔的遗物，会让人感受到那场灾难中鲜活而恐怖的记忆：八名矮人在绝望中吟唱的幻象、七具尸体散落在一名独自跪地的法师周围，以及一座巍峨的原始烈焰巨碑，它夺走了整个部族的灵魂与自由。"}},faq={{q="索瑞森城在被摧毁前是什么地方？",a="那是索瑞森城，黑铁部族引以为傲的地表首都。在至高王莫迪姆斯·安威玛尔死后，他们被驱逐出铁炉堡并建立了这座城市，在它彻底毁灭之前，这里曾是他们新兴王国的中心。",al={"索瑞森城背景","什么是索瑞森","索瑞森的建造者"}},{q="这座城市是如何被摧毁的？",a="为了在三锤之战中击败其他矮人部族，大巫师索瑞森孤注一掷，试图召唤一个强大的超自然仆从。仪式打破了束缚在地底的拉格纳罗斯的枷锁。炎魔的暴力降临引发了世界末日般的火山喷发，将城市及周边郁郁葱葱的山谷化为焦土废墟。",al={"索瑞森的焚毁原因","摧毁索瑞森的元凶","谁摧毁了索瑞森"}},{q="为什么废墟周围的地面是一片灰烬荒原？",a="燃烧平原曾经是赤脊山北部肥沃的绿色区域。拉格纳罗斯被召唤时引发的爆炸性灾难撕裂了大地，隆起了黑石山，并将整片广袤的土地烧成了一片干旱、灰烬弥漫的荒野。",al={"燃烧平原灰烬成因","此地发生了什么","与赤脊山的联系"}},{q="幸存的黑铁矮人去了哪里？",a="幸存者被拉格纳罗斯及其元素爪牙奴役。他们撤退到黑石山深处建造了暗炉城，抛弃了沦为荒原的故都，在为炎魔的效力中受尽苦难。",al={"黑铁部族的现状","暗炉城的起源"}}},fp="19,298,21.714.0,17.517.1,43.240.0,27.303.0,54.193.0,45.220.0"}
P.entries["subzone:ruins-of-uldum"] = {n="Ruins of Uldum",s="坐落在塔纳利斯南部守卫之谷的锯齿状悬崖中，Ruins of Uldum由一座守卫着封印的泰坦设施的古老石厅组成。巨大的石门保护着这里的秘密，使其免受盗墓者和好奇探险家的侵扰。",h="坐落在塔纳利斯南部守卫之谷的锯齿状悬崖中，Ruins of Uldum由一座守卫着封印的泰坦设施的古老石厅组成。巨大的石门保护着这里的秘密，使其免受盗墓者和好奇探险家的侵扰。",kw={"土灵","塔纳利斯","泰坦","奥丹姆","守卫之谷"},ang={["profession:Mining"]="奥丹姆的石雕和机械展现了泰坦的精湛工艺，历经数千年的构造压力和沙漠侵蚀依然屹立不倒。",["race:Dwarf"]="对于追溯血统至土灵的矮人来说，奥丹姆代表了最初的泰坦育婴室之一，他们的祖先在大分裂后曾在此地首次休憩。"},sec={{t="泰坦前厅",b="Ruins of Uldum深嵌在塔纳利斯南部的基岩之中，看起来像是通往一个更大、已封印的地下综合体的门厅或宏伟入口。其巨大的石门紧闭，拒绝外界的干扰，现代学者所知的任何机制或钥匙都无法将其打开。"},{t="生物圈的秘密",b="根据古代记录和天象观测者的说法，奥丹姆是由泰坦与奥达曼和奥杜尔等设施一同建立的，旨在研究、修改和监测艾泽拉斯生物圈的研究基地。当大分裂在万年前撕裂世界时，土灵感受到了世界的痛苦，并退回这些地下拱顶中进行休眠。若要获得通往遗迹封印的内部入口之后的完全访问权限，需要失落的奥丹姆石板，因此该设施的全部范围仍然对现代地表居民封闭。"}},faq={{q="奥丹姆遗迹里面有什么？",a="没人能确定。这些遗迹是一座封印在巨大石门后的古老泰坦大厅，石门后的综合体至今仍未向现代探险家开放。",al={"奥丹姆里有什么","塔纳利斯的奥丹姆是什么","奥丹姆遗迹内部"}},{q="玩家可以进入门后的主要设施吗？",a="不可以。大门仍然处于封闭状态。诺甘农的石卫士表示，只有携带失落的奥丹姆石板的人才被允许进入奥丹姆大院，而目前还没有人找到它们。",al={"可以打开奥丹姆的门吗","如何进入奥丹姆","打开奥丹姆大门"}},{q="奥丹姆是为什么而建的？",a="诺甘农的石卫士等泰坦构装体将奥丹姆描述为一个旨在研究、维持和增强艾泽拉斯生物圈的研究综合体，其起源与奥达曼和奥杜尔等地点类似。",al={"泰坦为什么要建造奥丹姆","奥丹姆的目的","奥丹姆背景故事"}}},fp="14,190,29.205.0,24.370.1,34.153.0,52.160.0,25.185.0"}
P.entries["subzone:ruins-of-zul-mamwe"] = {n="祖玛维废墟",s="祖玛维废墟隐匿在莫什奥格食人魔山以南的山区凹地中，是裂颅者巨魔部族的一座戒备森严的据点。这座古老的石制平台几乎四面环绕着陡峭的悬崖，在残暴的首领“冷酷的安纳塞克”的统治下，如今这里到处都是凶猛的丛林巨魔。",h="祖玛维废墟隐匿在莫什奥格食人魔山以南的山区凹地中，是裂颅者巨魔部族的一座戒备森严的据点。这座古老的石制平台几乎四面环绕着陡峭的悬崖，在残暴的首领“冷酷的安纳塞克”的统治下，如今这里到处都是凶猛的丛林巨魔。",kw={"安纳塞克","冷酷的安纳塞克","古拉巴什","丛林巨魔","裂颅者","荆棘谷","祖玛维"},ang={["race:Troll"]="对于效忠部落的暗矛巨魔来说，祖玛维是一个发人深省的提醒，时刻警示着那些拒绝放弃嗜血传统、无法适应更广阔世界的丛林亲族们，他们正走在野蛮而封闭的道路上。"},sec={{t="裂颅者的据点",b="祖玛维废墟是裂颅者部族在中部荆棘谷的主要权力中心之一。该遗址坐落于天然的环形山谷之中，仅有北部一条通路，使其成为了极其优越的防御堡垒。在那风化的金字塔和石质梯台之上，首领“冷酷的安纳塞克”指挥着他的战士和巫医，奋力捍卫领土，抵御着外来冒险者和敌对丛林巨魔部族的侵袭。"},{t="古代帝国的遗迹",b="正如点缀在丛林中的许多石制聚落一样，祖玛维是古老的古拉巴什帝国的遗迹，该帝国曾统治过这片大陆的南部疆域。虽然伟大的帝国早已分裂成互相争斗、敌对的派系，但现代的裂颅者部族仍在这些祖先的石刻间顽强地坚守，在杂草丛生的砖石和残破的巨石阵中延续着古老的部族仪式。"}},faq={{q="谁控制着祖玛维废墟？",a="这些废墟由裂颅者巨魔部族占据，他们是荆棘谷中两个主要且具有侵略性的丛林巨魔部族之一。他们在现场由其首领“冷酷的安纳塞克”指挥。",al={"这里住着谁","祖玛维巨魔","谁拥有祖玛维"}},{q="祖玛维位于哪里？",a="祖玛维位于中部荆棘谷，就在莫什奥格食人魔山的南边。这个营地几乎四面都被高耸的山脉环绕，主要通过北面的一条山谷通道进出。",al={"如何前往祖玛维","祖玛维位置","它在哪里"}},{q="为什么裂颅者会对旅行者充满敌意？",a="裂颅者部族极度排外且对外界怀有敌意，视所有其他种族和敌对的巨魔部族为闯入他们祖先领地的入侵者。在“冷酷的安纳塞克”的领导下，他们会攻击任何接近他们丛林圣地的人。",al={"巨魔为什么攻击","裂颅者敌意"}},{q="这些废墟背后的历史是什么？",a="祖玛维的石制结构可以追溯到古拉巴什帝国的鼎盛时期。在帝国崩溃并分裂成相互交战的派系后，裂颅者占据了这里作为内陆作战基地，并保留了其古老的石质梯台。",al={"废墟历史","谁建造了祖玛维","祖玛维背景故事"}}},fp="18,222,32.387.0,29.320.0,36.181.0,27.190.0,48.247.0,39.236.0"}
P.entries["subzone:rustmaul-dig-site"] = {n="锈锤挖掘场",s="锈锤挖掘场是位于闪光平原南端的一处废弃挖掘场。它最初由铁炉堡的探险者协会建立，旨在发掘古代遗迹，但在部落的一支战争小队屠杀了这里的矿工之后，这里便陷入了悲剧，随后地下涌出了异种虫群。如今，这里已被凡人遗弃，到处都是从地下洞穴中爬出的充满敌意的昆虫生物。",h="锈锤挖掘场是位于闪光平原南端的一处废弃挖掘场。它最初由铁炉堡的探险者协会建立，旨在发掘古代遗迹，但在部落的一支战争小队屠杀了这里的矿工之后，这里便陷入了悲剧，随后地下涌出了异种虫群。如今，这里已被凡人遗弃，到处都是从地下...",kw={"探险者协会","铁石营地","摩克塔·克林","锈锤挖掘场","闪光平原","异种虫","千针石林"},ang={["faction:Horde"]="尽管摩克塔·克林的战争小队声称战胜了矮人挖掘者，但在战斗结束后，一种古老而恐怖的异种虫威胁随之出现，如今正威胁着整个地区。",["race:Dwarf"]="对于铁炉堡的矮人来说，锈锤挖掘场是探险者协会所面临危险的悲剧性提醒，因为在大地本身塌陷向恐怖的昆虫之前，他们的学者就已经在此被屠杀。"},sec={{t="盐碱地上的屠杀",b="来自铁炉堡探险者协会的探矿者们建立了锈锤挖掘场，希望发掘出掩埋在盐碱平原下的遗忘神器。然而，随着摩克塔·克林率领的一支充满攻击性的部落战争小队突袭营地并屠杀了矮人挖掘者，他们的努力被残酷地打断了。然而，征服者们并没有享受到胜利。这场激烈的冲突似乎惊动了遗址下方休眠的洞穴网络，释放出了无穷无尽的异种虫群，迅速淹没并驱逐了伤痕累累的幸存者。"},{t="苏醒的虫群",b="如今，锈锤挖掘场对于地表种族而言已彻底沦陷。仅存的采矿设备和脚手架掩埋在爬行的节肢和异形的甲壳之下。摩克塔·克林战争小队的幸存者们向北撤退到了铁石营地，被袭击后涌出的无穷无尽的虫群吓破了胆。"}},faq={{q="什么是锈锤挖掘场？",a="它是位于千针石林闪光平原内的一处挖掘营地。矮人探险家最初在此建立它是为了发掘古代遗迹，但后来它被致命的异种虫群占领了。",al={"什么是锈锤","锈锤背景故事","闪光平原挖掘场"}},{q="过去是谁住在这里并在此工作？",a="来自矮人探险者协会的探矿者和挖掘工最初在此进行挖掘作业，发掘埋藏在盐碱平原下的文物和遗迹。",al={"谁挖掘了锈锤","谁拥有锈锤","在锈锤的矮人"}},{q="为什么挖掘场被遗弃且充满了虫子？",a="由摩克塔·克林率领的部落战争小队袭击了营地并屠杀了矮人。这场骚乱似乎惊动了矿洞内位于地下的异种虫巢穴，释放出的虫群驱散了幸存的袭击者。",al={"锈锤发生了什么","为什么锈锤有虫子","谁袭击了锈锤"}},{q="幸存的袭击者去了哪里？",a="摩克塔·克林的部落战争小队残部伤痕累累，向北逃过平原，撤退到铁石营地休整，信使们甚至将警告传回了奥格瑞玛。",al={"摩克塔·克林在哪里","锈锤的幸存者","铁石营地联系"}}},fx={["55b33fa4"]={q="锈锤挖掘场发生了什么？",a="探险者协会的矮人考古学家当时正在此处发掘古代遗迹，摩克塔·克林率领的一支部落军队突然袭击了他们，将现场的矮人全部屠杀。这场暴力冲突似乎惊动了洞穴深处的地下异种虫巢穴。一股势不可挡的虫群从深处涌出，击溃并赶走了伤痕累累的部落袭击者，占据了整个挖掘场。",al={"锈锤挖掘场的历史","锈锤发生了什么","锈锤屠杀事件"}},d4492c4a={q="锈锤挖掘场危险吗？",a="那里极其危险。贪婪的异种虫遍布挖掘沟壑，在中央洞穴中成群出没。任何进入其中的旅人都有被虫群包围并吞噬的危险，正如那些伤痕累累的幸存袭击者最终被虫群的数量压倒、赶走一样。",al={"锈锤危险吗","锈锤挖掘场的威胁","锈锤的危险"}}},fp="17,252,23.433.0,19.281.0,30.165.0,31.136.0,47.204.0,37.151.0"}
P.entries["subzone:rut-theran-village"] = {n="鲁瑟兰村",s="鲁瑟兰村是一个位于泰达希尔南麓的海滨避风港。它作为达纳苏斯的主要海运港口，通过渡轮和角鹰兽航线将与世隔绝的世界之树与卡利姆多大陆连接起来。",h="鲁瑟兰村是一个位于泰达希尔南麓的海滨避风港。它作为达纳苏斯的主要海运港口，通过渡轮和角鹰兽航线将与世隔绝的世界之树与卡利姆多大陆连接起来。",kw={"奥伯丁","黑海岸","达纳苏斯","码头","角鹰兽","月神之泪号","港口","鲁瑟兰","泰达希尔"},ang={["class:Druid"]="从神圣的月光林地避难所归来的德鲁伊可以乘坐塞纳里奥角鹰兽，从永夜港直接飞越卡利姆多北部抵达鲁瑟兰村。",["race:NightElf"]="对于离开泰达希尔去援助联盟的年轻暗夜精灵来说，鲁瑟兰村是他们在航向卡利姆多大陆前，对世界之树树冠的最后告别。"},sec={{t="通往世界之树的门户",b="鲁瑟兰村坐落在泰达希尔高耸入云的下方，位于水畔，是暗夜精灵首都与外界之间的门户。虽然达纳苏斯位于上方的枝叶之中，但鲁瑟兰村为维持其运转提供了必要的后勤保障。一处神秘的传送门在树下拱起，瞬间将旅客从海岸传送到达纳苏斯。若是想要渡海，村庄的码头有渡轮直达黑海岸的奥伯丁，同时还有飞行管理员照看训练有素的角鹰兽栖息地。"}},faq={{q="我该如何从这里前往达纳苏斯？",a="从码头沿着平缓的坡道向巨大的凉亭帐篷走去。踏上平台那闪烁着紫色光芒的传送门，你就能瞬间传送到位于达纳苏斯内部的神殿花园。",al={"前往达纳苏斯","通往达纳苏斯的传送门","如何到达达纳苏斯"}},{q="码头上的船去往哪里？",a="停靠在鲁瑟兰村的船只“月光”号，提供穿过迷雾之海前往黑海岸沿岸奥伯丁镇的航线。",al={"船去哪里","鲁瑟兰渡轮","鲁瑟兰航线"}},{q="为什么这个村庄是在海平面而不是在树上？",a="泰达希尔的树冠太高，无法容纳常规帆船或进行海上贸易。鲁瑟兰村建立在其根部，旨在提供一个海平面的港口和栖息地，并通过永久的传送门与高处相连。",al={"为什么鲁瑟兰在海平面","为什么在泰达希尔底部"}},{q="我能从这里飞往任何地方吗？",a="是的。村庄的栖息地有一位角鹰兽训练师，提供飞越水域前往黑海岸的奥伯丁的飞行路线，而从月光林地归来的德鲁伊则会乘坐塞纳里奥议会从永夜港飞来的角鹰兽在这里降落。",al={"鲁瑟兰飞行点","角鹰兽能飞去哪里"}}},fp="18,177,25.389.0,36.174.0,37.105.0,64.208.0,29.183.0"}
P.entries["subzone:saldean-s-farm"] = {n="萨丁农场",s="萨丁农场是西部荒野中唯一没有被迪菲亚潜行者彻底占领并荒废的家园。在顽固的农夫萨丁和他妻子萨尔玛·萨丁的坚守下，这座农舍成为了该地区动荡局势中一处难得的避风港。",h="萨丁农场是西部荒野中唯一没有被迪菲亚潜行者彻底占领并荒废的家园。在顽固的农夫萨丁和他妻子萨尔玛·萨丁的坚守下，这座农舍成为了该地区动荡局势中一处难得的避风港。",kw={"农夫萨丁","收容所","收割傀儡","难民","萨丁","萨尔玛·萨丁","西部荒野"},ang={["faction:Alliance"]="萨丁农场代表了王国边境原始而颓败的一角，暴露了当暴风城的领导层心不在焉时，普通公民所遭受的苦难有多深。",["profession:Cooking"]="萨尔玛·萨丁因能将搜集来的西部荒野食材烹饪成如血牙野猪的肝馅饼这样热乎且能救命的菜肴，而在旅人中享有盛誉。"},sec={{t="尘土中的灯塔",b="当周边的土地沦陷于强盗劫掠和机械破坏时，萨丁一家拒绝放弃他们的土地。农夫萨丁和他的妻子萨尔玛·萨丁一直留守在他们的家园，为过往的旅人提供热食和一句温暖的话语。尽管他们十分坚韧，但农田依然饱受徘徊在平原上的失控收割傀儡之苦，迫使这一家人只能紧守在农舍围墙附近。"},{t="坚守阵线",b="由于暴风城王室在很大程度上忽视了西部荒野，这里的治安力量非常薄弱。虽然有少数来自哨兵岭和暴风城的卫兵在周边巡逻，但农场的生存主要靠的是坚韧不拔的毅力和过往旅行者的援助。对于萨丁一家来说，萨尔玛·萨丁著名的西部荒野炖肉、血牙野猪的肝馅饼以及农舍提供的庇护，都是对抗迪菲亚潜行者时刻威胁的小小慰藉。"}},faq={{q="为什么其他农场都陷落了，而这座农场还能屹立不倒？",a="当迪菲亚潜行者席卷西部荒野时，农夫萨丁和他的妻子只是拒绝收拾行囊逃离。尽管充满敌意的收割傀儡在他们的庄稼地里游荡，这一家人还是在过往民兵和冒险者的帮助下，顽强地保卫着农舍周边的区域。",al={"为什么没有被占领","萨丁农场的生存","农场是如何存活下来的"}},{q="聚集在房子周围的都是些什么人？",a="农场的常驻民是农夫萨丁和他的妻子萨尔玛·萨丁；你在那里发现的其他任何人都可能是过往的旅人，因为这对夫妇欢迎访客，也欢迎愿意帮助他们解决困扰农田威胁的冒险者。",al={"萨丁农场的难民","西部荒野的流浪者","农场的孤儿"}},{q="为什么机械傀儡会袭击农田？",a="迪菲亚潜行者将该地区的机械收割机和傀儡改造为了致命的哨兵。它们在田野间游荡，攻击任何试图耕作或清理土地的人。",al={"收割傀儡","为什么庄稼地里有机器人","机械稻草人"}},{q="暴风城军队在保护这座农场吗？",a="官方的军事力量几乎不存在。几名从哨兵岭和暴风城派来的零星守卫只能提供最低限度的警戒，王室在很大程度上将西部荒野的防御留给了当地人自行解决。",al={"暴风城军事存在","哨兵岭守卫在这里","守卫支持"}}},fx={a60e97c5={q="萨丁农场是什么地方？",a="萨丁农场是西部荒野最后几处尚未被迪菲亚潜行者完全占据的农庄之一。周围的土地已遭摧残或被遗弃，这座顽强的农庄却依然屹立在北部平原上，在这片地区的衰败中始终为人们提供庇护。",al={"萨丁农场是什么地方","萨丁农场概况","萨丁农场背景"}},a483aabd={q="萨丁农场为什么叫这个名字？",a="农场以农夫萨丁和他的妻子萨尔玛·萨丁的名字命名。迪菲亚潜行者掌控西部荒野时，大多数地主都逃走了，萨丁一家却固执地坚守家园，不肯放弃农庄，还为过往旅人提供食物和亲切的问候。",al={"谁给萨丁农场起的名字","萨丁农场名字的含义","为什么叫萨丁农场"}}},fp="14,215,20.299.0,16.367.0,53.240.0,49.193.0,47.180.0,42.184.0"}
P.entries["subzone:saltspray-glen"] = {n="盐沫沼泽",s="盐沫沼泽是位于湿地西北部的一片广袤荒野，紧邻巴拉丁海湾。强劲的海风经常将咸涩的海水吹过这片长满苔藓的低地，而这里到处都是极具攻击性的野生迅猛龙。它构成了一条险峻的自然通道，连接着周围鱼人出没的沼泽和古老的矮人遗迹。",h="盐沫沼泽是位于湿地西北部的一片广袤荒野，紧邻巴拉丁海湾。强劲的海风经常将咸涩的海水吹过这片长满苔藓的低地，而这里到处都是极具攻击性的野生迅猛龙。它构成了一条险峻的自然通道，连接着周围鱼人出没的沼泽和古老的矮人遗迹。",kw={"巴拉丁海湾","蓝腮沼泽","铁须之墓","迅猛龙","盐沫沼泽","湿地"},ang={["class:Hunter"]="潜伏在沼泽湿润海草丛中的凶猛迅猛龙，为追踪海岸的猎人提供了丰厚的猎物，也是可靠而凶猛的野兽。"},sec={{t="咸盐与利爪",b="盐沫沼泽深藏在湿地的最西北角，这个名字来源于每当沿海大风刮起时，从巴拉丁海湾吹向内陆的海雾。它南临鱼人横行的蓝腮沼泽，东接铁须之墓静谧的悬崖，对于路过的旅人来说，这里几乎没有落脚之地。成群狡猾的野生迅猛龙在沼泽的草丛中筑巢，它们与来自附近恐龙岭和黑水沼泽的同类一起，在咸湿的平原上猎食。"}},faq={{q="为什么叫盐沫沼泽？",a="这片沼泽直接坐落在巴拉丁海湾的开阔海岸线上。每当猛烈的海上风从西北方横扫海湾时，海水就会化作浓重的咸雾，被吹向内陆的低洼地带。",al={"盐沫沼泽名字含义","为什么叫盐沫","名字起源"}},{q="盐沫沼泽里生活着什么生物？",a="这片沼泽里到处都是极具攻击性的野生迅猛龙，它们利用沿海的灌木丛和沼泽洼地作为理想的筑巢地。它们会毫不犹豫地伏击任何偏离大路的人。",al={"盐沫沼泽的怪物","盐沫迅猛龙","这里有什么"}},{q="盐沫沼泽通往哪里？",a="盐沫沼泽位于湿地西北部。它北临并西接巴拉丁海湾，南邻鱼人领地蓝腮沼泽，东接铁须之墓的岩石高地。",al={"盐沫沼泽位置","盐沫沼泽在哪里","边界"}}},fp="14,158,15.434.0,32.161.0,38.150.0,31.214.0"}
P.entries["subzone:salty-sailor-tavern"] = {n="Salty Sailor Tavern",s="Salty Sailor Tavern是藏宝海湾社交生活的核心，也是这座港口主要的旅店和休憩之所。它由地精旅店老板斯金德尔经营，欢迎来自两个阵营、寻求避开丛林险境的恶棍、雇佣兵和旅行者。",h="Salty Sailor Tavern是藏宝海湾社交生活的核心，也是这座港口主要的旅店和休憩之所。它由地精旅店老板斯金德尔经营，欢迎来自两个阵营、寻求避开丛林险境的恶棍、雇佣兵和旅行者。",kw={"黑水强盗","藏宝海湾旅店","守护石","水手之家","斯金德尔"},ang={["class:Rogue"]="Salty Sailor Tavern拥挤而烟雾缭绕的大厅是交换传闻、聆听海盗闲聊，以及守护好你钱包的理想场所。"},sec={{t="丛林中的避风港",b="Salty Sailor Tavern坐落在藏宝海湾的木质阶梯之间，在黑水强盗的注视下提供温暖的床铺和烈酒。酒吧后面站着旅店老板斯金德尔，在各色海盗、商人和冒险者于这片中立之地交际时，他负责为客人们斟满酒杯。建筑外挂着一件巨大而奇特的古董——一块祖尔格拉布守护石——在这个繁忙的商业窝点中成为了一个奇怪的战利品。"}},faq={{q="是谁经营着水手之家旅店？",a="这家旅店及其相关服务由旅店老板斯金德尔管理，这位勤奋的地精专门为往来藏宝海湾的各色水手、雇佣兵和冒险者提供服务。",al={"旅店老板","谁是旅店老板","斯金德尔"}},{q="挂在旅店外面的那块大石头是什么？",a="建筑外悬挂着的是一块祖尔格拉布守护石，这是一件从丛林深处古老巨魔遗迹中带回的不祥遗物。",al={"外面的石头","祖尔格拉布之石","守护石"}},{q="联盟和部落的成员都能住在这里吗？",a="是的。和藏宝海湾的其他地方一样，水手之家旅店在热砂港的中立权威下运营。只要顾客遵守规矩且不拔出武器，联盟和部落的旅行者都可以自由地在这里休息。",al={"这里是中立的吗","允许联盟和部落进入","部落可以使用这家旅店吗"}}},fp="19,210,26.327.0,33.158.0,52.134.0,38.171.0"}
P.entries["subzone:sanctum-stromgarde-keep"] = {n="Sanctum (Stromgarde Keep)",s="密室是位于激流堡教堂后方的一处神圣堡垒。它坐落在摇摇欲坠的要塞之中，守卫着通往托尔贝恩家族先祖陵墓的入口，在阿拉希的废墟中，这里是圣光仅存的堡垒之一。",h="密室是位于激流堡教堂后方的一处神圣堡垒。它坐落在摇摇欲坠的要塞之中，守卫着通往托尔贝恩家族先祖陵墓的入口，在阿拉希的废墟中，这里是圣光仅存的堡垒之一。",kw={"阿拉希","教堂","圣光大教堂","陵墓","加林","密室","激流堡","托尔贝恩"},ang={["class:Paladin"]="教堂和密室是阿拉希沦陷的都城中最后未被玷污的圣光避难所，因此保卫这里是一项庄严的职责。",["faction:Alliance"]="守住密室确保了托尔贝恩王室能够继续维持对先祖领地的控制，让联盟在激流堡的争夺废墟中依然保有一席之地。"},sec={{t="废墟中的堡垒",b="尽管激流堡的大部分地区已经落入辛迪加渗透者和巨石食人魔之手，但密室及其相邻的教堂在激流堡幸存守军的殊死保卫下依然未被攻陷。密室位于礼拜堂后方，与要塞的墓地接壤，是通往激流堡历代国王安息的皇家陵墓的必经之地。对于簇拥在加林·托尔贝恩王子麾下的残部忠诚者来说，守住这片神圣的土地不仅仅是一个战术据点的问题；更是一场为了守护王国先祖传承与信仰不被入侵者践踏而进行的绝望之战。"},{t="国王的门槛",b="密室的石板之下通往皇家陵墓。这里的土地是神圣的，原本是人们静思和崇拜圣光的地方。在索拉斯·托尔贝恩国王遇刺及王国随之崩溃后，密室反而成为了一个防御性的撤退点。那些试图闯入The Inner Sanctum的人不仅要面对遍布大厅的皇家卫兵，还要面对这个古老的人类血脉在神圣门槛上苦苦求存的凄凉现实。"}},faq={{q="什么是密室？",a="密室是激流堡内圣光大教堂后方的内部区域。它与要塞的墓地相连，并直接通往托尔贝恩家族的先祖陵墓。",al={"什么是密室","激流堡密室"}},{q="现在是谁控制着密室？",a="密室由忠于联盟和加林·托尔贝恩王子的幸存激流堡士兵把守。与被辛迪加匪徒和巨石食人魔占领的城市其他地区不同，教堂和密室仍在人类的守卫之下。",al={"谁在密室里","密室守卫","谁控制了密室"}},{q="密室后面有什么？",a="穿过密室便是托尔贝恩家族的陵墓，激流堡历代陨落的统治者，包括最近遇害的索拉斯·托尔贝恩国王，都安葬于此。",al={"密室通向哪里","密室陵墓","密室后面有什么"}},{q="为什么这个区域对激流堡很重要？",a="密室不仅是崇拜圣光的神圣中心，还守护着激流堡国王的皇家安息之地。对于幸存的守军来说，放弃这里就意味着任由入侵者亵渎先祖的坟墓。",al={"为什么要在意密室","密室的意义","为什么要保卫密室"}}},fp="25,142,22.412.0,22.390.0,20.151.0,35.222.0,29.140.0,41.187.0"}
P.entries["subzone:sandsorrow-watch"] = {n="流沙岗哨",s="流沙岗哨是一个位于塔纳利斯加基森以西的广阔沙漠前哨站。周围的沙丘和废墟被敌对的沙怒巨魔及其复活的亡者所占领，他们还控制着俯瞰荒地的东侧瞭望塔。",h="流沙岗哨是一个位于塔纳利斯加基森以西的广阔沙漠前哨站。周围的沙丘和废墟被敌对的沙怒巨魔及其复活的亡者所占领，他们还控制着俯瞰荒地的东侧瞭望塔。",kw={"加基森","沙巨魔","沙怒","流沙岗哨","塔纳利斯"},ang={["profession:Blacksmithing"]="在沙怒控制的瞭望塔里没有铁匠工作；沙漠铁匠们都聚集在东面加基森的城墙内。",["race:Troll"]="暗矛巨魔在这里找不到任何亲属关系：敌对的沙怒部族将所有外来者视为必须被粉碎并复活为行尸走肉的入侵者。"},sec={{t="危险的栖木",b="流沙岗哨位于繁华的地精贸易枢纽加基森的正西方，是塔纳利斯沙漠中一处严峻的边境。这片广袤的区域主要由沙怒部族控制，他们与成群结队的行尸巨魔一起，积极捍卫着这片荒凉的领土。位于东侧边缘的一座高耸瞭望塔巩固了他们的阵地，在这片不断侵蚀的沙漠荒野和敌对的土著部族之间，提供了一个坚固的有利位置。"},{t="边境前哨",b="即使是位于东侧边缘、在加基森城墙视线范围内的瞭望塔，也被沙怒部族所把持。他们从高处警惕地注视着这座地精城镇，而从加基森西门离开的旅行者几乎会直接走进他们的领地，这时刻提醒着人们塔纳利斯投机定居者与当地沙巨魔之间不稳定的边境紧张局势。"}},faq={{q="流沙岗哨位于何处？",a="流沙岗哨位于塔纳利斯北部沙漠平原，加基森的正西方。从加基森西门出发的旅行者几乎会立即遇到它。",al={"流沙岗哨位置","流沙岗哨在哪里","如何前往流沙岗哨"}},{q="谁控制着流沙岗哨？",a="废墟、周围的沙丘以及东侧的瞭望塔全部被敌对的沙怒巨魔及其亡灵爪牙所占领。",al={"谁住在流沙岗哨","流沙岗哨阵营","谁占领了流沙岗哨"}},{q="为什么流沙岗哨会有亡灵巨魔？",a="沙怒部族修炼邪恶的死灵法术和巫毒，经常将阵亡的沙怒勇士复活为沙怒僵尸，以守卫他们遍布塔纳利斯的荒凉领土和前哨站。",al={"沙怒僵尸","为什么塔纳利斯有巨魔僵尸","流沙岗哨僵尸"}},{q="冒险者在周围的沙丘中会遇到什么威胁？",a="该地区有大量的沙怒投斧手、火法师和剥皮者巡逻，随行的还有他们复活的巨魔僵尸。未经准备的旅行者如果走出加基森西侧的主路，很容易被游荡的沙怒战团所淹没。",al={"流沙岗哨怪物","流沙岗哨敌人","流沙岗哨敌对巨魔"}}},fp="16,92,18.192.0,16.245.0,34.147.0,30.98.0,48.151.0,61.186.0"}
P.entries["subzone:sar-theris-strand"] = {n="萨瑟里斯海岸",s="萨瑟里斯海岸构成了凄凉之地的西海岸线，面朝迷雾之海。与贫瘠灰暗的内陆荒野形成鲜明对比的是，这里的海岸阳光明媚、绿草如茵，但由于徘徊的娜迦、海巨人以及马库拉，这里依然危机四伏。",h="萨瑟里斯海岸构成了凄凉之地的西海岸线，面朝迷雾之海。与贫瘠灰暗的内陆荒野形成鲜明对比的是，这里的海岸阳光明媚、绿草如茵，但由于徘徊的娜迦、海巨人以及马库拉，这里依然危机四伏。",kw={"凄凉之地","卡尼托","马库拉","萨瑟里斯","海岸","虎鱼"},ang={["profession:Cooking"]="萨瑟里斯海岸及周边水域拥有丰富的海洋猎物，包括马库拉和珍稀海鱼，但生火烹饪时必须时刻提防徘徊的娜迦。"},sec={{t="灰色荒野上的绿色边缘",b="萨瑟里斯海岸绵延在凄凉之地的西侧，为内陆平原的尘灰提供了一处离奇的休憩之所。这里的崖顶和海滩明亮而翠绿。然而，这片海岸绝非善地：蛇形的娜迦与高大的海巨人及领地意识极强的马库拉一同巡视着浪潮。浅滩上散落着沉船残骸，包括北方的卡尼托号残骸，以及艾瑟雷索高塔下方破碎的小艇，证明了海洋与海岸一样险恶。"},{t="残骸与珍稀水域",b="除了娜迦和巨人的持续威胁外，海岸外的水域因其独特的馈赠而在老练的旅行者中闻名。崎岖的近海浅滩中隐藏着来自失踪探险队和商队的打捞物，而深处的浪潮中栖息着珍稀的海洋生物，最著名的便是卡利姆多各地的钓鱼大师们苦苦追寻的珍贵鱼类——萨瑟里斯虎鱼。"}},faq={{q="为什么凄凉之地的其他地方一片死寂，而萨瑟里斯海岸却是绿色的？",a="与凄凉之地贫瘠灰暗的内陆相比，这段海岸线阳光明媚，绿草如茵。来源中并未解释造成这种反差的原因。",al={"为什么海岸是绿色的","凄凉之地沿海草地","萨瑟里斯天气"}},{q="萨瑟里斯海岸栖息着哪些生物？",a="这片海岸的主要居民是两栖的滑刃娜迦、游荡的海巨人以及横行的马库拉。旅行者必须时刻留意浪潮，因为巡逻队经常在水边出没。",al={"这里住着谁","萨瑟里斯怪物","海岸上有哪些怪物"}},{q="海岸边有哪些沉船残骸？",a="卡尼托沉船位于海岸北侧的水域中，而在艾瑟雷索精灵遗迹高塔下方的海滩断崖上，则散落着较小船只的残骸。",al={"卡尼托沉船","海岸沉船","海滩残骸"}},{q="为什么渔夫们会前往萨瑟里斯海岸？",a="这里的沿海水域是萨瑟里斯虎鱼的唯一栖息地，这种难以捕捉的鱼类被著名的垂钓者纳特·帕格公认为是考验钓鱼技艺的终极挑战之一。",al={"萨瑟里斯虎鱼","凄凉之地海岸钓鱼","纳特·帕格鱼类"}}},fp="17,190,28.408.0,24.263.0,65.115.0,41.154.0,36.157.0,44.198.0"}
P.entries["subzone:sardor-isle"] = {n="萨尔多岛",s="萨尔多岛是一座郁郁葱葱的岛屿，坐落于菲拉斯西海岸外，恐怖之岛的北部。它是羽月要塞的所在地，而羽月要塞是卡利姆多南部主要的暗夜精灵军事堡垒。尽管有大量的哨兵驻守，岛屿的部分地区仍有野兽出没，并有从浅滩爬上来的敌对纳迦潜伏。",h="萨尔多岛是一座郁郁葱葱的岛屿，坐落于菲拉斯西海岸外，恐怖之岛的北部。它是羽月要塞的所在地，而羽月要塞是卡利姆多南部主要的暗夜精灵军事堡垒。尽管有大量的哨兵驻守，岛屿的部分地区仍有野兽出没，并有从浅滩爬上来的敌对纳迦潜伏。",kw={"羽月要塞","菲拉斯","恐怖之岛","纳迦","萨尔多岛","哨兵","珊蒂斯·羽月"},ang={["faction:Alliance"]="萨尔多岛是联盟在菲拉斯的主要权力支点，在羽月要塞内提供安全的港湾、补给和飞行管理员。",["race:NightElf"]="在珊蒂斯·羽月将军的领导下，萨尔多岛上的哨兵们密切关注着整个菲拉斯的古代遗迹以及新出现的纳迦威胁。"},sec={{t="哨兵堡垒与荒野海岸",b="萨尔多岛隔水与菲拉斯大陆相望，岛上坐落着羽月要塞，这是一座由珊蒂斯·羽月将军指挥的雄伟精灵驻军点。虽然要塞本身防御森严，并有定期渡轮与大陆相连，但整座岛屿远未被完全驯服。成群的狼在树木繁茂的山坡上游荡，而入侵的纳迦则潜伏在岩石嶙峋的西岸和北岸，不断试探着暗夜精灵哨兵的底线。"}},faq={{q="萨尔多岛位于哪里？",a="萨尔多岛位于卡利姆多南部的菲拉斯西海岸外，就在恐怖之岛的北面。可以通过从大陆被遗忘的海岸出发的船只抵达。",al={"萨尔多岛位置","萨尔多在哪里","寻找萨尔多岛"}},{q="萨尔多岛上的主要定居点是什么？",a="岛上由羽月要塞占据主导地位，这是暗夜精灵和联盟在菲拉斯的主要堡垒和集结地，由珊蒂斯·羽月将军指挥。",al={"谁住在萨尔多岛","萨尔多岛城镇","萨尔多暗夜精灵基地"}},{q="要塞之外的岛上有什么威胁？",a="在羽月要塞的保护墙之外，旅行者会面临在树林中游荡的野狼群，以及潜伏在沿海礁石和沙滩上的敌对纳迦。",al={"萨尔多岛敌人","萨尔多岛上的危险","萨尔多怪物"}},{q="萨尔多岛与恐怖之岛有何不同？",a="萨尔多岛位于北面，主要由羽月要塞的暗夜精灵占据。恐怖之岛位于更南边，是一片更加严酷、未被驯服的领土，到处都是危险的奇美拉和纳迦。",al={"萨尔多岛与恐怖之岛的区别","与恐怖之岛的不同之处"}}},fp="11,173,32.406.0,29.154.0,43.169.0,60.122.0,51.187.0"}
P.entries["subzone:sargeron"] = {n="萨格隆",s="萨格隆是位于凄凉之地北部的一座古老暗夜精灵城市的废墟。在天崩地裂中，这座城市分崩离析，其前身为艾露恩神殿的地方如今已被愤怒的萨特占领并亵渎，他们以其主人萨格拉斯之名重新命名了这片土地。",h="萨格隆是位于凄凉之地北部的一座古老暗夜精灵城市的废墟。在天崩地裂中，这座城市分崩离析，其前身为艾露恩神殿的地方如今已被愤怒的萨特占领并亵渎，他们以其主人萨格拉斯之名重新命名了这片土地。",kw={"艾露恩之杯","凄凉之地","艾露恩","愤怒萨特","卡多雷","萨格拉斯","萨格隆","萨特"},ang={["class:Priest"]="月亮祭司们会认出散落在破碎石块间的艾露恩大教堂遗迹和圣物，并敦促对其进行净化。",["race:NightElf"]="对任何卡多雷来说，这些废墟都是令人心痛的景象，因为神圣的艾露恩祭坛正被恶魔萨特公然亵渎，他们以萨格拉斯的名义嘲弄着女神。"},sec={{t="一处被亵渎的圣所",b="在上古之战摧毁这片大陆之前，这处定居点是一座繁荣的艾露恩崇拜中心，供奉着艾露恩神殿、圣所和大教堂等圣地。它原本的名称早已湮没在历史中。当世界破碎时，城市化为废墟，留下了如艾露恩之杯、艾露恩火盆和艾露恩侍女等圣物。在随后的数千年里，堕落的愤怒萨特占领了这些石头建筑，将神圣的卡多雷建筑改造成了供奉泰坦萨格拉斯的据点。"}},faq={{q="大分裂前萨格隆叫什么名字？",a="它原本的暗夜精灵名称早已被时间遗忘。现名“萨格隆”是愤怒萨特为了向堕落泰坦萨格拉斯致敬，而给这些废墟取的名字。",al={"原始名称","萨格隆原始名称","它过去叫什么"}},{q="现在是谁占据着萨格隆？",a="这些废墟被愤怒萨特占据，他们是上古之战期间产生的堕落恶魔生物，一直在积极亵渎这些古老的精灵遗迹。",al={"谁住在这里","萨格隆怪物","萨格隆的敌人"}},{q="这里最初有哪些圣地？",a="这座城市曾拥有多处供奉月亮女神的重要场所，包括艾露恩神殿、艾露恩圣所和艾露恩大教堂，这里曾存放着如艾露恩之杯等受人崇敬的圣物。",al={"艾露恩神殿","圣地","这里曾有什么建筑"}},{q="为什么萨格隆对暗夜精灵很重要？",a="它作为上古之战的残酷提醒，见证了恶魔势力对卡多雷神圣空间的亵渎，并保存着古老的精灵神器，这些神器面临着丢失或被腐化的风险。",al={"萨格隆暗夜精灵传说","为什么暗夜精灵在意"}}},fp="8,230,19.505.0,46.152.0,26.130.0,45.142.0,43.171.0"}
P.entries["subzone:satyrnaar"] = {n="萨提纳尔",s="萨提纳尔是一处位于灰谷东北部的古老暗夜精灵废墟定居点，现已完全落入邪心萨特的手中。它坐落在碎木岗哨与艾萨拉之间的主干道旁，是森林中保存最完好且最容易进入的萨特据点。",h="萨提纳尔是一处位于灰谷东北部的古老暗夜精灵废墟定居点，现已完全落入邪心萨特的手中。它坐落在碎木岗哨与艾萨拉之间的主干道旁，是森林中保存最完好且最容易进入的萨特据点。",kw={"灰谷","邪心","暗滩","林歌神殿","萨特","萨提纳尔","灵魂宝石","碎木"},ang={["class:Druid"]="邪心萨特散布的扭曲邪能正在不断扼杀灰谷的自然之灵，必须尽快净化。",["race:NightElf"]="看着祖先的石刻遭到邪能腐蚀，并被诅咒的上层精灵遗民所占据，这对任何途经灰谷的暗夜精灵来说都是一种沉重的冒犯。"},sec={{t="邪能与暗影的巢穴",b="萨提纳尔位于碎木岗哨东北方、林歌神殿西南方，与萨维亚和夜道谷并列为灰谷的三大主要萨特定居点之一。与其他深处的荒野遗迹不同，萨提纳尔相对保存完好，在崩塌的精灵建筑中搭建着帐篷。它是邪心萨特的繁忙营地，导致前往艾萨拉的附近贸易路线对旅行者来说充满了危险。此外，黑暗的勾当在此滋生：萨特们与阴暗的暗滩教派结成了同盟，并将他们邪恶的灵魂宝石之一藏在这些腐化的石块之中。"}},faq={{q="萨提纳尔是什么地方？",a="萨提纳尔是灰谷东北部的一处暗夜精灵遗迹，已被邪心萨特占据。它是该地区萨特的主要据点之一。",al={"萨提纳尔概况","这是什么地方","萨特营地"}},{q="谁居住在萨提纳尔？",a="该定居点由邪心萨特部族占据。他们在古老的遗迹中搭建帐篷，并与暗滩教派勾结在一起。",al={"谁在这里","萨提纳尔怪物","邪心萨特"}},{q="为什么萨提纳尔比其他萨特遗迹更重要？",a="在灰谷的三大萨特据点——萨提纳尔、夜道谷和萨维亚中，萨提纳尔保存最完好且位置最居中，就在通往艾萨拉的大路旁。",al={"萨提纳尔与萨维亚","为什么选择萨提纳尔"}},{q="藏在萨提纳尔的黑暗神器是什么？",a="萨提纳尔藏有一枚属于暗滩教派的腐化灵魂宝石，这是一个与邪心萨特结盟的凡人暗影教派。",al={"暗滩灵魂宝石","萨提纳尔水晶","灵魂宝石"}}},fp="9,250,23.458.0,18.105.0,23.125.0,59.166.0,46.120.0"}
P.entries["subzone:savage-coast"] = {n="野人海岸",s="野人海岸是北荆棘谷崎岖的西海岸线，从西部荒野的南部边界一直延伸至格罗姆高营地。这里徘徊着淡水鳄、海岸蛇颈龙以及充满敌意的巨魔部落，这片滩涂正如其名，每一次潮汐都伴随着残酷的杀戮。",h="野人海岸是北荆棘谷崎岖的西海岸线，从西部荒野的南部边界一直延伸至格罗姆高营地。这里徘徊着淡水鳄、海岸蛇颈龙以及充满敌意的巨魔部落，这片滩涂正如其名，每一次潮汐都伴随着残酷的杀戮。",kw={"蛇颈龙","淡水鳄","格罗姆高","野人海岸","荆棘谷","暗礁海","西部荒野"},ang={["class:Hunter"]="这片海岸线上拥有大量的淡水鳄和蛇颈龙，适合进行追踪、剥皮以及野兽驯服。",["faction:Horde"]="海岸的北段位于格罗姆高营地上方，作为抵御靠近无尽之海的野生动物和激进巨魔团体的外围缓冲区。"},sec={{t="危险的滩涂",b="野人海岸从与西部荒野接壤的悬崖向南一直延伸到格罗姆高营地，构成了北荆棘谷险恶的西缘。这片沙滩绝非善地：鳄鱼、淡水鳄和石 stalkers 在潮汐池和漂流木间自由游荡。稍往内陆走，便是领地意识极强的丛林巨魔营地，这使得在这片海滩上任何漫不经心的散步都成了生存之战。近海处，水域向下沉没，直逼潜伏着暗礁海危险的水域，确保了无论是沙滩上还是波浪下，处处皆是危机。"}},faq={{q="野人海岸在哪里？",a="野人海岸位于北荆棘谷的西侧大洋边缘。它始于北部的西部荒野边界，向南延伸经过暗礁海附近的水域，直达格罗姆高营地。",al={"野人海岸位置","野人海岸在哪里","野人海岸地图"}},{q="野人海岸生活着哪些生物？",a="海岸上到处是危险的野生动物，其中最常见的是在沙滩上晒太阳的极具攻击性的淡水鳄和蛇颈龙。在水线之外和附近的丛林悬崖边，敌对的巨魔部落建立了俯瞰冲浪点的营地。",al={"野人海岸怪物","野人海岸有什么","野人海岸野兽"}},{q="对于从西部荒野向南旅行的游客来说，野人海岸安全吗？",a="一点也不。虽然沿着海岸进入荆棘谷可以避开茂密的丛林树冠，但野人海岸挤满了凶猛的两栖捕食者和当地的巨魔战士，他们会迅速淹没那些不加防备的旅行者。",al={"可以从西部荒野走到荆棘谷吗","西部荒野到野人海岸的路径"}},{q="野人海岸附近有什么地标？",a="近海处是沉没的暗礁海，沿着海岸线向下走则是部落的防御据点格罗姆高营地。向北，悬崖升起，连接着西部荒野的农田和海岸。",al={"野人海岸兴趣点","野人海岸附近有什么"}}},fp="12,191,20.371.0,26.189.0,43.130.0,66.135.0,41.159.0"}
P.entries["subzone:scarab-dais"] = {n="甲虫之台",s="甲虫之台是一座古老的高台，位于希利苏斯南部、甲虫之墙的西北方。台上安放着传说中的 圣甲虫之锣，这件仪式用具与将 其拉 帝国封印在安其拉之内的魔法结界直接相连。",h="甲虫之台是一座古老的高台，位于希利苏斯南部、甲虫之墙的西北方。台上安放着传说中的 圣甲虫之锣，这件仪式用具与将 其拉 帝国封印在安其拉之内的魔法结界直接相连。",kw={"安其拉","天启者乔纳森","甲虫之台","圣甲虫之锣","甲虫之墙","流沙","希利苏斯"},ang={["race:NightElf"]="对 kaldorei 而言，甲虫之台时刻提醒着他们千年前那场惨烈的流沙之战，暗夜精灵与各色巨龙军团曾在那场战争中付出鲜血的代价，才将 qiraji 封印在墙后。"},sec={{t="安其拉之锣",b="甲虫之台俯瞰着甲虫之墙这道巍峨屏障前的流沙，是千年前施加于安其拉的封印的核心。这座石台上安放着 圣甲虫之锣，一件在流沙之战期间铸造的遗物。据暗夜精灵的古老史书记载与 青铜龙军团 所述，唯有用重铸的流沙节杖敲响这面锣，才能击碎魔法屏障，打开大门。在那决定命运的时刻到来之前，这座高台始终笼罩着不祥的气息，守望着墙后被封印的、沉睡中的恐怖虫族。"}},faq={{q="甲虫之台是什么？",a="甲虫之台是一座位于希利苏斯南部的石质仪式平台，坐落在甲虫之墙西北方不远处。它是为安放 甲虫之锣 而建的，这面锣控制着封印安其拉的魔法结界。",al={"这座平台是什么","甲虫之台资料","锣的平台"}},{q="如果有人敲响台上的锣，会发生什么？",a="传说，用修复的流沙节杖敲响 甲虫之锣，就会击碎甲虫之墙上的结界，解除安其拉之门的封印，释放囚禁其中的 其拉 大军。",al={"锣有什么作用","敲响 圣甲虫之锣","敲锣"}},{q="谁在守护甲虫之台？",a="天启者乔纳森是 青铜龙军团 的一名人类守望者，人称 甲虫之锣 的守护者。他在高台上守护着这面锣，以及远处那扇被封印的大门。",al={"谁在甲虫之台","甲虫之台的青铜龙","天启者乔纳森"}}},fp="11,158,21.414.0,24.188.0,51.212.0,33.166.0"}
P.entries["subzone:scarab-wall"] = {n="甲虫之墙",s="甲虫之墙是位于希利苏斯南境，安其拉虫人帝国前方的一道巨大壁垒。它在流沙之战末期被创造出来，这道屏障结合了岩石与青铜龙军团的魔法，用以封印古老的虫群。它耸立在那里，无声地提醒着人们那场战争惨痛的代价。",h="甲虫之墙是位于希利苏斯南境，安其拉虫人帝国前方的一道巨大壁垒。它在流沙之战末期被创造出来，这道屏障结合了岩石与青铜龙军团的魔法，用以封印古老的虫群。它耸立在那里，无声地提醒着人们那场战争惨痛的代价。",kw={"安其拉","青铜龙军团","其拉虫人","甲虫之墙","希利苏斯","流沙之战"},ang={["class:Druid"]="德鲁伊们能感受到墙体周围生命力的不自然压制，那里古老的结界正竭力遏制着一股腐蚀性的地下枯萎之力。",["race:NightElf"]="对于暗夜精灵来说，这堵墙是一座神圣的纪念碑，铭记着在流沙之战中做出的惨烈牺牲，在那场战争中，整整一代人为了阻挡虫群而陨落。"},sec={{t="对抗阴影的护盾",b="甲虫之墙横贯沙漠东西，于千年前灾难性的流沙之战结束后矗立而起。在被其拉虫人逼近毁灭边缘后，暗夜精灵军队及其巨龙盟友将虫群赶回了它们古老的王国。为了永久封印它们，一道巨大的沙漠石壁拔地而起，上方笼罩着由青铜龙军团编织的宏大魔法屏障。这堵墙成功地将虫人军队与卡利姆多隔绝开来，尽管封印在石墙后的恐怖气息依然清晰可感。"},{t="被封印的废墟",b="在砂岩石工和巨龙结界之后，便是古其拉虫人的据点——安其拉。这堵墙是在流沙之战后为囚禁其军队而建的。使用流沙节杖敲响甲虫之锣便可打开它的大门，这是一件与巨龙和范达尔·鹿盔有关的圣物。"}},faq={{q="什么是甲虫之墙？",a="甲虫之墙是一道位于希利苏斯南缘的巨大石质魔法屏障。它的建立是为了封印古老的安其拉虫人王国，并将那些贪婪的虫群困在沙漠废墟之中。",al={"甲虫之墙的目的","希利苏斯的这堵墙是什么","安其拉之墙"}},{q="谁建造了甲虫之墙？",a="它是由暗夜精灵和青铜龙军团在流沙之战达到高潮时共同创造的。一道石墙封住了其拉虫人，而巨龙们在墙上投射了一道巨大的魔法屏障。",al={"谁建造了这堵墙","谁创造了甲虫之墙"}},{q="为什么要建造甲虫之墙？",a="为了结束流沙之战。在暗夜精灵及其巨龙盟友将其拉虫群赶回安其拉后，建造了这堵墙以将它们封印在内。",al={"为什么要建造甲虫之墙","甲虫之墙的用途"}},{q="玩家可以穿过这堵墙吗？",a="甲虫之墙是为了封印安其拉而建，但使用流沙节杖敲响甲虫之锣可以打开它的大门。",al={"能穿过甲虫之墙吗","如何穿过希利苏斯的墙"}}},fp="11,201,25.511.0,13.321.1,24.155.0,26.202.0,31.194.0,29.127.0"}
P.entries["subzone:scarlet-base-camp"] = {n="血色十字军营地",s="血色十字军营地是位于东瘟疫之地米雷达尔湖东岸的一处防御前哨，就在提尔之手以西。这里的路障标志着血色十字军的一处外围防御阵地。",h="血色十字军营地是位于东瘟疫之地米雷达尔湖东岸的一处防御前哨，就在提尔之手以西。这里的路障标志着血色十字军的一处外围防御阵地。",kw={"东瘟疫之地","米雷达尔湖","血色十字军营地","血色十字军","提尔之手"},ang={["class:Paladin"]="这座营地反映了白银之手遗产的可悲堕落，他们本应是为了捍卫洛丹伦圣地而产生的正义狂热，如今却已扭曲为针对其他幸存者的激进偏执。",["race:Undead"]="这个前哨站时刻提醒着人们，这些狂热者不仅无情地猎杀无脑的天灾军团，也同样希望将亡灵从洛丹伦彻底清除。"},sec={{t="米雷达尔湖的前线",b="血色十字军营地坐落在米雷达尔湖的东岸，是一座位于提尔之手西侧的加固工事。它标志着血色十字军在这片荒芜土地上的一处外围据点。"},{t="堡垒的屏障",b="提尔之手是血色十字军在洛丹伦的据点之一。这座营地位于其西侧的进军路线上，在这片区域中，十字军试图从亡灵手中收复失地，并对外来者持怀疑态度。"}},faq={{q="血色十字军营地的目的是什么？",a="这座营地是血色十字军在米雷达尔湖东岸的一处加固工事，就在提尔之手以西。",al={"什么是血色十字军营地","为什么血色十字军营地会在这里","营地的目的"}},{q="谁在指挥驻扎在营地的部队？",a="在最初的经典版游戏中，该营地没有明确的指挥官。它只是提尔之手附近的一处血色十字军阵地。",al={"谁领导血色十字军营地","营地指挥官","血色营地领导人"}},{q="营地里的人对旅行者怀有敌意吗？",a="血色十字军对两个阵营的外来者都持有敌意，认为他们可能是瘟疫的携带者或天灾军团的代理人。",al={"血色十字军营地会攻击我吗","血色营地有敌意吗","他们是友好的吗"}},{q="营地相对于米雷达尔湖的位置在哪里？",a="它矗立在米雷达尔湖的东岸，位于提尔之手以西。",al={"血色十字军营地 湖","血色营地在哪里","提尔之手附近的营地"}}},fp="17,147,31.160.0,21.208.0,45.121.0,43.115.0,39.131.0,47.85.0"}
P.entries["subzone:scarlet-basilica"] = {n="血色十字军教堂",s="血色十字军教堂是一座宏伟的大教堂，矗立在东瘟疫之地的提尔之手中心。它作为血色十字军在东部的精神和军事权力中心。在十字军领主瓦德玛的监督下，教堂大厅象征着这些狂热者对抗天灾军团的不屈堡垒。",h="血色十字军教堂是一座宏伟的大教堂，矗立在东瘟疫之地的提尔之手中心。它作为血色十字军在东部的精神和军事权力中心。在十字军领主瓦德玛的监督下，教堂大厅象征着这些狂热者对抗天灾军团的不屈堡垒。",kw={"大教堂","十字军领主瓦德玛","东瘟疫之地","血色十字军教堂","血色十字军","提尔之手"},ang={["class:Paladin"]="这座大教堂是一座扭曲的纪念碑，见证了虔诚信仰的误入歧途，昔日的白银之手骑士们将他们的热忱变成了冷酷的狂热。",["race:Undead"]="对于被遗忘者来说，这座大教堂是那些狂热分子最坚固的据点之一，他们积极寻求彻底根除所有的亡灵，无论其是否拥有自由意志。"},sec={{t="东方十字军的核心",b="血色十字军教堂矗立在提尔之手的防御堡垒之上，是血色十字军在东瘟疫之地行动的中央大教堂和指挥中心。虽然远在西边提瑞斯法林地的血色修道院是该组织的精神核心，但这座大教堂是他们抵御洛丹伦被瘟疫侵蚀的恐怖生物、仅存的领土据点。大教堂由精锐的十字军严密守卫，十字军领主瓦德玛在此坐镇，指挥当地防御，并狂热地清洗任何胆敢靠近的外来者。"}},faq={{q="血色十字军教堂是什么？",a="血色十字军教堂是位于东瘟疫之地提尔之手要塞城市内的大教堂。它是血色十字军在该地区的主要宗教和军事权力中心。",al={"血色十字军教堂信息","这是什么教堂","提尔之手教堂"}},{q="谁领导着教堂内的军队？",a="十字军领主瓦德玛指挥着血色十字军教堂内的军队，作为血色十字军的高级领导人之一，他驻守提尔之手，对抗天灾军团和其他被视为敌人的势力。",al={"血色十字军教堂里有谁","瓦德玛","血色十字军教堂首领"}},{q="这与血色修道院相比如何？",a="虽然提瑞斯法林地的血色修道院是该组织的主要精神总部，但血色十字军教堂是他们在东部的对应机构，在瘟疫之地深处提供了一个军事化的宗教指挥中心。",al={"修道院与教堂的区别","这是血色修道院吗"}},{q="旅行者在教堂内受欢迎吗？",a="不。血色十字军已经陷入了排外的疯狂，认为任何没有身穿他们深红色制服的人都受到了亡灵瘟疫的污染。无论是联盟还是部落的入侵者，都会在看到后立即受到攻击。",al={"联盟可以进入吗","血色十字军教堂是敌对的吗","我可以访问吗"}}},fp="16,187,28.397.0,29.167.0,41.185.0,47.191.0,42.164.0"}
P.entries["subzone:scarlet-monastery"] = {n="血色修道院",s="血色修道院坐落在提瑞斯法林地的东北丘陵中，这里曾经是圣光教会进行学术研究和礼拜的和平中心。在洛丹伦陷落之后，这里已经成为狂热的血色十字军重兵把守的堡垒。任何没有身着红色制服的人在接近这里时，都会被视为携带瘟疫的感染者并被当场处决。",h="血色修道院坐落在提瑞斯法林地的东北丘陵中，这里曾经是圣光教会进行学术研究和礼拜的和平中心。在洛丹伦陷落之后，这里已经成为狂热的血色十字军重兵把守的堡垒。任何没有身着红色制服的人在接近这里时，都会被视为携带瘟疫的感染者并被...",kw={"军械库","大教堂","墓地","图书馆","莫格莱尼","旧修道院","血色十字军","血色修道院","提瑞斯法林地","怀特迈恩"},ang={["class:Paladin"]="这座建筑群曾经在白银之手麾下训练圣骑士，因此它堕落成为一个充满偏执狂热的堡垒，令忠诚的圣光战士们感到痛心。",["faction:Horde"]="修道院就坐落在幽暗城的家门口，这使得其武装严密的十字军对被遗忘者的领土构成了实质性的生存威胁。"},sec={{t="从圣所到要塞",b="在第三次战争之前，这座建筑群是洛丹伦祭司阶层引以为傲的堡垒，曾是神学研究、圣物典藏和圣骑士训练的重要中心。当洛丹伦王国陷落于天灾军团之手时，幸存的守军在这里抵抗着亡灵的入侵。随着他们堕落为狂热的血色十字军，他们加固了修道院，将其宁静的图书馆、花园和教堂变成了一座武装堡垒。"},{t="狂热的堡垒",b="修道院分为四个不同的区域——亵渎的墓地、广阔的图书馆、军械库以及宏伟的大教堂。这里驻扎着由血色十字军指挥官莫格莱尼和大检察官怀特迈恩领导的庞大守军。这里的十字军将所有外来者，无论生者还是亡灵，联盟还是部落，都视为瘟疫携带者。虽然被遗忘者试图消除这支威胁到他们家门口的守军，但联盟领导层也越来越将十字军的暴力极端主义视为对圣光的一种危险扭曲。"}},faq={{q="为什么血色修道院会在这里？",a="它最初是在洛丹伦统治时期建造的，作为一个供人学习的宁静圣所，用于存放神圣的经文和训练圣骑士。在王国陷落后，幸存的十字军占领并加固了这里，将其作为在提瑞斯法林地对抗亡灵的军事集结地。",al={"什么是血色修道院","为什么在提瑞斯法建造修道院","修道院的用途"}},{q="为什么血色十字军会攻击联盟成员？",a="十字军的狂热已经演变成彻底的偏执。他们认为任何在他们严密防守的营地之外旅行过的人都可能是天灾瘟疫的携带者，因此他们拒绝在对待外来者时抱有侥幸心理，无论对方的种族或效忠对象为何。",al={"为什么血色十字军敌视联盟","血色十字军属于联盟吗","为什么十字军攻击人类"}},{q="谁在领导修道院内的部队？",a="修道院的守军由血色十字军指挥官莫格莱尼和血色十字军指挥官莫格莱尼共同领导，前者在大教堂内指挥军事行动，后者是一位以虔诚和复活能力而闻名的狂热女祭司。",al={"谁是血色修道院的首领","修道院领导者","谁在这里领导血色十字军"}},{q="这座建筑群的四个区域分别是什么？",a="该建筑群被分为四个不同的区域：墓地，那里充斥着躁动的亡灵和刑讯室；图书馆，保存着历史档案和书籍；军械库，十字军在此制造武器和盔甲；以及大教堂，那是精神核心和指挥官的驻地。",al={"修道院分区","血色修道院有哪些区域","修道院布局"}}},fp="17,290,28.416.0,23.461.0,34.245.0,53.244.0,42.216.0,39.243.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Scarlet Monastery Armory",s="武器库是血色修道院的军事强化侧翼，专门用于为血色十字军制造武器和训练新兵。在锁住的铁门后，成群狂热的步兵和十字军在血色冠军赫洛德的严厉指挥下进行演练。",h="武器库是血色修道院的军事强化侧翼，专门用于为血色十字军制造武器和训练新兵。在锁住的铁门后，成群狂热的步兵和十字军在血色冠军赫洛德的严厉指挥下进行演练。",kw={"武器库","十字军武器库","步兵武器库","勇士大厅","赫洛德","血色冠军","血色十字军钥匙","血色修道院武器库"},ang={["class:Warrior"]="武器库是冷兵器格斗的典型试验场，血色战士们在这里演示致命的架势、缴械技巧以及赫洛德那著名的旋风斩技术。",["faction:Horde"]="随着血色十字军在幽暗城大门外集结军队，掠夺他们的军械并屠杀他们的冠军对于被遗忘者的生存至关重要。"},sec={{t="狂热铸造厂",b="修道院曾经是洛丹伦牧师们的一处静修之地，但在第三次战争后被彻底改造。武器库现在作为十字军的主要锻造厂、武器仓库和战斗试验场。从露天训练场到深处的武器大厅，成群的血色步兵、法师和十字军不断进行演练，准备肃清天灾军团以及任何他们认为被玷污的人。该侧翼与Grand Vestibule之间保持封闭，只有携带在邻近图书馆中发现的血色十字军钥匙的人才能进入。"},{t="Hall of Champions",b="武器库中心坐落着Hall of Champions，两旁矗立着纪念十字军历史上传奇英雄的高大雕像。该大厅由赫洛德负责监管，他是一位残暴的战士，以其凶猛和旋风斩在十字军中闻名。赫洛德亲自训练下一代狂热者；当战斗陷入苦战时，他那些绝望的新兵会涌入大厅，为他们的冠军而战并献出生命。"}},faq={{q="如何进入武器库？",a="大门廊里的武器库大门紧锁。要打开它，你必须进入图书馆侧翼，从图书馆奥法师杜安身后的箱子里取回血色十字军钥匙，或者带上一位开锁技能足够高的潜行者。",al={"武器库上锁","如何解锁武器库","武器库血色十字军钥匙","打开武器库大门"}},{q="谁在武器库中统领部队？",a="该侧翼由被称为血色冠军的赫洛德指挥。他驻守在勇士大厅内，负责操练士兵并让新加入的征召兵接受高强度的战斗考验。",al={"武器库首领","谁负责武器库","谁管理武器库","赫洛德武器库"}},{q="这个侧翼对血色十字军有什么用途？",a="它作为十字军的主要军械库和训练学院。建筑群内设有大型武器锻造厂、步兵和十字军的装备库，以及用于在将士兵派往提瑞斯法和瘟疫之地前进行体能训练的户外操练场。",al={"武器库存在目的","他们在这里做什么","武器库用途"}},{q="勇士大厅里纪念的是谁的雕像？",a="这些雕像纪念的是该组织最受推崇的殉道者和英雄，在训练新兵进行反抗亡灵的战争时，十字军们常会引用这些冠军的事迹。",al={"武器库雕像","勇士大厅雕像","赫洛德房间里的雕像"}}},fx={["469efc8f"]={q="什么是血色修道院军械库？",a="武器库是位于提瑞斯法林地的血色修道院建筑群内一处戒备森严的区域。这里曾是洛丹伦牧师团用于虔诚崇拜和研习圣光的场所，如今则成为血色十字军激进战士的训练营房、武器库和集结地。",al={"什么是武器库","血色修道院武器库背景","武器库介绍"}},cd55d42c={q="武器库发生了什么？",a="第三次战争期间，天灾军团蹂躏了洛丹伦，席卷这片地区，将这座宁静的学府变成了孤注一掷的堡垒。幸存的神职人员和士兵逐渐激进化，组建了血色十字军。他们武装自己，将此地筑成坚不可摧的堡垒，誓要消灭任何他们怀疑染上瘟疫的人。",al={"武器库历史","武器库发生了什么","血色修道院武器库背景"}},edfdc72e={q="武器库危险吗？",a="这里极其危险。大厅里挤满了狂热的十字军士兵、步兵和受过见人便杀训练的战斗法师。十字军认为所有外来者都可能是天灾瘟疫的携带者，因此任何闯入训练场或大厅的人，都会遭遇纪律严明、战斗到底的士兵。",al={"武器库有多危险","武器库安全吗","武器库威胁"}}},fp="24,157,19.434.0,21.345.0,33.196.0,35.147.0,57.213.0,51.153.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Scarlet Monastery Cathedral",s="大教堂是血色修道院的精神与军事核心，也是血色十字军的圣所所在。这里曾经是洛丹伦祭司们宁静的礼拜殿堂，如今却成了大检察官怀特迈恩和血色十字军指挥官莫格莱尼的指挥中心，由十字军中最虔诚的狂热者守卫。",h="大教堂是血色修道院的精神与军事核心，也是血色十字军的圣所所在。这里曾经是洛丹伦祭司们宁静的礼拜殿堂，如今却成了大检察官怀特迈恩和血色十字军指挥官莫格莱尼的指挥中心，由十字军中最虔诚的狂热者守卫。",kw={"大教堂","礼拜堂庭院","十字军大教堂","大检察官","莫格莱尼","血色修道院","怀特迈恩"},ang={["faction:Alliance"]="对联盟而言，十字军代表着对圣光和洛丹伦光荣传统的悲剧性扭曲，这促使南海镇的指挥官们派遣勇士前去终结他们的疯狂。",["faction:Horde"]="大教堂坐落于幽暗城附近，极其危险，这里聚集着致力于彻底铲除被遗忘者及其任何部落盟友的狂热者。"},sec={{t="狂热圣所",b="大教堂曾是洛丹伦祭司们启迪心智与祈祷的宁静中心，但在第三次战争之后陷入了疯狂。随着王国在天灾军团的铁蹄下沦陷，幸存的狂热者将这一建筑群改造成了一座充满不屈仇恨的堡垒。穿过修葺整齐的礼拜堂庭院，便是宏伟的十字军大教堂，祭司和战士们聚集于此，向他们的十字军事业表达忠诚。他们视所有外来者——无论其种族或阵营——为亡灵瘟疫的携带者，必须用刀剑和圣火予以净化。"},{t="大检察官与她的指挥官",b="驻扎在大教堂内的部队直接听命于血色十字军指挥官莫格莱尼，他以铁腕纪律管理着守军。然而，该据点狂热信仰的核心是大检察官怀特迈恩。作为一名强大的圣光使用者，怀特迈恩虔诚的信仰使她能在激战中复活阵亡的勇士。她与莫格莱尼共同守卫着内殿，阻挡任何胆敢闯入修道院大门的人，证明了血色十字军对北洛丹伦的控制依然坚不可摧。"}},faq={{q="大教堂的用途是什么？",a="它是血色十字军在血色修道院内的内堡和神圣的高层指挥所。在这里，该组织最高领导人主持宗教仪式，并指挥他们在整个提瑞斯法林地的军事行动。",al={"大教堂用途","为什么要参观大教堂","这是什么地方"}},{q="谁在这里领导血色十字军？",a="守军由血色十字军指挥官莫格莱尼指挥，而精神领袖则是大检察官怀特迈恩，一位令人敬畏且狂热的女祭司。",al={"这里的首领是谁","大教堂首领","怀特迈恩 莫格莱尼"}},{q="为什么大教堂的门锁着？",a="通往大教堂侧厅的沉重铁门被锁上，是为了防止入侵者冲击圣所。进入需要血色十字军钥匙，该钥匙由修道院图书馆侧厅内的守卫看管。",al={"大教堂门锁","如何进入大教堂","钥匙在哪里"}},{q="为什么十字军要攻击其他活着的凡人？",a="受天灾军团毁灭洛丹伦的影响而陷入妄想，血色十字军坚信所有外来者都是亡灵瘟疫的携带者。他们拒绝与外部阵营接触，并处决任何靠近其堡垒的人。",al={"为什么要攻击联盟","血色十字军邪恶","为什么十字军敌对"}}},fx={["9962382e"]={q="什么是血色修道院大教堂？",a="大教堂是提瑞斯法林地血色修道院建筑群的核心，也是其中最宏伟的部分。这里曾是备受尊崇的洛丹伦牧师团圣所，致力于求知和精神启迪，如今则成为血色十字军狂热分子的至圣之所和指挥中心。",al={"什么是大教堂","血色大教堂","大教堂区域"}},d9fd8161={q="血色修道院大教堂发生了什么？",a="第三次战争之前，这座宁静的修道院是洛丹伦圣光信仰的骄傲堡垒，致力于研习与救治。当天灾军团席卷王国时，幸存的守卫加固了这处圣地，将宁静的大厅和庭院改造成一座戒备森严的要塞，充斥着偏执与狂热的仇恨。",al={"大教堂历史","这里发生了什么","修道院往事"}},["09ab4f6a"]={q="血色修道院大教堂危险吗？",a="这里远比修道院其他区域危险。穿过庭院，便是一座宏伟的礼拜堂，里面挤满了精锐十字军、虔诚的修士和致命的术士。守卫们怀着狂热的怒火作战，闯入者将面对指挥官莫格莱尼与强大的大检察官怀特迈恩联手出击。",al={"大教堂危险吗","这里安全吗","大教堂有多危险"}}},fp="27,89,15.450.0,37.401.1,31.195.0,35.143.0,40.143.0,52.181.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {n="Scarlet Monastery Graveyard",s="Scarlet Monastery Graveyard是位于提瑞斯法林地东北部的宏大宗教建筑群中的墓地区域。曾经是洛丹伦神职人员和贵族的宁静安息之所，如今却陷入了令人不寒而栗的荒废中，被徘徊的亡灵和骷髅血法师萨尔诺斯所腐化的魔法所占据。",h="Scarlet Monastery...",kw={"忏悔室","遗忘回廊","墓地苔","墓地","荣耀之墓","血色修道院","萨尔诺斯"},ang={["profession:Herbalism"]="Forlorn Cloister潮湿、被玷污的土壤是北洛丹伦采集墓地苔最可靠的来源之一。",["race:Undead"]="被遗忘者的施法者和药剂师将这座墓地视为十字军虚伪的残酷证明：这群狂热分子谴责被遗忘者，而一个亡灵血法师却在他们的地下室里腐烂。"},sec={{t="一个被玷污的圣所",b="在第三次战争之前，这座修道院式墓地曾是洛丹伦神职人员宁静的安息之所。当血色十字军为了抵御亡灵而加固这座修道院时，他们狂热的警惕性却未能净化他们自己的地下墓穴。如今，这座墓地被废弃并深深地受到诅咒。徘徊的幽灵、不安的尸体和蹒跚的恐怖生物游荡在Chamber of Atonement和雾气缭绕的Forlorn Cloister中。死者在这里没有得到神圣的安息，却在十字军漠不关心的注视下遭受着无尽的折磨。"},{t="内部的腐化",b="在墓地后方矗立着Honor's Tomb，那里滋生着对十字军教条最大的嘲弄：血法师萨尔诺斯。没有任何记录说明他生前是谁，但他死于亡灵瘟疫，并作为施展暗影箭和火焰魔法的骷髅怪物复活。上面的十字军宣扬要彻底根除亡灵瘟疫，却在他们自己神圣的土地上包庇着一个腐烂堕落的施法者。"}},faq={{q="为什么血色十字军的据点里会有亡灵？",a="十字军的领导层沉迷于狂热之中，指挥着他们的十字军向外杀戮活着的局外人，并在提瑞斯法进行战争。因此，修道院的地下墓穴和墓葬区被彻底忽视，这使得残留的瘟疫和死去的教士们不安的灵魂得以在无人阻挡的情况下复活。",al={"为什么血色修道院墓地有亡灵","血色修道院里的亡灵","为什么这里有鬼魂"}},{q="血法师萨尔诺斯是谁？",a="关于萨尔诺斯生前是谁并无记载。亡灵瘟疫夺走了他的生命，他作为一名骷髅施法者复活，现在统治着荣誉之墓那被亵渎的地下墓穴。",al={"萨尔诺斯背景故事","血法师萨尔诺斯是谁","墓地首领"}},{q="墓地区域位于修道院内的什么位置？",a="进入血色修道院的大门廊后，墓地的入口是最左侧的副本传送门。与军械库和大教堂区域不同，进入它不需要钥匙。",al={"血色修道院墓地在哪里","如何找到墓地区域","哪扇门是墓地"}},{q="什么是遗忘回廊？",a="遗忘回廊是位于入口墓穴和荣誉之墓之间的露天花园和墓地。那里散落着墓碑，游荡着食尸鬼，泥土中长满了墓地苔。",al={"凄凉回廊","墓地庭院"}}},fx={["2ee90fec"]={q="什么是血色修道院墓地？",a="这里是血色修道院建筑群最左侧的区域，位于提瑞斯法林地东北部。它曾是洛丹伦圣职团的墓地和地下墓穴，如今已腐化、荒废，遍布墓穴、陵墓和不得安息的亡者。",al={"什么是墓园","墓园区域","血色墓园"}},d7efe218={q="血色修道院墓地发生了什么？",a="这里原本是洛丹伦受尊崇的牧师和勇士安息的宁静之地。修道院为抵御天灾军团而加固后，墓园便落入血色十字军控制之下。埋葬于此的尸体非但没有安息，反而开始化为亡灵复起，十字军只得将这片受污染的墓地封锁起来。",al={"墓园历史","这里发生了什么","墓园的由来"}},["35b34413"]={q="谁控制着血色修道院墓地？",a="虽然十字军声称控制着整座修道院建筑群，但墓园区域大多已被遗弃，任由躁动的亡灵盘踞。堕落的法师萨尔诺斯如今化作嗜血的骷髅施法者，盘踞在最深处的墓穴中，统领着散布各处的食尸鬼、鬼魂和游荡的亡者。",al={"谁管理墓园","这里由谁负责","墓园首领"}},c4dc5010={q="为什么血色修道院墓地荒废破败？",a="十字军狂热的圣光之力也无法阻止天灾瘟疫亵渎他们的亡者。他们无法彻底净化复起的尸体，活着的十字军只好撤回戒备森严的礼拜堂和武器库，任由墓地杂草丛生，被复生的尸体占据。",al={"墓园为何破败","为何被遗弃","为何荒废"}},["2daa3a11"]={q="血色修道院墓地危险吗？",a="是的。这里的组织程度不及占据修道院其他区域的武装力量，但墓园中满是凶猛的亡灵、恶毒的灵体和黑暗施法者，例如血法师萨尔诺斯。他们会无情地攻击任何擅闯墓地的活人。",al={"墓园危险吗","墓园中的危险","墓园有多危险"}},cfbfb429={q="为什么叫血色修道院墓地？",a="这里是血色修道院专用的墓地和陵园，其中有古老的地下墓穴、荣誉之墓一类的陵墓，以及遗忘回廊——洛丹伦的圣职守卫传统上安葬于此。",al={"为何叫墓园","墓园名称","为何叫血色修道院墓园"}}},fp="27,213,19.474.0,22.371.0,57.296.0,25.162.0,57.159.0,29.181.0"}
P.entries["subzone:scarlet-monastery-library"] = {n="Scarlet Monastery Library",s="图书馆是提瑞斯法林地血色修道院的东翼，曾经致力于神圣学术和洛丹伦的牧师事业。如今这里由战犬和狂热者守卫，收藏着珍贵的古籍和文献，令两个阵营的学者和法师垂涎不已。",h="图书馆是提瑞斯法林地血色修道院的东翼，曾经致力于神圣学术和洛丹伦的牧师事业。如今这里由战犬和狂热者守卫，收藏着珍贵的古籍和文献，令两个阵营的学者和法师垂涎不已。",kw={"奥法师杜安","雅典娜神殿","堕落者纲要","驯犬者洛克希","图书馆","血色十字军钥匙","血色修道院","提瑞斯法林地"},ang={["class:Mage"]="雅典娜神殿是那些寻求远古能量仪祭并希望通过挑战奥法师杜安的毁灭性奥术来磨练自身能力的雄心勃勃的法师们必须朝圣之地。",["faction:Alliance"]="图书馆保存着洛丹伦阵亡英雄的神圣记录和泰坦历史，这些都是铁炉堡的探险者大厅迫切希望从十字军手中夺回的资料。"},sec={{t="洛丹伦档案馆",b="第三次战争前，这座修道院是洛丹伦牧师学习和启迪的中心。东侧的回廊中收藏着浩如烟海的宗教思想、历史记录和奥术论著。当血色十字军为了防御天灾军团而加固修道院时，他们保留了这些藏书库，并将安静的厅堂变成了一座武装堡垒。如今，驯兽师带着追踪犬在庭院中巡逻，战斗法师在书架间往来，守卫着《堕落者纲要》等历史卷宗以及关于泰坦的远古研究，防范外来者。"},{t="雅典娜神殿的守卫者",b="想要闯入图书馆，必须穿过狩猎者回廊，避开驯犬者洛克希，他驯养的猎犬会嗅出试图进入内室的潜入者。在Gallery of Treasures之后便是雅典娜神殿，由奥法师杜安监管。杜安是一位强大的法师，擅长施展毁灭性的火焰和防护奥术，他隐居于此进行研究，顽强地守卫着十字军私藏的知识，抵御任何敢于深入建筑群核心的人。"}},faq={{q="图书馆位于血色修道院的什么位置？",a="当你进入提瑞斯法林地血色修道院建筑群的大门廊时，可以通过最右侧的副本入口进入图书馆区域。",al={"图书馆入口","哪扇门是图书馆","如何找到图书馆区域"}},{q="为什么冒险者会被派往图书馆？",a="联盟和部落的学者、牧师和法师都在寻找保存在其高墙内的珍贵文献。重要的目标包括《堕落者纲要》、铁炉堡历史学家寻求的泰坦传说，以及供进阶奥法师研习的远古魔法手册。",al={"为什么要前往图书馆","图书馆任务","图书馆里有什么"}},{q="谁统治着图书馆区域？",a="图书馆的内圣所，即雅典娜神殿，由血色十字军强大的施法者奥法师杜安统领。外庭院则由驯犬者洛克希和他的凶猛追踪兽负责守卫。",al={"图书馆首领","谁在管理图书馆","谁领导图书馆"}},{q="这里能找到什么血色十字军钥匙？",a="奥法师杜安的雅典娜神殿中的一个锁盒里装着血色十字军钥匙，这是打开沉重的铁门，进入修道院军械库和教堂区域所必需的。",al={"杜安钥匙","血色十字军钥匙掉落","血色十字军钥匙在哪里"}}},fx={["10860e43"]={q="什么是血色修道院图书馆？",a="图书馆是提瑞斯法林地血色修道院广阔建筑群最右侧的区域。这里曾是洛丹伦安静的研习和神职启蒙中心，如今则收藏着血色十字军搜集的典籍、军事珍宝，并设有猎犬犬舍。此区域分为猎手回廊、珍宝陈列室和雅典娜神殿。",al={"什么是图书馆","血色图书馆区域","修道院图书馆概况"}},["05144c18"]={q="血色修道院图书馆发生了什么？",a="图书馆原本是洛丹伦牧师团引以为傲的堡垒之一，致力于求知、神学研究和启迪。第三次战争期间，亡灵天灾军团席卷王国，幸存的人类狂热分子加固了整座建筑群。他们将原本宁静、收藏书籍与圣洁知识的场所，改造成血色十字军的武装据点。",al={"血色修道院图书馆历史","图书馆往事","这里发生了什么"}},a62144f3={q="血色修道院图书馆危险吗？",a="这里极其危险。图书馆由狂热的血色士兵、牧师和战斗法师驻守，他们视所有外来者为必须当场铲除的天灾瘟疫携带者。闯入者必须先击败驯犬者洛克希指挥的受训攻击猎犬，之后还要面对内侧雅典娜神殿中奥法师杜安施展的致命法术。",al={"血色修道院图书馆危险吗","图书馆中的威胁","图书馆有多危险"}}},fp="25,174,21.461.0,26.400.0,50.128.0,40.230.0,27.143.0,35.138.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Scarlet Raven Tavern",s="血鸦旅店是夜色镇的社交中心和主要旅店，在暮色森林的阴霾中提供了一处炉火边的避难所。旅店老板斯密茨坐镇于此，这里也是饱受困扰的当地人、过往的冒险者以及试图逃离城镇周边恐怖威胁的惊恐旅人们的聚集地。",h="血鸦旅店是夜色镇的社交中心和主要旅店，在暮色森林的阴霾中提供了一处炉火边的避难所。旅店老板斯密茨坐镇于此，这里也是饱受困扰的当地人、过往的冒险者以及试图逃离城镇周边恐怖威胁的惊恐旅人们的聚集地。",kw={"夜色镇","暮色森林","黑蟹蛋糕","哈加德","基特斯","血鸦旅店","斯密茨","旅店老板斯密茨"},ang={["faction:Alliance"]="对于穿越南部边界的联盟旅行者来说，血鸦旅店提供了在艾尔文森林和逆风小径之间为数不多的安全炉火和休息站之一。",["profession:Cooking"]="旅店的菜单上提供诸如黑蟹蛋糕之类的当地美食，这是一种当地主食，即使是像基特斯这样躲在墓地里的绝望流浪者也对其垂涎三尺。"},sec={{t="昏暗的避难所",b="血鸦旅店位于夜色镇的中心附近，当永恒的暮色笼罩着周围的森林时，旅店依然点燃着炉火。多年前，这里曾是一个热闹的歇脚点，哈加德元帅和暴风城卫队在巡逻后会在这里共饮。如今，随着城镇治安的恶化，生意也日渐萧条。旅店老板斯密茨为一群在寒冷与恐惧中蜷缩的阴郁、焦虑的顾客提供服务。即便如此，这家旅店仍然是搜集传闻不可或缺的交汇点，也是那些试图寻找困扰该地区的黑暗现象真相的旅人们的出发点。"},{t="秘密与被窃取的麦酒",b="除了作为避难所，这家旅店还隐藏着几起谜案的线索。隐居的流浪者基特斯曾在这里租住多日，他每天夜里疯狂地在日记中记录，随后在恐怖的黑暗骑士到达前逃离了城镇。旅店屋檐下保存的数十年前的城镇八卦和客房记录，也指向了斯塔文·密斯特曼托等早已被遗忘的人物，这使得斯密茨的酒吧成为了好奇的调查者在追寻暮色森林那些不安的亡者历史时的首选之地。"}},faq={{q="谁经营着血鸦旅店？",a="旅店老板斯密茨是这家旅店的经营者。此外，旅店还有其他工作人员为夜色镇的旅客服务。",al={"夜色镇旅店老板","谁拥有血鸦旅店","旅店老板斯密茨"}},{q="为什么旅店的氛围如此阴郁？",a="笼罩在暮色森林上的诅咒阻塞了贸易路线，令当地人感到恐惧。由于亡灵、野性狼人以及阴影骑士在林间游荡，顾客多是惊恐的镇民和绝望的佣兵，而非无忧无虑的游客。",al={"为什么血鸦旅店让人沮丧","夜色镇旅店氛围"}},{q="基特斯住在血鸦旅店吗？",a="基特斯确实住在旅店，他在逃离城镇前曾在日记中疯狂书写。通过对暮色森林的调查，可以揭开他这样做的原因。",al={"基特斯的房间","基特斯的旅店","基特斯住在这里吗"}},{q="这家旅店与斯塔文传说有什么联系？",a="旅店内存放的老主顾和往昔城镇记录包含了关于斯塔文·密斯特曼托的线索，他在陷入悲剧并声名狼藉之前，曾频繁出入于此。",al={"斯塔文与旅店的联系","斯塔文·密斯特曼托夜色镇旅店"}}},fp="20,215,12.518.0,24.371.1,34.112.0,41.227.0,38.164.0,63.173.0"}
P.entries["subzone:scarlet-watch-post"] = {n="血色十字军哨岗",s="血色十字军哨岗是一座位于提瑞斯法林地东北部岩石丘陵中的孤立瞭望塔，位于血色修道院的正北方。它由一支警惕的十字军卫戍部队驻守，其唯一目的就是保卫修道院脆弱的北翼，防止侧翼攻击。",h="血色十字军哨岗是一座位于提瑞斯法林地东北部岩石丘陵中的孤立瞭望塔，位于血色修道院的正北方。它由一支警惕的十字军卫戍部队驻守，其唯一目的就是保卫修道院脆弱的北翼，防止侧翼攻击。",kw={"麦拉其队长","十字军前哨","血色十字军","血色修道院","血色十字军哨岗","提瑞斯法林地"},ang={["faction:Horde"]="十字军将所有外来者——无论生死——都视为被亡灵瘟疫污染的携带者，因此对于任何冒险进入这些丘陵的部落旅行者来说，这个哨岗是绝对的敌对区域。",["race:Undead"]="对于被遗忘者来说，血色十字军是一个盘踞在幽暗城家门口的生存威胁；清除像这样的孤立塔楼可以破坏这些狂热分子的通讯网络，并确保提瑞斯法北部的安全。"},sec={{t="守卫北部通道",b="血色十字军哨岗矗立在血色修道院后方的崎岖高地上，是修道院狂热者们关键的早期预警堡垒。虽然通往修道院大门的南部道路交通繁忙且防御严密，但提瑞斯法北海岸线沿途崎岖的悬崖却为潜入者提供了一条诱人的后路。为了消除这一盲点，血色十字军维护着这座坚固的石塔——这是散布在提瑞斯法林地的数个十字军前哨站之一。在麦拉其队长的严厉指挥下，由新兵、先锋和虔诚的修士组成的混合部队在悬崖上日夜守望，确保天灾军团和被遗忘者无法从后方突袭该组织。"}},faq={{q="血色十字军哨岗的目的是什么？",a="该哨岗保护血色修道院免受侧翼攻击。虽然修道院的正门朝向南方的提瑞斯法道路，但其后方斜坡朝向北部荒野，使其容易受到协调一致的攻击。这座哨岗确保了哨兵能够发现并拦截任何试图从北部绕行的入侵者。",al={"为什么血色十字军哨岗会在这里","血色十字军哨岗的目的","十字军的角色"}},{q="谁在指挥血色十字军哨岗？",a="麦拉其队长负责监管驻扎在塔楼的卫戍部队。他指挥着一支防御性随从队伍，包括私人保镖、前线先锋、有抱负的新兵以及施法的修士。",al={"血色十字军哨岗的领袖","谁领导血色十字军哨岗","麦拉其队长"}},{q="血色十字军哨岗与提瑞斯法的其他塔楼有关系吗？",a="是的。它是环绕提瑞斯法林地北部和西部区域的四个独立的十字军前哨站之一。这些石塔构成了一道防御周界，用于监视天灾军团的活动并遏制被遗忘者从幽暗城扩张。",al={"提瑞斯法塔楼","提瑞斯法的十字军前哨站","其他血色十字军塔楼"}}},fp="18,165,30.539.0,46.241.0,36.159.0,66.229.0"}
P.entries["subzone:scholomance"] = {n="通灵学院",s="通灵学院深藏在凯尔达隆地下的墓穴中，是天灾军团首屈一指的黑暗技艺与通灵术学院。在这里，凡人与亡灵一同在黑暗院长加丁那残酷的指导下，以及巫妖莱斯·霜语那警惕的目光注视下，学习亡灵瘟疫与血肉塑形术。",h="通灵学院深藏在凯尔达隆地下的墓穴中，是天灾军团首屈一指的黑暗技艺与通灵术学院。在这里，凡人与亡灵一同在黑暗院长加丁那残酷的指导下，以及巫妖莱斯·霜语那警惕的目光注视下，学习亡灵瘟疫与血肉塑形术。",kw={"巴罗夫","凯尔达隆","诅咒神教","黑暗院长加丁","克尔苏加德","通灵术","莱斯·霜语","通灵学院"},ang={["class:Mage"]="通灵学院内教授的扭曲课程代表了对奥术学术的彻底扭曲，在这里，对魔法理论的探究已被腐朽、阴影和邪恶的亵渎所取代。",["race:Undead"]="被遗忘者施法者们以冷漠的熟悉感和厌恶感看待通灵学院；天灾军团最卑劣的奴役与生物战手段中，有许多就是在这些教室里完善的。"},sec={{t="毁灭契约",b="在第三次战争之前，凯尔达隆是巴罗夫家族引以为傲的宅邸，这是一个在洛丹伦拥有广袤土地的富有贵族王朝，其领地包括布瑞尔、塔伦米尔和南海镇。巴罗夫家族因害怕失去财富与生命，屈服于克尔苏加德那永恒生命的诱惑。他们将自己的堡垒与家族陵墓割让给了The Cult of the Damned，而后者随即通过屠杀这些贵族并将广阔的地下墓穴改造成隐藏的亡灵法术训练场，作为对他们的“报答”。"},{t="通灵术学校",b="在凯尔达隆那闹鬼的地表废墟之下，坐落着一个繁荣的天灾军团工业中心。在这些潮湿的大厅里，早期的瘟疫菌株曾在巴罗夫家族的仆人身上进行过测试。今天，凡人侍僧们蜂拥至此，在院长黑暗院长加丁和冰冷的哨兵莱斯·霜语的监督下磨练他们对黑暗魔法的掌控，而巴罗夫家族那不得安息的亡灵残骸仍在永恒的折磨中徘徊。"}},faq={{q="通灵学院是什么？",a="通灵学院是一所由诅咒神教和天灾军团开办的秘密通灵术学院。它位于凯尔达隆岛屿堡垒的地下，是凡人通灵师、瘟疫研究员和血肉塑形师的训练设施。",al={"这里是什么地方","通灵学院背景故事","通灵学院介绍"}},{q="谁拥有凯尔达隆和这些地下墓穴？",a="这座城堡最初属于巴罗夫家族，这是洛丹伦最富有的贵族家族之一。他们为了寻求永生，将祖居之地交给了克尔苏加德，结果却在自己的大厅中被杀害并复活成了亡灵奴仆。",al={"谁拥有这里","巴罗夫家族"}},{q="现在谁在管理这所学院？",a="黑暗院长加丁担任这所学校阴险的凡人院长，负责监督教学与折磨。代表天灾军团的巫妖莱斯·霜语也在此地严密守卫。",al={"谁是首领","谁领导通灵学院","院长"}},{q="这里开发了什么恐怖的东西？",a="通灵学院是诅咒神教早期的试验场。当侍僧们在大厅里学习技艺时，邪教徒们会在巴罗夫家的仆人身上测试亡灵瘟疫的各种原型变体。",al={"这里制造了什么","通灵学院的实验","憎恶"}}},fp="11,177,14.451.0,24.367.1,20.162.0,36.293.0,25.169.0,33.182.0"}
P.entries["subzone:scholomance-classic"] = {n="Scholomance (Classic)",s="通灵学院是一所隐藏在西瘟疫之地凯尔达隆地下墓穴中的地下通灵术学院。它由克尔苏加德和The Cult of the Damned建立，是天灾军团训练那些寻求掌握死亡之力的凡人施法者的首要场所。",h="通灵学院是一所隐藏在西瘟疫之地凯尔达隆地下墓穴中的地下通灵术学院。它由克尔苏加德和The Cult of the Damned建立，是天灾军团训练那些寻求掌握死亡之力的凡人施法者的首要场所。",kw={"巴罗夫","凯尔达隆","诅咒神教","加丁","通灵术","莱斯·霜语","通灵学院"},ang={["class:Mage"]="通灵学院是对达拉然学术传统的怪诞歪曲，它展示了当肯瑞托的专业知识完全转向通灵术和腐朽时会发生什么。",["class:Paladin"]="对于白银之手骑士团的骑士们来说，净化凯尔达隆下被玷污的大厅是一项紧迫的职责，这是直接打击天灾军团凡人领导层的源头。"},sec={{t="墓穴中的学院",b="在第三次战争摧毁洛丹伦之前，叛逆的大法师克尔苏加德正为他的The Cult of the Damned招募成员。他从凯尔达隆的领主，富有的巴罗夫家族那里找到了愿意资助他的人，他们用自己的土地和墓穴换取了永生的承诺。然而，该教派不仅没有兑现承诺，反而屠杀了他们，并将他们复活为可怕的亡灵。在废墟要塞之下，该教派将古老的阿拉索地下墓穴改造成了一所黑暗艺术学院。在这里，凡人侍僧们远离人们的视线，研究瘟疫学、灵魂绑定和血肉塑形，磨练那些摧毁了洛丹伦的邪恶魔法。"},{t="巫妖与院长",b="虽然克尔苏加德已经转而在上方指挥天灾军团的行动，但这所学校依然在全面运作。永恒的巫妖莱斯·霜语以天灾军团的名义守护着这里，而凡人死灵法师黑暗院长加丁则担任院长，指导雄心勃勃的术士们进行可怕的实验。那些表现出软弱的学生会被丢弃到地下墓穴中，喂给潜伏在下层拱顶里的贪婪尸妖——拉文尼亚。"}},faq={{q="什么是通灵学院？",a="通灵学院是由诅咒神教运营的一所秘密通灵术学院。它坐落在凯尔达隆岛屿要塞深处的地下墓穴中，负责培训凡人施法者掌握天灾军团的黑暗艺术。",al={"这里是什么地方","通灵学院背景故事","通灵学院介绍"}},{q="现在是谁在统治通灵学院？",a="巫妖莱斯·霜语代表天灾军团监督着这座要塞，但凡人的事务和教学工作由学校冷酷的院长黑暗院长加丁负责指挥。",al={"谁领导通灵学院","谁在负责","通灵学院首领"}},{q="天灾军团是如何得到凯尔达隆的？",a="第二次战争后，高贵的巴罗夫家族一直把守着这座要塞。在克尔苏加德永生承诺的诱惑下，他们将自己的祖居和墓穴转让给了诅咒神教。该教派通过屠杀巴罗夫家族成员并将他们转化为亡灵的方式，“完成”了这笔交易。",al={"巴罗夫家族背景","凯尔达隆的主人是谁","诅咒教派如何获得通灵学院"}},{q="为什么学校大门是锁着的？",a="那扇巨大的铁门被封印起来，是为了保护学院的研究成果和召唤师免受入侵者的干扰。打开这扇门需要骷髅钥匙，这种钥匙是通过跨越整个瘟疫之地的复杂仪式锻造而成的。",al={"通灵学院大门紧锁","如何进入通灵学院","通灵学院骷髅钥匙"}}},fp="21,172,21.582.0,19.425.0,20.137.0,26.141.0,40.201.0,25.191.0"}
P.entries["subzone:screaming-gully"] = {n="Screaming Gully",s="Screaming Gully是穿过哀嚎洞穴入口后遇到的第一个广阔地下洞穴。这里沐浴在不自然的真菌微光和浅水中，作为堕落的尖牙德鲁伊及其变异野兽的外围据点。",h="Screaming Gully是穿过哀嚎洞穴入口后遇到的第一个广阔地下洞穴。这里沐浴在不自然的真菌微光和浅水中，作为堕落的尖牙德鲁伊及其变异野兽的外围据点。",kw={"贫瘠之地","变异迅猛龙","尖牙领主","克雷什","安娜科德拉","尖啸峡谷","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，Screaming Gully展现了他们堕落兄弟们令人心碎的一面，他们放弃了爪与翼的道路，拥抱了蛇形的腐化。"},sec={{t="梦魇的门槛",b="跨入哀嚎洞穴的门槛，便直接进入了Screaming Gully，这是一个回声阵阵的深渊，风在地下裂隙中哀鸣。这里与上方干旱的贫瘠之地截然不同，沟壑中充斥着潮湿的植被、潮湿的雾气，以及被翡翠梦魇扭曲的凶猛野生生物。尖牙领主安娜科德拉掌管着此洞室，周围环绕着尖牙德鲁伊的侍僧和凶残的变异迅猛龙，而像克雷什这样的古老龟类则在下方浅水中巡游。"}},faq={{q="尖啸谷位于哪里？",a="尖啸谷是穿过哀嚎洞穴内的传送门后进入的第一个主要洞室，位于北贫瘠之地下方。",al={"尖啸谷位置","尖啸谷在哪里","如何找到尖啸谷"}},{q="为什么它被称为尖啸谷？",a="哀嚎洞穴的名字来源于地下蒸汽和风穿过岩石裂隙时发出的呼啸和呻吟声，而这个宽阔的入口深渊正是这些回荡哀鸣的主要汇集处。",al={"为什么叫尖啸谷","尖啸谷名字由来"}},{q="谁统治着尖啸谷？",a="该洞室由安娜科德拉掌管，她是与纳拉雷克斯一同堕入翡翠梦魇腐化的主要尖牙领主之一。",al={"尖啸谷首领","尖啸谷里有什么人","尖啸谷领袖"}},{q="什么生物在此洞室中徘徊？",a="沟壑中栖息着变异迅猛龙、被腐化的尖牙德鲁伊以及游荡的水生生物，包括在洪水淹没的地面上漫步的古老龟类克雷什。",al={"尖啸谷怪物","尖啸谷里的敌人"}}},fx={edd75ba3={q="什么是尖啸峡谷？",a="尖啸峡谷是越过哀嚎洞穴入口后遇到的第一处广阔地下洞室。地下溪流汇入洞底，积成浅水；这道巨大的裂谷回荡着诡异的自然声响和被腐化野兽的嘶鸣，是深处逐渐滋生的噩梦最前沿。",al={"什么是尖啸谷","尖啸谷概况","尖啸谷背景"}}},fp="15,106,26.335.0,37.101.0,37.156.0,35.102.0,33.135.0"}
P.entries["subzone:scuttle-coast"] = {n="流亡海岸",s="流亡海岸是杜隆塔尔东部遭受海浪拍打的海岸线，位于剃刀岭和提拉加德城堡之间。多岩石的海滩上散布着来自戴林·普罗德摩尔海军上将的库尔提拉斯舰队的沉船残骸，使其成为了部落积极搜寻物资的场所，也是近期海军战争挥之不去的印记。",h="流亡海岸是杜隆塔尔东部遭受海浪拍打的海岸线，位于剃刀岭和提拉加德城堡之间。多岩石的海滩上散布着来自戴林·普罗德摩尔海军上将的库尔提拉斯舰队的沉船残骸，使其成为了部落积极搜寻物资的场所，也是近期海军战争挥之不去的印记。",kw={"戴林·普罗德摩尔","杜隆塔尔","库尔提拉斯","马库拉","剃刀岭","流亡海岸","沉船","提拉加德城堡"},ang={["faction:Horde"]="散落在沙滩上的残破船体，是杜隆塔尔防御戴林·普罗德摩尔入侵海军的鲜明纪念碑。"},sec={{t="舰队残骸",b="流亡海岸沿着杜隆塔尔东部边缘延伸至无尽之海，它在戴林·普罗德摩尔海军上将领导的入侵期间获得了其严峻的特质。当库尔提拉斯舰队袭击尚在起步阶段的杜隆塔尔国家时，与部落的激烈战斗导致许多人类战舰冲向了锯齿状的浅滩，撞成了破碎的残骸。如今，海岸线上挤满了覆盖着藤壶的木材、断裂的索具和被抢救出来的货物桶。对于附近的剃刀岭营地来说，这片海岸依然是一个挥之不去的提醒，时刻告诫着人们库尔提拉斯的威胁离他们有多近。"},{t="拾荒者与潮汐",b="“流亡海岸”这个名字可能指的是在战斗中被凿沉或搁浅的战舰，也可能指的是那些在腐烂的废墟中觅食的螃蟹群和马库拉群。海岸野生生物和危险的潮汐让普通的旅行者远离这些残骸。"}},faq={{q="这些沉船都是从哪里来的？",a="这些破碎的船只属于戴林·普罗德摩尔海军上将麾下的库尔提拉斯海军舰队。在海军上将针对新建立的部落发动的失败军事行动中，它们被撞毁在杜隆塔尔多岩的浅滩上。",al={"这里为什么会有船只","沉船属于谁","杜隆塔尔沉船"}},{q="为什么它被称为流亡海岸？",a="没有人能确定。这个名字可能指的是在海战中被凿沉在沿岸的战舰，也可能指的是在岩石沙滩上横行（横行）的无数马库拉和螃蟹。",al={"为什么叫流亡海岸","流亡海岸名称由来"}},{q="流亡海岸旅行安全吗？",a="不安全。除了险恶的海浪和锯齿状的岩石外，像马库拉这样的敌对海岸野兽在浪花中潜行，而武装的库尔提拉斯幸存者仍然驻扎在南部的提拉加德城堡。",al={"流亡海岸的危险","流亡海岸危险吗"}}},fp="13,190,21.478.0,20.217.0,41.199.0,35.172.0,36.198.0"}
P.entries["subzone:sea-of-cinders"] = {n="灰烬之海",s="灰烬之海是一片焦灼、狂风肆虐的荒地，横亘于灼热峡谷南部，位于黑石山正北方。在元素热力和无休止的狂风摧残下，这片平地不断喷出灰烬与余火，形成了一片令人窒息、几乎没有生灵能够存活的废土。",h="灰烬之海是一片焦灼、狂风肆虐的荒地，横亘于灼热峡谷南部，位于黑石山正北方。在元素热力和无休止的狂风摧残下，这片平地不断喷出灰烬与余火，形成了一片令人窒息、几乎没有生灵能够存活的废土。",kw={"灰烬","黑石山","黑铁","余烬","拉格纳罗斯","灰烬之海","灼热峡谷","荒原"},ang={["profession:Mining"]="黑石山周边的岩石极不稳定，被高温灼裂，常常露出丰富的矿藏与黑铁矿脉，等待那些敢于在漫天灰烬中勘探的人。",["race:Dwarf"]="对铜须和蛮锤矮人而言，走过这片燃烧的荒原，总会沉重地想起索瑞森的愚行，以及震碎赤脊山的黑暗力量。"},sec={{t="余烬荒原",b="灰烬之海延伸于灼热峡谷的岩壁与巍峨的黑石山之间，因平原上终年席卷着令人窒息的尘霾和灼热砂砾而得名。数百年前，火焰之王拉格纳罗斯被召唤到凡人世界，剧烈的动荡震裂了赤脊山，将周围的大地化为干旱的熔渣堆。灰烬之海是那场浩劫留下的最荒芜的遗迹之一，这片无法居住的平原上，就连大地本身也不肯冷却。"},{t="山麓下的危机",b="由于这片灼热的平地紧邻通往黑石山的北侧入口，旅人和拾荒者往往别无选择，只能从此穿过。这里的狂风扬起遮蔽视线的浓密灰云，掩盖了突现的地裂、可怕的元素生物，以及适应了酷热的游荡掠食者。险恶的环境，加上宣称占据此地的黑铁矮人带来的威胁，使任何穿越灰烬之地的人都必须保持警惕，迅速通行。"}},faq={{q="灰烬之海是什么地方？",a="这是一片荒凉、遍布灰烬的平地，位于灼热峡谷南部，紧贴黑石山北麓。阴燃的泥土与飞舞的余烬覆盖着这里。",al={"灰烬之海是什么","灰烬之海背景故事","灰烬之海在哪里"}},{q="为什么地面始终在燃烧？",a="数百年前，巫术领主索瑞森在三锤之战期间召唤了火焰之王拉格纳罗斯，令这片地区遭到彻底毁灭。那场灾难性的喷发使大地变得炽热，震碎了群山，留下至今仍在阴燃的平原。",al={"为什么在燃烧","为什么有余烬","地面为什么冒烟"}},{q="有人住在这里吗？",a="灰烬之海内部没有成形的定居点。令人窒息的高温、污浊的空气和水源的匮乏，使人无法在此长久居住，只有游荡的野兽、火元素，以及隶属于黑石山的巡逻队出没于这片荒地。",al={"谁住在这里","灰烬之海居民","定居点"}},{q="穿越这里有哪些危险？",a="除了凶猛的野兽和潜伏在山边的黑铁矮人，环境本身也足以致命。空气中弥漫着遮蔽视线的烟尘与灼热的灰烬，平坦的地面上遍布着深邃的灼热裂隙。",al={"是否安全","灰烬之海的危险"}}},fp="14,69,21.359.0,24.341.0,27.165.0,37.202.0,22.237.0,44.167.0"}
P.entries["subzone:sen-jin-village"] = {n="森金村",s="森金村是杜隆塔尔南海岸的一个沿海定居点，也是暗矛巨魔的避难所。在沃金酋长带领族人被迫离开回音群岛的祖居地后，他建立了这个村庄，以此纪念他已故的父亲，巫医森金。如今，这里已成为一个专注于生存、草药学和收复失地的脆弱港湾。",h="森金村是杜隆塔尔南海岸的一个沿海定居点，也是暗矛巨魔的避难所。在沃金酋长带领族人被迫离开回音群岛的祖居地后，他建立了这个村庄，以此纪念他已故的父亲，巫医森金。如今，这里已成为一个专注于生存、草药学和收复失地的脆弱港湾。",kw={"暗矛部族","杜隆塔尔","回音群岛","森金村","森金","沃金","扎拉赞"},ang={["profession:Herbalism"]="这个村庄是天然药物的重要中心，周围遍布着当地巫医用来治疗中毒和诅咒的海岸宁神花、银叶草和地根草。",["race:Troll"]="对于从试炼谷走出的暗矛巨魔来说，这个避难所是他们流离失所的人民的中心，承载着他们对已故酋长的记忆，以及扎拉赞背叛所带来的长久痛苦。"},sec={{t="难民的海岸",b="当邪恶的巫医扎拉赞背叛了暗矛部族并夺取了回音群岛的控制权后，沃金酋长被迫带领幸存者横跨海峡，来到了杜隆塔尔的内陆。在那里，他们依托海岸悬崖，眺望着大海，搭建起简陋的茅屋，建立了森金村。这个定居点以沃金的父亲、那位在第三次战争中被鱼人俘虏并献祭的受人尊敬的长者——森金的名字命名。尽管他们与萨尔的部落结成了紧密的联盟，但这里的巨魔仍生活在流亡的阴影之下，每天隔着浅滩凝望着他们失去的家园。"},{t="注视着群岛",b="森金村的日常生活围绕着备战和防御展开。面对当地的野猪人袭击、凶猛的海兽以及从海上飘来的扎拉赞的诅咒，村民们严重依赖草药和强效的炼金药剂。当沃金在部落主城协调更大范围的部族防御时，当地的萨满、猎人和斥候聚集在这里，招募从试炼谷走出的新冒险者。他们的目标很明确：收集资源，保护杜隆塔尔的南翼，并策划最终击败叛徒扎拉赞。"}},faq={{q="暗矛部族为什么要在森金村这里定居？",a="在巫医扎拉赞发疯并控制了回音群岛的家园后，暗矛部族逃过了海峡，抵达了杜隆塔尔海岸。沃金建立了森金村，作为隔海眺望他们被窃土地的临时避难所和集结地。",al={"为什么会有森金村","为什么巨魔会在杜隆塔尔","为什么巨魔离开了回音群岛"}},{q="谁是森金？",a="森金是一位受人尊敬的巫医，也是暗矛部族的酋长，同时还是沃金的父亲。在第三次战争期间，他预见到了萨尔的到来，但在萨尔赶来营救他之前，他被南海的鱼人俘虏，并被献祭给了他们的海巫。",al={"谁是森金","森金的名字由来","森金背景故事"}},{q="为什么这里有这么多的草药师和炼金师？",a="当地的巫医和治疗师严重依赖杜隆塔尔的海岸植物和蝎毒来调制护身符、解毒剂和进行仪式。这些草药药剂维系着伤者，并提供了抵御从回音群岛飘来的黑暗诅咒的护盾。",al={"森金村训练师","森金村的专业技能","为什么这里有炼金术"}},{q="可以从森金村前往回音群岛吗？",a="回音群岛位于村庄东方，隔水相望。冒险者经常游泳或涉水穿过浅水航道，去反击扎拉赞的巫毒教徒，找回被窃的文物，或为村庄的防御者收集资源。",al={"如何前往回音群岛","森金海岸外的群岛","游向回音群岛"}}},fp="15,218,15.530.0,17.484.0,49.203.0,16.230.0,53.205.0,50.226.0"}
P.entries["subzone:sentinel-hill"] = {n="哨兵岭",s="哨兵岭是联盟在西部荒野的主要堡垒，也是人民民兵的Command Center。这里被荒废的田野、拾荒的豺狼人和敌对的暴徒所包围，这座坚固的高地是该地区守法公民唯一的安全立足点。",h="哨兵岭是联盟在西部荒野的主要堡垒，也是人民民兵的Command Center。这里被荒废的田野、拾荒的豺狼人和敌对的暴徒所包围，这座坚固的高地是该地区守法公民唯一的安全立足点。",kw={"格里安·斯托曼","狮鹫栖木","人民民兵","河爪豺狼人","哨兵岭","哨兵塔","西部荒野"},ang={["faction:Alliance"]="哨兵岭是你在西部荒野唯一的防御哨站和补给中心，维系着联盟在此地对抗法外之徒和劫掠者的存在。",["race:Human"]="看到西部荒野的农夫被迫在此组建自己的民兵，反映出王国在王位空缺期间日益加深的危机。"},sec={{t="沙尘中的堡垒",b="哨兵岭坐落在西部荒野中央的高地上，是这片无法之地的关键避难所。这里设有兵营风格的旅店、连接旅客往返暴风城及更远地区的Gryphon Roost、铁匠铺和伐木场，所有设施都以巍峨的Sentinel Tower为核心。虽然周边的土地已经沦为强盗和贪婪野兽的乐园，但这个营地维持着脆弱的防线，让旅客、受困的农夫和新兵可以在老兵的注视下重新集结。"},{t="民兵之心",b="由于皇家军队被困在暴风城，无法抽调士兵保护边远领土，格里安·斯托曼便在这座山上建立了人民民兵。以此为据点，志愿者战士们组织侦察，协调针对河爪豺狼人的打击行动，并调查那些在西部荒野废弃农场中肆虐的有组织劫匪。哨兵岭既不是豪华的堡垒，也不是舒适的避难所，而是一个致力于收复王国昔日粮仓的前线作战营地。"}},faq={{q="为什么暴风城没有派兵保卫哨兵岭？",a="由于瓦里安·乌瑞恩国王下落不明，且王国各地的资源捉襟见肘，暴风城的摄政当局很大程度上放弃了西部各省，任其自生自灭。当地公民和退伍军人不得不自发组成人民民兵来坚守哨兵岭，保护西部荒野残存的一切。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","为什么这里有民兵"}},{q="谁负责哨兵岭？",a="格里安·斯托曼在哨兵塔的基座指挥着人民民兵。他负责协调当地防御，收集周边威胁的情报，并引导到访的冒险者对抗侵扰定居点的豺狼人和强盗。",al={"谁领导哨兵岭","哨兵岭指挥官","格里安·斯托曼"}},{q="哪些威胁正在危及哨兵岭？",a="该营地面临着来自在西部平原游荡的侵略性河爪豺狼人的持续压力，以及潜伏在废弃农场各处的迪菲亚潜行者所进行的阴险且有组织的破坏活动。",al={"什么在攻击哨兵岭","哨兵岭的敌人","谁在进攻"}},{q="这里为旅客提供哪些服务？",a="哨兵岭提供全套的前沿补给设施：一名提供前往暴风城及其他联盟哨站旅行服务的狮鹫管理员、一名旅店老板、一个邮箱、商业补给商贩，以及当地铁匠铺周边的修理设施。",al={"哨兵岭的设施","哨兵岭的飞行点","这里有旅店吗"}}},fx={["3c1a5a7a"]={q="哨兵岭是什么地方？",a="哨兵岭是联盟在西部荒野的核心哨站。这里围绕一座俯瞰平原的高大瞭望塔建成，是人民军的作战总部。四周的匪徒和豺狼人步步逼近，而这座山丘设有飞行兽栖地、旅店、铁匠铺，并备有必需的补给，为疲惫的旅人提供了一处难得的安全堡垒。",al={"哨兵岭是什么地方","哨兵岭介绍","西部荒野哨兵岭"}},fc9f9bfd={q="哨兵岭危险吗？",a="在哨塔和旅店紧邻的警戒范围内，卫兵会保护你免受伤害。然而，周围的山坡和平原极其危险。河爪豺狼人在道路附近游荡，失控的收割看守在附近的田野间徘徊，迪菲亚强盗则频繁巡逻于哨站边界之外。",al={"哨兵岭安全吗","哨兵岭危险","哨兵岭安全"}}},fp="13,271,21.376.0,20.457.0,59.282.0,34.248.0,40.149.0,47.188.0"}
P.entries["subzone:sentinel-tower"] = {n="Sentinel Tower",s="哨兵 Tower矗立在哨兵岭的顶峰，是西部荒野守军的主要瞭望点和指挥部。站在高塔之上，格里安·斯托曼和人民民兵组织起绝望的防线，抵御强盗、豺狼人和日益壮大的迪菲亚潜行者的威胁。",h="哨兵 Tower矗立在哨兵岭的顶峰，是西部荒野守军的主要瞭望点和指挥部。站在高塔之上，格里安·斯托曼和人民民兵组织起绝望的防线，抵御强盗、豺狼人和日益壮大的迪菲亚潜行者的威胁。",kw={"迪菲亚潜行者","格里安·斯托曼","人民民兵","哨兵岭","哨兵塔","瞭望塔","西部荒野"},ang={["faction:Alliance"]="哨兵 Tower代表了普通的联盟子民在暴风城的高层视而不见时，为保卫家园而展现出的坚韧。",["race:Human"]="对于王国的平民来说，这座塔是一个令人痛苦的提醒：暴风城的农业粮仓在本土叛乱的冲击下已岌岌可危。"},sec={{t="守护西部荒野",b="哨兵 Tower建在哨兵岭的山脊上，是动荡的西部荒野的军事心脏。由于暴风城的正规军大多缺席且拒绝提供援助，当地的志愿者和老兵联合起来，建立了一个中央堡垒。这座石塔让瞭望员能够俯瞰尘土飞扬的平原，从废弃的南瓜田到雾气弥漫的海岸，都能尽收眼底，从而在流寇或豺狼人突袭队开始出没时发出预警。"},{t="民兵指挥部",b="这座塔是格里安·斯托曼及其核心领导团队的指挥所。塔周围环绕着临时防御工事、受伤的难民和疲惫的士兵，它既是一个行政中心，也是为被赶出家园的农户提供的紧急避难所。在这里，有关迪菲亚潜行者的情报被汇总，民兵被组织起来，对这个让该省陷入废墟的组织进行协同打击。"}},faq={{q="谁在负责哨兵塔？",a="格里安·斯托曼在塔内指挥行动。作为人民民兵的领袖，他负责协调西部荒野流离失所的农民的防御工作，并招募愿意帮忙的冒险者。",al={"哨兵塔领袖","谁领导哨兵塔","谁管理这座塔"}},{q="为什么这座塔对西部荒野如此重要？",a="它是中原地区仅存的防御工事和瞭望哨。由于暴风城基本放弃了对西部荒野的防守，这座塔成为了该地区难民最后的秩序与安全堡垒。",al={"哨兵塔为何重要","哨兵塔的用途"}},{q="谁住在塔内及其周围？",a="你会发现民兵军官、守望的哨兵、军需官，以及那些因为家园被毁而逃难至此，寻求在坚固石墙旁避难的农户家庭。",al={"哨兵塔里的人","哨兵塔的住户"}},{q="塔上监视着哪些威胁？",a="哨兵们时刻监视着河爪豺狼人的动向、从海岸爬向内陆的鱼人，以及最主要的威胁——迪菲亚潜行者的流浪强盗和匪徒。",al={"哨兵塔的敌人","塔防守的目标"}}},fx={["226a51b2"]={q="哨兵塔 是什么？",a="哨兵塔 是一座醒目的侦察塔，坐落在西部荒野中部的哨兵岭顶端。它是人民军设防坚固的据点和指挥中心，格里安·斯托曼和他的斥候可在此俯瞰起伏的平原，监视整个地区的敌军动向。",al={"哨兵塔 是什么","西部荒野 哨兵塔","关于 哨兵塔"}},["7792f636"]={q="哨兵塔 发生过什么？",a="哨兵塔 原本是一座保护西部荒野农户的瞭望塔，在暴风城撤走驻军后，便成了当地最主要的防御堡垒。流离失所的农民和难民曾多次来到塔下，在民兵的保护下寻求庇护。",al={"哨兵塔 历史","哨兵塔 发生过什么","哨兵塔 的历史"}},["3b2e4075"]={q="哨兵塔 危险吗？",a="哨塔本身对联盟旅人而言是安全的，这里是人民军戒备森严的指挥中枢。然而，周围的丘陵危机四伏，不断受到迪菲亚匪徒、敌对的河爪豺狼人和四处游荡的机械收割看守侵扰。",al={"哨兵塔 安全吗","哨兵塔 危险吗","哨兵塔 危险"}}},fp="14,178,24.368.0,27.393.0,35.185.0,42.225.0,34.188.0,40.137.0"}
P.entries["subzone:sentry-point"] = {n="警戒哨岗",s="警戒哨岗是一座人类瞭望塔，位于尘泥沼泽的大陆边缘，守卫着通往塞拉摩岛的堤道桥。它由塞拉摩的部队维持，负责监视进出吉安娜·普罗德摩尔的岛屿要塞的人流。",h="警戒哨岗是一座人类瞭望塔，位于尘泥沼泽的大陆边缘，守卫着通往塞拉摩岛的堤道桥。它由塞拉摩的部队维持，负责监视进出吉安娜·普罗德摩尔的岛屿要塞的人流。",kw={"桥梁","尘泥沼泽","哨塔","吉安娜·普罗德摩尔","警戒哨岗","塞拉摩","瞭望塔"},ang={["faction:Alliance"]="对于从尘泥沼泽危险的泥沼中赶来的旅行者而言，警戒哨岗是进入塞拉摩岛安全区域的欢迎之门。",["faction:Horde"]="这座塔楼清晰地提醒着人们塞拉摩在卡利姆多大陆上的军事存在，它戒备森严，严防任何接近的部落侦察兵。"},sec={{t="塞拉摩之门",b="警戒哨岗位于连接塞拉摩岛与尘泥沼泽危险湿地的长桥西端，是该要塞在大陆上的第一道防线。这座石砌的侦察塔监视着沼泽道路，确保敌对的沼泽野兽或部落突袭者无法在不被察觉的情况下接近这座岛屿城市。"}},faq={{q="警戒哨岗有什么用？",a="它是塞拉摩岛的预警哨所和边境检查站。驻扎在这里的卫兵负责监视在沼泽道路上通行的人流，并向城市卫兵通报临近的威胁。",al={"警戒哨岗用途","这是什么塔","为什么这里有警戒哨岗"}},{q="谁控制着这个哨站？",a="该哨站由塞拉摩卫兵驻守和维护，在吉安娜·普罗德摩尔及其军事长官的指挥下运作。",al={"谁拥有警戒哨岗","警戒哨岗是联盟的吗","塞拉摩卫兵塔"}},{q="警戒哨岗对部落旅行者安全吗？",a="不安全。尽管吉安娜·普罗德摩尔致力于与部落实现和平，但驻扎在这个哨站的军事卫兵负责保卫联盟领土，并会攻击视线内的入侵部落成员。",al={"部落能去警戒哨岗吗","部落友好的警戒哨岗"}}},fp="12,182,22.261.0,30.166.0,26.103.0,41.147.0"}
P.entries["subzone:sepulcher"] = {n="瑟伯切尔",s="瑟伯切尔是银松森林中被遗忘者的主要定居点和据点。这里曾是俯瞰西海岸的普通洛丹伦墓地和墓穴，如今已成为部落抵御周边区域威胁的防御性避难所。",h="瑟伯切尔是银松森林中被遗忘者的主要定居点和据点。这里曾是俯瞰西海岸的普通洛丹伦墓地和墓穴，如今已成为部落抵御周边区域威胁的防御性避难所。",kw={"墓穴","死亡卫士","被遗忘者前哨站","墓地","瑟伯切尔","银松森林","银松森林瑟伯切尔"},ang={["faction:Horde"]="对于任何从提瑞斯法林地向南冒险的部落旅行者来说，瑟伯切尔是方圆数英里内唯一可靠的避难所、维修点和飞行枢纽。",["race:Undead"]="瑟伯切尔是被遗忘者在银松森林开展平定行动的集结地，指导针对残留的天灾忠诚者、肯瑞托残部和野蛮狼人的作战行动。"},sec={{t="迷雾中的圣所",b="瑟伯切尔坐落在洛丹伦海岸线上方的山丘中，原本是西侧道路旁的一处安静的墓地和墓穴。在第三次战争之后，刚获得解放的被遗忘者将这座古老的石库及其周边区域改造成了一个重要的前哨站。瑟伯切尔四周受敌——南面是野蛮的狼人，东面是游荡的天灾余孽，而安伯米尔的肯瑞托法师也虎视眈眈——因此它成为了在银松森林行进的旅人们难得的安全、补给与指挥中心。"}},faq={{q="在被遗忘者入驻之前，瑟伯切尔是什么地方？",a="在第三次战争和洛丹伦王国覆灭之前，它仅仅是一处路边的墓地和石质墓穴，当地村民会将死者安葬于此。",al={"瑟伯切尔历史","瑟伯切尔的前身","瑟伯切尔的建造者"}},{q="为什么瑟伯切尔对被遗忘者如此重要？",a="它是被遗忘者在银松森林唯一的防御中心。从这个中心位置，被遗忘者的斥候和指挥官们可以监视逼近的达拉然法师、天灾残党，以及潜伏在影牙城堡附近的狼人威胁。",al={"瑟伯切尔为何重要","银松森林的被遗忘者","瑟伯切尔的角色"}},{q="其他部落种族的旅行者在这里受欢迎吗？",a="是的。虽然该基地完全由被遗忘者死亡卫士、商人和药剂师管理和居住，但它作为部落的官方避难所，为途经该地区的兽人、巨魔和牛头人提供休憩与贸易服务。",al={"兽人可以去瑟伯切尔吗","瑟伯切尔对部落友好吗","瑟伯切尔的部落"}},{q="有哪些威胁围绕着瑟伯切尔？",a="该定居点被敌对势力团团包围：东面游荡着天灾军团，东南面的安伯米尔由肯瑞托把持，南面的森林中则潜伏着凶残的狼人。",al={"瑟伯切尔面临的威胁","银松森林的敌人","瑟伯切尔受到什么攻击"}}},fp="9,182,20.469.0,52.135.0,46.190.0,58.197.0,36.155.0"}
P.entries["subzone:serpent-s-coil"] = {n="盘蛇谷",s="盘蛇谷是一处位于诅咒之地东部山脊的蜿蜒洞穴网络和烧毁的营地。这里到处都是从旧时代战争中遗留下来的被烧焦的兽人建筑，成为了黑暗教徒们的隐秘据点。",h="盘蛇谷是一处位于诅咒之地东部山脊的蜿蜒洞穴网络和烧毁的营地。这里到处都是从旧时代战争中遗留下来的被烧焦的兽人建筑，成为了黑暗教徒们的隐秘据点。",kw={"奥利斯塔","诅咒之地","被诅咒的基里斯","盘蛇谷","影誓者"},ang={["class:Warlock"]="在盘蛇谷内活动的影誓教徒进行着束缚仪式并藏匿着强大的神器，使该洞穴成为了肆无忌惮的恶魔研究的阴暗缩影。"},sec={{t="灰烬与岩石的迷宫",b="盘蛇谷凿刻在诅咒之地崎岖的东部悬崖上，其蜿蜒的路径和洞穴经过了追溯到第一次和第二次战争时期的废弃兽人小屋。这些隧道中潜藏的不是普通的野兽，而是被弥漫在红色荒原中的残留恶魔能量所吸引的影誓教徒和黑暗艺术修行者。在深邃蜿蜒的空洞中，他们远离了守望堡的监视，进行着各种勾当。"},{t="邪教徒巢穴",b="这些洞穴长期以来一直是大法师奥利斯塔的教徒们的集结地，他们崇拜恶魔领主，并试验着像奥利斯塔的护符这样的邪恶神器。即使在他们主人的掌控力动摇时，忠诚的影誓狂热者们依然在洞穴的转角处巡逻，在被诅咒的基里斯的麾下维持着仪式，并躲藏在焦黑的路障后。"}},faq={{q="什么是盘蛇谷？",a="盘蛇谷是一处位于诅咒之地东部的蜿蜒洞穴网络和峡谷，因其焦黑的兽人遗迹和邪恶的居住者而闻名。",al={"盘蛇谷","这个洞穴是什么","诅咒之地盘蛇谷"}},{q="为什么这里有古老的兽人建筑？",a="这些营地建筑可以追溯到第一次和第二次战争时期，当时旧部落穿过附近的黑暗之门，并在战败前加固了周边地区。",al={"为什么有兽人遗迹","诅咒之地的兽人建筑","烧毁的小屋"}},{q="谁居住在盘蛇谷内？",a="洞穴被效忠于大法师奥利斯塔及其所侍奉的恶魔力量的影誓教徒所占据。",al={"这里有什么人","盘蛇谷的敌人","谁控制着这个洞穴"}}},fp="14,159,28.325.0,16.339.1,23.104.0,38.160.0,32.97.0"}
P.entries["subzone:sewers"] = {n="Sewers",s="下水道是一个庞大的地下排水网络，提供了直接通往幽暗城的第二入口。这条通道位于洛丹伦废墟宫殿西侧的山丘下方，让蝙蝠管理员和潜行的旅行者可以绕过从王座大厅向下延伸的危险电梯。",h="下水道是一个庞大的地下排水网络，提供了直接通往幽暗城的第二入口。这条通道位于洛丹伦废墟宫殿西侧的山丘下方，让蝙蝠管理员和潜行的旅行者可以绕过从王座大厅向下延伸的危险电梯。",kw={"后门","蝙蝠管理员","排水","飞行路线","洛丹伦","下水道","提瑞斯法林地","幽暗城"},ang={["faction:Alliance"]="任何足够愚蠢或勇敢去突袭被遗忘者首都的人都知道，下水道是绕过防御严密的地面废墟的唯一隐蔽路径。",["race:Undead"]="对于被遗忘者来说，下水道是一条至关重要的生命线和飞行走廊，它使幽暗城能够与洛丹伦的其他地区保持联系，而不会让交通拥堵在庭院电梯处。"},sec={{t="通往地下墓穴的后门",b="在瘟疫摧毁洛丹伦之前，这些石质涵洞曾是皇家首都的普通下水道。然而，在希尔瓦娜斯·风行者的被遗忘者手中，这些径流隧道已被整合到幽暗城的外部防御系统中。该通道在地面废墟西侧、提瑞斯法林地一处有争议的血色十字军岗哨附近通向地面，提供了一条平坦、直接的下坡路。被遗忘者的蝙蝠管理员利用这条巨大的管道，将乘客快速运送到地下环形区，完全避开了缓慢的铁笼电梯。由于它绕过了防御严密的地面庭院，这里仍然是一个敌对渗透者不断试图利用的危险漏洞。"}},faq={{q="下水道隧道在外部通向哪里？",a="该管道通向提瑞斯法林地的起伏丘陵，就在洛丹伦废墟正门的西侧。它距离俯瞰湖泊的血色十字军岗哨不远。",al={"幽暗城下水道出口","下水道通向哪里","下水道后门"}},{q="为什么有人会使用下水道而不是正门？",a="进入幽暗城的主要方式需要乘坐从宫殿废墟向下延伸的铁笼电梯，这在受到攻击时既缓慢又危险。下水道是一条直接的斜坡路线，既能处理被遗忘者的蝙蝠运输，又允许在无需等待电梯的情况下快速撤离。",al={"为什么使用下水道","下水道与电梯","幽暗城后门"}},{q="下水道对联盟袭击者来说安全吗？",a="绝不安全。因为它绕过了洛丹伦防御严密的门楼和王座大厅，下水道成为了大胆的联盟侦察兵和突击队试图直接潜入被遗忘者首都的首选突破点。",al={"联盟攻击下水道","下水道有守卫吗","幽暗城下水道防御"}}},fp="6,185,29.518.0,41.161.0,61.234.0,40.176.0"}
P.entries["subzone:shadow-grave"] = {n="灰影墓穴",s="灰影墓穴是一座坐落在提瑞斯法林地丧钟镇上方斜坡墓地顶部的石砌墓穴。它是新获得自由的被遗忘者摆脱死亡带来的迟钝和巫妖王逐渐消退的控制，从而获得觉醒的物理起点。",h="灰影墓穴是一座坐落在提瑞斯法林地丧钟镇上方斜坡墓地顶部的石砌墓穴。它是新获得自由的被遗忘者摆脱死亡带来的迟钝和巫妖王逐渐消退的控制，从而获得觉醒的物理起点。",kw={"觉醒","墓穴","丧钟镇","灰影墓穴","初始之墓","提瑞斯法林地","管理员摩尔多"},ang={["race:Undead"]="每一位被遗忘者冒险者都是从这座墓穴冰冷的石板上开始他们的旅程，睁开双眼面对不死与自由意志的严酷现实。"},sec={{t="被遗忘者的摇篮",b="灰影墓穴隐藏在丧钟镇上方墓地斜坡顶端的岩石山脚下，这是一座简单的石制陵墓，却有着非凡的用途。在它潮湿的拱顶内，被复活为天灾军团无心奴仆的尸体逐渐觉醒并获得自由意志。在像管理员摩尔多这样的看管者的注视下，这些新近获得自由的亡灵从石板上站起来，向着一个厌恶他们的世界迈出战栗的第一步，然后沿着小路走向丧钟镇，向黑暗游侠女王宣誓效忠。"}},faq={{q="灰影墓穴是用来做什么的？",a="它是新觉醒的被遗忘者苏醒意识的墓穴。这些复活的个体没有像尘土中毫无思想的天灾爪牙那样继续存在，而是在墓穴内恢复了自由意志，并开始了服务于希尔瓦娜斯·风行者的第二次生命。",al={"灰影墓穴用途","什么是灰影墓穴","灰影墓穴陵墓"}},{q="灰影墓穴位于哪里？",a="灰影墓穴坐落在丧钟镇上方的墓地斜坡顶部，背靠提瑞斯法林地的南部山脉。一条土路从入口处蜿蜒下行，通往丧钟镇的定居点。",al={"灰影墓穴在哪里","灰影墓穴位置","灰影墓穴地图"}},{q="谁在这里看管新觉醒者？",a="管理员摩尔多负责照看墓穴内新觉醒的亡灵，评估那些从石板上爬起来的人是否已经恢复了神智，并足以投身于被遗忘者的大业。",al={"灰影墓穴里有什么人","灰影墓穴角色","管理员摩尔多位置"}}},fp="12,81,22.373.0,34.180.0,34.172.0,37.140.0"}
P.entries["subzone:shadow-hold"] = {n="暗影堡",s="暗影堡是隐藏在费伍德森林西部加德纳尔腐化峡谷中的一座庞大的地下建筑群。这里曾是一座神圣的暗夜精灵古墓，后被暗影议会占领并亵渎，成为了他们在卡利姆多的主要堡垒。",h="暗影堡是隐藏在费伍德森林西部加德纳尔腐化峡谷中的一座庞大的地下建筑群。这里曾是一座神圣的暗夜精灵古墓，后被暗影议会占领并亵渎，成为了他们在卡利姆多的主要堡垒。",kw={"阿可娜琳","贝恩霍勒","古墓","费尔丹","费伍德森林","加德纳尔","暗影议会","暗影堡","崔伊·光铸"},ang={["class:Warlock"]="暗影堡的最深处藏有像克索诺斯星尘这样稀有的恶魔试剂，只有通过巧妙的潜入赢得贝恩霍勒领主的青睐，才能获得这些试剂。",["race:NightElf"]="对于暗夜精灵来说，这座堡垒是一个恐怖的地方——一座被邪能污泥、囚笼和恶魔仪式所亵渎的祖先古墓。"},sec={{t="一座被亵渎的圣所",b="在加德纳尔被腐蚀的红土地之下，坐落着暗影堡。这是一个巨大的地下迷宫，由古代暗夜精灵古墓改造而成。曾经有沉睡的德鲁伊在此休息并照看翡翠梦境，而如今，黑暗术士和恶魔仆从在魔火照亮的蜿蜒走廊中潜行。在最深处，该邪教在恐惧魔王贝恩霍勒领主、萨瓦里斯王子和暗影领主费尔丹的统领下，掌握着一支强大的武装力量，使其成为了该地区恶魔势力的最高据点。"},{t="深处的恐怖",b="暗影议会利用这些洞穴来协调他们对费伍德森林的腐化，并进行残酷的审讯。包括暗夜精灵阿可娜琳·星影和人类圣骑士崔伊·光铸在内的联盟斥候在暗影堡深处落入了邪教徒手中。虽然阿可娜琳及时获救而幸存，但崔伊却被邪教的刑吏折磨致死，他的灵魂在安息前曾一度被扭曲成邪恶之物。翡翠之环和当地的萨满祭司一直在努力穿透保护着暗影堡的黑暗屏障，希望能一举击溃这里的恶魔主人。"}},faq={{q="暗影议会占领之前，暗影堡是什么地方？",a="暗影堡最初是一座古老的暗夜精灵古墓，供奉着那些沉睡的德鲁伊，他们曾在此照看大地并与翡翠梦境进行交流。在第三次战争和费伍德森林遭受恶魔腐化之后，暗影议会占领了这座地下建筑群，并将这些神圣的大厅亵渎为一座邪能堡垒。",al={"暗影堡历史","谁建造了暗影堡","暗影堡最初是什么"}},{q="谁统治着暗影堡？",a="这座堡垒由恐惧魔王贝恩霍勒领主监管，同时还有强大的副手协助，包括萨特萨瓦里斯王子和指挥凡人邪教徒的术士暗影领主费尔丹。",al={"暗影堡首领","谁在掌管暗影堡","暗影堡的领袖"}},{q="冒险者为何要潜入暗影堡？",a="寻求强大召唤试剂（如克索诺斯星尘）的黑魔法修行者有时会伪装成忠诚的暗影议会邪教徒进入堡垒。只有当外来者通过铲除其队伍中的间谍和叛徒来证明忠诚时，贝恩霍勒领主才会允许他们与堡垒进行贸易。",al={"潜入暗影堡","伪装成暗影议会进入暗影堡","克索诺斯星尘 暗影堡"}},{q="堡垒中的俘虏遭遇了什么？",a="暗夜精灵阿可娜琳·星影和圣骑士崔伊·光铸在侦察暗影议会时被俘。崔伊被邪教徒拉凯亚折磨致死，而阿可娜琳则被冒险者从笼中救出，随后冒险者又寻回了崔伊的遗骸，使其得以安葬。",al={"加德纳尔的俘虏","崔伊·光铸与阿可娜琳","暗影堡的囚笼"}}},fp="11,186,19.406.0,19.484.1,60.302.0,29.158.0,58.269.1,42.268.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="破影峡谷",s="破影峡谷是一处位于凄凉之地东南部的隐蔽山谷。这处阴森的峡谷掩藏在玛格拉姆村附近嶙峋的峭壁之中，是火刃氏族的恶魔势力和凡人狂热者的秘密据点。",h="破影峡谷是一处位于凄凉之地东南部的隐蔽山谷。这处阴森的峡谷掩藏在玛格拉姆村附近嶙峋的峭壁之中，是火刃氏族的恶魔势力和凡人狂热者的秘密据点。",kw={"火刃氏族","邪教徒","恶魔","凄凉之地","邪能","破影峡谷","玛格拉姆村"},ang={["class:Warlock"]="黑暗的召唤法阵和浓郁的邪能气息，使得这座隐秘的峡谷成为了火刃氏族黑暗魔法触角深远的明证。"},sec={{t="一处邪能的隐秘飞地",b="破影峡谷深藏在玛格拉姆村东南方贫瘠的山脊之中，为火刃氏族提供了一个远离游荡的半人马部落视线的隐蔽集结地。在奇异的巨型蘑菇和阴森的仪式营地之间，邪教徒们与被召唤出的恶魔并肩劳作。在这里，黑暗修行者们调用邪能，维护着沉重的仪式锁链，利用峡谷天然的隔离环境，集结援军，并在凄凉之地的荒原中稳固其恶魔据点。"}},faq={{q="破影峡谷是什么地方？",a="破影峡谷是一处位于凄凉之地东南部、玛格拉姆村外围的隐蔽山谷。它是火刃氏族的恶魔爪牙和邪教徒的隐秘营地与集结地。",al={"破影峡谷信息","这是什么地方","破影峡谷在哪里"}},{q="谁占据了这座峡谷？",a="这座峡谷被火刃氏族的邪教徒占据，他们直接与恶魔并肩作战。他们利用峡谷受遮蔽的地形进行黑暗仪式，并为他们在该地区发动的更广泛的攻势提供支援。",al={"谁住在这里","破影峡谷怪物","破影峡谷的敌人"}},{q="在峡谷内可以发现哪些特征？",a="峡谷内有黑暗仪式建筑、巨大的铁链，以及在隐藏于山缝中的邪能营地间生长的醒目巨型蘑菇。",al={"破影峡谷里面有什么","破影峡谷地标"}}},fp="18,92,23.372.0,27.175.0,24.151.0,45.123.0"}
P.entries["subzone:shadowfang-keep"] = {n="影牙城堡",s="影牙城堡坐落在银松森林南部，俯瞰着焚木村的一处崎岖峭壁之上，是疯狂的大法师阿鲁高和他那些野性狼人的黑暗巢穴。这座要塞原名为席瓦莱恩城堡，在第三次战争期间被召唤出的贪婪狼群攻陷，如今其古老的厅堂里游荡着被杀害的贵族的亡魂，到处爬满了狼形的怪物。",h="影牙城堡坐落在银松森林南部，俯瞰着焚木村的一处崎岖峭壁之上，是疯狂的大法师阿鲁高和他那些野性狼人的黑暗巢穴。这座要塞原名为席瓦莱恩城堡，在第三次战争期间被召唤出的贪婪狼群攻陷，如今其古老的厅堂里游荡着被杀害的贵族的亡魂，...",kw={"阿鲁高","芬鲁斯","焚木村","影牙","席瓦莱恩","银松森林","斯普林瓦尔","狼人"},ang={["class:Mage"]="影牙城堡是肯瑞托傲慢行径的一个残酷警示，展现了无节制地进行异维度召唤所带来的灾难。",["faction:Horde"]="对于被遗忘者来说，阿鲁高的狼人是一个不可预测的威胁，它们就盘踞在银松森林中幽暗城外围领地的家门口，必须尽快予以铲除。"},sec={{t="席瓦莱恩家族的陨落",b="在第三次战争之前，这座高耸的要塞被称为席瓦莱恩城堡，是席瓦莱恩男爵的祖宅，也是附近焚木村的权力中心。当天灾军团席卷洛丹伦时，绝望的法师们寻求禁忌手段来遏制这股亡灵浪潮。依靠达拉然法师乌尔的空间维度研究，大法师阿鲁高将异维度的狼人召唤到了艾泽拉斯。这些野蛮的野兽撕碎了天灾军团，但很快就失控了。狼群在银松森林南部横冲直撞，围攻了这座要塞，屠杀了席瓦莱恩男爵、他的家人以及指挥官斯普林瓦尔的守军。内疚与悲伤摧毁了阿鲁高的理智；他没有逃走，而是占领了这座要塞，将其更名为影牙城堡，并收养了这些凶残的掠食者作为他的“孩子”。"},{t="被诅咒的堡垒",b="今天，影牙城堡已成为瘟疫般肆虐银松森林的狼人诅咒的中心。阿鲁高居住在最高的观星台，身旁簇拥着他那贪婪的狼人——包括月怒狼群和影牙狼群——以及像他巨大的宠物狼芬鲁斯那样的邪恶野兽。在他的圣所之下，城堡昔日领主们那不安的灵魂，例如席瓦莱恩男爵和指挥官斯普林瓦尔，依然被困在痛苦之中，被诅咒着去无休止地守卫那些他们在生前未能守护的厅堂。阿鲁高站在城墙之上，将他险恶的影响力延伸至焚木村和周边的林地，对试图清除森林中疯狂之源的邻近被遗忘者构成了可怕的威胁。"}},faq={{q="在阿鲁高接管之前，影牙城堡叫什么名字？",a="它最初名为席瓦莱恩城堡。它是席瓦莱恩男爵的祖传要塞，他在狼人入侵之前一直管理着焚木村和周边的土地。",al={"原名","谁曾经拥有影牙城堡","席瓦莱恩城堡"}},{q="为什么阿鲁高要在这里召唤狼人？",a="在第三次战争期间，天灾军团无情地碾压了达拉然的军队，并将被杀害的法师复活为亡灵。不顾肯瑞托的警告，大法师阿鲁高利用法师乌尔的研究召唤了异维度的狼人来扭转战局。虽然它们消灭了亡灵，但这些野兽很快就转向了活人，并在银松森林中横行。",al={"阿鲁高为什么要召唤狼人","阿鲁高背景故事","狼人是如何来到这里的"}},{q="现在是谁统治着影牙城堡？",a="这座城堡由大法师阿鲁高把持。因释放这些怪物而产生的内疚感让他陷入疯狂，他将狼人视为自己的“孩子”，并在要塞高处与他那致命的狼群一起进行统治。",al={"影牙城堡的现任主人","谁住在影牙城堡","阿鲁高的城堡"}},{q="为什么影牙城堡里会有鬼魂？",a="这些鬼魂属于席瓦莱恩男爵、指挥官斯普林瓦尔和城堡以前的家臣。当狼群涌入城堡并屠杀了里面的所有人时，居民们的灵魂被困在了石头之中，被诅咒着在废墟般的走廊里游荡。",al={"席瓦莱恩男爵的鬼魂","指挥官斯普林瓦尔的鬼魂","影牙城堡内的亡灵"}},{q="焚木村与这座城堡有什么联系？",a="焚木村坐落在城堡的阴影之下，历史上一直由席瓦莱恩男爵管理。在阿鲁高蔓延的影响下，村民们受到了狼人诅咒的折磨，白天表现为普通的凡人，但在夜幕降临时会变身为狂暴的野兽。",al={"焚木村与影牙城堡","焚木村的诅咒"}}},fp="15,240,24.678.0,17.655.0,56.156.0,38.303.0,36.181.0,40.247.0,55.238.1"}
P.entries["subzone:shadowglen"] = {n="幽影谷",s="幽影谷是坐落在泰达希尔东北部枝干间的一处幽静而昏暗的山谷。巨大的古树奥达希尔在此耸立，这里也是年轻的暗夜精灵在奔赴广阔世界开启冒险生涯前，迈出第一步的安全避风港。",h="幽影谷是坐落在泰达希尔东北部枝干间的一处幽静而昏暗的山谷。巨大的古树奥达希尔在此耸立，这里也是年轻的暗夜精灵在奔赴广阔世界开启冒险生涯前，迈出第一步的安全避风港。",kw={"奥达希尔","卡多雷","暗夜精灵新手区","幽影谷","黑丝洞","泰达希尔"},ang={["faction:Alliance"]="幽影谷坐落在泰达希尔高耸的枝干上，处于严密守卫的港口深处，是联盟最隐蔽、防御最森严的圣地幽谷之一。",["race:NightElf"]="每一位年轻的暗夜精灵都是从奥达希尔那受庇护的根系间开启他们的冒险旅程，在面对卡利姆多的危险之前，在这里接受最初的祝福和指引。"},sec={{t="一处隐蔽的摇篮",b="幽影谷藏在泰达希尔的东北部树冠中，被高耸的山脊环绕，与世隔绝。幽谷终日沐浴在暮色之中，以奥达希尔为中心，这是一棵巨大的古树，其中空的树干内住着长者、女祭司和导师，为刚刚开始训练的年轻暗夜精灵提供指导。走出山谷的唯一路线是向南穿过一条狭窄的山道，通往星风村和多兰纳尔。这使得幽影谷成为世界之树上防御最自然、最宁静的圣地之一。"},{t="蔓延的阴影",b="尽管幽影谷静谧隐蔽，但也并非完全没有危险。在极西北处坐落着黑丝洞，这是一个阴暗的洞穴，遍布着毒蜘蛛，时刻威胁着这片宁静的林地。即使在泰达希尔这片纯净的枝干上，也需要保持警惕。初出茅庐的保卫者们肩负着击退入侵的害虫和野兽的任务，然后才能前往枝干上更广阔的世界。"}},faq={{q="什么是幽影谷？",a="幽影谷是暗夜精灵的隐蔽新手村，位于泰达希尔的东北部。这是一个以大树奥达希尔为中心的宁静隐蔽的避风港，新手们在导师的指导下进行训练，随后便会踏上探索世界之树的旅程。",al={"这是什么地方","幽影谷背景故事","关于幽影谷"}},{q="山谷中心那棵巨大的树是什么？",a="这棵树是奥达希尔，它是构成幽影谷核心的古树。其中空的内部作为行政小屋和训练中心，年轻的暗夜精灵在这里会见职业训练师、导师和看护者。",al={"幽影谷的大树","奥达希尔","幽影谷树木"}},{q="幽影谷存在哪些威胁？",a="主要威胁来自西北部的黑丝洞，这是一个遍布毒蜘蛛的洞穴，这些蜘蛛经常爬到山谷中。年轻的保卫者们的任务是清除这些蜘蛛，并安抚躁动的当地野生动物。",al={"为什么这里有蜘蛛","幽影谷的危险","黑丝洞"}},{q="如何离开幽影谷？",a="幽影谷四面环山，只有一条向南的小路。穿过这个狭窄的山隘，向南可以前往星风村和多兰纳尔聚居地。",al={"离开幽影谷","小路通向哪里","走出幽影谷的路径"}}},fx={ceaa8c71={q="泰达希尔是什么？",a="泰达希尔是一棵生长在卡利姆多西北海岸外的巨型世界之树。它的名字在达纳苏斯语中意为“大地之冠”。第三次大战之后，古树议会与强大的德鲁伊催生了泰达希尔，使其成为 卡多雷 的新家园。它庞大的枝干从海中直冲而起，枝头承载着一整片森林覆盖的陆地，以及都城达纳苏斯。",al={"这棵巨树是什么","泰达希尔世界之树","关于泰达希尔"}},c8ee90fe={q="谁种下了泰达希尔？",a="玛法里奥·怒风失踪后，大德鲁伊范达尔·鹿盔说服古树议会种下一棵新的世界之树。强大的德鲁伊汇聚魔力，使它从海中拔起，希望借此恢复 卡多雷 失去的永生。然而，守护巨龙拒绝祝福它的枝干，其中尤其包括曾赐予他们永生的诺兹多姆，使这棵树的生长留下了缺陷。",al={"谁造就了泰达希尔","谁种下了泰达希尔","谁创造了世界之树"}},["8fe22cbd"]={q="暗夜精灵为什么如今住在树上？",a="第三次大战带来了毁灭，诺达希尔在海加尔山被牺牲，暗夜精灵也随之失去了世代享有的永生。为了重获永恒的生命，并找到远离大陆威胁的安全居所，卡多雷 催生了泰达希尔作为庇护所，又在高耸的枝干间建起了辉煌的都城达纳苏斯。",al={"为什么住在树上","暗夜精灵为何住在泰达希尔","为什么住在泰达希尔"}},["5b09454b"]={q="谁住在奥达希尔顶端？",a="幽影谷的领袖特纳隆·雷拳住在奥达希尔的树冠之中。他在这棵巨树高处的枝干间，监督初出茅庐的暗夜精灵守护者接受训练与入门试炼。",al={"奥达希尔顶端","谁在奥达希尔","特纳隆·雷拳 奥达希尔"}},["27b05a0e"]={q="奥达希尔和泰达希尔是同一棵树吗？",a="不是。泰达希尔是从海洋中拔起的巨型世界之树，上层枝干承载着一片岛屿般大小的土地，其上有森林、山脉和城市。奥达希尔则是一棵单独的巨型古树，扎根于幽影谷的土壤之中，而幽影谷本身就位于泰达希尔之上。",al={"奥达希尔与泰达希尔","奥达希尔是泰达希尔吗","奥达希尔与泰达希尔的区别"}},["0792cbea"]={q="这里由谁负责？",a="特纳隆·雷拳在奥达希尔顶端的居所中统管幽影谷。他指挥山谷的防御，协调当地的德鲁伊、哨兵和导师，指导新来者，并应对当地野生生物中日益蔓延的腐化。",al={"谁领导幽影谷","幽影谷领袖","幽影谷负责人"}},["3fc160d4"]={q="整个暗夜精灵族由谁领导？",a="高阶女祭司泰兰德·语风通过艾露恩姐妹会领导卡多雷，而在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔目前执掌塞纳里奥议会。祭司与德鲁伊共同在首都达纳苏斯领导暗夜精灵一族。",al={"暗夜精灵领袖","谁统治暗夜精灵","卡多雷领袖"}},["003c713a"]={q="树林蜘蛛是什么，为什么会在这里？",a="树林蜘蛛是在这棵年轻的世界之树内部、黑丝洞中筑巢的巨型蛛类。它们过去大多独自栖居，但笼罩泰达希尔的黑暗污染使它们陷入凶暴的狂乱，迫使它们离开巢穴，攻击任何在北部游荡的人。",al={"泰达希尔树林蜘蛛","幽影谷为什么有蜘蛛","幽影谷蜘蛛"}},["19b22b7f"]={q="树林蜘蛛一直都在那个洞里吗？",a="是的。西北方的黑丝洞是泰达希尔巨型蜘蛛的天然栖息地。然而，近日在蛛母基塞伊斯的统领下，它们的敌意急剧增强，使洞穴变成了初出茅庐的旅人面临的致命险地。",al={"蜘蛛一直在黑丝洞吗","黑丝洞历史","蜘蛛一直在这里吗"}},b0a66f5b={q="艾露恩是谁？",a="艾露恩是暗夜精灵敬奉的月亮女神，与和平、星光和治愈息息相关。卡多雷自远古以来便崇拜她，而由泰兰德·语风领导的高阶女祭司们引导她的天界之力，保护族人，惩击敌人。",al={"月亮女神艾露恩","艾露恩与暗夜精灵","女神艾露恩"}},["2f0ec344"]={q="多兰纳尔是什么地方，为什么大家总让我去那里？",a="多兰纳尔是最近的大型聚居地，穿过南边的山口，便能抵达这座位于幽影谷西南方的村镇。谷中的导师考验过你的本领后，就会派你前往多兰纳尔，继续训练、学习手艺，并协助应对泰达希尔各地的危机。",al={"多兰纳尔是什么地方","为什么去多兰纳尔","多兰纳尔村庄"}},["94588242"]={q="暗夜精灵为什么失去了永生？",a="第三次大战期间，燃烧军团进军海加尔山，企图吞噬最初的世界之树诺达希尔。玛法里奥·怒风引导森林之魂与古树的力量，彻底消灭了恶魔领主阿克蒙德。牺牲诺达希尔也摧毁了守护巨龙赐予的魔法，使卡多雷失去了不老之身。",al={"暗夜精灵失去永生","暗夜精灵为什么会死","暗夜精灵永生的丧失"}},b6ffca43={q="我是怎么来到幽影谷的？",a="你身处泰达希尔东北部高耸枝冠中的一片幽静林地，这棵年轻的世界之树生长在卡利姆多北部海岸之外。在大树奥达希尔的庇护下，这片宁静的森林远离外界，是初怀志向的卡多雷的避风港与训练场。你响应长者的召唤来到这里，在幽静中磨炼本领，然后踏上族人新家园更广阔的枝干。",al={"怎么来到这里的","如何抵达这里的","为什么在这里"}},e332bd9f={q="我在幽影谷该做些什么？",a="你的任务是帮助奥达希尔的守护者与长者，应对不断滋扰林地的问题。最近，一股邪恶的腐化开始扰乱当地的野生生物，使本地的树林蜘蛛和林间野兽变得充满敌意。与大树周围的训练师和领袖交谈，根除黑丝洞中滋生的病害，让森林恢复平衡，然后沿着小路向南前往多兰纳尔。",al={"在这里该做什么","来这里的目的是什么","在幽影谷做什么"}},["3011769b"]={q="新晋暗夜精灵为什么要从幽影谷开始？",a="第三次大战结束、诺达希尔被牺牲后，暗夜精灵渡海迁往泰达希尔，重新开始生活。幽影谷是树冠中防护最严密、最为隐蔽的一隅，环绕的山岭将其与外界隔开，经验丰富的哨兵在此守卫。你刚刚开始研习德鲁伊之道、战斗技艺或艾露恩的赐福，因此族人让你在奥达希尔的安全庇护下接受训练，再派你进入更广阔、更危险的世界。",al={"暗夜精灵为什么从这里开始","暗夜精灵为什么从幽影谷起步","为什么从幽影谷开始"}}},fp="10,264,18.302.0,16.258.0,19.184.0,51.156.0,33.142.0,28.168.0"}
P.entries["subzone:shadowprey-village"] = {n="葬影村",s="葬影村是部落位于凄凉之地萨瑟里斯海岸南部岩石海岸线上的一处偏远渔业定居点。这里居住着大量暗矛巨魔渔民，并有牛头人后勤人员提供支持，它在荒凉的废土中作为至关重要的海岸前哨站和贸易生命线发挥着作用。",h="葬影村是部落位于凄凉之地萨瑟里斯海岸南部岩石海岸线上的一处偏远渔业定居点。这里居住着大量暗矛巨魔渔民，并有牛头人后勤人员提供支持，它在荒凉的废土中作为至关重要的海岸前哨站和贸易生命线发挥着作用。",kw={"凄凉之地","萨瑟里斯海岸","葬影村","泰迦·慧鬃","巨魔捕鱼"},ang={["faction:Horde"]="对于穿越凄凉之地的部落旅行者来说，葬影村提供了科多兽坟场以南唯一的海岸休息站、飞行枢纽和安全的补给基地。",["race:Troll"]="葬影村是卡利姆多中部少有的暗矛海岸文化避风港，展示了该部族传统的长矛捕鱼、潜水和海岸生存技巧。"},sec={{t="海岸上的避风港",b="葬影村依偎在凄凉之地南部的悬崖边，为这个以半人马部族和荒芜废土而闻名的地区提供了一处安全的避风港。该定居点主要由巨魔渔民的营地组成，他们的捕获物不仅维持了村庄自身的生存，也为幽灵岗哨等内陆哨所提供了补给。尽管海岸线崎岖不平，但高耸的木制码头延伸至海洋中，让当地的垂钓者能够深入深海，并在散布于萨瑟里斯海岸的沉船残骸间潜水捕捞贝类。"},{t="海岸的磨难",b="在凄凉之地维持一个前线港口充满了危险。除了内陆肆虐的半人马和召唤恶魔的火刃氏族带来的威胁外，海洋本身也用汹涌的浅滩和饥饿的海洋生物考验着村庄的生存能力。包括泰迦·慧鬃以及旅店和双足飞龙管理员在内的牛头人盟友，正协助加强防御，并保持着连接整个卡利姆多的贸易路线畅通。"}},faq={{q="为什么葬影村对部落很重要？",a="凄凉之地是一片缺乏自然资源的荒凉废土。葬影村是部落在该地区唯一的海岸港口，它运送着至关重要的鱼类和贝类捕获物来供养幽灵岗哨等驻军，同时提供了一个连接石爪山脉、雷霆崖和菲拉斯的双足飞龙旅行枢纽。",al={"葬影村的目的","为什么葬影村在这里","葬影村在部落中的角色"}},{q="谁领导着葬影村？",a="该定居点没有记载有单一的首领。村庄以一种松散的巨魔渔民社区形式运作，而像泰迦·慧鬃这样的牛头人居民则协助防守，抵御着在凄凉之地蠢蠢欲动的火刃氏族邪教徒。",al={"葬影村的首领","谁负责葬影村"}},{q="为什么在巨魔村庄里会有牛头人负责服务工作？",a="葬影村最初是作为土著暗矛部族的渔业前哨站建立的，但它作为区域供应枢纽的角色吸引了部落更广泛的后勤机构。牛头人负责监督重要的共享基础设施，维护旅店，管理马厩，并指挥连接港口与莫高雷及其他地区的双足飞龙管理员。",al={"葬影村的牛头人","为什么牛头人在这里"}},{q="有哪些威胁在困扰着渔民？",a="除了内陆敌对的半人马之外，村庄还必须面对火刃氏族的威胁，他们的召唤恶魔的邪教徒盘踞在雷斧堡垒中，此外还有海岸汹涌的水域和危险的海洋生物。",al={"葬影村的问题","葬影村的威胁"}}},fp="18,189,21.397.0,20.368.0,49.264.0,29.209.0,61.267.0,41.193.0"}
P.entries["subzone:shadowsong-shrine"] = {n="影歌神殿",s="影歌神殿是一处位于艾萨拉西部山坡上的废弃圣地，距离灰谷边境不远。这里不仅有古代上层精灵不安的灵魂徘徊，更承载着影歌家族那显赫的名号，尽管它与该家族真正的历史渊源至今仍笼罩在迷雾之中。",h="影歌神殿是一处位于艾萨拉西部山坡上的废弃圣地，距离灰谷边境不远。这里不仅有古代上层精灵不安的灵魂徘徊，更承载着影歌家族那显赫的名号，尽管它与该家族真正的历史渊源至今仍笼罩在迷雾之中。",kw={"艾萨拉","鬼魂","上层精灵","玛维","废墟","影歌","神殿"},ang={["race:NightElf"]="对于暗夜精灵来说，影歌这个名字因守望者玛维而令人肃然起敬，因此这处遗迹被备受折磨的上层精灵鬼魂所亵渎，显得格外令人悲伤。"},sec={{t="被诅咒的遗产",b="影歌神殿坐落于艾萨拉破碎大地之上的一处高坡，如今已成了一片长满杂草的古老废墟。与周围大部分海岸地区一样，这里也饱受徘徊在倒塌石柱间的上层精灵鬼魂的侵扰，它们试图消灭任何胆敢踏入其领地的凡人生命。这座神殿与伊利丹·怒风那毫不留情的守望者玛维·影歌同名。至于这座圣地究竟是为了纪念她的家族，还是在大分裂之前就已经存在，这已是一个被岁月掩埋的秘密。"}},faq={{q="影歌神殿是什么地方？",a="它是一处位于艾萨拉西部高地上的暗夜精灵古迹。如今它已残破不堪，被敌对的上层精灵幽灵所占据。",al={"这是什么地方","影歌神殿信息","艾萨拉山坡上的废墟"}},{q="这座神殿是以谁的名字命名的？",a="它与曾经囚禁伊利丹·怒风的著名守望者玛维·影歌同名。然而，这座神殿是否是为了纪念她或她的家族，并没有明确的记载。",al={"玛维·影歌","为何叫影歌"}},{q="为什么这座神殿闹鬼？",a="和艾萨拉各处的许多废墟一样，该遗迹在一万年前的大分裂中遭受了毁灭。在大灾变中丧生的上层精灵的灵魂被束缚在这些石头上，陷入了疯狂，并对生者怀有敌意。",al={"这里为什么会有鬼魂","艾萨拉的上层精灵鬼魂","影歌神殿的鬼魂"}},{q="这座神殿位于哪里？",a="它位于艾萨拉西部的一座山丘之上，在灰谷森林边界的东面，距离塔伦迪斯营地并不远。",al={"影歌神殿在哪里","影歌神殿位置","如何找到影歌神殿"}}},fp="17,227,16.337.0,26.130.0,30.161.0,26.176.0,28.107.0"}
P.entries["subzone:shadowthread-cave"] = {n="黑丝洞",s="黑丝洞位于幽影谷西北方的峭壁之下，洞中的蜘蛛已变得十分危险。这群蜘蛛如今威胁着奥达希尔附近年轻的 kaldorei。",h="黑丝洞位于幽影谷西北方的峭壁之下，洞中的蜘蛛已变得十分危险。这群蜘蛛如今威胁着奥达希尔附近年轻的 kaldorei。",kw={"邪恶的基塞伊斯","幽影谷","黑丝洞","蛛丝","泰达希尔","树林蜘蛛"},ang={["class:Druid"]="身为德鲁伊，你能从 Webwood 蛛群肆无忌惮的攻击行为中看出一个令人不安的征兆：泰达希尔的自然和谐已遭到严重破坏。",["race:NightElf"]="身为年轻的暗夜精灵，你最初的试炼之一，就是清剿黑丝洞并杀死基塞伊斯，守护神圣的家园，抵御逐渐蔓延的腐化。"},sec={{t="躁动的蛛群",b="黑丝洞的入口位于幽影谷西北部的林荫深处，是泰达希尔巨型蜘蛛的巢穴。早些年，蜘蛛在世界之树的嫩枝旁安静地生活。如今，它们凶狠地守卫着自己的领地。webwood 蛛丝塞满了石质通道，蛛群威胁着那些走出奥达希尔的年轻 kaldorei。"},{t="基塞伊斯",b="基塞伊斯盘踞在黑丝洞的最深处。这只可怕的蛛母远比普通的 webwood 爬行者凶猛。年轻的暗夜精灵哨兵和德鲁伊进入洞穴，遏制蛛患并杀死基塞伊斯，以免侵染泰达希尔野生动物的腐化吞没幽影谷这片庇护之地。"}},faq={{q="黑丝洞在哪里？",a="黑丝洞位于幽影谷的西北角，紧靠岩石山坡，这片山坡毗邻泰达希尔暗夜精灵初出茅庐时所在的山谷。",al={"黑丝洞位置","黑丝洞在哪","寻找黑丝洞"}},{q="洞里的蜘蛛为何如此凶猛？",a="蜘蛛一直栖息在黑丝洞中，但一种邪恶的疾病，加上泰达希尔日益加剧的失衡，已使当地的野生动物陷入疯狂。树林 蜘蛛变得异常凶暴。",al={"蜘蛛为何敌对","黑丝洞蜘蛛腐化","蜘蛛为何攻击"}},{q="基塞伊斯是谁？",a="基塞伊斯是一只体型庞大、身带剧毒的 树林 蛛母，栖身于黑丝洞的最深处。威胁幽影谷年轻 卡多雷 的凶暴蛛群，正是她的子嗣。",al={"基塞伊斯","基塞伊斯是谁","黑丝洞蜘蛛首领"}},{q="洞穴虽然危险，却有何珍贵之处？",a="层层叠叠、天然织成的 树林 蛛丝布满了洞穴。幽暗洞室中的蜘蛛大量织出这种珍贵而坚韧的制作材料。",al={"黑丝洞蛛丝","幽影谷蛛丝"}}},fp="17,132,24.311.0,17.323.0,35.142.0,46.196.0,25.191.0,48.161.0"}
P.entries["subzone:shady-rest-inn"] = {n="树荫旅店",s="树荫旅店曾是一处温馨的驿站，由人类建造，坐落在贫瘠之地与塞拉摩岛之间的道路旁。如今，这里只剩下焦黑的木材和余烬，此前发生了一起突如其来的暴力纵火事件。这场悲剧令旅店老板心碎不已，并导致整个沼泽地区的局势变得紧张，调查人员仍在废墟中搜寻线索。",h="树荫旅店曾是一处温馨的驿站，由人类建造，坐落在贫瘠之地与塞拉摩岛之间的道路旁。如今，这里只剩下焦黑的木材和余烬，此前发生了一起突如其来的暴力纵火事件。这场悲剧令旅店老板心碎不已，并导致整个沼泽地区的局势变得紧张，调查人员...",kw={"纵火","贫瘠之地边界","尘泥沼泽","恐怖图腾","詹姆斯·海厄尔","帕瓦尔·雷瑟","树荫旅店","塞拉摩"},ang={["faction:Alliance"]="旅店的毁坏代表着通往塞拉摩岛的主要陆路交通遭到了严重的安全威胁，不仅威胁着往来的旅客，也加剧了对潜伏敌人的恐惧。",["race:Tauren"]="关于谁烧毁了旅店的猜疑，威胁着要破坏部落与Jaina Proudmoore在尘泥沼泽势力之间脆弱的和平。"},sec={{t="边界的灰烬",b="树荫旅店旨在为往来于尘泥沼泽和贫瘠之地之间危险路段的旅人提供服务，是这片荒凉之地中一处文明而舒适的据点。然而，随着旅店在一次毁灭性的大火中被夷为平地，这一切戛然而止。旅店老板詹姆斯·海厄尔在大火中幸存，但他的妻子和孩子却不幸丧生。遭受创伤和悲痛的海厄尔一无所有，而这片废墟成了犯罪现场，受到塞拉摩当局的严密调查，他们急于查明纵火的真凶。"},{t="疑云重重",b="最初的纵火调查指向人类逃兵和可疑士兵，帕瓦尔·雷瑟和卡德维尔中尉等人都曾被列为重大嫌疑对象，但随后都遭遇了不幸。然而，从灰烬中发现的物证（包括独特的蹄印和仪式徽记）表明，这不仅仅是一次内部背叛。纵火行径是由冷酷无情的恐怖图腾牛头人实施的，他们从沼泽深处发动袭击，意在挑拨塞拉摩与其邻国之间的关系。"}},faq={{q="树荫旅店发生了什么？",a="旅店遭到袭击并被烧毁。起初人们怀疑是逃兵和流氓联盟士兵所为，调查人员仍在废墟中搜寻线索，以查明纵火的真正幕后黑手。",al={"为什么树荫旅店被烧","旅店发生了什么","谁烧毁了树荫旅店"}},{q="谁拥有并经营这家旅店？",a="詹姆斯·海厄尔经营着树荫旅店。他在大火中幸存，但他的妻子和孩子在火海中丧生，这让他遭受了极大的创伤。",al={"树荫旅店老板","谁经营树荫旅店","詹姆斯·海厄尔"}},{q="树荫旅店位于哪里？",a="废墟位于尘泥沼泽西部的主要道路旁，就在沼泽与贫瘠之地交界的附近。",al={"树荫旅店位置","树荫旅店在哪里"}},{q="帕瓦尔·雷瑟和卡德维尔中尉是谁？",a="他们是在火灾初步调查中被牵连的人类嫌疑人。两人都在调查人员获得供词或最终查明他们参与程度之前就死了。",al={"雷瑟是谁","树荫旅店 卡德维尔上尉","雷瑟和卡德维尔"}}},fp="14,242,19.325.0,18.323.1,36.174.1,31.132.0,36.114.0,45.189.1"}
P.entries["subzone:shalzaru-s-lair"] = {n="沙尔扎鲁的巢穴",s="沙尔扎鲁的巢穴是一处蔓延的深水洞穴，位于菲拉斯恐怖之岛的北端。它是仇恨之脊纳迦的一座主要据点，也是其强大的主人沙尔扎鲁的藏身处。这些蛇形入侵者在潮湿的隧道中策划着侵略行动，就在羽月要塞的南面。",h="沙尔扎鲁的巢穴是一处蔓延的深水洞穴，位于菲拉斯恐怖之岛的北端。它是仇恨之脊纳迦的一座主要据点，也是其强大的主人沙尔扎鲁的藏身处。这些蛇形入侵者在潮湿的隧道中策划着侵略行动，就在羽月要塞的南面。",kw={"羽月要塞","菲拉斯","仇恨之脊","恐怖之岛","纳迦洞穴","沙尔扎鲁","沙尔扎鲁的巢穴"},ang={["faction:Alliance"]="仇恨之脊在洞穴中的集结威胁到了羽月要塞的补给线和和平，这使得清除沙尔扎鲁和他的族群成为哨兵及其盟友的首要任务。",["race:NightElf"]="纳迦亵渎菲拉斯古老海岸遗迹的邪恶行径，痛苦地提醒着人们大分裂的往事，以及上层精灵堕落并变异为怪物的过程。"},sec={{t="浅滩中的蛇穴",b="沙尔扎鲁的巢穴开凿在恐怖之岛北端的崎岖悬崖中，分为一个巨大的主洞穴和一个较小的附属室，由淹没的地下水道相连。洞内遍布着保持高度警惕的仇恨之脊蛇卫和施法女巫。在深处居住着领主沙尔扎鲁，这位蛇形霸主指挥着整个岛上的仇恨之脊族群。它距离萨尔多岛很近，对驻扎在海峡对岸羽月要塞的暗夜精灵哨兵构成了直接且持续的威胁。"}},faq={{q="沙尔扎鲁的巢穴位于何处？",a="沙尔扎鲁的巢穴位于恐怖之岛的北端，该岛位于萨尔多岛和羽月要塞正南方的菲拉斯西海岸外。",al={"沙尔扎鲁的巢穴位置","沙尔扎鲁巢穴位置","如何找到沙尔扎鲁的巢穴"}},{q="沙尔扎鲁是谁？",a="沙尔扎鲁是一位强大的纳迦督军，也是栖息在恐怖之岛的仇恨之脊部族的主人。他从巢穴内被淹没的深处指挥着他的部队。",al={"沙尔扎鲁是谁","沙尔扎鲁背景故事","沙尔扎鲁的巢穴首领"}},{q="这座洞穴里居住着什么生物？",a="洞穴中到处都是仇恨之脊纳迦，主要是看守干燥路径的警惕的仇恨之脊蛇卫，以及在地下水域中引导魔法的仇恨之脊女巫。",al={"沙尔扎鲁的巢穴敌人","仇恨之脊纳迦洞穴怪物"}},{q="为什么这座巢穴对当地的暗夜精灵很重要？",a="因为恐怖之岛位于羽月要塞隔水相望的地方，沙尔扎鲁的巢穴内集结的纳迦部队对珊蒂斯·羽月的军队以及萨尔多岛的安全构成了直接的军事威胁。",al={"为什么暗夜精灵关注沙尔扎鲁","羽月要塞的纳迦威胁"}}},fp="15,157,29.426.0,33.143.0,16.147.0,33.129.0,52.172.0"}
P.entries["subzone:shaper-s-terrace"] = {n="塑造者之台",s="塑造者之台位于马绍尔营地上方的北部峭壁高处，是一处以古老泰坦建筑为标志的神秘观景台。它以塑造者卡兹格罗斯命名，默默见证了塑造安戈洛环形山的原始实验。",h="塑造者之台位于马绍尔营地上方的北部峭壁高处，是一处以古老泰坦建筑为标志的神秘观景台。它以塑造者卡兹格罗斯命名，默默见证了塑造安戈洛环形山的原始实验。",kw={"环形山","卡兹格罗斯","马绍尔营地","塑造者","塑造者之台","泰坦","安戈洛"},ang={["race:Dwarf"]="对于探寻自身泰坦血统的矮人来说，塑造者之台提供了又一个窥探卡兹格罗斯建筑风格和创造者宏伟杰作的迷人视角。"},sec={{t="泰坦的遗产",b="塑造者之台俯瞰着安戈洛环形山郁郁葱葱的史前盆地，保留着泰坦留下的宏伟石制建筑。据信此处是献给塑造者卡兹格罗斯的，这座高耸的平台见证了那些曾将环形山培育为艾泽拉斯早期生命活体实验室的星界建筑师。从这些高耸的石块上，古老的实体曾在此观察并引导下方的动植物。其冰冷的石拱门和巨大的金属基座与下方繁茂的原始荒野形成了鲜明而神秘的对比。"}},faq={{q="塑造者之台是什么？",a="塑造者之台是一处位于安戈洛环形山北部峭壁沿线、马绍尔营地正上方的高处泰坦遗迹。它拥有与曾经塑造这片土地的泰坦相关的石制建筑。",al={"塑造者之台","这是什么平台","安戈洛平台"}},{q="“塑造者”是谁？",a="该平台指的是塑造者卡兹格罗斯，他是帮助在遥远的过去创造和培育艾泽拉斯世界的泰坦创造者之一。",al={"塑造者是谁","卡兹格罗斯","谁建造了塑造者之台"}}},fp="16,182,22.487.0,29.166.0,21.112.0"}
P.entries["subzone:shatter-scar-vale"] = {n="碎痕谷",s="碎痕谷是位于费伍德森林中部的一片焦土盆地，就在血毒瀑布的正北方。它是第三次战争期间恶魔地狱火坠入卡利姆多北部的中心地带。时至今日，这些陨坑仍在燃烧着魔火，并残留着燃烧军团的余孽。",h="碎痕谷是位于费伍德森林中部的一片焦土盆地，就在血毒瀑布的正北方。它是第三次战争期间恶魔地狱火坠入卡利姆多北部的中心地带。时至今日，这些陨坑仍在燃烧着魔火，并残留着燃烧军团的余孽。",kw={"血毒瀑布","燃烧军团","陨坑","费伍德森林","地狱火","碎痕谷"},ang={["class:Druid"]="山谷中阴燃的伤痕是卡利姆多大地上久久未能愈合的创口，只要军团的构装体还在燃烧，它们就无法痊愈。",["class:Warlock"]="游荡在这些陨坑中的地狱火，其体内注入了邪能的核心，代表了军团入侵后留下的混乱魔法的强力传导源。"},sec={{t="地狱火的冲击",b="第三次战争期间，燃烧军团向卡利姆多北部投下了活体攻城武器。碎痕谷承受了这场天外打击的主要冲击。恶魔地狱火从天而降，撕裂了古老的树冠，在大地上砸出了深深的坑洞。猛烈的撞击摧毁了地形，留下了至今仍在燃烧着邪恶之火的焦黑深坑。尽管军团在海加尔山战败，但地狱火和残留的小型恶魔从未真正散去，始终在这片伤痕累累的土地上固守着据点。"}},faq={{q="为什么地面上到处都是陨坑？",a="这些陨坑是在第三次战争中形成的，当时燃烧军团用地狱火轰炸了这片森林。这些巨大的邪能石构体像流星一样从天而降，砸入地面，在山谷中留下了阴燃的撞击痕迹。",al={"费伍德森林的陨坑","为什么碎痕谷会有陨坑","是什么造成了陨坑"}},{q="碎痕谷里游荡着什么生物？",a="山谷中依然充斥着燃烧军团的构装体和仆从。活体地狱火仍守卫着阴燃的撞击坑，与入侵失败后留下的其他游荡的小型恶魔一起驻扎于此。",al={"这里有什么怪物","碎痕谷的敌人"}},{q="碎痕谷位于何处？",a="碎痕谷位于费伍德森林的中部区域，坐落在血毒瀑布的正北方，森林主路东侧。",al={"碎痕谷的位置","碎痕谷在哪里"}}},fp="17,219,23.485.0,37.228.0,38.178.0,35.127.0"}
P.entries["subzone:shattered-strand"] = {n="破碎海岸",s="破碎海岸是艾萨拉风暴海湾北缘的一片荒凉而崎岖的海岸线。这里巨浪拍岸，古老的遗迹随处可见，沙滩上到处都是危险的海洋野兽和部落制的海洋生物。",h="破碎海岸是艾萨拉风暴海湾北缘的一片荒凉而崎岖的海岸线。这里巨浪拍岸，古老的遗迹随处可见，沙滩上到处都是危险的海洋野兽和部落制的海洋生物。",kw={"艾萨拉","风暴海湾","九头蛇","麦克罗拉","鱼人","海巨人","破碎海岸","亚考兰神殿","埃达拉之塔"},ang={["class:Hunter"]="这片海岸提供了一个未驯服的试炼场，充满了强大的九头蛇和沿海野兽，非常适合那些寻找强大野兽或研究卡利姆多海岸掠食性动物群的冒险者。"},sec={{t="危险的海岸线",b="破碎海岸沿着风暴海湾的北缘延伸，绝非一片宁静的海岸。岩石遍布的沙滩和潮汐浅滩上栖息着大量的攻击性野生生物，包括高大的海巨人、多头九头蛇和凶猛的麦克罗拉，旁边还有沿海鱼人的营地。破碎的精灵建筑俯瞰着波涛，以古老的亚考兰神殿和孤耸的埃达拉之塔等地标为中心。对于在艾萨拉险峻的悬崖间穿行的旅行者来说，降落到这片孤立的海岸意味着要面对该地区最致命的某些两栖威胁。"}},faq={{q="破碎海岸位于哪里？",a="破碎海岸构成了风暴海湾的北岸，位于艾萨拉的东部地区，耸立在巨大的悬崖之下。",al={"破碎海岸位置","破碎海岸在哪里","破碎海岸地图"}},{q="哪些生物栖息在破碎海岸？",a="海岸线上到处出没着凶恶的九头蛇、巨大的海巨人、披甲的麦克罗拉以及成群结队的敌对鱼人，它们在潮滩上巡逻。",al={"破碎海岸怪物","破碎海岸生物","破碎海岸野兽"}},{q="在海滩上能发现哪些著名的遗迹？",a="海岸上有古老的上层精灵建筑，其中最著名的是亚考兰神殿，以及附近俯瞰海湾的埃达拉之塔。",al={"破碎海岸遗迹","破碎海岸建筑","破碎海岸地标"}},{q="破碎海岸适合随意探索吗？",a="不适合。海滩位置偏僻，由于周围悬崖峭壁林立，难以迅速逃离，而且挤满了掠食性水生野兽和强大的巨人。",al={"破碎海岸危险吗","破碎海岸等级"}}},fp="16,153,23.413.0,38.125.0,44.81.0,48.79.0,52.140.0"}
P.entries["subzone:shifting-mire"] = {n="流沙泥潭",s="流沙泥潭构成了悲伤沼泽那片广袤而泥泞的核心区域，位于泪水之池的西侧。它的名字源于浑浊水底那种奇异且不安分的淤泥，这些淤泥似乎受到某种无形力量的影响，不断漂移和堆积。",h="流沙泥潭构成了悲伤沼泽那片广袤而泥泞的核心区域，位于泪水之池的西侧。它的名字源于浑浊水底那种奇异且不安分的淤泥，这些淤泥似乎受到某种无形力量的影响，不断漂移和堆积。",kw={"鳄鱼","美洲豹","失落者","流沙泥潭","淤泥","悲伤织网蛛","悲伤沼泽"},ang={["class:Hunter"]="纠缠的灌木丛和漂移的水域使得追踪变得危险重重，这要求猎人们必须保持警惕，提防隐藏在叶丛中的隐秘沼泽美洲豹和剧毒的悲伤织网蛛。"},sec={{t="生机勃勃的沼泽",b="流沙泥潭横跨沼泽地带的中心区域，是一片令人不安的广阔地带，在这里很难找到坚实的立足点。沼泽底部的淤泥仿佛被一种活生生的意志所驱使，不断移动和聚集，这股意志是由渗透在泥炭中奇异的环境能量所驱动。在漂移的泥沼中，潜伏着捕食性的沼泽美洲豹、巨大的悲伤织网蛛和饥饿的锯齿鳄鱼，而被称为“失落者”的破碎德莱尼部族也在这些沉没的小径中徘徊。"}},faq={{q="为什么它被称为流沙泥潭？",a="该区域的名字源于沼泽底部那层极其细软的淤泥。不同于普通的沉积物，一股神秘的能量流使得这些泥土像是有生命一样在湿地中聚集、漂移和流动。",al={"流沙泥潭名字由来","为什么叫流沙泥潭","为什么地面会移动"}},{q="流沙泥潭里生活着什么生物？",a="这片泥潭中满是危险的野生动物，包括潜伏在浅滩的锯齿鳄鱼、在树枝间织网的巨型悲伤织网蛛，以及隐秘的沼泽美洲豹。这里也常有徘徊的失落者出没，他们是被家园流放并发生了扭曲的德莱尼人。",al={"流沙泥潭怪物","流沙泥潭有什么"}},{q="流沙泥潭位于哪里？",a="它涵盖了悲伤沼泽的中心地带，位于被誉为“泪水之池”的巨大湖泊正西侧。",al={"流沙泥潭位置","流沙泥潭在哪里"}}},fp="13,157,12.345.0,35.153.0,41.246.0,35.105.0"}
P.entries["subzone:shimmer-ridge"] = {n="闪光岭",s="闪光岭是一处坐落在丹莫罗北部的高地，位于铁炉堡大门正西方。这里被敌对的霜鬃巨魔占据，其岩石高地上有两个营地，由一座摇摇欲坠的桥连接。这里因是获取强效闪光草的唯一产地而闻名。",h="闪光岭是一处坐落在丹莫罗北部的高地，位于铁炉堡大门正西方。这里被敌对的霜鬃巨魔占据，其岩石高地上有两个营地，由一座摇摇欲坠的桥连接。这里因是获取强效闪光草的唯一产地而闻名。",kw={"丹莫罗","霜鬃巨魔","铁炉堡","登山者","闪光岭","闪光草","巨魔"},ang={["profession:Herbalism"]="虽然普通的植物很难在丹莫罗的零下气候中生存，但闪光岭却独一无二地支持着在霜鬃巨魔营地间培育的珍贵闪光草篮。",["race:Dwarf"]="闪光岭坐落在铁炉堡大门的阴影下，是一个令人恼火的提醒，时刻警示着持续存在的霜鬃巨魔威胁，同时也是矮人传奇烈性黑啤酒所需的优质闪光草的危险来源。"},sec={{t="霜鬃据点",b="闪光岭栖身于铁炉堡雄伟入口西侧的崎岖山坡上，是霜鬃巨魔部族的活跃据点。这个飞地分为两个跨越深谷的营地，并由一座木桥连接，由巨魔拾荒者和他们驯养的山地野猪严密把守。由于靠近主干道和矮人首都，它们对过往行人和山地巡逻队构成了持续的威胁，后者必须时刻警惕来自高地的突袭。"},{t="闪光草的代价",b="除了战略位置外，山岭还以种植闪光草而闻名，这种植物由霜鬃巨魔培育。当地矮人酿酒师非常看重这种药草，将其用于酿造强效且风味独特的高地麦酒，而这种药草在其他地方很难采摘。勇敢的登山者和新兵经常冒着遭遇霜鬃巨魔伏击和野兽袭击的危险，只为直接从巨魔的种植地采摘一篮篮珍贵的植物。"}},faq={{q="闪光岭在哪里？",a="闪光岭位于丹莫罗北部，就在通往矮人首都的巨大铁炉堡大门正西方。",al={"闪光岭位置","闪光岭在哪里","寻找闪光岭"}},{q="谁控制着闪光岭？",a="该山岭由当地的霜鬃巨魔部族占据，他们建立了两个由桥梁连接的营地，并与他们驯养的野猪一起保卫着这片高地。",al={"谁住在闪光岭","闪光岭的敌人","闪光岭的巨魔"}},{q="什么是闪光草，为什么要寻找它？",a="闪光草是一种独特的山地草药，生长在山岭寒冷的山坡上。当地矮人酿酒师非常珍视它，将其作为酿造特制、风味独特的高地麦酒的必备原料。",al={"闪光草用途","什么是闪光草","闪光草目的"}},{q="为什么矮人不彻底清除这些巨魔？",a="铁炉堡的军队忙于更广泛的防御和外部事务，使得丹莫罗当地的霜鬃巨魔据点等威胁只能由区域内的登山者和四处游荡的新兵来应对。",al={"为什么铁炉堡无视闪光岭","铁炉堡与霜鬃巨魔","矮人对闪光岭的反应"}}},fx={["92b9c418"]={q="闪光岭是什么地方？",a="闪光岭是丹莫罗北部的一片崎岖高地，就在宏伟的铁炉堡大门西侧。这片危险的领地由霜鬃巨魔占据，他们在高处建起了两座独立的营地，以一座木桥相连。除了盘踞于此的巨魔战帮和他们驯养的野猪，这道山岭还以出产微光草闻名，这种效力强劲的本地植物深受附近矮人酿酒师的青睐。",al={"闪光岭是什么地方","闪光岭概况","闪光岭介绍"}},aaffe09f={q="闪光岭危险吗？",a="是的，对缺乏经验的旅人而言，这里相当危险。居住在山岭各处的霜鬃巨魔极其敌视外来者，严密守卫着营地和微光草种植地。凶悍的巨魔守卫与他们饲养驯服的野猪遍布山岭，任何贸然登上高地的人，都可能很快被当地的战帮击溃。",al={"闪光岭安全吗","闪光岭的危险","闪光岭有多危险"}},e59eca35={q="为什么叫闪光岭？",a="这个名字的由来尚不清楚。山岭以微光草闻名，霜鬃巨魔种植这种植物，矮人酿酒师则寻求用它酿造麦酒。",al={"闪光岭名字由来","为什么叫闪光岭","闪光岭的名字从何而来"}}},fp="13,160,22.280.0,24.280.0,31.111.0,27.107.0,47.118.0,54.181.0"}
P.entries["subzone:shimmering-flats"] = {n="闪光平原",s="闪光平原是一片广阔的盐碱滩，位于千针石林的东南端，毗邻塔纳利斯沙漠。这里曾经是一个古老湖泊的湖床，如今这片被太阳炙烤的荒原以沙漠赛道的高速机械竞赛和凶猛的沙漠野兽而闻名。",h="闪光平原是一片广阔的盐碱滩，位于千针石林的东南端，毗邻塔纳利斯沙漠。这里曾经是一个古老湖泊的湖床，如今这片被太阳炙烤的荒原以沙漠赛道的高速机械竞赛和凶猛的沙漠野兽而闻名。",kw={"沙漠赛道","普兹克","锈锤","盐滩","闪光平原","其拉虫人","塔纳利斯","千针石林"},ang={["profession:Engineering"]="这片盐滩是工程师们的朝圣之地，到处都是废料、燃料实验品，以及在地精和侏儒机械师之间无休止的竞争下进行的高速载具试运行。",["race:Gnome"]="在沙漠赛道上，侏儒驾驶员和机械陆行鸟勇敢地捍卫着侏儒工程学的骄傲，对抗着地精对手那些不稳定且具有爆炸性的设计。"},sec={{t="盐滩与极速",b="闪光平原在耀眼的南方烈日下绵延开来，是一片广袤、植被稀疏的干涸湖床，点缀着被太阳晒白的龟骨，甚至还有一艘古代帆船的木质残骸。其平坦而连续的表面使它成为卡利姆多测试实验性载具的首选之地。平原中央坐落着沙漠赛道，侏儒和地精技师们在这里不断较量，看谁的火箭车、旋翼机和引擎能达到最高速度——这往往导致在这片白色地壳上留下火光冲天的坠毁残骸和冒烟的坑洞。"},{t="盐滩的危险",b="除了赛道上轰鸣的引擎声外，这片盆地远非宁静之地。坚硬的石化蜥蜴、好斗的蝎形虫和盘旋的秃鹫捕食着在这片开阔地上减速的任何生物。再往南，锈锤挖掘场周围的地面变得愈发危险。这里最初由矮人勘探者开采，后来遭到部落争夺。当鹤嘴锄凿穿地下隧道，释放出一群凶猛的其拉虫人涌入平原南缘时，该采石场被彻底废弃。"}},faq={{q="为什么沙漠中间会有一艘破船？",a="闪光平原曾经是一个巨大的内陆湖，早已干涸。平原北部那艘破损的船只正是那片古老水域的遗迹，是湖水蒸发并形成如今广阔盐滩后留下的残骸。",al={"闪光平原的船","盐滩上的船","千针石林的沉船"}},{q="为什么侏儒和地精会聚在一起？",a="平坦且连续的盐碱地壳为测试火箭车和尖端机械装置提供了完美的场地。当地的侏儒和地精并没有为了领土而争斗，而是建立了沙漠赛道来激发他们的技术对抗，无休止地在速度、工程学和鲁莽的勇气上试图胜过对方。",al={"赛道背景故事","他们为什么要赛车","盐滩上的侏儒和地精"}},{q="南部的矮人挖掘场发生了什么事？",a="锈锤挖掘场由矮人考古学家建立，但很快就遭到了由摩克塔·克林领导的部落突袭队的攻击。随后，挖掘者无意中凿穿了一个地下的其拉虫人巢穴，释放出的蜂群般的昆虫怪物将所有人驱逐，并占领了南部平原。",al={"锈锤挖掘场背景故事","锈锤挖掘场发生了什么","盐滩上的虫子"}},{q="穿过闪光平原的道路通向哪里？",a="沿着穿过盐滩的东南方向轨道走，可以直接通往通往广阔的塔纳利斯沙漠和中立港口加基森的山隘。",al={"闪光平原通往何处","如何前往塔纳利斯","塔纳利斯出口"}}},fx={a9a42c0c={q="什么是闪光平原？",a="闪光平原是一片广阔、白得刺眼的盐碱地，位于千针石林东南端，与塔纳利斯沙漠接壤。这里原本是湖床，如今已完全干涸，寸草不生。平坦辽阔的地面吸引发明家前来测试他们最疯狂的发明，凶猛的沙漠野兽也在龟裂的大地上游荡。",al={"什么是闪光平原","闪光平原传说","关于闪光平原"}},bc39548e={q="闪光平原危险吗？",a="尽管这里看起来荒凉，却相当凶险。盐壳蜥、蝎子和秃鹫等致命的本地捕食者在开阔的盆地中出没，而地精和侏儒赛车手驾驶的不稳定火箭车，以及测试事故，也让遍地都是燃烧的残骸。此外，最近南部地区一座地下异种虫巢穴破土而出，席卷了一处古老的矮人挖掘场。",al={"闪光平原危险吗","闪光平原的危险","闪光平原有多危险"}},b2b7f543={q="为什么叫闪光平原？",a="这个名字源自阳光照射在古老的结晶盐床上时产生的刺眼景象。白色干燥矿物结壳反射出强烈的光芒，在地平线上形成耀眼闪烁的海市蜃楼，从干涸的盆地各处都能看见，绵延数英里。",al={"为什么叫闪光平原","闪光平原名称由来"}}},fp="16,232,23.462.0,19.395.0,59.178.0,41.243.0,51.233.0,54.125.0"}
P.entries["subzone:shining-strand"] = {n="闪光湖岸",s="闪光湖岸是银松森林东侧紧邻洛丹米尔湖的一片狭长湖岸，从洛丹伦废墟向南一直延伸至奥特兰克山脉崎岖的山麓地带。浅滩上聚居着充满攻击性的邪鳍鱼人，使得这段湖岸成为了毫无经验的旅行者的险地。",h="闪光湖岸是银松森林东侧紧邻洛丹米尔湖的一片狭长湖岸，从洛丹伦废墟向南一直延伸至奥特兰克山脉崎岖的山麓地带。浅滩上聚居着充满攻击性的邪鳍鱼人，使得这段湖岸成为了毫无经验的旅行者的险地。",kw={"药剂师贝拉德","黎明岛","洛丹米尔湖","闪光湖岸","银松森林","邪鳍","狼人"},ang={["faction:Horde"]="这条湖岸提供了一条清晰但危险的通道，沿着洛丹米尔湖连接着银松森林的北部入口与通往奥特兰克山脉的道路。",["race:Undead"]="对于被遗忘者来说，闪光湖岸的邪鳍鱼人是皇家药剂师学会研究新瘟疫所需宝贵样本的来源。"},sec={{t="一片有争议的海岸",b="闪光湖岸沿着银松森林的东缘延伸，与烟波浩渺的洛丹米尔湖接壤。邪鳍鱼人部族在这片浅滩上建立了多个充满攻击性的定居点，对任何试图走湖畔道路的旅行者构成了致命威胁，而野性的狼人则在岸边后方的银松森林深处游荡。"},{t="炼金收获",b="除了位于洛丹伦和南部边境之间的战略位置外，闪光湖岸及其邻近水域还引起了皇家药剂师学会的早期关注。已故的药剂师贝拉德记录了关于从当地邪鳍鱼人身上采集的奇特硬化肿瘤的研究笔记，并推测它们发生突变的生理结构可以作为研制新瘟疫的宝贵催化剂，以供希尔瓦娜斯·风行者新生的国家使用。"}},faq={{q="闪光湖岸位于哪里？",a="闪光湖岸是银松森林的东部湖岸，与洛丹米尔湖接壤。它起始于洛丹伦废墟以南，终止于将银松森林与奥特兰克山脉隔开的崎岖丘陵。",al={"闪光湖岸位置","闪光湖岸在哪里","银松海岸"}},{q="在闪光湖岸能发现什么威胁？",a="邪鳍鱼人在岸边拥有多个定居点并会攻击不慎的旅行者，而野性的狼人则在岸边的银松森林中出没。",al={"闪光湖岸怪物","闪光湖岸有什么","闪光湖岸敌人"}},{q="为什么皇家药剂师学会对这个地区感兴趣？",a="已故的药剂师贝拉德记录了当地的邪鳍鱼人身上带有具有独特生理特征的硬化肿瘤。学会认为这些增生物在他们持续进行的致命新瘟疫研究中是很有前景的成分。",al={"药剂师贝拉德","闪光湖岸瘟疫","新瘟疫肿瘤"}},{q="邪鳍是谁？",a="邪鳍是一个在闪光湖岸边建立了多个定居点的鱼人部族，这使得湖岸对毫无经验的旅行者来说非常危险。",al={"银松森林的鱼人在哪里","邪鳍位置","闪光湖岸鱼人"}}},fp="14,224,21.240.0,18.356.1,36.201.0,48.151.0,60.238.0,21.129.0"}
P.entries["subzone:shrine-of-aessina"] = {n="艾森娜神殿",s="艾森娜神殿是一处隐秘在灰谷西南部森林中的神圣精灵地标，供奉着这位古老的自然与野生生物的森林之灵。它坐落在迈斯特拉岗哨与阿斯特兰纳之间，在地区边界摩擦日益加剧的环境下，这里是一片宁静的庇护所。",h="艾森娜神殿是一处隐秘在灰谷西南部森林中的神圣精灵地标，供奉着这位古老的自然与野生生物的森林之灵。它坐落在迈斯特拉岗哨与阿斯特兰纳之间，在地区边界摩擦日益加剧的环境下，这里是一片宁静的庇护所。",kw={"艾森娜","灰谷","阿斯特兰纳","卡多雷","迈斯特拉岗哨","自然神殿","艾森娜神殿","荒野之神"},ang={["class:Druid"]="作为供奉荒野活体之灵的古老圣所，对于那些致力于维护卡利姆多自然平衡的人来说，这座神殿具有极其深远的意义。",["race:NightElf"]="对于卡多雷而言，这座神殿代表了他们与灰谷本土灵魂数个世纪以来的和谐共处，而这种和谐现在不断受到外界入侵势力的威胁。"},sec={{t="深林之中的圣所",b="艾森娜神殿位于阿斯特兰纳以西，隐蔽于深林之中，供奉着那位象征着深林之心与灵魂的神秘荒野之神。世世代代以来，暗夜精灵及其林地盟友一直尊崇着这片宁静之地，远离繁忙的主路与自然进行沟通。然而，随着部落为了收集木材和建立据点而不断向灰谷推进，整个地区内这些神圣的土地正面临着和平的不确定性。"}},faq={{q="艾森娜是谁？",a="艾森娜是一位受人尊崇的古老自然之灵和荒野之神，与原始森林的核心息息相关。暗夜精灵和林地生物视她为自然的活化之魂，代表着原始的荒野。",al={"艾森娜背景故事","艾森娜是谁","艾森娜神殿女神"}},{q="艾森娜神殿位于哪里？",a="该神殿位于灰谷西南部，坐落在迈斯特拉岗哨的西南方，以及阿斯特兰纳定居点的西侧。",al={"艾森娜神殿位置","艾森娜神殿在哪里","寻找艾森娜神殿"}},{q="为什么这个地方对暗夜精灵很重要？",a="该神殿是供奉林地之灵的古老圣地。像这样的地点将暗夜精灵社会和德鲁伊传统与卡利姆多原始的荒野直接联系在了一起。",al={"艾森娜神殿的重要性","暗夜精灵圣地"}}},fp="17,206,29.342.0,15.181.0,39.93.0,49.157.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="眠炎圣殿",s="眠炎圣殿坐落在试炼谷西北方的最高峰顶端，是一处深受部落萨满祭司尊崇的隐秘圣地。在孤独的守望者泰尔夫·祖拉姆的指引下，新晋者们会踏上艰险的攀登之路，以求与火焰元素沟通，证明他们的精神掌控力。",h="眠炎圣殿坐落在试炼谷西北方的最高峰顶端，是一处深受部落萨满祭司尊崇的隐秘圣地。在孤独的守望者泰尔夫·祖拉姆的指引下，新晋者们会踏上艰险的攀登之路，以求与火焰元素沟通，证明他们的精神掌控力。",kw={"火焰的召唤","眠炎圣殿","杜隆塔尔","火焰图腾","圣殿","怒水河流域","泰尔夫·祖拉姆","试炼谷"},ang={["class:Shaman"]="每一位年轻的兽人和巨魔萨满都必须踏上这段艰苦的旅程，攀登至这座峭壁之巅，以点燃他们与火焰之间的精神联系，并赢得他们的火焰图腾。",["faction:Horde"]="这座孤立的圣殿隐藏在杜隆塔尔上方的群山之中，守护着古老的元素仪式，这对新部落的精神核心至关重要。"},sec={{t="试炼与火焰之巅",b="想要抵达眠炎圣殿，必须勇敢地穿越一条蜿蜒狭窄的小径，起点位于怒水河沿岸，即怒水河流域的西南边缘。山顶高踞于杜隆塔尔的红色峭壁之上，可以俯瞰周围的大片土地，但如果沿着悬崖行走时稍有不慎，便会坠入深渊。在这个宁静的避难所中，徘徊着泰尔夫·祖拉姆，这是一位负责监督神圣仪式的孤独隐士。对于进行“火焰的召唤”试炼的兽人和巨魔萨满新晋者来说，圣殿的火盆就是他们的熔炉，他们必须在此利用被击败的元素生物留下的余烬点燃沉睡的煤炭，以此证明他们有能力与充满破坏力的火焰之灵沟通并保持敬畏。"}},faq={{q="如何才能抵达眠炎圣殿？",a="路径始于怒水河畔，位于怒水河流域的西南边缘，就在试炼谷的西北方。一条狭窄的山路盘旋在山峰周围，直接通往山顶。",al={"如何前往眠炎圣殿","眠炎圣殿路径","攀登眠炎圣殿山峰"}},{q="为什么这座圣殿对萨满祭司如此重要？",a="这座圣殿是一处神圣的场所，在此，部落的萨满学徒们能够学习如何理解并驾驭火焰元素。作为“火焰的召唤”修行之旅的一部分，新晋者们必须前往这座山顶来准备仪式药剂，并点燃沉睡的火盆。",al={"眠炎圣殿的用途","萨满祭司为何要去这里","火焰的召唤 圣殿"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位孤独的巨魔隐士，担任着圣殿守护者的职责。他指导年轻的萨满完成他们的试炼，调制火焰药剂以唤醒他们的精神视野，并考验他们的决心。",al={"泰尔夫·祖拉姆是谁","眠炎圣殿角色","圣殿守护者"}},{q="点燃火盆后会发生什么？",a="收集了所需仪式材料并击败了敌对火焰元素的萨满祭司，会将火焰余烬放入火盆中。这是一种祭品，旨在证明他们拥有驾驭狂暴火焰之灵的力量与纪律。",al={"眠炎圣殿的火盆","点燃火焰","圣殿火盆任务"}}},fp="27,209,27.515.0,49.184.0,39.187.0,19.186.0,41.214.0"}
P.entries["subzone:shrine-of-the-fallen-warrior"] = {n="战士之魂神殿",s="战士之魂神殿坐落于十字路口以西的一处偏僻山脊上，是一座静谧的纪念碑，俯瞰着贫瘠之地广袤的红色稀树草原。纪念碑上有一块刻有“MK”首字母的石基，旁边躺着一名阵亡的兽人战士，并由一位名为科尔特的灵魂医者温柔地守护着。",h="战士之魂神殿坐落于十字路口以西的一处偏僻山脊上，是一座静谧的纪念碑，俯瞰着贫瘠之地广袤的红色稀树草原。纪念碑上有一块刻有“MK”首字母的石基，旁边躺着一名阵亡的兽人战士，并由一位名为科尔特的灵魂医者温柔地守护着。",kw={"贫瘠之地","十字路口","科尔特","纪念碑","米歇尔·科尔特","战士之魂神殿","双子巡航者"},ang={["class:Warrior"]="各个种族的战士经常会静静地朝圣这座山丘，向一位在成为传奇之前英勇作战、随后阵亡的战友致敬。",["faction:Horde"]="这处静谧的安息之所坐落在部落领地的中心地带，展现了卡利姆多萨满与战士传统核心中的荣誉、职责与牺牲精神。"},sec={{t="寂静的守望",b="战士之魂神殿深藏于十字路口西北方的高山上，在贫瘠之地尘土飞扬、危机四伏的环境中，它是一处格外肃穆的避难所。想要找到它，旅行者必须沿着山顶西南方蜿蜒的山脊小径攀登，直到抵达一个平缓的土丘。山顶上矗立着一座雕刻过的石碑，石基上刻着“MK”的首字母。碑前躺着一具穿着盔甲的兽人战士遗体，一位名为科尔特的灵魂医者日夜守护于此。这里没有战斗的号角，只有为了纪念一位曾经行走在卡利姆多大地上的勇士而进行的静默沉思。"},{t="纪念碑的意义",b="在游戏世界中，这座神殿是向一位部落已故勇士致以永恒敬意的纪念，他的灵魂在灵魂的照拂下长存。在现实中，这座纪念碑是游戏美术团队为了纪念Michel Koiter而创作的深情致敬，他是一位备受爱戴的插画师，在游戏开发期间不幸离世。沉睡的战士正是以科尔特自己的测试版角色“Twincruiser”为原型塑造的，让他的身影在卡利姆多开阔的天空下永垂不朽。"}},faq={{q="战士之魂神殿位于哪里？",a="该神殿位于贫瘠之地北部，十字路口以西的一座小山上。旅行者可以通过寻找高地西南方的山脊底部，并沿着蜿蜒的小路向上走，即可到达那片草丘。",al={"神殿位置","神殿在哪里","如何前往战士之魂神殿"}},{q="躺在石基上的兽人是谁？",a="在游戏中，他代表着一位备受尊敬的阵亡战士。在现实中，他是直接以双子巡航者为原型塑造的，那是已故暴雪美术师米歇尔·科尔特在早期开发阶段所扮演的兽人战士角色。",al={"死去的兽人是谁","阵亡战士的身份","双子巡游者"}},{q="石碑上刻的“MK”代表什么意思？",a="卢恩字母首字母缩写“MK”是为了纪念米歇尔 科尔特，他是一位在2004年游戏开发期间离世的资深美术师。",al={"mk首字母","mk代表什么","石头上的字母"}},{q="站在神殿旁边的灵魂医者是谁？",a="这位灵魂医者的名字叫科尔特。与普通只在灵魂死亡时才显现的灵魂医者不同，科尔特始终在此守望，任何跋涉上山的活着的漫游者都能清楚地看到他。",al={"灵魂医者科尔特","神殿的天使","幽灵是谁"}},{q="与这座神殿相关的任务吗？",a="没有。战士之魂神殿不属于任何任务线或阵营冲突的一部分。它仅仅作为一个肃穆的沉思、怀念与致敬之地而存在。",al={"神殿任务","战士之魂神殿的任务","这里有任务吗"}}},fx={["7e92bc4e"]={q="什么是战士之魂神殿？",a="战士之魂神殿是一座宁静而庄严的纪念圣地，坐落在十字路口以西的一座高山之上。这里有一座精雕细琢的石台，上面安放着一位受人敬仰的兽人战士；一座方尖碑和一名幽灵守卫守护着石台。艾泽拉斯各地的旅行者都会来到这里，在远离贫瘠之地纷争的地方静静致敬。",al={"什么是战士之魂神殿","贫瘠之地的战士之魂神殿","贫瘠之地山上的纪念碑"}},a34bf1b4={q="战士之魂神殿危险吗？",a="不危险。神殿是一处神圣的圣地，不受敌对生物或交战阵营侵扰。尽管下方的贫瘠之地遍布徘徊的野兽、刺背野猪人和敌对士兵，但山顶的纪念地始终宁静祥和，任何登上山顶的旅行者都能在此安然停留。",al={"战士之魂神殿安全吗","神殿危险吗","神殿里的敌人"}}},fp="28,190,14.458.0,27.361.0,50.170.0,37.185.0,46.103.0,52.166.0,49.137.0"}
P.entries["subzone:si-7-stormwind-city"] = {n="SI:7 (Stormwind City)",s="这座不起眼的石砌庄园位于旧城区的东角，是暴风城王国精英情报和间谍机构——军情七处（SI:7）的总部所在地。在那扇沉重的大门后，间谍大师马迪亚斯·肖尔和他的高级特工们静静地监视着威胁王国的敌人，协调着遍布王国各地的卧底特工。",h="这座不起眼的石砌庄园位于旧城区的东角，是暴风城王国精英情报和间谍机构——军情七处（SI:7）的总部所在地。在那扇沉重的大门后，间谍大师马迪亚斯·肖尔和他的高级特工们静静地监视着威胁王国的敌人，协调着遍布王国各地的卧底特工...",kw={"军营","迪菲亚","间谍活动","马迪亚斯·肖尔","旧城区","潜行者","军情七处","si:7","间谍大师","暴风城"},ang={["class:Rogue"]="对于联盟的潜行者来说，SI:7建筑是一个至关重要的职业中心，提供高级职业训练、毒药补给以及直接来自间谍大师马迪亚斯·肖尔的秘密任务。",["faction:Alliance"]="作为暴风城防御体系中不可见的基石，SI:7的情报网络为联盟军队提供了应对王座威胁的关键侦察信息。"},sec={{t="王国间谍活动的核心",b="对于旧城区的普通路人来说，这座坚固的石砌建筑看起来与普通的庄园或军营没什么两样。但事实上，它是暴风城情报局第七处（SI:7）的指挥中枢。在马迪亚斯·肖尔大师的领导下，SI:7负责收集情报、进行监视并执行隐秘行动，以保护王国免受颠覆。当城市卫兵在鹅卵石街道上巡逻，皇家卫兵守卫着暴风要塞时，SI:7在暗处工作，训练联络员并派遣隐秘特工去应对外国敌人、破坏者以及国内的动荡。"},{t="阴影中的警惕之眼",b="随着国王瓦里安·乌瑞恩离奇失踪，迪菲亚潜行者在西部荒野和暮色森林制造混乱，总部内始终回荡着忙碌的秘密活动。来自人类领地深处的深潜侦察兵不断将情报汇入这座建筑。在底层的地窖和武器林立的训练室中，致命的技术被不断完善，任务被分配出去，在威胁到达小国王的王座厅之前就将其消灭。"}},faq={{q="什么是SI:7？",a="SI:7代表暴风城情报局第七处。它是为暴风城王权服务的一流秘密间谍、侦察和刺杀机构。",al={"什么是军情七处","谁是军情七处","军情七处含义"}},{q="谁在暴风城领导SI:7？",a="马迪亚斯·肖尔大师在建筑内领导着该组织。马迪亚斯·肖尔负责监督王权所有的外勤任务、情报网络和战略侦察。",al={"谁是军情七处的领导","军情七处首领","谁管理军情七处"}},{q="这座建筑位于城中的什么位置？",a="总部位于旧城区，坐落在该区的东南部边缘，靠近运河和训练场。",al={"军情七处在哪里","军情七处位置","如何前往军情七处"}},{q="为什么SI:7对西部荒野如此感兴趣？",a="SI:7负责追踪整个暴风城领土内的颠覆活动，而迪菲亚潜行者代表了王国境内最危险的暴动势力。",al={"迪菲亚潜行者与军情七处","为什么军情七处监视迪菲亚"}}},fx={["3c33de19"]={q="军情七处危险吗？",a="对于忠于暴风城的公民和盟友来说，军情七处并不构成威胁。在其内部，王国的秘密情报网络负责训练和协调特工。不过，若是与他们为敌或威胁王权，你就会发现，他们的大师级盗贼、斥候和刺客是东部王国最致命的对手之一。",al={"军情七处危险吗","军情七处的危险","军情七处安全吗"}}},fp="21,174,32.521.0,29.398.1,13.141.0,28.144.0,43.117.0,38.139.0"}
P.entries["subzone:silver-stream-mine"] = {n="银泉矿洞",s="银泉矿洞是一座位于洛克莫丹北部的废弃矮人矿洞，坐落在奥加兹岗哨和巨石水坝之间。这里曾经是铁炉堡王国的一处富饶银矿脉，在矿藏枯竭后，这片挖掘出的空洞被重新规划为矿工同盟的补给仓库，随后被害虫占领。如今，隧道鼠狗头人蹲守在矿道内，囤积着偷来的装备和稀有的矿物珍品。",h="银泉矿洞是一座位于洛克莫丹北部的废弃矮人矿洞，坐落在奥加兹岗哨和巨石水坝之间。这里曾经是铁炉堡王国的一处富饶银矿脉，在矿藏枯竭后，这片挖掘出的空洞被重新规划为矿工同盟的补给仓库，随后被害虫占领。如今，隧道鼠狗头人蹲守在矿...",kw={"充能裂隙宝石","狗头人","洛克莫丹","矿工同盟","银泉矿洞","隧道鼠"},ang={["class:Mage"]="法师学徒们深入危险的、狗头人出没的矿道，专门为了采集充能裂隙宝石，这是制作仪式服装不可或缺的原料。",["race:Dwarf"]="对于矮人来说，银泉矿洞是一项来之不易的基础设施的令人恼火的损失，笨拙的狗头人现在玷污了受人尊敬的铁炉堡矿工同盟仓库。"},sec={{t="从富矿脉到储藏仓库",b="银泉矿洞曾流淌着珍贵的矿石，为铁炉堡的白银储备做出了巨大贡献。久而久之，矮人的鹤嘴锄挖掘得足够深，耗尽了主要矿脉，将这片广阔的矿室变成了一座空荡荡的地下建筑群。矿工同盟没有放弃这些来之不易的工程，而是将矿井改造成了一个安全的储藏仓库，用于存放工具、采矿箱和区域性设备。这里也是目前已知的稀有充能裂隙宝石的唯一产地，吸引着那些寻找精致裁缝材料的好奇奥术师们。"},{t="狗头人的入侵",b="这个安静的仓库没能安全太久。好斗的隧道鼠狗头人被无人看管的工具、蜡烛油和被遗忘的地下缝隙的气味所吸引，成群结队地涌入了矿井。矿工同盟的管理员们很快就被赶到了洛克莫丹的寒风中。现在，狗头人们以近乎狂热的劲头守卫着偷来的矮人板条箱，而在后门外，破损的兽人投石车和马车被遗忘在那里，静静地诉说着往昔的边境冲突。"}},faq={{q="银泉矿洞最初的用途是什么？",a="它最初是由铁炉堡的矮人开采的一座高产银矿。在矿脉枯竭后，铁炉堡矿工同盟将这些空旷的地下大厅改造成了存放工具和挖掘物资的仓库。",al={"银泉矿洞是什么","银泉矿洞历史","银泉矿洞的建造原因"}},{q="谁目前占据着这座矿洞？",a="这座矿洞已经被隧道鼠狗头人彻底占领了。他们赶走了矮人管理员，现在守卫着矿道，囤积着同盟废弃的补给箱，并挖掘着残余的矿渣。",al={"谁住在银泉矿洞","银泉矿洞怪物","银泉矿洞里有什么"}},{q="为什么法师要前往银泉矿洞？",a="这座矿洞是目前已知的充能裂隙宝石的唯一产地。这种不稳定的、具有魔法反应的宝石受到联盟奥术师的追捧，用以编织强大的附魔长袍。",al={"银泉矿洞法师任务","充能裂隙宝石","银泉矿洞法师长袍"}},{q="矿洞后面的破损投石车是什么？",a="矿洞后面停放着损坏的兽人马车和破烂的投石车，这是早期战争冲突的风化残骸，那些冲突曾威胁到连接洛克莫丹和北部山口的通道。",al={"银泉矿洞后的兽人马车","洛克莫丹矿洞破损投石车","洛克莫丹的部落攻城武器"}}},fx={fbe48c53={q="银泉矿洞是什么地方？",a="银泉矿洞曾是矮人的采掘场，坐落在洛克莫丹北部的峭壁间，位于奥加兹岗哨以东、巨石水坝西南方。这里曾有丰富的银矿，由铁炉堡矮人开采，后来被矿工联盟改作补给仓库，最终落入敌手。",al={"银泉矿洞资料","银泉矿洞是什么","关于银泉矿洞"}},["6efdd539"]={q="银泉矿洞为什么被废弃了？",a="很久以前，矿洞中的银矿脉枯竭，采掘活动便逐渐停止。矿工联盟仍将这些隧道用作有守卫的仓库，但凶悍的坑道鼠狗头人成群涌入，抢占里面剩余的资源，将矮人工人全部赶了出去。",al={"银泉矿洞为什么被废弃","矮人为什么离开银泉矿洞"}},["339be7ce"]={q="银泉矿洞危险吗？",a="是的。矿洞已被敌对的坑道鼠狗头人彻底占据。这些地下害物领地意识极强，拼命囤积矿洞中的物资，任何胆敢接近洞口或深入矿洞的旅人和矿工都会遭到它们的攻击。",al={"银泉矿洞危险吗","银泉矿洞内的威胁","银泉矿洞的怪物"}}},fp="18,220,31.370.0,20.290.0,52.193.0,32.162.0,42.107.0,46.197.0"}
P.entries["subzone:silverwind-refuge"] = {n="银风避难所",s="银风避难所是坐落在灰谷中南部的一处宁静的暗夜精灵定居点，位于密斯特拉湖正北。在哨兵的保护下，这里为行走在林间小径上的旅人们提供了一处温馨的避风港。",h="银风避难所是坐落在灰谷中南部的一处宁静的暗夜精灵定居点，位于密斯特拉湖正北。在哨兵的保护下，这里为行走在林间小径上的旅人们提供了一处温馨的避风港。",kw={"灰谷","伊瑞斯湖","密斯特拉湖","暗夜精灵","哨兵","银风避难所"},ang={["faction:Alliance"]="对于穿行在灰谷的联盟旅者来说，银风避难所提供了一个可靠的营地，让他们可以休息、补充补给并精进荒野贸易技能，而不必大老远赶去阿斯特兰纳。",["profession:Herbalism"]="该避难所是灰谷采集者的一处重要停靠点，周围环绕着密斯特拉湖丰富的植被，并提供现场的草药学训练。"},sec={{t="林地圣所",b="银风避难所坐落在平静的密斯特拉湖与北面的伊瑞斯湖之间，与阿斯特兰纳一样，是灰谷中部主要的暗夜精灵中转站之一。这里有教授草药学、炼金术、剥皮和狩猎的工匠与荒野训练师。在坚定的哨兵守卫下，这处避难所成为了盟友们穿梭在阴郁古木林中时的安宁休憩点。"}},faq={{q="谁控制着银风避难所？",a="银风避难所是一个联盟定居点，由暗夜精灵建造并维护。这里由哨兵严密守卫，保护着这片宁静的土地。",al={"谁拥有银风避难所","银风避难所是联盟还是部落","谁住在银风避难所"}},{q="银风避难所位于何处？",a="它位于灰谷的中南部，位置在密斯特拉湖正北、伊瑞斯湖以南。",al={"银风避难所位置","银风避难所在哪","如何前往银风避难所"}},{q="避难所有什么服务？",a="旅人们可以在这里找到贸易供应商，以及提供草药学、炼金术、剥皮和猎人技能指导的专业训练师。",al={"银风避难所有什么","银风避难所训练师","银风避难所供应商"}}},fp="17,137,18.335.0,31.108.0,35.105.0,38.111.0"}
P.entries["subzone:silverwing-grove"] = {n="银翼树林",s="银翼树林坐落在灰谷中南部，靠近坠星湖，是银翼要塞的集结地。在这个堡垒般的林中空地，暗夜精灵战士召集联盟部队，以击退正在森林中大肆砍伐的战歌氏族伐木工。",h="银翼树林坐落在灰谷中南部，靠近坠星湖，是银翼要塞的集结地。在这个堡垒般的林中空地，暗夜精灵战士召集联盟部队，以击退正在森林中大肆砍伐的战歌氏族伐木工。",kw={"灰谷","坠星湖","哨兵艾蒂亚·轻歌","银翼树林","银翼要塞","战歌峡谷"},ang={["faction:Alliance"]="这座树林是联盟勇士召集并进入战歌峡谷惨烈战斗的主要集结地。",["race:NightElf"]="对于卡多雷来说，银翼树林代表了他们誓要阻止战歌氏族的战斧亵渎神圣树木的坚定决心。"},sec={{t="森林战争的前线",b="银翼树林隐藏在银翼哨站西南方向的翡翠树冠之下，是银翼要塞至关重要的军事集结哨所。它并非一处宁静的林地避风港，而是暗夜精灵在战歌峡谷抵御部落伐木行动的残酷领土争夺战中的作战核心。联盟的高级军官、补给品和侦察兵汇集于此，组织小规模冲突并召集勇士，保卫古老的灰谷免受兽人的扩张威胁。"}},faq={{q="银翼树林的作用是什么？",a="银翼树林是银翼要塞的集结基地。暗夜精灵军队和他们的联盟盟友在这里组织行动，以对抗战歌氏族的乱砍滥伐，并由此进入战歌峡谷参与持续不断的冲突。",al={"银翼树林为什么在这里","什么是银翼树林","银翼树林的作用"}},{q="银翼树林在哪里？",a="它位于灰谷中南部，坐落在银翼哨站西南方，紧邻坠星湖以西。",al={"银翼树林的位置","银翼树林在哪里","如何找到银翼树林"}},{q="谁在银翼树林中进行活动？",a="这座树林由银翼要塞负责驻守，同时还有联盟军事指挥官、联盟准将、后勤商人和诸如哨兵艾蒂亚·轻歌等协调对抗部落行动的军官。",al={"谁在银翼树林","银翼树林的角色","谁管理银翼树林"}},{q="部落玩家可以进入银翼树林吗？",a="不能。这座树林是一个活跃的军事哨所，驻扎着敌对的联盟哨兵和卫兵，他们会立即攻击任何入侵的部落成员。",al={"银翼树林是敌对的吗","部落可以去银翼树林吗","部落 银翼树林"}}},fp="16,228,28.327.0,40.160.0,34.115.0,37.212.0,41.89.0"}
P.entries["subzone:silverwing-outpost"] = {n="银翼哨站",s="银翼哨站是位于灰谷中南部，弗伦河以东的一座防御严密的暗夜精灵驻地。它由杜瑞尔·月火指挥，是联盟在这一争议林地中抵御部落的最东端堡垒。",h="银翼哨站是位于灰谷中南部，弗伦河以东的一座防御严密的暗夜精灵驻地。它由杜瑞尔·月火指挥，是联盟在这一争议林地中抵御部落的最东端堡垒。",kw={"灰谷","杜瑞尔·月火","弗伦河","银翼哨站","银翼要塞","碎木岗哨","托雷克"},ang={["faction:Alliance"]="银翼哨站作为你在河对岸的重要前哨据点，牵制着从碎木岗哨向外扩张的兽人势力。",["faction:Horde"]="对于部落来说，该哨站是碎木岗哨心腹之患，直接阻碍了你在灰谷南部的行动和补给线。"},sec={{t="弗伦河以东",b="银翼哨站位于碎木岗哨西南方，紧邻贫瘠之地边境线以北，其战略位置极其险要。由于地处弗伦河东岸——这一区域受到部落的激烈争夺与巡逻——该哨站成为了暗夜精灵在森林深处领地的直接屏障。杜瑞尔·月火和她的银翼要塞部队始终面临着附近兽人的持续围攻，这些兽人誓要将暗夜精灵势力从该地区彻底清除。"},{t="永恒的前线",b="围绕银翼哨站的冲突是灰谷中最激烈的。以碎木岗哨为基地的兽人战争小队（例如托雷克率领的劫掠者）不断对哨站的城墙发动突袭。对于部落而言，清除这个哨站是确保道路安全、在不受哨兵部队持续反击威胁的情况下扩展资源开采行动的关键。"}},faq={{q="银翼哨站位于何处？",a="它位于灰谷中南部，碎木岗哨西南方，贫瘠之地边境线以北，且处于弗伦河的东岸。",al={"银翼位置","银翼在哪里","银翼哨站地图"}},{q="谁在指挥银翼哨站？",a="该哨站由杜瑞尔·月火指挥，这是一名统领银翼要塞部队、负责保卫森林东部边陲的暗夜精灵军官。",al={"银翼指挥官","谁领导银翼哨站","杜瑞尔·月火"}},{q="为什么部落如此猛烈地攻击这个哨站？",a="银翼哨站直接坐落在弗伦河东岸，靠近碎木岗哨。它的存在使哨兵部队能够切断部落的补给线，并直接威胁兽人在灰谷的行动。",al={"为什么要攻击银翼","部落对银翼的兴趣","碎木岗哨与银翼的冲突"}},{q="什么是银翼要塞部队？",a="银翼要塞部队是一个由暗夜精灵战士和女猎手组成的军事组织，致力于保护灰谷免受侵犯，特别是对抗不断扩张的伐木场和部落的战争小队。",al={"什么是银翼部队","银翼要塞部队背景","银翼阵营"}}},fp="18,224,21.375.0,18.309.1,36.147.0,32.118.0,55.184.0,33.148.0"}
P.entries["subzone:sishir-canyon"] = {n="希塞尔山谷",s="希塞尔山谷是石爪山脉中一条崎岖的峡谷，向东穿过了嶙峋的山峰。这里不仅布满了可怕的深苔蜘蛛和厚重的蛛网，还是前往埃雷萨废墟的危险通道。踏入这片纠结深渊的旅者必须面对剧毒蜘蛛以及它们那正在孵卵的蛛后。",h="希塞尔山谷是石爪山脉中一条崎岖的峡谷，向东穿过了嶙峋的山峰。这里不仅布满了可怕的深苔蜘蛛和厚重的蛛网，还是前往埃雷萨废墟的危险通道。踏入这片纠结深渊的旅者必须面对剧毒蜘蛛以及它们那正在孵卵的蛛后。",kw={"贝瑟雷斯","深苔","埃雷萨","希塞尔山谷","蜘蛛","石爪","蛛网"},ang={["class:Hunter"]="危险的蛛网和剧毒的深苔蜘蛛使希塞尔山谷成为了猎人们的艰巨试炼场，让他们在此狭窄的峡谷环境中磨练追踪与捕捉野兽的技巧。",["race:NightElf"]="被占据的峡谷阻断了通往埃雷萨祖先遗迹的安全便捷通道，使得卡多雷哨兵和学者们必须穿过密集的蜘蛛巢穴，才能到达属于他们的文化遗产。"},sec={{t="蛛网通道",b="希塞尔山谷从石爪山脉的山路分支而出，是一条通往古老埃雷萨废墟的险恶天然走廊。这道峡谷并非平静的山间小径，而是早已被深苔蜘蛛彻底占领。黏稠的蛛丝和成堆的卵囊覆盖了石地与岩壁，将这道峡谷变成了一个活生生的巢穴。试图前往前方暗夜精灵遗迹的旅者和哨兵，必须杀出一条血路，穿过成群结队的攻击性织网蛛。"},{t="贝瑟雷斯的领地",b="潜伏在峡谷最深处的是深苔蛛群庞大而致命的族长——贝瑟雷斯。她的剧毒和巨大的体型，让任何试图通过此通道的人都感到恐惧。石爪山脉的当地势力对这座峡谷保持着警惕，警告冒险者们，进入那些布满蛛网的深处不仅意味着要面对零散的蜘蛛，还要面对守护蛛群的顶级掠食者。"}},faq={{q="什么是希塞尔山谷？",a="希塞尔山谷是位于石爪山脉中一处被蜘蛛占据的峡谷，它从主要山路蜿蜒延伸至古老的埃雷萨废墟。",al={"希塞尔山谷在哪里","希塞尔山谷位置"}},{q="峡谷里居住着什么生物？",a="这座峡谷被捕食性的深苔蜘蛛完全占据。这些蛛形生物在峡谷中覆盖了厚厚的蛛网和卵囊，捕食着任何进入它们领地的生物。",al={"希塞尔山谷中的怪物","石爪峡谷中的蜘蛛"}},{q="贝瑟雷斯是谁？",a="贝瑟雷斯是栖息在希塞尔山谷深处的强大蛛后。她统领着深苔蛛群，是该地区对过往旅者最大的威胁。",al={"贝瑟雷斯位置","希塞尔山谷巨型蜘蛛"}},{q="希塞尔山谷通往哪里？",a="沿着峡谷向东走，可以直接到达埃雷萨废墟，这是一个隐藏在高山之上的古老暗夜精灵遗迹。",al={"希塞尔山谷尽头有什么","穿过希塞尔山谷的路径"}}},fp="13,171,15.323.0,18.304.0,22.121.0,34.149.0,17.143.0,30.110.0"}
P.entries["subzone:skittering-dark"] = {n="粘丝洞",s="粘丝洞是一处位于银松森林西部的废弃矿井和阴暗林地洼地。由于受到具有攻击性的巨型蜘蛛的侵扰，这座洞穴及其周边树林布满了蛛网，对毫无防备的野兽和旅行者来说充满危险。",h="粘丝洞是一处位于银松森林西部的废弃矿井和阴暗林地洼地。由于受到具有攻击性的巨型蜘蛛的侵扰，这座洞穴及其周边树林布满了蛛网，对毫无防备的野兽和旅行者来说充满危险。",kw={"克雷希斯","矿井","北流海岸","银松森林","粘丝洞","蜘蛛"},ang={["faction:Horde"]="进入银松森林的部落旅行者们请注意：粘丝洞的蜘蛛会伏击那些从周边树林误入它们蛛网巢穴的毫无防备的猎物。"},sec={{t="蛛网密布的洼地",b="粘丝洞坐落在北流海岸西岸以东的山丘中，曾经是一座运作中的矿井。如今，矿井通道完全被蛛网堵塞，成为了巨型蜘蛛的庞大巢穴。阴影编织者Krethis出没在洞穴外部，这些蜘蛛会猎杀任何靠得太近的目标。"}},faq={{q="什么是粘丝洞？",a="这是位于银松森林西部的一处废弃矿井，已被巨型蜘蛛完全占领。洞穴网络和周边的树木上覆盖着厚厚的黏性蛛网，还有许多捕食性的蛛形纲生物。",al={"粘丝洞矿井","这是什么矿井","银松森林蜘蛛洞"}},{q="矿井里的蜘蛛由谁领导？",a="目前还没有已知的单一蜘蛛首领。其中最令人恐惧的是暗影织网者克雷希斯，这是一种稀有且危险的织网者，经常在矿井内外徘徊。",al={"蜘蛛首领","粘丝洞首领","蛛后"}},{q="粘丝洞在哪里？",a="它坐落在银松森林西部的群山之中，就在被称为北流海岸的岸线以东。",al={"粘丝洞位置","如何找到粘丝洞"}}},fp="15,173,15.277.0,28.167.0,34.151.0,37.99.0"}
P.entries["subzone:skull-rock"] = {n="骷髅石",s="骷髅石是位于杜隆塔尔东海岸悬崖中的一处洞穴，就在奥格瑞玛的东边。它充当了火刃氏族这一恶魔崇拜组织的堡垒，其位置就在奥格瑞玛的眼皮底下。",h="骷髅石是位于杜隆塔尔东海岸悬崖中的一处洞穴，就在奥格瑞玛的东边。它充当了火刃氏族这一恶魔崇拜组织的堡垒，其位置就在奥格瑞玛的眼皮底下。",kw={"火刃氏族","邪教徒","杜隆塔尔","加祖兹","奥格瑞玛","骷髅石"},ang={["class:Warlock"]="在骷髅石内练习的黑暗魔法展示了恶魔影响力的肆意蔓延，这是萨尔的部落竭力想要根除和控制的。",["faction:Horde"]="清除骷髅石内的邪教徒对于确保杜隆塔尔沿海通道的安全，以及保护奥格瑞玛免受内部颠覆至关重要。"},sec={{t="邪教徒的巢穴",b="骷髅石隐藏在杜隆塔尔东北部的岩礁之下，是该地区火刃氏族最危险的据点之一。黑暗的邪教徒、崇拜邪能的兽人和召唤师们聚集在蜿蜒的隧道深处，练习恶魔魔法，并密谋对抗新生的部落。该组织由危险的术士加祖兹领导，他的行动对附近的奥格瑞玛大门和往来东海岸的旅者构成了迫在眉睫的威胁。"}},faq={{q="什么是骷髅石？",a="骷髅石是一处位于杜隆塔尔东北部沿海的洞穴系统。这里被火刃氏族的邪教徒所占据，他们利用天然的掩体来策划对抗萨尔的部落。",al={"骷髅石洞穴","骷髅石在哪里","骷髅石里有什么"}},{q="谁控制着骷髅石？",a="洞穴被火刃氏族渗透，兽人术士加祖兹在洞穴的最深处指挥着一切。",al={"谁领导骷髅石","谁在运作骷髅石","骷髅石首领"}},{q="为什么部落关心这个洞穴？",a="它靠近奥格瑞玛，构成了严重的安全隐患。火刃氏族积极寻求破坏萨尔的新国度，并试图让兽人重新陷入恶魔的奴役之中。",al={"为什么要清理骷髅石","为什么骷髅石很危险"}}},fp="10,134,17.355.0,19.140.0,24.110.0,40.168.0"}
P.entries["subzone:slag-pit"] = {n="熔渣之池",s="熔渣之池是一处深埋于灼热峡谷大熔炉内部的巨大地下矿坑。在冷酷的黑铁矮人工头和奴隶贩子的监管下，这些充满烈焰的隧道在黑石山的阴影下依靠强制劳役维持运作。入侵者不仅要面对敌对的矮人监工，还要提防在底层游荡的贪婪燃火龙。",h="熔渣之池是一处深埋于灼热峡谷大熔炉内部的巨大地下矿坑。在冷酷的黑铁矮人工头和奴隶贩子的监管下，这些充满烈焰的隧道在黑石山的阴影下依靠强制劳役维持运作。入侵者不仅要面对敌对的矮人监工，还要提防在底层游荡的贪婪燃火龙。",kw={"大熔炉","黑铁矮人","燃火龙","灼热峡谷","熔渣之池","奴隶贩子","奴隶","工头"},ang={["profession:Mining"]="熔渣之池的深井直插灼热峡谷富含矿产的核心地带，使其成为一处利润丰厚——但也极其危险——的高品位矿石产地。",["race:Dwarf"]="对于铁炉堡的矮人来说，目睹熔渣之池中黑铁奴隶贩子的残暴行径，是对各矮人氏族之间深刻分歧的一次严酷提醒。"},sec={{t="地下苦役",b="熔渣之池开凿在大熔炉深处，是黑铁矮人在灼热峡谷残酷工业机器的缩影。日夜不停地，被奴役的劳工在残暴的监工和工头的鞭笞下，被迫挖掘丰富的矿石和矿物。这里的环境恶劣而令人窒息，充斥着灼热的温度、呛人的尘土和铁镐的撞击声。黑铁矮人对他们的矿坑实行残酷的纪律，并暴力击退任何干扰他们通往黑石深渊补给线的外部势力。"},{t="矿坑深处",b="除了奴隶贩子的残暴，这些隧道本身对工人和入侵者而言也是致命的威胁。在矿坑的底层，大地裂开，形成了一座座酷热的洞穴，栖息着燃火龙——这是一种原产于地下火海的凶猛爬行兽。尽管时刻面临着被这些地下掠食者吞噬的危险，黑铁矮人大师们依然驱使劳工深入岩石，对过程中丧生的生命毫不在意。"}},faq={{q="熔渣之池在哪里？",a="熔渣之池位于大熔炉的深处，那是一个占据了灼热峡谷中心位置的巨大挖掘坑。其隧道直接从地表的采矿作业区下方延伸开来。",al={"熔渣之池位置","熔渣之池在哪","如何前往熔渣之池"}},{q="谁控制着熔渣之池？",a="这座矿坑完全由黑铁氏族掌控。黑铁奴隶贩子和工头在矿井中巡逻，执行残酷的纪律，并驱使俘虏们全天候不停地挖掘。",al={"谁管理熔渣之池","熔渣之池所属势力","黑铁矮人熔渣之池"}},{q="为什么奴隶工会攻击入侵者？",a="虽然被奴役的劳工对外界并不具有天生的攻击性，但他们对黑铁大师的恐惧根深蒂固。如果有奴隶贩子或工头在附近遇袭，惊慌失措的劳工为了避免严厉的惩罚，会冲上去保护他们的监工。",al={"为什么奴隶会攻击","敌对的奴隶","奴隶劳工仇恨"}},{q="熔渣之池里住着什么生物？",a="除了黑铁矮人和他们的奴隶之外，矿坑的最深处还滋生着燃火龙——一种具有攻击性、覆盖着火焰鳞片的爬行掠食者，潜伏在地下隧道中。",al={"熔渣之池怪物","燃火龙","熔渣之池野兽"}}},fp="8,143,17.311.0,17.231.0,30.153.0,26.128.0,42.203.0,36.119.0"}
P.entries["subzone:slaughter-hollow"] = {n="屠杀谷",s="屠杀谷是一处与世隔绝的食人魔土丘，隐匿在奥特兰克山脉白雪皑皑的高处。这里被野蛮的碎颅氏族所控制，更像是一个粗陋的营地，而非熙熙攘攘的定居点。除非是去猎杀食人魔或探索冰封的山隘，否则旅行者很少有理由踏足此地。",h="屠杀谷是一处与世隔绝的食人魔土丘，隐匿在奥特兰克山脉白雪皑皑的高处。这里被野蛮的碎颅氏族所控制，更像是一个粗陋的营地，而非熙熙攘攘的定居点。除非是去猎杀食人魔或探索冰封的山隘，否则旅行者很少有理由踏足此地。",kw={"奥特兰克","碎颅氏族","希尔斯布莱德","食人魔土丘","里兹·螺栓","屠杀谷"},ang={["race:Gnome"]="里兹·螺栓被碎颅氏族不幸俘获，给那些毫无准备就在奥特兰克山隘徘徊的技工和斥候敲响了警钟。"},sec={{t="食人魔巢穴",b="屠杀谷隐藏在希尔斯布莱德与奥特兰克交界的崇山峻岭之中，是当地碎颅氏族食人魔的营地。正如散布在高地上的许多食人魔土丘一样，这里到处都是临时搭建的篝火、丢弃的尸骨和简陋的住所。虽然山中的其他食人魔巢穴经常因领土争端或被盗的补给品而爆发冲突，但屠杀谷大体上还算安静，并未卷入主要的军事行动之中。"},{t="俘虏与旅行者",b="由于其位置偏僻，该土丘偶尔会被当作关押沿山路被俘的不幸之人的地方。旅行者中流传着一个关于名为里兹·螺栓的不幸侏儒的消息，他发现自己被关在这里一个简陋的笼子里，试图与任何经过的人进行交易。这些不幸的俘虏在面对碎颅氏族那贪婪的胃口时，往往结局凄惨。"}},faq={{q="什么是屠杀谷？",a="屠杀谷是奥特兰克山脉中一个由碎颅氏族居住的食人魔营地。这里有高地食人魔定居点典型的原始土丘住宅和篝火。",al={"屠杀谷背景故事","这里是什么地方","希尔斯布莱德的屠杀谷"}},{q="谁住在屠杀谷？",a="屠杀谷完全由碎颅氏族食人魔居住，该氏族同样占据着附近的奥特兰克废墟以及周围的各个哨所。",al={"谁在这里","屠杀谷怪物","谁控制了屠杀谷"}},{q="这里有任务吗？",a="没有直接将冒险者引向屠杀谷的正式任务。它大体上是一个在探索山区地形时偶然发现的偏远巢穴。",al={"屠杀谷任务","屠杀谷有任务吗","为什么要来这里"}},{q="被关在这里的侏儒是谁？",a="一个名叫里兹·螺栓的侏儒被囚禁在谷内的一个笼子里，向任何发现他的人兜售商品。",al={"里兹·螺栓","笼子里的侏儒","屠杀谷商人"}}},fp="16,161,14.328.0,22.273.0,25.129.0,30.134.0,26.120.0,29.106.0"}
P.entries["subzone:slaughtered-lamb"] = {n="Slaughtered Lamb",s="已宰的羔羊藏在暴风城的法师区里，表面上不过是一间安静又破旧的酒馆。然而，在它的地板之下，错综复杂的地下墓穴隐藏着联盟非法术士的密室和训练场。",h="已宰的羔羊藏在暴风城的法师区里，表面上不过是一间安静又破旧的酒馆。然而，在它的地板之下，错综复杂的地下墓穴隐藏着联盟非法术士的密室和训练场。",kw={"地下墓穴","扎雷·穆尔","法师区","已宰的羔羊","暴风城","术士","维沙克","加尔德斯"},ang={["class:Warlock"]="下方的地下墓穴是你身处暴风城时的主要避难所，这里提供职业训练师、恶魔奴役仪式，以及掌握黑暗技艺所必需的任务。",["faction:Alliance"]="虽然联盟崇尚圣光与秩序，但已宰的羔羊揭示了这个王国在阴影中容忍黑暗魔法的默许态度。"},sec={{t="拙劣的伪装",b="表面上，已宰的羔羊只有阴暗的角落和稀少的顾客，由酒保扎雷·穆尔照看。他会告诫随意的访客远离阴影，这句警告并非虚言。穿过后方的通道向下走，会发现一个由地下墓穴和召唤法阵组成的地下建筑群。在这里，人类术士和来自卡兹莫丹的施法者们公开研究着邪能奥术，免受圣光教会和肯瑞托那充满非议的目光的注视。"},{t="贵族的酒账",b="在王都中心经营一个邪能集会点总是伴随着持续的危险。当鲍雷斯·维沙克公爵发现潜伏在地窖里的术士时，他威胁要召集贵族议会并请求王座进行全面调查。实际上，这位贵族只是想赖掉一笔巨额酒账。在这一骚动引发真正的审查之前，黑爪加尔德斯安排维沙克喝下了一杯致命的混合物，永远地让这个多管闲事的人闭了嘴，守护住了这里的秘密。"}},faq={{q="已宰的羔羊下面究竟在进行什么活动？",a="酒馆下方的地下墓穴是暴风城术士的秘密密室。恶魔学识和暗影魔法的修行者们聚集在那里教导学徒、进行召唤仪式，并练习在上方街道中被禁止的邪能技艺。",al={"已宰的羔羊下面有什么","已宰的羔羊地下室","已宰的羔羊里有什么人"}},{q="暴风城守卫知道术士的存在吗？",a="这间酒馆在摇摇欲坠的“合理推诿”掩盖下运作。圣光教会和法师学院对邪能魔法抱有深深的不信任，迫使这个集会组织必须秘密运作，并积极地让任何威胁要向王室当局告发他们的人永远闭嘴。",al={"守卫知道术士吗","为什么术士没有被捕","已宰的羔羊是非法的吗"}},{q="维沙克公爵是谁，他发生了什么事？",a="鲍雷斯·维沙克公爵是一位贵族，也是酒馆的常客，他发现了躲在下面的术士。他在贵族议会中引起了骚动，并游说进行全面调查，希望请求国王关闭这家店。",al={"鲍雷斯·维沙克","维沙克公爵的下场","维沙克是谁"}},{q="侏儒术士为什么来这里？",a="在诺莫瑞根沦陷后，其术士大师拉戈·黑钳将新手送到已宰的羔羊的黑暗缚灵者加科因那里接受训练。",al={"暴风城的侏儒术士","卡兹莫丹术士"}}},fx={["28eb4e6b"]={q="什么是已宰的羔羊？",a="表面上看，已宰的羔羊是一家安静而阴暗的酒馆，藏在暴风城的法师区。地面上的酒馆看起来几乎无人打理，空荡荡的酒吧间只有酒保扎雷·穆尔在照看。然而，地板之下却延伸着庞大的地下墓穴和陵寝网络。这些幽暗深处是暴风城术士的秘密圣所，为他们遮掩禁忌的邪能仪式和召唤，不让城卫队和贵族议会那不赞同的目光窥见。",al={"已宰的羔羊 是什么","已宰的羔羊 酒馆","已宰的羔羊"}},f1944543={q="已宰的羔羊发生过什么事？",a="当鲍雷斯·维沙克公爵发现术士藏身于酒馆地下室时，这里的秘密差点暴露。他在贵族议会掀起风波，并游说展开全面调查，希望请求国王下令关闭这家店。",al={"已宰的羔羊 的历史","已宰的羔羊 发生过什么事","已宰的羔羊 背景"}},["531ea530"]={q="谁在经营已宰的羔羊？",a="楼上的酒吧间由酒保扎雷·穆尔看管，他会悄悄提醒好奇的顾客远离那些阴暗角落。地下的隐秘据点里住着神秘的术士导师和召唤师，其中包括黑爪加尔德斯。他们教导人类学徒以及从侏儒处转来的学徒，行事低调，好让生意和黑暗魔法不受打扰地进行。",al={"谁在经营 已宰的羔羊","已宰的羔羊 的酒保","已宰的羔羊 里有哪些人"}},ecc63b24={q="已宰的羔羊危险吗？",a="藏身于此的术士会严密守护他们的秘密，绝不容许任何人揭露他们的地下集会。",al={"已宰的羔羊 危险吗","已宰的羔羊 的危险","已宰的羔羊 里安全吗"}}},fp="16,111,15.373.0,15.399.1,49.203.0,54.188.0,47.212.1,32.189.0"}
P.entries["subzone:slither-rock"] = {n="滑石",s="滑石是一个隐蔽的洞穴，位于燃烧平原遥远的东北部悬崖中，穿过危险的龙翼小径即可到达。它是塞勒斯·萨雷芬图斯唯一的避难所，这只口舌尖酸的黑龙人怀揣着自己不可告人的目的。",h="滑石是一个隐蔽的洞穴，位于燃烧平原遥远的东北部悬崖中，穿过危险的龙翼小径即可到达。它是塞勒斯·萨雷芬图斯唯一的避难所，这只口舌尖酸的黑龙人怀揣着自己不可告人的目的。",kw={"黑龙人","燃烧平原","塞勒斯·萨雷芬图斯","滑石","龙翼小径"},sec={{t="一处隐蔽的洞穴",b="滑石隐藏在龙翼小径尽头的焦黑岩壁之中，在燃烧平原那火热的荒野里很容易被忽略。这个偏远的洞穴远离黑石塔那轰鸣的熔炉和行军的兽人战团，它是孤独的黑龙人塞勒斯·萨雷芬图斯的居所。尽管龙人通常是黑龙军团中极其忠诚的士兵，但塞勒斯却在此保持着一种古怪而暴躁的独立性。比起见面就大开杀戒，他更愿意与凡人旅者交谈——尽管交谈时总少不了一连串的谩骂。"}},faq={{q="滑石位于哪里？",a="滑石位于燃烧平原遥远的东北角。旅行者必须穿过巡逻在龙翼小径上的黑龙人，才能到达那里。",al={"滑石位置","滑石在哪里","找到滑石"}},{q="谁住在滑石里？",a="这个洞穴住着塞勒斯·萨雷芬图斯，一只孤独的黑龙人。与他那些一见到凡人就发动攻击的同类不同，塞勒斯愿意与外人交谈，尽管他依然脾气暴躁且出言不逊。",al={"滑石里的人","滑石怪物","滑石角色"}},{q="冒险者为什么要寻找这个洞穴？",a="冒险者们冒着危险穿过龙翼小径，去寻求塞勒斯·萨雷芬图斯的建议和帮助。尽管态度恶劣，但这只龙人还是会帮助他们战胜共同的敌人，不过他一定会伴随着大量的粗鲁和嘲讽言论。",al={"为什么要去滑石","滑石任务","塞勒斯的目的"}}},fp="12,215,17.452.0,30.158.0,26.197.0,43.206.0"}
P.entries["subzone:slithering-scar"] = {n="巨痕谷",s="巨痕谷是一座庞大的其拉虫巢，坐落在安戈洛环形山的南侧悬崖上。这里是极具侵略性的戈里希虫群的家园，它们挖掘的隧道和有机尖塔代表了一种危险的昆虫入侵，正在蚕食这片原始盆地。",h="巨痕谷是一座庞大的其拉虫巢，坐落在安戈洛环形山的南侧悬崖上。这里是极具侵略性的戈里希虫群的家园，它们挖掘的隧道和有机尖塔代表了一种危险的昆虫入侵，正在蚕食这片原始盆地。",kw={"扎瓦斯主母","巨像","戈里希","虫巢","其拉虫","巨痕谷","安戈洛"},ang={["class:Druid"]="戈里希虫巢的侵略性扩张威胁着环形山脆弱而原始的活力，需要人们时刻警惕这种不自然的虫群滋生。"},sec={{t="戈里希虫巢",b="巨痕谷深陷在安戈洛南部的红土和岩石之中，如同在繁茂的史前景观中植入的外来异物。这座虫巢由戈里希其拉虫控制，这是一个组织严密的昆虫种群，它们在悬崖中开凿了无数潮湿的洞穴和孵化室。在这些地下巢穴中，工虫和钻地虫在照料着大量的虫卵、幼虫以及高耸的黄蜂巢穴。更令人担忧的是，虫群还在培育初生的其拉巨像，这些庞然大物旨在为它们在环形山的生态系统中开辟一条畅通无阻的道路。虫巢内镶嵌的奇异水晶结构散发着不自然的共鸣，成为了虫群阴暗且协调一致的意志焦点。"},{t="缺失的守卫",b="经常穿行在安戈洛边缘的学者和探险家们，注意到了这个虫巢位置的一个令人不安的异常之处。虽然古老的水晶塔矗立在盆地的北部、东部和西部边缘作为守护，但南部区域却没有这样的柱子。正是在这个毫无保护的缺口处，戈里希其拉虫从邻近的沙漠中向内掘进。究竟是其拉虫有意破坏了一处被遗忘的南部守卫，还是它们仅仅入侵了环形山原始防护最为薄弱的地方，这对那些关注它们迅速扩张的人来说，仍然是一个令人不安的谜团。"}},faq={{q="什么是巨痕谷？",a="它是一座开凿在安戈洛环形山南侧悬崖上的其拉虫巢建筑群，戈里希虫群栖息于此。",al={"这是什么地方","巨痕谷概览","安戈洛虫巢"}},{q="其拉虫在这里做什么？",a="戈里希虫群正在挖掘庞大的地下隧道，照料装满幼虫和虫卵的育婴室，并培育巨大的其拉巨像，以建立对环形山的统治。",al={"为什么虫子在这里","其拉虫在安戈洛的目的","戈里希目标"}},{q="为什么南部没有像其他地区那样的水晶塔？",a="虽然安戈洛的北部、东部和西部边缘都有古老的水晶塔作为标记，但南部的悬崖却没有。巨痕谷正是出现在这个防御边界缺失的地方。",al={"缺失的南部水晶塔","为什么没有南部的塔","南部的水晶塔在哪里"}},{q="有哪些危险的生物栖息在虫巢中？",a="除了成群的工虫、掠夺者和刺虫外，虫巢中还有正在发育的巨像，以及像扎瓦斯主母这样声名狼藉、凶猛异常的巢穴首领。",al={"虫巢首领","著名的虫子","扎瓦斯主母"}}},fp="15,134,16.475.0,14.455.0,28.92.0,33.166.0,58.186.0,42.133.0"}
P.entries["subzone:sludge-fen"] = {n="淤泥沼泽",s="淤泥沼泽是荆棘谷地精在贫瘠之地东北部运营的一处有毒工业油田。这片湿地曾经是一汪纯净清澈的碧蓝水潭，但在地精竖起钻井平台和机械装置后，便沦为了一片油污泥潭。该行动由卢格维兹主管监督，并持续引来棘齿城竞争对手的工业间谍破坏活动。",h="淤泥沼泽是荆棘谷地精在贫瘠之地东北部运营的一处有毒工业油田。这片湿地曾经是一汪纯净清澈的碧蓝水潭，但在地精竖起钻井平台和机械装置后，便沦为了一片油污泥潭。该行动由卢格维兹主管监督，并持续引来棘齿城竞争对手的工业间谍破坏活...",kw={"石油钻井","伐木机","淤泥沼泽","斯布特瓦夫","卢格维兹主管","贫瘠之地","荆棘谷地精","维兹尔克兰"},ang={["class:Druid"]="淤泥沼泽是反自然剥削的罪恶见证。部落德鲁伊在进行海狮试炼时，会潜入这片油腻的深渊取回水兽敏捷坠饰。",["profession:Engineering"]="荆棘谷地精在此处运作着尖端的伐木机和机械装置，这使得该地点成为了蓝图、特殊零件以及棘齿城精心策划的商业盗窃行动的诱人目标。"},sec={{t="工业破坏",b="在荆棘谷地精到来之前，淤泥沼泽原本是由贫瘠之地的天然泉水补给的纯净清澈的水潭。出于对利润的无止境追求，荆棘谷地精在盆地上兴建了大规模的石油钻探工程，将这片湿地糟蹋成了一个覆盖着厚重工业废料的污泥水库。在卢格维兹主管的监管下，地精钻探工、工程师和监工昼夜不停地抽取原油，对环境的破坏置若罔闻。如今水域中充斥着径流和有毒副产品，本地的水生生物都在油垢的重压下窒息而亡。"},{t="企业竞争与间谍活动",b="沼泽里的机械装置和伐木机创新技术使其成为了工业窃取的首要目标。在附近的棘齿城，工匠联合会的工程师斯布特瓦夫面临着巨大的压力，急需匹配荆棘谷地精尖端的伐木和挖掘技术。斯布特瓦夫并没有研发自己的设计，而是派出了一个名叫维兹尔克兰的特工，打算直接从淤泥沼泽抢走一台荆棘谷地精的伐木机。由于维兹尔克兰愚蠢地在没有拿到打火钥匙的情况下就劫持了机器，雇佣兵们经常被卷入泥潭，设法从卢格维兹手中夺取钥匙，并护送这台被窃的战争机器穿过愤怒的荆棘谷地精员工的重重包围。"}},faq={{q="荆棘谷地精到来之前的淤泥沼泽是什么样的？",a="淤泥沼泽原本是一汪纯净的碧蓝色水潭。荆棘谷地精在上面直接建造了钻井和炼油设施，毁掉了这片天然绿洲，将周围的湿地淹没在原油和化学废料之中。",al={"淤泥沼泽的过去","淤泥沼泽一直是被污染的吗","淤泥沼泽历史"}},{q="谁在负责淤泥沼泽的运营？",a="这片油田由卢格维兹主管代表荆棘谷地精进行管理。他监管着一支由监工、钻探工和工程师组成的劳动力队伍，手下还有像格利比监工和格里尔斯工头这样的副手。",al={"淤泥沼泽首领","谁领导淤泥沼泽","卢格维兹主管"}},{q="为什么沼泽中间停着一台被劫持的伐木机？",a="地精维兹尔克兰受棘齿城的斯布特瓦夫派遣，前来窃取荆棘谷地精的高级伐木机设计。然而，他跳进驾驶舱时却忘了先拿到打火钥匙，结果被困在原地，被敌对的荆棘谷地精员工团团包围。",al={"维兹尔克兰的伐木机","淤泥沼泽伐木机里的地精","为什么伐木机动不了"}},{q="德鲁伊为什么要潜入这些被污染的水域？",a="进行海狮试炼的部落德鲁伊会被指引前往受污染水潭的底部，从一个淹没在水下的锁盒中取回水兽敏捷坠饰，以此在恶劣的环境中考验他们的耐力。",al={"淤泥沼泽德鲁伊任务","水兽敏捷坠饰","水栖形态试炼"}}},fp="10,203,22.418.0,31.538.1,60.192.0,37.171.0,65.202.0,46.197.0"}
P.entries["subzone:solliden-farmstead"] = {n="索利丹农场",s="索利丹农场是位于提瑞斯法林地西部的一座仍在耕作的人类南瓜农场，就在丧钟镇的北面。它是洛丹伦北部罕见的异常存在：这些幸存下来的本土农夫在亡灵瘟疫中存活了下来，并在血色十字军的庇护下坚守着他们的土地。",h="索利丹农场是位于提瑞斯法林地西部的一座仍在耕作的人类南瓜农场，就在丧钟镇的北面。它是洛丹伦北部罕见的异常存在：这些幸存下来的本土农夫在亡灵瘟疫中存活了下来，并在血色十字军的庇护下坚守着他们的土地。",kw={"亡灵卫兵希米尔","丧钟镇","悲伤之田","南瓜","索利丹","索利丹农场","提瑞斯法林地"},ang={["faction:Alliance"]="看到活人耕种洛丹伦的土地带来了一丝希望，但残酷的现实是，这些孤立的幸存者对暴风城的公民抱有同样的排外仇恨，就像他们仇视亡灵一样。",["race:Undead"]="对于新崛起的被遗忘者来说，索利丹农场是现实政治的第一课：这些洛丹伦活人蔑视你们所变成的样子，既是药剂师毒素的原材料，也是一个潜在的南部桥头堡。"},sec={{t="反抗的遗民",b="尽管洛丹伦的大部分地区已沦为废墟和腐烂之地，索利丹农场的田地里依然出产着健康的作物。如今，这些幸存的人类农夫生活在附近一座塔楼中巡逻的血色十字军的庇护之下。他们饱受创伤且封闭排外，以毫不妥协的敌意保卫着他们的家园，攻击任何靠近的陌生人——无论是部落还是联盟。"},{t="幽暗城的注视",b="对于刚从丧钟镇走出来的被遗忘者来说，索利丹既是一种威胁，也是一种资源。皇家药剂师学会看中了农场里那些完好的南瓜，将其视为酿造新瘟疫的绝佳有机实验材料。与此同时，像亡灵卫兵希米尔这样的被遗忘者军官会派遣新兵突袭田地，为布瑞尔的药剂师乔汉偷走那些南瓜，并给这些活人一点教训。"}},faq={{q="为什么提瑞斯法林地会有活人农夫？",a="索利丹的农夫是洛丹伦的本土人类，他们在第三次战争中奇迹般地躲过了感染。在附近塔楼中巡逻的血色十字军的保护下，他们固执地继续耕种土地，而不是逃离他们的祖居之地。",al={"为什么他们还活着","这些农夫是谁","提瑞斯法的活人"}},{q="为什么索利丹的农夫会对联盟玩家保持敌意？",a="经历了洛丹伦的沦陷后，这些农夫变得多疑、痛苦，并且完全不信任圈子以外的任何人。在狂热的血色十字军的保护下，他们将所有闯入者视为潜在的威胁或受感染的拾荒者，无差别地攻击联盟和部落的旅行者。",al={"为什么农夫攻击联盟","他们是联盟吗","为什么对联盟是红色敌对"}},{q="为什么被遗忘者想要索利丹农场的南瓜？",a="服务于皇家药剂师学会的药剂师需要新鲜、未受污染的有机物质来测试和提炼他们的新瘟疫。索利丹土壤中生长的饱满、未受污染的南瓜，是开发毒素菌株的理想活体宿主。",al={"为什么要偷南瓜","悲伤之田南瓜任务","皇家药剂师学会南瓜"}},{q="亡灵卫兵希米尔是谁，为什么他要针对这个农场？",a="亡灵卫兵希米尔是一名驻扎在丧钟镇附近的被遗忘者军官。他派遣被遗忘者新兵去突袭农场，为布瑞尔的药剂师乔汉偷走十个南瓜，并给这些人类和保护他们血色十字军一点教训。",al={"为什么要杀死农夫","亡灵卫兵希米尔任务","收割收割者"}}},fp="18,271,17.322.0,21.370.0,55.228.0,57.250.0,58.197.0,58.252.0"}
P.entries["subzone:sorrow-hill"] = {n="悔恨岭",s="悔恨岭是西瘟疫之地安多哈尔以南的一片广阔墓地。它曾是平民、士兵和贵族的安息之所，但受到附近瘟疫锅的腐蚀，如今已变成亡灵四处游荡的恐怖之地。",h="悔恨岭是西瘟疫之地安多哈尔以南的一片广阔墓地。它曾是平民、士兵和贵族的安息之所，但受到附近瘟疫锅的腐蚀，如今已变成亡灵四处游荡的恐怖之地。",kw={"安多哈尔墓地","达尔加","约瑟夫·雷德帕斯","骷髅剥皮者","悔恨岭","乌瑟尔之墓","西瘟疫之地"},ang={["class:Paladin"]="对于圣骑士来说，悔恨岭是一个充满哀思与敬畏之地，他们前来乌瑟尔之墓瞻仰，同时还要击退那些亵渎导师安息之地的亡灵。",["faction:Alliance"]="这片墓地紧邻寒风营地，既是通往安多哈尔的战略要塞，也是洛丹伦阵亡捍卫者们神圣的安息之地。"},sec={{t="坟冢的重担",b="在第三次战争之前，悔恨岭是安多哈尔及其周边城镇的主要埋葬地。当天灾军团散布亡灵瘟疫时，掘墓人根本无法处理堆积如山的尸体。整齐的墓穴很快被浅浅的、标记简陋的土坑所包围。最终，惊恐的幸存者完全停止了传统的安葬方式，为了防止尸体复活，他们不得不将亲人的遗体运往南边的集体火堆烧毁。在城镇彻底沦陷前，幸存的居民将光明使者乌瑟尔安葬在墓地的高地上，从此赋予了这座山丘这个悲剧性的名字。"},{t="复活的死者",b="天灾军团在该地区散布的邪恶瘟疫锅早已腐蚀了悔恨岭。原本埋葬于此的士兵和市民如今已变成骷髅剥皮者和贪婪的食尸鬼，在迷雾缭绕的墓碑间游荡，而骷髅法师和一名当地的天灾指挥官则盘踞在东南部的墓穴中。由于这片墓地正位于寒风营地和安多哈尔之间的道路上，联盟和银色黎明经常派遣巡逻队清理此地的亡灵，以维持在该地区的重要立足点。"}},faq={{q="为什么这片墓地被称为悔恨岭？",a="这个名字源于洛丹伦沦陷期间，当时安多哈尔的幸存者在天灾军团的攻击下遭受了毁灭性的损失。他们在逃离前的最后一次集体行动，就是将他们倒下的领袖——光明使者乌瑟尔安葬在山顶的一座宏伟陵墓中。",al={"悔恨岭名字含义","为什么叫悔恨岭"}},{q="这里为什么有这么多浅坟？",a="当亡灵瘟疫袭击安多哈尔时，死亡人数激增，市民们根本来不及建造像样的陵墓。他们仓促地挖掘了一些标记简陋的土坑，直到瘟疫的攻势变得无法抵挡，他们便放弃了安葬，转而选择集体火葬。",al={"悔恨岭的浅坟","为什么墓碑标记简陋"}},{q="谁被埋葬在悔恨岭？",a="除了成千上万阵亡的士兵和安多哈尔市民外，这片墓地还安置着光明使者乌瑟尔的宏伟陵墓。这里还安息着炮手达尔加，并立有一座纪念约瑟夫·雷德帕斯的纪念碑，但他本人的遗体已被摧毁。",al={"悔恨岭的著名墓葬","这里埋葬的名人"}},{q="如今悔恨岭构成了什么样的威胁？",a="在巫妖王的瘟疫锅腐蚀下，墓地里的死者已经复活，化身为骷髅剥皮者、流着口水的食尸鬼和骷髅法师。在盘踞于东南部墓穴的天灾指挥官带领下，这些亡灵威胁着通往安多哈尔的南向道路。",al={"悔恨岭的天灾军团","谁控制着悔恨岭"}}},fp="11,147,18.546.0,20.416.0,41.221.0,42.197.0,29.250.0,40.240.0"}
P.entries["subzone:sorrowmurk"] = {n="忧伤湿地",s="忧伤湿地是悲伤沼泽中，位于泪水之池正东方的一片险恶湿地区域。长期以来，这里一直被负责守卫沉没的神庙入口的绿龙族巡逻队所占据，它是东部沼泽中最危险的地区之一。",h="忧伤湿地是悲伤沼泽中，位于泪水之池正东方的一片险恶湿地区域。长期以来，这里一直被负责守卫沉没的神庙入口的绿龙族巡逻队所占据，它是东部沼泽中最危险的地区之一。",kw={"阿塔哈卡","龙人","绿龙军团","绿幼龙","泪水之池","忧伤湿地","悲伤沼泽"},ang={["class:Druid"]="这些湿地中沾染了悲伤腐化的翡翠梦境守护者，对于任何自然仆从来说，这里的绿龙族都是令人悲痛的景象。"},sec={{t="危险的边界",b="忧伤湿地沿泪水之池的东侧延伸，是一片与禁忌之海接壤的茂密而阴暗的泥沼。多年来，这里的沼泽和纠结的枝桠间一直爬满了凶猛的绿龙人与高大的幼龙，它们是负责看守阿塔哈卡神庙遗迹的龙群遗部。它们的存在使得只有经验丰富的旅行者才敢涉足这片潮湿的土地。"}},faq={{q="忧伤湿地在哪里？",a="忧伤湿地位于悲伤沼泽的最东端，就在泪水之池和阿塔哈卡神庙的沉没遗迹之外，紧邻海岸。",al={"忧伤湿地位置","忧伤湿地在哪里","忧伤湿地地图"}},{q="忧伤湿地里有什么生物？",a="该地区以绿龙族而闻名，包括好斗的龙人以及在该神庙水域周围严密巡逻的大型幼龙。",al={"忧伤湿地怪物","忧伤湿地里有什么","忧伤湿地敌人"}},{q="为什么忧伤湿地里会有绿龙？",a="绿龙军团受伊瑟拉之托，负责监视泪水之池，并确保阿塔哈卡神庙中沉没的邪恶被封印。",al={"为什么这里有龙","悲伤沼泽绿龙军团","神庙巨龙"}}},fp="10,170,17.338.0,32.144.0,38.118.0,46.144.0"}
P.entries["subzone:south-gate-outpost"] = {n="南门哨岗",s="南门哨岗是一座坚固的矮人山地哨所，位于丹莫罗与洛克莫丹之间的南门小径沿途。这里的守山人驻守着这条积雪的南方道路，守护着在铁炉堡的寒冷高地与洛克湖温带山谷之间往来的旅客，保障交通顺畅。",h="南门哨岗是一座坚固的矮人山地哨所，位于丹莫罗与洛克莫丹之间的南门小径沿途。这里的守山人驻守着这条积雪的南方道路，守护着在铁炉堡的寒冷高地与洛克湖温带山谷之间往来的旅客，保障交通顺畅。",kw={"丹莫罗","矮人","铁炉堡之路","洛克莫丹","守山人","南门哨岗","南门小径","塞尔萨玛"},ang={["faction:Alliance"]="这座哨所是卡兹莫丹主要国内补给线上一处可靠的军事庇护所，确保了首都与东部定居点之间的通道畅通。",["race:Dwarf"]="对于第一次离开寒脊山谷和丹莫罗的矮人来说，南门哨岗是进入洛克莫丹那充满活力、阳光明媚的土地之前，最后的一处寒冷地标。"},sec={{t="南方道路的守望者",b="南门哨岗坐落于南门小径高山峡谷的中途，标志着丹莫罗积雪山坡与洛克莫丹葱郁盆地之间的边界。驻扎在这里的铁炉堡守山人负责巡逻崎岖的之字形山路，并将危险的野生生物挡在主干道外。与北门哨岗处境艰难的同僚相比，这里的守军在很大程度上已经肃清了他们负责的路段，使得前往塞尔萨玛的旅客、朝圣者和商队能够相对安全地通行。"}},faq={{q="南门哨岗的作用是什么？",a="它作为南门小径上的坚固边境检查站和驻军点发挥作用。驻扎于此的守山人负责清理积雪覆盖的交通要道，防止山中野兽和敌对入侵者在丹莫罗与洛克莫丹之间往来。",al={"为什么这里有南门哨岗","南门哨岗的用途","南门哨岗是什么"}},{q="为什么这里比北门哨岗平静得多？",a="南门哨岗的驻军成功清理了道路周边极具侵略性的野生生物。相比之下，北门哨岗面临着更严重的入侵和更狂野的山地地形，这使得南面的小径相对平静。",al={"北门与南门有何区别","南门安全吗","南门与北门对比"}},{q="通过南门哨岗的路通往哪里？",a="向西沿小径上行可进入丹莫罗的积雪高地，前往铁炉堡。向东下行则直接通往洛克莫丹的温带山谷，道路蜿蜒直达塞尔萨玛定居点。",al={"这条路通向哪里","南门道路目的地","南门小径路线"}}},fx={["3c6e6693"]={q="南门哨岗是什么地方？",a="南门哨岗是丹莫罗东部沿南门小径修建的一座设有防御工事的矮人山间驿站。它就坐落在连接丹莫罗与外侧广阔山谷的积雪高山通道上，迎接向东前往塞尔萨玛的旅人与信使。",al={"南门哨岗是什么","南门哨岗资料","南门小径哨岗"}},["790564b9"]={q="谁住在南门哨岗，或负责管理那里？",a="铁炉堡的巡山人驻守着这座偏远的边境哨站。他们留意穿越山道的旅人，管理补给，并与当地巡逻人员密切配合，确保丹莫罗与洛克莫丹之间的山间通道安全畅通。",al={"谁控制南门哨岗","谁管理南门哨岗","谁住在南门哨岗"}},["94f233ba"]={q="南门哨岗危险吗？",a="哨岗本身相当安全。驻守的巡山人勤勉地清除了山道沿线大部分侵扰的山地野兽，使这座哨站免受北门哨岗所面临的凶猛生物袭击与严峻压力。",al={"南门安全吗","南门哨岗危险吗","南门哨岗的危险"}},["09ad7c8c"]={q="为什么叫南门哨岗？",a="它因南门小径而得名，那是穿过丹莫罗与洛克莫丹之间峭壁的南侧山口，与北门哨岗守卫的北侧通道相对。",al={"为什么叫南门哨岗","南门哨岗名字由来","为什么叫南门"}}},fp="18,196,29.341.0,42.224.0,57.188.0,52.181.0"}
P.entries["subzone:south-gate-pass"] = {n="南门小径",s="南门小径是连接丹莫罗的雪域高地与洛克莫丹山谷盆地的主要山道。它由矮人隧道和哨岗环绕，是往返于铁炉堡和塞尔萨玛定居点之间最直接的路线。",h="南门小径是连接丹莫罗的雪域高地与洛克莫丹山谷盆地的主要山道。它由矮人隧道和哨岗环绕，是往返于铁炉堡和塞尔萨玛定居点之间最直接的路线。",kw={"丹莫罗","洛克莫丹","登山者","南门哨岗","南门小径","塞尔萨玛","隧道"},ang={["faction:Alliance"]="该关口是连接铁炉堡与东部联盟领土的重要内部动脉，由国王的登山者进行维护和保卫。",["race:Dwarf"]="对于离开丹莫罗的矮人来说，南门小径是冰冷的空气逐渐转变为洛克莫丹开阔谷地与采石场的一道门槛。"},sec={{t="通往东方之路",b="南门小径径直穿过卡兹莫丹山脉，连接着西侧丹莫罗的高山与东侧洛克莫丹起伏的谷地。离开寒冷山坡的旅行者穿过石拱门，便会进入气候更为温和的矮人腹地。由于这条路直通塞尔萨玛，因此常有登山者、信使和从首都出发的受训冒险者往来。"},{t="受守护的关口",b="南门哨岗驻扎着时刻保持警惕的矮人登山者，他们负责保卫关口，抵御野兽和徘徊的穴居人。虽然此处通常比深谷中的荒野更安全，但仍建议旅行者留在道路上，因为敌对的野生生物和游荡的威胁经常试探性地袭击关口周边。"}},faq={{q="南门小径通向哪里？",a="向西穿过隧道即可进入丹莫罗的雪域高地，那是通往铁炉堡的道路。向东行进则会下到洛克莫丹盆地，直达塞尔萨玛定居点。",al={"南门小径通往哪里","南门小径目的地","南门之路"}},{q="南门小径旅行安全吗？",a="由于南门哨岗驻扎有矮人卫兵，道路本身相对安全，但隧道口外周边的岩脊和山坡上有熊、蜘蛛和不断入侵的穴居人出没。",al={"南门小径危险吗","南门小径威胁"}},{q="为什么这条路比北门小径使用得更频繁？",a="南门小径提供了丹莫罗与塞尔萨玛之间最直接、最便捷的陆路连接，因此成为当地贸易、补给商队和前往洛克莫丹中心地带的旅行者的首选路线。",al={"南门与北门对比","为什么要走南门"}}},fx={ae3b1570={q="南门小径是什么地方？",a="南门小径是一条重要的山间通道，穿过西侧积雪的丹莫罗与东侧洛克莫丹诸山谷之间的峭壁。由于出口就在塞尔萨玛镇附近，它成为巡山人、信使和旅人往来铁炉堡故土与洛克湖之间的主要路线。",al={"南门小径资料","南门小径是什么","南门小径背景故事"}},d7b0d8f2={q="谁守卫着南门小径？",a="这条山道由驻扎在南门哨岗的铁炉堡巡山人守卫和维护。这些矮人哨兵监视着穿过隧道的往来行人，抵御潜伏在周围山丘中的野兽和敌对威胁，确保商路保持畅通。",al={"谁控制南门小径","南门小径守卫","南门哨岗"}},["487bb631"]={q="为什么叫南门小径？",a="这条山道的名字源于它在分隔丹莫罗与洛克莫丹的山脊中的位置。它构成了穿越山脉的南侧门户，与北面的北门小径遥相对应。",al={"南门小径名字含义","为什么叫南门小径","为什么叫南门"}}},fp="15,115,13.325.0,19.271.0,32.183.0,34.159.0,48.201.0"}
P.entries["subzone:south-seas"] = {n="南海",s="南海涵盖了分隔卡利姆多南部地区和东部王国的广阔阳光普照的水域。这些热带海域拍打着塔纳利斯和荆棘谷的海岸，以有利可图的贸易路线、危险的礁石和肆无忌惮的海盗船队而闻名。",h="南海涵盖了分隔卡利姆多南部地区和东部王国的广阔阳光普照的水域。这些热带海域拍打着塔纳利斯和荆棘谷的海岸，以有利可图的贸易路线、危险的礁石和肆无忌惮的海盗船队而闻名。",kw={"血帆","海盗","南海","热砂","荆棘谷","塔纳利斯","泰拉比姆","赞达拉"},ang={["class:Rogue"]="无法无天的南海是海盗财团和私掠者的生命线，为那些擅长接舷战、走私违禁品以及游走于残酷港口政治中的恶棍提供了无穷的机会。",["profession:Cooking"]="南海奇异的水域和沿岸海滩出产珍贵的海洋鱼类、巨型乌贼，以及从泰拉比姆等孤立岛屿运出的著名甜香蕉。"},sec={{t="剑客的边疆",b="南海向南延伸，位于无尽之海和大漩涡下方，冲刷着塔纳利斯的沙漠和荆棘谷郁郁葱葱的丛林。自一万年前大分裂将原始大陆撕裂以来，这片海洋孕育了偏远的热带岛屿、独特的海洋生物和独立的商贸网络。地精航运财团在热砂港和藏宝海湾等避风港运作，维持着穿过海浪的脆弱航线。然而，这片水域依然以无法无天而著称，到处都是海盗、血帆海盗以及掠食性的海洋生物，它们捕食任何胆敢远离海岸的船只。"},{t="隐藏的深渊与遥远的群岛",b="在沿海贸易航线之外，散布着一系列传奇岛屿和沉没的危险。南海中散布着著名的土地，包括古老的巨魔岛屿赞达拉和物产丰富的泰拉比姆海岸。然而，商船水手必须面对的远不止强盗；更深的水域潜藏着巨大的巨型乌贼、原始海龟以及守护着被波涛吞没的古代遗迹的潜伏娜迦。航行在这片水域需要经验丰富的船长、可靠的海图和强大的火力。"}},faq={{q="哪些地区与南海接壤？",a="在卡利姆多南部，南海构成了塔纳利斯的海岸线，靠近奥丹姆的封印大门。穿过东部的大洋，它们冲刷着荆棘谷及其哈圭罗岛和尤亚姆巴岛等外围岛屿的海岸。",al={"南海在哪里","南海边界","南海海岸"}},{q="谁控制着南海的航运？",a="没有任何单一势力统治南海。热砂财团控制着热砂港和藏宝海湾之间的主要商船交通，但他们不断与血帆海盗和南海自由海盗等敌对海盗组织争夺这些水域。",al={"谁统治南海","南海贸易","南海港口"}},{q="有哪些危险生物生活在这些水域？",a="开阔的海面上充满了危险，从贪婪的巨型乌贼和沿海礁鲨到披甲的巨型海龟，应有尽有。在第二次战争中，部落的暴风掠夺者氏族甚至捕获了这些水域原生的巨型海龟，将它们改装成海军潜水艇。该地区的岛屿还潜伏着食肉的血翼蝙蝠和出没的娜迦巡逻队。",al={"南海怪物","塔纳利斯海怪","南海生物"}},{q="南海里有哪些著名的岛屿？",a="深海中著名的岛屿包括物产丰富的泰拉比姆岛和巨魔帝国历史悠久的国度赞达拉。靠近海岸的地方则是一些较小的地标，如尤亚姆巴岛和哈圭罗岛。",al={"南海岛屿","科赞 赞达拉 南海","南海岛屿列表"}}},fx={b58adc59={q="南海是什么地方？",a="南海是无尽之海南部辽阔的海域，将卡利姆多和东部王国的南部区域分隔开来。这片温暖的热带海域位于狂暴的巨浪之下，拍打着塔纳利斯和荆棘谷的海岸，散布着偏远的群岛、海盗据点和未经探索的岛屿。",al={"南海是什么","南海概况","南海在哪里"}},["89d72661"]={q="南海的历史上发生过什么？",a="一万年前，大分裂撕碎了陆地，当时整个艾泽拉斯还是一块完整的大陆。上古之战期间，永恒之井爆炸，海水涌入裂隙，将大陆撕裂，并形成了巨浪和周边海域。散布在南海中的岛屿，都是那个远古世界的残余。",al={"南海历史","南海如何形成","南海的起源"}},["68566e28"]={q="在南海航行危险吗？",a="这片海域以险恶著称。除了变幻莫测的天气和危险的暗礁，南海还遍布凶猛的掠食者，包括巨型乌贼，以及在热带岛屿筑巢、吞食血肉的巨大血翼蝙蝠。更糟的是，血帆海盗等凶残的海盗集团在航道上游荡，袭击商船和胆敢前来的旅人。",al={"南海危险吗","南海的险情","南海的威胁"}},["7fe84177"]={q="为什么叫南海？",a="这个地区的名称直接源自其地理位置：它是无尽之海南部的一片海域，覆盖中央巨浪以南、毗邻两块主要大陆南岸的水域。",al={"南海名称由来","南海名称是怎么来的"}}},fp="10,228,25.526.0,31.445.0,33.184.0,40.248.0,46.299.0,47.154.0"}
P.entries["subzone:south-tide-s-run"] = {n="南流海岸",s="南流海岸是银松森林孤寂的西南海岸线，沿着无尽之海冰冷的水域延伸。这些潮湿的沙滩与海浪位于森林内陆的侧翼，与北流海岸互为南部对应。",h="南流海岸是银松森林孤寂的西南海岸线，沿着无尽之海冰冷的水域延伸。这些潮湿的沙滩与海浪位于森林内陆的侧翼，与北流海岸互为南部对应。",kw={"无尽之海","银松海岸","银松森林","南流海岸"},ang={["race:Undead"]="这片狂野的西南海岸远离瑟伯切尔的庇护，使其成为一片很少有被遗忘者踏足的空旷边境。"},sec={{t="西海岸",b="南流海岸沿着银松森林的西南边缘延伸，在树林与无尽之海之间形成了一道荒凉的边界。与通往格雷迈恩之墙、受到保护的东部道路不同，这条开阔的海岸直接承受着西部潮汐的冲击，成为了一片荒凉的沿海荒野，基本未受内陆定居点的影响。"}},faq={{q="南流海岸位于哪里？",a="南流海岸占据了银松森林的西南海岸线，与无尽之海的广阔水域接壤。",al={"南流海岸在哪里","南流海岸位置","南流海岸地图"}},{q="南流海岸与北流海岸有什么不同？",a="两者都是构成银松森林西部海岸线的长滩，但南流海岸覆盖了海岸的南部，而北流海岸则沿着西北方向靠近提瑞斯法林地边界的地方延伸。",al={"北流海岸与南流海岸的区别","流海岸之间的差异"}},{q="南流海岸沿线有任何定居点吗？",a="海滩本身没有任何主要城镇或哨所。大多数被遗忘者的活动仍集中在主要交通要道附近的内陆地区，使得这条海岸线处于与世隔绝的状态。",al={"南流海岸的城镇","谁居住在南流海岸"}}},fp="16,168,17.240.0,34.90.0,55.166.0,49.127.0"}
P.entries["subzone:southern-gold-road"] = {n="南黄金之路",s="南黄金之路是穿越贫瘠之地南半部的一条重要沙漠通衢，连接了中部平原与升降梯。它是区域贸易不可或缺的动脉，往来于卡利姆多远方的商队、物资和旅客都经由此地。",h="南黄金之路是穿越贫瘠之地南半部的一条重要沙漠通衢，连接了中部平原与升降梯。它是区域贸易不可或缺的动脉，往来于卡利姆多远方的商队、物资和旅客都经由此地。",kw={"贫瘠之地","商队","黄金之路","升降梯","南黄金之路","千针石林"},ang={["faction:Horde"]="这条路是贫瘠之地中心十字路口与临近千针石林的南部哨所之间部落补给线的中枢。"},sec={{t="南方的动脉",b="南黄金之路正式起始于分割贫瘠之地南北半部的石桥，向南延伸直至连接通往千针石林的升降梯。正如那条简单称为黄金之路的北部路段一样，这条尘土飞扬的公路得名于延绵不断、满载利润的商队。尽管常年受到当地野猪人部族和草原掠食者的骚扰，它依然是该大陆最繁忙的长途路径之一，在偏远哨所与繁华港口之间运送着货物。"},{t="遥远之地的十字路口",b="这条道路上的往来不仅限于部落的交通。远道而来的冒险者和坚韧的商人——他们来自塔纳利斯南部沙漠的加基森、黑海岸多雾的海岸边，或是月光林地神圣的永夜港——都会踏上这片被太阳炙烤的土地。对于那些步行穿越卡利姆多内陆的旅行者来说，活着走完南黄金之路是一场艰苦的成人礼。"}},faq={{q="南黄金之路的起点和终点在哪里？",a="这条路正式起始于分割贫瘠之地南北半部的桥梁，向南延伸，直到到达升降梯处的千针石林边缘。",al={"南黄金之路路径","南黄金之路路线","南黄金之路在哪里"}},{q="为什么叫它黄金之路？",a="这条通衢因常年往来的高价值贸易商队而得名，商队运送着宝贵的货物、矿石和钱币，横跨卡利姆多的中心地带。",al={"为什么叫黄金之路","黄金之路名称由来","黄金之路含义"}},{q="黄金之路和南黄金之路有什么区别？",a="分界线是穿过贫瘠之地中心地带的桥梁。桥梁以北被称为黄金之路，而通往南侧升降梯的路段则被划定为南黄金之路。",al={"黄金之路与南黄金之路","两条黄金之路"}},{q="谁会走这段路？",a="除了当地的部落信使和巡逻队外，商人和探险家也会利用这条路线在遥远的领地之间往来，将远南的加基森与远北的黑海岸和月光林地连接起来。",al={"谁使用南黄金之路","南黄金之路商队"}}},fp="18,177,19.497.0,29.401.0,48.151.0,31.115.0,72.149.0,39.153.0"}
P.entries["subzone:southern-savage-coast"] = {n="南野人海岸",s="南野人海岸包含了紧贴荆棘谷西南部的漫长海滩和潮汐水域。这些海岸不仅面临着南海深处潜藏的危险，还是野生猛兽、敌对娜迦以及时刻威胁着过往船只的沿海掠夺者的巢穴。",h="南野人海岸包含了紧贴荆棘谷西南部的漫长海滩和潮汐水域。这些海岸不仅面临着南海深处潜藏的危险，还是野生猛兽、敌对娜迦以及时刻威胁着过往船只的沿海掠夺者的巢穴。",kw={"藏宝海湾","加尼罗哨站","野人海岸","南海","南野人海岸","荆棘谷","暗礁海"},ang={["class:Hunter"]="宽阔开阔的海滩是两栖猎物、海岸猫科动物和蜥蜴的理想追踪地，这里的视野远比丛林内部幽闭的灌木丛要好得多。"},sec={{t="危险的海岸线",b="南野人海岸沿着南部丛林的西侧边缘延伸，标志着大陆与南海温暖洋流交汇的地带。它与北部的野人海岸被暗礁海的水下遗迹和重重危机隔开。这条海岸线穿过古拉巴什竞技场和纳克迈尼圣泉附近的小海湾，一路延伸，经过藏宝海湾和加尼罗哨站后逐渐变窄。尽管这里的海滩相比令人窒息的丛林内部视野开阔，但旅行者仍需应对凶猛的爬行类捕食者、在浅滩猎食的娜迦，以及四处搜寻猎物的海盗。"}},faq={{q="南野人海岸从哪里开始，到哪里结束？",a="它覆盖了荆棘谷的西南海岸线，起始于暗礁海下方，向南沿着海岸延伸，经过藏宝海湾和加尼罗哨站，最终过渡到蛮荒海岸。",al={"南野人海岸位置","南野人海岸在哪里","野人海岸边界"}},{q="它与北部的野人海岸有什么不同？",a="这两段海岸线被暗礁海分隔开。北部的野人海岸沿着北荆棘谷的大海海域延伸，而南野人海岸则位于南角，毗邻南海。",al={"野人海岸与南野人海岸的区别","为什么有两个野人海岸","暗礁海边界"}},{q="旅行者在海滩上会遇到什么威胁？",a="开阔的沙滩上遍布着凶恶的蜥蜴、鳄鱼、从浅滩爬出的敌对娜迦以及巡逻的领地海盗。",al={"南野人海岸危险吗","南野人海岸怪物","海岸沿线的威胁"}},{q="藏宝海湾控制着这条海岸线吗？",a="不。黑水强盗和热砂港仅对藏宝海湾的港口及其直接航道保持控制。南北两侧的荒野海滩依然是无法无天的蛮荒之地。",al={"藏宝海湾拥有这片海滩吗","热砂港对海岸的控制","地精领土"}}},fp="21,137,23.480.0,51.185.0,51.197.0,50.149.0,38.182.0"}
P.entries["subzone:southfury-river"] = {n="怒水河",s="怒水河是卡利姆多中部最主要的水道之一，它从海加尔山的高处发源，一路向南，冲刷出宽阔湍急的河道。这条河流形成了艾萨拉与灰谷，以及杜隆塔尔与贫瘠之地之间的天然边界，最终在棘齿城附近汇入无尽之海。",h="怒水河是卡利姆多中部最主要的水道之一，它从海加尔山的高处发源，一路向南，冲刷出宽阔湍急的河道。这条河流形成了艾萨拉与灰谷，以及杜隆塔尔与贫瘠之地之间的天然边界，最终在棘齿城附近汇入无尽之海。",kw={"灰谷","艾萨拉","贫瘠之地","杜隆塔尔","海加尔山","奥格瑞玛","棘齿城","怒水河"},ang={["faction:Horde"]="怒水河充当了杜隆塔尔的西部防御边界，也是连接主城与贫瘠之地核心地带的天然交通干线。"},sec={{t="重要的天然分界线",b="怒水河发源于海加尔山的高处，奔腾而下形成壮观的瀑布，随后流经卡利姆多中部。奔腾的河水成为了明确的地理分界，将灰谷的圣洁森林与古老的艾萨拉隔开，也将杜隆塔尔的干旱丘陵与贫瘠之地的草原分开。只有少数几座战略桥梁敢于横跨这湍急的水流，其中最著名的是守卫着奥格瑞玛后门的重型桥梁，以及连接杜隆塔尔与贫瘠之地的渡口。河流最终在棘齿城中立港口东北方的一处瀑布汇入无尽之海。"},{t="战略重要性",b="对于部落来说，怒水河既是一道盾牌，也是一条至关重要的天然补给线。它保护着杜隆塔尔和奥格瑞玛的西部免受地面部队的直接突袭，同时也为这片焦灼干旱的土地提供了新鲜的山泉径流。就在通往奥格瑞玛的西部渡口以北，存在一个独特的地理枢纽，四个主要区域在此交汇：灰谷、艾萨拉、杜隆塔尔和贫瘠之地。控制这条奔腾的水道可以确保奥格瑞玛与部落边远定居点之间的补给线畅通无阻。"}},faq={{q="怒水河从哪里发源，又在哪里汇入大海？",a="怒水河发源于海加尔山的高山地带，奔流而下形成壮观的瀑布，流经低地。它向南流经灰谷、艾萨拉、杜隆塔尔和贫瘠之地，最后在棘齿城东北方的一处瀑布汇入无尽之海。",al={"怒水河源头","怒水河流向","怒水河入海口"}},{q="这条河流沿途与哪些地区接壤？",a="这条河流在北部将灰谷与艾萨拉隔开，在南部将贫瘠之地与杜隆塔尔隔开。值得注意的是，在奥格瑞玛西侧桥梁以北，四个区域沿河岸交汇于一点。",al={"怒水河流经区域","怒水河边界"}},{q="旅行者可以在哪里跨越怒水河？",a="主要有三座桥梁横跨怒水河：一座连接艾萨拉和灰谷，一座通往奥格瑞玛的后门，还有一座连接杜隆塔尔与贫瘠之地的重要桥梁。",al={"怒水河桥梁","如何横跨怒水河","怒水河上的桥"}},{q="为什么这条河流对奥格瑞玛很重要？",a="这条河流构成了捍卫奥格瑞玛和杜隆塔尔西侧防线的天然屏障。此外，它新鲜的山泉水是这片干旱地区不可或缺的生命线。",al={"怒水河与奥格瑞玛","部落为何重视怒水河"}}},fx={dbc3f3f2={q="怒水河是什么地方？",a="怒水河是卡利姆多中部最显著的水道。河水从海加尔山高处向南奔流，在灰谷的森林与艾萨拉的废墟之间冲出天然边界，随后又向下流去，将杜隆塔尔与贫瘠之地分隔开来。它最终从棘齿城东北方的一处层叠瀑布注入无尽之海。",al={"怒水河是什么","怒水河概况","怒水河背景"}},["4c95fcc0"]={q="怒水河危险吗？",a="怒水河水流湍急，从海加尔山奔流而下并注入大海之处还有险峻的瀑布。除了危险的急流，两岸土地也遍布冲突和徘徊的野兽，因此不经引导贸然渡河，远比走设防的桥梁危险得多。",al={"怒水河危险吗","怒水河的威胁","怒水河的危险"}}},fp="15,206,22.348.0,20.425.0,45.191.0,34.193.0,46.154.0,40.130.0"}
P.entries["subzone:southmoon-ruins"] = {n="南月废墟",s="南月废墟是位于塔纳利斯南部、守卫之谷正北方的古代石质遗迹。这些残垣断壁长期被残暴的沙槌食人魔占据，遗迹中保留着在沙漠将其吞没之前统治此地的古代巨魔文明的遗迹。",h="南月废墟是位于塔纳利斯南部、守卫之谷正北方的古代石质遗迹。这些残垣断壁长期被残暴的沙槌食人魔占据，遗迹中保留着在沙漠将其吞没之前统治此地的古代巨魔文明的遗迹。",kw={"沙槌食人魔","遗迹","南月","南月废墟","塔纳利斯","守卫之谷"},ang={["race:Dwarf"]="穿越南部塔纳利斯的矮人旅行者在南月废墟除了饱经风霜的巨魔石雕和驻扎在其中的沙槌食人魔之外，几乎一无所获。",["race:Troll"]="对于暗矛巨魔来说，这些断壁残垣是一次令人清醒的审视，让他们看到了远房巨魔亲戚曾经的辉煌如今已沦落至在烈日下的一片荒凉。"},sec={{t="流沙之中的石块",b="南月废墟矗立在塔纳利斯南部酷热的荒原上，作为曾经统治卡利姆多南部疆域的古代巨魔帝国的风蚀见证而存在。就像附近的东月废墟和日影废墟一样，这里的石柱和祭坛历经了数千年的风蚀和沙砾磨砺。此地经常成为沙槌食人魔的肮脏营地，他们对过去的工艺毫无敬意，仅仅将这些古老的建筑用作遮风避雨和占据领地的场所。"},{t="瓦砾之下的秘密",b="这些建筑遗迹带有明显的巨魔风格，但关于是谁建造了南月废墟，以及他们为何遗弃这里，几乎没有记载留存。无论他们留下了什么，都已经埋葬在流动的黄沙之下，而那些在石柱间盘踞的食人魔对此毫无兴趣。"}},faq={{q="南月废墟最初是谁建造的？",a="南月废墟是古代巨魔的遗迹，是曾经占据如今塔纳利斯沙漠南部疆域的巨魔文明的残存遗迹。",al={"南月废墟建造者","南月历史","这是巨魔遗迹吗"}},{q="目前是谁居住在这些废墟中？",a="这些废墟传统上一直由沙槌食人魔占据，他们游荡到塔纳利斯，将各种破败的古代哨所作为营地，并赶走了其他拾荒者。",al={"谁住在这里","南月废墟怪物","南月废墟的沙槌食人魔"}},{q="南月废墟位于哪里？",a="它们位于塔纳利斯的南半部，地处守卫之谷的西北方，中部沙漠荒原的南侧。",al={"南月废墟位置","南月废墟在哪里","如何找到南月废墟"}}},fp="15,198,28.348.0,26.225.0,41.142.0,33.152.0,38.124.0"}
P.entries["subzone:southpoint-tower"] = {n="南点哨塔",s="南点哨塔是一座位于希尔斯布莱德丘陵西侧边界的洛丹伦废弃侦查塔，俯瞰着通往银松森林的道路。这座曾经的人类哨所如今已是残垣断壁，被遗忘者侦察兵用来监视该地区的联盟动向。",h="南点哨塔是一座位于希尔斯布莱德丘陵西侧边界的洛丹伦废弃侦查塔，俯瞰着通往银松森林的道路。这座曾经的人类哨所如今已是残垣断壁，被遗忘者侦察兵用来监视该地区的联盟动向。",kw={"亡灵哨兵莱什","希尔斯布莱德农场","希尔斯布莱德丘陵","侦察塔","银松森林","南点哨塔"},ang={["faction:Alliance"]="这座废弃的塔楼窝藏着监视通往银松森林道路的敌方间谍，这使它成为保护希尔斯布莱德人类定居点的侦察兵们的天然打击目标。",["race:Undead"]="对于被遗忘者而言，这座塔楼在银松森林边界提供了一个不可或缺的侦察高地，用于监测从希尔斯布莱德出发的人类部队调动。"},sec={{t="废墟哨兵",b="南点哨塔耸立在连接银松森林和希尔斯布莱德丘陵的公路南侧，最初由洛丹伦王国建造，旨在守卫东部农田与西部森林之间的交通往来。第三次战争及天灾军团摧毁王国后，石砌建筑便化为废墟。如今，它屋顶尽失，砖石剥落，成为这片破碎领土上人类统治的一座孤立遗迹。"},{t="高地之眼",b="尽管已成废墟，但这处制高点仍具有重要的战术价值。遗忘者在此维持着一个前哨站，并派遣亡灵哨兵莱什等特工驻守于此，窥探当地的联盟巡逻队、附近的希尔斯布莱德农场人类定居点以及沿主路经过的旅行者。由于其孤立的位置紧邻敌对领土，这座塔楼频繁成为小规模冲突的爆发点。"}},faq={{q="南点哨塔位于何处？",a="南点哨塔位于希尔斯布莱德丘陵的西缘，就在通往银松森林的道路正南方，希尔斯布莱德农场以西。",al={"南点哨塔位置","南点哨塔在哪里","寻找南点哨塔"}},{q="目前是谁控制着南点哨塔？",a="该塔楼由遗忘者控制。一名名叫亡灵哨兵莱什的特工驻扎在其残破的墙壁内，观察着道路并监视附近的联盟部队。",al={"谁在南点哨塔","南点哨塔归谁所有","南点哨塔阵营"}},{q="为什么塔楼会变成废墟？",a="在洛丹伦陷落、天灾军团蹂躏该地区时，这座塔楼遭到破坏并被废弃。它从未被修复，只剩下破碎的石墙。",al={"为什么南点哨塔是破损的","谁摧毁了南点哨塔"}},{q="为什么联盟玩家会攻击这个前哨站？",a="该哨所驻有一名正在监视人类领土的被遗忘者侦察兵。其紧邻边界的孤立位置使其成为往返南海镇与西部道路的联盟旅行者眼中一个容易且诱人的目标。",al={"为什么要击杀亡灵哨兵莱什","联盟攻击南点哨塔"}}},fp="16,157,17.374.0,17.340.0,34.137.0,40.123.0,26.164.0,44.210.0"}
P.entries["subzone:southridge-beach"] = {n="南山海滩",s="南山海滩沿着艾萨拉中部风暴海湾的南岸延展开来。这里曾是古老的卡多雷城市艾萨拉的一处宏伟区划，如今却只剩下破碎的废墟，被敌对的纳迦、鱼人和高大的海巨人所占据。",h="南山海滩沿着艾萨拉中部风暴海湾的南岸延展开来。这里曾是古老的卡多雷城市艾萨拉的一处宏伟区划，如今却只剩下破碎的废墟，被敌对的纳迦、鱼人和高大的海巨人所占据。",kw={"艾萨拉","风暴海湾","甲壳生物","鱼人","纳迦","海巨人","南山海滩"},ang={["race:NightElf"]="南山海滩上的破败建筑无声地诉说着大分裂前高等精灵文明的辉煌与悲惨陨落，令人唏嘘不已。"},sec={{t="沉没的海岸线",b="南山海滩构成了风暴海湾汹涌水域的南边界。数千年前，这片海岸曾是高等精灵城市艾萨拉辉煌的一部分，但大分裂撕裂了大地，将其大部分宫殿沉入海底。如今，风化的大理石柱和饱经风霜的石质亭阁散布在沙滩上。这里早已不再有学者和贵族的身影，取而代之的是好战的毒鞭纳迦、潜行的甲壳生物、凶残的多头蛇以及四处拾荒的鱼人部落。即便是巨大的海巨人也会偶尔从深海游荡到岸上。"}},faq={{q="南山海滩位于何处？",a="南山海滩位于艾萨拉中部，坐落在风暴海湾的南缘，紧邻内陆悬崖下方。",al={"南山海滩位置","南山海滩在哪里","艾萨拉南山海滩"}},{q="海滩上散布着什么遗迹？",a="沙滩上的石柱和拱门是艾萨拉的外围残骸，这是一座曾经伟大的高等精灵城市，在一万年前的大分裂中被摧毁并淹没。",al={"南山海滩遗迹","艾萨拉遗迹海滩","这里的遗迹是什么"}},{q="南山海滩上生活着什么生物？",a="海岸线上布满了纳迦，此外还有原始的鱼人、披甲的甲壳生物、危险的多头蛇，以及偶尔游荡的海巨人。",al={"南山海滩怪物","南山海滩敌人","这里生活着什么"}},{q="为什么这里有这么多纳迦？",a="纳迦从深海涌出，试图收复它们在艾萨拉的前文明遗迹，并在风暴海湾沿岸建立了稳固的军事据点。",al={"为什么海滩上有纳迦","纳迦南山海滩","艾萨拉纳迦"}}},fp="16,156,19.469.0,34.126.0,41.169.0,40.117.0,32.183.0"}
P.entries["subzone:southshore"] = {n="南海镇",s="南海镇是希尔斯布莱德丘陵的一座人类沿海港口，也是洛丹伦沦陷后联盟仅存的几个据点之一。它曾经是一个宁静的渔村，如今却成了一座饱经战火的堡垒，时刻面临着塔伦米尔的被遗忘者驻军、辛迪加不法暴徒以及海岸怪物的威胁。",h="南海镇是希尔斯布莱德丘陵的一座人类沿海港口，也是洛丹伦沦陷后联盟仅存的几个据点之一。它曾经是一个宁静的渔村，如今却成了一座饱经战火的堡垒，时刻面临着塔伦米尔的被遗忘者驻军、辛迪加不法暴徒以及海岸怪物的威胁。",kw={"希尔斯布莱德","杰森","洛丹伦","马雷布","雷德帕斯","南海镇","辛迪加","塔伦米尔"},ang={["faction:Alliance"]="南海镇是你作为联盟成员在北洛丹伦的主要避难所、任务中心和军事堡垒，为你对抗被遗忘者和辛迪加提供必要的支持。",["faction:Horde"]="对于部落——尤其是附近塔伦米尔的被遗忘者来说——南海镇是一个顽固的联盟飞地，侵占了属于亡者的土地。"},sec={{t="洛丹伦的灯塔",b="南海镇在第一次战争期间首次崭露头角，当时载着暴风城王国沦陷后的幸存者的难民船在它的海滩上登陆。尽管在第二次战争期间曾被争夺和占领，但它后来得到了重建，并熬过了第三次战争的恐怖。今天，当洛丹伦的其他地区陷入废墟或处于被遗忘者的统治之下时，南海镇依然坚定地效忠于大联盟。它为流离失所的人类幸存者、白银之手的资深圣骑士以及肯瑞托的学者们提供了避难所。"},{t="四面受敌",b="尽管这里有美丽的码头，米奈希尔港和奥伯丁之间的船只也会在此停靠，而且这里还有著名的海龟浓汤，但南海镇的生活依然充满危险。在赫尼·马雷布镇长和治安官雷德帕斯的领导下，该镇在巨大的压力下艰难求生。在北方，塔伦米尔的被遗忘者为了争夺对希尔斯布莱德的统治权，发动了激烈的边界冲突。在内陆，辛迪加的贵族亡命徒袭击补给线并暗杀当地领导人，同时食人魔、鱼人和娜迦也不断骚扰城镇的边界。"}},faq={{q="既然洛丹伦已经沦陷，为什么南海镇依然站在联盟这一边？",a="南海镇在天灾军团的入侵中幸免于难，未被彻底摧毁。其幸存的人类民众重申了他们对大联盟的历史誓言，并获得了来自暴风城的军事和后勤支持，从而在北方保留了一个立足点。",al={"为什么南海镇属于联盟","谁控制了南海镇","南海镇 联盟 洛丹伦"}},{q="为什么南海镇和塔伦米尔之间会有如此激烈的战斗？",a="塔伦米尔由被遗忘者控制，而南海镇则是该地区主要的联盟堡垒。双方都声称拥有对希尔斯布莱德丘陵的合法统治权，导致了几乎不断的边界冲突、突袭和破坏活动。",al={"南海镇与塔伦米尔的战争","为什么南海镇和塔伦米尔会战斗","希尔斯布莱德冲突"}},{q="谁在领导南海镇？",a="民政事务由赫尼·马雷布镇长处理，他在前任镇长被辛迪加暗杀后接管了职位。军事防御和城镇安全则由治安官雷德帕斯指挥。",al={"南海镇领导人","谁管理南海镇","马雷布镇长"}},{q="除了被遗忘者，南海镇还面临哪些威胁？",a="除了被遗忘者，南海镇还必须抵御海岸上的鱼人和娜迦、从奥特兰克山脉南下的碎颅食人魔，以及盘踞在敦霍尔德城堡的辛迪加犯罪组织。",al={"南海镇的敌人","南海镇面临的威胁"}}},fx={f6e4321c={q="南海镇是什么地方？",a="南海镇是希尔斯布莱德丘陵南岸一座繁忙的港口城镇。在天灾军团摧毁首都后，这里成为洛丹伦仅存的人类文明据点和联盟权力中心之一。尽管周围遍布敌对势力，南海镇仍维持着正常运作的港口、地方政务和坚定的驻军。",al={"南海镇是什么地方","南海镇","南海镇简介"}},b35b5b82={q="南海镇历史上发生过什么？",a="南海镇最初只是一个普通的渔村，第一次战争后接纳了逃离暴风城的难民。第二次战争期间，它因近海石油而成为各方觊觎的战略港口，曾被部落攻陷，战后又被收复并重建。",al={"南海镇历史","南海镇背景","南海镇的历史"}},["856a6b32"]={q="南海镇危险吗？",a="对联盟而言，南海镇有严密守卫，是一处安全的避难所，但周边乡野危机四伏。与塔伦米尔的被遗忘者之间的冲突常常蔓延至丘陵各处，沿海的鱼人和娜迦也威胁着港口。此外，辛迪加盗贼、破碎岭食人魔和徘徊的亡灵都潜伏在城镇外围。",al={"南海镇有多危险","南海镇安全吗","南海镇的威胁"}}},fp="10,210,21.452.0,22.469.0,70.225.0,70.197.0,33.176.0,58.136.0"}
P.entries["subzone:southshore-town-hall"] = {n="Southshore Town Hall",s="南海镇市政厅是希尔斯布莱德丘陵南海岸的行政中心，也是洛丹伦尚存的民政权力机构之一。赫尼·马雷布镇长在厅内协调当地的防御工作，并管理着镇上的幸存居民。这座市政厅是联盟在饱受瘟疫蹂躏的北方苦苦维持立足点时的重要枢纽。",h="南海镇市政厅是希尔斯布莱德丘陵南海岸的行政中心，也是洛丹伦尚存的民政权力机构之一。赫尼·马雷布镇长在厅内协调当地的防御工作，并管理着镇上的幸存居民。这座市政厅是联盟在饱受瘟疫蹂躏的北方苦苦维持立足点时的重要枢纽。",kw={"赫尼·马雷布","希尔斯布莱德","昆德瑞克·赞登","洛丹伦","镇长","南海镇","市政厅"},ang={["faction:Alliance"]="对于抵达北方的联盟勇士来说，南海镇市政厅是提供区域行政授权和发布对抗周边威胁的重要任务的主要民政哨所。",["race:Human"]="人类旅行者将这座市政厅视为洛丹伦失落荣耀的辛酸见证，在这里，一位行使职权的镇长依然在飘扬着破碎王国的旗帜。"},sec={{t="民政统治的堡垒",b="尽管大部分洛丹伦地区都在天灾军团的腐化和被遗忘者的扩张下支离破碎，南海镇的市政厅依然维持着人类政府尚存的样貌。赫尼·马雷布镇长在此处办公，监督日常政务，并与昆德瑞克·赞登等官员协作，保障资源供给并维护民政秩序。在一片被凶残的不死族、辛迪加盗贼和希尔斯布莱德激烈的边境冲突所包围的区域，这座市政厅是指挥城镇在持续不断的威胁中求生的神经中枢。"}},faq={{q="是谁在南海镇市政厅领导着这座城镇？",a="赫尼·马雷布镇长是南海镇的主要行政领导人，他在市政厅内处理镇务，指挥这座人类定居点的防御和行政事务。",al={"这里由谁负责","南海镇镇长","谁管理南海镇"}},{q="南海镇市政厅具有怎样的战略重要性？",a="它代表了洛丹伦在北方最后合法的民政领导机构之一。联盟成员寻求市政厅的指引、赏金任务，以及对抗步步紧逼的被遗忘者和辛迪加匪徒的协同作战。",al={"市政厅为什么重要","南海镇的重要性"}},{q="还有谁在市政厅里工作？",a="除了赫尼·马雷布镇长，还有像昆德瑞克·赞登这样的公务员驻守在市政厅内，协助管理当地事务并支持城镇的运作。",al={"谁在南海镇市政厅里","昆德瑞克·赞登","市政厅角色"}},{q="市政厅是如何与更广阔的联盟保持联系的？",a="虽然历史上南海镇属于洛丹伦王国，但现在它及其领导层极度依赖联盟，通过联盟获得的增援和补给来保卫这一孤立的沿海堡垒，对抗周遭的敌对势力。",al={"南海镇属于联盟吗","与暴风城的联系"}}},fp="20,212,23.384.0,49.138.0,57.203.0,36.151.0,61.210.0"}
P.entries["subzone:southwind-village"] = {n="南风村",s="南风村是希利苏斯黄沙中一座暗夜精灵前哨站的闹鬼废墟。在流沙之战中被其拉虫人彻底摧毁，如今村庄的街道上游荡着阵亡守卫者们不安的灵魂，以及四处潜行的其拉虫群。",h="南风村是希利苏斯黄沙中一座暗夜精灵前哨站的闹鬼废墟。在流沙之战中被其拉虫人彻底摧毁，如今村庄的街道上游荡着阵亡守卫者们不安的灵魂，以及四处潜行的其拉虫群。",kw={"范达尔·鹿盔","其拉虫人","拉贾克斯将军","琥珀月之影","希利苏斯","南风村","瓦斯坦·鹿盔","流沙之战"},ang={["class:Druid"]="南风村残破的林地建筑和那些受折磨的古代德鲁伊灵魂，沉重地提醒着人们大自然在面对虫族大军时所遭受的惨痛损失。",["race:NightElf"]="对于暗夜精灵来说，南风村是他们历史上最痛苦的失败之一，而徘徊在残垣断壁间的那些受折磨的幽灵，正是等待着安宁的卡多雷同胞。"},sec={{t="黄沙中的悲剧",b="一千年前的流沙之战期间，南风村曾是暗夜精灵的主要据点。当其拉虫人大军突破防御防线时，大德鲁伊范达尔·鹿盔之子瓦斯坦·鹿盔率领一支小分队驻守该村。这场防御战以彻底的灾难告终：暗夜精灵守卫者们被压倒性的兵力屠戮殆尽，瓦斯坦本人也被拉贾克斯将军拖走并俘虏。村庄被夷为平地，昔日的建筑在烈日下分崩离析。"},{t="受折磨的亡者",b="在毁灭后的千年里，南风村一直是沙漠中未愈合的伤口。那场袭击带来的创伤是如此彻底，以至于阵亡的暗夜精灵哨兵和德鲁伊们的灵魂无法安息。由于无法摆脱生命最后时刻的恐怖，这些不安的幻影在琥珀月之影的带领下，无止境地徘徊在坍塌的石墙间，袭击任何闯入者，而贪婪的其拉虫群则在周围的沙丘中蜂拥肆虐。"}},faq={{q="南风村发生了什么？",a="南风村在一千年前的流沙之战中被摧毁。贪婪的其拉虫人军队蜂拥而至，袭击了暗夜精灵的驻军，无情地屠杀了守卫者并将这座前哨站夷为平地。",al={"为什么南风村是废墟","南风村背景故事","什么摧毁了南风村"}},{q="瓦斯坦·鹿盔是谁？",a="瓦斯坦·鹿盔是大德鲁伊范达尔·鹿盔挚爱的儿子。他领导了针对入侵虫族的南风村防御战，但他的部队伤亡殆尽，他本人也被其拉指挥官拉贾克斯将军俘虏。",al={"瓦斯坦·鹿盔南风村","范达尔·鹿盔之子","谁防守了南风村"}},{q="为什么这里有暗夜精灵的鬼魂？",a="守卫者们突如其来的残酷屠杀将他们的灵魂困在了废墟之中。阵亡的德鲁伊和哨兵的灵魂陷入了他们生命最后时刻那场恐怖战斗的永恒循环中，并在琥珀月之影的徘徊注视下不得解脱。",al={"南风村亡魂","为什么南风村有鬼魂","琥珀月之影"}},{q="虫子与摧毁村庄的原因有关吗？",a="是的。在废墟周围蜂拥而至的其拉虫群是其拉虫人虫族灾难的一部分，正是这股势力在几个世纪前入侵了希利苏斯并摧毁了这座前哨站。",al={"其拉虫群南风村","虫子和南风村有关系吗"}}},fp="17,199,22.428.0,18.382.0,35.195.0,26.218.0,36.207.0,51.141.0"}
P.entries["subzone:spirit-rise"] = {n="灵魂高地",s="灵魂高地是雷霆崖西北部的台地，是这座牛头人主城中进行精神和萨满修行的首要圣地。这里由追天者部族等精神向导管理，上方设有神圣的训练大厅，并向下延伸至洞穴般的预见之池。",h="灵魂高地是雷霆崖西北部的台地，是这座牛头人主城中进行精神和萨满修行的首要圣地。这里由追天者部族等精神向导管理，上方设有神圣的训练大厅，并向下延伸至洞穴般的预见之池。",kw={"灵魂大厅","莫高雷","预见之池","萨满","追天者","灵魂高地","雷霆崖"},ang={["class:Shaman"]="对于部落的萨满来说，灵魂高地是一个重要的聚集地，可以咨询训练师、进行元素仪式并与祖先之灵沟通。",["race:Tauren"]="这座高地体现了你们人民深厚的精神根源，在预见之池神秘的水域旁，让你从世俗的职责中获得慰藉。"},sec={{t="灵魂的圣所",b="灵魂高地高踞在俯瞰莫高雷平原的峭壁之上，致力于与元素和祖先之灵沟通。通过绳桥与中心台地相连，这里设有灵魂大厅和心灵治疗馆，年轻的和资深的萨满在此聚集，加深他们与大地、空气、火焰和水的联系。追天者部族在整个高地上保持着强大的影响力，指引寻求者遵循古老的传统。"},{t="洞穴与通道",b="在微风吹拂的小屋和露天图腾神龛之下，有一个深入台地本身的入口：热气腾腾的预见之池，这是一个神圣的地下洞穴，先知们在此凝视被灵魂触碰的水面。"}},faq={{q="灵魂高地以什么闻名？",a="灵魂高地是雷霆崖的精神中心，主要用于萨满修行、治疗，以及与自然之灵和祖先沟通。它也是通往预见之池的入口。",al={"灵魂高地是什么","灵魂高地的目的","为什么要访问灵魂高地"}},{q="哪个牛头人部族领导灵魂高地的活动？",a="追天者部族在此拥有显著的影响力，培养着定义了这座高地的精神传统、占卜仪式和萨满训练。",al={"谁管理灵魂高地","灵魂高地的部族","追天者部族"}},{q="我能在灵魂高地下方找到什么？",a="从高地向下走便可进入预见之池，这是一个潮湿的地下洞穴，充满了冒着热气的水，先知和精神修行者们在此冥想并寻求幻象。",al={"灵魂高地的洞穴","灵魂高地下方","预见之池入口"}}},fp="11,180,26.426.0,19.178.0,30.141.0,51.135.0,39.165.0"}
P.entries["subzone:spirit-rock"] = {n="灵魂石地",s="灵魂石地是位于杜隆塔尔试炼谷上方嶙峋峭壁上的一处神圣岩架。通过一条名为秘道的蜿蜒小径即可到达，它是一处隐秘的圣地，新兵们在此直接与大地的元素力量进行沟通。",h="灵魂石地是位于杜隆塔尔试炼谷上方嶙峋峭壁上的一处神圣岩架。通过一条名为秘道的蜿蜒小径即可到达，它是一处隐秘的圣地，新兵们在此直接与大地的元素力量进行沟通。",kw={"大地的召唤","杜隆塔尔","大地之灵","秘道","萨普塔","萨满","灵魂石地","试炼谷"},ang={["class:Shaman"]="灵魂石地对于年轻的兽人和巨魔萨满来说是一次至关重要的成年礼，他们踏上秘道去饮用大地萨普塔，并建立起他们与岩石和土地之灵的最初羁绊。"},sec={{t="元素圣所",b="它俯瞰着年轻的部落战士和斥候开始受训的红色峡谷，灵魂石地是一座沟通的祭坛。它与试炼谷的喧嚣隔绝，只能通过蜿蜒在岩石脊线上的秘道到达。有抱负的萨满祭司会前往这处荒凉的露头进行朝圣，饮下传统的萨普塔，穿透物质世界的面纱，倾听大地本身的轰鸣与低语。"}},faq={{q="灵魂石地的用途是什么？",a="灵魂石地是一处主要供部落萨满学徒使用的神圣场所。通过在这块岩石上饮用一种被称为大地萨普塔的特殊药剂，新手们可以获得与大地之灵直接沟通所需的灵视。",al={"灵魂石地用途","灵魂石地发生了什么","灵魂石地使用"}},{q="如何前往灵魂石地？",a="灵魂石地坐落在杜隆塔尔西南部试炼谷上方的悬崖高处。可以通过攀登秘道到达，这是一条狭窄且没有标记的小径，从峡谷底部蜿蜒延伸至崎岖的山丘中。",al={"如何到达灵魂石地","通往灵魂石地的道路","灵魂石地位置"}},{q="什么是萨普塔？",a="萨普塔是一种由萨满训练师调制的仪式性元素药剂。饮用它可以改变寻求者的感知，使他们能够察觉到普通感官无法看到的元素显现。",al={"大地萨普塔","什么是萨普塔","萨普塔饮料"}}},fp="11,147,27.329.0,29.165.0,29.140.0,16.173.0"}
P.entries["subzone:splinterspear-junction"] = {n="断矛路口",s="断矛路口是蜿蜒穿过悲伤沼泽腹地的主干道上一个战略性的分叉点。这里矗立着一座粗犷的兽人瞭望塔，部落哨兵会定期在此巡逻，它将通往北部避难地和南部前哨的路径分离开来。",h="断矛路口是蜿蜒穿过悲伤沼泽腹地的主干道上一个战略性的分叉点。这里矗立着一座粗犷的兽人瞭望塔，部落哨兵会定期在此巡逻，它将通往北部避难地和南部前哨的路径分离开来。",kw={"避难营","断矛路口","斯通纳德","悲伤沼泽","瞭望塔"},ang={["faction:Alliance"]="在路口附近行走时要小心；兽人瞭望塔有大量部落哨兵把守，他们渴望斩杀任何从夜色镇流落至此的入侵者。",["faction:Horde"]="路口的瞭望塔为往返于斯通纳德与沼泽北部目的地之间的旅客提供了重要的路径点和安全检查站。"},sec={{t="冲突的十字路口",b="断矛路口坐落在悲伤沼泽的中心附近，将旅客分流到两条道路：一条是通往失落者避难所——避难营和农田避难所的北部小径，另一条是直接经过斯通纳德要塞并通往诅咒之地的南部公路。一座古老的兽人瞭望塔俯瞰着这个分岔路口，由现役的部落军队驻守和巡逻。对于部落成员来说，这是在险恶沼泽中一个安全的地标；而对于联盟旅客而言，它是这条本就无情的道路上一个致命的伏击点。"}},faq={{q="断矛路口的道路通向何处？",a="这条路分为两条截然不同的路线。北方的岔路经过德莱尼人的避难所避难营，通向农田避难所；而南方的支路引导旅客向南前往斯通纳德，并继续进入诅咒之地的干旱荒野。",al={"道路去向","断矛路口路径","断矛路口往哪走"}},{q="断矛路口对联盟旅客安全吗？",a="不安全。该路口由部落控制，他们在此处维持着一座防御坚固的瞭望塔，并在交叉路口周围进行定期巡逻。这些守卫对联盟公开敌对，一旦发现路过的冒险者就会发起攻击。",al={"断矛路口对联盟是否安全","守卫是否敌对","断矛路口玩家对战"}}},fp="22,185,24.473.0,50.158.0,54.156.0"}
P.entries["subzone:splintertree-post"] = {n="碎木岗哨",s="碎木岗哨是灰谷东部主要的部落要塞，位于冥火岭的西北方。它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，是抵御暗夜精灵的坚固堡垒，也是领土扩张的据点。",h="碎木岗哨是灰谷东部主要的部落要塞，位于冥火岭的西北方。它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，是抵御暗夜精灵的坚固堡垒，也是领土扩张的据点。",kw={"灰谷","阿斯特兰纳","冥火岭","格罗玛什·地狱咆哮","碎木岗哨","弗拉格","战歌氏族"},ang={["faction:Horde"]="碎木岗哨是冒险者穿越灰谷时的重要中央基地，提供维修、休憩之所，以及横跨卡利姆多的关键飞行航线。",["race:NightElf"]="对暗夜精灵而言，这座要塞是灰谷上的一道苦涩伤疤，它由那位击倒了塞纳留斯的督军所建，并由那些屠戮他们古老树木的入侵者所延续。"},sec={{t="边境据点",b="碎木岗哨直接从古老的林地中开辟而成，是部落在灰谷东部的主要军事和后勤枢纽。最初由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间兽人首次进入森林时建立，如今它仍是一个重兵把守的飞地，主要由兽人和牛头人侦察兵及战士进行防御。这里设有飞行管理员、旅店，并拥有通往奥格瑞玛的稳定补给线，是部落在树冠之下维持抗争的基石。"},{t="持续的报复威胁",b="碎木岗哨时刻处于戒备状态。暗夜精灵既没有忘记也没有原谅格罗玛什在战争期间的暴行，更无法容忍兽人持续进行的伐木活动以及对阿斯特兰纳的突袭。因此，这个定居点时刻面临着藏身于周围林木中的哨兵所发动的报复性打击和游击战，这无时无刻不在考验着驻军守卫。"}},faq={{q="谁建立了碎木岗哨？",a="它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，当时兽人首次进入灰谷以采集木材并建立立足点。",al={"谁建造了碎木岗哨","碎木岗哨建立者","格罗玛什 碎木岗哨"}},{q="为什么暗夜精灵频繁攻击这个基地？",a="暗夜精灵将碎木岗哨视为对祖先领地的非法亵渎与入侵。格罗玛什在第三次战争中的残暴战役留下的敌意至今未散，而部落持续的伐木活动以及针对附近精灵据点阿斯特兰纳的冲突，更加剧了这种敌意。",al={"为什么精灵要攻击","碎木岗哨哨兵袭击","暗夜精灵突袭碎木岗哨"}},{q="这里提供哪些设施和旅行选择？",a="碎木岗哨提供旅店、马厩管理员、邮箱、护甲维修服务，以及通往奥格瑞玛、十字路口和卡利姆多各地其他部落前哨站的双足飞龙飞行管理员。",al={"碎木岗哨飞行路线","碎木岗哨服务","碎木岗哨旅店"}},{q="碎木岗哨目前的驻军由谁组成？",a="该定居点主要由兽人和牛头人居住，他们作为经验丰富的侦察兵、哨兵和前线军官，负责驻守边境。",al={"碎木岗哨守卫","谁住在碎木岗哨","碎木岗哨种族"}}},fp="17,247,21.389.0,34.327.0,30.169.0,51.243.0,53.190.0,52.162.0"}
P.entries["subzone:splithoof-crag"] = {n="裂蹄峭壁",s="裂蹄峭壁是加拉克半人马的一处堡垒式定居点，坐落在千针石林北侧的悬崖边。它是该部族除了高耸的台地之外的主要据点之一，守卫着通往裂蹄堡的入口。穿行于峡谷底部的旅行者必须应对在峭壁附近游荡的、极具攻击性的加拉克巡逻队。",h="裂蹄峭壁是加拉克半人马的一处堡垒式定居点，坐落在千针石林北侧的悬崖边。它是该部族除了高耸的台地之外的主要据点之一，守卫着通往裂蹄堡的入口。穿行于峡谷底部的旅行者必须应对在峭壁附近游荡的、极具攻击性的加拉克巡逻队。",kw={"半人马","裂开的蹄子","黑云峰","加拉克","裂蹄峭壁","裂蹄堡","千针石林"},ang={["faction:Horde"]="控制峭壁下方的通道对于确保南贫瘠之地、乱风岗和闪光平原之间的通行安全至关重要。",["race:Tauren"]="牛头人与半人马之间长期的敌对状态，使得裂蹄峭壁成为部落侦察兵监控千针石林各地敌对活动时的重点关注对象。"},sec={{t="加拉克要塞",b="裂蹄峭壁依傍着千针石林北侧的险峻岩壁而建，位于巍峨的黑云峰正东方。这是一处成熟的加拉克半人马飞地，有着粗陋的帐篷营地和穿过峭壁的土路。在村庄中心，背靠悬崖的地方坐落着裂蹄堡，这是一处地下洞穴，里面供奉着裂蹄之蹄——一件由圣火盆守护的古老半人马圣物。"},{t="守卫洞穴",b="加拉克部族在峡谷的这一隅进行着激烈的争夺，与任何经过此地、在峭壁下徘徊的旅行者、部落远征队或牛头人侦察小队发生冲突。虽然恐怖图腾部族占据着附近高耸的山峰，但半人马牢牢控制着这处峡谷沟壑以及深埋于岩石之下的洞穴。"}},faq={{q="谁住在裂蹄峭壁？",a="这处定居点属于加拉克半人马部族，他们是与敌对的恐怖图腾牛头人并列，在千针石林中居住的主要氏族之一。",al={"裂蹄峭壁里有什么人","裂蹄峭壁怪物","裂蹄峭壁的半人马"}},{q="裂蹄峭壁位于哪里？",a="它位于千针石林的北侧峡谷壁上，坐落在黑云峰的正东方。",al={"裂蹄峭壁在哪里","裂蹄峭壁位置"}},{q="裂蹄堡里有什么？",a="裂蹄堡是该村庄的核心洞穴。在深处的密室中，加拉克人守护着“裂蹄之蹄”，这是一件被古老火盆中燃烧的圣火所保护的远古部族神器。",al={"什么是裂蹄堡","裂蹄峭壁的洞穴"}},{q="这里的半人马与附近的恐怖图腾有盟约吗？",a="没有。没有任何迹象表明他们之间存在结盟：加拉克人固守着他们的峡谷村庄和洞穴，而恐怖图腾则占据着黑云峰的高地。",al={"恐怖图腾与加拉克","半人马与牛头人的关系"}}},fx={fc440e32={q="裂蹄峭壁是什么地方？",a="裂蹄峭壁是千针石林北部岩壁上的一处坚固聚落，位于黑云峰以东不远处。这里是当地加拉克半人马的重要据点，峡谷底部散布着成群的营地，内部还有一处名为裂蹄堡的洞穴。",al={"这是什么地方","裂蹄峭壁简介","裂蹄峭壁介绍"}},["76cca678"]={q="裂蹄峭壁危险吗？",a="对外来者来说，这里极其危险。加拉克半人马凶悍好斗，领地意识极强，会一见入侵者便发动攻击。此外，聚落内部的圣所裂蹄堡也防守严密，用以保护他们的圣物。",al={"这里安全吗","裂蹄峭壁的危险","裂蹄峭壁的威胁"}}},fp="14,195,18.325.0,21.214.0,28.138.0,32.108.0,30.162.0,54.164.0"}
P.entries["subzone:splithoof-hold"] = {n="裂蹄堡",s="裂蹄堡是千针石林中一座深藏于裂蹄峭壁岩石内部的洞穴要塞。该洞穴由加拉克半人马部族占据，作为一座防御森严的巢穴，并供奉着古老火盆，其中燃烧着永不熄灭的神圣火焰。",h="裂蹄堡是千针石林中一座深藏于裂蹄峭壁岩石内部的洞穴要塞。该洞穴由加拉克半人马部族占据，作为一座防御森严的巢穴，并供奉着古老火盆，其中燃烧着永不熄灭的神圣火焰。",kw={"古老火盆","加拉克半人马","神圣之火","裂蹄峭壁","裂蹄堡","千针石林"},ang={["class:Shaman"]="在黑暗的石洞深处存在着一团永恒之火，这吸引了所有感应元素之火原始奥秘的灵性修行者的注意。",["race:Tauren"]="加拉克半人马依然是牛头人的血仇死敌，这使得他们在千针石林中保持的任何据点，都对乱风岗的安宁构成了直接威胁。"},sec={{t="半人马堡垒",b="裂蹄堡隐藏在裂蹄峭壁之内，是加拉克半人马的防御据点。与狂风呼啸的峡谷底部不同，这座封闭的洞穴为他们提供了遮蔽、易守难攻的关隘，以及躲避敌对部族和穿行在千针石林的旅人的安全避难所。"},{t="神圣之火",b="要塞幽暗的深处安放着一座古老火盆，其中孕育着神圣之火。这团神秘的火焰经久不息，既是半人马力量与仪式崇拜的焦点，也是峡谷中那些追寻灵性的流浪者们深感好奇的对象。"}},faq={{q="裂蹄堡在哪里？",a="裂蹄堡坐落在千针石林北侧崖壁上的裂蹄峭壁之中。入口位于半人马主要定居点内的一个洞穴开口处。",al={"裂蹄堡位置","裂蹄堡在哪里","如何找到裂蹄堡"}},{q="谁控制着裂蹄堡？",a="该洞穴由加拉克半人马部族所占据，他们积极防御着洞穴，抵御外来者、野兽入侵以及附近乱风岗的牛头人。",al={"谁住在裂蹄堡","裂蹄堡怪物","谁拥有裂蹄堡"}},{q="要塞里有什么？",a="除了充满敌意的加拉克半人马守卫，洞穴内还供奉着古老火盆，这是一件让神秘的神圣之火在岩石深处永恒燃烧的神器。",al={"裂蹄堡里有什么","古老火盆位置","裂蹄堡神圣之火"}}},fx={["9edfe937"]={q="裂蹄堡是什么地方？",a="裂蹄堡是千针石林裂蹄峭壁岩层中的一处洞穴据点。凶悍的加拉克半人马部族占据了天然洞穴，并将其改造成峡谷中的坚固基地，将圣物和氏族的炉火安置在其中。",al={"裂蹄堡是什么地方","裂蹄堡背景","裂蹄堡简介"}},["8bfe11a3"]={q="裂蹄堡危险吗？",a="裂蹄堡对外来者来说极其危险。这里是好战的加拉克半人马的重要据点，他们严密守卫着自己的洞穴、战团，以及深藏其中的永恒圣焰，不容任何人擅闯。",al={"裂蹄堡危险吗","裂蹄堡的危险","裂蹄堡的威胁"}}},fp="14,140,17.250.0,16.218.0,32.150.0,28.127.0,24.168.0"}
P.entries["subzone:stagalbog"] = {n="雄鹿沼泽",s="雄鹿沼泽是一片茂密、积水的沼泽地，横跨悲伤沼泽的南部区域。它毗邻泪水之池下方的南部山脉，是一片未开化的荒野。",h="雄鹿沼泽是一片茂密、积水的沼泽地，横跨悲伤沼泽的南部区域。它毗邻泪水之池下方的南部山脉，是一片未开化的荒野。",kw={"沼泽","泪水之池","雄鹿沼泽","雄鹿沼泽洞穴","悲伤沼泽"},ang={["class:Hunter"]="沼泽水域和山崖之间安静的区域使雄鹿沼泽成为了本地沼泽野兽绝佳的潜行狩猎场。",["profession:Herbalism"]="雄鹿沼泽潮湿且缺乏阳光的根系为那些远离人迹的沼泽植物提供了绝佳的生长条件。"},sec={{t="南部泥沼",b="雄鹿沼泽延伸在南部山崖的阴影之下，具有悲伤沼泽的典型特征：死水、低垂的芦苇和纠结的植被。它位于阿塔哈卡神庙沉没遗迹的正南方，夹在受污染的湖泊和该地区的岩石边界之间。除了粗野的野生动物外，这里没有文明的立足之地。"},{t="神庙之影",b="因为与泪水之池接壤，雄鹿沼泽经常受到从沉没的神庙中渗透出来的阴影或腐化的影响。"}},faq={{q="雄鹿沼泽位于哪里？",a="雄鹿沼泽位于悲伤沼泽的南部，直接坐落在泪水之池的南面，沿着南部山脉的基部延伸。",al={"雄鹿沼泽位置","雄鹿沼泽在哪里","如何找到雄鹿沼泽"}},{q="在沼泽中漫游着什么威胁？",a="沼泽中栖息着当地的沼泽野兽和掠食性生物。",al={"雄鹿沼泽怪物","雄鹿沼泽里的怪物"}}},fp="9,104,17.283.0,20.105.0,31.131.0,44.57.0"}
P.entries["subzone:stagalbog-cave"] = {n="雄鹿沼泽洞穴",s="雄鹿沼泽洞穴是一个潮湿的地下洞穴，坐落于悲伤沼泽东部的雄鹿沼泽内。它不仅是沼泽鱼人的据点，也是他们邪恶的精神领袖——沼泽语者的巢穴。",h="雄鹿沼泽洞穴是一个潮湿的地下洞穴，坐落于悲伤沼泽东部的雄鹿沼泽内。它不仅是沼泽鱼人的据点，也是他们邪恶的精神领袖——沼泽语者的巢穴。",kw={"沼泽鱼人","鱼人巢穴","雄鹿沼泽","雄鹿沼泽洞穴","悲伤沼泽","沼泽语者"},sec={{t="沼泽部族的巢穴",b="雄鹿沼泽洞穴隐藏在悲伤沼泽阴暗的东部湿地中，为当地的鱼人提供了躲避沼泽连绵阴雨的庇护所。这些被称为“沼泽部族”的两栖生物，与他们的首席秘术师——沼泽语者一道，凶猛地守卫着蜿蜒的洞穴深处。冒险者在靠近雄鹿沼泽那片沉陷的泥沼时，经常能听到鱼人咕噜咕噜的叫声在长满青苔的河岸间回荡，以此警告外来者远离他们的筑巢地。"}},faq={{q="雄鹿沼泽洞穴是什么？",a="雄鹿沼泽洞穴是一个位于悲伤沼泽东部雄鹿沼泽内的天然洞穴。这里主要被一群凶残的沼泽鱼人占据。",al={"雄鹿沼泽洞穴在哪里","雄鹿沼泽洞穴里有什么"}},{q="谁统治着这个洞穴？",a="这个洞穴由沼泽部族及其领袖沼泽语者所统治，沼泽语者是一位极具影响力的鱼人秘术师，负责监督该部族在潮湿洞穴内部的仪式与防御。",al={"雄鹿沼泽首领","沼泽语者","谁在这里领导鱼人"}},{q="附近有友好的定居点吗？",a="洞穴周围全是狂野而充满敌意的沼泽地。距离最近的友好定居点（至少对部落而言）是位于西部的斯通纳德前哨站。",al={"最近的城镇","雄鹿沼泽附近的商人"}}},fp="14,78,22.301.0,23.111.0,19.130.0,38.109.0"}
P.entries["subzone:staghelm-point"] = {n="鹿盔岗哨",s="鹿盔岗哨是一座古老的暗夜精灵瞭望塔，坐落在希利苏斯东北部的一座崎岖山峰之巅。这座塔俯瞰着不断逼近的沙丘和附近的暮光小径洞穴，作为一道守望防线，警惕着徘徊在沙漠中的古老威胁。",h="鹿盔岗哨是一座古老的暗夜精灵瞭望塔，坐落在希利苏斯东北部的一座崎岖山峰之巅。这座塔俯瞰着不断逼近的沙丘和附近的暮光小径洞穴，作为一道守望防线，警惕着徘徊在沙漠中的古老威胁。",kw={"青铜龙","范达尔·鹿盔","拉洛珊","希利苏斯","鹿盔岗哨","暮光小径","瞭望塔"},ang={["class:Druid"]="这座塔冠以鹿盔之名，提供了一个沉思的视角，俯瞰着这片破坏自然平衡、荒凉腐化的荒野。",["race:NightElf"]="鹿盔岗哨唤起了关于流沙之战的庄严历史，作为卡多雷为阻挡希利苏斯地下的恐怖而付出沉重牺牲的鲜明提醒，屹立不倒。"},sec={{t="沙海之上的静默守望",b="鹿盔岗哨高耸于希利苏斯东北部的干旱平原之上，塔顶是一座孤零零的暗夜精灵塔楼。这个哨所像是一个孤独的卫兵，守护着这片荒原，并监视着潜伏在附近洞穴（如暮光小径）中的邪教徒。永恒守望者拉洛珊镇守于此，头顶还有一只青铜龙盘旋巡逻。这座塔承载着鹿盔家族那引以为傲却又充满悲剧色彩的名字——这是为了纪念卡多雷在古代流沙之战中所做出的巨大牺牲。"}},faq={{q="谁居住在鹿盔岗哨？",a="这座孤塔由永恒守望者拉洛珊守护，而一只来自诺兹多姆的子嗣的雄伟青铜龙则在塔顶上空进行永恒的巡逻。",al={"谁在鹿盔岗哨","鹿盔岗哨角色","拉洛珊"}},{q="附近有什么威胁？",a="沿着蜿蜒小路从山峰而下，就是暮光小径，那里的洞穴和周围营地里爬满了暮光之锤教派的狂热信徒。",al={"鹿盔岗哨危险","附近的敌人","暮光小径"}}},fp="14,190,30.392.0,28.114.0,24.138.0"}
P.entries["subzone:stagnant-oasis"] = {n="死水绿洲",s="死水绿洲是坐落在贫瘠之地干旱中心的一片珍贵水域，位于黄金之路和商旅海岸之间。这里环绕着茂密的棕榈树，并有科卡尔半人马在此争夺，其浑浊的水域和周边的海岸支撑着独特的当地野生生物，包括鳄鱼和游荡的科多兽。",h="死水绿洲是坐落在贫瘠之地干旱中心的一片珍贵水域，位于黄金之路和商旅海岸之间。这里环绕着茂密的棕榈树，并有科卡尔半人马在此争夺，其浑浊的水域和周边的海岸支撑着独特的当地野生生物，包括鳄鱼和游荡的科多兽。",kw={"贫瘠之地","半人马","变异鱼","黄金之路","科多兽","科卡尔","鳄鱼","死水绿洲"},ang={["faction:Horde"]="对于往返于十字路口和陶拉祖之间的部落信使和侦察兵来说，绿洲上的半人马营地对黄金之路的补给运输构成了持续的威胁。",["profession:Cooking"]="死水绿洲的水域盛产稀有的变异鱼，这是烹制美味风蛇的重要配料。"},sec={{t="干旱中的浑浊避风港",b="死水绿洲隐藏在黄金之路以东、商旅海岸的内陆地带，在贫瘠之地尘土飞扬的灌木丛中提供了一片宝贵的绿色。和邻近的水域一样，这片水塘支撑着茂密的植被和好斗的鳄鱼，而虚弱的贫瘠之地科多兽经常远离巨人旷野庞大的兽群，徘徊到这里。然而，旅行者必须小心谨慎：科卡尔半人马在岸边设有营地，他们凶猛地守卫着水源，对抗任何闯入其领地的外来者。"},{t="奇异的水域",b="尽管外观上看来死气沉沉，但这片水塘中却充满了不同寻常的水生生物，包括像变异鱼这样奇异的变异物种。学者和萨满祭司一直密切关注着贫瘠之地的绿洲，研究那些影响当地泉源以及饮用泉水的野生生物的奇特力量。"}},faq={{q="死水绿洲位于哪里？",a="死水绿洲位于贫瘠之地的中南部地带，处于黄金之路以东，商旅海岸沿线的悬崖以西。",al={"死水绿洲位置","死水绿洲在哪里","如何找到死水绿洲"}},{q="谁控制着死水绿洲？",a="游牧的科卡尔半人马在水塘周边建立了营地。除了半人马，还有诸如绿洲鳄鱼和落单、游荡的科多兽等危险野兽在周围的绿地中徘徊。",al={"谁住在死水绿洲","死水绿洲半人马","死水绿洲的敌人"}},{q="为什么这里的科多兽更容易狩猎？",a="与在南面巨人旷野发现的庞大、协作的兽群不同，死水绿洲附近的科多兽通常是落单的，而且往往身体虚弱或迷失了方向，这使它们成了猎人和旅行者眼中更容易捕捉的猎物。",al={"迷失的贫瘠之地科多兽","死水绿洲科多兽","狩猎贫瘠之地科多兽"}},{q="在这片水塘里能钓到什么样的鱼？",a="垂钓者可以从这片浑浊的水塘中钓到变异鱼，这是一种独特的渔获，可以烹制成在整个卡利姆多都备受推崇的美味佳肴。",al={"死水绿洲垂钓","死水绿洲变异鱼","在死水绿洲钓鱼"}},{q="萨尔在长征期间曾造访过这座绿洲吗？",a="没有记录能证实这一点。死水绿洲可能是萨尔和新抵达的部落在与凯恩·血蹄一起穿越贫瘠之地时所占领的三处水源之一。",al={"萨尔死水绿洲","长征绿洲","魔兽争霸3绿洲"}}},fp="14,157,28.377.0,14.268.0,36.127.0,32.118.0,38.197.0,44.112.0,50.210.0"}
P.entries["subzone:starbreeze-village"] = {n="星风村",s="星风村是位于泰达希尔，多兰纳尔以东的一处被遗弃的暗夜精灵定居点。这里曾经是一片宁静的林地村落，但最近却沦陷在陷入疯狂的瘤背部族熊怪手中。这座废弃的定居点现在已成为正在渗透进世界之树根部的腐蚀力量的鲜明象征。",h="星风村是位于泰达希尔，多兰纳尔以东的一处被遗弃的暗夜精灵定居点。这里曾经是一片宁静的林地村落，但最近却沦陷在陷入疯狂的瘤背部族熊怪手中。这座废弃的定居点现在已成为正在渗透进世界之树根部的腐蚀力量的鲜明象征。",kw={"多兰纳尔","菲罗斯塔","熊怪","瘤背","星风村","泰达希尔","乌鲁森","村庄"},ang={["class:Druid"]="瘤背熊怪所遭受的疯狂以及星风村的遭践踏，直接挑战了塞纳里奥议会恢复泰达希尔野生动植物平衡的职责。",["race:NightElf"]="看到一个距离多兰纳尔如此之近的精灵定居点沦为废墟，痛苦地提醒着人们泰达希尔岌岌可危的状态以及正在啃噬世界之树的腐蚀力量。"},sec={{t="沦陷的村落",b="星风村位于幽影谷东南方，距离多兰纳尔不远，这里曾是居住在泰达希尔枝叶下的暗夜精灵家庭的安宁家园。如今，村庄已是一片废墟，木质建筑被极具攻击性的瘤背熊怪占领。这些野兽般的生物受到折磨世界之树枝叶的邪恶腐蚀力量的影响而变得狂暴，它们驱逐了精灵居民，现在正凶猛地守卫着这片废墟。"},{t="菲罗斯塔的威胁",b="瘤背部族在村中的存在不仅仅是一次普通的领地掠夺。徘徊在定居点边缘的是梦境吞噬者菲罗斯塔，一个神秘的、堕落的实体，它的存在表明某种黑暗而邪恶的魔法正在积极地驱使熊怪走向疯狂。连同像乌鲁森这样在道路上潜行的庞大野兽，这些入侵者使星风村成为了泰达希尔东部旅行者的一个重大威胁。"}},faq={{q="星风村为什么会被废弃？",a="当瘤背熊怪成为泰达希尔内部蔓延的腐蚀力量的牺牲品时，村庄便沦陷了。陷入疯狂和暴力的熊怪袭击了这里的暗夜精灵居民，迫使他们逃离并放弃了家园。",al={"星风村发生了什么","为什么星风村是一片废墟","星风村是空的吗"}},{q="现在谁居住在星风村？",a="充满敌意的瘤背熊怪现在占据了村庄。其中比较突出的人物包括游荡的巡逻者乌鲁森以及被称为梦境吞噬者菲罗斯塔的堕落者。",al={"谁在星风村","星风村的怪物","谁占领了星风村"}},{q="星风村在哪里？",a="星风村位于泰达希尔东部，在幽影谷的东南方，多兰纳尔的东方。",al={"星风村在哪里","星风村地图位置","如何找到星风村"}},{q="梦境吞噬者菲罗斯塔是谁？",a="菲罗斯塔是一个危险的堕落生物，出现在星风村边缘，与驱使当地瘤背部族陷入疯狂的黑暗力量有关。",al={"菲罗斯塔背景故事","菲罗斯塔是谁","菲罗斯塔 星风村"}}},fp="18,186,15.371.0,23.352.1,36.198.0,36.144.0,36.92.0,33.197.0"}
P.entries["subzone:starfall-village"] = {n="坠星村",s="坠星村是一处坐落在冬泉谷雪路旁的宁静暗夜精灵避难所。作为这片冰封山谷中唯一的联盟前哨站，它为在严寒中跋涉的旅行者提供了庇护与补给。它也时刻守护着附近的一处兽穴。",h="坠星村是一处坐落在冬泉谷雪路旁的宁静暗夜精灵避难所。作为这片冰封山谷中唯一的联盟前哨站，它为在严寒中跋涉的旅行者提供了庇护与补给。它也时刻守护着附近的一处兽穴。",kw={"联盟","暗夜精灵","坠星","坠星村","冬泉谷"},ang={["faction:Alliance"]="作为冬泉谷内唯一的联盟定居点，坠星村在这一荒凉险峻的高地中提供了必要的休憩、贸易物资和指路服务。",["race:NightElf"]="对于暗夜精灵而言，坠星村是一处重要的北方前哨站，矗立在一处安静、空置的兽穴旁。"},sec={{t="冰雪中的联盟避难所",b="坠星村位于地精贸易站永望镇的西北方、霜刀石的南面，是冬泉谷中联盟文明的唯一堡垒。该定居点由传统的暗夜精灵木屋组成，为过路人提供了一个休憩之所，在恶劣的山区环境中提供关键补给和温暖的炉火。尽管外观平静，但该村庄始终保持警惕，其位置毗邻着一处安静且无人居住的兽穴。"}},faq={{q="坠星村是什么地方？",a="坠星村是冬泉谷内的一处暗夜精灵飞地。它作为联盟在山谷中的主要避难所和补给营地，为前往霜刀石或调查附近兽穴的侦察兵提供食宿、贸易和指引。",al={"坠星","坠星镇","这里是什么地方"}},{q="部落玩家可以使用坠星村的设施吗？",a="不能。坠星村严格效忠于暗夜精灵和联盟。误闯此地的部落旅行者将会遭到当地守卫的敌对攻击。",al={"坠星村对部落友好吗","部落可以使用坠星村吗","坠星村部落"}},{q="村庄旁边的兽穴是什么？",a="村庄正后方的洞穴是一处空置的兽穴。此类圣所通常供德鲁伊在精神漫游翡翠梦境时栖身，但目前并没有德鲁伊在此沉睡。",al={"坠星兽穴","坠星旁的洞穴"}},{q="坠星村位于何处？",a="村庄坐落在穿越冬泉谷的主干雪道旁，位于地精定居点永望镇的西北方，霜刀石的南面。",al={"坠星位置","如何前往坠星","坠星在哪里"}}},fp="16,181,30.289.0,25.218.0,56.135.0,43.174.0,34.120.0"}
P.entries["subzone:steamwheedle-port"] = {n="热砂港",s="热砂港是位于塔纳利斯东海岸的一个繁忙的沿海前哨站，直接与加基森相连。它由中立的热砂港运作，是跨越南海的重要海上枢纽，同时时刻防范着不断侵扰的南海海盗。",h="热砂港是位于塔纳利斯东海岸的一个繁忙的沿海前哨站，直接与加基森相连。它由中立的热砂港运作，是跨越南海的重要海上枢纽，同时时刻防范着不断侵扰的南海海盗。",kw={"加基森港口","落帆海湾","南海海盗","热砂港","塔纳利斯码头","叶基亚"},ang={["class:Rogue"]="地精商人和附近的南海海盗之间不断的摩擦，为扒手、侦察兵和回收契约创造了有利可图的机会。",["profession:Engineering"]="该港口是一个宝贵的仓库，存放着从南海各地进口的零件和补给品，使其成为了修补匠们打听八卦和获取蓝图的天然中心。"},sec={{t="流沙之上的门户",b="热砂港坐落在南海沿岸的沙丘旁，为内陆沙漠城市加基森提供了通往海上贸易的直接生命线。这座定居点由热砂港管理，码头工人、商人和不畏艰险的海上船长往来其中，热闹非凡。补给船定期往返于此地和遥远的地精贸易站之间，将贵重的机械零件、奢侈品和原材料运往南卡利姆多。"},{t="海盗与古怪的学者",b="港口的生活绝非平静。沿着海岸向南走便是落帆海湾，那里盘踞着猖獗的南海自由海盗，他们经常洗劫地精货船、窃取货物并争夺海岸线的控制权。除了讨价还价的码头工人和试图追回失窃货物的多疑商人，港口还接待着一些不寻常的游客，比如神秘的巨魔叶基亚，他正在远离窥视的目光，研究着世界上古老而又不祥的灵魂。"}},faq={{q="谁控制着热砂港？",a="该定居点由热砂港建造并管理，这是中立地精的主要贸易集团。只要你与加基森和该财团保持良好的声望，联盟和部落的旅行者都会受到自由欢迎。",al={"谁经营热砂港","热砂港阵营","热砂港是否友好"}},{q="从这个港口出发的船只前往哪里？",a="该港口是热砂港跨越南海的海上联络点，将其与遥远的地精贸易中心相连，一艘客船会从这里的码头出发，横渡大海前往河林的爆破引线港。",al={"热砂港的船去哪","热砂港渡船"}},{q="为什么附近有这么多海盗？",a="南海自由海盗在南面的落帆海湾建立了基地。他们经常劫持进港货物、抢劫码头补给并袭击海岸线上的掉队者，这使他们成为当地地精贸易的主要威胁。",al={"落帆海湾海盗","塔纳利斯南海海盗"}},{q="叶基亚是谁？",a="叶基亚是一位在港口歇息的古怪巨魔学者。他招募勇敢的冒险者前往远方，捕捉诸如来自菲拉斯的尖啸者之类的灵魂精华，以研究被遗忘的原始仪式。",al={"叶基亚的目的","热砂港的巨魔"}}},fp="17,208,31.354.0,28.375.0,31.206.0,41.189.0,37.231.0,17.221.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="钢架补给站",s="钢架补给站是一座繁忙的工程车间与维修站，坐落于丹莫罗卡拉诺斯的正东方。在贝尔丁·钢架及其工匠团队的监管下，它成为了车辆维护、修理补给运输和回收工作的最前线枢纽。",h="钢架补给站是一座繁忙的工程车间与维修站，坐落于丹莫罗卡拉诺斯的正东方。在贝尔丁·钢架及其工匠团队的监管下，它成为了车辆维护、修理补给运输和回收工作的最前线枢纽。",kw={"贝尔丁·钢架","丹莫罗","工程学","卡拉诺斯","钢架","钢架补给站","车间"},ang={["profession:Engineering"]="补给站是一个露天实验室，周围环绕着蒸汽机械和修理用品，这使得它成为了途经丹莫罗的有志工程师们天然的休憩站点。",["race:Gnome"]="流亡的侏儒修理工与他们的矮人东道主紧密合作，经常使用补给站的熔炉和备用零件来维持他们回收的装置正常运转。"},sec={{t="蒸汽与钢铁的堡垒",b="钢架补给站坐落在卡拉诺斯东侧雪路旁，这里终日回荡着金属碰撞的叮当声、蒸汽喷口的嘶嘶声以及实验性引擎的轰鸣声。矮人矿工与古怪的侏儒工程师聚集在此，周围是重型机械、机械步行装置以及从附近矿场运出的成堆矿石。面对丹莫罗持续不断的穴居人骚乱和机械补给短缺，贝尔丁·钢架和他的团队维持着联盟机械的正常运转，成为旅行者在严寒中寻求备件或技术指导不可或缺的落脚点。"}},faq={{q="钢架补给站是什么地方？",a="钢架补给站是位于丹莫罗的一座工程车间和前哨站，就在卡拉诺斯以东的道路旁。它主要服务于矿工、修理工以及负责维护重型机械的现场技术人员。",al={"钢架补给站","这是什么地方"}},{q="谁在管理这个补给站？",a="该补给站由钢架家族管理，主要是贝尔丁·钢架，并与负责维护周边机械和监督采矿作业的矮人及侏儒工匠们共同协作。",al={"谁领导钢架补给站","谁运营钢架补给站","贝尔丁·钢架"}},{q="这里提供什么服务？",a="补给站内设有贸易供应商、维修服务，以及为希望在外出时磨练工程学和采集技能的工匠准备的训练师。",al={"钢架补给站的训练师","我能在这里做什么","钢架补给站的服务"}}},fx={["01d49f70"]={q="钢架补给站危险吗？",a="补给站本身没有直接的危险。钢架补给站是一处安全的矮人作业营地和贸易驿站，坐落在卡拉诺斯以东的积雪道路旁。尽管周围的峭壁和山丘遍布野兽、游荡的穴居人，以及从诺莫瑞根沦陷中逃出的恼人麻风侏儒，补给站本身仍牢牢掌握在联盟手中，由健壮的矿工、工匠和附近的巡山人守护。",al={"钢架补给站危险吗","钢架补给站危险","钢架补给站安全吗"}},["14c76990"]={q="钢架补给站为什么叫这个名字？",a="这处前哨以贝尔丁·钢架的名字命名，他是一位工程大师兼实业家，负责管理这里的运作。贝尔丁与他的工匠同伴在繁忙的卡拉诺斯聚落外建立了这处路边营地，用于维修、组装和测试矮人与侏儒的精妙机械、攻城器械和采矿设备。",al={"为什么叫钢架补给站","钢架是谁","钢架名字由来"}}},fp="18,172,28.373.0,27.173.0,19.162.0,33.137.0"}
P.entries["subzone:stendel-s-pond"] = {n="斯特登的池塘",s="斯特登的池塘是一处位于西部荒野哨兵岭西南方，且可能受到污染的小型水域。它被游荡的豺狼人所环绕，并有附近的坟墓作为标记，尽管存在险恶的隐患，但它仍是这片干旱土地上为数不多的几个淡水垂钓点之一。",h="斯特登的池塘是一处位于西部荒野哨兵岭西南方，且可能受到污染的小型水域。它被游荡的豺狼人所环绕，并有附近的坟墓作为标记，尽管存在险恶的隐患，但它仍是这片干旱土地上为数不多的几个淡水垂钓点之一。",kw={"豺狼人","坟墓","池塘","鼠尾鱼","哨兵岭","斯特登","西部荒野"},ang={["faction:Alliance"]="由于豺狼人营地的存在，这座靠近哨兵岭的池塘成为了民兵组织南部防线上一个不受控制的威胁。",["profession:Cooking"]="从这些浑浊水域中捕获的鼠尾鱼因可用于制作鱼类菜肴而受到厨师们的重视。"},sec={{t="危险的饮水处",b="斯特登的池塘位于哨兵岭西南方一隅，为西部荒野尘土飞扬的平原提供了一处宁静的休憩之所，尽管危险从未远离。豺狼人在泥泞的岸边徘徊，而散落的骸骨和两座孤坟暗示着，无论是池水还是周遭的野兽，对于粗心的旅人来说都是致命的。垂钓者们依然会冒险前往，以获取鼠尾鱼群。"}},faq={{q="斯特登的池塘位于哪里？",a="它位于西部荒野中心地带，哨兵岭的西南方，就在通往南部地区的尘土小径旁。",al={"斯特登的池塘位置","斯特登的池塘在哪里","寻找斯特登的池塘"}},{q="池塘周围潜伏着什么生物？",a="池塘泥泞的岸边有领地意识极强的河爪豺狼人游荡，它们会攻击任何靠近水域的流浪者。",al={"谁住在这里","斯特登的池塘的怪物","斯特登的池塘豺狼人"}},{q="为什么岸边会有骸骨和坟墓？",a="这些骸骨和两座无名坟墓指出了该地区的致命危险。旅人们究竟是沦为了豺狼人的猎物，还是被污浊的池水毒害，至今仍是一个不祥的谜团。",al={"这些坟墓是谁的","为什么有骸骨","池塘边的坟墓"}}},fx={a33fcb3a={q="斯特登的池塘是什么地方？",a="斯特登的池塘是一片宁静的小水域，坐落在西部荒野中部平原上，位于哨兵岭西南方。尽管远看平静，池塘岸边却诉说着这片尘土弥漫之地艰辛而凄惨的故事。",al={"斯特登的池塘是什么","斯特登的池塘概况","关于斯特登的池塘"}},["9e1e18fd"]={q="斯特登的池塘危险吗？",a="是的，对独行的旅人来说，这里远非安全之地。凶猛的豺狼人在水边游荡，让任何靠近的举动都充满危险。此外，岸边散落的骸骨与孤零零的坟墓表明，要么当地的野生动物十分致命，要么这潭死水本身可能污浊不堪，无法饮用。",al={"斯特登的池塘安全吗","斯特登的池塘的危险","斯特登的池塘有多危险"}}},fp="14,88,25.283.0,32.121.0,36.89.0,48.169.0"}
P.entries["subzone:stillwater-pond"] = {n="静水池",s="静水池是一片宁静、死气沉沉的水域，位于提瑞斯法林地布瑞尔的西侧。它曾是洛丹伦的活人孩子钟爱的野餐和游泳地点，如今已沦为一片浑浊的池塘，栖息着骷髅鱼，并有危险的食腐生物徘徊。",h="静水池是一片宁静、死气沉沉的水域，位于提瑞斯法林地布瑞尔的西侧。它曾是洛丹伦的活人孩子钟爱的野餐和游泳地点，如今已沦为一片浑浊的池塘，栖息着骷髅鱼，并有危险的食腐生物徘徊。",kw={"贝恩","澈水湖","布瑞尔","暗犬","骷髅鱼","静水池","提瑞斯法林地"},ang={["class:Hunter"]="池塘周围受到瘟疫感染的野生生物，包括像贝恩这样的狂暴暗犬，使该区域成为了布瑞尔外围巡逻侦察兵的危险狩猎场。",["race:Undead"]="对于那些保留着洛丹伦生活记忆的被遗忘者来说，静水池是一个残酷的提醒，勾起了他们曾在其曾经清澈的岸边野餐和游泳的逝去童年时光。"},sec={{t="荒废的休憩之所",b="在第三次战争和亡灵瘟疫的浩劫之前，静水池曾是提瑞斯法林地居民的一处宁静休憩地。附近村庄的家庭常聚集在它绿草如茵的岸边享用午后野餐，而那些年幼到无法挑战澈水湖危险深度的孩子们，则会在它的浅滩学习游泳。如今，那曾经田园诗般的水域已变得毫无生机，死气沉沉。活人早已绝迹，只留下骷髅鱼在水面下穿梭，漫无目的的亡灵在周围的树林中游荡。"},{t="迷雾中的潜行者",b="尽管与提瑞斯法那些饱受战火的道路和争夺中的农场相比，静水池较为安静，但这里依然暗藏危机。这片浑浊的水域只为林地里受瘟疫感染的野兽提供水源，其中最引人注目的莫过于一只名叫贝恩的凶猛暗犬，它常在岸边潜行。前往布瑞尔途中穿过西部草甸的旅人必须小心谨慎，因为掠食野兽和漫无目的的僵尸经常在水边徘徊。"}},faq={{q="瘟疫爆发前的静水池是什么样的？",a="在人类统治洛丹伦时期，静水池是一处风景优美且深受当地人喜爱的野餐地点。因为它比广阔的澈水湖更浅、更平静，家庭常带年幼的孩子来这里安全地游泳。",al={"静水池历史","静水池用途","提瑞斯法游泳点"}},{q="现在水里还有活物吗？",a="正常的海洋生物并未能在提瑞斯法受到的瘟疫侵蚀中存活下来。在这灰暗的水面下唯一游动的，是天灾军团的腐蚀所留下的被复活的鱼类骷髅残骸。",al={"静水池鱼类","静水池里有什么","静水池生物"}},{q="哪些危险生物在池塘附近游荡？",a="除了在林地游荡的无脑亡灵外，岸边最臭名昭著的威胁是贝恩，这是一只异常强大且好斗的暗犬，它常以粗心大意的旅人为食。",al={"静水池怪物","贝恩是谁","布瑞尔附近的暗犬"}},{q="静水池位于哪里？",a="静水池位于提瑞斯法林地中部，正处于布瑞尔镇的西侧，澈水湖的西南方。",al={"静水池位置","静水池地理位置","如何找到静水池"}}},fp="15,99,16.338.0,20.345.0,48.200.0,42.146.0,46.154.0,33.106.0"}
P.entries["subzone:stonard"] = {n="斯通纳德",s="斯通纳德是部落在悲伤沼泽南部湿地建立的一座防御性前哨站。它始建于第一次战争期间，如今已成为现代部落在东部王国南部的重要立足点，也是监视诅咒之地的观察哨所。",h="斯通纳德是部落在悲伤沼泽南部湿地建立的一座防御性前哨站。它始建于第一次战争期间，如今已成为现代部落在东部王国南部的重要立足点，也是监视诅咒之地的观察哨所。",kw={"黑色沼泽","诅咒之地","大厅","兽人","罗卡德","斯通纳德","悲伤沼泽"},ang={["class:Shaman"]="斯通纳德作为东部王国南部的主要据点而闻名，部落萨满可以在此找到远离卡利姆多的指引与训练。",["faction:Horde"]="斯通纳德是部落在北部的荒芜之地和西部的荆棘谷之间，唯一的防御性锚点。"},sec={{t="第一次战争的遗迹",b="斯通纳德是艾泽拉斯最古老的兽人定居点之一。它是旧部落穿过黑暗之门进入曾经的黑色沼泽时建立的，斯通纳德及其姊妹哨站罗卡德共同构成了入侵者的防线支点。尽管在第二次战争结束后一度荒废并遭到破坏，但萨尔率领的新部落重建了斯通纳德并在此驻军。在传统的兽人大厅和防御工事的拱卫下，这座哨站如今已成为在这片未开化且充满危险的沼泽中，象征部落权威的一座坚实堡垒。"},{t="边境哨站",b="现代斯通纳德既是探险营地，也是集结地。制图师和侦察兵们分散在周围的泥沼中，勘测未知的沼泽地带，监视着当地的敌对野兽、迷失的德莱尼流浪者以及东部的沉没的神庙。至关重要的是，斯通纳德还为部落提供了一个位于破碎的诅咒之地北侧的后勤补给站，确保部落始终能密切关注那扇沉寂的黑暗之门。"}},faq={{q="为什么斯通纳德对部落很重要？",a="斯通纳德为部落在东部王国南部深处提供了一个坚固的军事和后勤枢纽。它使侦察兵能够勘测危险的悲伤沼泽，为进攻附近的沉没的神庙提供了行动基地，并保持着一支靠近诅咒之地的常备驻军。",al={"为什么斯通纳德在这里","斯通纳德的目的","斯通纳德是什么"}},{q="斯通纳德有多古老？",a="它可追溯到第一次战争时期，是艾泽拉斯最早建立的兽人定居点之一。它由旧部落在穿过黑暗之门后不久建立，在第二次战争后一度荒废，后来由萨尔领导的新部落进行了重建。",al={"斯通纳德历史","斯通纳德是何时建造的","谁建立了斯通纳德"}},{q="它的姊妹定居点罗卡德发生了什么事？",a="罗卡德与斯通纳德在第一次战争期间同时建立，这两座姊妹城镇是旧部落在沼泽防线的支点。与新部落重建的斯通纳德不同，自战争结束后，关于罗卡德的命运并无记录。",al={"罗卡德是什么","罗卡德历史","斯通纳德姊妹城镇"}},{q="我可以飞行或直接前往斯通纳德吗？",a="可以。斯通纳德拥有连通大陆的飞行点，连接着卡加斯、烈焰峰、格罗姆高营地、中立港口藏宝海湾，以及河林的洛格玛。",al={"斯通纳德飞行点","如何前往斯通纳德","斯通纳德传送门"}}},fp="7,156,24.389.0,16.331.0,38.272.0,19.181.0,48.209.0,42.126.0"}
P.entries["subzone:stone-cairn-lake"] = {n="石碑湖",s="石碑湖是一片位于艾尔文森林东北部的环形水域。湖中心坐落着一座小岛，上面矗立着英雄哨岗，这是为纪念第一次战争中阵亡者而建立的纪念碑。这里曾是一个平静的沉思之地，如今却因湖岸边充满敌意的鱼人和占据小岛的流亡法师而不再安宁。",h="石碑湖是一片位于艾尔文森林东北部的环形水域。湖中心坐落着一座小岛，上面矗立着英雄哨岗，这是为纪念第一次战争中阵亡者而建立的纪念碑。这里曾是一个平静的沉思之地，如今却因湖岸边充满敌意的鱼人和占据小岛的流亡法师而不再安宁。",kw={"铜矿","艾尔文森林","第一次战争","英雄哨岗","鱼人","流亡法师","石碑湖","纪念之石"},ang={["profession:Mining"]="环绕石碑湖的断崖和丘陵拥有艾尔文森林中最密集的铜矿矿脉之一，这使其成为渴望成为锻造师和工程师的人们的必经之地。",["race:Human"]="中心岛是暴风王国的一处意义深远的纪念地，旨在纪念第一次战争期间王国陷落时牺牲的人们。"},sec={{t="被围困的纪念碑",b="石碑湖的名字源于其中心大岛上耸立的显眼石制纪念碑。这座纪念碑被称为英雄哨岗，是为了纪念在与兽人部落进行的第一次战争中牺牲的大量人类生命而建立的。曾经，家庭和朝圣者可以安全地前往岛上缅怀先烈，凝望着平静水面上的庄严石碑。然而今天，危险的流亡法师直接在纪念碑旁建立了营地，将这个神圣的缅怀之地变成了一处充满敌意的堡垒。"},{t="湖岸",b="环绕着这片环形湖泊的风景优美的湖岸，如今对当地居民和旅行者来说已变得愈发危险。一群极具攻击性的鱼人占据了南岸，沿着水线建造了简陋的棚屋，骚扰着任何靠近的人。除了这些危险之外，环绕湖泊的丘陵和岩层中蕴藏着丰富的矿脉，使得这片区域成为了不惧当地威胁的勘探者和矿工们经常光顾的地方。"}},faq={{q="为什么这里叫石碑湖？",a="湖名取自英雄哨岗，这是一座建在中心岛屿上的石堆纪念碑，旨在纪念第一次战争中牺牲的暴风城士兵和平民。",al={"石碑湖命名","为什么叫石碑湖","地名来源"}},{q="现在是谁占据了中心岛？",a="这座岛屿被流亡法师和叛逆者占领，他们驱逐了普通的朝圣者，并在纪念碑周围建立了防御营地。",al={"岛上的人","岛上的法师","湖上的流亡法师"}},{q="为什么鱼人聚集在水边？",a="当地的一支鱼人部落在南岸的浅滩和河岸定居下来，建造了原始的棚屋，并将这片鱼产丰富的水域据为己有。",al={"石碑湖的鱼人","湖中鱼人","南岸棚屋"}},{q="岛上的纪念碑叫什么名字？",a="这座纪念碑被称为英雄哨岗，其主体是一座通常被称为纪念之石的石堆。",al={"岛上纪念碑名称","纪念碑名称","石碑湖圣坛"}}},fx={a25fa3d9={q="石碑湖是什么地方？",a="石碑湖是一片位于艾尔文森林东北部的环形水域。湖心有一座小岛，岛上矗立着英雄哨岗，这座庄严的纪念碑用以缅怀在第一次兽人战争中逝去的人们。这里曾是旅人与悼念者的宁静去处，如今却已荒芜，危机四伏。",al={"石碑湖是什么","石碑湖信息","石碑湖介绍"}},["9a875c99"]={q="石碑湖危险吗？",a="是的，这里对四处游历的旅人来说相当危险。叛逆的巫师占据了湖心岛，用奥术魔法猛烈抵御来犯者，守卫自己的营地。此外，敌对的鱼人盘踞在浅滩，并在南岸建起了聚落，袭击任何靠近的人。",al={"石碑湖安全吗","石碑湖威胁","石碑湖危险"}},["92ff0cce"]={q="石碑湖为何不再是朝圣之地？",a="石碑湖曾是一处宁静的朝圣之地，民众来到这里，缅怀在第一次兽人战争中阵亡的士兵。然而，随着动乱加剧，暴风城的卫兵无力保障这里的安全，叛逆的施法者趁机占据了纪念碑所在的岛屿，凶恶的鱼人也霸占了湖岸。",al={"石碑湖为何荒废","石碑湖为何破败","石碑湖朝圣"}}},fp="16,163,19.336.0,18.276.0,34.158.0,46.136.0,42.165.0,42.96.0"}
P.entries["subzone:stonebull-lake"] = {n="石牛湖",s="石牛湖是一片宁静的马蹄形水域，环绕着莫高雷中部的血蹄村。它由平原上纯净的自然径流汇聚而成，为在凯恩·血蹄指导下步入成年的牛头人后辈提供了至关重要的淡水、丰富的鱼类资源以及宁静的岸边休憩之所。",h="石牛湖是一片宁静的马蹄形水域，环绕着莫高雷中部的血蹄村。它由平原上纯净的自然径流汇聚而成，为在凯恩·血蹄指导下步入成年的牛头人后辈提供了至关重要的淡水、丰富的鱼类资源以及宁静的岸边休憩之所。",kw={"血蹄村","垂钓","湖泊","莫高雷","石牛湖","雷霆崖"},ang={["race:Tauren"]="对于在莫高雷各地建立家园的牛头人而言，石牛湖提供了温和的滋养，也是在大地母亲的恩赐下，靠近他们首都的一处寄托。"},sec={{t="平原之水",b="石牛湖三面环绕血蹄村，定义了莫高雷中部的地理格局。一座木桥横跨湖面最狭窄处，承载着连接该定居点与北面宏伟的雷霆崖高地之间的主干土路。湖水平静，鱼类繁多，其岸边是休憩的猎人、疲惫的旅者以及在广阔苍穹下学习捕鱼技艺的学徒们所青睐的地方。"}},faq={{q="石牛湖位于哪里？",a="石牛湖位于莫高雷中部。它呈马蹄形环绕着血蹄村，从三面包围着这个定居点。",al={"石牛湖位置","石牛湖在哪里","莫高雷湖泊"}},{q="横跨湖面的桥梁有什么用途？",a="这座桥横跨石牛湖最狭窄的部分，承载着连接血蹄村与北方雷霆崖的主要道路。",al={"石牛湖之桥","血蹄村附近的桥","跨越石牛湖的道路"}},{q="为什么石牛湖对牛头人很重要？",a="该湖泊是血蹄村居民不可或缺的淡水来源和重要的捕鱼点。对于在莫高雷中部进行训练的年轻牛头人勇士来说，它也是一处沉思与聚会的宁静之地。",al={"为什么石牛湖很重要","石牛湖的用途"}}},fp="14,78,19.385.0,32.88.0,44.143.0,46.150.0"}
P.entries["subzone:stonefield-farm"] = {n="斯通菲尔德农场",s="斯通菲尔德农场是一处坐落在艾尔文森林南部的农庄。这里居住着斯通菲尔德家族，他们与邻居马科伦家族长期陷入激烈的世仇之中。",h="斯通菲尔德农场是一处坐落在艾尔文森林南部的农庄。这里居住着斯通菲尔德家族，他们与邻居马科伦家族长期陷入激烈的世仇之中。",kw={"艾尔文森林","米莱德·斯通菲尔德","马科伦","斯通菲尔德","斯通菲尔德农场","托米·乔"},ang={["race:Human"]="对于从北郡出发的人类新手来说，斯通菲尔德家族和马科伦家族之间的争吵，让人在土匪和豺狼人的威胁之外，得以轻松地一窥王国农村的生活。"},sec={{t="苦涩的家园",b="斯通菲尔德农场坐落在闪金镇以南的青葱丘陵之中，在为王国生产农作物的同时，也一直与附近的马科伦农场保持着长达数十年的深仇大恨。两家之间的积怨导致了琐碎的争吵、互相指责偷窃以及持续的紧张局势。然而，在这敌对的争执之下，年轻的托米·乔·斯通菲尔德却暗中爱上了梅贝尔·马科伦，这段安静的恋情要么能弥合两大家族之间的裂痕，要么会引发更激烈的愤怒。"}},faq={{q="斯通菲尔德家族和马科伦家族之间的世仇是什么？",a="斯通菲尔德家族和马科伦家族在艾尔文森林南部有着长期且顽固的竞争关系。他们不断指责对方擅自闯入、小偷小摸以及各种不当行为，甚至在简单的邻里事务上也拒绝合作。",al={"斯通菲尔德与马科伦的世仇","斯通菲尔德家族为何争斗","斯通菲尔德的竞争对手"}},{q="谁住在斯通菲尔德农场？",a="这座农场由斯通菲尔德家族经营，其中包括米莱德·斯通菲尔德、斯通菲尔德妈妈和年轻的托米·乔·斯通菲尔德。",al={"斯通菲尔德非玩家角色","谁在斯通菲尔德农场"}},{q="托米·乔·斯通菲尔德有什么秘密？",a="尽管两家之间存在着激烈的敌意，托米·乔·斯通菲尔德还是暗中爱上了梅贝尔·马科伦。这两位恋人依靠富有同情心的旅行者来传递信息和礼物，以免被家人发现。",al={"托米·乔的秘密","托米·乔的恋情","斯通菲尔德的爱情"}}},fx={["60255a1c"]={q="斯通菲尔德农场是什么地方？",a="斯通菲尔德农场是一处位于艾尔文森林南部的幽静农庄，由斯通菲尔德家族耕作打理。它看起来只是一座为当地出产作物的普通农庄，却因与邻近的马科伦农场长期激烈不和而闻名整个山谷。来访者常常会被卷入家庭争吵、传家宝失踪引发的纠纷，以及年轻一辈的秘密恋情。",al={"斯通菲尔德农场是什么","艾尔文斯通菲尔德农场","斯通菲尔德农场介绍"}},["45c8f9cb"]={q="斯通菲尔德农场危险吗？",a="农庄本身由家族打理，通常很安全，但周围的田野却是另一番景象。和艾尔文森林南部的大部分地区一样，野兽在外围游荡，当地的强盗和不断侵入的害兽也时常威胁牲畜与庄稼。旅人在进入牧场，或向附近的河岸和果园行进时，应随时备好武器。",al={"斯通菲尔德农场危险吗","斯通菲尔德农场的威胁","斯通菲尔德农场敌人"}}},fp="15,115,18.319.0,58.210.0,29.114.0,38.207.0"}
P.entries["subzone:stonefire-tavern"] = {n="Stonefire Tavern",s="石火旅店是铁炉堡这座山中之城主要的旅店，为往来的旅人提供服务。它坐落在城市大门以北熙熙攘攘的平民区，提供温暖的炉火、烈性的矮人麦酒，以及让来自卡兹莫丹各地的冒险者休憩的场所。",h="石火旅店是铁炉堡这座山中之城主要的旅店，为往来的旅人提供服务。它坐落在城市大门以北熙熙攘攘的平民区，提供温暖的炉火、烈性的矮人麦酒，以及让来自卡兹莫丹各地的冒险者休憩的场所。",kw={"平民区","矮人旅店","吉温娜·火酒","旅店老板洛雷·火酒","铁炉堡","卡兹莫丹","石火旅店"},ang={["faction:Alliance"]="作为距离铁炉堡正门最近的主要旅店，石火往往是到访这座矮人首都的联盟旅行者的中心集结地。",["race:Dwarf"]="对于从卡兹莫丹各地远征归来的矮人们来说，石火旅店是他们在首都里喝上一品脱冰镇火酒并打听当地消息的首选之地。"},sec={{t="平民区中心",b="石火旅店位于平民区要塞大门的北侧，是铁炉堡首屈一指的酒馆。这里由旅店老板洛雷·火酒与其女儿Gwenna共同经营，为疲惫的旅人提供热腾腾的饭菜、当地酿造的酒水以及山底下的住处。无论你是为了躲避丹莫罗严酷的山区风雪，还是在深入城市之前寻找交换情报和补给的场所，来自联盟各地的旅行者都会聚集在这里的炉火旁。"}},faq={{q="石火旅店位于哪里？",a="这家旅店位于铁炉堡的平民区，穿过主城大门向北走一小段路即可到达。",al={"石火旅店位置","铁炉堡旅店位置","石火在哪里"}},{q="谁在经营石火旅店？",a="这家旅店由旅店老板洛雷·火酒在女儿吉温娜·火酒的协助下共同管理。",al={"谁经营石火旅店","石火旅店老板","火酒旅店"}},{q="旅行者可以在这里绑定炉石吗？",a="是的。旅店老板洛雷·火酒欢迎那些想把石火旅店作为铁炉堡基地联盟旅行者。",al={"铁炉堡炉石绑定","铁炉堡旅店","石火炉石"}},{q="附近有什么设施？",a="旅店入口外就有一个城市邮箱，周围的平民区里也遍布银行、商人和贸易补给商。",al={"石火服务","石火附近的邮箱"}}},fx={a8df8501={q="石火旅店是什么地方？",a="石火旅店是铁炉堡内主要的聚会场所和旅店之一。它位于城门以北不远处繁华的平民区，为来到这座山中都城的疲惫旅人、士兵和访客提供温暖的炉火、浓烈的矮人佳酿，以及舒适宜人的歇脚之所。",al={"石火旅店是什么","铁炉堡石火旅店"}},["3314a531"]={q="石火旅店危险吗？",a="一点也不危险。石火旅店坐落在铁炉堡防御森严的腹地，是一处安全而友善的避风港。这里有矮人巡逻队守卫，周围都是联盟同伴，你在此可能遇到的唯一真正危险，就是多喝了几杯火酒家的烈性麦酒。",al={"石火旅店安全吗","石火旅店危险","石火旅店威胁"}}},fp="16,179,20.409.0,38.90.0,34.86.0,43.99.0,26.114.0"}
P.entries["subzone:stonemaul-ruins"] = {n="石槌废墟",s="石槌废墟是石槌村破碎的残骸，这里曾是卡利姆多石槌食人魔引以为傲的定居点。在被黑龙军团驱逐后，该氏族向北逃亡，留下他们曾经的家园被火鬃龙人所占领。",h="石槌废墟是石槌村破碎的残骸，这里曾是卡利姆多石槌食人魔引以为傲的定居点。在被黑龙军团驱逐后，该氏族向北逃亡，留下他们曾经的家园被火鬃龙人所占领。",kw={"蕨墙","黑龙谷","火鬃","考戈尔","莫格穆洛克","石槌","石槌废墟","石槌村"},ang={["faction:Horde"]="石槌食人魔是坚定的盟友，他们曾与萨尔的部落并肩作战，与库尔提拉斯浴血奋战。帮助他们反击黑龙军团是对这份盟约的尊重。"},sec={{t="氏族家园的兴衰",b="石槌食人魔在迁徙到卡利姆多后，于尘泥沼泽阴暗的湿地中建立了他们的定居点。当兽王雷克萨勇闯氏族致命的试炼、击杀残暴的酋长考戈尔，并号召食人魔保卫新生的部落免受库尔提拉斯军队的侵害时，这座村庄声名大噪。战争结束后，雷克萨将指挥权留给了食人魔莫格穆洛克。在莫格穆洛克自私的统治下，村庄逐渐衰落，最终遭到黑龙军团的伏击并被摧毁。幸存的食人魔向北逃亡并建立了蕨墙村，而奥妮克希亚的后裔则完全占据了这些废墟。"},{t="收复家园的斗争",b="如今，这些废墟牢牢地坐落在黑龙谷内，到处爬满了照看附近巢穴的火鬃龙人。虽然莫格穆洛克大王变得胆小懦弱，满足于在蕨墙村苟延残喘，但像萨尔格和德拉兹辛比这样更年长、更自豪的氏族成员却拒绝放弃他们的家园。他们以蕨墙村为据点，敦促部落的勇士们屠杀占领此地的龙人并摧毁龙蛋，希望能有一天石槌食人魔能再次进军并收复他们祖先的村庄。"}},faq={{q="谁曾经住在石槌废墟？",a="石槌食人魔氏族在抵达卡利姆多后，建造并居住在这个被称为石槌村的定居点。",al={"谁曾住在这里","石槌废墟历史","谁建造了石槌村"}},{q="为什么村庄会被遗弃？",a="奥妮克希亚的黑龙军团袭击了该定居点并驱逐了食人魔，将村庄变成了火鬃龙人的巢穴哨站。",al={"为什么石槌被摧毁","石槌村发生了什么","谁袭击了石槌"}},{q="幸存的食人魔去了哪里？",a="幸存者在莫格穆洛克大王的带领下向北撤退到尘泥沼泽，并将蕨墙村作为他们临时的据点。",al={"食人魔现在在哪里","石槌食人魔所在地"}},{q="雷克萨与这个地方有什么联系？",a="雷克萨来到这里是为了招募食人魔对抗库尔提拉斯。他通过了他们的试炼，在战斗中击杀了暴君考戈尔，并曾短暂担任酋长，随后将领导权交给了莫格穆洛克。",al={"雷克萨与石槌","雷克萨与食人魔酋长"}},{q="食人魔计划夺回废墟吗？",a="是的。虽然莫格穆洛克不敢采取行动，但萨尔格和德拉兹辛比等其他石槌领袖积极招募部落的冒险者来清除火鬃龙人，为夺回家园做准备。",al={"食人魔会回去吗","收复石槌"}}},fp="15,172,30.542.0,28.442.0,36.114.0,30.134.0,33.105.0,43.178.0,38.171.0"}
P.entries["subzone:stonesplinter-valley"] = {n="碎石怪之谷",s="碎石怪之谷是位于洛克莫丹西南部的一处崎岖山谷，那里充斥着充满敌意的穴居人。它曾经是一片原始的高山空地，如今在穴居人首领格拉姆格的残暴统治下，已经变成了一座设防营地。",h="碎石怪之谷是位于洛克莫丹西南部的一处崎岖山谷，那里充斥着充满敌意的穴居人。它曾经是一片原始的高山空地，如今在穴居人首领格拉姆格的残暴统治下，已经变成了一座设防营地。",kw={"格拉姆格","洛克莫丹","碎石怪","碎石怪之谷","塞尔萨玛","穴居人"},ang={["faction:Alliance"]="清理碎石怪之谷可以确保穿过洛克莫丹的重要补给路线安全，在铁炉堡的兵力分散在各地的情况下，这些路线已经变得十分脆弱。",["race:Dwarf"]="这里的穴居人泛滥是对洛克莫丹安全的一种侮辱，塞尔萨玛的山地探险队员们指望着勇敢的矮人同胞能清除掉格拉姆格手下那些不断扩张的野蛮生物。"},sec={{t="嘶鸣的要塞",b="碎石怪之谷坐落在洛克莫丹西南部崎岖的山坡之间，曾经是一片宁静的高山空地。当成群结队的地下穴居人从卡兹莫丹各地挖掘通道来到地表时，这份宁静便荡然无存。碎石怪部族将这座山谷占为己有，迅速将岩石峡谷变成了粗陋的防御工事，挖掘洞穴、竖起路障，并猎杀任何靠近的生物。他们的人数使这座山谷成为了洛克莫丹南部道路上的一道伤疤，迫使塞尔萨玛的山地探险队员不得不雇佣愿意消灭这些穴居人并除掉他们那高大的军阀格拉姆格的冒险佣兵。"}},faq={{q="碎石怪之谷位于哪里？",a="它位于洛克莫丹西南角的群山之中，就在经过灰爪山的主干道南侧。",al={"碎石怪之谷位置","碎石怪之谷在哪里","洛克莫丹穴居人山谷"}},{q="谁统治着碎石怪之谷？",a="这座营地由一名残暴的穴居人首领格拉姆格所统治，他从山谷的最深处指挥该部族对当地的旅行者和巡逻队进行袭击。",al={"谁领导碎石怪穴居人","格拉姆格","洛克莫丹穴居人首领"}},{q="为什么穴居人会来到洛克莫丹？",a="穴居人是在矮人于卡兹莫丹其他地区进行挖掘时从地下深处被发掘出来的。在无脑攻击性的驱使下，不同的战帮迁移到了地表，而碎石怪部族选择了这片偏僻的山谷作为他们的主要集结地。",al={"为什么洛克莫丹有穴居人","穴居人从哪里来","洛克莫丹穴居人起源"}},{q="为什么矮人想要清理这座山谷？",a="山谷距离矮人的定居点、矿井和山路非常近，构成了严重的威胁。放任一支根深蒂固的碎石怪穴居人军队不管，不仅威胁着穿过洛克莫丹南部的旅行者的安全，也让本已捉襟见肘的山地探险队巡逻任务倍感压力。",al={"为什么要对抗碎石怪穴居人","塞尔萨玛穴居人问题"}}},fx={c84babb8={q="碎石怪之谷是什么地方？",a="碎石怪之谷是一座位于洛克莫丹西南部的崎岖山谷。这里曾是一片原始的高山景致，如今却被一个庞大的敌对穴居人氏族彻底占据，它们将谷地与山口据为自己的据点。",al={"碎石怪之谷概况","碎石怪之谷是什么","碎石怪之谷介绍"}},["30aeaf73"]={q="碎石怪之谷发生了什么？",a="这片湖区山地盆地中原本未受侵扰的宁静角落，如今成了穴居人的巢穴。碎石氏族在卡兹莫丹各地破土而出后，大举涌入山谷，玷污了这片荒野，并赶走了所有胆敢靠近的人。",al={"碎石怪之谷历史","山谷发生了什么","碎石怪之谷穴居人泛滥"}},["39c06fe2"]={q="碎石怪之谷危险吗？",a="这里极其危险。敌对的碎石穴居人成群盘踞在这片地区，凶狠地抵御外来者，守卫自己的领地。山谷深处潜伏着它们强大的酋长格劳姆格，使任何深入谷地的行动都可能致命。",al={"碎石怪之谷有多危险","碎石怪之谷威胁","碎石怪之谷安全吗"}},["27e6d962"]={q="碎石怪之谷为何得名？",a="山谷直接得名于盘踞并控制此地的碎石穴居人部族。它们在这里根深蒂固的势力，已经彻底改变了周围矮人守军对这片地区的看法。",al={"碎石怪之谷名称由来","为何叫碎石怪之谷","碎石名称起源"}}},fp="20,147,23.542.0,38.121.0,31.146.0,38.231.0,50.220.0"}
P.entries["subzone:stonetalon-peak"] = {n="石爪峰",s="石爪峰是一处隐匿在石爪山脉西北边缘青翠高山峡谷中的古老暗夜精灵圣所。这里是卡多雷的神圣之地，由当地的德鲁伊照看，也是联盟在这些崎岖高地上的主要堡垒。",h="石爪峰是一处隐匿在石爪山脉西北边缘青翠高山峡谷中的古老暗夜精灵圣所。这里是卡多雷的神圣之地，由当地的德鲁伊照看，也是联盟在这些崎岖高地上的主要堡垒。",kw={"吉安娜","卡多雷","暗夜精灵","神谕者","哨兵","石爪","石爪峰","鹰巢","萨尔"},ang={["class:Druid"]="这处圣所与塞纳里奥的历史以及神圣的鹰巢有着深厚的联系，使其成为了荒野守护者们朝圣和防御的关键场所。",["faction:Alliance"]="石爪峰是你在西部山脉中唯一的坚固立足点，在敌对区域内提供关键的休憩地、飞行路线和任务协助。"},sec={{t="神圣的山谷",b="石爪峰高耸于低海拔地区干旱的尘土之上，展开了一片郁郁葱葱、云雾缭绕的圣所。这里自古以来就被视为神圣之地，浸透着古老的魔法，山谷中保留着数千年前的遗迹，那时该地区还坐落着在大分裂之前供奉艾萨拉女王的神庙。在现代，卡多雷哨兵和德鲁伊在此恢复了有序且和平的治理，维护着这片宁静的避难所，这里不仅有一处林精巢穴，还有一个重要的联盟飞行点。"},{t="命运的十字路口",b="除了田园诗般的森林和古老的遗迹外，石爪峰还因第三次战争而具有历史意义。在麦迪文预言的指引下，Jaina Proudmoore的人类远征军和萨尔的部落都攀登上了这片危险的高地，寻找隐居在深山洞穴中的神谕者。那次决定性的相遇迫使宿敌放下了手中的利刃，为在海加尔山共同抵御燃烧军团的艰难契约奠定了基础。如今，这里依然牢牢掌握在哨兵手中，尽管低地部落的入侵让守卫们时刻保持警惕。"}},faq={{q="为什么石爪峰相比周围的山脉如此翠绿？",a="石爪峰坐落在一个受保护的高海拔盆地中，充满了古老的魔法。通过暗夜精灵和附近鹰巢德鲁伊的精心照料，这里得以保留了一片充满生机的森林圣所，茂密的植被与下方焦黑、嶙峋的悬崖形成了鲜明的对比。",al={"为什么石爪峰是绿色的","为什么石爪峰会有森林","石爪峰天气"}},{q="第三次战争期间这里发生了什么？",a="在先知麦迪文的预言警告引导下，吉安娜·普罗德摩尔和萨尔都来到了石爪峰，寻找山洞中的神谕者。他们在深山中的会面促使双方达成了历史性的休战，让联盟与部落联合起来对抗燃烧军团。",al={"石爪峰发生了什么魔兽争霸3","吉安娜和萨尔石爪","神谕者石爪"}},{q="现在是谁控制着石爪峰？",a="该山峰是一处联盟哨站，由暗夜精灵哨兵和德鲁伊保护和维护。它是联盟冒险者在石爪山脉活动时的主要避风港、任务中心和飞行管理员所在地。",al={"石爪峰是联盟还是部落","谁住在石爪峰","石爪峰阵营"}},{q="这里有哪些古老遗迹？",a="散布在峡谷中的断壁残垣和大理石建筑是古老暗夜精灵帝国的遗迹，在大分裂和艾萨拉女王堕落之前，这里曾是供奉她的神庙。",al={"石爪峰遗迹","古老神庙石爪","艾萨拉神庙石爪峰"}}},fp="15,193,22.291.0,21.430.0,70.183.0,40.232.0,39.189.0,36.216.0"}
P.entries["subzone:stonewatch"] = {n="石堡",s="石堡是位于赤脊山中心的一座坚固堡垒，旨在保护周边人类土地免受北方入侵。这座堡垒曾由暴风城的士兵驻守，如今已沦陷并处于黑石兽人的残酷控制之下，对附近的湖畔镇构成了直接威胁。",h="石堡是位于赤脊山中心的一座坚固堡垒，旨在保护周边人类土地免受北方入侵。这座堡垒曾由暴风城的士兵驻守，如今已沦陷并处于黑石兽人的残酷控制之下，对附近的湖畔镇构成了直接威胁。",kw={"黑石兽人","加塞尔佐格","湖畔镇","摩根斯","赤脊山","石堡","石堡要塞","萨瑞尔祖恩"},ang={["faction:Alliance"]="石堡代表了敌对兽人对联盟核心领土最危险的前沿入侵之一，因此将其收复对于赤脊山的安全至关重要。",["race:Human"]="第12军刀军团的屠杀和要塞的陷落，痛苦地提醒着人们湖畔镇的脆弱和暴风城政治上的漠视。"},sec={{t="沦陷的堡垒",b="石堡坐落在石堡瀑布附近的悬崖之上，由一座坚固的塔楼和要塞组成，旨在守卫来自燃烧平原的通道。这座堡垒最初由湖畔镇的守军把守，后来因背叛者术士摩根斯与黑石氏族结盟而沦陷。在黑暗魔法的加持下，入侵的兽人击溃了当地的人类守军——第12军刀军团，并占领了这座堡垒。尽管摩根斯最终背叛了他的盟友，并带着一支暗皮豺狼人军队撤退到了附近的伊尔加拉之塔，但黑石兽人在督军加塞尔佐格和中尉萨瑞尔祖恩的指挥下，依然牢牢控制着这座要塞。"},{t="对湖畔镇的威胁",b="随着石堡被敌对的兽人牢牢占据，湖畔镇直接处于迫在眉睫的征服威胁之下。由于暴风城贵族议会的冷漠或无能，无法提供实质性的军事增援，所罗门镇长和治安官马瑞斯被迫雇佣佣兵和志愿者。铲除该堡垒的领导层——即同时针对萨瑞尔祖恩和加塞尔佐格——仍然是小镇解除该地区围困的孤注一掷的首要希望。"}},faq={{q="谁现在控制着石堡？",a="石堡目前被黑石氏族的兽人占据，指挥官是督军加塞尔佐格和他的副官萨瑞尔祖恩。他们驱逐了王国的驻军，现在将这座堡垒作为对整个赤脊山发动攻击的基地。",al={"石堡里有什么人","谁控制着石堡","石堡的敌人"}},{q="人类是如何失去石堡的？",a="这座要塞是在黑石氏族的一次协同入侵中陷落的，当时得到了叛变人类术士摩根斯的黑暗魔法支持。他们合力击溃了第12军刀军团的守卫者，占领了整个建筑群。",al={"石堡的陷落","石堡是如何陷落的","石堡背景故事"}},{q="为什么暴风城不派军队将其夺回？",a="暴风城拒绝向边境地区调拨足够的部队，导致所罗门镇长和治安官马瑞斯只能独自防守赤脊山。湖畔镇只能依靠路过的冒险者和雇佣兵来组织对石堡的反击。",al={"为什么没有暴风城的支援","湖畔镇增援"}},{q="石堡和伊尔加拉之塔有什么关系？",a="摩根斯最初协助黑石兽人夺取了石堡，但在胜利后不久，他就背叛了他的盟友。他在附近建造了伊尔加拉之塔，聚集了一群由魔法奴隶和暗皮豺狼人组成的随从，同时攻击兽人和人类。",al={"与伊尔加拉之塔的联系","摩根斯与石堡"}}},fp="10,180,17.525.0,23.399.0,34.189.0,35.179.0,52.219.0,69.224.0"}
P.entries["subzone:stonewatch-falls"] = {n="石堡瀑布",s="石堡瀑布是一处风景秀丽的瀑布和深山水潭，位于赤脊山的东部边缘，由止水湖流出的河水汇聚而成。瀑布从石堡高耸的山崖下倾泻而下，其与世隔绝的水域被一支充满敌意的鱼人部落占据。",h="石堡瀑布是一处风景秀丽的瀑布和深山水潭，位于赤脊山的东部边缘，由止水湖流出的河水汇聚而成。瀑布从石堡高耸的山崖下倾泻而下，其与世隔绝的水域被一支充满敌意的鱼人部落占据。",kw={"止水湖","鱼人","赤脊山","石堡","石堡瀑布","瀑布"},ang={["faction:Alliance"]="位于石堡瀑布的鱼人定居点是又一个危险的怪物据点，它们不断袭扰着本就动荡不安的赤脊山东部地区。"},sec={{t="危险的山中盆地",b="石堡瀑布源自止水湖东侧的河流，沿崎岖的地势奔流而下，直抵黑石兽人要塞石堡之下。倾泻的水流在山脚下冲刷出一个深邃的水潭。尽管这里自然风光绝美，但旅人们很少在此驻足观赏；一群凶残的鱼人盘踞在水潭边，搭建起粗陋的芦苇棚屋，猎杀任何胆敢靠近水边的愚蠢之徒。"}},faq={{q="石堡瀑布的水源来自哪里？",a="瀑布的源头是止水湖东侧流出的河流，河水沿山坡而下，汇入石堡悬崖下的幽静山间盆地。",al={"石堡瀑布从哪里开始","瀑布水源","石堡河流源头"}},{q="石堡瀑布周围生活着哪些生物？",a="一支当地的鱼人部落占据了瀑布的岸边。他们以深山水潭中的鱼类为食，并在河岸边搭建了简陋的窝棚和栖身之所。",al={"石堡瀑布有什么","石堡瀑布的鱼人","瀑布附近的怪物"}},{q="石堡瀑布与石堡要塞有联系吗？",a="瀑布位于石堡及其废弃要塞正下方的山脚处。虽然上方的高地堡垒由黑石兽人把守，但下方的水域盆地则被鱼人控制。",al={"瀑布与要塞的联系","石堡要塞在瀑布附近吗","石堡关系"}}},fp="16,114,25.303.0,53.143.0,44.117.0,49.130.0"}
P.entries["subzone:stonewatch-keep"] = {n="石堡要塞",s="石堡要塞是一座耸立在赤脊山东部的坚固石制堡垒，曾由暴风城王国建造并驻守。它现已被一支入侵的黑石兽人军队攻陷，成为了他们的前线作战基地，这些兽人军阀正以此为据点威胁着湖畔镇。",h="石堡要塞是一座耸立在赤脊山东部的坚固石制堡垒，曾由暴风城王国建造并驻守。它现已被一支入侵的黑石兽人军队攻陷，成为了他们的前线作战基地，这些兽人军阀正以此为据点威胁着湖畔镇。",kw={"黑石氏族","加塞尔佐格","基沙恩","湖畔镇","莫甘斯","赤脊山","石堡要塞","萨瑞尔祖恩"},ang={["faction:Alliance"]="石堡要塞是暴风城边境防线紧张局势的痛苦缩影；清理其城墙上的敌军对于保护脆弱的湖畔镇居民至关重要。",["race:Human"]="人类守军曾为保卫这些城墙流尽鲜血，解放要塞有助于为那些阵亡的士兵和被黑石氏族俘虏的人们复仇。"},sec={{t="沦陷的壁垒",b="石堡要塞最初用于守卫东部山脊，保卫湖畔镇的定居者免受敌对势力的侵扰。当背叛的术士莫甘斯与黑石氏族结盟时，和平被打破了。在黑暗魔法的加持下，兽人发动了极其凶残的突袭，击溃了人类守军并占领了要塞。尽管莫甘斯后来抛弃了他的盟友，转而建立附近的伊尔加拉之塔并奴役当地的豺狼人，但黑石入侵者成功巩固了对石堡的控制，将这座曾经的联盟堡垒改造成了他们进攻山谷的坚固前哨站。"},{t="军阀的王座",b="要塞现已被大量的黑石兽人守军占据，由强大的兽人军阀加塞尔佐格和其残暴的副官萨瑞尔祖恩共同把守。这些指挥官站在石墙之上协调着对赤脊山的突袭，抓捕了包括暴风城的基沙恩下士在内的俘虏。由于王国的军队兵力不足，无法派遣整支军团来解放这座要塞，所罗门镇长和治安官马瑞斯被迫雇佣佣兵勇士潜入堡垒，在湖畔镇彻底沦陷之前铲除这些黑石氏族的领导层。"}},faq={{q="现在是谁占领了石堡要塞？",a="这座要塞目前由黑石氏族占领，由军阀加塞尔佐格及其副官萨瑞尔祖恩现场指挥。在被占领之前，它曾是保卫湖畔镇的联盟据点。",al={"谁控制着石堡要塞","谁住在石堡要塞","石堡要塞的敌人"}},{q="黑石兽人是如何攻占这座要塞的？",a="黑石氏族与背叛的人类术士莫甘斯结盟。在莫甘斯黑暗巫术的加持下，兽人发动了凶猛的突袭，击溃了驻守在石堡的人类守军。",al={"兽人是如何得到石堡的","石堡要塞的陷落","石堡为何陷落"}},{q="为什么暴风城军队不夺回石堡要塞？",a="由于内部政治问题和王国各地的兵力短缺，暴风城军队在很大程度上忽略了赤脊山。因此，湖畔镇的领导人们必须依赖独立的冒险者来应对威胁。",al={"为何没有暴风城军队","守卫在哪里","湖畔镇的军事援助"}},{q="莫甘斯与这座堡垒有什么关联？",a="莫甘斯曾帮助黑石氏族征服了石堡要塞，但在胜利后不久便背叛了他们。他搬去建造了自己的巢穴——伊尔加拉之塔，并利用受过魔法控制的影皮豺狼人而非兽人来为他效力。",al={"莫甘斯与石堡","莫甘斯在石堡要塞里吗"}}},fp="15,222,16.460.0,18.487.0,35.156.0,44.173.0,54.172.0,47.221.0"}
P.entries["subzone:stonewatch-tower"] = {n="石堡高塔",s="石堡高塔是一座屹立在赤脊山东北部被占领的石堡要塞之中的石质岗哨。这座前哨站曾由湖畔镇的守军负责维护，后来被黑石氏族夺取，用以监视周边山脊并巩固他们的山中堡垒。",h="石堡高塔是一座屹立在赤脊山东北部被占领的石堡要塞之中的石质岗哨。这座前哨站曾由湖畔镇的守军负责维护，后来被黑石氏族夺取，用以监视周边山脊并巩固他们的山中堡垒。",kw={"黑石氏族","加塞尔佐格","湖畔镇","赤脊山","侦察塔","石堡","石堡高塔"},ang={["faction:Alliance"]="石堡高塔是一个冷酷的提醒，展示了在暴风城王国的中央军队缺席时，黑石氏族已经深入渗透到了何种程度。",["race:Human"]="对于湖畔镇的居民来说，看到兽人的旗帜在石堡的塔楼上飘扬，是他们生存所面临的持续威胁。"},sec={{t="陷落的岗哨",b="石堡高塔由暴风城王国建造，旨在守护止水湖上方的高海拔山口，是作为石堡要塞的前哨侦察点而存在的。从这座高处的制高点，哨兵可以轻易监视东部的山脊，并向湖畔镇预警任何从燃烧平原逼近的威胁。当加塞尔佐格督军麾下的黑石兽人从高处俯冲而下，击溃人类守军并将这座要塞据为己有时，那套早期预警网络便随之瓦解了。如今，这座塔楼里布满了黑石哨兵，确保没有任何联盟侦察兵能在不被发现的情况下接近要塞。"}},faq={{q="石堡高塔是什么？",a="它是一座位于赤脊山脉东北部，更大的石堡区域内的人类设防岗哨。它最初是为了保护该地区而建造的，目前被来自黑石氏族的入侵者所控制。",al={"石堡高塔背景故事","这座塔是什么","石堡了望台"}},{q="目前是谁控制着石堡高塔？",a="这座塔楼被加塞尔佐格督军麾下的黑石氏族兽人所占据，他们从当地赤脊山人类手中夺取了这座要塞。",al={"谁拥有石堡高塔","谁在石堡高塔里","石堡高塔的敌人"}},{q="为什么这座塔对黑石兽人很重要？",a="其高海拔的地势使黑石氏族能够侦察到逼近的联盟军队，并保护他们主要堡垒——石堡要塞的进出通道。",al={"兽人为什么想要石堡高塔","石堡高塔的战略重要性"}},{q="湖畔镇能收复这座塔吗？",a="湖畔镇缺乏足够的军事人力来独自夺回石堡，因此只能依靠流浪的冒险者来削减占据塔楼和要塞的黑石守军。",al={"湖畔镇会收复它吗","湖畔镇针对石堡高塔的计划"}}},fp="16,167,18.511.0,25.179.0,40.118.0,49.136.0,32.127.0"}
P.entries["subzone:stonewrought-dam"] = {n="巨石水坝",s="巨石水坝是一座巨大的矮人工程奇迹，矗立在洛克莫丹的北缘。它拦截了洛克湖的水流，形成了巨大的高地湖泊，同时也使下方的湿地排水，变成了适宜居住的沼泽。",h="巨石水坝是一座巨大的矮人工程奇迹，矗立在洛克莫丹的北缘。它拦截了洛克湖的水流，形成了巨大的高地湖泊，同时也使下方的湿地排水，变成了适宜居住的沼泽。",kw={"黑铁矮人","弗兰克罗恩·铸铁","辛德维尔","洛克莫丹","巨石水坝","洛克湖","湿地"},ang={["profession:Engineering"]="对于任何派系的工程师来说，这座水坝都是水力控制和巨石承重力学的经典之作，甚至可以媲美铁炉堡地下的伟大工程。",["race:Dwarf"]="这座水坝是古代矮人砖石建筑和建筑独创性的丰碑，尽管其黑铁传承在铁炉堡的历史学家中仍然是一个令人不快且备受争议的话题。"},sec={{t="矮人技艺的奇迹",b="巨石水坝横跨丹奥加兹以东的峡谷，被广泛认为是矮人文明最伟大的结构性成就之一。这座屏障由黑铁建筑大师弗兰克罗恩·铸铁设计，采用了他开创性的巨石构造技术建造而成。通过拦截山谷盆地的水流，这座水坝使洛克湖的表面积增加了一倍，同时稳步降低了北方的水位，使湿地的沼泽盆地从曾经完全被淹没的山谷中显现出来。"},{t="破坏与防御",b="尽管是在黑铁建筑师的指导下建造的，但这座水坝如今服务于铁炉堡——并且已经成为从南方山区活动的黑铁破坏者们的主要目标。近期的袭击和渗透企图迫使铁炉堡在主工程师辛德维尔七世的指挥下在此驻扎了一支卫戍部队。卫兵和工程师日夜巡逻着这些砖石建筑，因为他们知道，任何缺口都会导致洛克湖的水灾难性地流失，并对下方的湿地造成毁灭性的洪水。"}},faq={{q="是谁建造了巨石水坝？",a="它是由著名的黑铁建筑师弗兰克罗恩·铸铁设计并监造的，他发明了巨石构造技术。虽然是由黑铁大师建造，但它如今服务于铜须王国。",al={"谁建造了巨石水坝","水坝的创造者","水坝建筑师"}},{q="如果水坝决堤会发生什么？",a="坍塌将是灾难性的。洛克湖会迅速干涸，使洛克莫丹留下一片空荡荡的泥坑，而排出的水则会像一场无法控制的毁灭性洪水一样席卷下方的湿地。",al={"如果水坝决堤","水坝决堤会怎样","水坝被毁"}},{q="为什么黑铁矮人要攻击它？",a="黑铁氏族试图打击铁炉堡的重要基础设施并破坏该地区的稳定。毁坏水坝将瘫痪补给线，淹没北部湿地，并对铜须矮人的自尊心造成沉重打击。",al={"为什么要攻击水坝","黑铁矮人攻击水坝"}},{q="目前是谁负责水坝的防御？",a="主工程师辛德维尔七世负责管理水坝的日常运作和防御工事，并与铁炉堡的部队协调以清除破坏者。",al={"谁在管理水坝","水坝工程师"}}},fx={["721eb9b8"]={q="巨石水坝是什么？",a="巨石水坝坐落在洛克莫丹北缘，丹奥加兹隘口以东，是矮人创造的宏伟奇迹。它拦住了浩瀚的湖水，大幅扩展了湖泊的面积，同时调节着流向下方湿地的水道。它被誉为世上最伟大的建筑奇观之一，是古代矮人工程技艺长存至今的丰碑。",al={"巨石水坝是什么","关于巨石水坝","巨石水坝的故事"}},b3d97da7={q="巨石水坝有怎样的历史？",a="这座水坝由才华横溢的Dark Iron建筑师Franclorn Forgewright构思并督建，他在氏族堕入黑暗之前开创了革新性的建造技艺。他的宏伟设计使洛克莫丹的蓄水量翻了一倍，也帮助排干了湿地沼泽盆地中的积水。水坝虽在很久以前的团结时期建成，如今却成了一场激烈冲突的前线，因为Dark Iron破坏者正企图将其摧毁。",al={"巨石水坝历史","水坝的历史","巨石水坝发生了什么"}},a124034a={q="巨石水坝危险吗？",a="水坝本身坚实稳固，但周围危机四伏。Dark Iron矮人渗透者和破坏者潜伏在水坝两侧及隧道中，携带炸药并运用黑暗魔法，企图炸开坝墙。联盟部队和铁炉堡卫兵为阻止接连不断的破坏行动而疲于奔命，毫无准备的旅人沿坝缘行走十分危险。",al={"巨石水坝危险吗","水坝安全吗","巨石水坝的威胁"}},e9d9cbd5={q="巨石水坝为什么叫这个名字？",a="水坝得名于“stonewrought”建造法，这是一种先进的矮人砌石与建筑技艺，由水坝的首席建造者Franclorn Forgewright发明。这种工艺精密而坚固，使巨大的坝墙能够世世代代承受庞大的水压。",al={"为什么叫巨石水坝","巨石水坝名字含义","stonewrought名字由来"}}},fp="16,167,25.390.0,20.382.0,31.220.0,31.190.0,39.205.0,48.140.0"}
P.entries["subzone:stonewrought-pass"] = {n="石坝小径",s="石坝小径是一条直接穿过洛克莫丹南部群山，通往灼热峡谷荒芜之地的地下隧道。这条通道由著名建筑师弗兰克罗恩·铸铁精心设计，将国王谷与尘火谷直接相连。沉重的铁门封锁了两端，以保护和平的矮人领地免受南部火山恐怖生物的侵扰。",h="石坝小径是一条直接穿过洛克莫丹南部群山，通往灼热峡谷荒芜之地的地下隧道。这条通道由著名建筑师弗兰克罗恩·铸铁精心设计，将国王谷与尘火谷直接相连。沉重的铁门封锁了两端，以保护和平的矮人领地免受南部火山恐怖生物的侵扰。",kw={"尘火谷","弗兰克罗恩·铸铁","洛克莫丹","贝波蒂","灼热峡谷","石坝小径","国王谷"},ang={["faction:Alliance"]="在矮人巡山人的守卫下，这条封闭的通道保护着洛克莫丹脆弱的定居点，使其免受灼热峡谷中滋生的火山威胁。",["race:Dwarf"]="这条隧道是弗兰克罗恩·铸铁工程才华的证明，尽管它现在紧邻着你们那些误入歧途的黑铁矮人同胞所征服的阴森领土。"},sec={{t="石中雕琢的门户",b="石坝小径由传奇建筑大师弗兰克罗恩·铸铁（也因宏伟的巨石水坝而闻名）从基岩中雕琢而成，它是连接洛克莫丹田园美景与灼热峡谷焦土荒原的直接通道。它在洛克莫丹的巨大国王谷附近出现，径直穿过山脊，一直延伸到尘火谷。由于灼热峡谷中充斥着黑铁矮人和火元素生物，铁炉堡的巡山人将这条通道用沉重的铁门严密封锁，以防止危险蔓延至北方。"}},faq={{q="石坝小径通往哪里？",a="这条小径直接穿过山脉，将洛克莫丹南缘的国王谷与灼热峡谷北部的尘火谷连接起来。",al={"石坝小径通向何处","隧道连接","灼热峡谷至洛克莫丹"}},{q="是谁设计了这条隧道？",a="它由矮人建筑大师弗兰克罗恩·铸铁设计。这位传奇工匠因设计了巨石水坝和其他宏伟的石构建筑而在卡兹莫丹备受赞誉。",al={"谁建造了石坝小径","小径的设计师","弗兰克罗恩·铸铁隧道"}},{q="为什么要锁住大门？",a="大门两侧均有重兵把守，旨在阻止灼热峡谷中的火元素怪物和敌对的黑铁矮人入侵洛克莫丹的居住区。巡山人贝波蒂守卫着洛克莫丹的入口，需要获得授权后才会放行。",al={"锁闭的大门","为何小径会被锁住","如何开启大门"}}},fp="17,248,25.426.0,38.147.0,25.163.0,25.203.0"}
P.entries["subzone:stormrage-barrow-dens"] = {n="怒风兽穴",s="怒风兽穴是一处古老的地下圣所，开凿在月光林地那片神圣的山谷之下。此处以玛法里奥·怒风的名字命名，这些安静的土制墓穴是德鲁伊们的专属休憩地，他们在此进行漫长而恢复元气的沉睡，以此游历翡翠梦境。",h="怒风兽穴是一处古老的地下圣所，开凿在月光林地那片神圣的山谷之下。此处以玛法里奥·怒风的名字命名，这些安静的土制墓穴是德鲁伊们的专属休憩地，他们在此进行漫长而恢复元气的沉睡，以此游历翡翠梦境。",kw={"兽穴","塞纳里奥议会","克林塔·梦游者","翡翠梦境","玛法里奥","月光林地","怒风兽穴"},ang={["class:Druid"]="对于两个种族的德鲁伊来说，怒风兽穴代表了塞纳里奥传统的圣地核心，展示了资深修行者往返于艾泽拉斯和翡翠梦境之间的传统地下庇护所。",["race:NightElf"]="这个空洞对卡多雷来说具有深远的历史意义，它铭记了他们沉睡者长达数千年的守护，也铭记了泰兰德·语风为对抗燃烧军团而深入地底唤醒玛法里奥·怒风的危险旅程。"},sec={{t="沉睡者之室",b="兽穴是遍布暗夜精灵领地的神圣避难所，为德鲁伊们提供了一个安全的地下栖身之所。当他们沉浸在翡翠梦境中时，肉身可以不受打扰地在此安息。怒风兽穴在神圣的月光林地中尤受尊崇。为了纪念大德鲁伊玛法里奥·怒风，这里以其名字命名，这些蜿蜒的土制大厅不仅蕴含着古老的敬意，还静静地守护着这里。虽然像Clintar Dreamwalker这样的一些德鲁伊仍然安全地在壁龛中沉睡，但那位伟大大德鲁伊本人的缺席，在空洞的根须和宁静的荧光灯笼上投下了阴郁的阴影。"},{t="第三次战争的回响",b="在第三次战争那段绝望的日子里，这些兽穴濒临彻底毁灭。恐惧魔王提克迪奥斯和燃烧军团的势力试图在沉睡的德鲁伊们集结之前将他们铲除。大祭司泰兰德·语风一路奋战，杀穿了入侵的恶魔和充满敌意的腐化生物，深入这些土制隧道，吹响了塞纳留斯之角，及时唤醒了玛法里奥·怒风。自从阿克蒙德在海加尔山战败后，玛法里奥的灵魂再次飘入了翡翠梦境，留下他的同胞守护着这些神圣的地下深处。"}},faq={{q="怒风兽穴的作用是什么？",a="兽穴为暗夜精灵德鲁伊提供了受保护的、宁静的地下圣所。当他们的心智和灵魂漫游在翡翠梦境的广阔路径时，他们的肉身会在数月甚至数年内保持静止且毫无防备，因此需要一个安静而隐蔽的休憩处，以便在同胞的守护下安全地休息。",al={"兽穴的用途","为什么要再兽穴中睡觉","怒风兽穴的目的"}},{q="玛法里奥·怒风现在在这些兽穴里吗？",a="在第三次战争期间，玛法里奥·怒风曾在兽穴中休息，后来被泰兰德·语风唤醒。战后，他的灵魂一直迷失在翡翠梦境中，而塞纳里奥议会则在没有他的情况下继续运作。",al={"玛法里奥在哪里","玛法里奥在兽穴里吗","我能在这里找到玛法里奥吗"}},{q="现在有谁在这些兽穴中沉睡？",a="在兽穴中休息的德鲁伊包括克林塔尔·梦行者，他正躺在地下深处做着梦，而他的灵魂则穿梭在自然的空灵路径中。",al={"谁在这里睡觉","克林塔·梦行者","月光林地的沉睡德鲁伊"}},{q="在第三次战争期间这里发生了什么？",a="在第三次战争期间，恐惧魔王提克迪奥斯和燃烧军团的恶魔势力入侵了兽穴，企图屠杀沉睡的暗夜精灵德鲁伊。大祭司泰兰德·语风率领突击队深入地底，奋战穿过恶魔势力，吹响了塞纳留斯之角并唤醒了玛法里奥·怒风。",al={"第三次战争与兽穴","提克迪奥斯袭击月光林地","泰兰德唤醒怒风"}}},fp="21,139,26.382.0,23.451.0,49.211.0,51.219.0,44.147.0,49.225.0"}
P.entries["subzone:stormwind-city"] = {n="暴风城",s="暴风城是暴风王国的雄伟首都，也是联盟的军事与政治中心。它在第一次战争中被摧毁，随后在废墟上重建，如今已成为北方诸王国沦陷后，艾泽拉斯人类势力最强大的堡垒。",h="暴风城是暴风王国的雄伟首都，也是联盟的军事与政治中心。它在第一次战争中被摧毁，随后在废墟上重建，如今已成为北方诸王国沦陷后，艾泽拉斯人类势力最强大的堡垒。",kw={"联盟","安度因","伯瓦尔","艾尔文","第一次战争","石匠工会","暴风城","乌瑞恩"},ang={["faction:Alliance"]="暴风城是联盟在东部王国南部的首要军事、海军和精神集结地，迎接并包容着矮人、侏儒和暗夜精灵的使节。",["race:Human"]="对于全艾泽拉斯的人类而言，暴风城的白色城墙代表了坚韧、生存，以及在北方诸王国覆灭后，人类文明依然存续的荣耀。"},sec={{t="浴火重生的灯塔",b="一千多年前，阿拉索的后裔向南迁徙，建立了暴风城。它曾是一座充满活力的沿海都城，四周环绕着坚固的石墙，因湍急的河流推动的水磨坊而繁荣。然而，这种辉煌在第一次战争中戛然而止：兽人部落围攻了这座城市，攻破了防御，并将其付之一炬。安度因·洛萨爵士被迫率领幸存的难民渡过无尽之海，逃往洛丹伦。在联盟于第二次战争中获胜后，石匠工会承担了重建首都的艰巨任务，将其打造为如今坐落在艾尔文森林北部的这座闪耀的要塞。它由白色石材筑成，拥有错综复杂的运河网络和高耸入云的尖塔。"},{t="联盟的心脏",b="随着洛丹伦被天灾军团摧毁，达拉然也在第三次战争中受到重创，暴风城成为了人类主要的避难所和据点。暴风城卫兵在宽阔的街道和防御墙上巡逻，维持治安；而位于城中的光明大教堂的尖塔则在南方诸王国传播着信仰与奉献。然而，在这秩序井然的城区和庄严的城门之下，却暗流涌动：瓦里安·乌瑞恩国王离奇失踪，留下年幼的儿子安度因在摄政王伯瓦尔·弗塔根公爵的辅佐下登基，并受到皇家顾问女伯爵卡特拉娜·普瑞斯托的耳语教唆。"}},faq={{q="为什么暴风城在第一次战争后要重建？",a="暴风城在第一次战争期间被兽人部落攻陷并焚毁。在洛丹伦联盟于第二次战争击败兽人后，人类难民收复了他们祖先的王国。皇家法庭委托石匠工会，在原来的废墟之上建造了一座更宏伟的堡垒之城。",al={"谁重建了暴风城","暴风城的重建","为什么暴风城看起来很新"}},{q="目前谁在统治暴风城？",a="名义上，在父亲瓦里安·乌瑞恩国王突然且毫无预兆地失踪后，少年国王安度因·乌瑞恩登上了王位。由于安度因尚且年幼，真正的治理权力掌握在摄政王兼王国防御指挥官——伯瓦尔·弗塔根公爵手中。",al={"谁是暴风城国王","谁在管理暴风城","暴风城现任统治者"}},{q="为什么暴风城是主要的人类首都，而不是洛丹伦？",a="在第三次战争期间，北方的洛丹伦王国在亡灵瘟疫和天灾军团的内部侵蚀下彻底覆灭。随着洛丹伦的毁灭和其他北方人类王国的满目疮痍，暴风城成为了艾泽拉斯仅存的、最富庶、最完好且人口最稠密的人类王国。",al={"洛丹伦发生了什么","为什么不是洛丹伦作为首都","暴风城是最后的城市吗"}},{q="哪些军事力量保护着这座城市？",a="城区内和城墙上的治安由暴风城卫兵维护。更大范围的领土防御和皇室保护则由王国的骑士、暴风要塞的驻军以及隶属于圣光教会的圣骑士们负责。",al={"谁在守卫暴风城","暴风城军队","城市卫兵"}}},fx={["209accb7"]={q="暴风城是什么地方？",a="暴风城是暴风城王国的首都，也是艾泽拉斯现存最强大的人类堡垒。它坐落于艾尔文森林以北的西海岸，是联盟跳动的心脏。高耸的白石城墙与幽深的运河之内，有繁荣的商业街区、王权的中枢，以及为所有敬奉圣光之人指引信仰的光明大教堂。",al={"暴风城是什么","暴风城概况","关于暴风城"}},["38604972"]={q="暴风城发生过什么？",a="暴风城由阿拉希后裔于一千多年前建立，历经豺狼人战争和巨魔袭击，最终在第一次兽人战争中遭遇彻底毁灭。兽人部落围攻首都，攻破防线，将城市夷为平地，迫使幸存者渡海北逃。联盟在第二次兽人战争中获胜后，石匠公会倾注心血重建城市，造就了如今这座宏伟的堡垒。",al={"暴风城历史","暴风城发生了什么","暴风城的陷落"}},["7f858f77"]={q="暴风城危险吗？",a="在城墙之内，暴风城是王国最安全的定居点之一，警觉的暴风城卫兵时刻巡逻。然而，和平并非牢不可破。旧城区的小巷等阴暗角落中潜藏着威胁，王廷内政治阴谋暗流涌动，王国周边领土也仍受亡命之徒和步步进逼的怪物威胁。",al={"暴风城安全吗","暴风城危险吗","暴风城内的威胁"}}},fp="14,201,16.546.0,21.582.0,46.299.0,35.216.0,61.253.0,38.254.0"}
P.entries["subzone:stormwind-gate"] = {n="Stormwind Gate",s="Stormwind Gate是连接艾尔文森林与暴风城之间宏伟的防御性入口。这道关口时刻都有皇家卫兵守卫，是宁静森林与宏大的英雄谷之间的主要界限。",h="Stormwind Gate是连接艾尔文森林与暴风城之间宏伟的防御性入口。这道关口时刻都有皇家卫兵守卫，是宁静森林与宏大的英雄谷之间的主要界限。",kw={"艾尔文森林","闪金镇","暴风城卫兵","暴风城大门","英雄谷"},ang={["faction:Alliance"]="这道大门象征着大联盟的安全与坚韧，是远征归来的士兵和年轻冒险者眼中展现威严的第一幕。",["race:Human"]="对于暴风城的民众来说，穿过这些石拱门意味着在穿越艾尔文森林及更远的地方经历漫长旅程后，终于回到了安全的家中。"},sec={{t="王国的门槛",b="Stormwind Gate高耸于艾尔文森林的南侧道路上，既是首都的防御工事，也是礼仪性的大门。暴风城卫兵的哨兵们时刻注视着这座石质门户，守卫着从森林通往城内的通道，同时正规巡逻队在外部拱门和英雄谷之间行进。尽管艾尔文森林各地仍有动荡，但这道巨大的铁石大门始终敞开，欢迎旅行者、商人和归来的守卫进入联盟的心脏。"}},faq={{q="暴风城大门通向哪里？",a="从艾尔文森林穿过大门，你将直接进入英雄谷，这是通往暴风城的宏伟入口，两旁矗立着第二次战争中英雄们的雕像。",al={"暴风城大门通向哪里","大门后面是什么","暴风城入口"}},{q="如果艾尔文森林很危险，为什么大门始终敞开？",a="暴风城的繁荣依赖于开放的贸易以及来自闪金镇和整个联盟的稳定通行。尽管周边森林中存在强盗和迪菲亚兄弟会的威胁，但暴风城选择派遣警惕的守卫驻守通道，而不是将自己的市民和商业拒之门外。",al={"为什么大门是开着的","暴风城大门是关闭的吗","为什么敞开"}},{q="是谁在守卫大门？",a="这个入口由暴风城卫兵驻守。两名哨兵在艾尔文森林外侧站岗，另外两名守卫着内侧通道，还有武装步兵在通往英雄谷的桥上巡逻。",al={"暴风城大门守卫","谁保卫大门"}},{q="大门处会举行特殊活动吗？",a="是的。暴风城大门周围的开阔地带经常举办联盟重大的城市节日和季节性聚会，作为拥挤街区之外的开放集会场所。",al={"暴风城大门的节日","大门处的活动"}}},fx={c23a16f5={q="暴风城大门危险吗？",a="对联盟成员而言并不危险。暴风城卫兵在城门内外及邻近的英雄谷巡逻，戒备森严。然而，敌方渗透者或部落旅人几乎不可能闯过这里，因为驻守的哨兵一旦发现任何公开与王国为敌的人，就会立即发起攻击。",al={"城门安全吗","暴风城大门危险","暴风城大门安全吗"}}},fp="14,149,28.286.0,35.147.0,56.190.0,21.193.0,42.185.0"}
P.entries["subzone:stormwind-keep"] = {n="Stormwind Keep",s="暴风要塞巍然耸立于首都之上，是暴风王国的石制堡垒和权力中心。它在第一次战争中被毁后重建，目前是年幼的国王安度因·乌瑞恩和他的摄政王伯瓦尔·弗塔根公爵的皇室庭院所在地。",h="暴风要塞巍然耸立于首都之上，是暴风王国的石制堡垒和权力中心。它在第一次战争中被毁后重建，目前是年幼的国王安度因·乌瑞恩和他的摄政王伯瓦尔·弗塔根公爵的皇室庭院所在地。",kw={"安度因·乌瑞恩国王","伯瓦尔·弗塔根","暴风城城堡","卡特拉娜·普瑞斯托","皇家图书馆","暴风要塞","王座大厅","作战室"},ang={["faction:Alliance"]="这座要塞是联盟东方军事指挥中心的心脏，伯瓦尔·弗塔根公爵和元帅们在此指挥防御，抵御来自艾尔文森林、西部荒野及更远地区的不断威胁。",["race:Human"]="这座堡垒在第一次战争的浩劫后从灰烬中重建，见证了暴风城人民的韧性和自豪。"},sec={{t="重建的要塞",b="暴风要塞坐落于俯瞰整座城市的高原之上，既是宫殿也是军事堡垒。在第一次战争末期，莱恩国王被刺杀后，最初的要塞被旧部落烧成了平地。联盟收复王国后，这座要塞在旧地基上拔地而起，重建后的要塞不仅拥有宏伟的王座大厅和 War Room，还拥有宁静的庭院和广阔的皇家图书馆。"},{t="分裂的宫廷",b="在这座要塞的旗帜和打磨光滑的石墙背后，隐藏着不安的和平。瓦里安·乌瑞恩国王在前往塞拉摩参加外交峰会的途中神秘失踪，治理国家的重任落在了十岁的安度因·乌瑞恩国王肩上。实际的统治权掌握在伯瓦尔·弗塔根公爵和贵族女伯爵卡特拉娜·普瑞斯托手中。虽然伯瓦尔负责防御和军事事务，但宫廷政治却因贵族内斗而陷入瘫痪，导致外围领土极其脆弱，王室也深陷混乱。"}},faq={{q="现在是谁在统治暴风要塞？",a="安度因·乌瑞恩国王在名义上拥有王位，但由于他年仅十岁，因此由伯瓦尔·弗塔根公爵担任摄政王，并与作为皇家顾问的女伯爵卡特拉娜·普瑞斯托共同治理国家。",al={"谁在负责","谁领导暴风城","谁是国王"}},{q="瓦里安·乌瑞恩国王发生了什么事？",a="瓦里安国王在穿越海洋前往塞拉摩参加和平会议的途中神秘失踪。他突然失踪导致王位空缺，迫使伯瓦尔和宫廷为确保政治稳定而加冕年幼的安度因。",al={"瓦里安在哪里","瓦里安失踪","国王发生了什么"}},{q="这座要塞在第一次战争中被摧毁了吗？",a="是的。在迦罗娜谋杀莱恩·乌瑞恩国王后，旧部落压倒了城市并彻底夷平了这座要塞。目前的堡垒是在第二次战争中联盟取得胜利后，在古老的地基上重建的。",al={"兽人摧毁了要塞吗","第一次战争城堡破坏"}},{q="要塞内可以参观哪些主要区域？",a="该建筑群包含主王座大厅、其后方的 作战室、用于接见请愿者的 请愿者大厅、开放式花园庭院、皇家画廊 和皇家图书馆。",al={"要塞房间","要塞里有什么","暴风要塞 的侧厅"}}},fx={["3e1bbfc4"]={q="暴风要塞是什么地方？",a="暴风要塞是人类王国暴风城的宏伟堡垒，也是权力中心。这座要塞俯瞰整座城市，既是王宫，也是王国政府的核心。走进坚固的石墙之内，可以看到王室朝廷、王座厅、供请愿者使用的接见厅、皇家图书馆、宁静的内庭花园，以及城堡精锐亲卫的营房。",al={"暴风要塞是什么","暴风要塞的用途","暴风要塞简介"}},a781e02c={q="暴风要塞危险吗？",a="对忠诚的臣民和联盟盟友而言，暴风要塞是世界上最安全的庇护所之一。这里驻扎着大批精锐王室卫兵和王冠守护者，时刻防范外部威胁。然而，平静的宫廷生活之下暗藏微妙的政治角力，贵族派系和王室顾问争相影响年轻的国王，而王国各地的动荡也日益加剧。",al={"暴风要塞危险吗","暴风要塞安全吗","要塞会敌对吗"}}},fp="14,189,19.431.0,15.391.1,38.173.0,35.172.0,40.206.0,48.189.0"}
P.entries["subzone:stormwind-stockade"] = {n="暴风城监狱",s="监狱隐藏在法师区北侧的运河下方，是暴风城戒备森严的惩戒所。这座地下堡垒原本用于关押杀人犯、政治异见者和外国敌对势力，但近期由于一场有组织的囚犯暴动，已经彻底陷入混乱之中。",h="监狱隐藏在法师区北侧的运河下方，是暴风城戒备森严的惩戒所。这座地下堡垒原本用于关押杀人犯、政治异见者和外国敌对势力，但近期由于一场有组织的囚犯暴动，已经彻底陷入混乱之中。",kw={"巴基尔·斯瑞德","运河","迪菲亚","迪克斯特·瓦德","卡姆·深怒","监狱","暴乱","暴风城","塔格尔","典狱官塞尔沃特"},ang={["class:Rogue"]="这场暴乱揭开了迪菲亚潜行者和巴基尔·斯瑞德的运作内幕，让人得以一窥这个犯罪黑社会在王权眼皮底下组织得有多么严密。",["faction:Alliance"]="监狱直接位于首都，因此平定监狱对民防至关重要；清理其大厅可以暴露迪菲亚潜行者渗透暴风城的程度有多深。"},sec={{t="围城中的监狱",b="监狱通常由典狱官塞尔沃特负责管理，王国会将最危险的囚犯关押于此，从亡命之徒和迪菲亚潜行者，到被俘获的黑石兽人和黑铁矮人，应有尽有。然而，狡诈的迪菲亚阴谋家巴基尔·斯瑞德策划了一场暴力起义，彻底取代了监狱看守。囚犯们现在在下层牢房中横行，将这里变成了一座暴乱的堡垒。塞尔沃特在勉强守住入口关卡后，只能指望独立冒险者们深入地下走廊，在暴乱蔓延到运河区之前平息这场叛乱。"},{t="官僚主义与幕后阴谋",b="监狱关押的不仅仅是普通的街头罪犯；长期以来，它一直是王国腐败的贵族议会手中的谈判筹码。那些在其他地方被判处死刑的杀人犯和高价值囚犯——例如来自暮色森林的盗墓贼迪克斯特·瓦德，或来自赤脊山的黑石行刑者可怕的塔格尔——由于贵族阶层的干预，他们的死刑被推迟执行，沦为政治傀儡。甚至邻近的铁炉堡也注意到了这一点，当人类官僚主义阻碍了正当的审判时，他们会秘密雇佣雇佣兵去处决像卡姆·深怒这样危险的囚犯。"}},faq={{q="监狱的入口在哪里？",a="入口位于暴风城的运河区，就在通往法师区的桥梁旁，隐藏在北侧的弯道处。一个有守卫把守的门口通往一条向下的石阶，直达地下牢房。",al={"监狱入口","如何进入监狱","监狱位置"}},{q="是谁引发了监狱里的暴乱？",a="这场叛乱是由关押在监狱中的迪菲亚潜行者高级头目巴基尔·斯瑞德策划并点燃的。在他的指挥下，囚犯们压制了守卫，夺取了武器，并完全控制了地下牢房区。",al={"巴基尔·斯瑞德是谁","谁领导了监狱暴乱","谁管理监狱"}},{q="为什么暴风城的监狱里会有兽人和黑铁矮人？",a="暴风城会从其有争议的领土上俘获高优先级敌对目标。值得注意的是，可怕的塔格尔是从赤脊山被抓捕的，而卡姆·深怒则代表了黑铁矮人的威胁。他们没有被迅速处决，而是作为战俘被带到这里，或者因贵族的法令而被保留性命以作为政治筹码。",al={"为什么监狱里有兽人","监狱里的黑铁囚犯"}},{q="为什么暮色森林和赤脊山的人要求人们在这里处决囚犯？",a="像夜色镇和湖畔镇这样的偏远定居点判处了迪克斯特·瓦德和可怕的塔格尔等罪犯死刑，却发现贵族议会中止了他们的处刑。由于对暴风城的官僚干预感到沮丧，地方领袖私下雇佣佣兵来绕过皇家的文书工作，完成任务。",al={"暮色森林监狱任务","罪与罚","因果报应"}}},fx={e9dc0ba3={q="暴风城监狱是什么地方？",a="监狱是一座戒备森严的地下监牢，开凿于暴风城的运河下方。这里由典狱官塞尔沃特掌管，专门关押王国最危险的罪犯，包括杀人犯、政治叛乱者、迪菲亚匪徒，以及等待审判的外来敌人。",al={"监狱是什么","暴风城监狱资料"}},d734f0f2={q="暴风城监狱发生过什么？",a="被捕的迪菲亚主谋巴基尔·斯瑞德在监狱内部策划了一场由囚犯发动的暴力叛乱。暴动的囚犯制服了狱卒，将卫兵彻底赶出牢房区，夺取了整座监狱的控制权。如今，城市卫兵正对这场危机保密，同时招募雇佣兵夺回监狱。",al={"监狱里发生了什么","监狱历史","监狱为什么发生暴动"}},["10925a1c"]={q="暴风城监狱危险吗？",a="眼下极其危险。囚犯们携带武器，在迪菲亚的领导下结成组织，与杀人恶徒、黑石兽人和黑铁渗透者一同在大厅内自由游荡，无人看管。任何进入这里的人，都必须杀出一条路，穿过那些秩序尽失、敌人遍布且卫兵无处立足的走廊。",al={"监狱有多危险","监狱危险吗","监狱里的危险"}}},fp="18,200,20.383.0,32.481.1,46.188.0,39.195.0,61.307.0,67.233.0"}
P.entries["subzone:stormwind-stockade-classic"] = {n="Stormwind Stockade (Classic)",s="暴风城监狱是位于暴风城运河区下方的一座加固地下监狱。它最初用于关押轻罪罪犯、暴力雇佣兵和政治颠覆分子，但最近因为一场暴力的囚犯叛乱而陷入了混乱。",h="暴风城监狱是位于暴风城运河区下方的一座加固地下监狱。它最初用于关押轻罪罪犯、暴力雇佣兵和政治颠覆分子，但最近因为一场暴力的囚犯叛乱而陷入了混乱。",kw={"巴基尔·斯瑞德","迪菲亚","迪克斯特·瓦德","卡姆·深怒","监狱","暴风城监狱","可怕的塔格尔","起义","典狱官塞尔沃特"},ang={["faction:Alliance"]="发生在首都街道下方的这场暴动对伯瓦尔·弗塔根公爵的执政当局来说是一种严重的羞辱，暴露出在国王缺席的情况下，暴风城内部竟是如此脆弱。",["race:Human"]="对于边境城镇的人类居民来说，监狱的瘫痪证明了贵族议会更关心首都的法律繁文缛节，而不是保护边境定居点免受谋杀犯的侵害。"},sec={{t="暴动的监狱",b="暴风城监狱隐藏在旧城区和法师区之间的运河旁，是暴风王国的首要惩戒设施。在典狱官塞尔沃特的管理下，这座地下建筑关押着王国里最危险的恶徒：迪菲亚潜行者中的杀手、一名掠夺成性的黑石兽人、一名食人魔，甚至还有一个潜入进来的黑铁矮人。最近，狡猾的罪犯巴基尔·斯瑞德精心策划了一场监狱暴乱，击溃了守卫部队，将幸存的卫兵赶走，使囚犯们完全控制了内部大厅。"},{t="官僚主义与报应",b="监狱内的灾难暴露了暴风城治理中的严重裂痕。许多臭名昭著的囚犯，例如黑石恐怖分子可怕的塔格尔和倒卖尸体的盗墓贼迪克斯特·瓦德，早已被判处死刑，却因有影响力的贵族们不断拖延执行而苟活至今。由于对贵族们的推诿感到愤怒，湖畔镇和夜色镇等周边定居点，连同丹莫德的矮人驻军，完全绕过了王室渠道，直接招募外来的冒险者，趁着混乱潜入并处决关键的首领。"}},faq={{q="暴风城监狱在哪里？",a="暴风城监狱的入口位于暴风城北侧运河岸边，连接着旧城区与大教堂区和法师区之间的通道。",al={"监狱入口","如何前往监狱","监狱位置"}},{q="目前是谁在管理监狱？",a="虽然典狱官塞尔沃特是官方指定的典狱官，但他已在叛乱中被赶走。该设施目前实际上是由挑起暴动的囚犯巴基尔·斯瑞德及其迪菲亚潜行者盟友所控制。",al={"谁在管理监狱","监狱首领","巴基尔·斯瑞德"}},{q="为什么暴风城会关押兽人和黑铁矮人？",a="暴风城在此关押着高价值的战俘和破坏者。可怕的塔格尔是从附近山区抓获的黑石兽人掠夺者，而卡姆·深怒则是一名因进行反联盟颠覆活动而被监禁的敌对黑铁矮人。",al={"为什么监狱里有兽人","卡姆·深怒","可怕的塔格尔"}},{q="为什么那些被判死刑的谋杀犯没有被处决？",a="暴风城高级贵族的官僚主义和政治干预反复拖延了迪克斯特·瓦德和塔格尔等罪犯的处决，引发了赤脊山和暮色森林等外围领地的强烈不满。",al={"为什么他们没有被处决","暴风城贵族","迪克斯特·瓦德的处决"}}},fx={d4f3da71={q="暴风城监狱是什么地方？",a="监狱建于暴风城运河区下方，是一座守卫严密、防范森严的监牢。这里由典狱官塞尔沃特管辖，原本用于关押王国的各类罪犯，从街头小偷、盗墓贼，到政治叛乱者、迪菲亚密谋者和残忍的杀人犯。",al={"监狱是什么","暴风城监狱","监狱介绍"}},["5c482541"]={q="暴风城监狱发生过什么？",a="最近，狡诈的主谋巴基尔·斯瑞德带头在牢房内发动了一场暴力囚犯叛乱。暴动的囚犯制服了卫兵，杀害看守，并将典狱官塞尔沃特赶到了运河边。城市卫兵被挡在门外，囚犯则完全控制了整座监狱，将地下大厅变成了杀人恶徒和密谋者固守的庇护所。",al={"这里发生了什么","监狱暴动的故事","监狱历史"}},b72eefeb={q="暴风城监狱危险吗？",a="极其危险。狭窄的石砌走廊里挤满了挣脱束缚的杀人犯、迪菲亚雇佣兵、凶猛的黑石兽人和黑铁渗透者。囚犯们困在拥挤的空间里，会凶狠地围攻任何闯入者，而敌方援兵涌入城内运河的风险，也始终威胁着暴风城的安全。",al={"监狱有多危险","监狱安全吗","监狱危险"}}},fp="28,157,18.318.0,27.407.1,30.134.0,36.172.0,64.219.0,60.203.0"}
P.entries["subzone:stoutlager-inn"] = {n="烈酒旅店",s="烈酒旅店是塞尔萨玛热闹的核心，也是洛克湖旅行者的主要避风港。它坐落在洛克湖起伏的丘陵之下，提供温暖的炉火、烈性的矮人麦酒，是冒险者和当地居民熙熙攘攘的聚集地。",h="烈酒旅店是塞尔萨玛热闹的核心，也是洛克湖旅行者的主要避风港。它坐落在洛克湖起伏的丘陵之下，提供温暖的炉火、烈性的矮人麦酒，是冒险者和当地居民熙熙攘攘的聚集地。",kw={"矮人","炉石","旅店老板","洛克莫丹","烈酒旅店","酒馆","塞尔萨玛"},ang={["faction:Alliance"]="这家旅店是联盟冒险者前往北方湿地，或是在洛克湖周围饱受困扰的山谷巡逻时的重要补给站和避风港。",["race:Dwarf"]="对于铜须矮人来说，烈酒旅店体现了熟悉的家园温暖，以纯正的好客、新鲜的麦酒和远离铁炉堡后的可靠陪伴而闻名。"},sec={{t="丘陵中温馨的炉火",b="烈酒旅店位于塞尔萨玛定居点的正中央，是洛克湖西部社区生活的中心。往返于丹莫罗和湿地之间的矿工、登山者和旅行者都会在此驻足，交换传闻、投宿，并分享浓郁的矮人佳酿。虽然塞尔萨玛之外的荒野因穴居人和狗头人的活动而日益险恶，但烈酒旅店那厚实的石墙和熊熊燃烧的炉火提供了一个可靠的避难所。"}},faq={{q="在烈酒旅店可以获得哪些服务？",a="这家旅店提供传统的酒馆设施，包括绑定炉石的旅店老板、为疲惫的旅行者准备的床铺，以及为穿越洛克湖的旅程提供补给和饮品的当地商人。",al={"旅店服务","旅店里有什么","塞尔萨玛旅店老板"}},{q="烈酒旅店位于哪里？",a="它建在塞尔萨玛的中心，这是位于洛克湖西部主干道旁的主要联盟城镇。",al={"旅店位置","烈酒旅店在哪里","寻找烈酒旅店"}},{q="为什么这家旅店对塞尔萨玛如此重要？",a="除了提供食物和住宿外，烈酒旅店还是城镇广场和消息中心。当地的登山者在这里发布悬赏，旅行者则在这里规划前往周边丘陵的探险。",al={"它为什么受欢迎","塞尔萨玛酒馆背景故事"}}},fx={["621b2370"]={q="烈酒旅店是什么地方？",a="烈酒旅店是塞尔萨玛充满活力的中心，也是整个洛克莫丹最热闹的聚会场所之一。它为走下山路、疲惫不堪的旅人提供温暖宜人的庇护，备有烈性的矮人麦酒、热腾腾的饭菜，以及炉火旁柔软的床铺。当地的巡山人、矿工和来访的冒险者常常聚在粗大的木梁下，交流传闻，筹划前往周围山丘的探险，在远离荒野的地方享受相聚的时光。",al={"烈酒旅店是什么","烈酒旅店背景","塞尔萨玛旅店"}},["7e615305"]={q="烈酒旅店危险吗？",a="一点也不危险。烈酒旅店坐落在塞尔萨玛的正中心，是一处安全的庇护所，受到当地矮人卫兵和过往巡山人的严密保护。虽然穴居人、狗头人和凶猛的野兽在洛克莫丹的湖岸与山脊间游荡，旅店本身依然是一处宁静的港湾，你可以在这里休息、喘口气，将灵魂与炉石绑定，无须担心遭到袭击。",al={"烈酒旅店安全吗","烈酒旅店危险","塞尔萨玛旅店的威胁"}}},fp="14,117,31.299.0,50.158.0,36.116.0,41.165.0"}
P.entries["subzone:strahnbrad"] = {n="斯坦恩布莱德",s="斯坦恩布莱德是一座破败的人类定居点，坐落在奥特兰克山脉东北部的山地上，毗邻西瘟疫之地。这里曾因阿尔萨斯·米奈希尔王子早期防卫黑石兽人袭击的壮举而闻名，但如今这座城镇已衰败不堪，成为了辛迪加这个犯罪组织的一处坚固据点。",h="斯坦恩布莱德是一座破败的人类定居点，坐落在奥特兰克山脉东北部的山地上，毗邻西瘟疫之地。这里曾因阿尔萨斯·米奈希尔王子早期防卫黑石兽人袭击的壮举而闻名，但如今这座城镇已衰败不堪，成为了辛迪加这个犯罪组织的一处坚固据点。",kw={"奥特兰克","阿尔萨斯","黑石","戈尔迪尔","克鲁斯克","洛丹伦","斯坦恩布莱德","辛迪加"},ang={["class:Paladin"]="漫步在斯坦恩布莱德的鹅卵石路上，让人回想起阿尔萨斯·米奈希尔王子和光明使者乌瑟尔那段早期清白的时光，这苦涩地提醒着人们，洛丹伦的英雄们如今已沦落至何种境地。",["faction:Horde"]="辛迪加对兽人戈尔迪尔的奴役使得斯坦恩布莱德成为了部落勇士们的目标，他们迫切需要打击这些人类强盗并营救自己的同胞。"},sec={{t="悲剧之城",b="斯坦恩布莱德原本属于奥特兰克王国，第二次战争后被并入洛丹伦，其不幸始于第三次战争前夕。黑石氏族的兽人袭击了该定居点，意图将人类作为燃烧军团的祭品。阿尔萨斯·米奈希尔王子和白银之手骑士团骑马赶来支援。尽管阿尔萨斯击退了袭击者并斩杀了他们的奴隶主，但小镇还是血流成河。此后不久，随着洛丹伦在天灾军团的铁蹄下沦陷，斯坦恩布莱德也遭到遗弃，任由风雨侵蚀。"},{t="辛迪加的控制",b="今天，斯坦恩布莱德已成为辛迪加的关键行动中心。辛迪加是由流离失所的奥特兰克贵族和亡命之徒组成的组织，他们密谋夺回沦陷的王国。这里有盗贼和强盗巡逻，废弃的市政厅和铁匠铺成了他们的藏身处和集结地。辛迪加利用这座废墟城镇来存放补给和关押苦工，其中包括不幸的囚犯，比如兽人戈尔迪尔，来自塔伦米尔的部落侦察兵正积极设法营救他。"}},faq={{q="为什么斯坦恩布莱德在历史上很重要？",a="斯坦恩布莱德是阿尔萨斯·米奈希尔王子在第三次战争中的首场交锋地点。受光明使者乌瑟尔之命，阿尔萨斯保卫此定居点免受狂暴黑石兽人的侵扰，他在此完成了自己早期的成名之战，解救了城镇居民并斩杀了兽人袭击者。",al={"为什么斯坦恩布莱德很重要","阿尔萨斯 斯坦恩布莱德","斯坦恩布莱德历史"}},{q="谁现在控制着斯坦恩布莱德？",a="辛迪加控制着斯坦恩布莱德。这些效忠于奥特兰克没落贵族血脉的人类强盗，加固了破败的市政厅和铁匠铺，将其作为在山区扩张势力的主要集结地。",al={"谁占领了斯坦恩布莱德","斯坦恩布莱德怪物","谁住在斯坦恩布莱德"}},{q="斯坦恩布莱德最初属于哪个王国？",a="斯坦恩布莱德在第一次战争前最初属于奥特兰克王国。在奥特兰克于第二次战争期间背叛联盟后，该镇被并入洛丹伦王国的领土。",al={"斯坦恩布莱德属于奥特兰克还是洛丹伦","斯坦恩布莱德所属王国"}},{q="部落为何关注这座城镇？",a="辛迪加俘虏了一名叫做戈尔迪尔的兽人，强迫他在斯坦恩布莱德的废墟中从事残酷的奴隶劳动。来自塔伦米尔的部落特工在克鲁斯克的指挥下，派遣冒险者前往此地突破辛迪加的防线并救出戈尔迪尔。",al={"斯坦恩布莱德部落任务","克鲁斯克 斯坦恩布莱德","戈尔迪尔 斯坦恩布莱德"}}},fx={["8ef7b8bc"]={q="斯坦恩布莱德是什么地方？",a="斯坦恩布莱德是一处废墟，坐落在奥特兰克山脉东北麓，靠近通往西瘟疫之地的山口。它原本是一座人类城镇，先后归属奥特兰克王国和洛丹伦，如今已荒废，街道上不见无辜居民的踪影，只剩危险的歹徒盘踞。",al={"这是什么地方","斯坦恩布莱德概况","介绍一下斯坦恩布莱德"}},e385b772={q="斯坦恩布莱德为何沦为废墟并被遗弃？",a="第三次战争前不久，叛逃的黑石兽人袭击了斯坦恩布莱德，抓捕祭品献给燃烧军团，使这座城镇遭受残酷破坏。阿尔萨斯·米奈希尔王子虽赶来驱逐袭击者，仍有许多镇民丧生。洛丹伦沦陷于天灾军团后，幸存者四散或死去，废弃的建筑随后被强盗占据。",al={"斯坦恩布莱德为何被摧毁","谁摧毁了斯坦恩布莱德","斯坦恩布莱德为何成了鬼城"}},["37fa5a7f"]={q="前往斯坦恩布莱德危险吗？",a="是的，斯坦恩布莱德非常危险。废弃的城镇是辛迪加的活跃据点。辛迪加是由前奥特兰克贵族和歹徒组成的残酷犯罪组织。他们一发现闯入者就会发动袭击，甚至会抓人强迫劳役，因此任何独自在山间经过的旅人都可能遭遇危险。",al={"斯坦恩布莱德安全吗","斯坦恩布莱德有敌对势力吗","斯坦恩布莱德的危险"}}},fp="10,234,17.469.0,20.355.0,41.225.0,28.198.0,50.179.0,40.215.0"}
P.entries["subzone:stratholme"] = {n="斯坦索姆",s="斯坦索姆曾是东威尔的明珠，也是洛丹伦王国第二大城市。在第三次战争期间，这里成为了阿尔萨斯·米奈希尔王子臭名昭著的“净化”行动的现场，起因是城中居民食用了受到亡灵瘟疫污染的谷物。如今，这座废弃的大都市仍在燃烧，成为了天灾军团在洛丹伦北部的主要据点。",h="斯坦索姆曾是东威尔的明珠，也是洛丹伦王国第二大城市。在第三次战争期间，这里成为了阿尔萨斯·米奈希尔王子臭名昭著的“净化”行动的现场，起因是城中居民食用了受到亡灵瘟疫污染的谷物。如今，这座废弃的大都市仍在燃烧，成为了天灾军...",kw={"安多哈尔","阿尔萨斯","净化","东威尔","玛尔加尼斯","瘟疫之地","天灾军团","白银之手","斯坦索姆","乌瑟尔"},ang={["class:Paladin"]="对于圣骑士而言，斯坦索姆是一片化为悲剧的神圣土地；这里是白银之手骑士团诞生的圣地，也是阿尔萨斯通过下令屠杀无辜平民而粉碎了同一兄弟会的地方。",["faction:Alliance"]="这座废墟之城是洛丹伦陨落的一座令人难忘的纪念碑，提醒着联盟的旅行者们，当北方王国在瘟疫和背叛中崩溃时，他们付出了多么惨痛的代价。"},sec={{t="圣骑士与贸易的摇篮",b="在陷落之前，斯坦索姆曾是北方文明的基石。它于几个世纪前从阿拉希人向东威尔的扩张中兴起，并繁荣发展成为洛丹伦第二大定居点，以其神圣的神殿和能够抵御黑暗魔法的神圣水源而闻名。在第二次战争之前，阿隆苏斯·法奥大主教在城内的礼拜堂聚集了众人，创立了白银之手骑士团，并册封了如光明使者乌瑟尔这样的传奇人物。在整个战争期间，斯坦索姆作为洛丹伦联盟的重要港口、补给中心和北部炼油基地，在经历旧部落的袭击后，又在胜利中重建。"},{t="净化与永恒的废墟",b="当诅咒神教将从安多哈尔运来的一批批受感染谷物送入城内市场时，斯坦索姆的命运就被注定了。毫无察觉的数千名居民食用了这些受污染的面粉。当阿尔萨斯王子与乌瑟尔和吉安娜·普罗德摩尔一同抵达时，他发现瘟疫已经扩散到无法治愈的地步。阿尔萨斯认为屠杀是阻止玛尔加尼斯获得一支军队的唯一途径，于是下令肃清城内所有居民——这一暴行导致乌瑟尔和吉安娜离他而去，也开启了王子堕落入疯狂的序幕。城市随后被付之一炬，此后，天灾军团进驻了这片烟雾弥漫的废墟，将其改造成了他们的区域首府。"}},faq={{q="为什么斯坦索姆还在燃烧？",a="当阿尔萨斯王子在第三次战争期间肃清该城时，他的军队点燃了房屋和街道，以消灭受感染的民众并阻止亡灵瘟疫的蔓延。受瘟疫污染的非自然大火至今仍未熄灭，在黑暗通灵能量和猖獗的天灾军团侵蚀下持续燃烧。",al={"为什么斯坦索姆在燃烧","斯坦索姆的火焰","斯坦索姆的烟雾"}},{q="什么是斯坦索姆的净化？",a="“净化”是指阿尔萨斯·米奈希尔王子对斯坦索姆民众的大规模屠杀。在全城居民食用了受到亡灵瘟疫污染的谷物后，阿尔萨斯选择处决每一位居民——无论病患还是健康者——以防他们成为天灾军团的士兵。这一决定使他失去了盟友，也摧毁了他的道德底线。",al={"斯坦索姆的净化","阿尔萨斯的肃清","斯坦索姆肃清"}},{q="斯坦索姆对白银之手骑士团有着怎样的历史意义？",a="斯坦索姆是白银之手骑士团的诞生地。在城内的阿隆苏斯礼拜堂，阿隆苏斯·法奥大主教在第二次战争前创立了圣骑士组织，并受封了最初的五位成员，其中包括光明使者乌瑟尔、图拉扬和赛丹·达索汉。",al={"白银之手起源","阿隆苏斯礼拜堂","白银之手骑士团斯坦索姆"}},{q="提里奥·弗丁在这里遭遇了什么？",a="在第二次战争结束多年后，提里奥·弗丁勋爵在斯坦索姆的司法大厅因捍卫崇高的兽人隐士伊崔格而受审。在乌瑟尔和联盟领袖的裁决下，提里奥被剥夺了爵位并遭到流放。后来，在萨尔领导的城市袭击中，他释放了伊崔格。",al={"提里奥·弗丁审判","提里奥斯坦索姆审判","伊崔格审判"}}},fp="10,264,28.579.0,28.524.0,32.252.0,35.299.0,59.220.0,38.309.0"}
P.entries["subzone:stratholme-classic"] = {n="Stratholme (Classic)",s="斯坦索姆曾是洛丹伦北部最引以为傲的明珠，也是白银之手骑士团的诞生地，如今却沦为了一片燃烧的废墟，成为了天灾军团的区域首府。这座被诅咒的城市在狂热的血色十字军与瑞文戴尔男爵的亡灵军团之间被一分为二，陷入了永无止境的残酷战争之中。",h="斯坦索姆曾是洛丹伦北部最引以为傲的明珠，也是白银之手骑士团的诞生地，如今却沦为了一片燃烧的废墟，成为了天灾军团的区域首府。这座被诅咒的城市在狂热的血色十字军与瑞文戴尔男爵的亡灵军团之间被一分为二，陷入了永无止境的残酷战争...",kw={"阿尔萨斯","达索汉","瘟疫之地","清洗","瑞文戴尔","白银之手","屠宰场","斯坦索姆"},ang={["class:Paladin"]="斯坦索姆的亵渎对圣骑士来说是沉痛的打击；它既是白银之手神圣的诞生地，也是阿尔萨斯粉碎乌瑟尔教诲的墓地。",["faction:Alliance"]="对于联盟来说，斯坦索姆代表了洛丹伦灾难性的陨落，提醒着士兵和幸存者们第三次战争所付出的惨重代价。"},sec={{t="被诅咒的都城",b="在第三次战争之前，斯坦索姆是洛丹伦北部的权力中心，也是白银之手骑士团神圣的诞生地。当阿尔萨斯王子因为被感染的谷物将瘟疫带入城内，而对城内百姓进行屠杀并清洗城市时，斯坦索姆的命运便已注定。如今，斯坦索姆在烟火和废墟中被天灾军团所占据。在巫妖克尔苏加德的最高权威和瑞文戴尔男爵的现场指挥下，这座城市成为了亡灵在瘟疫之地力量的主要基地。"},{t="分裂的战线",b="斯坦索姆被两个陷入永恒血战的残酷阵营一分为二。在西侧，狂热的血色十字军在大十字军战士赛丹·达索汉的指挥下，加固了十字军广场和血色区。东侧则是天灾军团的屠宰场和死灵之城，由高耸的通灵塔和死亡骑士瑞文戴尔男爵防守。任何进入城市的人都必须在这磨人的交叉火力中穿行，四周环绕着燃烧的住宅区和躁动的灵魂。"}},faq={{q="为什么斯坦索姆还在燃烧？",a="阿尔萨斯王子在第三次战争中那场臭名昭著的清洗行动中放火烧城，以阻止亡灵瘟疫的蔓延。由于黑暗魔法、死灵术以及天灾军团与血色十字军之间无休止的城市巷战，火势从未真正熄灭，始终在燃烧。",al={"为什么斯坦索姆在燃烧","是谁烧毁了斯坦索姆","斯坦索姆燃烧"}},{q="现在是谁在控制斯坦索姆？",a="控制权被瓜分了。大十字军战士达索汉指挥着一支幸存的血色十字军，固守在西侧的堡垒中，而死亡骑士瑞文戴尔男爵则在克尔苏加德的统领下，为天灾军团统治着东侧的废墟。",al={"谁统治着斯坦索姆","谁在负责斯坦索姆","斯坦索姆的领袖"}},{q="这座城市对于圣骑士有何历史意义？",a="斯坦索姆是白银之手骑士团的诞生地，阿隆索斯·法奥大主教曾在此第一次为光明使者乌瑟尔和最初的圣骑士们举行了圣礼。它的沦陷是该骑士团历史上最沉痛的悲剧。",al={"白银之手斯坦索姆","圣骑士历史斯坦索姆"}},{q="如何进入这座城市中天灾军团控制的那一侧？",a="虽然冒险者可以从正门一路杀进去，但东侧的天灾区也可以通过后门直接进入。进入这个后门需要巴纳扎尔（或相关掉落）或巴瑟拉斯镇长持有的钥匙，不过技术高超的潜行者、强大的锻造骷髅钥匙或地精炸药也可以强行打开它。",al={"后门钥匙","斯坦索姆后门","如何进入亡灵一侧"}}},fp="20,187,18.473.0,18.433.0,32.239.0,34.234.0,60.219.0,57.263.0"}
P.entries["subzone:stratholme-main-gate"] = {n="Stratholme Main Gate",s="斯坦索姆正门矗立在东瘟疫之地西北部，是这座洛丹伦北部大都市宏伟却燃着烈火的入口。它提供了通往这座城市废墟大道，进而直达国王广场和内部血色十字军防御工事的直接通路。",h="斯坦索姆正门矗立在东瘟疫之地西北部，是这座洛丹伦北部大都市宏伟却燃着烈火的入口。它提供了通往这座城市废墟大道，进而直达国王广场和内部血色十字军防御工事的直接通路。",kw={"阿尔萨斯","东瘟疫之地","前门","国王广场","正门","血色堡垒","亡灵天灾","斯坦索姆"},ang={["class:Paladin"]="站在这些大门前会让圣骑士感到无比悲痛；阿尔萨斯在清洗斯坦索姆当天解散白银之手骑士团时，这个组织就是在此分崩离析的。",["race:Human"]="这座主拱门曾是洛丹伦第二大首府的宏伟门槛，如今已沦为一座灰烬弥漫的死灵之城。"},sec={{t="通往陨落明珠的门户",b="斯坦索姆曾是洛丹伦北部的骄傲，以白银之手骑士团的诞生地而闻名。如今，其巨大的拱形正门标记着一场永无止境的梦魇的开端。正是在这里，阿尔萨斯王子在第三次战争期间背叛了他的导师光明使者乌瑟尔，并在亡灵天灾夺走他们之前清洗了自己的国民。自那以后，这座城市一直在熊熊燃烧，成为了该地区主要的亡灵天灾据点。"},{t="血色之路",b="穿过正门可以直接进入国王广场和市场区的废墟，径直前往被称为血色堡垒的防御区。血色十字军的狂热者们冲破了这个入口试图收复城市并净化亡灵，在废墟中开辟了一处营地。然而，十字军发现自己陷入了铺天盖地的亡灵怪物的包围之中，正在进行一场他们注定无法在这股操控着斯坦索姆防御的黑暗力量面前获胜的消耗战。"}},faq={{q="这道门通往哪里？",a="正门是进入斯坦索姆的宏伟前入口，直接通往国王广场和市场区。它是前往血色堡垒——也就是血色十字军所争夺的那个区域——的主要路径。",al={"斯坦索姆正门通向哪里","什么是斯坦索姆正门","斯坦索姆前门"}},{q="为什么这道门后的城市仍在燃烧？",a="在第三次战争期间，阿尔萨斯王子清洗了这座城市并将其付之一炬，以阻止亡灵瘟疫的蔓延。黑暗的死灵魔法、邪恶的火焰和肆虐的亡灵天灾腐蚀使这座废墟城市自那以后一直阴燃并不断燃烧，从未停歇。",al={"为什么斯坦索姆在燃烧","谁烧毁了斯坦索姆","斯坦索姆的火焰"}},{q="这道门和后门有什么区别？",a="两个入口都通向同一座广阔的废墟城市，但分别位于城市两端。正门进入后靠近城市中存活者和血色十字军占据的区域，而后门则直接通向东部的街道，那里完全处于亡灵天灾的屠宰场和瑞文戴尔男爵的统治之下。",al={"正门与后门区别","斯坦索姆哪个入口","斯坦索姆大门"}},{q="谁控制着正门内的区域？",a="拱门后的起始街道上徘徊着蹒跚的僵尸、食尸鬼、骷髅怪物和游荡的阴影，而血色十字军在更深处的大道上维持着一座处于激战中的堡垒。",al={"正门内有什么人","斯坦索姆前门有什么怪物"}}},fp="20,206,25.412.0,20.393.0,26.165.0,49.230.0,66.248.0,55.174.0"}
P.entries["subzone:stratholme-service-entrance"] = {n="Stratholme Service Entrance",s="Stratholme Service Entrance 是位于东瘟疫之地北部东墙大门的一座防御森严的后门。它提供了直接、隐蔽的通道，可进入这座燃烧的城市中被天灾军团控制的东部区域，从而绕过宏伟的前门。",h="Stratholme Service Entrance 是位于东瘟疫之地北部东墙大门的一座防御森严的后门。它提供了直接、隐蔽的通道，可进入这座燃烧的城市中被天灾军团控制的东部区域，从而绕过宏伟的前门。",kw={"后门","瑞文戴尔男爵","东瘟疫之地","东墙大门","长者广场","天灾军团","服务入口","斯坦索姆"},ang={["class:Paladin"]="对于圣光的骑士来说，这道门槛直通天灾军团亵渎的死灵装置，为肃清瑞文戴尔男爵并重拾这座圣城失落的荣誉提供了一条直接的途径。",["class:Rogue"]="这道服务之门是经典的战术渗透体现，让冒险者能够绕过防御严密的战线，悄悄溜进城市的维修通道。"},sec={{t="被攻破的堡垒",b="虽然宏伟的 Stratholme Main Gate 通向国王广场，并提供了一条通往血色堡垒的路线，但 Stratholme Service Entrance 却在东墙大门处突破了城市的东部防御。如今，它直接通往这座大都市腐化堕落的中心：长者广场，以及通往瑞文戴尔男爵屠宰场的荒芜小径。"},{t="天灾军团的堡垒",b="穿过这道服务传送门可以更近地接近天灾军团的东部地区。周围的小巷里爬满了石像鬼、地穴恶魔和守卫着恐怖通灵塔的邪教徒。对于银色黎明和那些寻求直接打击统治此地的死亡骑士的勇敢冒险者来说，这道隐蔽的铁门是针对巫妖王麾下指挥官进行外科手术式打击的主要集结地。"}},faq={{q="斯坦索姆仆从入口 位于何处？",a="该入口位于东瘟疫之地北部山脉沿线的东墙大门处，就在斯坦索姆主要废墟的东侧。它隐藏在防御墙沿线的一座石拱门中。",al={"服务入口位置","后门在哪里","斯坦索姆侧门地图","如何找到斯坦索姆后门"}},{q="这个入口与 斯坦索姆正门 有什么不同？",a="正门 通向国王广场，并提供了一条横穿城市前往血色堡垒的路线。而 后门 开在长者广场附近，能更近地接近亡灵控制的东部地区和屠宰广场。",al={"后门与前门的区别","服务入口的区别","斯坦索姆哪个入口"}},{q="为什么它被称为“服务入口”？",a="它是位于东墙大门的一处后门，可以绕过城市的前方入口。它最初的市政用途并未明确。",al={"为什么叫服务入口","服务之门背景故事"}},{q="城市的这一部分由谁控制？",a="门后的区域由天灾军团牢牢控制，由瑞文戴尔男爵和他的侍僧们监管，他们维护着在长者广场锚定其黑暗魔法的通灵塔。",al={"谁控制了后门","服务入口首领","亡灵区首领"}}},fp="27,162,18.255.0,19.267.0,49.182.0,60.206.0,38.54.0,35.173.0"}
P.entries["subzone:stromgarde-keep"] = {n="激流堡",s="激流堡是位于阿拉希高地、已覆灭的人类王国斯托姆加德那饱经战火且四分五裂的首都。这座要塞曾是人类文明引以为傲的摇篮，名为“激流城”，如今却被敌对的辛迪加盗贼、入侵的巨石食人魔，以及加林·托尔贝恩王子麾下拼死抵抗的皇家守军瓜分殆尽。",h="激流堡是位于阿拉希高地、已覆灭的人类王国斯托姆加德那饱经战火且四分五裂的首都。这座要塞曾是人类文明引以为傲的摇篮，名为“激流城”，如今却被敌对的辛迪加盗贼、入侵的巨石食人魔，以及加林·托尔贝恩王子麾下拼死抵抗的皇家守军瓜...",kw={"阿拉希","阿拉索","巨石氏族","加林","激流城","斯托姆加德","激流堡","辛迪加","索拉丁","托尔贝恩"},ang={["faction:Alliance"]="斯托姆加德是第二次战争期间洛丹伦联盟的创始成员。其陷入困境的守军代表了北方仅存的忠诚堡垒之一，正在进行殊死抵抗，以避免彻底覆灭。",["race:Human"]="斯托姆加德是你整个种族的古老心脏，最初的人类部落在索拉丁的领导下在此团结起来，并从高等精灵那里学习了奥术。看到它被罪犯和食人魔蹂躏，实在令人痛心。"},sec={{t="人类的摇篮",b="在拥有现在的名字之前，这座要塞在近三千年前就被建立，名为激流城，是索拉丁国王统治下的阿拉索统一帝国的第一座首都。它是人类对抗森林巨魔取得胜利的集结地，也是人类法术的诞生地，高等精灵法师曾在此教导了最初的一百位人类施法者。几个世纪以来，随着达拉然、洛丹伦和暴风城等年轻的姐妹王国崛起并繁荣起来，激流城的影响力逐渐衰退。留守此地的顽强的托尔贝恩王朝将其更名为斯托姆加德，在第二次战争期间，它始终是一座引以为傲的战士堡垒，是洛丹伦联盟抵御兽人部落的坚固支柱。"},{t="破碎的堡垒",b="在第三次战争的浩劫之后，斯托姆加德最终在日益严重的灾难和背叛中土崩瓦解。如今，这座宏伟的石砌城市被分割为三个交战区域。辛迪加的贵族叛徒占据了宏伟的内堡，而粗野的巨石食人魔则占领了法师区的前圣所。加林·托尔贝恩王子和饱经战火的斯托姆加德军队被困在剩下的城区中，在多条战线上进行着艰苦而血腥的战争，只为不让他们的祖居之地湮没在记忆中。"}},faq={{q="谁现在控制着激流堡？",a="这座废墟之城被划分为三个激烈争夺的区域。奸诈的辛迪加控制着中央内堡，入侵的巨石氏族食人魔占据了荒废的法师区，而加林·托尔贝恩王子则在剩下的城区带领着斯托姆加德军队的残部。",al={"激流堡的居民","激流堡的控制者","激流堡内的人员"}},{q="什么是阿拉索帝国？",a="阿拉索帝国是第一个统一的人类国家，由索拉丁国王在近三千年前建立。它的首都是激流城，坐落在今天激流堡所在的位置上。",al={"什么是激流城","第一个人类王国","阿拉索帝国"}},{q="为什么这座城市会变成废墟？",a="斯托姆加德在第二次战争期间曾是中坚力量，但在第三次战争混乱的余波中，该王国变得脆弱且孤立无援。内部背叛、犯罪组织辛迪加的投机攻击以及巨石食人魔的突袭，共同摧毁了这座城市的防御。",al={"斯托姆加德为何毁灭","斯托姆加德的遭遇"}},{q="加林·托尔贝恩是谁？",a="加林·托尔贝恩王子是斯托姆加德残存军队的皇室后裔和指挥官。他在堡垒内受到围攻的据点里，指挥着针对辛迪加和食人魔的绝望防御战。",al={"托尔贝恩王子","加林王子是谁"}}},fp="15,188,18.610.0,19.499.0,39.230.0,31.178.0,25.205.0,23.203.0"}
P.entries["subzone:sun-rock-retreat"] = {n="烈日石居",s="烈日石居是隐藏在石爪山脉中部高山之中的一座部落避难所，位于暗色湖以南。这里主要由牛头人和兽人力量驻守，是部落在该地区的主要集结地和补给站。除了战略用途之外，这处定居点还坐落在一片被牛头人长期尊崇的圣地上，因其深厚的精神共鸣而备受推崇。",h="烈日石居是隐藏在石爪山脉中部高山之中的一座部落避难所，位于暗色湖以南。这里主要由牛头人和兽人力量驻守，是部落在该地区的主要集结地和补给站。除了战略用途之外，这处定居点还坐落在一片被牛头人长期尊崇的圣地上，因其深厚的精神共...",kw={"安舍","暗色湖","石爪山脉","烈日石居","牛头人","荆棘谷地精"},ang={["faction:Horde"]="作为部落在石爪山脉的主要集结枢纽，烈日石居在这片饱受争夺的山峰中提供了一个重要的补给站和飞行枢纽。",["race:Tauren"]="对舒哈鲁而言，烈日石居不仅仅是一座前哨站；它是受到安舍祝福的神圣土地，数百年来萨满们一直在此漫步于灵界之中。"},sec={{t="高山之中的神圣避难所",b="烈日石居隐匿在暗色湖以南的山谷中，长期以来对牛头人而言具有重要的精神意义。根据古老的传说，太阳安舍曾亲吻过村庄所在的这座山峰。在部落到来之前的几代人里，牛头人萨满和朝圣者们都会来到这里举行仪式，沟通凡世与彼岸，从这片土地与灵界的紧密联系中汲取力量。"},{t="边境前哨",b="如今，烈日石居是部落在石爪山脉的主要行动基地。兽人和牛头人并肩作战，建立起稳固的立足点，以抵御敌对的鹰身人族群、当地的暗夜精灵哨兵以及荆棘谷地精的工业掠夺。作为连接雷霆崖、十字路口以及灰谷边界的贸易和飞行航线的枢纽，烈日石居为那些勇闯险峰的人们提供了庇护、补给和精神指引。"}},faq={{q="什么是烈日石居？",a="烈日石居是部落在石爪山脉的主要前哨站。这里主要居住着牛头人和兽人，是部落英雄在该地区开展工作的和平避难所、贸易站和指挥部。",al={"烈日石居是什么","烈日石居信息","谁在管理烈日石居"}},{q="为什么这个地方对牛头人来说是神圣的？",a="牛头人的传说认为，太阳安舍曾触碰过如今烈日石居所在的山峰。这片土地与灵界有着持久的联系，使其成为进行幻象试炼和与祖先沟通的古老朝圣地。",al={"为什么烈日石居是圣地","安舍 石爪山脉","牛头人烈日石居背景故事"}},{q="烈日石居面临着哪些威胁？",a="烈日石居需要应对好战且具有领地意识的鹰身人、守护神圣森林的敌对暗夜精灵，以及正在破坏自然景观的荆棘谷地精的破坏性采矿和伐木活动。",al={"烈日石居的威胁","谁在攻击烈日石居","石爪山脉的敌人"}},{q="当地的飞行管理员通向哪里？",a="烈日石居提供双足飞龙服务，可将旅客直接送往卡利姆多中部的多个主要地点，包括贫瘠之地的十字路口和牛头人的主城雷霆崖。",al={"烈日石居飞行路线","飞往烈日石居","烈日石居飞行管理员"}}},fp="16,207,27.357.0,16.431.0,25.205.0,39.200.0,35.171.0,43.166.0"}
P.entries["subzone:sundown-marsh"] = {n="日落沼泽",s="日落沼泽标志着湿地最深、最西端的区域，那里死水汇集，野兽横行。尽管有迅猛龙、软泥怪和豺狼人在此徘徊，但一对古怪的搭档仍在这片泥泞边缘的一处孤立宅邸中安了家。",h="日落沼泽标志着湿地最深、最西端的区域，那里死水汇集，野兽横行。尽管有迅猛龙、软泥怪和豺狼人在此徘徊，但一对古怪的搭档仍在这片泥泞边缘的一处孤立宅邸中安了家。",kw={"鳄鱼","弗拉德·迅齿","苔黑","软泥怪","日落沼泽","温娜·丝须","湿地"},ang={["race:Gnome"]="看到弗拉德·迅齿和温娜·丝须能够在危险的泥泞中经营他们的风车前哨站，这证明了侏儒的巧思可以在任何地方开辟出一片舒适的家园。"},sec={{t="狂野而昏暗的低地",b="日落沼泽位于湿地的西北角，以深水、厚重的淤泥和密集的掠食者种群而闻名。巨型鳄鱼、流动的软泥怪、游荡的迅猛龙以及领地意识极强的苔黑豺狼人在迷雾中自由穿行。危险的地形使得大多数过往旅客只能严格沿着连接米奈希尔港和铁炉堡的铺石主路行进，从而使得这片深处的角落基本处于未被开发的野蛮状态。"},{t="泥沼边缘的生活",b="在沼泽的重重危机之中，矗立着一座孤独的石屋，屋顶上有着一台不停转动的风车。在那里，侏儒弗拉德·迅齿和矮人温娜·丝须以在沼泽中拾荒为生，这对组合看起来十分不协调。他们将从泥沼中寻获的奇珍异宝和稀有配方兜售给那些勇敢到足以穿越这片充满敌意生物的沼泽的旅行者。"}},faq={{q="日落沼泽位于何处？",a="日落沼泽位于湿地的西北部。它代表了沼泽地势最低、最深的部分之一，偏离了主要皇家道路。",al={"日落沼泽位置","日落沼泽在哪里","湿地沼泽位置"}},{q="谁住在日落沼泽？",a="一对古怪的搭档，侏儒弗拉德·迅齿和矮人温娜·丝须住在这里，他们的住所是一座带有风车的小型石屋。他们在泥沼中搜寻奇珍，并向路过的旅行者出售稀有商品。",al={"谁住在这里","日落沼泽非玩家角色","迅齿小屋"}},{q="日落沼泽里有什么威胁？",a="这片沼泽中充满了危险的野生生物和怪物，包括巨型鳄鱼、污浊的软泥怪、沼泽兽、迅猛龙以及敌对的苔黑豺狼人，这些生物让普通的探险望而却步。",al={"日落沼泽的怪物","日落沼泽的危险","日落沼泽的敌人"}},{q="冒险者为什么要进入日落沼泽？",a="除了应对当地的野兽，旅行者们还会前往那座风车小屋，与弗拉德·迅齿和温娜·丝须进行贸易。他们提供在周围沼泽中发现的罕见配方和奇异珍品。",al={"为什么要访问日落沼泽","前往日落沼泽的理由","日落沼泽商人"}}},fp="13,151,25.317.0,28.311.0,31.113.0,27.200.0,43.143.0,50.174.0"}
